pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, but with a smooth non-linear (quartic-ish) decay
    // so that small post-residuals are strongly preferred (tight packing).
    let mut score = pr * pr / cap * (1.0 + pr / cap) - 2.0 * pr;

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly (fewer chances to fill it).
    let progress_coupling = 1.0 + progress * (pr / cap) * (1.0 - progress);
    score += progress_coupling * (pr / cap).powi(3) * cap * 0.5;

    // Reward bins whose post-residual smoothly matches the next item size
    // (polynomial interaction instead of hard thresholds).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        let match_term = (diff * diff) / cap; // 0 when next item fits perfectly
        score -= (1.0 - progress) * match_term * 0.8;
        // penalize when next item cannot fit at all (post_residual < next)
        let cannot_fit = ((nxt - pr).max(0.0) / cap).powi(2) * cap;
        score += 1.5 * cannot_fit;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin, scaled smoothly by how well it fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (pr / cap);
        score -= 8.0 * tightness;
    }

    // Slight preference for bins with below-mean residual (consolidate fuller bins),
    // smoothly interpolated.
    score += 0.3 * ((mean_residual - bin_residual as f64) / cap).max(-1.0).min(1.0);

    // New-bin candidate: give it a moderate baseline so it's chosen only when
    // open bins have genuinely poor fits (high post-residual or mismatch).
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 300.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Open-bins pressure: when many bins are open, prefer reusing existing bins;
    // when few are open, opening a new bin is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize leaving a gap that blocks it.
        score += 30.0;
    }

    // Prefer bins below mean residual (denser bins) mildly.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate: make it attractive only when current bin would leave big waste.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual * 0.5 && open_bins_count > 0 {
            score -= 80.0;
        } else {
            score += 500.0; // discourage opening new bins unnecessarily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual that is too small to hold the next item
    // (or the minimum item) is wasted capacity.
    let min_item = if next_item_size > 0 { next_item_size.min(100) } else { 10 };
    if post_residual > 0 && post_residual < min_item {
        score += (min_item - post_residual) as f64 * 2.5;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == min_item {
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 20.0 * fill_ratio;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are low
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * 1.5;

    // Prefer bins with residual close to item size (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 45.0 + 40.0 * big_item + 25.0 * poor_fits - 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild progression scaling: tighten packing as stream advances
    score *= 1.0 + 0.15 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap below the minimum item size (1..100 unknown, use conservative 10)
    // is pure waste; scale penalty nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits: post_residual small relative to bin capacity.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral base, slightly favored early in stream,
    // penalized later so we consolidate into existing bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * 0.5 + 20.0 * progress;

        // If next item is large and this item leaves a bad gap, opening a new
        // bin is attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
        // If only one bin fits and it's a decent fit, disfavor new bin.
        if fitting_bins_count >= 1 && post_residual <= 15 {
            score += 35.0;
        }
    }

    // Lookahead: prefer leaving gaps that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // (keep uniform residuals for future flexibility).
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10
    let post = post_residual as i64;
    let cap = bin_capacity as i64;
    let r = post % 10;

    // Perfect fits are golden
    if post == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual that no typical item (1..=100) can pair with
    if post > 0 && post < 10 {
        score += 60.0; // tiny sliver = dead space
    }

    // Harmonic reward: residual in "usable" classes (multiples of 5 or 10)
    if r == 0 {
        score -= 25.0; // residual divisible by 10 -> easy to fill
    } else if r == 5 {
        score -= 15.0; // divisible by 5 -> decent
    }

    // Lookahead coupling: does next_item_size divide or fit the post residual?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n == post {
            score -= 200.0; // perfect follow-up fit
        } else if n <= post {
            // harmonic class match: next item keeps residual in a good class
            let nr = (post - n) % 10;
            if nr == 0 {
                score -= 40.0;
            } else if nr == 5 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's residual: mild penalty scaled by gap
            score += ((n - post) as f64) * 0.3;
        }
        // residue pairing: post + next == capacity-like harmony
        if post + n == cap {
            score -= 120.0;
        }
    }

    // Integer division threshold on post_residual: coarse fill tiers
    let q = post / 25; // 0..4 quarters
    score -= q as f64 * 5.0; // prefer bins whose leftover is a large chunk (still reusable)

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else {
        // spread load when many bins fit: prefer tighter bins (base post_residual already does)
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost,
    // unless current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin when open bins are fairly full; penalize opening early
        score += 30.0 + pressure * 40.0 - (open_bins_count as f64) * 2.0;
        // late in stream, reusing is cheaper
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += t * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: penalize placements when many bins are already open,
    // encouraging consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Coupling with mean residual: prefer bins whose residual is below average
    // (i.e., nearly full bins get filled first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0 - gap * 1.5;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use.
        score += 12.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item is
    // large or no existing bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 70.0 - tightness * 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: low post_residual is good (already the base).
    // Penalize post_residual that is small but unusable (dead space).
    if post_residual > 0 {
        let dead_threshold = 9.0; // smallest item is 1; anything tiny is near-dead
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // 2-step lookahead: reward if next_item_size fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent — the residual is reusable immediately.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 20.0 * tightness;
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce-space bins;
    // filling them is good if the fit is tight, bad if it creates dead space.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            // Below-mean residual: scarcer space, favor using it when tight.
            score -= 8.0 * (1.0 - rel);
        } else {
            // Above-mean residual (roomy bin): mild penalty to prefer tighter bins.
            score += 3.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= bin_capacity / 4 {
            score -= 30.0; // good fit in the only option: strong reward
        } else {
            score -= 5.0; // weak encouragement anyway
        }
    }

    // New-bin candidate handling: make a fresh bin moderately attractive only when
    // the current fit is bad (large post_residual) or lookahead fails.
    if bin_residual == bin_capacity {
        // Base score for a new bin is bin_capacity (large = unattractive),
        // but discount it so it can win over truly poor fits.
        score = score * 0.55 - 10.0;
        // If lookahead item is large, a fresh bin is a safe bet.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: penalize small unusable gaps (1..=15) heavily.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 + (15 - post_residual) as f64 / 15.0);
    } else if post_residual > 15 && post_residual < 30 {
        score += 10.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when item is large or residuals are large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64 / bin_capacity as f64).powf(2.0);
        score = score * 0.4 + 30.0 + 40.0 * (1.0 - tightness) - 20.0 * progress;
    }

    // Lookahead: penalize if next item cannot use the post residual.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 6.0;
    }

    // Slight preference for bins tighter than the average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Reward leaving gaps that still fit plausible small items.
        score -= (post_residual as f64 / 10.0).floor() * 2.0;
    }

    // Last-chance pressure: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates dead space for the known next item
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmenting).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // New-bin candidate: prefer it only when it avoids a very poor fit.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: decent residual (100 - item) minus a fixed
        // opening cost so we only open when existing bins score worse.
        score = (bin_capacity - item_size) as f64 + 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual divided into
    // capacity-fraction classes (0, small, medium, large leftovers).
    let post_f = post_residual as f64;
    let class = (post_f / cap * 8.0).floor() as i32; // 0..=7 classes

    // Dead-space penalty: leftovers that no future item (1..=100) can ever
    // pair with are the worst. Class 1 (residual <= 12.5) is nearly dead.
    if post_residual > 0 && post_residual < 13 {
        score += 60.0;
    }
    // Class 2: 13..25 — only very small items fit; mild penalty.
    if post_residual >= 13 && post_residual < 26 {
        score += 18.0;
    }

    // Perfect fit bonus via modulo arithmetic on capacity fractions.
    // post_residual == 0 is a perfect closure: reward heavily.
    if post_residual == 0 {
        score -= 120.0;
    }
    // Harmonic complements: residual is an exact fraction of capacity
    // (25, 50, 75) -> these are reusable "harmonic" classes.
    if post_residual == 25 || post_residual == 50 || post_residual == 75 {
        score -= 25.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward, scaled by tightness
            let tight = 1.0 - (post_f - next_item_size as f64) / cap;
            score -= 40.0 + 30.0 * tight;
        } else {
            // next item will NOT fit here: this bin becomes dead space
            // for the known future -> penalize proportionally to waste.
            score += 12.0 + 0.3 * post_f;
        }
    }

    // Last-chance logic: if this is the only fitting bin, using it avoids
    // opening a new bin; reward unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
        if post_f < 0.10 * cap && post_residual > 0 {
            score += 30.0; // but terrible fit cancels the reward
        }
    }

    // New-bin candidate (empty bin): only attractive when open bins are
    // congested (low mean residual) or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        }
        if mean_residual < 15.0 {
            score -= 55.0; // existing bins nearly full -> open fresh one
        }
        // Harmonic: opening a bin when the item is large leaves a
        // "complementary" residual that pairs with small items well.
        if item_size >= 50 && item_size <= 90 {
            score -= 10.0;
        }
    }

    // Stream progression: early on, prefer consolidation (keep few bins);
    // late in the stream, closing bins perfectly matters more.
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress * (1.0 - post_f / cap);

    // Prefer bins whose residual deviates favorably from the mean
    // (use the tightest bins first to preserve large residuals).
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum item (1)
    // are worthless; residuals below a "useful" threshold become dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 15.0; // marginal gap
    }

    // Reward using a nearly-full bin so it closes out.
    if post_residual as f64 <= mean_residual * 0.5 {
        score -= 8.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // leaves a gap the next item cannot use
    }

    // New-bin candidate: only attractive when existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit || (fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.5) {
            score -= 30.0;
        } else {
            score += 50.0; // prefer reusing open bins when fits are decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * fill;
        } else {
            // next item does NOT fit in the leftover: penalize dead space
            score += 50.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small unusable gaps (< 10% of capacity)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to open new bins for large items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize mildly unless item is large or stream is early
        score += 120.0 - 30.0 * (item_size as f64 / bin_capacity as f64) - 100.0 * (1.0 - progress);
    }

    // Slight preference for filling larger-residual bins when many bins open
    score -= 0.1 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it only
    // when existing bins are crowded and the fit is poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so open bins with decent fits win.
        score += 40.0;
        // More attractive late in the stream or when few bins remain open.
        score -= 20.0 * progress;
        score -= 2.0 * open_bins_count as f64;
        // If mean residual is small (bins nearly full), a new bin is reasonable.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 25.0;
    }

    // Mild pressure toward consolidating into bins below mean residual (balance).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Time-horizon modulation: early on, be greedy about tight fits; later, be
    // more conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 8.0 * fit_ratio;
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it cannot fit even the smallest plausible item (<= 20),
    // and grows worse the smaller the gap is.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0;
    }

    // Perfect fit bonus: strong reward for zero waste.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Near-perfect fit: reward tiny residuals only if next item could use them.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0; // residual is reusable by lookahead item
    } else if post_residual > 0 && next_item_size > 0 {
        score += 15.0; // residual cannot host next item: mild dead-space penalty
    }

    // Open bins pressure: discourage spreading across many bins when
    // this placement leaves a large residual (fragmentation risk).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (1.0 - progress);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a forced new bin for a poor fit later.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., consuming a large chunk of a fuller bin) is efficient.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit in an open bin,
        // so new bins are opened only when open bins score badly.
        score += 40.0;
        // Late in the stream, be more conservative about opening bins.
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted space is quadratic-ish).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space if it cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 4.0; // next item may chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual below mean (fill the emptier-tail bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize unless current bin would leave unusable scrap.
    if bin_residual == bin_capacity {
        let scrap_penalty = if next_item_size > 0 && post_residual < next_item_size {
            0.0
        } else {
            20.0
        };
        score += 35.0 - scrap_penalty - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1..10) are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Residuals too small for the lookahead item (but >=10) are also likely dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 30 {
        score += 15.0;
    }

    // Reward near-perfect fits (small usable leftover).
    if post_residual <= 10 {
        score -= 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize adding to bins when many are already open,
    // pushing toward consolidation into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer filling bins with small residuals relative to the mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Tightness ratio: favor bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // New-bin candidate: default neutral-ish score; open a fresh bin only when
    // existing bins would create dead space or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0;
        // If the item is large, a fresh bin is attractive (it will fill well).
        if item_size >= 60 {
            score -= 20.0;
        }
        // If no open bin is a last chance, opening is less costly.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // Lookahead: if next item is large, a fresh bin can host both.
        if next_item_size >= 40 && item_size + next_item_size as u32 <= bin_capacity {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += (post_residual as f64) * (post_residual as f64) * 0.02;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to leftover
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * ratio;
        } else {
