        }
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual,
    // this bin chains perfectly — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // If next item fits into post-residual, mild reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack * 0.5;
    }

    // Penalize dead space that the next item cannot use (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let dead = post_residual as f64;
        score += dead * 1.5;
        // Extra penalty for small unusable gaps (classic bad residual).
        if dead < 10.0 {
            score += 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual space
    // elsewhere is badly fragmented. Scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual - post_residual as f64;
        // Prefer existing bins when mean residual is reasonably large.
        if mean_residual >= item_size as f64 {
            score += 300.0;
        } else {
            score -= 100.0 + fragmentation * 0.5 + progress * 50.0;
        }
    }

    // Mild preference for tighter (smaller-residual) bins relative to the mean.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr - 8.0 * prn * (1.0 - prn);

    // Non-linear coupling of post-residual with stream progress:
    // early on, keep bins flexible (penalize very small residuals more);
    // late in stream, squeeze tightly (reward small residuals more).
    let coupling = 0.5 + progress * progress;
    score += coupling * prn * prn * 30.0;

    // Penalize dead space relative to next item: if next item could use the residual, reward leaving room
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / (nxt * 2.0)).max(0.0);
        } else {
            score += 4.0 * (nxt - pr) / cap * 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open and residual is wasteful
    score += 0.02 * open_bins_count as f64 * prn;

    // Mild drift toward mean residual to keep bin balance smooth
    score += 0.1 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much more than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: nothing (min size 1) can ever use it
    } else if post_residual < 20 {
        score += 8.0; // very hard to fill
    } else if post_residual < 30 {
        score += 3.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still accommodate typical future items.
    if post_residual >= 50 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + slack * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // this bin would become dead space before the next item arrives
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item is large relative
    // to what open bins would leave behind, or no decent fit exists.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin, offset by its huge flexibility
        score = (bin_capacity - item_size) as f64 + 15.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // forced open anyway
        }
    } else {
        // Slight preference for bins whose residual is close to mean (avoid fragmenting outliers)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
