        } else if post_residual > next_item_size {
            // next item fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // next item won't fit: penalize wasted chain potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty so open bins usually win
        score += 250.0;
        // but if the item is large and current open bins are fragmented, allow new bin
        if item_size as f64 > mean_residual + 20.0 {
            score -= 400.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 150.0;
        }
    }

    // Mild preference to keep number of open bins moderate
    score += open_bins_count as f64 * 0.1;

    // Slight time decay: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits: small post_residual is good, especially near zero.
    if post_residual > 0 {
        score -= 25.0 / post_residual as f64;
    } else {
        // Perfect fill: huge reward.
        score -= 120.0;
    }

    // Reward using bins that are the last chance to fit this item (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Post residual too small for next item: penalize dead space relative to next need.
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Penalize creating residuals that are unusably small for typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    score -= 2.0 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is much emptier than average, favor filling it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: penalize opening a new bin, but relax the penalty
    // late in the stream or when item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 55.0;
        // Large items leave little residual anyway; slightly cheaper to open a bin for them.
        new_bin_penalty -= 30.0 * item_frac;
        // Late in stream, closing out with new bins is less costly.
        new_bin_penalty *= (1.0 - 0.4 * progress);
        // If no other bin fits, this penalty is effectively moot (only candidate),
        // but if others fit, discourage wasteful opening.
        if fitting_bins_count > 1 {
            new_bin_penalty += 20.0;
        }
        score += new_bin_penalty;
    }

    // Mild time-horizon term: early on, be slightly conservative with tight fits.
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        // Dead space penalty: smaller unusable gap => heavier penalty.
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonable fit exists; encourage using existing bins.
    if bin_residual != bin_capacity {
        score -= 3.0;
        score += open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: penalize opening a bin unless the fit is bad
        // or the stream is early and consolidation is cheap.
        score += 15.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
        // If no open bin fits well (large dead space elsewhere), opening
        // a new bin becomes attractive: offset the penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement; if post_residual is just barely too small
    // for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the
    // mean (more filled bins), keeping well-filled bins busy.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = (pr - nxt).abs();
            // exact match next step is ideal
            score -= 300.0 * (1.0 - gap / 100.0).max(0.0);
            if gap == 0.0 {
                score -= 250.0;
            }
        } else {
            // next item cannot fit here: penalize proportional to wasted lookahead potential
            score += 0.8 * (nxt - pr);
        }
    } else {
        // last item: minimize post residual aggressively
        score += 2.0 * post_residual as f64;
    }

    // Compare post_residual relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin unless item is large and residuals elsewhere are small
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let urgency = (item_size as f64 / 100.0) * (1.0 - progress);
        score += 150.0 - 120.0 * urgency;
        if next_item_size > 0 && post_residual >= next_item_size as f64 {
            score -= 80.0; // fresh bin can host next item too
        }
    }

    // Tight fit preference: smaller waste relative to capacity
    score += 0.3 * (pr / bin_capacity as f64) * 100.0;

    // Prefer bins with high utilization so far
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward (lower score) when the next item exactly fills the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Reward if next item can still fit in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Penalize dead space too small for the next item (or anything meaningful).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, allow opening new bins more readily (keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus a discount early on.
        score = bin_capacity as f64 * 0.5 - 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in stream, be more selective; later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward perfect/near-perfect fits: small post_residual is good.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space: residual smaller than min item size.
        if post_residual < 10 {
            score += 50.0 * (10.0 - post_residual as f64);
        }
        // Tightness reward: quadratic bonus for small residuals.
        let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        score -= 30.0 * tight * tight;
    }

    // 2-step lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chain
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward proportional to how snugly next item fits.
            score -= 200.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 20.0 * (over / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win; reduced late in stream
        // or when many bins are open (consolidation pressure).
        let mut new_bin_penalty = 120.0;
        new_bin_penalty *= 1.0 - 0.5 * progress;
        if open_bins_count > 3 {
            new_bin_penalty -= 10.0 * (open_bins_count.min(10) as f64 - 3.0);
        }
        // If next item is large, a fresh bin may be attractive.
        if next_item_size > 60 {
            new_bin_penalty -= 40.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Prefer bins with below-average residual (more room to fill later),
        // i.e., penalize bins whose residual is already small relative to mean
        // only mildly; favor using fuller bins to consolidate.
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    // Mild global pressure: when many bins are open, pack tighter.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space in (0,10) is nearly unusable
    // for items in [1,100]; residual classes by integer division thresholds.
    let dead = post_residual < 10;
    if dead {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Modulo-class coupling: a residual that is an exact multiple of common
    // item sizes (10,20,25,50) is more reusable -> reward.
    let r = post_residual;
    if r == 0 {
        score -= 40.0; // perfect fill
    } else if r % 50 == 0 || r % 25 == 0 || r % 10 == 0 {
        score -= 15.0;
    } else if r % 20 == 0 {
        score -= 12.0;
    }

    // Lookahead harmony: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size <= r {
            score -= (r - next_item_size) as f64 * 0.15;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 90 {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.1;
        if post_residual >= 90 {
            score -= 30.0;
        }
    }

    // Progress: later in the stream, prefer tighter packing (waste less).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Prefer bins already below mean residual (concentrate usage).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Harmonic class logic: post_residual modulo 10 — small remainder classes
    // represent "dead space" fragments that are hard to fill later.
    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Perfect closure class: post_residual is an exact multiple of 10
    // (clean harmonic slot for typical small items).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling with next item (k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post == nxt {
            // Perfect wrap-around: bin closes exactly with next item.
            score -= 25.0;
        } else if post < nxt {
            // Next item won't fit here: penalize proportionally to the gap.
            score += (nxt - post) * 1.5;
        } else {
            // Next item fits: reward, more so if the leftover stays in a good class.
            score -= 8.0;
            if ((post - nxt) as u32) % 10 == 0 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Reward larger items entering this bin (tighter packing per placement).
    score -= (1.0 - item / cap) * 5.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default mild penalty so we prefer existing bins with decent fits...
        score += 6.0;
        // ...but if open bins are nearly exhausted (low mean residual),
        // opening a fresh bin is attractive.
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 12.0;
        }
        // Also open a new bin early in the stream when few bins exist.
        if open_bins_count == 0 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: mildly amplify differences so tight fits win.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

