    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bins are poorly filled
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Slight progression term: later in stream, prefer tight packing more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

