            // Next item fits here: strong reward proportional to how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 + 20.0 * snug;
        } else {
            // Next item will NOT fit here: penalize leaving a residue just below the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 15.0; // tantalizing near-miss residue — worst dead space
            } else {
                score += 5.0;
            }
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Fill-rate reward: bins closer to full are better targets ---
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // --- New-bin candidate handling: opening a new bin is only acceptable when ---
    // the item is large (would leave little residue anyway) or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Large items justify a fresh bin (item >= 50 consumes half a bin cleanly).
        if item_size >= 50 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins: discourage spreading further.
        score += open_bins_count as f64 * 1.5;
        // If other bins fit and their mean residual is tight, avoid a new bin.
        if fitting_bins_count > 0 && mean_residual < item_size as f64 + 15.0 {
            score += 25.0;
        }
    }

    // --- Mild tie-break: prefer bins whose residual is close to the item (snug fit) ---
    let slack = (bin_residual - item_size) as f64;
    score += 0.15 * (slack - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable item are pure waste; penalize them quadratically.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 500.0;
    } else if post_residual <= 10 {
        // Tight fits are excellent: reward strongly.
        score -= 60.0 * (11.0 - post_residual as f64);
    } else if post_residual <= 25 {
        // Moderately small gap: mild penalty proportional to dead space.
        score += 0.5 * (post_residual as f64 - 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins would leave
    // large dead space or no bin fits well. Penalize opening new bins
    // mildly by default, scaled by open bin pressure.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If lookahead item could use the fresh bin's full space, soften.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.15 * next_item_size as f64;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // bins with smaller residual (tighter packing).
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead synergy: reward leaving a gap that exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly discouraging extreme outliers late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty for dead space: small residuals are heavily discounted.
        let pr = post_residual as f64;
        score -= 60.0 * (-pr / 25.0).exp();
        // Threshold bonus: residual small enough to be plausibly fillable later.
        if pr <= 20.0 {
            score -= 40.0 * (1.0 - pr / 20.0);
        }
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64 - ni).abs() < 0.5 {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: mild reward, scaled by
            // how well it matches relative to mean residual.
            let slack = post_residual as f64 - ni;
            score -= 25.0 * (-slack / 15.0).exp();
        } else {
            // Next item won't fit here; penalize if we leave a large awkward gap.
            let gap = ni - post_residual as f64;
            if gap > 0.0 && gap < 30.0 {
                score += 15.0 * (1.0 - gap / 30.0);
            }
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // prefer filling tighter bins to consolidate space.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or no good fits exist. Penalize the
    // fresh-bin call moderately so it loses to good fits but wins over bad ones.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the item is huge and would leave a tiny residual anywhere,
        // a fresh bin is fine — soften the penalty.
        if item_size >= 70 {
            score -= 100.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Mild consolidation pressure: with many open bins, prefer existing bins.
    score -= 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Smallest item is 1, so residual 0 is perfect; residual < 4 is nearly dead.
    if post_residual > 0 && post_residual < 4 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; slight penalty for creating a stranded state.
        score += 2.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (keep big holes for big items).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Time horizon: early in the stream, be conservative (favor spreading);
    // late in the stream, pack aggressively to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage opening yet another one.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (6.0 + 0.4 * open_bins_count as f64);

    // But if no open bin fits well (large post_residual waste anyway), new bin is fine.
    if new_bin > 0.0 && post_residual as f64 > 0.7 * bin_capacity as f64 {
        score -= 10.0;
    }

    // Mild preference for fuller bins regardless.
    score -= 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (waste), scaled by stream progress.
    let mut score = pr * (1.0 + 1.5 * norm_pr * (0.5 + progress));

    // Smooth polynomial coupling: residual waste matters more as stream progresses.
    score += 8.0 * norm_pr * norm_pr * (progress * progress + 0.25);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 + 3.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that cannot host the next item.
        score += 3.0 * norm_pr * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Distance from mean residual: prefer bins deviating toward fullness.
    score += 0.5 * (mean_residual - pr).abs() * 0.1;

    // New-bin candidate: make empty bin mildly attractive only for large items.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 12.0 * (1.0 - large_item) * (1.0 - progress) - 5.0 * large_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction bands. Small leftovers are "tight fits" (good),
    // large leftovers are "wasteful fills" (bad).
    let cap = bin_capacity as f64;

    // Band 1: post_residual <= 10 -> excellent (nearly perfect packing)
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 40 {
        score += 6.0;
    } else {
        score += 18.0;
    }

    // Modulo arithmetic: leftover in multiples of 10 is "reusable" by
    // typical item sizes; odd leftovers create dead space.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m >= 5 {
        score += 2.0;
    } else {
        score += 4.0;
    }

    // Integer-division harmonic class: post_residual / item_size ratio
    // tells whether the bin could still hold another item of similar size.
    if item_size > 0 {
        let ratio = post_residual as f64 / item_size as f64;
        if ratio >= 1.0 {
            // bin could take another item of the same size again
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0;
        } else if gap <= 15 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving a stranded mid-size gap
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac > 0.7 {
            score -= 20.0; // big item: fresh bin is fine
        } else {
            score += 25.0; // small item: keep filling existing bins
        }
    }

    // Stream progression: early on, be conservative (prefer tight fits);
    // later, allow more bins since distribution is known better.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Mean residual coupling: when open bins are already loose on average,
    // penalize adding to looseness; when they are tight, reward filling.
    if mean_residual > 0.5 * cap && post_residual > 30 {
        score += 6.0;
    } else if mean_residual < 0.25 * cap {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 12) are unusable by future items
    // (min item size 1, but realistically small fragments waste capacity).
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still host the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Creating a gap too small for the next item: penalize.
        score += 10.0;
    }

    // Reward using bins that are already fairly full (low residual before placement).
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 10.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: make it attractive only when no open bin fits well,
    // i.e., when mean residual is large relative to item (fragmented bins).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bins mildly; escalate when many bins are open.
        score += 20.0 + open_bins_count as f64 * 0.3;
        // But if open bins are fragmented (mean residual small), new bin is fine.
        if fragmentation < (item_size as f64 / bin_capacity as f64) {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack left over.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to how tight the 2-step fit is.
        score -= 300.0 / (1.0 + slack);
        // Extra penalty for leaving very small unusable slack (1..=5 dead units).
        if slack > 0.0 && slack <= 5.0 {
            score += 40.0;
        }
    }
    // Next item does NOT fit in this bin after placement: penalize proportionally
    // to how much of the next item overflows.
    else if next_item_size > 0 && post_residual < next_item_size {
        let overflow = (next_item_size - post_residual) as f64;
        score += 2.0 * overflow;
    }

    // Penalize large post_residual relative to mean residual (wasteful big-bin usage).
    let mean_resid = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.5 * (post_residual as f64 - mean_resid).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Late in the stream, tighten packing: penalize residual more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Slight preference for using already-open bins over opening new ones
    // when many bins are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for any plausible future item.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual > 80 {
        score += 5.0; // near-empty placement wastes the bin's flexibility
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin.
        let mut penalty = 20.0 + 10.0 * progress;
        // If many bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            penalty += 25.0;
        }
        // Lookahead: if the next item is large, a fresh bin is valuable.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx > item_size as f64 && post_residual + item_size as u32 as u32 >= 0 {
                // fresh bin residual = capacity; check if next item fits better there
                let fresh_left = bin_capacity as f64 - nx;
                let here_left = post_residual as f64 - nx;
                if fresh_left >= 0.0 && here_left < 0.0 {
                    penalty -= 35.0;
                }
            }
            // If next item fits exactly into post_residual, keep this bin.
            if next_item_size == post_residual {
                penalty += 40.0;
            }
        }
        // When mean residual is high, open bins are fragmented; new bin ok.
        penalty -= (mean_residual / bin_capacity as f64) * 10.0;
        score += penalty;
    } else {
        // Lookahead synergy: reward bins whose post_residual matches the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let nx = next_item_size as f64;
            let gap = post_residual as f64 - nx;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 6.0; // this bin becomes dead after placement if next item is big
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Prefer filling bins with larger residual slightly less (best-fit bias already
    // via post_residual), add small tie-break on residual balance vs mean.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear tightness reward: strongly favor small post_residual.
    let tight = (pr / cap).powi(2);
    score += 18.0 * tight * (1.0 + progress);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large dead space quadratically, scaled by stream progress.
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead * (0.5 + progress);

    // Last-chance bin: reward it to avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a bin, more so early when residuals are plentiful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_open = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        let usable = (avg_open / cap).max(0.0);
        let lookahead_pressure = if next_item_size > 0 {
            ((next_item_size as f64) / cap).powf(2.0)
        } else {
            0.0
        };
        score += 30.0 + 60.0 * usable - 20.0 * lookahead_pressure * progress;
    } else {
        // Prefer bins whose post_residual still accommodates the lookahead item.
        if next_item_size > 0 {
            if (next_item_size as u32) <= post_residual {
                score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
            } else {
                score += 4.0 * (1.0 - progress);
            }
        }
    }

    // Mild preference for spreading load when many bins are open late in the stream.
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // Smooth progress coupling: late stream favors consolidation (small post_residual).
    score += 10.0 * progress * (1.0 - (pr / cap).exp());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that nothing (min item 1..100)
    // can use is worse than space matching common item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows super-linearly for small unusable slivers.
        if pr <= 5 {
            score += 60.0; // tiny sliver: nearly unusable
        } else if pr <= 10 {
            score += 25.0;
        } else if pr <= 20 {
            score += 10.0;
        }
        // Reward residuals that fall into "harmonic" buckets: multiples of 10
        // and half-capacity fractions are more likely reusable.
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 25 == 0 {
            score -= 10.0;
        }
        if pr % 50 == 0 {
            score -= 15.0;
        }
        // Integer-division class: residual in [50,100) is half-bin class, good.
        let half_class = pr / (bin_capacity / 2);
        if half_class >= 1 {
            score -= 8.0 * half_class as f64;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // Reward proportionally to how well next item fills the leftover.
            let fill = next_item_size as f64 / pr as f64;
            score -= 40.0 * fill;
            // Harmonic match: next item and post_residual share a class.
            if pr % 10 == next_item_size % 10 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: penalize leaving it.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to capacity and no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.85 {
            score -= 70.0; // big item: fresh bin is fine
        } else if fitting_bins_count > 0 {
            score += 90.0; // discourage opening when a fit exists
        } else {
            score -= 50.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0
        * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Late-stream conservatism: waste less as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual below the smallest possible item (1) is impossible,
    // but gaps below a "useful" threshold are dead space.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Non-linear penalty on small post residuals (0 treated as perfect fit).
    if post_residual > 0 {
        let r = post_residual as f64;
        score += 40.0 / r;
    }

    // Reward near-perfect fits (post_residual close to 0) with a bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // If this is the only fitting bin, strongly favor using it (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }

    // Penalize placements whose post_residual is just below the next item
    // (wasted opportunity for lookahead chaining).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins with residual close to item_size
    // (tight fit relative to fleet average).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    // New-bin candidate handling: make empty bin attractive only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If many bins already fit the item, opening a new one is wasteful.
        score += fitting_bins_count as f64 * 25.0;
        // If no other bin fits, opening a new bin is necessary and fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight preference for bins whose residual exceeds item size by a
    // comfortable margin usable by future items (mid-range gaps).
    let pr = post_residual as f64;
    if pr >= 20.0 && pr <= 50.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-empty bin's potential on a poor fit
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill bonus
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // Opening a new bin is penalized, but less when the fit would leave big dead space
        score += 30.0;
        score -= 0.4 * poor_fit;
        // Early in stream, be more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Many open bins with slack: discourage new bins
        score += 1.5 * open_bins_count as f64;
        // If lookahead item fits into the residual left here, new bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Existing bin: bonus if residual after placement accommodates the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 8.0;
            } else {
                score += 0.25 * (next_item_size - post_residual) as f64;
            }
        }
        // Penalize bins deviating from mean residual (keep fleet balanced)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Prefer filling bins that are already low on residual
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth non-linear coupling: penalize large residuals more as stream progresses
    score += 20.0 * progress * pr_norm * pr_norm * (1.0 - pr_norm);

    // Reward tight fits via smooth decay of fit quality
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit * fit * (1.0 + progress);

    // Lookahead: penalize if next item fits well in post_residual (waste of space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = gap / cap;
        score += 10.0 * gap_norm * gap_norm - 8.0 * (1.0 - gap_norm * 2.0).abs() * (1.0 - gap_norm);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening new bins mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
    }

    // Coupling with mean residual: favor bins deviating below mean (consolidation)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    }

    // Harmonic class of post_residual: dead space that cannot host common
    // small items (mod-10 classes) is penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // unusable sliver
        score += 30.0;
    }
    // Prefer residuals that are multiples of 10 (harmonic with item grid)
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: residual quality depends on leftover after next
            let leftover = pr - next_item_size;
            if leftover % 10 == 0 {
                score -= 10.0;
            }
            score -= (leftover as f64) * 0.2;
        } else {
            // next item won't fit here; residual becomes dead until later
            score += 4.0;
        }
        // Integer-division threshold classes on next_item_size
        match next_item_size / 10 {
            0..=2 => score -= 2.0,  // small next item: keep bins flexible
            7..=10 => score += 3.0, // large next item: prefer saving roomy bins
            _ => {}
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits
    // well (residual far from item) or open bins are few and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_possible = (bin_capacity as f64 - mean_residual).abs();
        // Penalize new bin by default; discount when open bins are crowded.
        score = 55.0
            + progress * 20.0
            - (open_bins_count as f64) * 2.0
            + best_possible * 0.1;
    }

    // Mild preference for filling bins that are already partially used
    // (reduces bin count pressure): tighter mean residual means bins are
    // well packed, keep it that way by favoring below-mean residuals.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // Residuals below the minimum item size (1..100 unknown, assume ~10) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 25 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) non-linearly.
    score -= ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress) * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Mild penalty so tight fits in open bins win; reduced under bin pressure.
        score += 60.0 - (open_bins_count as f64).min(20.0);
        // If the current item is large relative to mean residual, opening fresh is attractive.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect match for the next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residual that neither fits next item nor is tiny.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 30.0;
    }

    // Reward tight packing relative to mean residual of open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    // Progress pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item would fit in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is slightly too big, mild penalty for wasting the residual.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // New-bin candidate handling: opening a new bin wastes all residuals of
    // open bins; penalize it proportionally to how much usable space would be lost.
    if bin_residual == bin_capacity {
        let wasted = mean_residual * open_bins_count as f64;
        score = 100.0 + wasted * 0.6;
        // Early in the stream, opening bins is cheap (few bins open).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
        // If nothing fits anywhere else, opening is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for bins whose residual deviates far below mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer keeping a few very large residual bins alive for big future items.
    if bin_residual as f64 > mean_residual + 20.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial base: penalize residual with cubic coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * cap * pr_norm * pr_norm * (1.0 - progress);

    // Smooth dead-space penalty: quartic small-residual term
    if pr > 0.0 {
        score += 6.0 * (1.0 - pr_norm).powi(3) * (1.0 + progress);
    }

    // Tight-fit reward: smooth bell around small post_residual
    let tight = (-pr_norm * 8.0).exp();
    score -= 12.0 * tight * (1.0 + 0.5 * progress);

    // Lookahead coupling: smooth polynomial interaction between post_residual and next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = ((pr - nx).abs()) / cap;
        score += fit_next * (10.0 * gap * gap - 6.0 * gap) - (1.0 - fit_next) * 8.0 * (1.0 - pr_norm);
    } else {
        // Last item: strongly prefer filling bins completely
        score -= 20.0 * (1.0 - pr_norm);
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Crowd penalty: many open bins with high mean residual -> favor consolidation
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 0.5 * crowd * (mean_residual / cap) * (1.0 - progress);

    // Mild preference for opening new bins early, reusing late (smooth sigmoid)
    let sigmoid = 1.0 / (1.0 + (-(progress - 0.5) * 6.0).exp());
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - sigmoid) - 4.0 * sigmoid;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the residual: classify post_residual by its
    // "usability" against typical small item sizes (1..=100 unknown dist).
    // Residuals divisible by common divisors (harmonic classes) tend to
    // be fillable by combinations of small items.
    let r = post_residual;
    let class: f64 = if r <= 10 {
        0.0 // nearly dead space
    } else if r % 10 == 0 {
        6.0 // harmonic with capacity fractions: very reusable
    } else if r % 5 == 0 {
        4.0
    } else if r % 2 == 0 {
        2.0
    } else if r <= 20 {
        -1.0 // small odd residual: likely dead space, penalize
    } else {
        1.0
    };
    score -= class * 3.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // reward proportionally to how well next item uses leftover
        let fill = next_item_size as f64 / r as f64;
        score -= 60.0 * fill;
        // harmonic bonus if combined residual stays harmonic
        let r2 = r - next_item_size;
        if r2 % 10 == 0 || r2 == 0 {
            score -= 30.0;
        }
    } else if next_item_size > r && r > 0 {
        // leftover too small for next item: penalize dead space
        score += 25.0 + 0.5 * r as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // residuals are poor (tight packing early, fragmentation late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin: neutral-ish baseline; penalize when open bins are
        // still healthy and the stream is early/mid.
        let healthy = mean_residual / bin_capacity as f64;
        score += 150.0 + 250.0 * (1.0 - progress) + 200.0 * healthy;
    } else {
        // Slight bonus for using existing bins generally.
        score -= 10.0;
        // Prefer tighter existing bins relative to mean residual.
        score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0);
    }

    // Discourage hoarding many bins when current fit is decent.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item * 10.0 {
            score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: prefer tighter packing when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a good future fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 20.0;
        }
    }

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Waste relative to mean residual.
    score += 0.3 * ((post_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chain), or comes close to it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits here afterwards: scale reward by closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize proportional to the gap.
            score += 10.0 * (diff / nxt);
        }
    }

    // Penalize leaving dead space that nothing (size >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: bins tighter than average are better.
    let pr = post_residual as f64;
    score += 0.5 * (pr - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when the fit is very tight
    // (wasting a fresh bin is costly), otherwise discourage.
    if bin_residual == bin_capacity {
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Slight preference for filling bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low, amplify it.
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, higher = tighter
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to ever fit a future item (min size 1..100 unknown,
    // so use a soft threshold around 10% of capacity).
    let dead_threshold = 0.10 * bin_capacity as f64;
    if (post_residual as f64) < dead_threshold {
        score += 8.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Penalize opening a new bin unless the fit is poor in all open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 10.0;
        // More bins already open -> opening another fragments capacity; penalize more.
        score += 0.5 * open_bins_count as f64;
        // If this is the last chance among fitting bins, the new-bin call will also see
        // fitting_bins_count == 1; keep it competitive but slightly worse than reusing.
        if fitting_bins_count == 1 {
            score -= 13.0; // net penalty ~ +10 - 13 + 0.5*open = still slightly higher than reuse
        }
        // If many open bins have large mean residual, avoid opening yet another bin.
        score -= 0.05 * mean_residual;
    }

    // Lookahead: if the next item would fit exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * chain_tightness;
        } else {
            // Next item cannot use this residual: dead space more likely, penalize leftover.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Time horizon: early in the stream, be conservative (favor reusing bins to keep
    // options open); late in the stream, tolerate tighter/cramped placements.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * fit_ratio;

    // Global pressure: when many bins are open relative to stream length, discourage
    // opening new bins implicitly by rewarding reuse of any existing bin.
    score -= 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear tightness reward: quadratic coupling of post_residual with item size
    let it = item_size as f64;
    score -= (it / cap) * (1.0 - (pr / cap)) * (1.0 - (pr / cap)) * 30.0;

    // Smooth stream-progress coupling: later in the stream, waste is penalized more strongly
    let prog_term = progress * progress * (1.0 - progress * 0.5);
    score += pr * prog_term * 0.8;

    // Penalize large post residual when it cannot plausibly hold the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let unusable = ((ni - pr) / cap).max(0.0);
        let usable = ((pr - ni) / cap).max(0.0);
        score += unusable * unusable * 25.0;
        score -= usable * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    } else {
        // mild penalty for spreading across many bins
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins with residual below mean (consolidate waste)
    score += (mean_residual - pr) * 0.3;

    // New-bin candidate: make it moderately attractive only when residuals are fragmented
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let fragmentation = (mean_residual / cap).min(1.0);
        score += 15.0 - 25.0 * fragmentation * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies on a
    // "friendly" lattice (multiples of 10, or small enough to be near-dead)
    // are treated specially.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Dead-space penalty grows super-linearly for awkward leftovers.
    if post > 0 && post < 10 {
        score += 60.0; // tiny unusable slivers are the worst outcome
    } else if post <= 20 {
        score -= 10.0; // perfect small-class fit: excellent packing
    }

    // Modulo-10 harmonic class: leftover divisible by 10 is reusable by the
    // typical item granularity.
    if post % 10 == 0 {
        score -= 8.0;
    } else if post % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0;
    }

    // Integer-division threshold: leftover in [next_item_size .. next+10)
    // guarantees the lookahead item also fits -> strong reward.
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if post >= nx {
            score -= 20.0;
            // extra reward if the second placement again leaves a harmonic class
            let post2 = post - nx;
            if post2 % 10 == 0 {
                score -= 12.0;
            }
        } else {
            // lookahead item cannot follow in this bin
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to mean residual or nothing fits well).
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.9;
        let crowded = open_bins_count == 0 || fitting_bins_count == 0;
        if tight || crowded {
            score -= 15.0; // open a fresh bin rather than fragmenting
        } else {
            score += 30.0; // keep using existing bins when they fit reasonably
        }
    }

    // Fraction-of-capacity coupling: favor leaving residuals in the upper
    // half of capacity classes (more reusable).
    let frac = post as f64 / cap as f64;
    if frac > 0.5 {
        score -= 5.0;
    } else if frac < 0.1 && post > 0 {
        score += 10.0;
    }

    // Mild stream-progression pressure: as the stream advances, tighten
    // tolerance for wasteful placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // minimum plausible item are worthless; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect closure is the best outcome.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // If the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host the lookahead item: mild penalty,
        // scaled by how badly it misses.
        score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless
    // the placement is genuinely efficient.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the dead space is egregious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when the stream is early or all open bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_fullness * 10.0);
        score += 20.0 + 2.0 * pressure - 30.0 * mean_fullness;
        // Late in the stream, prefer consolidation over new bins.
        score += 25.0 * progress;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // keeps the bin pool balanced.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = if post_residual == next_item_size {
            -60.0 // perfect 2-step fit
        } else {
            -30.0 * (next_item_size as f64 / post_residual as f64)
        };
        score += match_quality;
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space
        score += 10.0 + (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Penalize residuals below the smallest plausible item threshold
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Slight pressure against opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: minimize post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    } else {
        // Mild dispersion penalty when many bins compete.
        score += (fitting_bins_count as f64) * 2.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0 + (next_item_size as f64 / bin_capacity as f64) * 20.0;
        } else {
            // Penalize leaving residual just below next item size (near-miss waste).
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > -10.0 && gap < 0.0 {
                score += 15.0;
            }
        }
    }

    // Global state: when mean residual is high, prefer consolidating into fuller bins.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.5;

    // Time horizon: early in stream, be conservative about fragmenting (favor tight fits more);
    // late in stream, prefer closing bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * (bin_residual - item_size) as f64 * 0.3;
    score += (1.0 - t) * 8.0;

    // New-bin candidate: only attractive when no open bin fits well
    // (handled implicitly: empty bin has max post_residual, so it loses unless
    // all open bins would create tiny dead space). Add slight penalty so we
    // don't open bins unnecessarily.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if stream is early and open bins are nearly full on average,
        // opening a fresh bin is fine.
        score -= (1.0 - t) * (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Discourage spreading across many open bins when few remain useful.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (0.5 + 0.5 * progress) + pr_norm * (1.0 - progress) * 0.3;
    score += poly * cap * 0.4;

    // Penalize near-full waste mildly, reward tight fits
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 6.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 2.0 + (-gap / cap) * 4.0;
        }
    }

    // Mean residual alignment: prefer bins close to the mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Slight pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.02 * pr_norm;

    // New-bin candidate: prefer it only when it offers maximal flexibility early
    if bin_residual == bin_capacity {
        score += 4.0 * progress + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band it falls into.
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor() as i32; // 0..8 harmonic band

    // Perfect fit is best
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space with non-linear growth by harmonic class
        score += (class as f64) * (class as f64) * 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, that's good (chained fit)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves residue: mild penalty proportional to leftover
            let nxt_left = (post_residual - next_item_size) as f64;
            score += nxt_left * 0.5;
            if nxt_left < cap * 0.05 {
                score -= 50.0; // near-perfect chain
            }
        } else {
            // next item cannot use post_residual: dead space likely, penalize small residuals harder
            if pr < cap * 0.25 {
                score += 30.0 + pr * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Modulo-arithmetic class on post_residual: multiples of small sizes are reusable
    let pr_u = post_residual;
    let reusable = pr_u % 10 == 0 || pr_u % 20 == 0 || pr_u % 25 == 0;
    if reusable && pr_u > 0 {
        score -= 15.0;
    }

    // Integer division threshold: residual in lowest band is nearly dead
    if pr_u > 0 && pr_u < 10 {
        score += 60.0;
    }

    // Slight preference for filling fuller bins (relative fill fraction)
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * 20.0;

    // Early in stream: be more willing to open new bins (keep flexibility)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus discount as stream progresses
        score = cap * 0.55 - progress * cap * 0.15;
        if post_residual == 0 { score -= 1.0; }
    } else if open_bins_count > 20 && progress < 0.3 {
        score += 5.0; // too many bins early: discourage spreading
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals of 1..=9 are nearly unusable
    // (smallest item is >= 1 but typical streams leave 10-80 gaps useless).
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0; // heavy penalty for creating dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward closing the bin
    } else {
        // Larger leftover gaps are more reusable: mild reward scaled by gap size
        score -= 0.15 * (post_residual as f64).sqrt();
    }

    // Tight-fit reward: fraction of the bin consumed by this item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Penalize bins whose residual is much larger than the item (wasteful match)
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * waste * waste;

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins and
    // prefer consolidating into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        score += 5.0 + 2.5 * open_bins_count as f64;
        // Slight discount late in the stream when residuals are fragmented
        if open_bins_count as f64 > mean_residual / 5.0 {
            score += 10.0;
        }
    } else {
        // Existing bin: reward when open-bin count is high (consolidation pressure)
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 9 {
        score += 15.0; // this placement would create dead space for the next item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // next item can reuse the leftover gap
    }

    // Early-stream tie-breaking: slightly prefer filling existing bins early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly matches the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size == post_residual {
            score -= 400.0; // chain fit: next item fills this bin perfectly
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally to how tightly it nests
            let tightness = 1.0 - (pr - nxt) / bin_capacity as f64;
            score -= 120.0 * tightness;
            // extra reward if post_residual - next_item is small (<= 10 dead space)
            if post_residual - next_item_size <= 10 {
                score -= 80.0;
            }
        } else {
            // next item won't fit here: penalize leaving residual that wastes space
            let waste = (pr - nxt).abs();
            score += 30.0 * (waste / bin_capacity as f64) * 10.0;
            // small residuals (< 10, below min item size) are pure dead space
            if post_residual < 10 {
                score += 150.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (pr - mean_residual) / (mean_residual + 1.0);
        score += 25.0 * deviation;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
        if post_residual <= 20 {
            score -= 100.0;
        }
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 90.0;
        // allow new bin early in the stream or when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 60.0;
        }
        if pr as u32 >= item_size && next_item_size > 0 && next_item_size <= post_residual {
            score -= 70.0; // fresh bin can host the next item too
        }
    }

    // Mild preference for tighter bins among equals.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 2.5 * fill;

    // Penalize small leftover dead space that few future items can use,
    // but reward perfect (zero) residual closure.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score += 6.0; // awkward sliver
    } else if post_residual <= 30 {
        score -= 3.0; // usable mid-range leftover
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover; mild penalty scaled by waste.
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 1.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global residual pressure: if mean residual is high, packing into existing
    // bins is cheap; if low, keep bins tight.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when good alternatives exist.
        if fitting_bins_count > 0 {
            score += 20.0 + 3.0 * fitting_bins_count as f64;
        } else {
            score -= 5.0; // must open anyway
        }
        // Opening a fresh bin is more acceptable late when open bins are nearly full.
        if open_bins_count > 0 {
            let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
            score -= 15.0 * avg_fill;
        }
        // Small next item makes a fresh bin attractive.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_n = pr / cap;

    // Base: post-residual, with non-linear penalty on mid-range dead space
    let mut score = pr;

    // Smooth polynomial coupling: dead space penalty grows as stream progresses
    let dead = pr_n * (1.0 - pr_n); // peaks at half-full residuals
    score += 40.0 * dead * (t * t * (3.0 - 2.0 * t));

    // Reward tight fits (small post_residual) more strongly early on
    score -= 25.0 * (1.0 - pr_n) * (1.0 - pr_n) * (1.0 - t);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * t;
    }

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 + 20.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - t);
    }

    // Perfect closure reward (smooth via cubic)
    let closure = (pr_n * (cap - pr) / cap).max(0.0);
    score -= 50.0 * closure * closure * closure.max(1.0) / cap.max(1.0);

    // Penalize opening new bins when many bins are already open and fit is poor
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (20.0 + 10.0 * open_bins_count as f64) * (0.5 + 0.5 * t);

    // Mild preference for bins below mean residual (balancing)
    score += 5.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual (dead-space tiers)
    let class: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };
    score += class as f64 * 12.0;

    // Alignment bonus: residuals that are multiples of 10 are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead (k=2): penalize leaving a residual that cannot host the next item
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 25.0 + (post_residual as f64) * 0.3;
        } else {
            // next item fits into the leftover: reward proportional to how snugly
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 500.0;
    }

    // New-bin candidate (empty bin): only attractive when nothing else fits
    if bin_residual == bin_capacity {
        score = 200.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 400.0; // no open bin can host: open a new one
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0; // fresh bin wasted for this item anyway
        }
    }

    // Slight preference for bins below the mean residual (tighter bins first)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Early in the stream, be slightly more selective about dead space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect or near-perfect packing.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual == 10 {
        score -= 25.0;
    }

    // If the next item fits exactly into the resulting gap, strongly favor it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 2.0 * slack;
    }
    // If next item cannot fit in the gap, the gap is likely dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: prefer it only when open-bin pressure is high and
    // current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        // Mildly attractive baseline for a fresh bin.
        score = 45.0;
        if open_bins_count as f64 > 3.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64) {
            score -= 10.0;
        }
    }

    // Open-bin pressure: encourage filling existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Slight preference for bins with residuals below average (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly favor bins whose post residual
    // exactly matches the next item size (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Penalize wasted gap relative to next item size.
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot fit here; penalize small unusable leftovers.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Compare post residual against mean residual across open bins:
    // placing into a bin that stays near the mean residual keeps balance.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.1;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize creating tiny dead space (< 10, unusable for min item size 1
    // but wasteful relative to typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Late in the stream, prefer filling existing bins tightly rather
    // than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    } else {
        // New-bin candidate: mild penalty so it only wins when fits are poor.
        score += 30.0 - progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically, but only if it's truly unusable
    // for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.9 * (post_residual as f64).powf(1.5);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room exactly sized for the next item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when current
    // bins are crowded and this fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit = fit_ratio < 0.5;
        if poor_fit && mean_residual < 35.0 {
            score -= 12.0 + 8.0 * (1.0 - progress);
        } else {
            score += 30.0 + 2.0 * crowded;
        }
    }

    // Reward using bins whose residual is above the mean (consolidate space).
    let resid_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * resid_gap;

    // Mild reward for high occupancy late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Penalize leaving exactly-small unusable slivers (<=10).
    if post_residual <= 10 && post_residual > 0 {
        score += 8.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space grows super-linearly with post_residual
    let post_norm = post / cap;
    score += 4.0 * post_norm * post_norm * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - post_norm).powi(3) * (0.5 + progress);

    // Penalize bins whose residual is far from mean residual (fragmentation coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if placing here blocks the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 2.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 3.0 + 4.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: prefer opening a new bin only when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).powi(2);
        score = cap - 6.0 * frag * cap * (1.0 - progress) - 5.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting bin
        }
    }

    // Mild penalty for proliferating open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual (modulo arithmetic) ----
    // Residuals divisible by coarse power-of-two classes are "usable" for
    // typical small items; odd/prime-ish residuals are dead space.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly rewarded
    } else if pr % 50 == 0 {
        -12.0 // half-capacity class: very reusable
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        4.0 // awkward residual: penalize
    };
    score += class;

    // ---- Integer-division threshold on post_residual ----
    // Residuals that can host the most common small sizes get a bonus.
    let quot = pr / 10; // how many 10-sized items fit
    score -= (quot.min(8)) as f64 * 1.5;

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here too: strong reward, scaled by how snugly.
            let snug = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 8.0 + 10.0 * snug;
        } else {
            // Next item cannot follow here: mild penalty proportional to gap.
            score += ((next_item_size - pr) as f64 / cap) * 6.0;
        }
    }

    // ---- Last-chance bin pressure ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // must use this bin or open a new one
    }

    // ---- New-bin candidate arbitration ----
    if bin_residual == bin_capacity {
        // Opening a new bin is good if the item leaves a harmonic residual
        // and there are few fitting bins; bad if many bins could take it.
        score -= 6.0 + class * 0.5;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 3.0;
        }
    } else {
        // Prefer filling existing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress;
        // Reward bins tighter than the mean residual (good compaction).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // ---- Fragmentation penalty: non-linear in wasted fraction ----
    let waste = post_residual as f64 / cap;
    score += waste * waste * 12.0;

    // Small tie-breaker favoring larger item placement into tighter bins.
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual super-linearly.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score -= 15.0;
    }

    // Dead space penalty: residual gaps too small for the smallest plausible
    // future item are unusable; punish them hard (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // A post_residual that exactly fits the lookahead item is a jackpot.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // If the next item fits comfortably in the post residual, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size + 10 {
        score -= 8.0;
    }
    // If the next item would NOT fit here after placement, this bin risks
    // becoming a dead-end; add pressure proportional to wasted space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; favor
    // filling existing bins rather than opening new ones.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: if mean residual is large (bins are loose),
    // prefer packing into existing space; if small, opening a new bin is
    // relatively less costly.
    score += 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin has full residual. Only choose
    // it when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap (build a pool of bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If no open bin can fit the item, the new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Large current item leaves small post_residual in a fresh bin only
        // if item is near capacity; a fresh bin for a tiny item is wasteful.
        if item_size < 20 {
            score += 30.0;
        }
    }

    // Slight preference for bins whose residual is close to item size
    // (best-fit flavor) beyond the raw post_residual baseline.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward leaving exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            // Reward proportional to how tight the two-step fit is.
            score -= 30.0 / (1.0 + slack_after_next / 10.0);
        } else {
            // Next item cannot follow into this bin: penalize dead space, worse if small.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.25 * dead;
        }
    }

    // Penalize residual far below mean (wasted capacity relative to fleet average).
    score += 0.35 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: make it unattractive unless current bin would leave bad dead space
    // or the item is huge and the stream is early (keep bins open for future pairings).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_space_penalty = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += 25.0 - dead_space_penalty - 10.0 * (1.0 - progress);
        // Discourage new bins when plenty of open bins exist.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Reward tight fills (quadratic fill bonus)
    score -= (cap - post) * (cap - post) * 0.02;

    // Lookahead chaining: strongly favor bins whose post-residual fits the next item
    if next_item_size > 0 && nxt <= post {
        score -= 12.0 + nxt * 0.15;
    }

    // Penalize small unusable dead space, more so early in the stream
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 15.0;
    }

    // New-bin candidate: penalize by default; relax when existing bins are crowded
    score += is_new_bin * (20.0 + mean_residual * 0.3 - progress * 10.0);

    // Mild penalty for deviating from the fleet's mean residual (keeps bins balanced)
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let tight = (pr / cap).powi(3);

    // Base: penalize leftover space, weighted by smooth progress coupling
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear reward for tight fits (small post_residual)
    score -= 30.0 * fill * fill * (1.0 - tight);

    // Penalize dead space that likely can't be used later
    let nxt = next_item_size as f64;
    let usable = (pr - nxt).max(0.0) / cap;
    score += 12.0 * (1.0 - usable) * (1.0 - usable) * pr / cap;

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 && pr >= nxt {
        score -= 15.0 * (1.0 - (pr - nxt) / cap);
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * fill;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    // Mean-residual coupling: discourage bins far below mean residual (wasteful)
    score += 0.3 * (mean_residual - pr).abs();

    // New-bin candidate: smooth penalty that relaxes late in stream / when fits are poor
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + fitting_bins_count as f64);
        score = cap * (0.5 + 0.5 * progress) + 5.0 * open_pressure;
        if fitting_bins_count == 1 {
            score += 40.0; // never open new bin when it's the last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity-fraction bucket does post_residual fall in?
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4).max(1);
    let eighth = (bin_capacity / 8).max(1);

    // Class A: post_residual is an exact divisor-compatible residue (fits small items cleanly)
    let harmonic_class = if post_residual == 0 {
        0 // perfect fit — best possible
    } else if post_residual % 10 == 0 && post_residual >= 10 {
        1 // round residue, likely usable by future items
    } else if post_residual < quarter {
        2 // small dead space — mildly penalize
    } else if post_residual < 2 * quarter {
        3 // medium residue
    } else {
        4 // large residue — bin still very usable
    };

    match harmonic_class {
        0 => score -= 25.0,
        1 => score -= 8.0,
        2 => score += 6.0,
        3 => {}
        _ => score -= 4.0,
    }

    // Integer-division threshold: does post_residual still admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead continues in this bin: reward chain packing
            let chain_depth = post_residual / next_item_size; // integer division
            score -= 3.0 + chain_depth as f64;
            // harmonic bonus if next item would also land on a round residue
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 2.5;
            }
        } else {
            // next item cannot follow here; penalize blocking the chain
            score += 5.0;
            // but if residue is tiny it's "closed cleanly"
            if post_residual < eighth {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / cap);
        // opening a bin is good when open bins are already well-filled on average
        let openness_penalty = 20.0 * (1.0 - avg_fill);
        score += openness_penalty + 10.0 * (1.0 - progress);
        // never open when a fitting bin exists and mean residual is small
        if mean_residual < item_size as f64 * 1.5 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Prefer tighter fits: relative waste ratio via modulo class
    let waste_ratio = post_residual as f64 / cap;
    score += 4.0 * waste_ratio * waste_ratio;

    // Harmonic modulo coupling: reward residues that are multiples of common small sizes
    for m in [5u32, 10, 20, 25, 50].iter() {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 1.0;
        }
    }

    // Congestion: many open bins with high mean residual → consolidate, avoid spreading
    if open_bins_count > 3 && mean_residual > 0.5 * cap && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (size ~10, but distribution unknown -> use a
    // conservative small-gap threshold) are wasted forever. Penalize hard.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 80.0;
    }

    // Non-linear tightness reward: quadratically favor small (but usable) gaps.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Next-item lookahead: if the residual after placement can host the next
    // item exactly or well, reward it; if it leaves a gap the next item
    // cannot use, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid pushing
    // toward a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < dead_threshold {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones (the new-bin candidate has max residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powi(2) * 0.15 * (0.5 + progress);

    // Alignment with mean residual: bins whose post-residual is far below the
    // mean are being packed tightly -> reward; far above -> mild penalty.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: brand-new empty bin gets a fixed opening cost that
    // grows with the number of open bins, so it only wins when no open bin
    // offers a decent fit.
    if bin_residual == bin_capacity {
        score += 90.0 + 10.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-match: next item fits into post_residual with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack * 1.5;
    }
    // Next item cannot use the leftover: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Reward tight fits of the current item relative to mean residual.
    let tightness = (bin_capacity as f64 - (post_residual as f64 - mean_residual)).max(0.0);
    score -= tightness * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize spreading across too many open bins when a new bin would be cleaner.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well (large post_residual mismatch), new bin is attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    } else if open_bins_count > 6 {
        score -= 10.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * (bin_residual as f64);

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that is too small for typical items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Post-residual unusable for next item: mild penalty, worse late in stream.
            score += 5.0 + 5.0 * progress;
        }
        // If this bin is the only option and next item is large, discourage wasting it.
        if fitting_bins_count == 1 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bin bonus: using the sole fitting bin avoids opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when few bins fit
    // the item or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64)
        } else {
            0.0
        };
        // Base cost of a fresh bin, discounted when existing bins are congested
        // or few alternatives exist.
        score = 60.0 - 30.0 * open_pressure - 10.0 * (fitting_bins_count as f64).recip();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with a large follow-up item
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time-horizon drift: early on be conservative (keep residuals large),
    // late in stream be aggressive (fill anything).
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr + 0.35 * progress * progress);

    // Penalize large dead space more than linearly (quadratic term)
    score += 0.5 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) especially early in the stream
    score -= (1.0 - norm_pr) * (1.0 - progress) * 8.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the mean residual (balance)
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (nx / cap).powf(1.5));
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferating many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small dead space (mod classes 1..9) is penalized unless near-zero.
    let r_mod = post_residual % 10;
    if post_residual == 0 {
        score -= 30.0; // perfect fit: strong reward
    } else if r_mod == 0 {
        score -= 8.0; // residual divisible by 10 aligns with item size classes
    } else if r_mod <= 5 {
        score += 6.0 + (5 - r_mod) as f64; // tiny unusable slivers
    }

    // Fractional fill of the bin by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac * fill_frac;

    // Harmonic threshold: prefer leaving residuals in the "pairable" band [next, next+small]
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt && (post_residual as f64 - nxt) <= 5.0 {
            score -= 15.0; // leaves room exactly for lookahead item
        } else if post_residual > 0 && (post_residual as f64) < nxt {
            score += 4.0; // dead space relative to lookahead
        }
        // Integer-division harmony: post_residual / next_item_size exact
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when the item fits existing space well.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Late-stream consolidation: as stream progresses, favor tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 {
        let unusable = (post_residual as f64) < 10.0;
        if unusable {
            score += 60.0; // tiny dead space is wasted capacity
        } else {
