    if bin_residual != bin_capacity {
        let pressure = (open_bins_count as f64) * 2.5;
        score -= pressure;
    } else {
        // New-bin candidate: penalize slightly so it's chosen only on good rationale
        score += 15.0;
        // Opening a new bin is attractive if it enables a near-perfect future fit
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < 15.0 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
