    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }

    // Mean residual coupling: avoid leaving residuals far below mean (fragmentation)
    if bin_residual != bin_capacity {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // Slight preference to place larger items earlier in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (item_size as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

