    let tightness = item_size as f64 / cap;
    score -= tightness * 20.0;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin would leave big dead space
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        if next > 0.0 && (waste - next).abs() < 3.0 {
            score -= 15.0; // fresh bin supports next item perfectly
        }
        score += 10.0; // default mild penalty: prefer reusing open bins
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    if post > 0.0 && post < 10.0 {
        score += 30.0;
    }

    // Context: many open bins -> prefer consolidation (reuse), penalize spreading
    if open_bins_count > 4 {
        score += (post - mean_residual).max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
