    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many items remain
        // and existing bins are fragmented (high mean residual spread).
        let fragmentation = (post_residual as f64 - mean_residual).abs().max(1.0);
        let discount = progress * (1.0 - 1.0 / (1.0 + fragmentation));
        score = 35.0 - 10.0 * discount + 0.1 * open_bins_count as f64;
        // If no open bin fits at all, opening a new bin is necessary-ish.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Penalize large dead space more than linearly as stream progresses
    score += 40.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) increasingly over time
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Mild penalty when many alternatives exist, scaled by residual
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * norm_pr;
    }

    // Encourage filling bins below mean residual (balancing open bins)
    score += 0.15 * (pr - mean_residual);

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 20.0 * (1.0 - gap * gap);
        } else {
            // next item cannot fit here: slight penalty proportional to waste
            score += 5.0 * progress;
        }
    } else {
        // Last item: just minimize residual
        score -= 10.0;
    }

    // Slight preference to keep open bins count low late in the stream
    score += 0.5 * open_bins_count as f64 * progress * norm_pr;

    // New-bin candidate: neutral baseline so it wins only when open bins score badly
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (integer division thresholds) ----
    // Class 0: post_residual <= 10  -> perfect fit, heavily reward
    // Class 1: 11..=25              -> small dead space
    // Class 2: 26..=50              -> moderate
    // Class 3: >50                  -> wasteful
    let class = if post_residual <= 10 { 0u32 }
        else if post_residual <= 25 { 1 }
        else if post_residual <= 50 { 2 }
        else { 3 };

    score -= match class {
        0 => 40.0,
        1 => 18.0,
        2 => 4.0,
        _ => 0.0,
    };

    // Modulo arithmetic: post_residual divisible by common item granularities
    // (5, 10, 20) is more likely to be exactly filled by future items.
    if post_residual > 0 {
        if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
    }

    // Exact match with the lookahead item: strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - tight / cap_f);
        } else {
            // Next item will NOT fit here: penalize, this bin becomes dead space.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: reward tight fits even more to disambiguate.
        score -= (30.0 - (post_residual as f64).min(30.0)) * 0.4;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only good when no existing bin fits well.
        // Base penalty so a decent existing fit beats a new bin.
        score += 20.0;
        // If nothing else fits, new bin is the only option: remove penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: new bin slightly worse than last-chance use.
            score += 5.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the item is huge, new bin keeps flexibility for large future items.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward keeping bins compact / few open bins.
        score += open_bins_count as f64 * 0.05;
        // Prefer bins with residual below the mean (consolidate emptier space).
        let res_f = bin_residual as f64;
        if res_f < mean_residual {
            score -= 2.0 * (mean_residual - res_f) / cap_f;
        } else {
            score += 1.0 * (res_f - mean_residual) / cap_f;
        }
    }

    // Global preference for filling bins deeply: subtract for low post_residual.
    score -= 0.25 * (cap_f - post_residual as f64) / cap_f * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        // Dead space penalty: smaller unusable gap => heavier penalty.
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonable fit exists; encourage using existing bins.
    if bin_residual != bin_capacity {
        score -= 3.0;
        score += open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: penalize opening a bin unless the fit is bad
        // or the stream is early and consolidation is cheap.
        score += 15.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
        // If no open bin fits well (large dead space elsewhere), opening
        // a new bin becomes attractive: offset the penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement; if post_residual is just barely too small
    // for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the
    // mean (more filled bins), keeping well-filled bins busy.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), but scale relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible -> strong reward.
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else if next_item_size <= bin_residual {
            // Next item fits only if we DON'T place here -> mild penalty for consuming space.
            score += 8.0;
        } else {
            // Next item won't fit this bin either way; dead space matters more.
            score += (post_residual as f64) * 0.1;
        }
    }

    // Compare post_residual against mean residual: penalize bins that end far above mean
    // (fragmenting), reward bins that end near or below mean (consolidating).
    let mean_post = mean_residual - item_size as f64;
    let diff = post_residual as f64 - mean_post;
    score += diff * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Empty new-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a very awkward residual elsewhere.
    if bin_residual == bin_capacity {
        let awkward = (post_residual > 0 && post_residual < 20) || (next_item_size > 0 && next_item_size > post_residual && next_item_size > 50);
        if awkward {
            score -= 30.0;
        } else {
            score += 30.0;
        }
    }

    // Late in the stream, tighten up: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 5.0;
    }

    // Prefer bins with already-low residual (pack nearly-full bins first).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowd penalty: when many bins are open, avoid fragmenting; when few, exploit open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * open_pressure * (1.0 - progress);

    // Mean-residual anchor: prefer bins near the mean residual (balanced usage)
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only attractive when no decent fit exists
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            1000.0
        } else {
            let best_possible = (bin_capacity - item_size.min(bin_capacity)) as f64;
            if best_possible > 40.0 { -5.0 } else { 15.0 + 0.3 * best_possible }
        };
        score += 30.0 - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let fit_frac = 1.0 - (it / cap);

    // Smooth polynomial coupling: reward tight fits more strongly as the stream progresses.
    let tightness = (pr / cap).powi(2) * (1.0 - pr / cap);
    score -= tightness * (30.0 + 40.0 * progress) * fit_frac;

    // Lookahead: penalize post-residuals that cannot host the next item (dead space),
    // reward residuals that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - ((pr - nxt) / cap).powi(2)) * 8.0 * (1.0 + progress);
        } else {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate (empty bin): make it mildly unattractive unless post space is large
    // and open-bin pool is fragmented; smooth in progress and mean residual.
    if bin_residual == bin_capacity {
        let frag = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).powi(2);
        score += 10.0 * (1.0 - frag) * (1.0 - progress) - (mean_residual / cap) * 6.0 * frag;
    }

    // Mild penalty for leaving residuals that are awkwardly small relative to mean residual.
    score += ((mean_residual - pr) / cap).max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue classes mod 10 capture
    // "dead space bands" that are hard to fill for typical item sizes.
    let pr = post_residual;
    let class = pr % 10;
    let quotient = pr / 10;

    // Reward tight fits strongly (post_residual near zero).
    if pr == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if pr <= 5 {
        score -= 40.0 + (5 - pr) as f64 * 8.0;
    } else if pr <= 10 {
        score -= 10.0;
    } else {
        // Dead-space penalty grows for residuals in awkward bands.
        // Classes 1..=3 are nearly unusable (min item is small though),
        // classes 4..=9 partially usable.
        let dead_penalty = match class {
            1..=3 => 18.0,
            4..=6 => 6.0,
            _ => 0.0,
        };
        score += dead_penalty + quotient as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size < pr {
            let new_pr = pr - next_item_size;
            // Reward chains that stay in fillable classes.
            if new_pr <= 10 {
                score -= 25.0;
            } else if new_pr % 10 >= 4 {
                score -= 8.0;
            } else {
                score += 5.0;
            }
        } else {
            // Next item won't fit here; mildly penalize unless this is a tight fit anyway.
            if pr > 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (item large relative to mean residual,
    // or all fits would leave big waste).
    if bin_residual == bin_capacity {
        let perfect_for_next = next_item_size > 0 && next_item_size >= bin_capacity / 2;
        let poor_fit_everywhere = mean_residual < item_size as f64 * 0.55;
        if poor_fit_everywhere || (fitting_bins_count == 0 && perfect_for_next) {
            score -= 55.0;
        } else {
            // Discard new bin unless every existing fit would waste a lot.
            score += 25.0 + mean_residual * 0.3;
        }
    }

    // Slight pressure toward consolidating bins when many are open.
    score += open_bins_count as f64 * 0.15;

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (pr <= 15) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open bins pressure: penalize using bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: mild penalty so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let item_frac = (item_size as f64 / cap).clamp(0.0, 1.0);
    let progress = (step_index as f64) / ((total_items.max(1)) as f64);
    let mean = if mean_residual.is_finite() { mean_residual } else { post };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score;

    if next > 0.0 && post + 0.5 >= next {
        // This placement can absorb the lookahead item too.
        let tail = post - next;
        let tightness = 1.0 - (tail / cap).clamp(0.0, 1.0);
        score = tail - (16.0 + 24.0 * tightness * tightness);
        if tail <= 0.5 {
            score -= 12.0;
        }
    } else {
        score = post;

        if next > 0.0 {
            // If this bin takes the current item, the lookahead item will likely need a fresh bin.
            score += (cap - next).max(0.0);

            if next <= residual + 0.5 {
                // Placing here destroys a residual that the next item could have used.
                let blocked = ((next - post) / cap).clamp(0.0, 1.0);
                score += 6.0 + 28.0 * blocked;
            }
        }
    }

    // Mean-residual coupling: penalize loose residuals, gently reward tighter-than-average bins.
    score += 0.22 * (post - mean).max(0.0);
    score -= 0.08 * (mean - post).max(0.0);

    if !is_new_bin {
        if fitting_bins_count == 1 {
            let new_bin_can_pair = next > 0.0 && next <= cap - item_size as f64 + 0.5;

            if next > 0.0 && post + 0.5 >= next {
                score -= 20.0 + 16.0 * item_frac + 10.0 * progress;
            } else if next > 0.0 && next <= residual + 0.5 {
                score -= 1.0 + 3.0 * progress;
            } else if new_bin_can_pair {
                // A fresh bin may be able to hold both the current and lookahead item.
                score += 2.0 + 0.10 * (cap - residual).max(0.0);
            } else {
                score -= 14.0 + 14.0 * item_frac + 8.0 * progress + 0.05 * mean.max(0.0);
            }
        } else if fitting_bins_count == 2 {
            score -= 2.0 + 3.0 * progress;
        }
    } else if fitting_bins_count == 0 {
        score -= 100.0;
    } else {
        if next > 0.0 && post + 0.5 >= next {
            score += 25.0 + 6.0 * item_frac + 0.20 * open_bins_count as f64;
        } else {
            score += 50.0 + 18.0 * item_frac + 0.70 * open_bins_count as f64 + 5.0 * progress;
            if next > 0.0 {
                score += 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small for typical items are wasted.
    let min_useful = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * (2.0 + 3.0 * progress);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot fit in the leftover space,
    // reward if it can (chain-fitting).
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= (next_item_size as f64) * 0.6;
        } else {
            score += (next_item_size as f64) * 0.4 * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 30.0 * fit_quality;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit signal),
    // scaled by how far this bin deviates from the mean residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Penalize scattering across many open bins; encourage filling existing bins
    // when the fleet of open bins is large relative to progress.
    let fleet_pressure = open_bins_count as f64 / (8.0 + 20.0 * progress);
    if bin_residual < bin_capacity {
        score -= fleet_pressure * 3.0;
    }

    // Mild attraction toward bins with below-average residual (nearly full bins).
    score += ((mean_residual - bin_residual as f64) * 0.15).max(-10.0).min(10.0);

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or no open bin is a decent fit; otherwise make it expensive.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 12.0 - 10.0 * big_item - 20.0 * desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Reward tight fits more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * progress;

    // Penalize post_residual that can't fit the next item (dead space)
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 12.0 * (nx - pr) / cap * (0.5 + 0.5 * progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Deviation from mean residual: prefer bins deviating positively (larger holes get filled)
    score -= 5.0 * (bin_residual as f64 - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Harmonic class logic: partition post_residual into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap / 4.0;

    // Dead-space penalty: residual in (0,10) is nearly unusable (items >= 1..100 but
    // practically small fragments waste the bin) — strongly penalize tiny residues.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-class coupling with next_item_size: perfect lookahead fit is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // exact fill: bin fully closed
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how much it consumes
            let fill_frac = next_item_size as f64 / post;
            score -= 40.0 * fill_frac;
            // penalize leaving another tiny dead space after hypothetical placement
            let post2 = post_residual - next_item_size;
            if post2 < 10 && post2 > 0 {
                score += 25.0;
            }
        } else {
            // next item cannot use this residual: penalize if residual is small
            if post_residual <= 30 {
                score += 30.0 * (1.0 - post / 30.0);
            }
        }
    } else {
        // last item: residual value is pure waste; minimize it hard
        score += post * 1.5;
    }

    // Integer-division thresholds on post_residual (harmonic bands).
    let band = post_residual / (bin_capacity / 8).max(1);
    score += band as f64 * 2.0; // larger bands slightly worse (waste scales)

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin has large post_residual; make it
    // attractive only when current residual is a bad class (very small or
    // poorly matched to next item).
    if bin_residual == bin_capacity {
        // fresh bin: post_residual == capacity - item_size; encourage when
        // item is large (good density) or stream is early.
        let density = item_size as f64 / cap;
        score -= 45.0 * density;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild bonus for bins below mean residual (consolidating emptier bins).
    if post < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score -= 1000.0; // perfect closure / unusable gap is great (nothing fits anyway)
    } else if post_residual < 20 {
        score += 60.0; // tiny gap: likely dead space, heavy penalty
    } else if post_residual < 30 {
        score += 25.0;
    } else if post_residual < 50 {
        score += 8.0;
    } else {
        // Large residual keeps future flexibility; mild reward scaled by fit quality
        score -= (post_residual as f64) * 0.15;
    }

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 2000.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0 + (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // blocks the natural next fit
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: penalize spreading across many bins; encourage consolidation
    // unless it creates dead space (handled above).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins first),
    // keeping loose bins available for big items.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (item is large relative to mean residual) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        if item_frac > mean_frac + 0.1 {
            score -= 90.0; // big item vs loose bins: fresh bin is fine
        } else {
            score += 150.0; // prefer consolidating into open bins
        }
        score += open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins where post_residual is tiny.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let second_post = post_residual - next_item_size;
            if second_post <= 5 {
                score -= 350.0;
            } else if second_post <= 15 {
                score -= 150.0;
            }
            // Small second leftover is good; large second leftover is mild waste
            score -= (30.0 - (second_post as f64).min(30.0)) * 0.5;
        } else {
            // Next item cannot fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets
    // for large items; bins looser than the mean should absorb small items.
    let residual = bin_residual as f64;
    let mean_gap = residual - mean_residual;
    if item_size > 50 {
        score += mean_gap * 0.3;
    } else {
        score -= mean_gap * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize new-bin candidate unless residual capacity is truly unusable
    // (i.e., this item would leave dead space no typical item can use).
    if bin_residual == bin_capacity {
        let waste = bin_residual - item_size;
        if waste > 0 && waste < 10 {
            score -= 250.0; // opening a bin that gets nearly filled is fine
        } else {
            score += 40.0 + (waste as f64) * 0.5;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Prefer denser bins (fewer open bins => tighter packing pressure)
    score -= (open_bins_count as f64).min(20.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear penalty.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap).powi(3) * 60.0;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Reward bins whose post_residual exactly (or nearly) accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap).max(0.0) * 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Many open bins: discourage spreading into half-empty bins, prefer best fit.
    score += open_bins_count as f64 * 0.05 * (pr / cap);

    // New-bin candidate handling: penalize opening a new bin unless the item is
    // large or nothing fits well.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / cap) > 0.6;
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) < next_item_size && next_item_size > 0);
        if !big_item && !poor_alternatives {
            score += 40.0;
        } else {
            score += 5.0;
        }
    }

    // Slight preference for leaving round usable residuals.
    if post_residual >= 10 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post residual with stream progress
    let poly = 1.0 + 0.6 * progress - 0.8 * progress * progress + 0.4 * progress * progress * progress;

    let mut score = pr * poly;

    // Penalize very small dead space asymmetrically as stream progresses
    let dead = if pr > 0.0 { (cap - pr) / cap } else { 1.0 };
    score -= 12.0 * dead * dead * (1.0 + progress);

    // Last-chance bonus: strongly favor this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        if fits {
            score -= 8.0 * (1.0 - (next_item_size as f64) / cap);
        } else {
            score += 4.0 * ((next_item_size as f64) - pr) / cap;
        }
    }

    // Mild preference toward consolidating residual mass when bins are many
    score += 0.05 * (open_bins_count as f64) * (norm_pr - mean_residual / cap).abs();

    // Slight bias against opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 6.0 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = if pr % 10 == 0 {
            0.0
        } else if pr % 5 == 0 {
            2.0
        } else if pr >= 10 && (pr % 20 == 10) {
            4.0
        } else {
            8.0
        };
        score += harmonic;

        // Dead-space penalty: leftover too small for the smallest item class.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // next item fits: mild reward scaled by how well it fills
            let fill = next_item_size as f64 / pr as f64;
            score -= 10.0 * fill;
        } else {
            // next item won't fit here: penalize small post residuals that
            // strand the next item
            let prog = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 * (1.0 - prog) * (1.0 - (pr as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin before opening a new one: reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full or the item is huge relative to the best residual.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0).min(1.0);
        let load = open_bins_count as f64;
        let prog = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * pressure + 0.5 * load - 10.0 * prog;
        if item_size >= 50 {
            score -= 15.0; // big items justify fresh bins
        }
    }

    // Mild preference for tighter bins overall.
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10 typical) can
    // use are waste. Penalize tiny gaps aggressively, with a hard spike below 10.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space: strongly penalize
    } else {
        // prefer larger usable residuals for future flexibility, mildly
        score += 0.05 * pr;
    }

    // Dead-space relative to capacity: fraction wasted
    score += 0.5 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 100.0;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (subtract to favor this bin) so we avoid spreading across too many bins.
    let open_pressure = open_bins_count as f64 / 10.0;
    if bin_residual != bin_capacity {
        score -= open_pressure * 3.0;
    } else {
        // New-bin candidate: penalize unless the current bin would leave a great fit
        score += open_pressure * 5.0;
        // Opening a new bin is OK if post_residual is 0 (perfect fit in fresh bin)
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 25.0;
        } else if nxt <= pr {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's tight;
    // favor placing here to consolidate.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.1;
    }

    // Late in the stream, be more conservative about opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
