}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 18.0 * (fit_ratio - 0.85);
    }

    // Penalize dead space: post_residual that is too small for typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 10.0 + 20.0 * (1.0 - progress);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 8.0 + 0.15 * (dead_threshold - post_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize slightly unless this is the only option.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Global state coupling: prefer filling bins when many are open.
    score -= 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with residual far from the mean (consolidation effect).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.03 * dev;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and no other bin is a last resort.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.4 && fitting_bins_count > 0;
        if bad_fit || next_item_size == 0 {
            score += 5.0; // still slightly discourage
        } else {
            score += 20.0; // discourage opening new bin when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post-residual with smooth non-linear shaping
    let mut score = post * (1.0 + 0.5 * post_norm * post_norm);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly
    let progress_coupling = post_norm * (1.0 - post_norm) * 4.0; // peaks at half-full bins
    score += progress * progress_coupling * cap * 0.35;

    // Smooth penalty for residual that no plausible future item fits
    let next_norm = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let unusable = ((post_norm - next_norm).max(0.0)) / (1.0 - next_norm.max(1e-6));
        score += unusable * unusable * cap * 0.6;
        // reward leaving room exactly for the next item (smooth bump)
        let fit_quality = 1.0 - ((post_norm - next_norm) / 0.25).powi(2);
        score -= fit_quality.max(0.0) * cap * 0.25;
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap * (0.4 + 0.3 * progress);
    }

    // Mild penalty for scattering across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins tighter than the mean residual (best-fit flavor, smooth)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize mildly early, more when a good fit exists elsewhere
    if bin_residual == bin_capacity {
        let base_new = cap * (0.9 - 0.4 * progress);
        score += base_new;
        if fitting_bins_count > 0 {
            score += cap * 0.3 * (1.0 - item_norm);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (likely dead space) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftover that no plausible item (>=1) can be trusted to fill.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Modulo-class logic: residues divisible by common item sizes (10, 20, 25, 50)
    // are more reusable; reward them.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 20 == 0 { score -= 4.0; }
        if r % 25 == 0 || r % 50 == 0 { score -= 5.0; }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= 15.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here; leftover becomes dead unless reusable.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish base; open a new bin only when the
    // stream is early or the item is large and existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 20.0 + 25.0 * (1.0 - progress);
        // Opening new bins is cheaper when item is large (poor fits likely).
        score = base - 10.0 * fill_ratio + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // large stream items: fresh bins useful
        }
    }

    // Slight preference for bins with residuals below the mean (consolidate
    // fragmentation into few bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a gap that the next item can still use (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (post_residual as f64 - next_item_size as f64).min(30.0);
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 25.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
        // But if the item is large and few bins fit it, allow opening a fresh bin.
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    } else {
        // Mild reward for filling an existing bin tightly.
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Coupling with mean residual: prefer bins tighter than the mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Perfect 2-step lookahead match: residual after placing equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Next item fits into the post residual: good chain, reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: dead space risk, penalize small leftovers.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Reward bins tighter than the mean residual (well-utilized bins).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: make it attractive only when it avoids a bad fit.
    if bin_residual == bin_capacity {
        // Prefer new bin when current item is large and would leave a big awkward residual,
        // or when next item is large and no good chain is possible.
        let bad_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if bad_fit || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10) {
            score -= 150.0;
        } else {
            score += 250.0; // otherwise discourage opening new bins.
        }
    }

    // Mild late-stream pressure to consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 50.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 80.0;
            // bonus proportional to how well next item fills leftover space
            let next_left = post_residual - next_item_size;
            score -= (10 - next_left.min(10)) as f64 * 6.0;
        } else {
            // leftover space after this placement is wasted w.r.t. lookahead
            score += 40.0;
        }
    } else {
        // Last item in stream: just minimize waste.
        score -= 50.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 30.0;

    // Time horizon: early on, be picky (penalize loose fits); late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.8;
    score -= progress * 60.0;

    // Global residual context: if mean residual is high, tight fits matter more.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= mean_gap * 0.5;
    } else {
        score += (-mean_gap) * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let best_open_hint = if fitting_bins_count == 0 { 500.0 } else { 0.0 };
        score += 120.0 - best_open_hint + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized quantities
    let post = post_residual as f64;
    let post_norm = post / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = item_size as f64 / cap;

    // Smooth non-linear coupling: dead space penalized more as stream progresses
    let dead_penalty = post_norm * post_norm * (0.5 + 2.0 * progress);
    score += 20.0 * dead_penalty;

    // Reward tight fits via cubic term on utilization
    let util = fit_norm;
    score -= 15.0 * util * util * util;

    // Interaction: progress * post_residual coupling (quartic decay of value of leftovers)
    let coupling = post_norm * post_norm * progress * (1.0 - progress);
    score += 30.0 * coupling;

    // Mean residual deviation: prefer bins near the mean (smooth quadratic)
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 25.0 * scarcity * scarcity;
    }

    // Lookahead: penalize if next item fits poorly into the post residual (smooth logistic-ish)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_next = if post >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (post - nxt).abs() / cap;
        score += fit_next * (10.0 * gap * gap) - 12.0 * fit_next * nxt;
        // Encourage leaving room compatible with next item
        score -= 6.0 * fit_next * nxt * (1.0 - post_norm);
    }

    // Bin-count pressure: mildly discourage proliferation of open bins late in stream
    let bin_pressure = (open_bins_count as f64).ln() / (cap);
    score += 5.0 * bin_pressure * (0.3 + progress);

    // Discourage opening a new bin when a good fit exists: add baseline offset for fresh bins
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - fit_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "residual band" we land in.
    // Classes of width 10 (capacity/10) — small classes are dead space.
    let class = post_residual / 10;
    match class {
        0 => score -= 45.0,          // perfect fit (0..=9 residual) — great
        1 => score -= 30.0,          // 10..19 still usable by min items
        2 => score += 4.0,           // 20..29 marginal
        3 => score += 10.0,          // 30..39 awkward
        4 => score += 18.0,          // 40..49
        5 => score += 25.0,          // 50..59 half-full
        _ => score += 34.0,          // 60.. mostly empty bin, wasteful use
    }

    // Modulo coupling: residual divisible by common item sizes is reusable.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 6.0 + (d as f64) * 0.1;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 40.0;
        } else if slack <= 15 {
            score -= 22.0;
        } else {
            score -= 8.0;
        }
        // Penalize if next item would be blocked (next > post_residual but
        // this bin could have held a bigger chunk of the stream).
        if next_item_size > post_residual && post_residual < 20 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish score for empty bin, but
    // discourage opening new bins when decent fits exist.
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64) * 1.5;
    } else {
        // Prefer fuller bins relative to mean residual of open bins.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += (bin_residual as f64 - mean_residual) * 0.25;
        }
    }

    // Stream progression: early on, be picky (waste tolerated); late,
    // squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalization of unusable dead space: gaps that no item (>=1) can use
    // are worst; gaps too small for typical items are heavily punished.
    if post_residual > 0 {
        let dead_ratio = if post_residual < 10 {
            1.0
        } else if post_residual < 20 {
            0.55
        } else {
            0.0
        };
        score += dead_ratio * 60.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += pressure * 8.0;
    } else {
        score -= pressure * 2.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item nearly fits (small overshoot), mild penalty for blocking it.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 10.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (below-mean
    // residual means this bin is already tight; fill it further).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact or near-exact
    // matches between the post-placement residual and the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect two-item completion: nearly close the bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: good, scale reward by tightness.
            let tightness = nxt / (post + 1.0);
            score -= 20.0 + 25.0 * tightness;
        } else {
            // Next item won't fit: penalize leftover dead space, more so
            // when the leftover is small (unusable sliver).
            let waste = (nxt - post) / bin_capacity as f64;
            score += 10.0 + 40.0 * (1.0 - waste);
        }
    }

    // Reward tight fits relative to the bin's own capacity.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Penalize creating residual far below the mean residual of open bins
    // (fragmentation relative to fleet state), unless it's a near-perfect fit.
    let post_f = post_residual as f64;
    if post_f < mean_residual * 0.5 && post_residual > 0 {
        score += (mean_residual - post_f) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive early
    // in the stream or when there are few open bins, but penalized when
    // the item would fit well in an existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        // Base cost of a new bin, discounted by stream progress and
        // by lack of alternatives.
        score += 55.0 * (1.0 - 0.5 * progress) - 30.0 * scarcity;
        // If the next item also pairs perfectly with this one in a fresh
        // bin, encourage opening it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_left = bin_capacity - item_size - next_item_size;
            score -= 25.0 - pair_left as f64 * 0.3;
        }
    }

    // Mild bonus for consolidating when many bins are open (bin-count pressure).
    score -= open_bins_count as f64 * 0.15 * (1.0 - post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post residual too small for next item: penalize proportionally.
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * crowding * (0.5 + progress);

    // Compare bin residual against global mean residual: prefer bins closer to mean
    // (balanced usage) early, and prefer larger-residual bins later.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 1.5 * dev * (1.0 - progress);

    // New-bin candidate: heavily penalize opening a new bin unless the item is large
    // relative to capacity and existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If item is huge (>= 70% of capacity), a fresh bin is actually reasonable.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
        // Late in the stream, opening new bins is less costly.
        score -= 15.0 * progress;
        // If mean residual across open bins cannot fit the item anyway, fresh bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Reward tight fits, more strongly late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        score -= 12.0 * fits_next * (1.0 - progress);
        // penalize post-residual that is too small for next item but nonzero
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 8.0 * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 10 classes of 10.
    let class = post_residual / 10;
    // Dead-space class penalty: residuals in awkward classes (1..3 -> 10..39)
    // are hard to fill with items >= 10, so penalize them extra.
    if class >= 1 && class <= 3 {
        score += 6.0 + 2.0 * (4 - class) as f64;
    }
    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 9 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item can exactly use the post residual,
    // this placement is a chain fit -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // Harmonic class of the double-fit leftover
            let lclass = leftover / 10;
            if lclass == 0 {
                score -= 12.0;
            } else if lclass >= 1 && lclass <= 3 {
                score += 4.0; // creates new dead space
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot use the leftover at all
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Modulo arithmetic on item size: items that are exact divisors of capacity
    // (10,20,25,50) tile well; pairing them into tight bins is valuable.
    if bin_capacity % item_size == 0 && post_residual < item_size {
        score -= 6.0;
    }

    // Prefer filling bins whose residual is below the mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Early stream: keep bins flexible, mild penalty for very tight fills
    // when many bins remain open anyway.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual < 10 && open_bins_count > 2 {
        score += 4.0;
    }

    // New-bin candidate: neutral-ish but slightly discouraged unless all
    // open bins would leave bad residuals. Empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        // An empty bin's "waste" is only worthwhile if best open-bin fit is poor.
        // Encourage reuse: make new bin moderately expensive, cheaper late in stream
        // when many near-full bins exist.
        score = score * 0.5 + 12.0 - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap threshold: smallest item that could arrive is 1..=100; treat gaps
    // below ~half of a typical small item as near-dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            // Nearly dead gap: strong penalty proportional to how close to zero.
            score += (10 - post_residual) as f64 * 4.0;
        } else if post_residual <= 30 {
            // Small gap: moderate penalty, scaled by stream progression.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (30 - post_residual) as f64 * (1.0 + 2.0 * progress);
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let last_chance_bonus = 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        score -= last_chance_bonus;
    }

    // Open-bin pressure: penalize creating many open bins; encourage filling
    // existing bins when open_bins_count is high.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += 0.35 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item would fit into the resulting post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward for near-exact next-item fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the gap: penalize leaving a gap that
            // blocks the lookahead item.
            score += 3.0;
        }
    }

    // New-bin candidate handling: make an empty bin mildly attractive only
    // when open bins are numerous and residuals are fragmented, otherwise
    // keep it unattractive so existing bins get filled.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if open_bins_count > 4 && fragmentation > 0.4 {
            score -= 5.0; // allow opening when bins are fragmented
        } else {
            score += 12.0; // discourage premature new bins
        }
    }

    // Mild progression-aware tightening: later in the stream, demand tighter
    // packing since future correction opportunities diminish.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this placement: mild reward proportional to slack left after both.
            let two_step_left = post_residual - next_item_size;
            score -= 15.0 - (two_step_left as f64).min(15.0);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space relative to next size.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize post residual.
        score += 5.0;
    }

    // Compare residual against mean residual across open bins: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin (only fitting bin): strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize very small unusable leftovers (< 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New empty bin candidate: penalize slightly so it's only chosen when open bins are bad,
    // but less penalty late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 12.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste inside the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for typical future items are worthless.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual > 50 {
        score += 8.0; // leaving a big hole is less valuable than a snug fit
    }

    // Lookahead: reward if the next item fits in the post residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 + next_item_size as f64 * 0.1;
        } else {
            // next item won't fit here; slight penalty proportional to leftover gap
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no open bin fits well (post_residual small) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 15.0 + open_pressure * 2.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits: must open new bin
        }
    }

    // Global balance: mildly prefer bins whose residual is near the mean
    // (keeps residual distribution homogeneous for future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream tightening: as stream progresses, favor fuller bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let base = pr * pr / cap; // quadratic dead-space penalty
    // smooth interaction: dead space matters more early (future items can fill it)
    let early = (1.0 - progress).powi(2);
    let mut score = base * (1.0 + 0.8 * early);
    // reward tight fits (small post_residual) with cubic shaping
    score -= (1.0 - pr / cap).powi(3) * 12.0;
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    // lookahead: if next item fits post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }
    // mildly prefer fuller bins vs mean residual
    score += 0.05 * (mean_residual - pr);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" classes (>= half capacity) are more reusable -> reward.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward post residuals in friendly harmonic classes.
    if post_residual >= half {
        score -= 18.0 * (post_residual as f64 / bin_capacity as f64);
    } else if post_residual >= quarter {
        score -= 6.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, close the bin
    } else {
        // Small dead space: penalize modulo class of dead space
        let dead = post_residual;
        let class = dead % 10;
        score += (10 - class) as f64 * 0.5; // dead space just below a decade boundary is worst
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 25.0 - 0.3 * slack as f64;
        // Harmonic bonus: next item leaves a class-aligned residual
        if slack % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize slightly if this bin was the only option
        if fitting_bins_count == 1 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when
    // open bins have poor fits. Scale its attractiveness with stream position
    // and mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * progress + 0.2 * mean_residual;
        // If the item is large relative to capacity, opening fresh is fine.
        if item_size > half {
            score -= 10.0;
        }
        // If many bins already open, discourage fragmentation.
        score += open_bins_count as f64 * 0.5;
    }

    // Tie-break: prefer tighter existing bins when residuals are close.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Harmonic class of item size itself: awkward sizes (non-multiples of 10)
    // benefit from bins with matching modulo residual.
    if item_size % 10 != 0 && post_residual % 10 == item_size % 10 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (below min item size 10)
    // are worthless -> heavily penalize them; zero leftover is perfect.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 80.0; // unusable dead space: worst outcome
    } else {
        // usable gap: mildly reward smaller gaps, but penalize gaps that
        // cannot accommodate the lookahead item (likely future dead space)
        score += (post_residual as f64) * 0.05;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap likely unusable for the next item
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0; // gap exactly fits the lookahead item
        }
    }

    // Reward tight fits (item occupies most of the bin's current residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: when many bins are open,
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (5.0 + 10.0 * progress);
    score += pressure;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mean residual coupling: bins with below-average residual are "well used";
    // favor them slightly to keep a clean set of large-residual bins.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item
    // is large (would leave little dead space) and existing fits are poor.
    if bin_residual == bin_capacity {
        let new_bin_dead = (bin_capacity - item_size) as f64;
        score = new_bin_dead * 1.2 + 40.0 - 20.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // large items pack better in fresh bins
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            // Perfect two-step chain: place here, next item fills this bin completely.
            score -= 40.0;
        } else if post_residual as f64 >= nxt {
            // Next item still fits: mild reward proportional to tightness.
            score -= (10.0 / diff).min(8.0);
        } else {
            // Dead space: post_residual too small for the next item.
            let dead = nxt - post_residual as f64;
            score += dead * 0.6;
        }
    }

    // Penalize tiny unusable residuals (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        // Perfect fill of this bin.
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New empty bin candidate: make it attractive only when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let base = 45.0 + (open_bins_count as f64).sqrt() * 2.0;
        // Attractive if item is large relative to capacity (few future pairing options).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score = base + large_item_bonus
            - if next_item_size > 0 && next_item_size.abs_diff(item_size) <= 5 { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_existing = mean_residual < item_size as f64 * 0.6;
        let mut new_bin_score = 25.0;
        if poor_existing {
            new_bin_score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        new_bin_score += 10.0 * (1.0 - progress);
        // If the next item could pair with this item in a fresh bin, encourage it.
        if next_item_size > 0 && (next_item_size + item_size) <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                new_bin_score -= 10.0;
            }
        }
        // Many open bins already: discourage proliferation.
        new_bin_score += (open_bins_count as f64) * 0.7;
        score = new_bin_score;
    }

    // Lookahead synergy: reward bins whose post-residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next < 10 {
            score -= 9.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Slight preference for bins with below-average residual (use up emptier bins first).
    if bin_residual != bin_capacity {
        score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 30.0 * norm_pr * norm_pr * norm_pr;

    // Stream-progress coupling: later in the stream, tighten fit preference more aggressively.
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += prog_coupling * (pr * 0.5 - item_size as f64 * 0.3);

    // Reward tight fits (near-zero post residual) increasingly over time.
    score -= (1.0 - norm_pr).powi(3) * (20.0 + 30.0 * progress);

    // Penalize dead space that can't fit typical future items (smooth via mean residual).
    if pr > 0.0 {
        let unusable = ((mean_residual - pr) / cap).abs();
        score += 15.0 * unusable * (pr / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item fits in post_residual.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        score -= fits_next * (15.0 + 10.0 * norm_pr);
        // Penalize leaving space that exactly blocks the next item slightly.
        let gap = (pr - next_item_size as f64).abs();
        score += 0.1 * gap * progress;
    }

    // Mild penalty for many open bins to encourage consolidation early.
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * norm_pr;

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score = pr + 60.0 * norm_pr - 35.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10.
    // Small post_residuals are dead space; reward near-full bins strongly.
    let pr = post_residual;
    let residue = pr % 10;
    if pr == 0 {
        score -= 500.0; // perfect fit
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 10 {
        score -= 60.0;
    } else if residue == 0 {
        score -= 15.0; // round residual, likely reusable
    } else {
        // penalize awkward odd residues
        score += (residue as f64) * 2.0;
    }

    // Integer-division threshold: residual in (0,10] is best, (10,20] ok, else worse.
    let class = pr / 10; // 0 = tiny, 1 = small, 2+ = large
    score += match class {
        0 => -40.0,
        1 => -10.0,
        2 => 5.0,
        _ => 15.0,
    };

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr && (pr - next_item_size) <= 5 {
            score -= 80.0;
        } else if next_item_size < pr && (pr - next_item_size) <= 10 {
            score -= 30.0;
        } else if next_item_size > pr {
            score += 20.0; // next item won't fit here anyway; dead space less costly
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // but keep it attractive when many open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 90.0 + 0.3 * (open_bins_count as f64);
    }

    // Progress: as stream advances, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 25.0 * (mean_residual / bin_capacity as f64).min(1.0);

    // Fragmentation penalty relative to mean residual.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress) * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., this item would create large dead space in every existing bin).
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (mean_residual - item_size as f64) < 8.0;
        if poor_fit_everywhere {
            score -= 30.0;
        } else {
            score += 40.0;
        }
    }

    // Lookahead: if next item can use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(10.0) * 0.8;
    }

    // Slight preference for bins with below-average residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits into leftover: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // Next item won't fit: leftover is likely dead space.
            score += 8.0;
        }
    }

    // Penalize unusable dead space below the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer tight fits relative to the mean residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (i.e., this is not a tight fit and no lookahead match exists).
    if bin_residual == bin_capacity {
        let tight = post_residual < 10;
        let lookahead_match = next_item_size > 0 && post_residual >= next_item_size;
        if tight || lookahead_match {
            score += 40.0; // keep using existing bins
        } else {
            score -= 5.0; // poor fit anywhere: new bin is reasonable
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 30.0;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to leftover.
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Time horizon: early in stream, be more conservative (favor filling existing bins);
    // later, allow opening new bins more freely by softening new-bin penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling: an empty bin gets post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced as stream progresses.
        let mut open_cost = 25.0 - 15.0 * progress;
        // If no existing bin fits, opening is necessary: remove cost.
        if fitting_bins_count == 0 {
            open_cost -= 100.0;
        }
        // Avoid proliferating bins when mean residual is already large.
        open_cost += mean_residual * 0.2;
        score += open_cost.max(-50.0);
    }

    // Prefer bins whose residual deviates from the mean in a "fillable" way:
    // bins with residual close to item_size are excellent targets.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.4;

    // Slight preference for bins with below-average residual (consolidate waste).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure against many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (x * x - x) * (0.5 + progress) + x * progress * (1.0 - progress) * 2.0;
    score += 20.0 * poly;

    // Tight fits are good, especially late in the stream
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin before opening a new bin gets rewarded
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when bin is far from the mean residual (imbalance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * (0.5 + progress);

    // Slight preference to keep many open bins from accumulating
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" residue classes (<= 10) are nearly dead space; penalize less
    // since they are effectively closed anyway.
    let residue_class = post_residual / 10; // 0..=10 integer division buckets
    match residue_class {
        0 => score -= 50.0,                    // tiny leftover, bin effectively full
        1 => score += 5.0,                     // 10..19: awkward dead zone
        2 => score += 15.0,                    // 20..29: worst dead zone
        3 => score += 10.0,
        4 | 5 => score += 3.0,                 // mid leftovers still usable
        _ => {}                                // large residual: fine
    }

    // Modulo-5 harmony: if next item exactly fills post_residual class
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // lookahead perfect fit: strong reward
        } else if next_item_size < post_residual {
            // next item fits here too: chain placement is good
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 120.0;
            } else {
                score -= (40.0 - gap as f64).max(0.0);
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is (modular distance on capacity fractions)
            let over = next_item_size - post_residual;
            score += (over as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual.
    // Only prefer opening a new bin when existing fit is terrible.
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin: mean residual of open bins
        // indicates how much space is being wasted currently
        score = 60.0 + mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 500.0; // never open new bin when a lone bin fits
        }
        if post_residual == 0 {
            score -= 1000.0; // item is full capacity edge case
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Prefer filling bins with low residual relative to fleet mean
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Tie-break: fewer open bins is better (compactness)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize gaps that cannot fit the lookahead item (dead space w.r.t. next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable_gap = next_item_size - post_residual;
        score += 8.0 + 0.5 * unusable_gap as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good existing fit exists.
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 15.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid opening a new bin.
        score -= 30.0;
    }

    // Mild preference for bins with residuals below the mean (consolidate emptier space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Prefer bins whose residual is close to item_size (best-fit flavor).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.4 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let n = next_item_size as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = pr;

    // Perfect single-item fill: overwhelmingly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: compare post_residual against next_item_size.
    if n > 0.0 {
        if pr >= n {
            // Next item also fits here: score by the combined two-item leftover,
            // with an extra reward proportional to the hosted next item.
            score += (pr - n) * 0.6 - n * 0.25;
            // Exact two-item match: current item + next item fill the bin perfectly.
            if pr == n {
                score -= 300.0;
            }
        } else {
            // Dead gap the next item cannot use. Penalize harder as the stream
            // progresses (less future opportunity to reuse fragments).
            let k = 0.5 + 0.7 * progress;
            score += (n - pr) * k;
        }
    }

    if is_new_bin {
        // Brand-new empty bin candidate: base cost of consuming an extra bin,
        // softened when existing open bins are nearly full (mean_residual low),
        // strengthened when open bins still have plenty of room.
        score += 10.0 + 35.0 * (mean_residual / cap).clamp(0.0, 1.0);
        if fitting_bins_count == 0 {
            // No open bin can host the item: opening a new bin is natural.
            score -= 25.0;
        } else {
            // Deterrent grows with the number of viable existing alternatives.
            score += 8.0 * fitting_bins_count as f64;
        }
    } else {
        // Mean-residual coupling: filling tighter than the fleet average is good,
        // leaving more dead space than average is mildly bad.
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.35;
        } else {
            score += (pr - mean_residual) * 0.15;
        }
        // Last-chance bin: strongly prefer using the only bin that fits
        // instead of opening a new one.
        if fitting_bins_count == 1 {
            score -= 180.0;
        }
        // Small reuse bonus so existing bins win ties against a new bin.
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness bonus: the smaller the leftover, the better.
        score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    }

    // Penalize leaving residuals that are too small to be useful later
    // (items are 1..=100; residual < ~10 is nearly dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how much the next item would consume
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }
    // Many fitting bins: mild penalty to keep diversity of bin fill levels.
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: opening new bins is costly when many bins are already open
    // with slack; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        let slack_ratio = mean_residual / bin_capacity as f64;
        score += 150.0 + 100.0 * slack_ratio + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (need bins to exist).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
        // If item is large relative to capacity, new bin is more acceptable.
        score -= 40.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Reward placing into bins that are already below mean residual
        // (balance fill levels across open bins).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.3 * dev;
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: waste grows super-linearly with post_residual (dead space penalty).
    let x = pr / cap;
    let mut score = x * x * (1.0 + 0.5 * x) * cap;

    // Smooth stream-progress coupling: late in the stream, tight fits matter more.
    let tightness = 1.0 - x; // fraction of bin used by this placement
    score -= 6.0 * tightness * (1.0 + progress * progress * 3.0);

    // Penalize residual that no plausible next item can use (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        score += 4.0 * gap_norm * gap_norm * cap * (0.5 + 0.5 * progress);
        // Reward bins whose post_residual exactly accommodates the next item.
        score -= 5.0 * (-gap_norm * 20.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: prefer opening a new bin early, or when existing fit is bad.
    if is_new_bin {
        let open_cost = 8.0 + 4.0 * (1.0 - progress);
        let fit_quality = 1.0 - (item_size as f64 / cap);
        // Open new bin if item is large relative to mean residual (poor fits elsewhere).
        let poor_elsewhere = ((mean_residual - item_size as f64) / cap).max(0.0);
        score = open_cost + 30.0 * fit_quality * (1.0 - poor_elsewhere.min(1.0)) - 20.0 * poor_elsewhere;
        // Late in stream, avoid proliferating bins.
        score += 10.0 * progress * (open_bins_count as f64).sqrt() / 4.0;
    } else {
        // Mild reward for balancing residuals toward the mean.
        score += 1.5 * ((pr - mean_residual) / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by residue mod 10.
    let pr = post_residual;
    let residue = (pr % 10) as f64;

    // Penalize leftovers that are "dead" — small non-zero residues that few
    // future items (1..100 unknown distribution) can use efficiently.
    if pr > 0 {
        if pr < 10 {
            score += 40.0; // unusable sliver
        } else {
            // residue 0 (multiple of 10) is most reusable; larger residue = worse
            score += residue * 1.5;
        }
    } else {
        score -= 60.0; // perfect fill
    }

    // Integer-division thresholds: leftover in [10, 30] is a "harmonic pocket"
    // that mid-size items can still fill; reward moderately.
    if pr >= 10 && pr <= 30 {
        score -= 25.0;
    }
    // Leftovers in (30, 60] are flexible; slight reward.
    if pr > 30 && pr <= 60 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let nr = pr - next_item_size;
            score -= 20.0 - (nr % 10) as f64; // reward good two-step packing
        } else {
            score += 12.0; // next item won't reuse this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is fine when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; worth it if existing bins fit poorly.
        score = bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // large next item benefits from fresh bin
        }
    }

    // Late-stream consolidation: prefer tightening packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * progress;
    score -= progress * 10.0 * (pr % 5 == 0) as i32 as f64;

    // Mild preference to spread across bins when many are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: strict dead-space avoidance. Small post_residual gaps are unusable.
    let mut score = post;

    // Harsh penalty for "dead space": residuals too small for the smallest item (1..100 range).
    // Treat residuals below a threshold band as wasted; scale penalty by how deep in the dead zone.
    let dead_threshold = 12.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - (post / cap);
    score -= tightness * 25.0;

    // Exact fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 20.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving a mid-range gap that traps it.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: more open bins -> favor consolidating into existing bins.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate (empty bin): penalize unless it enables a near-perfect packing.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If item is large, new bin leaves a useful residual; discount slightly.
        if item > 50.0 {
            score -= 15.0;
        }
        // If no existing bin fits well (this is the only fitting option), opening is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild tie-breaker: prefer bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item fits: reward tight coupling.
            score -= 20.0 * (1.0 - diff / 100.0);
            if diff <= 2.0 {
                score -= 15.0; // perfect 2-step chain
            }
        } else {
            // Next item won't fit here; mildly penalize wasted potential.
            score += 5.0 + 0.1 * diff;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: baseline so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + 20.0;
        if next_item_size > 0 && (next_item_size as i64 - bin_capacity as i64).abs() <= 5 {
            score -= 30.0; // next item is huge, fresh bin attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving residuals that are awkward for typical future items:
    // residuals in (0, 15) are near-dead space.
    if post_residual > 0 && post_residual < 15 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slightly penalize wasting space on it
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Many fitting bins: prefer the emptiest-ish choice to consolidate.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early,
    // acceptable late or when open bins are nearly full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let urgency = (mean_tightness * 1.5 + progress * 0.5).clamp(0.0, 2.0);
        score += 15.0 + 35.0 * (1.0 - urgency.min(1.0));
        // If no open bin fits at all, allow the new bin more readily.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference to fill bins with larger residuals when few bins open.
    score += (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Slight time-varying exploration term (deterministic).
    let phase = ((step_index as f64) * 0.05).sin();
    score += 2.0 * phase * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual squared normalized, weighted by stream progress.
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= 6.0 * (-norm_pr * 6.0).exp() * (0.4 + 0.6 * progress);

    // Dead-space penalty: post_residual that cannot fit the next item is wasted,
    // smoothly coupled with lookahead size and progress.
    if nxt > 0.0 {
        let wasted = (nxt - pr).max(0.0) / cap;
        score += 10.0 * wasted * wasted * (0.5 + progress);
        // Reward bins whose post_residual still accommodates the next item.
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 3.0 * (fits_next * 5.0).exp().min(1.0);
    }

    // Penalize deviation from mean residual: keep bin pool balanced (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize mildly when good fits exist, more so early on;
    // allow opening new bins when existing bins would create large dead space.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 5.0 * pressure * (0.6 + 0.4 * progress);
        if nxt > 0.0 && pr >= nxt {
            score -= 4.0;
        }
    }

    // Slight penalty for very large items in nearly full bins creating tiny leftovers
    // that are hard to use (smooth cubic in normalized residual).
    score += 2.0 * norm_pr.powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-10 buckets) ---
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: small unusable residuals (< next item or < min item 10)
    let min_item = 10.0f64;
    let usable = if next_item_size > 0 {
        pr >= next_item_size
    } else {
        pr >= min_item as u32
    };
    if !usable && pr > 0 {
        score += 25.0 + prf * 0.5; // wasted space that no item can use
    }

    // Perfect / near-perfect fits strongly rewarded
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Harmonic residue classes: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more likely reusable later.
    let harmonic_bonus: f64 = if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Fractional capacity coupling: reward leaving residual near simple
    // capacity fractions (1/4, 1/2, 3/4 of C)
    for frac in [0.25f64, 0.5, 0.75] {
        let target = cap * frac;
        let d = (prf - target).abs();
        if d <= 5.0 {
            score -= 8.0 * (1.0 - d / 5.0);
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // harmonic class of the gap left after the next item too
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 6.0;
            }
            score -= 4.0 * (gap as f64 / cap);
        } else {
            // next item won't fit here; mildly penalize locking this bin
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish score anchored on mean residual
    // so it wins only when all open bins would create heavy dead space.
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64) * 0.5 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can host the next item too
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - prf / cap);

    // Prefer bins below mean residual (denser bins) slightly
    score += 0.1 * (mean_residual - prf).max(0.0) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap below the minimum item size (1..100 unknown, use conservative 10)
    // is pure waste; scale penalty nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits: post_residual small relative to bin capacity.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral base, slightly favored early in stream,
    // penalized later so we consolidate into existing bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * 0.5 + 20.0 * progress;

        // If next item is large and this item leaves a bad gap, opening a new
        // bin is attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
        // If only one bin fits and it's a decent fit, disfavor new bin.
        if fitting_bins_count >= 1 && post_residual <= 15 {
            score += 35.0;
        }
    }

    // Lookahead: prefer leaving gaps that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // (keep uniform residuals for future flexibility).
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack (<= 5).
    else if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) <= 5 {
        score -= 30.0 - (post_residual - next_item_size) as f64 * 4.0;
    }
    // Next item does NOT fit after placement: penalize dead space relative to mean residual.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize unusable dead space: tiny post_residual that no item (min size 1..10) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: only open bin that fits -> strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Reward bins tighter than the mean residual (good packing density).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin, more so early and when good fits exist.
    if bin_residual == bin_capacity {
        let mut penalty = 45.0;
        if fitting_bins_count > 0 {
            penalty += 20.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Late in the stream, reusing bins is even more valuable.
        penalty += 20.0 * progress;
        // If many open bins, prefer consolidating into them.
        penalty += (open_bins_count as f64).min(10.0) * 2.0;
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: quadratic penalty on wasted space
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can host the next item (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // penalize residual that is too small for next item (likely dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
        // exact pairing bonus
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are terrible
    if bin_residual == bin_capacity {
        // opening a new bin costs ~1 bin; only attractive if best existing waste is large
        let crowding = open_bins_count as f64;
        score = bin_capacity as f64 - 0.5 * waste;
        // early in stream, opening bins is cheap/normal
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // many open bins with slack: discourage yet another bin
        score += 0.3 * crowding;
        // if mean residual across bins can't host future items, new bin more attractive
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (good consolidation)
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.4 * diff;
    }

    // Late stream: penalize leaving large residuals (little time to fill them)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (waste), with non-linear polynomial coupling to progress
    let mut score = pr;

    // Quadratic/cubic coupling: waste becomes more costly as stream progresses
    let prn = pr / c;
    let poly = prn * prn * (1.0 + 2.0 * progress) + prn * prn * prn * (3.0 * progress);
    score += 60.0 * poly;

    // Reward tight fits (small post_residual) more strongly early-to-mid stream
    score -= 25.0 * (1.0 - prn).powf(2.0 + 2.0 * progress);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / c;
    score += 10.0 * dev * dev;

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / c);
        score -= 15.0 * snug;
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / c) * (1.0 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * prn;

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * (1.0 - item / c);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let pr = post_residual;
    let cls = pr / 10; // integer division threshold class 0..10
    let class_penalty = match cls {
        0 => -30.0,               // perfect fit
        1 => -12.0,               // nearly full
        2 => -4.0,
        3 => 2.0,
        4 => 8.0,                 // awkward gap ~40
        5 => 10.0,                // worst: half-full dead zone
        6 => 8.0,
        7 => 3.0,
        8 => -2.0,
        9 => -6.0,
        _ => -10.0,               // empty bin class
    };
    score += class_penalty;

    // Modulo-arithmetic bonus: residual divisible into common item sizes
    let modulo_bonus: f64 = if pr == 0 { 0.0 } else {
        let mut b = 0.0;
        for s in [10u32, 20, 25, 30, 40, 50, 80] {
            if pr % s == 0 { b -= 6.0; }
        }
        b
    };
    score += modulo_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // fraction of next item absorbed
            let frac = next_item_size as f64 / pr.max(1) as f64;
            score -= 12.0 * frac;
            // penalize leaving residual in awkward class for next item
            let nxt_gap = pr - next_item_size;
            if nxt_gap > 0 && nxt_gap < 10 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (mean_residual / cap).max(0.01);
        let poor_fit_everywhere = fitting_bins_count == 0;
        if poor_fit_everywhere || (mean_residual < 15.0 && open_bins_count > 2) {
            score -= 25.0 + 10.0 * progress;
        } else {
            score += 20.0 + crowded.min(50.0);
        }
    }

    // Mild tightness coupling with mean residual: prefer bins below mean residual (fuller bins)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are unusable dead space -> heavy penalty; larger residuals are reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Penalize residuals that cannot fit the next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64;
    }
    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when pressure is high, but allow new bins early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's
    // a "junk" bin; prefer dumping items there to consolidate.
    let res = bin_residual as f64;
    if res < mean_residual - 15.0 {
        score -= 10.0;
    } else if res > mean_residual + 15.0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large dead-space risk) or bin count pressure is low.
    if bin_residual == bin_capacity {
        let bad_fit_risk = if post_residual > 0 && post_residual < 10 { 0.0 } else { 0.0 };
        let _ = bad_fit_risk;
        score += 55.0 + 3.0 * open_bins_count as f64 - 40.0 * (1.0 - progress);
        // If next item is huge, opening fresh bin is safer.
        if next_item_size >= 70 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: lower score for small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // 2-step lookahead: reward if post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
        // Chain fit: current + next exactly consumed is excellent.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if it beats poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin when alternatives exist,
            // unless the item is large and fits are very loose.
            let best_loose = if post_residual as f64 > mean_residual { 1.0 } else { 0.0 };
            score += 45.0 - 20.0 * best_loose * (item_size as f64 / 100.0);
        } else {
            score -= 5.0;
        }
    }

    // Slight preference for bins with residual near mean (balanced usage).
    score += 0.08 * ((bin_residual as f64 - mean_residual).abs());

    // Late stream: prefer filling existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize the fit quality into [0,1] and subtract.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to ever hold a meaningful item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = post_residual - next_item_size;
        score -= 20.0 + 10.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Partial lookahead credit: next item partially covered.
        let cover = (post_residual as f64 / next_item_size as f64).min(1.0);
        score += 5.0 * (1.0 - cover);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to encourage consolidation elsewhere.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (many scattered bins); prefer new bins when open bins are already tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
        score += 3.0 * progress * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when the item is large
    // (poor fit candidates elsewhere) or no good reason to reuse bins.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 40.0;
        score -= large_item_bonus;
        // Penalize opening bins early in the stream; allow more later.
        score += 15.0 * (1.0 - progress);
        // If the item would leave a large awkward residual anyway, a fresh bin is fine.
        if post_residual >= item_size {
            score -= 5.0;
        }
        // If this is the only fitting option, new bin is naturally competitive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: residual normalized, squared and cubic terms
    let x = pr / cap;
    score += 8.0 * x * x * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - x) * (1.0 - x) * (0.3 + progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize spreading when many bins are open relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // Penalize opening a new bin mildly, stronger early
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 partition dead space
    // into "harmonic" classes. Residues near multiples of 10 are more likely
    // to be filled by typical item sizes, so reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fill_frac = 1.0 - (post_residual as f64) / cap; // how full the bin becomes

    // Reward high fill fraction (quadratic coupling).
    score -= 60.0 * fill_frac * fill_frac;

    // Harmonic class reward: post_residual mod 10 == 0 is ideal (perfect packing),
    // small residues are good, large odd residues are dead space.
    let residue_class = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 100.0; // perfect fit, huge reward
    } else if residue_class == 0.0 {
        score -= 25.0;  // multiple of 10: very reusable
    } else if residue_class <= 3.0 {
        score -= 10.0;  // small residue: likely fillable
    } else if residue_class >= 7.0 {
        score += 8.0;   // awkward large-ish residue
    }

    // Integer-division threshold on post_residual: chunk it into bands of 10.
    let band = post_residual / 10;
    score += (band as f64) * 1.5; // prefer bins whose leftover falls into low bands

    // Lookahead coupling: if the next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportionally to how well it fills
            let nf = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 30.0 * nf;
        } else {
            // next item cannot use this residue: penalize awkward leftovers
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or all residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let item_frac = (item_size as f64) / cap;
        // Base cost of a fresh bin; discounted for large items.
        score += 55.0 - 40.0 * item_frac;
        // If existing bins are fragmented (high mean residual vs item), new bin is fine.
        if mean_residual > 2.0 * (item_size as f64) {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper (more items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for tighter bins overall (small bin_residual before placement).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with residual already below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mild progression term: later in stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // New-bin candidate: make it moderately attractive only when item is large
    // relative to residuals (avoids wasting open space on small items).
    if bin_residual == bin_capacity {
        let wasted = mean_residual * (open_bins_count as f64);
        if (item_size as f64) < wasted * 0.35 {
            score += 30.0;
        } else {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is exponentially bad).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64).powi(3) / (cap * cap);
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 300.0 - chain_waste * 1.5;
        } else {
            // next item cannot follow here: penalize more if it leaves large gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Relative to mean residual: prefer filling bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 0 && post_residual < 20);
        if poor_fit_elsewhere {
            score -= 120.0;
        } else {
            score += 400.0 + open_bins_count as f64 * 10.0;
        }
    }

    // Late in stream: consolidate harder, discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits in the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // exact chain
        } else if next_item_size < post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a residual that is too small to be useful.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0 * (10.0 - dead);
            }
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when good fits exist
    // or when many bins are already open (amortize existing capacity).
    if bin_residual == bin_capacity {
        score += 50.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in the stream, opening bins is cheaper (build diversity of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is near the mean residual (keeps bin profile homogeneous,
    // making future items likely to fit several bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild preference for bins with larger residual when item is small (avoid wasting big gaps).
    if (item_size as f64) < 0.5 * bin_residual as f64 {
        score += 5.0;
    }

    // Slight penalty per open bin to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth coupling of post_residual with stream progress:
    // early on, prefer tight fills less strongly; late, squeeze bins harder.
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Reward near-perfect fits smoothly (small post_residual gets extra discount)
    let fit_quality = (cap - post) / cap;
    score -= 8.0 * fit_quality * fit_quality * fit_quality;

    // Penalize bins whose residual deviates from mean residual (spread control),
    // coupled non-linearly with progress
    let dev = post - mean_residual;
    score += (0.5 + 2.0 * progress) * dev * dev / cap;

    // Last-chance bin: strongly reward using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: reward leaving room for next item, smooth interaction
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let room = post / nxt.max(1.0);
        score -= 4.0 * (1.0 / (1.0 + room * room)) * (1.0 - progress);
        // penalize if post residual is just barely enough (creates awkward fit)
        let margin = (post - nxt) / cap;
        if margin >= 0.0 && margin < 0.1 {
            score += 2.0 * (1.0 - margin / 0.1);
        }
    }

    // Mildly penalize spreading across many open bins, smooth in count
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - fit_quality);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong reward for tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // Harmonic class of post_residual: classify leftover space into modulo buckets.
    // Residuals in {0} perfect, {1..9} great, {10..19} good, {20..39} ok, else poor.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -50.0
    } else if pr <= 9 {
        -20.0
    } else if pr <= 19 {
        -8.0
    } else if pr <= 39 {
        5.0
    } else {
        15.0
    };
    score += class_penalty;

    // Modulo arithmetic: leftover divisible by small harmonics (5, 10) is more reusable
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Odd residuals slightly penalized (less likely to pair with future items)
        if pr % 2 == 1 {
            score += 2.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it fills
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty scaled by overflow gap
            score += ((next_item_size - pr) as f64).min(30.0) * 0.3;
        }
    }

    // Integer division threshold on bin_residual: bins with residual near capacity
    // are "fresh"; avoid wasting them on tiny items
    let q = bin_residual / 25; // quarter-of-capacity classes: 0..4
    if item_size <= 20 && q >= 3 {
        score += 12.0; // don't put tiny items in nearly-empty bins
    }
    if item_size >= 60 && q <= 1 {
        score -= 5.0; // big items prefer the tightest bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0
            - 10.0 * (mean_residual / bin_capacity as f64)
            - 15.0 * progress
            + (open_bins_count as f64).min(10.0);
        // If item is large and mean residual is low, opening new bin is fine
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: prefer bins below mean residual (fill the fullest bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (10.0 - post_residual as f64) / 9.0;
    }
    // Medium gaps (10..30) are mildly penalized relative to their size.
    if post_residual >= 10 && post_residual < 30 {
        score += 0.35 * (30.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Coupling with mean residual: bins far below mean residual are worse
    // candidates (their space is more reusable); prefer bins close to mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.12 * dev;

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fits.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave a large usable residual AND no good existing fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; grows with number of open bins.
        let mut new_score = 55.0 + 1.2 * open_bins_count as f64;
        // If the item leaves a residual that could fit the next item, discount.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score -= 18.0;
        }
        // Late in the stream, prefer closing bins out; opening new bins is costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_score += 25.0 * progress;
        // If other fitting bins exist, new bin must beat them clearly.
        if fitting_bins_count >= 1 {
            new_score += 10.0;
        }
        score = new_score + score * 0.0; // new-bin score is standalone
    }

    // Lookahead: if this placement leaves exactly room for the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base cost: leftover space after placement (waste).
    let mut score = post_residual as f64;

    // Strongly reward an exact 2-step match: post_residual == next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: huge bonus; near match: scaled bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 10.0 {
            score -= 40.0 - 2.0 * diff;
        } else {
            // Penalize residuals that neither fit nor match the next item well
            score += 0.15 * diff;
        }
    } else {
        // Last item: only tightness matters
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual to mean residual across open bins:
    // leaving a residual well below mean is efficient (bin nearly full).
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let rel = post_residual as f64 - mr;
    score += 0.25 * rel;

    // Penalize tiny unusable dead space (< 10) unless it was an exact next-item match.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 15.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // Late in the stream, prefer tightening existing bins further.
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: heavily penalized so it's chosen only when
    // no open bin offers a decent fit (e.g., all fits would waste a lot).
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * item_size as f64;
        // Allow new bin early if item is huge and no open bin fits well.
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that nothing can use later (min item size 1).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 8.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_pair = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack_after_pair as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // this bin likely becomes dead after placement
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let mean_tightness = mean_residual / bin_capacity as f64;
        // Opening a bin is fine early on or when open bins are very full.
        let pressure = 1.0 - mean_tightness;
        score = 30.0 + 20.0 * pressure - (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        // If several bins already fit, discourage spreading.
        if fitting_bins_count >= 1 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Perfect-fit alternative exists? then never open new bin.
        if post_residual == 0 {
            score += 100.0;
        }
    }

    // Mild preference to balance load across bins when many are open.
    score -= 0.05 * open_bins_count as f64 * (1.0 - tightness);

    // Slight time decay: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward tight fits with a non-linear (quadratic + cubic) coupling
    let mut score = post * (1.0 + 0.5 * norm_post) - 12.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Smooth stream-progress coupling: late in the stream, tighten more aggressively
    score -= 8.0 * progress * (1.0 - norm_post) * (1.0 - norm_post);

    // Dead-space penalty: residuals too small for any plausible item are wasted
    let dead = if post < 10.0 { 1.0 - post / 10.0 } else { 0.0 };
    score += 15.0 * dead * dead;

    // Lookahead: bonus if the next item fits the post-residual (smooth kernel)
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let tightness = 1.0 - (post - next_item_size as f64) / cap;
        score -= 10.0 * tightness * tightness;
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - post) / cap;
        score += 6.0 * gap * gap;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a bin unless existing residuals are poor
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 30.0 + 25.0 * (1.0 - progress) - 6.0 * (mean_residual / cap).ln().max(0.0);
    }

    // Slight preference for bins below mean residual (consolidation)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are ideal
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Class by capacity fractions: residual <= 10 is near-perfect
        if post_residual <= 10 {
            score -= 200.0;
        } else if post_residual <= 20 {
            score -= 80.0;
        } else if post_residual <= 30 {
            score -= 30.0;
        }
        // Modulo arithmetic: residuals divisible by common item sizes are reusable
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                score -= 15.0;
            }
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // Harmonic threshold: gap small enough to be useful
            if gap <= 10 {
                score -= 60.0;
            } else if gap <= 25 {
                score -= 20.0;
            } else {
                // next item cannot use much of the residual: penalize wasted space
                score += gap as f64 * 0.3;
            }
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current open bins have poor fit (item barely fits or lots of dead space)
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted when many bins already open
        score = 100.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 1000.0; // no alternative, must open
        }
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 30.0;
        }
    } else {
        // Prefer tighter existing fits: reward small waste relative to item
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * 40.0;
        // Prefer bins whose residual is close to the mean (balance load)
        score += (mean_residual - post_residual as f64).abs() * 0.2;
    }

    // Late in the stream, consolidate harder to avoid leftover bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 500.0 * (dead_threshold - post_residual as f64);
    }

    // Reward residuals that can still host future items (mid-size gaps are useful).
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 40.0;
    } else if post_residual > 0 && next_item_size > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins would create dead space.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 * 5.0;
        score += 80.0 + open_pressure;
        if post_residual < dead_threshold {
            score -= 300.0; // opening a fresh bin avoids dead space entirely
        }
    }

    // Prefer tighter fits: relative fill ratio discount.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fill_ratio;

    // Divergence from mean residual: bins far below mean are more valuable to fill.
    score -= 0.3 * (mean_residual - bin_residual as f64).abs();

    // Early-stream exploration: slightly favor compacting early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward when the next item also fits in this bin after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Penalize dead space that neither current nor next item can use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // penalizing outliers that create fragmented leftovers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Tight fits are good: small post_residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and would leave a very fragmented fit elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Slight preference for keeping bin count low early in the stream.
    score += open_bins_count as f64 * 0.05 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Penalize residual that is too small to hold any plausible future item
    // (dead space below the minimum item size is pure waste).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            score -= 12.0 * (nx / pr).max(0.5);
        } else if nx - pr < 10.0 {
            score += 15.0 * (nx - pr); // near-miss wasted capacity
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score -= 10.0; // weak alternative exists; slight preference to use it
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins whose residual is far above the mean (consolidate space).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more aggressive about using open bins (avoid
    // leaving many half-empty bins at the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Slight penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 12.0
                 - norm_pr * progress * 6.0
                 + norm_pr * norm_pr * norm_pr * progress * 10.0;
    score += coupling * cap * 0.25;
    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 8.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack) * (1.0 - slack) * 6.0;
        } else {
            score += (nx - pr) * 0.15 * (0.5 + progress);
        }
    }
    // penalize divergence from mean residual (smooth quadratic)
    score += (pr - mean_residual) * (pr - mean_residual) * 0.02;
    // mild penalty for many open bins
    score += open_bins_count as f64 * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that land in "useful" classes.
    // Residuals that are small multiples of common item sizes (or near 0) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // class by integer division: dead-space buckets
        let class = pr / 10;
        score += (class as f64) * 3.5; // finer penalty as dead space grows in 10s
        // modulo-harmonic bonus: residuals divisible by 5 or 10 pair well with typical sizes
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // harsh penalty for awkward tiny residuals (3..9) that rarely fit anything
        if pr < 10 {
            score += 25.0;
        }
    }

    // Tightness reward: item fills a large fraction of the bin
    let fill = item_size as f64 / cap;
    score -= fill * 30.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_class = (pr - next_item_size) / 10;
            score -= 15.0 - (nxt_class as f64) * 4.0; // closer fit of next item => better
        } else {
            // next item cannot fit here: penalize more if residual is large (wasted)
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline so it only wins when
    // open bins fit poorly.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (mean_residual - post_residual as f64).abs() * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).recip() * 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item (items >= 1, but small gaps < ~10 are near-worthless)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness * tightness;

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open bins,
    // opening a new bin is cheaper, so mildly prefer tight fits elsewhere.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 2.0 * (1.0 - progress);

    // Lookahead: if next item fits in the post_residual, reward leaving that gap;
    // if next item would not fit even now, this bin is less attractive for chaining.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual < next_item_size && bin_residual != bin_capacity {
            score += 5.0;
        }
    }

    // New-bin candidate: give it a moderate default score so it wins only when
    // all open bins are poor fits (their dead-space penalties push them above this).
    if bin_residual == bin_capacity {
        score = 55.0 + pressure * 3.0 - 10.0 * (1.0 - progress);
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier future packing).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match between leftover and next item is highly desirable
        score -= 12.0 * (1.0 - lookahead_gap / (bin_capacity as f64)) * (lookahead_gap / 20.0).exp();

        // Perfect two-item closure: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Pair fills the bin completely
        if post_residual < next_item_size && post_residual <= 5 {
            score -= 10.0; // near-perfect single-item fit, tiny dead space
        }
    } else {
        // Last item: minimize dead space strongly
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Penalize large dead space non-linearly (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no good fit exists
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; slightly penalized so good fits win
        score += 6.0;
        // But if open bins are all loose (high mean residual), a new bin keeps them clean
        if mean_residual > 40.0 && next_item_size > 0 {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to bin.
    let fit_ratio = post_residual as f64 / cap;
    score -= 0.6 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * cap;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Lookahead: reward if next item fits perfectly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            // Next item cannot use leftover; penalize dead space proportionally.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.25 * dead;
            }
        }
    }

    // Penalize creating very small unusable slivers (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin for an item that barely fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let mean_fullness = 1.0 - (mean_residual / cap);
        // Opening a new bin is penalized when many bins are open and still roomy.
        score += 12.0 + 8.0 * crowd * (1.0 - mean_fullness);
        // But reward opening a fresh bin late in the stream or when existing
        // residuals are small (poor fit prospects).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * mean_fullness + 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate into crowded bins when many are open.
    score += 0.02 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows quadratically with
    // normalized residual, modulated by stream progress.
    score += 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Interaction with mean residual: prefer bins whose residual deviates
    // favorably from the mean (using this bin avoids fragmenting mean space).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 25.0 * dev * dev - 15.0 * dev * (0.5 + progress);

    // Lookahead coupling: bonus if the next item fits the post-residual,
    // penalize if post-residual is a "dead zone" (too small for next item).
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size as f64;
        if fits_next {
            score -= 20.0 * (1.0 - pr / (next_item_size as f64 + 1.0)) * (0.3 + 0.7 * progress);
        } else {
            score += 18.0 * (1.0 - pr / cap) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mild penalty for opening new bins when many are open and progress is high.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Cubic smoothing term for fine-grained residual ordering.
    score += 10.0 * norm_pr * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "usable" for
    // common small-item classes get a discount; dead-space residues get penalized.
    let pr = post_residual;
    let mut dead = 0.0;
    if pr > 0 {
        // classes: divisible by 10 (nice), 5, or very small (dead)
        if pr % 10 == 0 {
            dead -= 12.0;
        } else if pr % 5 == 0 {
            dead -= 6.0;
        }
        if pr < 10 {
            dead += 18.0; // unusable sliver
        } else if pr <= 20 {
            dead -= 4.0; // fits a small item likely
        }
        // integer-division threshold: residue in [25,50] is a sweet spot
        if pr / 25 == 1 && pr < 50 {
            dead -= 8.0;
        }
        if pr > 60 {
            dead += 3.0; // large residue means loose fit, fine but not great
        }
    }
    score += dead;

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this residue: mild penalty scaled by overflow
            let over = (next_item_size - pr) as f64;
            score += 0.15 * over.min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless current fit is terrible.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / cap;
        score += 15.0 - 25.0 * fit_quality; // high post_residual (bad fit) -> open new bin
    }

    // Progress-based modulation: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / cap);

    // Prefer bins tighter than average.
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Small tie-break on exactness of fit.
    score -= 0.05 * item_size as f64 / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // Post-residuals in (0, 10] are the worst kind of dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    } else if post_residual > 20 && post_residual <= 30 {
        score += 8.0;
    }

    // Perfect fit bonus: strongly reward exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is only acceptable if a future item can use it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            // The lookahead cannot use this gap: penalize proportionally.
            score += (post_residual as f64) * 1.5;
        } else {
            // Lookahead fits into the residual: reward tight coupling.
            score -= (post_residual as f64 - next_item_size as f64).min(10.0);
        }
    }

    // Open-bin pressure: discourage spreading across too many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    score += pressure * 2.0;

    // Prefer bins whose residual is already below the mean (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should reuse one).
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (fitting_bins_count as f64).min(5.0);
        // Late in the stream, opening a fresh bin is cheap since mean residual is low.
        score -= mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect fill on the following step).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect lookahead match: strongly prefer this bin
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: mild bonus scaled by tightness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit after placement: penalize leftover dead space
            score += 10.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // Prefer bins whose residual is below mean residual (tighter packing),
    // penalize bins that are unusually empty relative to the mean.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (large items benefit from a fresh bin).
    if bin_residual == bin_capacity {
        score += 25.0 - 0.2 * item_size as f64;
        // Late in the stream, be more reluctant to open new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    }

    // Small global pressure toward tighter fits overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    } else if post_residual >= 10 && post_residual <= 40 {
        // residual in the common item range is reusable
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // More competing bins -> mild penalty for fragmenting
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item can't use the residual, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            score += 8.0;
        }
    }

    // Global state: prefer filling bins when many are open (reduce spread)
    let open_f = open_bins_count as f64;
    score += (open_f - 3.0).max(0.0) * 2.0;

    // Deviation from mean residual: bins far from mean are less attractive
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only when no bin is a good fit and many bins are open
        let good_fit_exists = fit_ratio > 0.7 && fitting_bins_count > 0;
        if good_fit_exists {
            score += 60.0; // discourage opening when a tight fit exists
        } else if post_residual >= 50 {
            score -= 10.0; // fresh bin is fine early
        }
        score += 5.0 * progress; // late in stream, avoid new bins
    }

    // Small stochastic-free tie-breaker based on residual ordering
    score += (bin_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: raw leftover space (lower is better fit).
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, tolerate slack; later, punish dead space more aggressively.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let slack_weight = 0.6 + 1.8 * prog2 + 1.2 * prog3;
    score += slack_weight * (pr / cap) * (pr / cap) * cap * 0.35;

    // Reward tight fits: near-zero post_residual gets a strong smooth bonus.
    let tightness = 1.0 - (pr / cap).min(1.0);
    score -= 14.0 * tightness * tightness * tightness;

    // Exact/near-exact fill bonus (post_residual small relative to item).
    if item > 0.0 {
        let fill_ratio = 1.0 - pr / item;
        score -= 6.0 * fill_ratio * fill_ratio;
    }

    // Lookahead coupling: if next item fits into the resulting post_residual,
    // reward; otherwise penalize proportional to wasted opportunity.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 5.0 * snug * snug;
        } else {
            let gap = (nxt - pr) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // New-bin candidate handling: opening a bin wastes its full residual unless
    // the item is large. Penalize smoothly by fraction of capacity left unused.
    if bin_residual == bin_capacity {
        let waste = pr / cap;
        score += 10.0 + 25.0 * waste * waste;
        // But if no existing bin fits, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, mildly discourage spreading across many bins.
        score += 3.0 * prog2;
    } else {
        // Reward using an existing bin, more so when many bins are open.
        score -= 2.0 + 0.15 * (open_bins_count as f64).sqrt();
        // Last-chance bin: strongly favor filling the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Favor bins whose residual is near the mean (keeps pool balanced),
        // smoothly penalizing outliers.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    score -= 60.0 * (1.0 - post_residual as f64 / cap);

    // Harmonic class of post_residual: residues divisible by small class
    // sizes are more reusable by future items (items 1..100).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 25.0; }
        else if pr % 5 == 0 { score -= 10.0; }
        if pr % 7 == 0 { score -= 6.0; }
        if pr % 3 == 0 { score -= 4.0; }
        // Dead space: residues in awkward bands (1..9 or 91..99 modulo classes)
        if pr < 10 { score += 40.0; }
        // Integer-division thresholds: quarter classes of capacity
        let q = pr / 25; // 0..4
        score -= [ -15.0, 5.0, 0.0, 5.0, -10.0 ][q as usize];
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let nr = pr - next_item_size;
            score -= 30.0 * (1.0 - nr as f64 / cap);
            if nr % 10 == 0 { score -= 8.0; }
        } else {
            score += 12.0; // next item won't fit here; mild penalty for wasting fit
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // fits are terrible (large post_residual) or many bins are already open.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 30.0 + 3.0 * open_bins_count as f64;
        // Allow new bin if item is large relative to capacity (hard to place later)
        if item_size as f64 / cap > 0.7 { score -= 45.0; }
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Mild pressure to consolidate as stream progresses.
    score -= 10.0 * (step_index as f64 / total_items.max(1) as f64) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger residuals are flexible; reward proportionally.
        score -= 0.15 * (post_residual as f64 - 35.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting the next item too (lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that almost fits the next item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading
    // (penalize placements that keep many bins alive with small residuals).
    let pressure = open_bins_count as f64;
    score += 0.05 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer opening a fresh bin only when all open bins
    // would leave tight dead space, or when bin pressure is low.
    if bin_residual == bin_capacity {
        let all_bad = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && post_residual < 20);
        if all_bad {
            score -= 20.0;
        } else {
            score += 15.0 + 0.5 * pressure;
        }
    }

    // Early in the stream, opening bins is cheap; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight tilt toward bins near the mean residual (balance load).
    score += 0.03 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact two-item fill of the bin: ideal outcome.
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward,
            // stronger the tighter the leftover gap.
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 - gap.min(60.0);
        } else {
            // Next item won't fit: leftover is dead space unless tiny.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
            if post_residual < 10 {
                score += 40.0; // nearly unusable sliver
            }
        }
    }

    // Relative to mean residual: prefer bins with less residual (tighter packing).
    let mean_gap = mean_residual - bin_residual as f64;
    score += mean_gap * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize spreading across many bins when plenty are open.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: neutral-ish baseline; only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is fine if the item is large (little waste later).
        score -= item_size as f64 * 0.4;
    }

    // Late in the stream, tighten up: prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fit_tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fit_tightness * fit_tightness;

    // Penalize dead space: small post_residual is good, but zero-waste is best.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0; // residual too small for any item (min size 1..100, but tiny gaps are near-dead)
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item fills the gap
            let gap_use = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * gap_use;
        } else {
            // next item cannot use this gap: mild penalty for large leftover
            score += 0.05 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        // Opening a new bin is penalized when decent open bins exist.
        let best_possible_waste = (bin_capacity - item_size) as f64;
        let open_bins_good = if mean_residual >= item_size as f64 {
            (mean_residual - item_size as f64) / bin_capacity as f64
        } else {
            0.0
        };
        score += 10.0 + 2.0 * open_pressure - 15.0 * open_bins_good;
        // Early in stream, opening bins is cheaper (builds inventory).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        let _ = best_possible_waste;
    }

    // Global state: when many open bins with large mean residual,
    // discourage spreading (favor filling existing bins).
    if bin_residual != bin_capacity {
        let spread_pressure = mean_residual / bin_capacity as f64
            * (open_bins_count as f64).sqrt();
        score += 0.5 * spread_pressure * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild time-dependent bias: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * fit_tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear waste penalty: quadratic in normalized post_residual
    let pr_norm = pr / cap;
    score += 18.0 * pr_norm * pr_norm;

    // Smooth stream-progress coupling: late in the stream, tolerate less slack
    score -= 8.0 * (1.0 - progress) * pr_norm * (1.0 - pr_norm);

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_gap = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    } else {
        // last item: strongly prefer minimal post residual
        score -= 5.0 * pr_norm;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more so early when open bins exist
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let openness = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
        score += 10.0 + 20.0 * openness;
    } else {
        // Prefer bins whose residual is close to the item (tight fit)
        let tight = (bin_residual as f64 - item_size as f64) / cap;
        score += 4.0 * tight * tight;
        // Reward bins below mean residual (already compressed)
        if (pr as f64) < mean_residual {
            score -= 3.0 * (mean_residual - pr as f64) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Strong penalty for post_residual in the "dead zone": too small to be useful
    // for typical items (1..100) but nonzero. Zero residual is perfect.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if pr < eighth {
        score += 60.0; // tiny dead space, wasted capacity
    } else if pr < quarter {
        score += 20.0;
    } else if pr < cap / 2.0 {
        score += 5.0;
    }

    // Integer-division harmonic classes on post_residual
    let pr_class = post_residual / 10; // classes 0..10
    score += (pr_class as f64) * 1.5;

    // Lookahead coupling: if the next item fits exactly or well in the leftover,
    // reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // chains a perfect follow-up
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            if npr < 10 {
                score -= 15.0; // next item nearly fills it
            } else if npr <= 25 {
                score -= 6.0;
            }
        } else {
            // leftover smaller than next item: mildly penalize
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless we have no real alternative
    // (handled above) or the stream is early and we want many bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64).sqrt() * 8.0;
        // early stream: opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual is far from the mean (consolidate leftovers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.3;

    // Prefer fuller bins generally
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Modulo harmonic: penalize post_residual that is awkward modulo 10
    let m = post_residual % 10;
    if m > 0 && m < 5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range)
    // are pure waste; penalize them quadratically.
    if post_residual < 1 {
        score += 1000.0; // impossible, shouldn't happen
    }
    if post_residual > 0 && post_residual < 10 {
        // Dead space: nothing (min item 1) ... but small gaps < smallest plausible item
        // are hard to fill; penalize hard.
        score += (10 - post_residual) as f64 * 40.0;
    }

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Prefer bins whose residual was large (we consume more of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Pressure from open bins count: more open bins -> discourage new bins.
        score += open_bins_count as f64 * 3.0;
        // If the next item would fit in the leftover of this placement, opening
        // a fresh bin is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Existing bin: reward if leftover can host the next item (lookahead chaining).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 {
            score += 5.0; // leftover likely dead space for the next item
        }
    }

    // Slight preference for bins below mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain: this bin becomes perfectly full next step
        } else if next_item_size <= post_residual {
            // next item fits here afterwards: mildly good, scaled by tightness
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize dead space proportionally
            score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;
        }
    }

    // Tightness of current placement relative to bin capacity.
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize bins far below mean residual (poorly utilized bins) mildly,
    // but reward bins near mean residual (balanced packing).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or many bins are open (diversification late in stream).
    if bin_residual == bin_capacity {
        score = 200.0
            - 100.0 * (fitting_bins_count as f64).recip()
            + 5.0 * (open_bins_count as f64).ln().max(0.0);
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 300.0; // fresh bin perfectly chains with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward near-perfect fits with a strong nonlinear bonus.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that can never host a typical future item.
    if post > 0.0 && post < 10.0 {
        score += 12.0 * (10.0 - post);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: prefer bins whose post-residual matches the next item.
    if next_item_size > 0 && post >= next_item_size as f64 {
        let slack = post - next_item_size as f64;
        score -= 8.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && post > 0.0 {
        // Post-residual unusable for the next item: mild penalty scaled by lookahead size.
        score += 3.0 * (next_item_size as f64 / cap);
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // bins are badly fragmented or the fit in an existing bin would be awful.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Base cost of a fresh bin.
        score += 20.0;
        // Reduce penalty if open bins are fragmented (large mean residual wasted)
        // or if the item is large relative to typical residual capacity.
        score -= 14.0 * fragmentation;
        score -= 6.0 * progress;
        // If item is big, a fresh bin gives the best long-term packing.
        score -= 8.0 * (item / cap);
    } else {
        // Mild bonus for consolidating into already-open bins.
        score += 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Small time-horizon modulation: late in the stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress) + norm_post * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * (0.3 + progress);

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 4.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many bins; favor consolidating residuals.
    let mean_diff = (mean_residual - post).abs() / cap;
    score += 3.0 * mean_diff * mean_diff;

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 10.0 + 20.0 * (1.0 - progress);
        let escape_bonus = if fitting_bins_count == 0 { 0.0 } else { 5.0 + 10.0 * (1.0 - progress) };
        score += base_penalty + escape_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals that are "dead" (very small)
    // and residuals that form perfect fractions of capacity (0, 1/4, 1/2, 3/4).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 20.0; // nearly dead space, fine
    } else if post_residual < quarter {
        score -= 8.0; // small usable gap
    } else if post_residual == quarter as u32 {
        score -= 15.0;
    } else if post_residual < half {
        score -= 2.0;
    } else if post_residual == half as u32 {
        score -= 12.0;
    } else if post_residual < three_quarter {
        score += 5.0; // large residual: wasteful placement
    } else {
        score += 12.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // typical item sizes; penalize awkward non-multiples.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: strongly reward a residual that exactly fits the next item,
    // penalize residuals that leave next item stranded.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post - nx;
            score -= 6.0 * (1.0 - slack / cap).max(0.0);
            if slack < 10.0 {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: residual becomes dead until refill
            score += (post / cap) * 10.0;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (post / cap) * 5.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // gives a decent fit. Make empty-bin score proportional to waste of
    // leaving item alone plus mild stream-position term.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score += (post / cap) * 20.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Slight pressure to prefer bins tighter than the mean residual
    // (best-fit flavor, normalized).
    score += (post - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure loss; penalize gaps that cannot fit the lookahead item either.
    if post_residual > 0 {
        // Gap smaller than any plausible future item is dead space.
        if post_residual < 10 {
            score += 40.0;
        }
        // Lookahead coupling: if the next item cannot use this gap, it's likely dead.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * post_residual as f64;
        }
    } else {
        // Perfect closure is excellent.
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; strongly discourage opening new bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if nothing fits well.
        score += 25.0 + 3.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 35.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., more filled bins) to consolidate.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild stream progression: late in the stream, close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // perfect chain: two items exactly fill the bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack.min(80.0); // tighter slack = bigger bonus
        } else {
            // next item cannot fit: penalize leftover dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: pure tightness packing.
        score += 0.0;
    }

    // Penalize bins far below the mean residual (bad space usage) mildly;
    // prefer bins close to mean residual for balanced packing.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large dead space would be created elsewhere) or late in the stream
    // with few open bins.
    if bin_residual == bin_capacity {
        let dead_elsewhere = if next_item_size > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 - 0.5 * dead_elsewhere - 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward leaving space the next item can use,
    // penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(2.0);
        } else {
            // dead space relative to next item
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (already via post_residual)
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Estimate the "waste" of the best alternative
    // via mean residual.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin: capacity minus item, penalized more when
        // plenty of open bins with room exist and the stream is early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = (open_bins_count as f64).sqrt().min(6.0);
        score += 55.0 + crowding * (1.0 - progress) * 6.0;
        // A new bin is attractive if the item is large (little residual waste)
        // or mean residual is very low (open bins are nearly full).
        score -= (item_size as f64 - 50.0) * 0.4;
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Placing in an open bin: mild penalty proportional to how much
        // residual this bin has vs the global mean (avoid fragmenting
        // already-loose bins when tighter ones exist).
        score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Penalize leaving residuals in the awkward 1..10 band (unusable slivers
    // for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (0.5 + p) - norm_pr * (0.3 + 0.4 * p * p);
    score += 12.0 * coupling;

    // Penalize dead space more heavily as stream advances (smooth power)
    score += 8.0 * norm_pr * norm_pr * (0.5 + 1.5 * p);

    // Reward tight fits smoothly
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_frac * fit_frac * (1.0 - 0.3 * p);

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - p * 0.5);
    }

    // Lookahead: reward leaving space for next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 3.0 * ((-gap) / cap);
        }
    }

    // Mean residual coupling: prefer bins deviating from mean (diversification)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev - 1.5 * dev;

    // New-bin candidate: prefer only when few open bins or early stream
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 + p) - 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: quantize dead space into capacity fractions ---
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // in [0,1]

    // Perfect fit gets a huge reward (strongly subtract).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for small residuals (unusable slivers).
        // Classes: residual <= 10 nearly useless, 11..=20 poor, etc.
        let class_penalty: f64 = if post_residual <= 10 {
            90.0
        } else if post_residual <= 20 {
            45.0
        } else if post_residual <= 30 {
            20.0
        } else if post_residual <= 50 {
            6.0
        } else {
            0.0
        };
        score += class_penalty;

        // Modulo arithmetic: residuals that are "harmonically compatible" with common
        // item sizes (multiples of 10, 20, 25, 50) are more reusable.
        let harmonic_bonus: f64 = if post_residual % 50 == 0 {
            12.0
        } else if post_residual % 25 == 0 {
            9.0
        } else if post_residual % 20 == 0 {
            7.0
        } else if post_residual % 10 == 0 {
            5.0
        } else if post_residual % 5 == 0 {
            2.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
    }

    // --- Lookahead coupling (k=2): does the next item fit into post_residual? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: reward keeping this pair together.
        let tightness = (post_residual - next_item_size) as f64;
        score -= 8.0 + 4.0 * (1.0 - tightness / cap_f);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit after this placement: penalize, worse for tiny residuals.
        score += 6.0 * (1.0 - frac);
    }

    // --- Last-chance bin: if this is the only fitting bin, prefer using it over opening new ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- New-bin candidate (bin_residual == bin_capacity): only attractive when the
    //     item fits poorly everywhere else / many open bins with big residuals exist. ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; discount when stream is early or bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 55.0 * (1.0 - 0.4 * progress);
        // If mean residual is large and item is small-ish, opening new bins is wasteful.
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_cost += 20.0;
        }
        // If many bins can fit the item, opening a new one is almost never right.
        if fitting_bins_count > 2 {
            new_bin_cost += 30.0 * (fitting_bins_count.min(6) as f64);
        }
        score += new_bin_cost;
    }

    // --- Mild preference for filling fuller bins (residual tightness coupling) ---
    score += 0.05 * (bin_residual as f64 - post_f);

    // --- Slight penalty for proliferating open bins when residuals are healthy ---
    if mean_residual > 30.0 && open_bins_count > 3 {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Reward tight fits: waste ratio relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Pressure from number of open bins: discourage opening/spreading into many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and would leave this bin stranded, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        // A fresh bin is only attractive when existing bins are crowded or fit is bad.
        if mean_residual < 25.0 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
        score += 1.5 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, be more conservative with dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * waste_ratio;

    // Mean residual coupling: high mean residual means open bins have room; reuse them.
    score += 0.15 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: item leaves exactly the space the next item needs.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item also fits in this bin after placement: strong bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the next item's demand.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize residuals far below mean residual (creating unusable slivers).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin would leave a tiny sliver.
    if bin_residual == bin_capacity {
        if post_residual < 10 && next_item_size > post_residual {
            score -= 15.0;
        } else {
            score += 30.0;
        }
    }

    // Late in the stream: tighten packing, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize creating small unusable dead space (post_residual that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect pairing: post_residual exactly matches next item size.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when it enables a large usable block
    // and existing bins are fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bins early, or when open bins have low mean residual (poor fits).
        let new_bin_appeal = 30.0 * (1.0 - progress) + (100.0 - mean_residual) * 0.25;
        score += 45.0 - new_bin_appeal;
        // Penalize new bin if an open bin gives a very tight fit.
        if tightness < 0.1 && open_bins_count > 0 {
            score += 20.0;
        }
        let _ = fragmentation;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    if open_bins_count > 3 && mean_residual > 50.0 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;
    // penalize near-empty post residual (dead space) with smooth saturating term
    score += 25.0 * (norm_pr / (norm_pr + 0.15)) * (1.0 - progress);
    // reward tight fits relative to capacity smoothly
    let tight = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= 30.0 * (1.0 - tight) * (1.0 - tight) * (0.5 + 0.5 * progress);
    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // lookahead: reward bins that can also host next item smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - norm_pr);
    }
    // new-bin candidate: mildly penalize early, allow late
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 6.0 * progress;
    }
    // mean residual alignment term
    score += 5.0 * (norm_pr - mean_residual / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover is.
    // Small leftovers (< 10) are dead space -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else {
            // reward leftovers that match common item-size classes (multiples of 10)
            let r = post_residual % 10;
            let bonus = if r == 0 { 12.0 } else { -3.0 * (r as f64 / 10.0) };
            score -= bonus;
            // quanta: leftover usable in halves/quarters of capacity
            let q = (post_residual as f64 / (cap / 4.0)).floor();
            score -= 4.0 * q;
        }
    } else {
        score -= 30.0; // perfect fill
    }

    // Perfect-fit harmonic classes: item + post_residual == residual, favor when
    // post_residual lies in the small-item class (1..=10) of the unknown distribution.
    if post_residual >= 1 && post_residual <= 10 {
        score += 6.0; // leaves room for a tiny item, mildly good
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - 0.15 * slack as f64; // tight lookahead fit is best
        } else {
            // next item won't fit: penalize proportionally to overflow
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // new bins when existing fits are bad. Cost grows with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.6 + 10.0 * (1.0 - progress) + open_bins_count as f64;
        // opening a new bin is attractive if current item is huge and would leave
        // a very fragmented residual elsewhere
        if item_size >= 70 { score -= 25.0; }
    }

    // Mild pressure to prefer bins below mean residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that are too small for typical next items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // But opening a new bin is fine if the next item is large and this item fits anywhere poorly.
        if next_item_size > 0 && post_residual == 0 {
            score -= 30.0;
        }
    }

    // Prefer bins with residuals close to item size (minimize fragmentation).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Slight stream-progression adaptation: tighten standards as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Discourage bins whose residual deviates strongly from the mean residual (fragmentation control).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness preference: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Two-step lookahead: reward if the next item exactly or nearly fits the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chained fit: extremely desirable.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement.
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space left behind.
            let waste = post_residual as f64;
            score += 0.8 * waste;
            // Extra penalty if the leftover is unusably small relative to typical item sizes.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than the mean.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 5.0 * residual_gap / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Default penalty so existing bins are preferred...
        score += 30.0;
        // ...unless the item is large and the stream is early (capacity planning).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 10.0;
        }
        // If many bins fit, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable slivers are wasteful
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - slack_after_next / (bin_capacity as f64));
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot.min(50.0);
        }
    } else {
        // Last item: just minimize leftover waste aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // open bins are congested (few fitting bins) or residuals are fragmented.
    if bin_residual == bin_capacity {
        let congestion = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early and when alternatives exist; relax later.
        score += 30.0 / congestion
            + 0.2 * fragmentation
            + 20.0 * (1.0 - progress)
            - (open_bins_count as f64).min(10.0) * 0.5;
    } else {
        // Mild preference for bins whose residual deviates from the mean
        // (consolidate fragmented space into predictable shapes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Dynamic time horizon: as the stream nears its end, prioritize minimizing
    // final waste more strongly.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * horizon;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (norm_pr * norm_pr) * (1.0 + progress) - 2.0 * norm_pr * progress + progress * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Tight-fit reward (smooth quadratic around zero residual)
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize when the next item cannot use the leftover space
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 30.0 * gap * gap;
        let fits_next = if next_item_size <= post_residual { 1.0 } else { 0.0 };
        score -= 15.0 * fits_next * (1.0 - progress);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly unless residuals are large
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress * (1.0 - mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Harmonic class of post_residual: mod-10 buckets (residuals are 1..100)
    let post_class = post_residual % 10;
    // Dead-space penalty: small unusable residuals (1..9) are bad unless next item fits
    if post_residual > 0 && post_residual < 10 {
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if next_fits {
            score -= 25.0; // perfect chain: next item exactly fills this class
        } else {
            score += 60.0; // dead space
        }
    }

    // Harmonic "half" classes: residuals near capacity/2 and capacity fractions
    let half = bin_capacity / 2;
    if post_residual == half {
        score -= 15.0; // half-filled bins are flexible
    }

    // Reward tight fits (small post_residual) super-linearly
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 10.0 + (15 - post_residual) as f64;
    }

    // Lookahead coupling: penalize if next item needs this residual but slightly misses
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size - post_residual;
        if gap <= 10 {
            score += 20.0 + gap as f64; // near-miss wastes the bin for the next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    let open_pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += open_pressure * 0.5 * (1.0 - progress);

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when few bins or early stream
        score = bin_capacity as f64 * 0.9 - (progress * 20.0);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 50.0; // prefer the single existing fitting bin
        }
        if next_item_size >= bin_capacity - 10 && item_size <= 30 {
            score -= 30.0; // reserve space for a large next item
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (fill laggards)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Open bins pressure: penalize placements into bins when many bins are open,
    // to encourage consolidation; but reward using last-chance bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    if fitting_bins_count == 1 {
        score -= 35.0; // last chance bin: strongly prefer using it
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space blocks next item
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + progress * 20.0 - (fitting_bins_count as f64) * 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item would leave very little slack.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
    }
    // Next item cannot fit here: mild penalty so lookahead-friendly bins win ties.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Penalize residuals far above the mean (wasteful large leftover),
    // reward residuals below mean (tight packing).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Never open a new bin when an open bin fits tightly (post_residual small).
    if bin_residual == bin_capacity {
        score += 50.0 + 0.25 * item_size as f64;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual was close to item size.
    let fit_slack = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_slack).powi(3);

    // Penalize tiny post-residuals that are dead space (too small for the
    // smallest plausible item ~ size 1, but useless if < next item).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reward leaving room for the lookahead item.
        if post_residual >= next_item_size {
            score -= 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 20.0 - 18.0 * crowding;
        // Late in the stream, prefer consolidation into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item can't fit anywhere but a fresh bin anyway
        }
    }

    // Many open bins: prefer filling bins with large residual (reduce spread).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 3.0 * (1.0 - dev / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: penalize residual scaled by progress
    score += (post_residual as f64) * (0.5 + progress * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (20.0 + 40.0 * progress);

    // If next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 15.0 * norm_next * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 5.0 * (1.0 - norm_post);
    }

    // Penalize creating dead space that likely cannot be used later
    if norm_post > 0.0 && norm_post < norm_item {
        score += 8.0 * norm_post * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Slight penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Deviation from mean residual: prefer bins with residual close to item
    let fit_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.3 * fit_gap * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when no tight fit exists
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // sizes for future items (small, or matching common capacity fractions).
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit is always best
    } else {
        // Fraction of capacity left as residue.
        let frac = pr as f64 / bin_capacity as f64;

        // Reward residues in "harmonic" buckets: <=10 (near-perfect),
        // exactly divisible into halves/quarters of capacity.
        if pr <= 10 {
            score -= 60.0 + (10 - pr) as f64 * 3.0;
        }
        if pr == bin_capacity / 2 || pr == bin_capacity / 4 || pr * 4 == bin_capacity * 3 {
            score -= 25.0;
        }
        // Modulo classes: residues divisible by common item granularities
        // (multiples of 5 and 10) are more likely reusable.
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }

        // Penalize large dead-space residues that no typical item (1..=100)
        // would fill efficiently; but very large residues on a fresh bin are fine.
        if pr > bin_capacity / 2 {
            score += (pr - bin_capacity / 2) as f64 * 0.5;
        }

        // Lookahead coupling: if next item fits exactly into post_residual,
        // strongly reward; if next item barely misses, penalize.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 80.0;
            } else if next_item_size < pr {
                score -= (pr - next_item_size).min(20) as f64 * 1.5;
            } else {
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }

        // Last-chance bin: if this is the only bin that fits, avoid opening
        // a new bin unless the fit is terrible.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // New-bin candidate: opening a new bin wastes (capacity - item).
        // Only attractive when the current fit is bad (large residue left here).
        if bin_residual == bin_capacity {
            let waste = (bin_capacity - item_size) as f64;
            score = waste * 1.1 + 5.0;
            // Slightly prefer new bins early in stream when few bins open.
            score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        }

        // Mild tie-break: prefer bins with residual below mean (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small for the minimum item size (1) is fine,
    // but residuals in the "awkward" band (1..=15) are hard to fill later.
    if post_residual >= 1 && post_residual <= 15 {
        score += 25.0;
    } else if post_residual > 15 && post_residual <= 30 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 30.0;
    }

    // Reward near-perfect fits (post_residual <= 5 is likely fillable by small items).
    if post_residual > 0 && post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize placements that leave
    // large residuals when many bins are already open.
    let obp = open_bins_count as f64;
    if open_bins_count > 4 {
        score += (post_residual as f64) * (obp / 40.0);
        // Extra pressure to close bins when many are open.
        if post_residual == 0 {
            score -= obp * 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would exactly fill the post residual, extra reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when no good fit exists, i.e., when
    // mean residual across open bins is small relative to the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin grows with stream progression
        // (early on, spreading is cheaper; later, consolidation matters).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * progress;
        // If existing bins fit poorly (mean residual < item size), opening
        // a new bin becomes more attractive.
        if (mean_residual) < item_size as f64 {
            score -= 18.0;
        }
        // If many bins are open and mean residual is large, discourage new bins.
        if open_bins_count > 3 && mean_residual > (item_size as f64) * 1.5 {
            score += 25.0;
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual is close to
    // what we consume (tight fits reduce fragmentation).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize proportionally to mismatch, but only if next item could fit.
            if next_item_size <= post_residual {
                score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
            } else {
                // next item won't fit: dead space penalty scaled by gap size.
                score += gap * 0.5;
            }
        }
    }

    // Penalize tiny unusable residuals (dead space) relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Favor bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in stream: slightly prefer filling existing bins; late: allow new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward when many bins open / tight fits scarce.
        score += 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0.0 -> 1.0)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space non-linearly: small leftovers are hard to reuse.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 8.0;
        }
        // Prefer bins whose residual after placement is either tiny or large enough
        // to plausibly fit a future item (>= next item size).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 12.0; // room for the lookahead item: good chaining
            }
            // Exact two-item closure: this item plus the next fills the bin.
            if item_size + next_item_size == bin_residual {
                score -= 30.0;
            }
            // Avoid leaving a gap that almost-but-not-quite fits the next item.
            if post_residual < next_item_size && post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Reward tight fits relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // When many bins are open, prefer consolidating into existing bins to
    // avoid spreading residual capacity thinly.
    if open_bins_count > 4 {
        let crowding = (open_bins_count as f64).ln() * 3.0;
        score -= crowding * fill_ratio;
    }

    // Global residual balance: placing into a bin whose residual is far below
    // the mean leaves the mean residual high elsewhere; slightly favor bins
    // near the mean residual (keeps residuals uniform and reusable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Time horizon: early in the stream, keep bins flexible (favor larger
    // post-residuals for future items); late in the stream, prioritize closing
    // bins tightly.
    if progress < 0.35 {
        score += post_residual as f64 * 0.05; // mild flexibility bonus early
    } else if progress > 0.7 {
        score -= (bin_capacity - post_residual) as f64 * 0.10; // pack tight late
    }

    // New-bin candidate (empty bin): make it attractive only when no open bin
    // offers a good fit. Penalize opening a new bin normally; the penalty is
    // reduced when the item is large relative to capacity.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let item_bulk = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 45.0 - item_bulk * 40.0;
        // If few bins fit the item, a new bin is less wasteful.
        if fitting_bins_count == 0 {
            new_bin_score -= 50.0;
        } else if fitting_bins_count == 1 {
            new_bin_score -= 15.0;
        }
        // Late in the stream, opening new bins is less useful.
        new_bin_score += progress * 10.0;
        score = score.max(0.0) + new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Quadratic penalty on post_residual: small leftovers are heavily favored.
    let pr = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * pr * pr * bin_capacity as f64;

    // Smooth reward for tight fit scaled by stream progress.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * (0.5 + progress);

    // Lookahead coupling: reward if next item fits in post_residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving a dead gap slightly smaller than the next item.
        score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin, more so early in the stream and when alternatives exist.
    if bin_residual == bin_capacity {
        let alt_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += (20.0 + 25.0 * (1.0 - progress)) * alt_pressure + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference to balance residuals across bins.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into useful "slots" that typical items can fill.
    // A leftover that is an exact multiple of common item sizes is valuable.
    let cap = bin_capacity as f64;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: modulo arithmetic against the
    // canonical small-item sizes (1..=100 unknown distribution, so probe
    // several divisors). Leftovers divisible by small sizes are reusable.
    let pr = post_residual as u32;
    let mut harmony = 0.0f64;
    for d in [5u32, 10, 20, 25, 50] {
        if pr % d == 0 && pr > 0 {
            harmony += 1.0;
        }
    }
    score -= harmony * 8.0;

    // Integer-division threshold: leftover that can hold a "half-bin" class
    // item (>= cap/2) is one class; leftover that can only hold tiny items
    // (< cap/10) is dead space -> penalize.
    if pr >= (cap * 0.5) as u32 {
        score -= 15.0; // flexible large leftover
    } else if pr < (cap * 0.1) as u32 {
        score += 10.0; // dead space
    } else if pr < (cap * 0.25) as u32 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // big reward (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            // reward if the double placement also lands in a good class
            if npr % 10 == 0 {
                score -= 25.0;
            }
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item won't fit here: leftover should be small/dead anyway
            score += (next_item_size as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it is the only
    // option (handled above) or mean residual of open bins is very low
    // (open bins nearly full anyway).
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.5 + (open_bins_count as f64) * 2.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are fine, but gaps that are unusable relative to
    // typical item sizes are heavily penalized.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        // tiny sliver: nearly dead space
        score += (10.0 - post_residual as f64) * 8.0;
    } else if post_residual > 0 {
        // penalize gaps that are too small for the next item (lookahead dead space)
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        }
        // mild penalty for gaps below the typical item scale
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio < 0.15 {
            score += (0.15 - gap_ratio) * 120.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // space rather than spreading; also make new-bin option less attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // new bin candidate: base cost plus pressure
        score += 6.0 + pressure * 4.0;
        // if no open bin fits well, opening new bin is more acceptable
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // existing bin: reward using it when many bins are open
        score -= pressure * 2.0;
    }

    // Reward filling bins tighter than the current mean residual
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Lookahead synergy: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Late-stream consolidation: as stream progresses, prefer tight packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward tight packing.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this placement chains perfectly.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if (pr - ni).abs() < 0.5 {
            score -= 500.0;
        } else if ni < pr {
            // Next item fits in the leftover: mildly good.
            score -= 0.5 * ni;
            // Extra reward if next item nearly fills the remainder.
            let ratio = ni / pr;
            if ratio > 0.8 {
                score -= 0.8 * pr;
            }
        } else {
            // Next item won't fit in the leftover: penalize wasted space
            // proportional to how big the dead gap is.
            score += 0.6 * (ni - pr);
        }
    }

    // Compare residual against mean residual across open bins: prefer bins
    // whose leftover stays near/above the mean (avoid creating outliers).
    let pr = post_residual as f64;
    if pr < mean_residual * 0.4 && post_residual > 0 {
        score += 30.0; // creating unusually small residual wastes the bin
    } else if pr > mean_residual * 1.5 {
        score -= 10.0; // keeping bin roomy is fine
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the empty-bin candidate, but
    // relax the penalty late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 400.0 - 200.0 * progress - 5.0 * open_bins_count.min(40) as f64;
        score += penalty.max(50.0);
    }

    // Slight preference for filling already-open bins as stream progresses.
    score += 0.05 * post_residual as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space relative to typical item sizes
        let dead = post_residual as f64;
        score += (dead * dead) / (bin_capacity as f64 * 0.5);
        // If the leftover can't fit a typical small item, extra penalty
        if post_residual < 10 {
            score += 25.0;
        }
        // Lookahead: reward if leftover fits the next item (chain packing)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        }
        // Penalize leaving a gap just below the next item (blocking)
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Tightness of the current fit: favor bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (denser bins) mildly
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin, more so when open bins exist
    // and can fit; but allow it if this bin would be very sparse and many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 + 40.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste pressure: quadratic in post_residual, damped by progress
    score += 0.35 * (pr / cap) * (pr / cap) * cap * (0.5 + 0.5 * progress);

    // Reward tight fits: subtract when post_residual is small relative to capacity
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize bins whose residual is far from the mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if next item could use the post-residual, reward leaving it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // Late stream: prefer consolidating into fewer bins
    score += 0.4 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize opening a fresh bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let base_penalty = 15.0 + 25.0 * (1.0 - progress);
        let waste = (pr / cap).powi(2) * 40.0;
        score += base_penalty + waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Small leftovers (< 10) are dead space; large leftovers host future items.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else {
        // Reward leftovers that can host a "harmonic class" of item sizes
        // (multiples of 10 are natural anchors in 1..100 streams).
        let class = post_residual / 10;
        score -= 4.0 * class as f64;

        // Can the lookahead item fit into the leftover? Strong bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0;
            // Exact harmonic match: leftover equals a multiple of the next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else if next_item_size > 0 {
            // Lookahead cannot use the leftover: mild penalty proportional to gap
            score += 3.0 + 0.15 * ((next_item_size - post_residual) as f64).min(20.0);
        }
    }

    // Tightness coupling: reward bins where the item fills a large fraction
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins with less residual among many fitting bins (best fit)
        score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // New-bin candidate logic: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins early and when item is small (can go anywhere)
        let mut new_bin_score = 45.0 + 10.0 * (1.0 - progress);
        if item_size <= 50 { new_bin_score += 20.0; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // room for the next item in a fresh bin: slightly less bad
            new_bin_score -= 10.0;
        }
        if fitting_bins_count == 0 {
            // no open bin fits: new bin is necessary
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    }

    // Mean-residual coupling: if open bins are already loose, discourage
    // spreading residual further; if tight, encourage consolidating.
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Mid-range dead space (10..=20) is also hard to fill with items >= 10.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot fit in post residual but could fit elsewhere.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening new is cheaper.
    score += (open_bins_count as f64).sqrt() * 2.0;
    score -= mean_residual * 0.05;

    // New-bin candidate: only attractive when current fit is poor or residual is dead space.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual >= bin_capacity { 0.0 } else { 0.0 };
        let _ = poor_fit;
        // Base cost of opening a new bin.
        let mut new_bin_score = 30.0 + post_residual as f64;
        // If this bin would be the only fitting bin, opening new is less attractive.
        if fitting_bins_count == 1 {
            new_bin_score += 20.0;
        }
        // If the current bin would leave a dead gap, new bin becomes competitive.
        if post_residual > 0 && post_residual < 10 {
            new_bin_score -= 35.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += progress * 15.0;
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards; reward small leftover after both
            let chain_residual = post_residual - next_item_size;
            score -= 0.5 * (next_item_size as f64) - 0.3 * (chain_residual as f64);
        } else {
            // next item won't fit in the leftover; penalize dead space
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful placement)
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let bad_fragmentation = mean_residual < item_size as f64 * 0.5;
        if bad_fragmentation {
            score -= 150.0;
        } else {
            score += 200.0;
        }
    }

    // Mild preference to fill bins tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement, especially if unusable
    // by the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0; // dead space: next item can't use it
        } else if post_residual >= next_item_size {
            // reward bins that can also host the next item snugly
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * next_fit;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets base penalty so we only
    // open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Open new bins more willingly early in the stream (more items left
        // to fill them) and when many bins are already open but residuals
        // are fragmented (mean residual low relative to item size).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit bias
        // beyond the quadratic term): penalize bins with lots of slack.
        let slack = bin_residual as f64 - item_size as f64;
        score += 0.15 * slack;
        // Mild preference to consolidate into bins with low residual
        // (fewer fragmented bins overall).
        score -= 0.05 * mean_residual;
        // When many bins are open, favor filling existing ones harder.
        score -= 0.5 * open_bins_count as f64;
    }

    // Late-stream urgency: as stream ends, squeeze items into existing bins
    // even at the cost of tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild penalty for large leftovers; late: strong penalty
    // because remaining slack is less likely to be filled.
    let slack_frac = post / cap;
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += slack_frac * slack_frac * cap * (0.5 + 2.5 * t);

    // Reward tight fits (post_residual near zero) more than linearly.
    score -= (item_size as f64 / cap) * (1.0 + 2.0 * t) * 4.0;

    // Lookahead: penalize if leftover cannot host the next item,
    // reward if it can (especially as stream progresses).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 5.0 * t;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post) * (0.2 + 0.6 * t);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * t;
    }

    // Penalize bins whose residual deviates badly from the mean residual
    // (keeps a diverse residual portfolio for future items).
    score += 0.3 * ((post - mean_residual).abs() / cap) * (1.0 + t);

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * t;

    // New-bin candidate: make it moderately attractive only when item is
    // large relative to capacity or residuals are all poor.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / cap;
        score = cap * (0.6 + 0.4 * t) - 4.0 * (item_size as f64 / cap)
                - 6.0 * (1.0 - avg_fit) * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of the post residual: multiples of 10 are "perfect" classes
    let post_class = (post_residual % 10) as f64;
    let class_bonus = if post_residual > 0 { (10.0 - post_class) * 0.6 } else { 8.0 };
    score -= class_bonus; // reward residuals landing on clean harmonic boundaries

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement: strongly reward
            score -= 12.0 + (next_item_size as f64) * 0.25;
        } else if post_residual > 0 {
            // Dead space: residual too small for the lookahead item
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + waste * 0.35;
        }
    }

    // Integer-division threshold: residual in (0,10) is nearly unusable sludge
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: baseline penalty that shrinks for large items or poor fits
    if is_new_bin {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 6.0 - 4.0 * tightness;
        // Late in the stream, be more willing to open fresh bins for large items
        score -= progress * (item_size as f64) * 0.05;
    }

    // Slight preference for keeping many bins well-balanced vs mean residual
    score += ((post_residual as f64) - mean_residual).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize moderate dead space more when the bin is nearly empty of items.
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bins pressure: penalize placements into bins when many bins are open,
    // to avoid spreading; conversely reward tight packing when few bins open.
    let open_pressure = open_bins_count as f64;
    score += 0.35 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.5 * open_pressure;
        // If next item is large, a fresh bin may be useful: reduce penalty.
        if next_item_size >= 60 {
            score -= 35.0;
        }
    }

    // Lookahead: reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just below the next item size (unusable for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (balanced packing), penalize outliers.
    let residual_f = bin_residual as f64;
    let deviation = (residual_f - mean_residual).abs();
    score += 0.15 * deviation;

    // Stream progression: as the stream ends, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead — reward when the next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remaining space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 40.0; // perfect 2-item packing bonus
            }
        } else {
            // Next item won't fit here: penalize wasted residual proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: minimize leftover as usual.
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average.
    let residual_f = bin_residual as f64;
    let tightness = (mean_residual - residual_f) / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Penalize creating dead space below the smallest plausible item (1..100 unknown, use 10 as soft floor).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual < 20 {
        score += 0.3 * (20 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidation into existing bins over new bins.
    if open_bins_count > 2 {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: make it unattractive unless residual is tiny and next item can't chain.
    if bin_residual == bin_capacity {
        let mut new_bin_score = bin_capacity as f64 * 0.9; // high base cost
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 20.0;
        }
        // Late in stream, opening a fresh bin is less costly (less future to serve).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 15.0 * progress;
        score = score.max(new_bin_score);
        score += new_bin_score * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already dominates).

    // Reward near-perfect fits strongly.
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Penalize dead space that is too small to be useful for typical items,
    // unless it's essentially zero (handled above).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 12.0 - slack * 1.5;
            }
        } else {
            // Next item won't fit here after placement: slight penalty unless
            // the leftover is still broadly usable.
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual >= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // existing bins. Make the empty bin costly by default; it should win only
    // when no open bin fits or all fits are catastrophically bad.
    if bin_residual == bin_capacity {
        let base_cost = 40.0 + 0.15 * (open_bins_count as f64);
        // As the stream progresses, become more reluctant to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += base_cost + 20.0 * progress;
        // If nothing fits anywhere, the new bin must be cheap.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: mild bonus scaled by how much residual we consolidate.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Global state: prefer placing into bins whose residual is above the mean
    // (keeps a portfolio of large residuals for future big items).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual - 10.0 {
            score += 4.0;
        } else if (bin_residual as f64) > mean_residual + 10.0 {
            score -= 4.0;
        }
    }

    // Time horizon: early in the stream, keep bins flexible (penalize tiny
    // leftovers more); late in the stream, squeeze hard (reward any fit).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Tie-break with a mild preference for fewer open bins via consolidation.
    score -= 0.5 * (open_bins_count as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let r_norm = pr / cap;

    // Base: quadratic penalty on wasted residual, softened by stream progress
    // (late in the stream, residual dead space matters more since fewer chances remain)
    let mut score = pr * (1.0 + progress * pr / cap);

    // Smooth non-linear coupling: residual^2 scaled by mean residual state
    let mean_ratio = mean_residual / cap;
    score += 2.0 * r_norm * r_norm * (1.0 + mean_ratio);

    // Tight fit reward: subtract when post_residual is small relative to capacity
    let tightness = 1.0 - r_norm;
    score -= 10.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead: reward bins whose residual can host the next item (k=2 lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // smooth reward proportional to how well next item fits after this placement
            let nxt_fit = 1.0 - (pr - nxt) / cap;
            score -= 8.0 * nxt_fit * nxt_fit;
        } else {
            // penalize placements that leave residual too small for the next item
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: neutral-ish score; prefer opening a new bin only when
    // existing bins would leave very poor fits (high post_residual) or few fitting bins
    if bin_residual == bin_capacity {
        let base = 0.45 * cap;
        let pressure = (fitting_bins_count as f64).max(1.0).recip();
        score = base + 12.0 * pressure + 15.0 * progress * mean_ratio;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.15 * open_bins_count as f64 * r_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact multiples of small divisors are
    // "usable" dead space (likely to host future items), otherwise penalize.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for &d in &[1u32, 2, 4, 5, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 1.0;
            }
        }
        score -= harmony * 2.0;

        // Integer-division threshold: small residuals (<= 10) are near-dead.
        if pr <= 10 {
            score += 15.0;
        } else if pr <= 20 {
            score += 5.0;
        }
    } else {
        // Perfect fit — best possible outcome.
        score -= 100.0;
    }

    // Fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 10.0;

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Harmonic bonus: residual exactly equals next item (perfect chaining).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate; early, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Prefer bins tighter than the mean (best-fit flavor with coupling).
    let res_frac = bin_residual as f64 / cap;
    if res_frac < mean_residual / cap {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate must not look too attractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual as f64 <= dead_threshold {
        // already penalized above
    } else {
        // moderate reward for tight fits relative to capacity
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 8.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (penalize opening/spreading into new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post-residual likely wasted for the next item; penalize small waste
        score += 3.0;
    }

    // Prefer bins with below-mean residual (keep large gaps available for large items).
    if (bin_residual as f64) > mean_residual {
        score += 2.5;
    } else {
        score -= 1.5;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to typical residuals and many bins exist.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 + open_bins_count as f64 * 0.8 + post_residual as f64 * 0.5;
        // If item is huge (won't fit typical residuals), soften the penalty.
        let large_item_relief = if item_size as f64 > mean_residual { 8.0 } else { 0.0 };
        score += new_bin_penalty - large_item_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item size (perfect chain placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 40.0; // exact 2-step match: strong reward
        } else {
            // penalize residual mismatch relative to next item
            score += 0.35 * diff;
            // if next item cannot fit here, penalize proportionally to tightness
            if post < nxt {
                score += 0.25 * (nxt - post);
            }
        }
        // if next item also fits leaving a tiny residue again, extra reward
        if post >= nxt && (post - nxt) < 10.0 {
            score -= 8.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates
    // from the mean in a useful way (tighter-than-mean bins get priority).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = res - mean_residual;
        score += 0.15 * dev;
        // nonlinear coupling: large positive deviation = lonely large gap
        if dev > 20.0 {
            score += 0.10 * (dev - 20.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // early in stream, new bins are cheap; later, expensive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Penalize creating unusable dead space (< 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Mild preference for tight fits overall.
    score += 0.10 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is exactly consumed.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tight.abs() * 2.0).max(-1.0) * 6.0;

    // Penalize leaving dead space that cannot fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // perfect-ish fill is great
    } else if post_residual >= 10 && post_residual < 30 {
        score += 2.0; // awkward mid gap
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (next_item_size as f64 / 100.0) * 4.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        // Spread load when many bins fit.
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (bin_capacity - item_size.min(bin_capacity)) as f64;
        // Base penalty for opening a bin, reduced late in stream or when item is large.
        score += 18.0 - 8.0 * progress - (item_size as f64 / bin_capacity as f64) * 10.0
                 - poor_fit * 0.05;
        // If many bins fit already, opening a new one is rarely right.
        if fitting_bins_count > 2 { score += 6.0; }
        // If next item is small, new bin wastes capacity.
        if next_item_size > 0 && next_item_size < 20 { score += 4.0; }
    }

    // Global state: discourage stuffing the fullest bin when mean residual is low.
    if (bin_residual as f64) > mean_residual * 1.3 && !is_new_bin {
        score += 2.5;
    } else if (bin_residual as f64) < mean_residual * 0.7 && !is_new_bin {
        score -= 1.5;
    }

    // Mild encouragement to balance bin count over time.
    score += (open_bins_count as f64).ln() * 0.3 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Small tie-breaker noise-free determinism: prefer slightly fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer leaving mid-size residuals (flexibility); late, prefer tight fits.
    let flex = 1.0 + 4.0 * (1.0 - progress) * progress; // peaks mid-stream
    let mut score = pr * (1.0 + 0.5 * flex * norm_pr * (1.0 - norm_pr));

    // Penalize large dead space quadratically, weighted by progress (late waste hurts more).
    score += norm_pr * norm_pr * cap * (0.3 + 0.9 * progress);

    // Reward tight fits (small post_residual) smoothly.
    score -= (1.0 - norm_pr).powi(3) * item_size as f64 * 0.4;

    // Lookahead coupling: if next item fits the post residual, reward this bin smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 6.0 * fit_quality * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty growing with progress.
        score += 2.0 * progress;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else {
        // Mild preference for bins in crowded pools (consolidation).
        score += (open_bins_count as f64).ln().max(0.0) * 0.3;
    }

    // Mean-residual coupling: prefer bins whose post residual deviates favorably
    // from the mean (below mean = tighter than average).
    score += 0.5 * (pr - mean_residual) * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline with progress-dependent reluctance
    // to open new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in a
    // "usable" residue class (small, reusable chunks) are rewarded.
    let r = post_residual;
    let r_mod = (r % 10) as f64;
    let r_class = (r / 10) as f64; // integer division threshold class

    // Perfect fit is supreme.
    if r == 0 {
        score -= 1000.0;
    } else {
        // Penalize awkward remainders that are hard to reuse later.
        // Remainders 1..9 are dead-space prone; multiples of 10 are friendly.
        score += (10.0 - r_mod) * 1.5;
        // Small leftover classes (r < 10) are nearly dead space.
        if r_class == 0.0 {
            score += 25.0;
        } else if r_class <= 2.0 {
            score += 8.0;
        } else if r_class <= 5.0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a harmonic pairing — reward strongly.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 120.0;
        } else if next_item_size < r {
            let pair_mod = r % next_item_size.max(1);
            // next item leaves a multiple-of-10 remainder -> good chain
            if (r - next_item_size) % 10 == 0 {
                score -= 40.0;
            }
            if pair_mod == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot fit here: leftover is final; penalize big leftovers
            score += (r as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when all
    // existing fits are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheap; later, prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If mean residual across open bins is small, reuse is scarce -> new bin ok
        score -= (mean_residual / 10.0).min(40.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Dead space: gap too small for any item (min size 1..100, but typical small items exist).
            // Penalize hard proportional to how "wasted" it is.
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
        // Perfect fit is gold.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if this is the only fitting option besides new bin, opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid bin proliferation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // Partial credit, scaled by how well it fits.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item can't use the leftover: dead space likely.
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: be a bit more liberal with new bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual relative to bin capacity.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.4 * diff;
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 150.0;
        }
        // Next item fits into the leftover space: keep this bin attractive.
        if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: bins tighter than average are worth filling.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize creating tiny dead space (< 10, unusable for min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing fits are poor (large post_residual) or none fit well.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins with decent fits win.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // new bin can serve future large items
        }
    }

    // Late in stream: consolidate into open bins, avoid proliferation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    } else {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if placing here blocks the next item from fitting
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 6.0; // placing here enables a near-perfect next fit
        }
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 20.0;
        // If many bins can fit the item, opening a new one is wasteful
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64);
        }
        // If the item leaves a very awkward residual in any bin, new bin more attractive
        if post_residual > 40 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If few bins open, opening one is cheaper
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    }

    // Prefer bins with residual far from mean (keeps diversity of bin sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Mild preference to fill fuller bins early (best-fit global bias)
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fits (small post_residual) matter more.
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 40.0 * coupling;

    // Penalize post_residual that cannot fit the lookahead item (dead space),
    // reward when the next item could still use the leftover.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (1.0 - (pr - ni) / cap);
        } else {
            let waste = (ni - pr) / cap;
            score += 12.0 * waste * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild preference for bins below mean residual (fill laggards).
    score -= 3.0 * ((mean_residual - pr) / cap);

    // Penalize opening a new bin more as stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" residue classes modulo 10 are preferred.
    let pr = post_residual.min(bin_capacity);
    let class = pr % 10;
    let harmonic_bonus = match class {
        0 => -12.0,                       // perfectly divisible leftover
        1 | 2 | 3 => 8.0,                 // nearly unusable slivers
        4 | 5 | 6 => 2.0,                 // mid-fit zone
        _ => -4.0,                        // 7..9 still fits small items
    };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual relative to capacity.
    let cap = bin_capacity as f64;
    let frac = pr as f64 / cap;
    if frac < 0.05 {
        score += 10.0; // dead space under 5 units
    } else if frac < 0.15 {
        score += 3.0;
    } else if frac < 0.5 {
        score -= 3.0;  // half-empty bin is attractive
    } else {
        score -= 1.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward exact/near-exact chaining
            let gap = pr - next_item_size;
            score -= 6.0;
            score -= (gap as f64) * 0.15;
            // harmonic chain bonus: next item leaves a multiple-of-10 remainder too
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot chain into this bin; penalize slightly more
            // if the leftover is in a bad residue class
            if class == 1 || class == 2 || class == 3 {
                score += 5.0;
            } else {
                score += 1.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: an untouched bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // neutral-ish base; slight penalty so good fits in open bins win
        score += 4.0;
        // but if open bins are fragmented (high mean residual spread),
        // opening fresh is reasonable
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 25.0 {
            score -= 6.0 + 4.0 * progress;
        }
    }

    // Prefer tighter bins overall: closeness of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 5.0;

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Perfect fit for the next item's lookahead: strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Dead space that cannot fit the next item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 400.0; // next item will perfectly fill this bin
        } else if post_residual as i64 == (next_item_size as i64 + item_size as i64) {
            score -= 250.0; // two-item chain fit
        } else {
            score += diff * 1.5; // penalize mismatch with lookahead
        }
        // If next item cannot fit here at all, mild penalty
        if nxt > post_residual as f64 {
            score += 50.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize creating small dead space (< next item size, unusable chunks).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Late in stream: prefer closing bins tightly, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open.
        score += 60.0 + 120.0 * progress + 10.0 * open_bins_count as f64;
        // But if item is huge relative to typical residuals, allow new bin.
        if item_size as f64 > mean_residual {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny slivers are wasteful unless it's a perfect fit case (already handled)
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 25.0;
            // Extra reward if next item exactly fills the remainder.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Post residual too small for next item: penalize proportional waste.
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer fuller bins (smaller residual).
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Global state: when many bins are open, discourage opening new ones.
    let new_bin = (bin_residual == bin_capacity) as f64;
    if new_bin > 0.0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).sqrt() * 2.0 + (1.0 - progress) * 10.0;
        // Opening a new bin is acceptable only if current bin fit is poor.
        score += 30.0 + pressure;
        // But if this item is huge and would leave a bad residual in any existing bin,
        // the tightness term already penalizes; soften new-bin penalty for large items.
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (fuller than average).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild time-horizon shaping: early in the stream, be more conservative with
    // creating fragmented residuals; late in the stream, just minimize residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr - 8.0 * prn * (1.0 - prn);

    // Non-linear coupling of post-residual with stream progress:
    // early on, keep bins flexible (penalize very small residuals more);
    // late in stream, squeeze tightly (reward small residuals more).
    let coupling = 0.5 + progress * progress;
    score += coupling * prn * prn * 30.0;

    // Penalize dead space relative to next item: if next item could use the residual, reward leaving room
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / (nxt * 2.0)).max(0.0);
        } else {
            score += 4.0 * (nxt - pr) / cap * 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open and residual is wasteful
    score += 0.02 * open_bins_count as f64 * prn;

    // Mild drift toward mean residual to keep bin balance smooth
    score += 0.1 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 (harmonic decade) -> very usable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual divisible by 5 but not 10 -> mildly usable
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class C: post_residual leaves remainder 1..4 -> small dead space
    else if post_residual % 10 <= 4 {
        score += 4.0;
    }

    // Integer-division threshold: post_residual in low third of capacity is dead space
    if pr < cap / 3.0 {
        score += 6.0;
    } else if pr < cap / 2.0 {
        score += 2.0;
    } else if pr >= cap * 0.75 {
        score -= 3.0; // large residual is valuable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect harmonic pairing
        } else if post_residual >= next_item_size {
            let after2 = post_residual - next_item_size;
            // harmonic class of double residual
            if after2 % 10 == 0 {
                score -= 7.0;
            } else if after2 % 5 == 0 {
                score -= 3.0;
            }
            if (after2 as f64) < cap / 4.0 {
                score += 3.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally
            score += 2.0 + (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open residuals are poor
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // average fullness of open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if pressure < 0.35 && open_bins_count > 0 {
            score -= 5.0; // open bins are too full/fragmented, fresh bin attractive
        } else {
            score += 4.0 + 6.0 * (1.0 - progress); // early stream: avoid bin proliferation
        }
        score += 0.0;
    }

    // Mild tie-breaking toward tighter bins overall
    score += (mean_residual - pr) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
