    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones over opening new.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below the mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild penalty for large remaining gap when item is small (wasteful placement).
    if (post_residual as f64) > 0.6 * bin_capacity as f64 {
        score += 15.0;
    }

    // Slight nudge toward opening a fresh bin when all fits would be terrible.
    if bin_residual == bin_capacity {
        score += 5.0; // small default cost; overridden when fits are bad
    }

    score
}

