pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        score += 8.0 + (fitting_bins_count as f64) * 2.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
    }

    // Last-chance bin bonus: avoid wasting this bin's unique fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 10.0;
        } else {
            // Dead space penalty scaled by how much next item overshoots.
            let overshoot = next_item_size as f64 - post_residual as f64;
            score += overshoot * 0.3;
        }
    }

    // Prefer using bins with small residuals relative to mean (consolidate fragmented space).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.2;

    // Slight preference for bins with more open bins competing (keep flexibility).
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Penalize very small unusable residuals.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = post;

    // Non-linear penalty on wasted residual, amplified by stream progress
    score += 40.0 * post_norm * post_norm * (0.5 + progress);

    // Cubic dead-space term: heavily punish tiny unusable residuals
    score += 60.0 * post_norm * post_norm * post_norm;

    // Reward tight fits (small post_residual relative to item size)
    score -= 30.0 * item_norm * (1.0 - post_norm);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 10.0 * post_norm * (next_item_size as f64 / cap);
    }

    // Smooth interaction with mean residual: prefer bins near mean to preserve spread
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate handling: penalize opening new bins unless current fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - item_norm) - 20.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 2.0 * open_bins_count as f64 * post_norm * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // classes (multiples of common item sizes) waste less future capacity.
    let pr = post_residual;
    let nice = if pr == 0 { 12.0 }
        else if pr % 10 == 0 { 6.0 }
        else if pr % 5 == 0 { 3.0 }
        else if pr % 25 == 0 { 4.0 }
        else if pr <= 10 { 1.0 }
        else { 0.0 };
    score -= nice;

    // Dead-space penalty: small awkward leftovers are nearly unusable.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward a post_residual that exactly fits the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 15.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        } else if pr < next_item_size && pr >= 10 {
            score += 3.0; // leftover likely dead for the lookahead
        }
        // Harmonic class match: next item divides post_residual evenly
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    // (large item relative to residual) or stream is early.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 + (1.0 - tight) * 40.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && pr == 0 {
            score -= 10.0;
        }
    }

    // Prefer tighter fills overall: scale by how full the bin becomes.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Slight pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 + (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongly reward (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is too small for the smallest plausible item (1..~12).
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 25.0;
    }

    // Medium gaps that cannot fit the lookahead item are also dead-ish.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward leaving room for the next item (good coupling with lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 30.0 + open_bins_count as f64 * 8.0 + progress * 20.0;
        // Allow new bin only if mean residual across open bins is very low
        // (i.e., open bins are nearly full anyway).
        score -= mean_residual.max(0.0) * 0.4;
    } else {
        // Mild reward for filling existing bins when pressure is high.
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins with tighter residual (best-fit flavor) among open bins.
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches next item (2-step lookahead)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving residual slightly larger than next item (dead space trap)
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer minimal waste
        score += 10.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize very small unusable residuals unless perfectly matched
    if post_residual < 10 && next_item_size > post_residual {
        score += 30.0;
    }

    // Late stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 50.0; // next item nearly fills a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is good, but exact/very tight fits deserve extra reward).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that no future item (min size 1..10) can realistically fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // small awkward gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // next item still fits: mild reward proportional to leftover after next item
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64).min(20.0) * 0.3;
        } else {
            // next item won't fit here: penalize leaving large residuals that block chaining
            score += 6.0;
        }
    }

    // New-bin candidate: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // baseline penalty so open bins usually win, reduced late in stream or with many open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 12.0;
        // if mean residual across open bins is small, open bins are crowded -> new bin more attractive
        if mean_residual < item_size as f64 + 5.0 {
            penalty -= 10.0;
        }
        // late in the stream, avoid spawning bins that will stay nearly empty
        penalty += progress * 10.0;
        // many open bins already: prefer filling them
        penalty += (open_bins_count as f64).min(10.0) * 0.8;
        // large items deserve fresh space
        if item_size > bin_capacity / 2 {
            penalty -= 6.0;
        }
        score += penalty;
    }

    // Mild global pressure: when few fitting bins exist, keep residuals usable.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Prefer bins whose residual is close to the item (relative tightness).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial in progress: later in the stream, tighten packing more
    let tightness = 1.0 + 3.0 * progress * progress + 2.0 * progress;

    // Penalize residual scaled by tightness (dead space matters more later)
    score += 0.05 * (post_residual as f64).powf(1.4) * tightness * 0.1;

    // Reward near-perfect fits (low post_residual) with a smooth quadratic bonus
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * (1.0 - fit_frac) * (1.0 - fit_frac);

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward it smoothly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 5.0 * (1.0 - gap / bin_capacity as f64).powi(2);
    }

    // Prefer bins whose residual is close to the mean (keeps residual distribution balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Smooth penalty for spreading across too many open bins
    score += 0.2 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize mildly unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 4.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity fractions.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead-space penalty: tiny leftovers are nearly useless.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual <= 5 {
        score += 30.0; // worst dead space class
    } else if post_residual <= 10 {
        score += 15.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 pair better with
    // typical item sizes (multiples of 10).
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: how many "average small items" fit afterward.
    let slots = post_residual / 20; // coarse slot count
    match slots {
        0 => score += 20.0,          // residual < 20: near-dead
        1 => score += 5.0,
        2 => score -= 3.0,           // sweet spot
        3 => score -= 6.0,
        _ => score -= 2.0,           // large residual: keep for big items
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus scaled by how snugly the next item lands.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 12.0 + 10.0 * snug;
            // Harmonic match: both multiples of 10 -> strong pairing.
            if next_item_size % 10 == 0 && post_residual % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't chain here; penalize proportionally to waste.
            score += 8.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins are tight.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base new-bin score: worse than any reasonable fit.
        score = cap * 0.8 - 30.0 * pressure + mean_residual * 0.2;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild phase awareness: early stream, keep bins flexible.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - phase) * frac * 5.0;

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += (post - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are >= 10 in classic streams; treat < 10 as pure waste).
    if post_residual < 10 {
        score -= 1000.0; // perfect or near-perfect closure
    } else if post_residual < 20 {
        score += 60.0;   // small dead space: strongly penalize
    } else if post_residual < 35 {
        score += 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.3;
    }

    // Penalize creating a residual that is too small for the next item,
    // wasting the chance to pair them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bin pressure: discourage spreading across many bins; but if this
    // is the ONLY fitting bin, strongly favor using it over opening a new one.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins would leave bad dead space
        // or when bin count is low and item is small.
        if post_residual < 10 {
            score -= 400.0; // perfect fit in fresh bin is fine
        } else {
            score += 120.0 + open_bins_count as f64 * -2.0 + mean_residual * 1.5;
        }
    }

    // Late-stream caution: fewer bins left to amortize, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= fill * 30.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let next = next_item_size as f64;

    // --- 2-step lookahead coupling ---
    if next > 0.0 {
        if post_residual as f64 >= next {
            // Reward exact-ish match: post_residual that next item can fill tightly.
            let gap = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 40.0 * (1.0 - gap).max(0.0);
            // Strong reward for perfect 2-item fill (post_residual == next_item_size)
            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            // Post-residual too small for the next item: dead space risk.
            let waste = (next - post_residual as f64) / bin_capacity as f64;
            score += 25.0 * waste * 100.0;
        }
    } else {
        // Last item: prefer the fullest bin.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // --- Mean residual coupling ---
    // Favor bins tighter than the mean (good fits), penalize looser ones.
    let mr = if is_new_bin { mean_residual } else { mean_residual };
    score += 0.5 * ((post_residual as f64) - mr);

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && !is_new_bin {
        // This is the only bin that fits; strongly prefer using it.
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Opening a new bin is wasteful unless it enables a great 2-step fill
        // or nothing fits well. Base penalty grows with number of open bins
        // (consolidate when many bins are open).
        let mut pen = 30.0 + 5.0 * open_bins_count as f64;
        if next > 0.0 && bin_capacity as f64 - next >= item_size as f64 {
            // New bin would leave room for the next item: soften penalty.
            pen -= 20.0;
        }
        if fitting_bins_count == 0 {
            pen = 0.0; // forced open
        }
        score += pen;
    }

    // --- Dead-space penalty for tiny unusable remainders ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild progress adaptation: later in the stream, be more conservative
    // about leaving large gaps.
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Reward tight fits: squashed residual penalty.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 30.0;

    // Lookahead: strongly reward if next item fits exactly/into post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item can slot in: reward proportionally to how well it fills
            let fill = 1.0 - ((post - nxt) / cap);
            score -= 12.0 * fill;
        } else {
            // next item won't fit here: slight penalty for leaving a small unusable gap
            score += 4.0 * (1.0 - (post / cap));
        }
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with slack: encourage consolidating into fullest bins.
    let slack = mean_residual - post;
    score += slack * 0.15;

    // Penalize opening a new bin unless item is large relative to capacity and
    // existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let frac_open = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin is attractive when item is big and few bins fit
        let big_item = item_size as f64 / cap;
        score -= 18.0 * big_item;
        // but discourage hoarding open bins early in the stream
        score += 3.0 * frac_open * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0; // opening a new bin when others fit is costly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight packing), normalized.
    let mut score = pr / cap;

    // Smooth non-linear dead-space penalty: squared normalized residual,
    // weighted by stream progress (dead space hurts more later in stream).
    let x = pr / cap;
    score += 1.4 * x * x * (0.5 + progress);

    // Tight-fit reward: smooth Gaussian-like coupling of post_residual with item size.
    let fit_center = item_size as f64 * 0.12 + 2.0;
    let tightness = (-(pr as f64 - fit_center) * (pr as f64 - fit_center)) / (2.0 * (fit_center * fit_center + 9.0));
    score -= 0.9 * (-tightness).exp();

    // Lookahead coupling: reward if next item fits into post_residual (chain packing),
    // penalize if post_residual is just barely below next item (unusable sliver).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            // smooth reward for leaving exactly enough room for the next item
            let gap = (pr - n) / cap;
            score -= 0.7 * (-gap * gap * 60.0).exp();
        } else {
            // sliver penalty grows as post_residual approaches next item size from below
            let miss = (pr - n + 1.0).abs() / cap;
            score += 0.5 * (-miss * miss * 40.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin — unless it would leave a large unusable residue.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = pr / cap;
        score -= 1.2 * (1.0 - waste) * (1.0 - progress * 0.5);
    }

    // New-bin candidate adjustment: empty bins should be penalized mildly when
    // decent fits exist, but become attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score += 0.35 - 0.5 * fragmentation * progress;
    } else {
        // Mild preference for bins whose residual is close to the mean (balance).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 0.15 * dev * dev;
    }

    // Open-bin count pressure: more open bins => favor consolidating into existing bins.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Smooth stream-progress interaction: as stream advances, tighten preference
    // for minimal post_residual via cubic coupling.
    score += 0.3 * x * x * x * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize dead space into
    // capacity-fraction classes. Residuals in the lowest class (<= 10) are
    // near-perfect fits and get the strongest reward.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual (harmonic bands of C/4).
    let band = post_residual / (bin_capacity / 4).max(1); // 0..3
    score -= match band {
        0 => 40.0,               // post_residual <= 24: excellent closure
        1 => 15.0,               // <= 49: decent
        2 => 0.0,                // <= 74: mediocre
        _ => 10.0,               // large leftover: penalize slightly
    };

    // Fine-grained modulo logic: residual divisible structure
    let m = post_residual % 10;
    if post_residual > 0 && m == 0 {
        score -= 12.0; // residual is a multiple of 10: future small items fit cleanly
    } else if m >= 8 {
        score += 6.0; // awkward sliver
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            // Next item fits: reward proportionally to how snugly it lands.
            let snug = 1.0 - (pr - ns) / cap;
            score -= 10.0 + 25.0 * snug;
            // Harmonic pairing: post_residual == next_item_size exactly
            if (pr - ns).abs() < 0.5 {
                score -= 30.0; // perfect two-item chain
            }
        } else {
            // Next item cannot use this residual: dead space risk grows
            // with how far the overshoot is, quantized by integer division.
            let overshoot_band = (next_item_size - post_residual) / 20;
            score += 8.0 + 10.0 * overshoot_band as f64;
        }
    } else {
        // Last item of the stream: minimize residual hard.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.1 * (bin_residual as f64 - pr);
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current item is large relative to capacity
    // and the fit in open bins would leave a big odd remainder.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        // Large items start fresh bins eagerly; small items should reuse.
        score -= 35.0 * fill - 10.0;
        // If many bins are open and mean residual is high, discourage sprawl.
        score += 0.05 * open_bins_count as f64 + 0.3 * (mean_residual - pr).max(0.0);
        // But if no open bin fits at all, this call is the only option anyway;
        // keep its score low via the large-item reward above.
    }

    // Progress term: early in the stream, tolerate slight looseness to keep
    // bins flexible; late in the stream, prioritize tight closure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - pr / cap);

    // Mild preference for compacting across few open bins.
    score += 0.02 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    // so loose bins stay available for large future items.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot hold even the smallest plausible item is wasted space.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 60.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space relative to next item lookahead: residual that cannot fit
    // the known next item is likely stranded.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Slight preference for bins tighter than average (pack dense bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Post residual large enough to hold next item: reward proportionally
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_frac = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * fit_frac;
    } else if next_item_size > 0 {
        // Dead space: post_residual too small for next item
        let gap = next_item_size as f64 - post_residual as f64;
        score += 4.0 * gap;
    }

    // Prefer bins tighter than the mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strong bonus to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bins are poorly filled
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Slight progression term: later in stream, prefer tight packing more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly as it becomes a better fit.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // Lookahead: penalize bins whose post_residual cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward residual that matches next item size closely
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 25.0;
        } else {
            // dead space for the lookahead item
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets a moderate penalty unless
    // current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // late in the stream, opening fresh bins is more acceptable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Global state coupling: prefer filling bins below mean residual
    // (i.e., bins with less room than average get slight preference).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Time horizon: as stream progresses, tighten preference for tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += fit_ratio * progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 0.5 * progress * norm_pr * pr;

    // Penalize dead space that cannot plausibly hold future items
    let dead = if next_item_size > 0 { (next_item_size as f64 - pr).max(0.0) } else { pr };
    score += dead * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly as stream matures
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0 * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.2 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantized by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 0..8 harmonic class

    // Penalize dead space super-linearly once below the smallest useful slot.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (8.0 - class);
    }

    // Reward if the lookahead item fits exactly into the post residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward when post residual is a harmonic multiple of next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by class
            score += 4.0 + class;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer tighter bins among many fitting bins (best-fit core), modulated by mean residual.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Harmonic integer-division threshold on residual: bins with residual in [50,100) class
    let half = bin_capacity / 2;
    if bin_residual > half && post_residual > 0 && post_residual < item_size {
        score += 10.0; // splitting a big residual into two unusable pieces
    }

    // Late in the stream, consolidate: penalize spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress > 0.5 {
        score += 2.0 * (open_bins_count as f64 - mean_residual / 10.0).max(0.0);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 35.0 - 10.0 * (fitting_bins_count as f64).min(3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

