    } else if post_residual < 20 {
        score -= 400.0;  // nearly unusable gap
    } else if post_residual < 30 {
        score -= 120.0;
    } else if post_residual < 50 {
        score += 30.0;   // moderately wasteful
    }

    // Penalize bins whose residual is already small (tight fits preferred there).
    if bin_residual <= item_size + 15 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: discourage opening a new bin unless the fit is genuinely bad.
    if bin_residual == bin_capacity {
        score += 250.0 + open_bins_count as f64 * 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 5.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
