}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with slight superlinearity
    // to punish dead space that can never be reused.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly or
    // nearly matches the next item's size (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can chain into this bin: reward proportional to closeness.
            score -= (bin_capacity as f64 - diff) * 0.5;
            if diff < 1.0 {
                score -= 40.0; // perfect chain bonus
            } else if diff < 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here: mild penalty scaled by leftover gap.
            score += diff * 0.1;
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // space; penalize wasting them on loose fits.
    let res = post_residual as f64;
    if res > mean_residual * 1.2 {
        score += (res - mean_residual) * 0.3;
    } else if res < mean_residual * 0.5 {
        score -= mean_residual * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call happens with full residual and item leaves big gap
    // elsewhere); make fresh bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead suggests the new bin would serve a chain well,
        // soften the penalty.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 3.0 {
            score -= 45.0;
        }
        // Early stream: opening bins cheaply is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Many open bins: discourage spreading items thin.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small post-residuals that create dead space unusable by future items.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if dead < 0.10 {
            score += (0.10 - dead) * 80.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= (slack as f64 / bin_capacity as f64) * 25.0;
    } else if next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are already open.
    let new_bin = (bin_residual == bin_capacity) as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64 / 8.0).min(1.5);
    score += new_bin * (10.0 + 20.0 * open_pressure * (1.0 - 0.5 * progress));

    // Pull toward bins with residuals near the mean (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early in the stream, encourage consolidation into few bins.
    if progress < 0.3 {
        score += new_bin * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap; // how full the bin becomes

    // Base: prefer tight fits, penalize residual with a non-linear (quartic-ish) term
    let mut score = pr * (1.0 + 0.9 * progress) + cap * 0.35 * (1.0 - tightness).powi(4);

    // Smooth polynomial coupling between post_residual and stream progress
    let coupling = pr / cap;
    score += 25.0 * coupling * coupling * (1.0 - coupling) * (0.5 + progress);

    // Lookahead: reward if the next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - pr / cap) * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Prefer bins with residuals below the mean (consolidate dead space)
    score += 0.15 * (pr - mean_residual);

    // Slight penalty for opening new bins as stream progresses, unless residual is tiny
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) - 10.0 * progress;
        if pr < 20.0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // modular classes (multiples of common item sizes) deserve a bonus.
    let pr = post_residual;
    let useful = |r: u32| -> f64 {
        if r == 0 { return 3.0; } // perfect fit is ideal
        // class by integer division into capacity fractions
        let frac = (r * 8) / bin_capacity; // 0..7 harmonic octave
        let octave_bonus: f64 = match frac {
            0 => 2.0,   // tiny dead space
            1 => 1.0,
            2 => 0.5,
            3 => 0.0,
            4 => 0.5,
            5 => 1.0,
            6 => 1.5,
            _ => 2.0,   // large residual, still reusable
        };
        // modulo arithmetic: residuals divisible by common item sizes are reusable
        let mod_bonus = if r % 10 == 0 { 2.0 }
            else if r % 20 == 0 { 1.5 }
            else if r % 5 == 0 { 1.0 }
            else if r % 25 == 0 { 0.8 }
            else { 0.0 };
        octave_bonus + mod_bonus
    };
    score -= useful(pr);

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 6.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 3.0 - slack * 0.05;
            // harmonic match: next item shares a divisor class with post residual
            if pr % next_item_size.max(1) == 0 { score -= 2.0; }
        } else {
            // next item cannot use this bin's leftover: penalize wasting space
            score += 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Many open bins: encourage closing bins tightly (low post residual).
    if open_bins_count > 3 {
        score += mean_residual * 0.05;
        score -= (bin_residual as f64 - mean_residual) * 0.03;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * 0.15 + progress * 2.0;
        score += 10.0 - pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 3.0; // fresh bin will pair item + next item well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 interface => min size 1) are pure waste, but
    // gaps that can still hold a plausible item are fine.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, unreachable normally
    }

    // Penalize "unusable" gaps: post_residual > 0 but smaller than the
    // next item and smaller than a typical small item => dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver => dead space penalty
    }

    // Reward exact/very tight fits relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 20.0 / (1.0 + tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64 + 1.0);
        let pressure = 8.0 + 20.0 * (open_bins_count as f64 / 10.0).min(2.0);
        score += pressure * (1.0 - 0.5 * progress);
        // If the next item would fit in this fresh bin's leftover after
        // placing current item... fresh bin leftover is huge anyway; slight
        // bonus if next item is large and no bin can hold both.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    } else {
        // Favor bins whose residual matches the next item's needs (lookahead).
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 0.15 * gap;
        }
    }

    // Prefer bins below mean residual (tighter bins get used first),
    // spreading load evenly keeps mean residual low.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for leaving residual just below next_item_size
    // (blocking the lookahead item in this bin).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize small post_residuals (dead space).
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.5 * waste * (next_item_size as f64 / bin_capacity as f64);
            }
        }
    }

    // Relative to mean residual: prefer bins whose post_residual deviates favorably.
    let cap = bin_capacity as f64;
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize leaving large unusable gaps relative to minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Late in the stream, consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual - post_residual) as f64 / cap;

    // New empty bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0 + 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * 0.35 * (item_size as f64 / bin_capacity as f64);

    // Lookahead: reward if the next item can also fit in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating dead space the known next item cannot use,
        // scaled by how "wasted" the leftover is.
        score += 0.10 * (post_residual as f64 / next_item_size as f64).min(1.0) * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation onto existing bins.
    score += 0.02 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are already fuller
    // (residual below mean) to balance load.
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream be more willing to open new bins
    // (keep flexibility); late in the stream pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, reduced early, increased late.
        score += 18.0 - 14.0 * (1.0 - progress);
        // Opening a new bin is attractive if all current fits are terrible
        // (post_residual would be tiny in every existing bin).
        score -= 4.0 * (1.0 - (pr / bin_capacity as f64));
    } else {
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let t = progress;
    // Smooth interaction: dead-space penalty grows non-linearly as stream progresses
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * t * t) * cap;
    score += 0.35 * coupling;

    // Penalize residuals that cannot fit the lookahead item (smooth logistic-like term)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - pr) / cap;
        let penalty = 1.0 / (1.0 + (-6.0 * gap).exp()); // ~0 if fits, ~1 if not
        score += 12.0 * (0.3 + 0.7 * t) * penalty;
        // Reward if lookahead fits exactly-ish (smooth quadratic closeness)
        let fit_quality = 1.0 - (pr - n) / cap;
        score -= 6.0 * fit_quality * fit_quality * (1.0 - t);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - t) + 8.0;
    }

    // Mild preference for bins tighter than the mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    // Encourage consolidation early when many bins are open
    let density = open_bins_count as f64 / (1.0 + t * 10.0);
    score += 0.05 * density * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: residuals that are
    // multiples of common item sizes are reusable, odd remainders are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals divisible by 10 (harmonic class alignment)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score += 2.0;
    }

    // Penalize small dead space (< 10) which is unusable for items >= 1..100 typical range
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            // harmonic class of the double leftover
            score -= if rem2 % 10 == 0 { 12.0 } else { 3.0 };
        } else {
            // next item won't fit here; penalize slightly
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fraction-of-capacity thresholds via integer division
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 4.0; // keep big residuals alive
    } else if post_residual >= quarter {
        score += 1.0;
    } else if post_residual > 0 {
        score += 6.0; // small residual bins get deprioritized unless perfect/last-chance
    }

    // Prefer bins tighter than the mean residual (best-fit flavor, normalized)
    score += (pr - mean_residual) * 0.15;

    // New-bin candidate: mild default preference; override only when open bins are bad.
    if bin_residual == bin_capacity {
        score = 20.0
            + pr * 0.1
            - if next_item_size > 0 && next_item_size <= bin_capacity / 2 { 5.0 } else { 0.0 }
            + (open_bins_count as f64) * 0.5;
        if fitting_bins_count <= 1 {
            score += 10.0; // discourage opening new bin when this is the only fitting bin
        }
    }

    // Slight stream-progression pressure: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible future item
    // (items in [1,100]) are wasted space. Penalize gaps below a usable threshold.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item cannot fit but could have fit elsewhere (bad sequencing).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (applied to the empty-bin candidate implicitly via its high residual, but
    // add explicit coupling).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins already open.
        score += open_bins_count as f64 * (2.0 + 3.0 * progress);
    } else {
        // Using an existing bin relieves pressure slightly.
        score -= open_bins_count.min(10) as f64 * 0.5;
    }

    // Prefer bins with below-mean residual (consolidate space into fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect pairing — huge reward
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * snug;
        } else {
            // next item does NOT fit: penalize wasted residual that next item can't use
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }

        // If post_residual is too small for the smallest plausible next item,
        // treat it as dead space.
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // last item: just close gaps
        score -= 20.0 * tightness;
    }

    // Compare against mean residual: prefer bins that keep the fleet balanced
    // unless this is a tight fit (then imbalance is fine).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // many options: be pickier about fit quality
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: an empty bin should only win when the item
    // is large and would leave a very fragmented open bin.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin normally...
        score += 30.0;
        // ...but reward it for large items or when existing bins are crowded.
        score -= 45.0 * large_item * large_item;
        score -= 10.0 * (mean_residual / bin_capacity as f64);
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If next item pairs well with a fresh residual of (C - item), encourage it
        if next_item_size > 0 {
            let fresh = bin_capacity - item_size;
            if next_item_size <= fresh {
                score -= 8.0;
            }
        }
    }

    // Slight preference for filling more-open bins early (reduces bin count pressure)
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual is already the base).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold a typical future item.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect chain fit bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into emptier bins.
    if open_bins_count > 4 {
        let rel = bin_residual as f64 / bin_capacity as f64;
        score += 10.0 * (rel - mean_residual / bin_capacity as f64).abs();
    }

    // New-bin candidate handling: only attractive when the item is large
    // or the current bin would leave a useless remainder.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (1.0 + 0.5 * progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Mild time-horizon scaling: late in the stream, waste is costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling: dead-space penalty grows with progress
    let waste_curve = norm_pr * norm_pr * (0.5 + progress);
    score += 40.0 * waste_curve;
    // reward tight fits (small post residual) more strongly later in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);
    // last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - (nxt / cap));
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }
    // mild pressure toward consolidating into fewer bins
    score += (open_bins_count as f64).ln() * (1.0 - norm_pr) * 2.0;
    // deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;
    // new-bin candidate: penalize opening a new bin unless residual would be well used
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space quality classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: near-perfect fit (residual <= 10) -> strong reward
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Modulo arithmetic on residual: residuals that are "usable" sizes
    // (multiples of small common item sizes) are more likely to be filled later.
    let usable = (post_residual % 10 == 0) as f64
        + (post_residual % 5 == 0) as f64
        + (post_residual % 20 == 0) as f64;
    score -= 4.0 * usable;

    // Dead space penalty: residual that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slightly penalize leaving mid-range residual
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into bins with small residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // Mean residual deviation: prefer bins below mean residual (tighter bins)
    score -= 0.3 * (mean_residual - pr);

    // New-bin candidate: neutral-ish baseline, penalize slightly unless current
    // options are bad (large post_residual elsewhere already penalized).
    if bin_residual == bin_capacity {
        score = 45.0 + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 50.0; // opening a bin is fine when alternatives are scarce
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, unusable gap)
    // is heavily penalized. Dead zone: gap too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tight fit relative to residual: reward filling most of the bin's space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead synergy: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item can't use the gap -> mild dead-space penalty.
        score += 10.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins); when few bins are open, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: apply pressure scaled by stream progress.
        score += 12.0 * pressure * (0.5 + 0.5 * progress);
    } else {
        // Existing bin: reward using it, more so under high pressure.
        score -= 6.0 * pressure.min(6.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's an outlier
    // small gap bin; using it consolidates fragmentation.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.15 * (res - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward tight chaining: small slack after the next item too.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.6 * chain_slack;
        } else {
            // Penalize dead space that the next item cannot use,
            // worse when the dead space is small (nearly-wasted sliver).
            let dead = next_item_size - post_residual;
            score += 10.0 + 0.5 * dead as f64;
        }
        // Bonus if the bin after placement becomes an exact host for next item.
        if post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Penalize large unusable residual relative to smallest plausible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: open a fresh bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so existing bins with decent fits win.
        score += 40.0;
        // But if current bin is a bad host (post residual leaves a sliver the
        // next item can't use), opening a new bin becomes attractive.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 70.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Prefer filling bins with below-average residual (tighter bins first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for bins that are already heavily loaded.
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 25.0;

    // Penalize dead space that is too small for typical items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a residual too small for the known next item.
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // When many bins can fit the item, prefer the tightest; add mild penalty
    // to spread pressure across the choice set.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state coupling: if mean residual is large, be pickier about
    // leaving large post_residuals (space is abundant, waste is relative).
    score += 0.10 * (post_residual as f64 - mean_residual).max(0.0);

    // Time horizon: early in the stream, opening new bins is cheap; late in
    // the stream, consolidate to avoid spreading items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item is large and few bins
        // fit it, or when open bins have small residuals (poor fits).
        let avg_fit_quality = mean_residual / bin_capacity as f64;
        let new_bin_bonus = 15.0 * (1.0 - avg_fit_quality) * fit_ratio;
        score -= new_bin_bonus;
        // But discourage opening new bins when many bins already fit the item.
        score += 10.0 * (fitting_bins_count as f64);
        // Late stream: prefer packing into existing bins.
        score += progress * 25.0;
    }

    // Slight preference for bins with residual close to item (exactness).
    let diff = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    // Early stream: penalize large residuals mildly; late stream: penalize strongly
    let progress_weight = 0.5 + 1.5 * p2 + p3;
    score += progress_weight * pr_norm * pr_norm * cap * 0.1;

    // Reward tight fits (small post_residual) with smooth decay
    let tightness = (-pr_norm * 4.0).exp();
    score -= 8.0 * tightness * (0.5 + p3);

    // Penalize when this placement creates dead space that next item cannot use
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap > 0.0 {
            let gap_norm = gap / cap;
            // smooth quadratic penalty for unusable gap
            score += 6.0 * gap_norm * gap_norm * cap * (0.3 + progress);
        } else {
            // next item fits exactly or better: reward
            score -= 4.0 * (1.0 - gap.abs() / cap) * (0.5 + p2);
        }
    }

    // Last-chance bin bonus: smooth in fitting_bins_count
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 10.0 * scarcity * (0.4 + 0.6 * p2);
    }

    // Penalize opening new bins when many bins already open and mean residual is high
    let mean_norm = mean_residual / cap;
    score += (open_bins_count as f64).sqrt() * mean_norm * (1.0 + p3) * 2.0;

    // Smooth new-bin candidate bias: empty bin gets slight late-stream penalty
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * p2 + 5.0 * p3;
        // but if item is large relative to capacity, opening fresh bin is smoother
        let big = item_size as f64 / cap;
        score -= 8.0 * big * big * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // modular classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for s in [10u32, 20, 25, 50, 100] {
            if s <= pr && pr % s == 0 {
                harmony += 6.0;
            }
        }
        // residual that is itself within typical item range [1,100] is reusable
        if pr <= 80 {
            harmony += (80 - pr) as f64 * 0.3;
        } else {
            harmony -= (pr - 80) as f64 * 0.5;
        }
        score -= harmony;
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: penalize leaving it unused only if fit is decent.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 10.0;
    }

    // Discourage opening new bins when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        // new-bin candidate: base preference for new bin is low unless residuals fragmented
        score += 8.0;
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 20.0; // next item cannot fit an empty... impossible, but guard
        }
    }

    // Progress-aware mild scaling of tightness reward.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (post_residual as f64 / cap) * 4.0 * (1.0 - progress);

    // Penalize residuals in dead zone (just below smallest plausible item class).
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any plausible
    // future item (<= 10) are pure waste; push such placements down hard.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Reward tight fits: post_residual near zero is a nearly perfect fit.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward residuals that exactly accommodate the lookahead item (k=2).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff <= 2 {
            score -= 25.0;
        } else if (post_residual as f64) < next_item_size as f64 && post_residual < 10 {
            score += 20.0; // kills space for the next item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones;
    // for the fresh-bin candidate (residual == capacity) add pressure instead.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // Opening a new bin is attractive only if the item leaves a large gap
        // in every existing bin; if mean residual is small, favor existing bins.
        score += 0.3 * mean_residual;
    }

    // Mild preference for filling bins with smaller residuals first.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill, close the bin
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        if gap as u32 == 0 {
            score -= 250.0; // exact chain: post_residual == next_item_size
        } else if post_residual >= next_item_size {
            score -= 40.0; // next item can still fit here
        } else {
            score += 60.0; // dead space relative to lookahead
        }
    }

    // Penalize bins far below mean residual (wasting large holes) mildly.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: make it costly unless the item is huge and no good fit exists.
    if bin_residual == bin_capacity {
        score += 200.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 150.0; // big items are fine in fresh bins
        }
    }

    // Late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward placements that fill the bin well.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space with diminishing returns (dead space > 30 becomes costly).
    let dead = post_residual as f64;
    if dead > 30.0 {
        score += 0.35 * (dead - 30.0);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to wasted potential.
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bonus: only one fitting bin -> avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or late in the stream where consolidation is less valuable.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late_bonus = 10.0 * progress;
        // Base new-bin cost keeps it slightly worse than a good existing fit,
        // but lets it win when fits are poor.
        score += 6.0 - desperation * 20.0 - late_bonus
            + 0.15 * (mean_residual - post_residual as f64).abs();
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // bins below the mean residual (consolidate space).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev * (open_bins_count as f64).ln();
    }

    // Early stream: slightly prefer filling bins tightly to build good partial sums.
    score -= (1.0 - progress) * 2.0 * fit_ratio;

    // Small penalty scaled by item size to break ties toward smaller items in tighter bins.
    score += 0.01 * item_size as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let mut score = norm_post * (1.0 + 0.8 * progress * norm_post);
    // smooth interaction: penalize large residuals late in stream
    score += 0.5 * norm_post * norm_post * progress;
    // reward tight fits (small post residual)
    score -= 0.6 * (1.0 - norm_post).powi(3);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 0.4;
    }
    // lookahead: if next item fits post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= norm_post * bin_capacity as f64 {
        score -= 0.3 * (next_item_size as f64 / bin_capacity as f64);
    }
    // dead space penalty relative to mean residual
    score += 0.2 * (norm_post - mean_residual / bin_capacity as f64).abs();
    // new-bin candidate handling: mildly penalize opening new bins early
    if bin_residual == bin_capacity {
        score += 0.3 + 0.5 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space buckets.
    // Residuals <= 10 are "perfect" (unusable sliver), reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 35 {
        score -= 5.0;
    } else {
        // Large leftover: penalize proportionally to how "wasteful" the class is
        score += (post_residual as f64 - 35.0) * 0.35;
    }

    // Harmonic class via modulo: residuals near multiples of 25 pair well
    // with common item sizes (25/50/75 splits of capacity).
    let m = post_residual % 25;
    if m == 0 {
        score -= 8.0;
    } else if m <= 5 {
        score -= 3.0;
    } else {
        score += m as f64 * 0.2;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(30.0) * 0.3;
        } else {
            // next item won't fit here: mildly penalize leaving big gaps
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive
    // only when the item is large relative to capacity or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 12.0 - 30.0 * size_frac - 10.0 * (1.0 - progress);
        if size_frac > 0.6 {
            score -= 15.0; // big items deserve a fresh bin
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it is
    // "tight" — using it preserves flexibility elsewhere.
    score -= (mean_residual - post_residual as f64).clamp(-20.0, 20.0) * 0.25;

    // Small penalty for many open bins: consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but treat tiny unusable
    // gaps (< 10) as dead space and penalize them extra.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // dead space: gap too small for any item
    }

    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits the post-residual gap,
    // this placement is valuable (chain packing); otherwise the gap is
    // likely wasted, so penalize proportionally to gap size.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += 0.3 * (post_residual as f64);
        }
    }

    // Perfect-fill potential: residual exactly matches a "nice" divisible
    // chunk (post_residual is a multiple of 10) is slightly favored.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new bins / partially filled ones; encourage consolidating fills.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean-residual alignment: bins whose residual is near the mean are
    // "typical" targets; deviating bins (nearly full or nearly empty)
    // get mild penalties so we fill balanced bins first.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: an empty bin should only win when the current
    // item is large relative to capacity and no good tight fit exists.
    if bin_residual == bin_capacity {
        score += 60.0
            - 0.4 * (item_size as f64)
            + pressure * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large consecutive items in a fresh bin
        }
    }

    // Slight progression term: late in the stream, be greedier about
    // exact fits since fewer items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead match strongly rewarded
        score -= 30.0 * (1.0 - diff / cap).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item fits exactly into residual after placement, big bonus
        if next_item_size <= post_residual {
            score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize dead space relative to mean residual
            score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin unless current bins are nearly full / poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin penalized more when many open bins exist or mean residual is large
        score += 15.0 + 0.5 * open_bins_count as f64 + 0.1 * mean_residual - 5.0 * progress;
    } else {
        // Reward filling existing bins tightly
        score -= 0.1 * item_size as f64;
    }

    // Slight penalty for very small post_residual waste that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that are too small for the
    // smallest plausible item (1..100 range, assume >= 10 typical) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is excellent; if post-residual is just barely too small
    // for the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing capacity rather than opening new bins.
    let reuse_pressure = mean_residual / bin_capacity as f64;
    score -= 8.0 * reuse_pressure * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * fit_ratio;
    score -= progress * 5.0;

    // New-bin candidate guard: an empty bin should only win when the fit here
    // is poor or the bin is nearly full anyway.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - fit_ratio);
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_post * (1.0 + 0.8 * progress) - 0.35 * norm_post * norm_post * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_post).powi(3) * (0.6 + 0.9 * progress);

    // Penalize dead space that is too small to be useful for typical items
    if post > 0.0 && post < 10.0 {
        score += 0.5 * (10.0 - post) / 10.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.3 * (nxt / cap) * (1.0 + progress);
        } else {
            score += 0.2 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * ((open_bins_count as f64).ln() + 1.0) * (norm_post - mean_residual / cap).abs();

    // New-bin candidate baseline: keep it slightly worse than decent fits
    if bin_residual == bin_capacity {
        score += 0.6 + 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "small dead-space" class (post_residual <= 10) are highly desirable.
    let dead_class = post_residual / 10; // 0..=9 harmonic classes on residual
    match dead_class {
        0 => score -= 60.0,               // near-perfect fill
        1 => score -= 25.0,               // leftover 10..19, still useful for min items
        2 => score -= 8.0,                // leftover 20..29
        3 => score += 6.0,                // leftover 30..39
        4 => score += 15.0,               // 40..49 starts wasting space
        5 => score += 26.0,
        _ => score += 35.0 + 2.0 * (dead_class as f64 - 6.0),
    }

    // Integer-division threshold coupling: does the NEXT item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains into this bin: reward, scaled by how tightly it fits.
            let tightness = (post_residual - next_item_size) as f64;
            score -= 20.0 + 30.0 * (1.0 - tightness / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize proportional to waste.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap.min(60.0) * 0.5;
        }
        // Modulo harmony: if next_item_size and post_residual share residue classes
        // mod 10, leftover is more likely reusable by future items of that class.
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: pure fill, reward small post_residual extra.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins with high mean residual: discourage spreading waste,
    // prefer bins below the mean (consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (post_residual as f64) < mean_residual {
        score -= 8.0 * (1.0 - progress * 0.5);
    } else {
        score += 4.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual for an empty bin is just capacity; neutral baseline,
    // but push it up so it only wins when open bins are penalized heavily).
    if bin_residual == bin_capacity {
        score += 55.0 - 40.0 * (fitting_bins_count as f64).recip().min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual that is too small to hold the next item
    // (or the minimum item) is wasted capacity.
    let min_item = if next_item_size > 0 { next_item_size.min(100) } else { 10 };
    if post_residual > 0 && post_residual < min_item {
        score += (min_item - post_residual) as f64 * 2.5;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == min_item {
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 20.0 * fill_ratio;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are low
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * 1.5;

    // Prefer bins with residual close to item size (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 45.0 + 40.0 * big_item + 25.0 * poor_fits - 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild progression scaling: tighten packing as stream advances
    score *= 1.0 + 0.15 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, slightly penalized so only
    // genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 * 0.95 + 10.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: subtract heavily.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 40.0 - snug.min(35.0);
        } else {
            // Next item won't fit here: penalize leftover dead space.
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.3;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose post
    // residual is below average (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(30.0) * 0.5;
    } else {
        score += (pr - mean_residual).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with smaller residual before placement (tightest fit).
    score += (bin_residual as f64) * 0.15;

    // Mild penalty for residual far from being reusable (dead space below
    // typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference to fill bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for typical future items,
        // reward residual that could still host a mid-size item.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 40.0; // unusable sliver
        } else if pr <= 30.0 {
            score -= 10.0; // still useful
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly
            score -= 30.0 * (1.0 - ((post_residual - next_item_size) as f64) / 100.0);
        } else {
            // next item would not fit here: penalize wasting space now
            score += 15.0 * (nxt - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer the tightest fit via post_residual (already), small bonus for scarcity
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual below mean (tighter bins) when mean is high.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (keep flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: early stream -> cheap to open; late -> expensive.
        score += 80.0 * (1.0 - progress) - 40.0 * progress;
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 30.0 * progress;
    }

    // Fragmentation guard: many open bins with high mean residual -> discourage
    // spreading; prefer consolidating into fuller bins.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (2.0 - 3.0 * p2);
    score += 12.0 * coupling;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.35 * gap * gap / cap;
        // Reward leaving exactly room for the next item
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - fit_gap / cap).max(0.0);
    }

    // Reward last-chance placements (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty when this bin's residual deviates from mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Late-stream: prefer tighter fills
    score -= progress * (item_size as f64 / cap) * 5.0;

    // New-bin candidate: penalize slightly so it is chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: penalize dead space classes
    // Residual classes mod 10: small leftovers are unusable for items >=10... but items can be >=1.
    let pr = post_residual as f64;
    let cls = (post_residual % 10) as f64;
    score -= 0.5 * cls; // favor post_residual divisible by 10 (harmonic alignment)

    // Penalize very small unusable post_residual (dead space) unless zero
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - tight / cap);
        } else {
            // next item won't fit here: mild penalty for leaving big gap it can't use
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // current bin would leave a bad gap relative to next item
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = 60.0 + 0.3 * (post_residual as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Tight fit reward: fraction of capacity filled by this item
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // Slight preference to fill bins with lower residual than mean (balance)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Stream progression: early on, be pickier (penalize sloppy fits); later, consolidate
    let prog = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - prog);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items >= 1, but tiny gaps are wasted) are
    // heavily penalized. Gaps below ~10 are almost always dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps in 10..20 range are only usable by the smallest items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item would leave a large, reusable residual in it, or when open bins
    // are already crowded. Otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Pressure from number of open bins: many open bins -> discourage new ones.
        score += open_bins_count as f64 * 2.0;
        // If the item fits tightly into a fresh bin, opening is actually good.
        if item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item would not fit and post_residual is small dead space, penalize.
    if next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for fuller bins relative to mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight pressure to keep open_bins_count low over the stream.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit: post_residual == next_item_size (2-step lookahead match)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead: next item could still fit in remaining space
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }
    // Dead space: next item cannot use the leftover
    else if next_item_size > 0 {
        score += 8.0;
    }

    // Reward near-exact fits regardless of lookahead
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Penalize opening a brand-new bin unless it's genuinely attractive:
    // a new bin has post_residual = capacity - item_size; if open bins exist
    // and this is not a tight fit, push the new-bin candidate down.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = post_residual as f64;
        if waste > 30.0 {
            score += 10.0 + 0.4 * (waste - 30.0);
        }
        // Early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual non-linearly (dead space is superlinearly bad)
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Reward tight fits (small post_residual)
    if post_residual <= 8 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 0.4 * next_item_size as f64;
        } else {
            // next item won't fit here: penalize leaving a residual just under next_item_size
            if post_residual > 0 && post_residual < next_item_size {
                score += 0.5 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Time horizon: early in stream, prefer keeping bins flexible; late, pack greedily
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 15.0 * (bin_capacity as f64 - pr) / bin_capacity as f64;
    score += (1.0 - t) * 0.1 * pr;

    // Global residual state: if mean residual is high, prefer filling this bin down
    score -= 0.3 * (pr - mean_residual);

    // Penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        let slack = mean_residual;
        if open_bins_count > 0 && slack > item_size as f64 {
            score += 20.0 + 0.2 * (slack - item_size as f64);
        }
        // But allow new bins late in stream if residual landscape is poor
        score -= t * 5.0;
    }

    // Mild preference for bins with residuals that pair with common item sizes
    for k in [10u32, 20, 25, 30, 40, 50] {
        if post_residual == k {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, non-linearly shaped
    let mut score = pr;

    // Polynomial coupling of residual with stream progress:
    // early on, prefer tight fits (waste penalized super-linearly);
    // late in stream, waste is cheaper relative to opening new bins.
    let shape = 1.0 + 1.5 * (1.0 - progress) * x - 0.8 * x * (1.0 - x) + 2.0 * progress * x * x;
    score *= shape;

    // Dead-space penalty: residuals too small to fit the smallest plausible item
    let dead = (x - (10.0 / cap)).min(0.0).abs();
    score += 40.0 * dead * dead * cap;

    // Lookahead: if next item fits the post-residual, reward this bin strongly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 25.0 * (1.0 - gap / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin when open bins exist
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * progress;
    }

    // Mild diversity term: keep residuals near mean to preserve flexibility
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let resid_class = post_residual % 10;
    let harmonic = ((post_residual / 10) % 4) as f64;

    // Reward residuals that belong to "harmonious" classes (multiples of 5 or 10)
    if resid_class == 0 {
        score -= 6.0;
    } else if resid_class == 5 {
        score -= 3.0;
    } else {
        score += resid_class as f64 * 0.4;
    }

    // Integer-division threshold: residuals <= 10 are perfect closures
    if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    } else if post_residual > bin_capacity / 2 {
        score += 3.0; // wasteful half-empty bin
    }

    // Coupling with next item: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size as u32 == post_residual {
            score -= 15.0; // exact harmonic pairing
        } else if next_item_size <= post_residual {
            score -= 4.0 * (post_residual as f64 / cap);
        } else {
            // dead space unless residual is in a reusable class
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
            if resid_class == 0 { score -= 2.0; }
        }
        // modulo coupling between next item and residual class
        let pair_class = (post_residual + next_item_size) % 10;
        if pair_class == 0 { score -= 2.5; }
    } else {
        score += 10.0; // last item: prefer filling existing bins
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean-residual harmonic alignment
    let mean_gap = (mean_residual - pr).abs();
    score += 0.3 * mean_gap;

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        let base = 0.55 * cap;
        if post_residual as f64 >= base {
            score -= 8.0; // fresh bin keeps flexibility early
        } else {
            score += 25.0; // discourage opening new bins for good fits
        }
        score += 0.05 * open_bins_count as f64;
    }

    // Stream progression: late in stream, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += harmonic * 0.5 * (1.0 - progress);
    score -= progress * 2.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead_zone = 10.0f64; // gaps below the minimum item size are pure waste
        if (post_residual as f64) < dead_zone {
            score += (dead_zone - post_residual as f64) * 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Penalize opening new bins when plenty of open bins exist (pressure to consolidate).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus open-bin pressure.
        score += 30.0 + open_bins_count as f64 * 4.0;
        // If only this bin can fit the item, opening a new bin is very bad.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // Early stream: prefer filling existing bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    } else {
        // Last-chance bin: strong reward to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Lookahead: if the next item fits exactly in the post residual, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            let next_fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= next_fit_quality * 12.0;
        }
        // Penalize bins whose residual deviates badly from the mean (fragmentation control).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Global open-bin pressure: more open bins -> push toward tighter packing.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect (or near-perfect) fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the next item exactly fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: good, but worse the more slack remains after it.
            let after_next = post_residual - next_item_size;
            score -= 100.0 - after_next as f64;
        } else {
            // Next item would NOT fit in the residual: penalize dead space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals that are too small to ever be useful (min item size 1,
    // but practically small leftovers are dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or existing fits are poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let poor_alternatives = (fitting_bins_count as f64).min(3.0);
        // Opening a new bin is good for big items or when few bins fit.
        score -= 120.0 * tightness;
        score += 40.0 * poor_alternatives;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 * progress;
        // If the next item is huge, a fresh bin keeps flexibility.
        if next_item_size >= 70 {
            score -= 50.0;
        }
    }

    // Mild preference for filling larger-residual bins when many are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving awkward gap
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = 10.0 + 40.0 * (open_bins_count as f64 / 20.0).min(1.5);
        score += open_penalty * (1.0 - 0.5 * progress);
        if fitting_bins_count <= 1 {
            // no real alternative: opening new bin is acceptable
            score -= 35.0;
        }
        // a fresh bin is only attractive if item is large relative to capacity
        score += 0.2 * (bin_capacity.saturating_sub(item_size) as f64);
    }

    // Global state coupling: prefer bins whose residual is near the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight time pressure: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled non-linearly by stream progress
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of residual with progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 40.0 * poly * (1.0 + progress);

    // Penalize dead space that no plausible item can use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (1.5 + progress);
        } else {
            // reward leaving space for the next item
            score -= 6.0 * (1.0 - ((pr - ni) / cap).min(1.0));
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild preference for fuller bins relative to the mean residual
    score -= (mean_residual - pr) * 0.25;

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and 25 capture
    // "companion-friendly" leftover sizes for typical item granularities.
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r25 = (pr % 25) as f64;
    // Penalize post-residuals whose harmonic class is awkward (far from 0 or 10 mod 10)
    let awkward10 = if r10 <= 5.0 { r10 } else { 10.0 - r10 };
    score += awkward10 * 0.6;
    // Quarter-capacity classes (mod 25): leftovers near multiples of 25 are reusable
    let q25 = if r25 <= 12.5 { r25 } else { 25.0 - r25 };
    score -= (12.5 - q25) * 0.4;

    // Integer-division tiers on post_residual: dead-space bands
    let tier = pr / 10; // 0..=10
    score += match tier {
        0 => 30.0,           // nearly full bin: excellent, but zero future use
        1 | 2 => -8.0,       // 10-29 left: tight but usable
        3 | 4 => 0.0,        // mid band neutral
        5 | 6 => -5.0,       // 50-69: half-bin sweet spot
        7 | 8 => 2.0,        // 70-89: large leftover, mediocre
        _ => -12.0,          // 90+: almost empty bin
    };

    // Lookahead coupling: does post_residual accommodate the next item's class?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits here: reward, scaled by how snugly
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - slack.min(10.0) * 0.5;
            // harmonic bonus if next item lands post_residual on a multiple of 10
            let nr = (pr - next_item_size) % 10;
            if nr == 0 { score -= 6.0; }
        } else {
            // next item cannot fit here: mild penalty for stranding this residual
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline offset so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.5;
        // Early in stream, opening bins is cheaper (build diversity of residuals)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins below mean residual (fill the emptier bins first to balance)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight preference for tighter fits overall
    score += (item_size as f64 / bin_residual.max(1) as f64) * -4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1..10) are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Residuals too small for the lookahead item (but >=10) are also likely dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 30 {
        score += 15.0;
    }

    // Reward near-perfect fits (small usable leftover).
    if post_residual <= 10 {
        score -= 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize adding to bins when many are already open,
    // pushing toward consolidation into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer filling bins with small residuals relative to the mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Tightness ratio: favor bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // New-bin candidate: default neutral-ish score; open a fresh bin only when
    // existing bins would create dead space or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0;
        // If the item is large, a fresh bin is attractive (it will fill well).
        if item_size >= 60 {
            score -= 20.0;
        }
        // If no open bin is a last chance, opening is less costly.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // Lookahead: if next item is large, a fresh bin can host both.
        if next_item_size >= 40 && item_size + next_item_size as u32 <= bin_capacity {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins where the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect 2-step match: big reward.
        score -= 40.0 + 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Lookahead item won't fit here after placement: penalize a bit relative to leftover.
        score += 10.0 + 0.2 * post_residual as f64;
    }

    // Penalize creating tiny dead space that nothing (min size 1..100) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: reward using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins that are already below-average residual (tighter bins).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference for compacting into few bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score += 2.0 * progress;
    }

    // Slight nudge toward higher fill ratio.
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post_residual as f64;

    // Penalize dead space: residual too small for any future item (min size 1, typical >= 10).
    if post_residual < 10 {
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward leaving room for the lookahead item (chain-friendly placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 2.0 * t;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 6.0; // space wasted relative to lookahead
    }

    // Last-chance bin before opening a new one: strong discount.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt();

    // New-bin candidate: small fixed opening cost, waived late in stream or for large items.
    if is_new_bin {
        let open_cost = 6.0 - 4.0 * t;
        score += open_cost.max(1.0);
        if item_size >= 60 {
            score -= 3.0; // big items deserve fresh space
        }
    }

    // Prefer tighter fits slightly more as stream progresses.
    score *= 1.0 + 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with a convex non-linear penalty
    let mut score = norm_post.powi(2) * cap + post * 0.5;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space is costlier)
    let coupling = norm_post.powi(2) * (1.0 - progress) * 40.0
                 - norm_post * progress * 60.0;
    score += coupling;

    // Non-linear interaction between post residual and mean residual:
    // reward bins tighter than average
    let mean_norm = mean_residual / cap;
    score += (norm_post - mean_norm).powi(2) * 30.0;
    score -= mean_norm * norm_post * 20.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: penalize if post residual is slightly above next item
    // (blocks the next item), reward if next item fits exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= fit_quality * fit_quality * 12.0;
        } else {
            let gap = (nxt - post) / cap;
            score += gap * gap * 18.0;
        }
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).powf(0.5) * (1.0 - progress) * 2.0;

    // New-bin candidate: prefer it only when the fit is poor elsewhere
    if bin_residual == bin_capacity {
        score = 55.0 + norm_post * 0.0 - 0.0;
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits (0) and tiny residues are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class the residual by integer division into harmonic bands.
        let band = post_residual / 10; // 0..10 harmonic class
        // Small bands (0,1) are nearly dead space -> penalize proportionally
        score += (10 - band as f64) * 2.0;

        // Modulo arithmetic: residuals that are multiples of common small item sizes
        // (e.g. 10, 20, 25, 50) remain reusable -> reward.
        let reusable = post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0;
        if reusable {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 200.0;
        } else if slack <= 10 {
            score -= 50.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Dead space relative to lookahead: penalize harmonic distance
        let gap = next_item_size - post_residual;
        score += gap as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Capacity fraction thresholds: bin_residual near capacity means fresh bin;
    // packing into it early keeps fragmentation low.
    let fill_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_fraction * 20.0;

    // Mean residual coupling: if this bin is far below mean residual, it's an outlier
    // worth filling (harmonic balancing).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.3;
    }

    // Late-stream consolidation: prefer existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 40.0 + 80.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead coupling: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // New-bin candidate: prefer reusing bins over opening new ones unless very tight fit.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Favor bins with residuals below the mean (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // ideal chaining: next item fills this bin completely
        } else if post_residual >= next_item_size {
            // Next item fits, but reward tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus if the chain leaves a small, still-usable remainder.
            if slack <= 10.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here: penalize dead space creation.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    } else {
        // Last item: prefer minimal final residual (perfect closure).
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward closeness of this bin's residual to the mean residual (balanced packing),
    // penalize bins far below mean residual (large leftover space).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();
    if dev > 0.0 {
        score += 0.25 * dev; // extra penalty for above-average leftover space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize wasting a nearly-full bin when other bins could absorb the item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 && bin_residual < bin_capacity {
        score += 12.0 * (1.0 - fill_ratio);
    }

    // Early in the stream, encourage consolidation into few bins.
    if open_bins_count > 1 {
        score += 3.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: keep it as a fallback, only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Slight progression-based tightening: as stream advances, prefer exact fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
