pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space is costly).
    score += progress * norm_pr * norm_pr * 3.0;

    // Lookahead: reward leaving room for the next item.
    let n = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let gap = (norm_pr - n).max(0.0);
        score -= 2.0 * gap * (1.0 + progress);
        // Penalize residual that is just barely too small for next item.
        if n > norm_pr && n > 0.0 {
            score += 1.5 * (n - norm_pr) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 2.5;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Discourage opening new bins when open bins have plenty of room,
    // scaled by stream progress (consolidate early, stay flexible late).
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    } else {
        // Slight preference for bins already below mean residual (balance spread).
        score += 0.3 * (mean_residual / cap - norm_pr).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by small
    // denominators are more reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        if pr % 10 == 0 { reuse_bonus += 6.0; }
        if pr % 5 == 0 { reuse_bonus += 3.0; }
        if pr % 2 == 0 { reuse_bonus += 1.0; }
        if pr % 25 == 0 { reuse_bonus += 4.0; }
        if pr % 20 == 0 { reuse_bonus += 3.0; }
        score -= reuse_bonus;

        // Dead-space penalty for tiny awkward residuals (below min item size 10).
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0;
        }
        // Sweet spot: residuals in [10, 30] are highly fillable.
        if pr >= 10 && pr <= 30 {
            score -= 8.0;
        }
    } else {
        // Perfect fill is ideal.
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // Harmonic class match between next item and post residual.
            if pr % next_item_size == 0 {
                score -= 6.0;
            }
            let leftover = pr - next_item_size;
            if leftover < 10 {
                score += 3.0; // would create dead space next step
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin when stream is late,
    // reward it early (amortization of bin overhead).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        score = score.max(0.0) + waste + 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 12.0; // next item cannot fit here anyway
        }
    }

    // Tight fit reward: filling most of the bin in one shot.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 5.0 * fill_ratio;
    }

    // Mild pressure toward bins with larger residuals when many bins are open.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..10) can
    // use efficiently are heavily penalized, especially tiny unusable slivers.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 12.0;
        } else if post_residual < 30 {
            score += 4.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * (fill_ratio - 0.8);
    }

    // Lookahead: if the next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    }
    // Penalize leaving a gap that the next item cannot use (dead space for k+1).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins over spreading out.
    score += 0.6 * open_bins_count as f64;

    // Mean-residual coupling: if average residual is small, protect remaining space;
    // if average residual is large, encourage using up slack bins.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Late-stream urgency: near the end, prefer tight packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins less attractive unless the fit is truly poor
    // in all open bins (handled via fitting_bins_count pressure above).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins whose post-residual exactly matches the next item size (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = post_residual - next_item_size;
        score -= 40.0 * (1.0 - match_gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize post-residual that cannot host the next item.
        score += 25.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better reuse targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid wasting the only fitting bin on a bad fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space more strongly later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Slight penalty for opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual is already the base).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Penalize bins whose residual is barely larger than the item (awkward fit).
    let gap = bin_residual as f64 - item_size as f64;
    if gap >= 0.0 {
        score += (1.0 - gap / bin_capacity as f64) * 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Lookahead: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            score += 8.0; // this placement likely strands the bin
        }
    }

    // Time horizon: late in the stream, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when alternatives exist.
        score += 15.0 + progress * 25.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // Opening a new bin is more attractive when mean residual is high (fragmented state).
        score -= mean_residual / bin_capacity as f64 * 10.0;
    } else {
        // Existing bin: mild bonus when its residual is below average (better-than-average use).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual interacts with stream progress
    let coupling = norm_pr * (1.0 + 2.0 * progress * (1.0 - progress) * 4.0);
    score += 6.0 * coupling * coupling;

    // Penalize dead space scaled by progress (later: waste hurts more)
    score += norm_pr * norm_pr * progress * 40.0;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack) * (0.5 + progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near/below mean to balance load
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev.abs();

    // New-bin candidate: smooth sigmoid-like acceptance
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + (-8.0 * (norm_pr - 0.35 - 0.2 * progress)).exp());
        score += 30.0 * openness - 10.0 * (1.0 - openness) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction buckets
    let class = post_residual / (bin_capacity / 4);
    match class {
        0 => score -= 25.0, // perfect fit class (0..=24 dead space) strongly rewarded
        1 => score += 5.0,  // 25..=49
        2 => score += 12.0, // 50..=74
        _ => score += 20.0, // 75..=99
    }

    // Modulo coupling: dead space that is a multiple of 10 (typical item quantum) is reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: penalize if next item cannot use this bin's post residual
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it slightly unattractive unless residual would be large
    if bin_residual == bin_capacity {
        score += 10.0 - (item_size as f64 * 0.05);
    }

    // Tightness coupling: prefer filling bins far below mean residual
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Stream progression: late in stream, favor closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum item (1)
    // are worthless; residuals below a "useful" threshold become dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 15.0; // marginal gap
    }

    // Reward using a nearly-full bin so it closes out.
    if post_residual as f64 <= mean_residual * 0.5 {
        score -= 8.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // leaves a gap the next item cannot use
    }

    // New-bin candidate: only attractive when existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit || (fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.5) {
            score -= 30.0;
        } else {
            score += 50.0; // prefer reusing open bins when fits are decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: prefer tight fits (small post_residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chain: this bin becomes perfectly full next step
        } else if next_item_size <= post_residual {
            // next item fits too: mild reward proportional to how well it nests
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving dead space the next item can't use
            let dead = post_residual as f64;
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * dead.min(gap);
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates favorably.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or lookahead suggests a better chain elsewhere.
    if bin_residual == bin_capacity {
        score += 55.0;
        if post_residual as f64 > item_size as f64 * 0.5 {
            score += 20.0; // opening bin for a small item wastes space
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 15.0;
        }
    }

    // Early in the stream: allow more bins to spread large items; late: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    } else {
        score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer keeping many open bins manageable: slight penalty for very full bins late.
    if open_bins_count > 3 && post_residual > 0 && post_residual < 10 {
        score -= 10.0; // nearly-full bins are fine to finish off
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, non-linearly.
    if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fill creates almost no dead space
    } else {
        // Penalize large dead space quadratically, scaled by bin capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 30.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the post residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item can fit into post residual, mild bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit post residual, penalize leaving awkward gaps.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time-horizon awareness: early in the stream, packing tightness matters more
    // (many items remain); late in the stream, avoid opening wasteful bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (1.0 - waste_frac_min(post_residual, bin_capacity));
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Global residual context: if mean residual is small, conserve open bins
    // (prefer fitting into existing bins rather than new ones).
    if bin_residual != bin_capacity {
        let gap = mean_residual - bin_residual as f64;
        if gap > 0.0 {
            score -= gap.min(20.0) * 0.5; // this bin is tighter than average -> prefer
        } else {
            score += (-gap).min(20.0) * 0.3; // looser than average -> slight penalty
        }
    } else {
        // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly,
        // but reduce penalty when many items remain or few bins are open.
        let base_penalty = 12.0;
        let relief = (progress * 6.0) + (open_bins_count as f64 * 0.5);
        score += base_penalty - relief.min(10.0);
        // If the item is large relative to capacity, a fresh bin is often better.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is a "nice" multiple region
    // (residuals near 50 split well into two medium items).
    let r = post_residual as f64;
    if (40.0..=60.0).contains(&r) {
        score -= 4.0;
    }

    score
}

#[inline]
fn waste_frac_min(post_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - (post_residual as f64 / bin_capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Core: penalize post residual with a smooth non-linear (quartic) profile
    // that grows faster for very small leftovers (dead space) and very large
    // leftovers (wasteful low-fill placement).
    let mut score = 10.0 * x + 40.0 * x * x * (1.0 - x) + 60.0 * x * x * x * x;

    // Exact fit bonus (post residual zero): strongly reward.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Smooth dead-space penalty: items that leave residual < typical item
        // sizes create unusable space; couple with mean residual.
        let dead = (1.0 - x).min(0.25) / 0.25; // peaks when bin nearly full
        score -= 8.0 * dead * (mean_residual / cap).min(1.0);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over
    // opening a new bin, scaled smoothly by stream progress.
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild congestion penalty so best-fitting bins are still preferred.
        score += 0.5 * ((fitting_bins_count as f64 - 1.0).ln().max(0.0));
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (x * cap / nx).min(1.0);
        score -= 12.0 * fit_next * fit_next;
        // If next item exactly fills post residual, extra smooth bonus.
        let exact = 1.0 - ((pr - nx).abs() / cap);
        score -= 5.0 * exact.max(0.0) * exact.max(0.0);
    }

    // Late-stream consolidation: favor filling existing bins more as the
    // stream progresses, penalizing new-bin opening smoothly.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 4.0 + 18.0 * progress * progress + 0.4 * open_bins_count as f64;
    } else {
        // Mild reward for choosing fuller bins (small residual before placement).
        score -= 3.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Small smooth interaction: progress-scaled residual coupling to break ties.
    score += progress * 2.0 * (x - 0.5) * (x - 0.5) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets capture common item-size
    // residues (items are integers, often multiples of 5/10). Residuals in
    // "friendly" classes are reusable; awkward classes are dead space.
    let r = post_residual as i64;
    let rmod = r % 10;
    match rmod {
        0 => score -= 12.0,             // perfect harmonic slot
        5 => score -= 6.0,              // half-harmonic slot
        1 | 9 => score -= 1.0,          // nearly harmonic
        2 | 8 => score += 2.0,
        3 | 7 => score += 5.0,
        _ => score += 9.0,              // 4|6: awkward dead space
    }

    // Very small residuals are effectively dead space regardless of class.
    if r < 10 {
        score += (10 - r) as f64 * 2.5;
    }

    // Lookahead coupling: reward residuals that can host the next item,
    // penalize residuals that trap the next item's harmonic class.
    if next_item_size > 0 {
        if (r as u32) >= next_item_size {
            let gap = r - next_item_size as i64;
            score -= 8.0;
            // exact fit for next item is excellent
            if gap == 0 {
                score -= 10.0;
            } else if gap % 10 == 0 {
                score -= 5.0;
            } else if gap < 10 {
                score += 3.0; // leaves unusable sliver after next item
            }
        } else {
            // next item won't fit here: residual becomes a waiting buffer
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Prefer packing into existing crowded bins early in the stream;
    // later, allow spreading to keep harmonic residuals available.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual / bin_capacity as f64) * (6.0 - 8.0 * progress);

    // New-bin candidate: only attractive when no open bin is decent or
    // the stream is young and fresh bins are cheap.
    if bin_residual == bin_capacity {
        let decent = if fitting_bins_count == 0 { 0.0 } else { 10.0 };
        score += decent + (open_bins_count as f64) * 0.8 - progress * 6.0;
        if next_item_size > 80 { score -= 5.0; } // big next item: fresh bin helps
    }

    // Mild penalty for proliferating bins when mean residual is healthy.
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead". Penalize them super-linearly.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small waste relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making the new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 3.0;
    } else {
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item almost fits (small miss), slight penalty for awkward gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 5.0;
    }

    // Early in the stream, opening fresh bins is cheaper; late, avoid fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (good fit) — penalize bins with much larger residual than needed.
    let excess = bin_residual as f64 - item_size as f64;
    if excess > mean_residual {
        score += (excess - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.35 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space penalty: post-residual too small for the lookahead item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
        // Perfect chain: post_residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: minimize residual as usual.
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current bin would be nearly empty anyway.
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only for large items or when it enables a perfect next-item fit.
        score += 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild stream-progression pressure: early on, be frugal with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (fitting_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space: residual too small to likely hold a future item (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // creates a gap that next item can't use
        }
        // Bonus if placing item leaves exactly room for next item (chained perfect fit).
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: an empty bin has neutral base but should only win
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 - 10.0 * (1.0 - progress);
        // If many open bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If the current item is small relative to capacity, a fresh bin wastes space.
        if (item_size as f64) < 0.5 * (bin_capacity as f64) {
            score += 8.0;
        }
    }

    // Global pressure: when mean residual across open bins is high, prefer packing
    // into existing bins (fragmentation risk); when low, slightly favor new bins.
    let mean_r = mean_residual;
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_r;
    }

    // Prefer filling bins that are already mostly full (larger bin_residual used).
    if bin_residual < bin_capacity {
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * fill;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.02 * (open_bins_count as f64) * (0.5 + progress_proxy(step_index, total_items));

    score
}

#[inline]
fn progress_proxy(step_index: usize, total_items: usize) -> f64 {
    if total_items > 0 { (step_index as f64 / total_items as f64).min(1.0) } else { 0.0 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling: post_residual penalty grows quadratically with progress
    // (late in the stream, wasted space is more costly)
    let pr = post_residual as f64;
    score += 2.0 * pr * pr / (bin_capacity as f64 * bin_capacity as f64) * (0.5 + progress);

    // Reward tight fits: smooth bell-shaped reward around post_residual == 0
    let tightness = (1.0 - pr / bin_capacity as f64).max(0.0);
    score -= 6.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // if post_residual is smaller than the next item, that space is likely wasted
    if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 1.5 * gap * (0.3 + progress);
        } else {
            // next item fits exactly-ish: reward
            score -= 1.0 * (-gap) * (0.3 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild penalty when many bins are open and this placement leaves large residual
    // (encourages consolidation when bin count is high)
    let open_norm = (open_bins_count as f64).ln().max(0.0);
    score += 0.3 * open_norm * (pr / bin_capacity as f64);

    // Coupling with mean residual: prefer bins whose residual deviates below the mean
    // (pack the emptier bins tighter, keep larger residuals for future large items)
    let dev = mean_residual - pr;
    score += 0.4 * dev * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residuals are mostly large
    if bin_residual == bin_capacity {
        let mean_ratio = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let openness = 1.0 - mean_ratio;
        // if mean residual is small, open bins are nearly full -> new bin is fine
        score = 3.0 + 10.0 * mean_ratio * mean_ratio - 4.0 * openness * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues modulo 10 and 25 ---
    let pr = post_residual;
    // Perfect-fit reward (dead space zero is the ideal)
    if pr == 0 {
        score -= 1000.0;
    }
    // Small dead space is fine; mid-range dead space is worst.
    if pr > 0 {
        let frac = pr as f64 / bin_capacity as f64;
        // penalize unusable mid residuals most
        score += frac * 40.0;
        // harmonic classes: residuals that are multiples of 10 or 25 are
        // more likely to be filled by future items (sizes 10..80)
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 25 == 0 { score -= 15.0; }
        if pr % 50 == 0 { score -= 8.0; }
        // residuals < 10 are near-dead; small extra penalty scaled by class
        if pr < 10 { score += 6.0; }
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward chains where the next item also fits here
            let next_class = if pr % 10 == 0 { 1.0 } else { 0.7 };
            score -= 5.0 * next_class * (next_item_size as f64 / 80.0 + 0.5);
            // extra reward for exact harmonic match
            if pr == next_item_size { score -= 60.0; }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            let over = (next_item_size - pr) as f64;
            score += over * 0.15;
        }
    }

    // --- Tightness of current fit ---
    let tight = item_size as f64 / bin_residual as f64;
    score -= tight * 10.0;

    // --- Last-chance bin: avoid opening a new bin unnecessarily ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive unless existing fits are bad.
        // Base penalty keeps it behind decent fits; reduced when many
        // open bins exist (fragmentation) or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 55.0;
        // if mean residual is large and fragmented, new bin less bad
        if mean_residual > 40.0 { nb -= 10.0; }
        if open_bins_count > 6 { nb -= 5.0; }
        if progress < 0.2 { nb -= 5.0; }
        // never open a new bin for a tiny item if any bin fits
        if item_size < 30 { nb += 20.0; }
        score += nb;
    }

    // --- Mild spread penalty: prefer bins below mean residual (keep big
    //     residuals available for big items) ---
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Post-residual that is too small for the minimum plausible future item
    // (items can be as small as 1) is dead space: penalize gaps in [1, 9].
    if post_residual >= 1 && post_residual < 10 {
        score += 14.0 * (10 - post_residual) as f64;
    }
    // Gaps that cannot hold the lookahead item are semi-dead: penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
    }
    // Perfect lookahead fit: strong reward.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 25.0;
    }
    // Residual still usable by the lookahead item: mild reward proportional to tightness.
    if next_item_size > 0 && post_residual as u32 >= next_item_size {
        score -= 6.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    }

    // --- Tight fit reward relative to item size ---
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // --- Open-bins pressure: discourage proliferation of bins with many tiny gaps ---
    if open_bins_count > 4 {
        score += 0.35 * open_bins_count as f64;
    }
    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    score += 0.05 * (mean_residual - post_residual as f64);

    // --- Last-chance bonus: if this is the only fitting bin, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is generally wasteful when any open bin fits;
        // penalize so existing bins win unless fits are terrible.
        score += 22.0;
        // But if no open bin fits (fitting_bins_count == 0 means only the
        // new-bin candidate), the penalty must vanish so the new bin is chosen.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // An existing bin fits: only take the new bin if that fit is awful
            // (would leave a large dead gap).
            if post_residual < 10 {
                score -= 26.0;
            }
        }
        // Late in the stream, slightly prefer reusing bins to avoid leftover churn.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item fits exactly into the post
    // residual, heavily reward this placement (perfect 2-chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves more waste: mild reward proportional to
            // how little extra slack remains after the lookahead item.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - chain_waste.min(30.0);
        } else {
            // Next item does NOT fit: post residual becomes dead space unless
            // small. Penalize medium dead space, but tiny leftovers are fine.
            if post_residual > 0 && post_residual < next_item_size {
                let gap = (next_item_size - post_residual) as f64;
                score += gap.min(50.0) * 0.6;
            }
        }
    }

    // Compare against mean residual across open bins: prefer leaving residuals
    // near the mean (balanced bins), penalize creating outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new bin candidate unless nothing else fits well:
    // new bins are acceptable when many bins are open and stream is early
    // (spread future load), or when the fit here is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.35;
        if poor_fit && open_bins_count > 2 && progress < 0.7 {
            score -= 20.0;
        } else {
            score += 35.0;
        }
    }

    // Slight preference for keeping few open bins (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness: fraction of bin filled by this placement
    let fill = item_size as f64 / cap;
    let waste_frac = post_residual as f64 / cap;

    // Penalize waste non-linearly; dead space below 20 is nearly unusable (min item ~10)
    if post_residual > 0 {
        score += (waste_frac * waste_frac) * 40.0;
        if post_residual < 10 {
            score -= 25.0; // near-perfect fit, kills the bin
        } else if post_residual < 20 {
            score -= 12.0; // hard-to-fill sliver is good if consumed later? no: it's leftover -> reward low residual
        }
    } else {
        score -= 40.0; // exact fit
    }

    // Reward good fill ratio
    score -= fill * 30.0;

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // next item can slot in: good chaining, but only if residual isn't huge
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64 / cap).abs();
            score -= 8.0 + 6.0 * chain_tight;
        } else {
            // next item won't fit here: leftover becomes dead space relative to lookahead
            let gap = (next_item_size as i64 - post_residual as i64) as f64;
            score += 0.15 * gap.min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - waste_frac);
    } else {
        // Many alternatives: prefer the tightest ones (already via post_residual), small extra spread
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with high mean residual -> encourage consolidating into existing bins
    let consolidation = (mean_residual / cap).clamp(0.0, 1.0);
    score -= consolidation * 6.0 * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, keep bins flexible (penalize tiny residuals that fragment);
    // late in stream, prioritize closing bins out
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if t < 0.3 && post_residual > 0 && post_residual < 10 {
        score += 15.0; // early: avoid creating unusable slivers, keep flexibility
    }
    score -= t * 5.0 * fill; // late: reward high-fill placements to close bins

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Only attractive when no open bin fits well (large waste) or item is huge.
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count > 0 {
            // how bad would the best existing option be? approximate via mean residual vs item
            ((item_size as f64) - mean_residual).max(0.0) / cap
        } else {
            1.0
        };
        // Base cost of opening a new bin, discounted when consolidation is hopeless
        let open_cost = 55.0 - 45.0 * open_pressure.min(1.0);
        // Big items justify a fresh bin more (less fragmentation risk)
        let size_bonus = 15.0 * fill;
        score += open_cost - size_bonus + (1.0 - t) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post-residual and item size
    let prn = pr / cap;
    let itn = it / cap;

    // Non-linear coupling: penalize mid-range residuals quadratically (dead space)
    let dead = prn * (1.0 - prn);
    score += 18.0 * dead * (0.5 + progress);

    // Reward tight fits (small post-residual) with smooth exponential-like polynomial
    score -= 12.0 * (1.0 - prn).powi(3) * (1.0 + 0.5 * progress);

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - gap).powi(2);
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to how much it overshoots
        let over = (next_item_size - post_residual) as f64 / cap;
        score += 6.0 * over * over;
    }

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let obn = open_bins_count as f64;
    score -= 4.0 * (obn / (obn + 5.0)) * (1.0 - prn);

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    let mrn = mean_residual / cap;
    score += 5.0 * (prn - mrn) * (1.0 - progress);

    // New-bin candidate handling: neutral base, penalize slightly unless item is large
    if bin_residual == bin_capacity {
        let base = 55.0 - 20.0 * itn * itn - 15.0 * progress;
        score = base + 0.5 * prn;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is
    // for typical small items (1..=20). Classify via modulo bands.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -30.0 // perfect fit, strongly reward
    } else if pr <= 10 {
        -12.0 // still very usable
    } else if pr <= 20 {
        -5.0
    } else if pr <= 34 {
        0.0
    } else if pr <= 50 {
        4.0
    } else {
        10.0 // large dead space
    };
    score += class;

    // Integer-division harmonic: post_residual / 10 gives coarse granularity;
    // odd classes are slightly worse (fragmentation feel).
    let coarse = pr / 10;
    if coarse % 2 == 1 && pr > 0 {
        score += 1.5;
    }

    // Reward tight fits: ratio of item to residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0;
        // extra reward if next item nearly fills the remainder
        let nxt_fill = next_item_size as f64 / pr as f64;
        score -= 4.0 * nxt_fill;
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to how much it misses
        let miss = (next_item_size - pr) as f64;
        score += 0.08 * miss;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: empty bins get a baseline so we only open
    // new bins when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 18.0;
        // early in stream, opening bins is cheaper (need spread)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer packing into bins whose residual is near the mean (balance).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Many open bins: discourage spreading, encourage consolidation.
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (or the lookahead item) are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, no dead space at all
    } else {
        // Penalize small-but-nonzero gaps quadratically: they are the hardest
        // to fill later.
        let dead = post_residual as f64;
        if dead <= 10.0 {
            score += (11.0 - dead) * (11.0 - dead) * 2.0;
        }
        // If the lookahead item cannot use this leftover, the gap is likely
        // permanent dead space -> extra penalty.
        if next_item_size > 0 && post_residual < next_item_size {
            score += dead * 0.8;
        }
        // If the lookahead item fits exactly well, reward.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bins are crowded
    // (mean residual small relative to item) or nothing fits well.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.5;
        if crowded && open_bins_count > 0 {
            score -= 5.0;
        } else {
            score += 40.0 + open_bins_count as f64 * 2.0;
        }
        // Late in the stream, new bins are cheap since leftovers rarely get reused.
        if progress > 0.8 {
            score -= 10.0;
        }
    } else {
        // Prefer tighter existing bins: compare residual to mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize creating dead space: post_residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead reward: post_residual can accommodate the next item.
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty, scaled by how unusable the leftover is.
            let dead = next_item_size - post_residual;
            score += 6.0 + 0.35 * dead as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / bin_capacity as f64);
    score -= 20.0 * pressure;

    // Time horizon: early in the stream, be more conservative (penalize low-fit placements);
    // later, exploit consolidation more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or existing bins are very full (mean residual low) and fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if poor_fits && mean_residual < item_size as f64 {
            score -= 10.0;
        } else {
            score += 25.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Mild penalty when item barely fits (residual close to item size) to keep
    // large residuals for large future items.
    if bin_residual < 2 * item_size && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 30.0 * x * x * (1.0 - progress) * (1.0 - progress);
    score -= 12.0 * x * (1.0 - x) * progress;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0);
        score += 0.8 * waste;
        // Reward exact-enough fit for the next item
        score -= 0.5 * (1.0 - (pr - nx).abs() / cap) * (pr >= nx) as i32 as f64;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (x - mean_residual / cap).abs();

    // New-bin candidate: prefer it early or when residual is huge
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
        score += 15.0 * progress * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity quarters
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let r = post_residual;
    let class = r % quarter;

    // Reward placements landing in "harmonic" sweet spots:
    // exact fill (r==0) is perfect; small usable chunks (class near 0) are good.
    if r == 0 {
        score -= 60.0;
    } else if class <= 2 {
        score -= 12.0;
    } else if class >= quarter - 2 {
        // residue just above a quarter boundary -> slightly awkward
        score += 4.0;
    }

    // Penalize dead space: residuals that no plausible item (1..=100) can fill
    if r > 0 && r < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Large residual chunks are valuable; keep them when possible
    if r >= half {
        score += (r - half) as f64 * 0.15; // prefer bins that stay flexible? actually penalize waste of big residual on small item
    }

    // Integer-division thresholds on next_item_size vs post_residual
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0; // next item exactly fills this bin
        } else if next_item_size <= r && (r / next_item_size.max(1)) >= 2 {
            score -= 8.0; // next item also fits comfortably
        } else if next_item_size > r && next_item_size <= r + item_size {
            score += 10.0; // next item would need this bin's just-used space
        }
        // modulo coupling between next item and residual classes
        if r > 0 && (next_item_size % quarter) == (r % quarter) && next_item_size <= r {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would be left with an awkward residue class or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = if r > 0 && r < 10 { 1.0 } else { 0.0 };
        score = 20.0 + awkward * 30.0 + progress * 10.0
            - (open_bins_count as f64).min(5.0) * 2.0;
        if next_item_size > item_size {
            score -= 15.0; // big item coming, fresh bin helps
        }
        return score;
    }

    // Mild pressure toward tighter bins when many are open
    score += (open_bins_count as f64) * 0.3;

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: residuals below typical small item size
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: strongly favor this bin when it is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins when alternatives exist
    let pressure = open_bins_count as f64 / (bin_capacity as f64 / 10.0);
    score += pressure * 0.5;

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins have large residuals
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if all open bins are nearly full (small mean residual), opening is fine
        if mean_residual < 25.0 {
            score -= 45.0;
        }
    }

    // Slight preference for tighter bins (small bin_residual) among open bins
    score += bin_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item fits exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_left = post_residual - next_item_size;
            score -= 150.0;
            if next_left == 0 {
                score -= 400.0; // chain of two perfect fits
            } else {
                // penalize leftover after next item, scaled
                score += next_left as f64 * 0.5;
            }
        } else {
            // next item cannot follow here: mild penalty, worse if gap is small (dead space)
            let gap = post_residual as f64;
            if gap > 0.0 {
                score += 20.0 + gap * 0.1;
            }
        }
    }

    // Compare against mean residual: prefer using bins with residuals close to item
    let fit_tightness = (bin_residual as f64 - item_size as f64);
    score += (fit_tightness - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless nothing decent exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let decent_open = (bin_residual as f64 - item_size as f64) < 20.0;
        if decent_open || open_bins_count > 0 {
            score += 250.0;
        }
        // toward the end, prefer closing bins rather than opening
        score += (1.0 - progress) * 50.0;
    }

    // Slight preference for tighter existing bins
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Fractional waste relative to capacity.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 80.0 * fill_frac;

    // Penalize creating dead space that cannot fit typical next items.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reward leaving exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 90.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 }
            else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let early = step_index as f64 / (total_items.max(1) as f64);
        // Opening bins early is fine; later, prefer consolidation.
        let open_bonus = 120.0 * (1.0 - 0.5 * early) * pressure;
        score += open_bonus;
        // A new bin for a small item is wasteful.
        if fill_frac < 0.4 {
            score += 100.0 * (0.4 - fill_frac);
        }
    }

    // Global residual state: if mean residual is high, prefer bins that
    // reduce fragmentation (i.e. big fills).
    score -= 10.0 * (mean_residual / bin_capacity as f64) * fill_frac;

    // Mild preference to fill already-open bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress * (1.0 - progress) * 4.0);
    score += 30.0 * x * x * (1.0 - x) * (1.0 + progress);

    // Penalize dead space that likely can't be used later
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 25.0 * (nxt - post) / cap;
        } else {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        }
    } else {
        score += 5.0 * x * x;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild preference for bins below mean residual (balance spreading)
    score -= 3.0 * ((post - mean_residual) / cap);

    // Slight penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into
    // capacity-fraction buckets. Leftovers near multiples of small divisors
    // (e.g. 10, 20, 25, 50) are "reusable classes" and get rewarded.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect fit: best possible outcome
    } else if pr <= 5 {
        -25.0
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -14.0
    } else if pr % 20 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += class_bonus as f64;

    // Dead-space penalty: leftover too small for the minimum item size
    // (1 here, but tiny slivers are still likely waste relative to stream scale).
    if pr > 0 && pr < 10 {
        score += 12.0 * (1.0 - pr as f64 / 10.0);
    }

    // Lookahead coupling: reward a leftover that exactly hosts the next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // fraction of next item absorbed; smoother the better
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).min(1.0);
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 8.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has neutral base residual = cap.
    // Make it slightly unattractive unless the item fits badly everywhere.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Early in the stream, opening bins is cheap and builds a portfolio.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall: align with mean residual to spread load.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: small unusable gaps (1..=9) are wasted forever
    // since items are >= 1 but typical usable chunks are larger; penalize
    // residuals that are too small to be practically reusable.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Medium residuals (10..=30) are moderately reusable: mild penalty scaled
    // by how much slack is left, to prefer bins that end up "tight".
    if post_residual >= 10 && post_residual <= 30 {
        score += 5.0;
    }

    // Large residuals are fine (bin stays flexible) — no extra penalty.

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else if gap <= 9 {
            score += 20.0; // chaining would create dead space
        } else {
            score -= 30.0; // chain keeps bin productive
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Opening a
    // new bin is only attractive when existing fits are poor. Make the empty
    // bin baseline relatively unattractive unless its "post fit" is clean.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin, grows with stream progress
        // (later in stream, prefer consolidating into open bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + 80.0 * progress;
        // But if the item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize placements that leave large residuals behind.
    score += (open_bins_count as f64) * (post_residual as f64) * 0.05;

    // Prefer bins tighter than average (mean residual coupling).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space penalty (nonlinear)
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0;
        }
        // Large dead space penalty: residual too small for typical future items
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // next item won't fit: penalize wasted chain potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty so open bins usually win
        score += 250.0;
        // but if the item is large and current open bins are fragmented, allow new bin
        if item_size as f64 > mean_residual + 20.0 {
            score -= 400.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 150.0;
        }
    }

    // Mild preference to keep number of open bins moderate
    score += open_bins_count as f64 * 0.1;

    // Slight time decay: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * (bin_residual as f64);

    // Penalize dead space that cannot hold the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: prefer it only when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count >= 2 {
            score += 12.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 3.0; // good pair potential in fresh bin
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 {
        score += 0.02 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs();
    }

    // Time horizon: late in stream, prefer filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    // Small bonus for matching mean residual usage pattern.
    score += 0.1 * ((post_residual as f64) - mean_residual).abs() / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer small post-residual, with smooth cubic decay of the penalty
    let mut score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Reward tight fits (post_residual near zero) more strongly as the stream progresses
    let tightness = 1.0 - (pr / cap).clamp(0.0, 1.0);
    score -= 12.0 * tightness.powi(3) * (0.5 + progress);

    // Smooth coupling with mean residual: prefer bins whose residual deviates below the mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * (1.0 + progress) - 2.0 * dev * dev;

    // Lookahead: reward leaving room for the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        let fit_next = ((gap + 0.5).tanh() + 1.0) * 0.5; // smooth 0..1
        score -= 6.0 * fit_next * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: penalize smoothly so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress - 3.0 * (mean_residual / cap).tanh();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (likely dead space) get penalized less if the
    // residue is exactly fillable by common item sizes; penalized more otherwise.
    let cap = bin_capacity as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Harmonic classes via integer division thresholds on post_residual.
    let cls = post_residual / 10; // 0..=10 harmonic class
    score -= (10 - cls as f64) * 5.0;

    // Modulo structure: residues divisible by 5/10 are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 12.0;
    } else {
        score += 8.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 60.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item cannot use this residue: dead-space risk
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer filling already-open bins when many are open; new-bin candidate
    // (residual == capacity) gets a mild penalty unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a laggard bin; using it consolidates waste.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Progress-scaled tightness: later in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=min) are pure waste.
    // Penalize dead space superlinearly.
    if post_residual > 0 {
        // dead space = space likely unusable; anything below the smallest plausible item
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 8.0 * dead;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a residual that exactly fits the lookahead item (k=2 lookahead synergy)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is positive but smaller than next item (dead for lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus open-bin pressure
        score += 30.0 + 6.0 * open_bins_count as f64;
        // if nothing fits well elsewhere, this is handled by fitting_bins_count==0
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // mild reward for filling already-open bins proportional to item size (larger items first)
        score -= 0.1 * item_size as f64;
    }

    // Prefer bins with lower residual (tighter bins) to consolidate space
    score += 0.05 * (bin_residual as f64 - mean_residual).abs().min(20.0);

    // Late-stream tightening: as stream progresses, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
