        if open_bins_count > 4 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // keeping space for a bigger next item
        }
    }

    // Late-stream consolidation: favor filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize small but nonzero dead space (hard-to-fill slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 5.0;
        }
        // Perfect two-item packing bonus.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // fit is terrible or stream is early with many items remaining.
    if bin_residual == bin_capacity {
        score += 25.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fit_ratio < 0.35 {
            score -= 20.0 * (1.0 - fit_ratio);
        }
        // Early in the stream, new bins are cheaper to open.
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 4.0;
    }

    // Mild preference for filling bins more completely as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, non-linearly
    let mut score = post.powf(1.4) * (1.0 + 0.8 * progress);

    // Smooth polynomial coupling between residual and progress
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (low post residual), stronger late in stream
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Prefer filling bins when many are open; new-bin penalty via coupling
    let open_pressure = (open_bins_count as f64).ln().max(1.0);
    score += 4.0 * norm_post * open_pressure;

    // Mean residual alignment: penalize bins deviating from fleet mean
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New empty bin: mildly penalized so it's chosen only for genuinely bad fits
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // "harmonics" of the capacity are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward post_residuals that divide capacity evenly (perfect harmonic fit)
    if pr > 0 && bin_capacity % pr == 0 {
        score -= 12.0 + 0.25 * prf;
    }
    // Half / quarter capacity classes
    if pr == bin_capacity / 2 {
        score -= 10.0;
    }
    if pr == bin_capacity / 4 || pr == (3 * bin_capacity) / 4 {
        score -= 6.0;
    }

    // Penalize small dead space (< 10, unusable for typical items)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            // harmonic class match between next item and post residual
            if pr % next_item_size == 0 {
                score -= 8.0;
            }
            let slack = (pr - next_item_size) as f64;
            score += 0.15 * slack;
        } else {
            // next item won't fit here: penalize proportionally to wasted opportunity
            score += 0.10 * (next_item_size as f64 - prf);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is nearly full
    if bin_residual == bin_capacity {
        // opening a new bin: neutral baseline plus mild pressure to reuse bins
        score += 5.0 + 0.5 * open_bins_count as f64;
    } else {
        // reward filling bins that are already tight
        let tightness = 1.0 - bin_residual as f64 / cap;
        score -= 10.0 * tightness;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good
    // candidate to close out (consume the small residual).
    let dev = mean_residual - bin_residual as f64;
    score += 0.20 * dev;

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can use are pure waste. Penalize "unusable" gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to capacity (fractional waste).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac;

    // If next item can exactly use the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item cannot fit into the post residual at all, this bin is closed
    // for the lookahead: penalize slightly unless it was a near-perfect fit.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer opening a new bin when open bins are already
    // fragmented (mean residual high) or many bins are open.
    if bin_residual == bin_capacity {
        score = 45.0 + 2.0 * open_bins_count as f64 + mean_residual * 0.3;
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the current item is large, a fresh bin is often best.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves slack; penalize proportional slack
            score -= 200.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here; penalize large dead space a bit more
            let waste = post_residual as f64;
            score += 0.3 * waste;
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 {
        score -= 500.0;
    }

    // Penalize creating small unusable residuals (below typical min item size 1..100,
    // treat residuals < 10 as dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post);

    // New-bin candidate: make it unattractive unless it beats a very poor fit
    if bin_residual == bin_capacity {
        score += 300.0;
        // allow new bin when item is large relative to capacity and many bins open
        score -= 0.2 * (item_size as f64 / cap) * 300.0;
    }

    // Slight preference for filling fuller bins late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-full fills strongly (non-linear).
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * fill_ratio * fill_ratio * fill_ratio;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: small unusable leftovers relative to min item size.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0 + 0.2 * (next_item_size as f64);
        } else {
            // Penalize leaving a gap that blocks the next item slightly more
            // when the gap is large (wasted potential).
            let gap = post_residual as f64;
            if gap > next_item_size as f64 * 0.5 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty
    // so it is only chosen when open bins fit poorly, scaled by stream progress
    // (later in the stream, reusing bins matters more).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + 25.0 * progress;
        // Opening a new bin is more acceptable when few bins are open relative
        // to mean residual congestion (open bins are fragmented).
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Reuse reward: mildly favor bins below-mean residual (consolidation),
        // i.e. prefer filling the emptier bins that still fit.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 2.0;
        }
    }

    // Fragmentation guard: penalize leaving residuals that nothing (>=10) can use.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual as u32 {
        score += 6.0;
    }

    // Time horizon: as the stream nears its end, prioritize exact packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (1.0 + progress) * norm_pr * norm_pr * cap * 0.5;
    score += coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 6.0 * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: penalize blocking the next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 3.0 + 3.0 * (next_item_size as f64 - pr) / cap;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Penalize deviating from mean residual (avoid fragmentation)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for many open bins to encourage consolidation
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-to-high baseline so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it land in?
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap; // 0..1

    // Integer division thresholds on post_residual (harmonic bands of C)
    // Perfect fits (post_residual in {0}) are golden; small residues are dead space.
    if post_residual == 0 {
        score -= 500.0; // perfect fit: strongly favored
    } else {
        // dead-space penalty grows non-linearly for small unusable residues
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else { 0.0 };
        score += dead;
    }

    // Modulo class: post_residual divisible by common item sizes (10/20/25/50) is reusable
    let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0);
    if reusable {
        score -= 12.0;
    } else {
        score += 6.0;
    }

    // Coupling with next item: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            // harmonic band of the second-order leftover
            score -= 30.0 * (1.0 - (leftover2 as f64) / cap);
            if leftover2 == 0 {
                score -= 120.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 0.15 * (next_item_size as f64 - post);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // fresh bin baseline: slightly worse than a decent fit, better than awful fits
        score = cap * 0.55 - 0.3 * (next_item_size as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
    }

    // Progress-aware tightening: late in the stream, prefer compacting into open bins
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score += progress * 0.05 * open_bins_count as f64;

    // Mean-residual alignment: prefer bins near the mean residual (keeps bin set homogeneous)
    score += 0.2 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap is wasted capacity
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit: strongly reward
    }

    // Penalize bins whose residual becomes very small relative to typical items (1..100, mean ~50)
    if post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins with large residual (best-fit-like)
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // If next item cannot fit in post residual, mild penalty for creating a tight bin
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let base = 35.0 + 0.8 * open_bins_count as f64;
        // Opening a new bin is fine early or when open bins are nearly full
        let open_bins_fullness = bin_capacity as f64 - mean_residual;
        score = base - 0.4 * open_bins_fullness + 20.0 * progress;
        if fitting_bins_count == 1 {
            score += 60.0; // never open a new bin when an open bin is the only fit
        }
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

