    // Tight fit reward: near-full bins are valuable.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, unless residual is huge.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
    }

    // Early in stream: be slightly conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
