    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, mildly convex in normalized residual
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (superlinear)
    score += 6.0 * norm_post * norm_post * progress * progress;

    // Penalize bins whose residual is far above mean (fragmented bins)
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (post - nx).max(0.0) / cap;
        score -= 10.0 * (1.0 - fits_next * 4.0).max(-1.0);
        // penalize leaving residual that neither wastes nor helps
        score += 3.0 * fits_next;
    }

    // New-bin candidate handling: empty bin gets a smooth penalty that
    // decreases as stream progresses and few bins fit the item
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 25.0 + 30.0 * (1.0 - progress) * scarcity;
    }

    // Mild penalty for many open bins to discourage sprawl
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space is wasted capacity.
    // Penalize post_residuals that are too small to ever hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    }

    // Modulo-class logic: reward post_residuals in "usable" classes
    // (multiples of 10, or large enough to host half-size items).
    let pr = post_residual;
    if pr >= 10 {
        if pr % 10 == 0 {
            score -= 15.0; // round-class residual is reusable
        } else if pr % 5 == 0 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits the post_residual exactly,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if pr >= next_item_size {
            score -= 20.0; // next item still fits afterwards
        } else {
            // next item won't fit: this bin becomes closed after placement;
            // penalize more if we waste residual space
            score += (pr as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // but if residual waste is huge, soften the preference
        if post_residual > bin_capacity / 2 {
            score += 25.0;
        }
    }

    // New-bin candidate: neutral-ish baseline; only attractive when current
    // bins would leave large dead space. Empty bin has full capacity ahead.
    if bin_residual == bin_capacity {
        // baseline so that poor fits into existing bins lose to a new bin
        score = (bin_capacity as f64) * 0.35 + (item_size as f64) * 0.1;
        if fitting_bins_count <= 1 {
            score -= 40.0; // opening a bin is fine when nothing fits well
        }
    }

    // Fraction of capacity consumed by this placement: reward high fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Progression: late in the stream, be slightly greedier about tight fits
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - t) * 0.0 + t * (post_residual.min(50) as f64) * 0.1;

    // Mean-residual coupling: when open bins are already slack on average,
    // discourage adding more slack to them.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are fine,
    // but small-but-nonzero gaps that no future item can use are wasted.
    // Treat gaps below the minimum plausible item threshold as pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Reward when the next item exactly fits the leftover gap (k=2 lookahead).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // gap still usable by next item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // the empty-bin candidate (bin_residual == bin_capacity) gets penalized so it's
    // only chosen when fits into open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        // Mildly favor fuller bins (smaller residual before placement).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream consolidation: as the stream progresses, prefer packing into
    // existing bins even more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: penalize bins where the item leaves nearly no waste.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tightness).powi(8);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits after this placement: strong reward, scaled by exactness.
            score -= 30.0 * (1.0 - lookahead_gap / (bin_capacity as f64)).max(0.0);
        } else {
            // Next item would NOT fit: penalize, scaled by how badly it misses.
            score += 15.0 + lookahead_gap.min(60.0);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is huge
    // relative to capacity and no tight fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.75 {
            score -= 35.0; // huge item: new bin is fine
        } else {
            score += 25.0 + 30.0 * (1.0 - fill_ratio); // discourage wasting a fresh bin
        }
    }

    // Mild late-stream preference to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (open_bins_count as f64 / 10.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Strong penalty for large dead space that can only fit the smallest items.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 8.0; // still a decent slot for typical small items
    }

    // Last-chance bin: heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // extra reward if next item fills the bin exactly after placement
            if post_residual - next_item_size < 10 {
                score -= 15.0;
            }
        } else {
            // penalize leaving residual that wastes a bin on one item
            score += 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Global state: if many bins are open with small mean residual, prefer consolidating
    // into bins with residual close to mean (avoid fragmentation).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * dev;
        // when many bins are open, mildly discourage opening new bins
        if bin_residual == bin_capacity {
            score += 15.0 + 2.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Time horizon: early in the stream, be conservative (keep space flexible);
    // late in the stream, aggressively close out bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - fit_ratio);
    score += 10.0 * (1.0 - progress) * fit_ratio;

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 30.0; // last-chance open bin exists, prefer it
        } else {
            score += 10.0;
        }
    }

    // Slight preference for bins with more residual used overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: best-fit core (smaller post-residual wins).
    let mut score = pr;

    // Smooth non-linear dead-space penalty: residuals that are too small to
    // hold typical future items are waste. Use a smooth bump around the
    // mid-low residual band instead of a hard threshold.
    let dead_center = 15.0 + 10.0 * progress;
    let dead_width = 12.0;
    let dead_bump = (-((pr - dead_center).powi(2)) / (2.0 * dead_width * dead_width)).exp();
    score += 18.0 * dead_bump;

    // Reward tight fits: interaction of fill ratio with stream progress.
    let fill = 1.0 - pr / cap;
    score -= 8.0 * fill * fill * (0.5 + progress);

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin; if post-residual just barely misses it,
    // penalize smoothly.
    if nx > 0.0 {
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 10.0 * (-gap * gap / 50.0).exp();
        } else {
            score += 6.0 * (-gap * gap / 200.0).exp();
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling fuller bins first keeps many open bins flexible).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Mild preference spreading across many fitting bins: keep options open.
        score += 2.0 * (fitting_bins_count as f64).ln().min(3.0);
    }

    // New-bin candidate handling: an empty bin has pr = cap - item.
    // Discourage opening new bins unless existing fits are poor (high pr
    // relative to capacity) or late in the stream where consolidation matters.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let existing_quality = pr / cap; // for empty bin, pr = cap - item
        let pressure = 1.0 - (open_bins_count as f64).ln().max(1.0) / 5.0;
        score += 25.0 * pressure * (1.0 - progress)
            - 10.0 * existing_quality * existing_quality;
    }

    // Mild open-bin-count regularization: too many open bins fragment capacity.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let pr = post_residual as i64;
    let capi = bin_capacity as i64;
    let cls = pr % (capi / 4); // quarter-capacity harmonic class
    // Penalize residuals in "dead" classes (small, hard-to-fill slivers)
    if cls < capi / 20 {
        score += (capi / 20 - cls) as f64 * 1.5;
    }

    // Perfect-fit harmonic bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Fractional capacity classes: post_residual relative to capacity
    let frac = post_residual as f64 / cap;
    if frac < 0.1 {
        score += 25.0; // tiny leftover is nearly dead space
    } else if frac < 0.25 {
        score += 8.0;
    } else if frac > 0.75 {
        score -= 5.0; // large residual keeps bin versatile
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            score += 12.0; // next item won't fit here
        }
        // Harmonic match: next item size class aligns with residual class
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let base = 55.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin late in stream or when open bins are crowded
        let crowd = (mean_residual / cap).powi(2);
        return base + 20.0 * progress - 25.0 * crowd + (open_bins_count as f64) * 0.5;
    }

    // Mild penalty for deviating from mean residual (balance load)
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Tiny leftover gaps are "dead space": heavily penalize unusable slivers.
    if post_residual == 0 {
        score -= 40.0; // perfect fill: ideal
    } else if post_residual < 10 {
        score += 25.0; // sliver gap: nearly unusable, strong penalty
    } else if post_residual < 20 {
        score += 8.0;  // small gap: mildly wasteful
    }

    // Reward tight fits relative to capacity (lower post_residual => lower score)
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // next item fills this bin exactly: excellent
        } else if next_item_size <= post_residual {
            // next item fits with little waste: gentle reward
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: leftover likely becomes dead space
            score += 6.0;
        }
    }

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Opening a new bin while open bins fit: penalize, scaled by open-bin pressure
            score += 30.0 + 5.0 * open_bins_count as f64;
        } else {
            // No open bin can fit: new bin is necessary, encourage it
            score -= 10.0;
        }
    } else {
        // Pressure to consolidate into existing bins
        score -= 2.0 * open_bins_count as f64;

        // Last-chance bin: if this is the only bin that fits, strongly prefer it
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Mild alignment with the mean residual: prefer bins tighter than average
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward when post_residual matches the next item size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (next item fills bin exactly) => strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item could also fit here afterward: mild reward scaled by tightness.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit in the leftover: penalize dead space relative to gap.
            score += 0.6 * gap;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.1 * post_residual as f64;
    }

    // Prefer bins whose residual deviates from the mean (more specialized usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        score -= 40.0 - 0.3 * waste;
    }

    // Penalize opening a new bin when good fitting bins exist and the fit is decent.
    if bin_residual == bin_capacity {
        let good_alternative = next_item_size > 0
            && post_residual == next_item_size;
        if open_bins_count > 0 && fitting_bins_count > 0 && !good_alternative {
            score += 35.0;
        }
        // Early in the stream, slightly discourage bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    } else {
        // Reward tighter fits generally (small post residual).
        score -= 0.2 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;
    }

    // Slight preference to fill nearly-full bins completely.
    if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that no plausible item can fill (items >= 1, but
    // realistically mid-sized: treat residual < 10 as near-dead).
    if post_residual < 10 {
        score -= 25.0; // perfect fill is excellent
    } else if post_residual < item_size {
        score -= 8.0; // residual too small for a repeat of this item
    } else {
        score += 6.0; // large leftover is mildly wasteful
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new-bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits exactly or well into post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize proportionally to wasted lookahead
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Global state coupling: when many bins are open, prefer consolidation
    // into existing bins; when few bins are open, new-bin is cheaper.
    let consolidation = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open-bin count.
        score = 55.0 + 3.0 * consolidation;
        // Early in stream, new bins are more acceptable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is small, opening fresh is fine.
        score -= (mean_residual / 10.0).min(10.0);
        // If nothing else fits (no fitting open bins), new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: slight preference to keep bins balanced with mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * consolidation.sqrt();
        // Later in stream, fill existing bins more aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
