    score *= 1.0 + 0.8 * progress * (pr / cap);

    // Reward bins whose post-residual can still hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * tight * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Dead space relative to lookahead: penalize smoothly.
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 8.0 * dead * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild pull toward bins with residuals near the mean (balance open bins).
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate (empty bin): penalize unless item is large relative to capacity,
    // so we don't fragment many half-empty bins when a good fit exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 10.0 * (1.0 - fill) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fraction.
    // Classes: [0..=10) tiny, [10..=25) small, [25..=50) medium, [50..=75) large, [75..100] huge.
    let c = bin_capacity as f64;
    let frac = post_residual as f64 / c;

    // Dead-space penalty: leftover space that no plausible item (1..=100) can use
    // is only "dead" if < 1; otherwise smaller leftover = better fit (best-fit core).
    // Penalize leftovers in awkward harmonic bands (too small for mid items, too big to ignore).
    if post_residual > 0 {
        // harmonic class index via integer division on thresholds
        let class = post_residual / 25; // 0,1,2,3
        let class_penalty = match class {
            0 => 0.0,                    // tiny leftover: near-perfect fit, reward
            1 => 6.0,                    // 25..50: awkward medium gap
            2 => 3.0,                    // 50..75: large gap, still usable
            _ => 8.0,                    // 75..100: nearly empty bin used poorly
        };
        score += class_penalty;

        // Reward tiny leftovers (near-exact fits) nonlinearly
        if post_residual <= 10 {
            score -= 12.0 * (1.0 - frac);
        }
    } else {
        // Perfect fill: strong reward
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next fits: leftover after next item, harmonic penalty again
            let next_left = post_residual - next_item_size;
            score += (next_left as f64) * 0.4;
            if next_left <= 10 { score -= 8.0; }
        } else {
            // next item does NOT fit here: penalize proportionally to how much it misses
            let miss = next_item_size - post_residual;
            if miss <= 15 {
                score += 5.0 + miss as f64 * 0.3; // near-miss: painful
            } else {
                score += 1.0; // next item clearly belongs elsewhere: mild penalty
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which wastes this bin's residual forever).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // More open bins with slack -> opening new bin is cheaper (spreads load)
        let slack = mean_residual / c;
        score -= 10.0 * slack;
        // Early in stream, new bins are fine; late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins already fit the item, discourage the new bin further
        if fitting_bins_count > 1 {
            score += 10.0;
        }
    } else {
        // Mild preference for tighter open bins when many fit
        score += (fitting_bins_count as f64) * 0.5;
    }

    // Mean-residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins above the mean (consolidate the emptiest space usage).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Modulo harmonic nudge: leftover divisible nicely by common item sizes (10,20,25)
    // leaves reusable structure.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps too small to ever hold a plausible item (min size 1, but practically
    // small gaps < ~10 are near-unusable) are heavily penalized.
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    // Perfect fit: zero residual is ideal — big reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= dead_threshold {
        // tiny-but-nonzero residual: penalize proportionally to wasted fraction
        score += 25.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward fits where post_residual can still hold the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0; // kills chance to serve next item
        }
    }

    // --- Last-chance bin: strongly favor using the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- Open bins pressure: with many open bins, discourage opening new ones ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (18.0 + 10.0 * open_bins_count as f64 * (0.5 + progress));

    // Prefer placing into bins with below-mean residual (consolidate emptier space usage).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild tightness reward: item fills a large share of the residual.
    if bin_residual > 0 {
        score -= 8.0 * (item_size as f64 / bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: compare post_residual to next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step fit: bin becomes exactly full after next item
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits; reward closeness to a perfect follow-up fill
            let leftover2 = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - leftover2 / bin_capacity as f64);
            if leftover2 == 0.0 {
                score -= 15.0; // exact two-item exhaustion
            }
        } else {
            // Dead space: next item cannot use the remainder
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    } else {
        // Last item: prefer minimal residual, exact fill is ideal
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward bins that are already relatively full (small residual before placement)
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Prefer bins tighter than the mean residual (compact packing)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (post_residual in 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Early in the stream, slightly discourage opening many new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual gets extra bonus).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize dead space that no plausible item (>=1) could be assumed to fill:
    // larger post_residual is already the base score; add superlinear penalty.
    let pr = post_residual as f64;
    score += 0.08 * (pr * pr) / bin_capacity as f64;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use leftover: penalize proportionally to wasted slack
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 10.0 * progress;

    // Many open bins: discourage opening new ones; prefer filling existing ones.
    let open_f = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= 2.0 * open_f.sqrt();
    } else {
        // New-bin candidate: penalize more when many bins already open.
        score += 5.0 + 1.5 * open_f;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's tight — good target.
    let res_f = bin_residual as f64;
    score -= 0.1 * (mean_residual - res_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 8.0 * x * x * (1.0 - t) + 14.0 * x * x * x * t;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - x;
    score -= 10.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dev = x - mean_residual / cap;
    score += 6.0 * dev * dev;

    // Lookahead coupling: prefer residuals that still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = (x - nx).max(0.0);
        score -= 7.0 * (fits_next / (1.0 + nx)) * (0.3 + 0.7 * t);
        score += 4.0 * nx * x; // mild penalty when large next item looms
    }

    // Last-chance bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * t);
    }

    // Congestion pressure: many open bins -> discourage spreading, favor filling
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate: penalize opening a new bin, less so early in the stream
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.6 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect closures (0) and tiny dead zones
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // classify residual into harmonic buckets via integer division thresholds
        let class = pr / 10; // 0..=9
        let dead_penalty = match class {
            0 => 18.0,          // 1..9: nearly dead space
            1 => 12.0,          // 10..19
            2 => 7.0,           // 20..29
            3 => 3.0,           // 30..39
            4 => 1.0,           // 40..49
            _ => 0.0,
        };
        score += dead_penalty;

        // modulo arithmetic: residuals divisible by 5/10 are more reusable
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
    }

    // Lookahead: does next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + (next_item_size as f64 / cap) * 10.0;
            // harmonic coupling: next item exactly matches a residual class
            if pr != 0 && pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize proportional to overshoot class
            let overshoot = (next_item_size - pr) / 10;
            score += 2.0 + overshoot as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // no open bin closes well (high mean residual waste) or late in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (mean_residual / cap - 0.35).max(0.0);
        score = 20.0 + waste_pressure * 30.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item: fresh bin useful
        }
    }

    // Slight preference for bins with below-average residual (keep big gaps free)
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Congestion: many open bins -> prefer consolidation
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1) are pure waste; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Tight fits are gold: reward small post_residual non-linearly.
    if post_residual > 0 {
        score -= 25.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);
    } else {
        // Perfect fill
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space for the known next item
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, allow spreading (new bin cheaper).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (8.0 + 6.0 * progress);

    // Prefer bins whose residual is near the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Mean-residual coupling: bins far below mean residual are less attractive
    // to top up unless the fit is tight.
    if (bin_residual as f64) < mean_residual - item_size as f64 {
        score += 6.0;
    }

    // New-bin candidate: only attractive when it enables a very tight future fit
    // or current bins are hopelessly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pair-packing into fresh bin
        }
        score += 25.0 - 15.0 * fragmentation.min(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the
    // next item size (either exact or near fit for the upcoming item).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 400.0; // exact two-step chain: item then next item fills bin
        } else if (post_residual as u32) >= next_item_size {
            let gap = post_residual as f64 - next;
            // penalize leftover that next item can't use well
            score -= 50.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit into the residual: dead-space penalty scaled
            let waste = next - post_residual as f64;
            score += 0.8 * waste;
        }
    }

    // Penalize small unusable residuals (< 10, minimum item size) — dead space.
    if post_residual < 10 {
        score += 60.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps flexibility for future items.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Late in the stream, be more conservative: prefer tighter fits to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Mild penalty for opening a new bin when several bins already fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 30.0 + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Penalize opening a brand-new bin when open bins could still fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid wasting its space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item can still use the post-residual, keep this bin attractive;
    // otherwise the dead space becomes more costly.
    if next_item_size > 0 {
        let pr = post_residual as u32;
        if pr >= next_item_size {
            score -= 3.0 + 4.0 * (1.0 - progress);
        } else {
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;
    score -= 0.1 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    let mut score = pr;

    // Smooth polynomial coupling: dead space matters more as stream progresses.
    let x2 = x * x;
    let x3 = x2 * x;
    let poly = 1.0 + progress * (3.0 * x - 2.0 * x2 + x3);
    score += progress * (pr * poly - pr) * 1.5;

    // Penalize residuals that cannot fit the next item (smooth quadratic mismatch).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += gap * gap * cap * (0.5 + progress);
        } else {
            // Reward leaving room for the next item (smooth saturation).
            let slack = (pr - nx) / cap;
            score -= slack * (1.0 - slack) * cap * 0.3;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when residuals are small.
    let mean_r = mean_residual / cap;
    score += (open_bins_count as f64).ln().max(0.0) * mean_r * 2.0 * (1.0 - progress);

    // Perfect fit reward (smooth, decaying quadratic around zero residual).
    score -= (1.0 - x) * (1.0 - x) * 10.0 * (0.3 + 0.7 * progress);

    // New-bin candidate handling: neutral-ish, slightly favored early, penalized later.
    if bin_residual == bin_capacity {
        score = pr + 8.0 - 20.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let quarter = cap / 4;
    let eighth = cap / 8;

    // Penalize residuals falling in awkward harmonic classes
    let class = pr % quarter;
    if class != 0 {
        score += (class as f64) * 0.35;
    }
    // Reward residuals that are exact multiples of eighths (clean partition points)
    if pr % eighth == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % eighth;
            score -= (post_residual as f64 - next_item_size as f64) * 0.4;
            if nxt_class == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot fit: post_residual becomes dead space
            score += (post_residual as f64) * 0.25;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 15.0 + (fitting_bins_count as f64) * 3.0;
        // but allow new bin if mean residual is very low (all bins nearly full)
        score -= mean_residual * 0.2;
    }

    // Mild waste penalty relative to mean residual
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Small time-based tie-break jitter via deterministic class of step_index
    let tie = (step_index % 7) as f64 * 0.01;
    score += tie;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are worse than larger ones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the next item (perfect lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize blocking the next item.
        score += 12.0;
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // tight fits rather than spreading; when few bins, be pickier.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates badly from the mean (keeps pool uniform).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: prefer it only when current bin leaves a large dead gap
    // and many bins are already open.
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        let avg_gap = mean_residual.max(1.0);
        if avg_gap < 15.0 {
            score -= 30.0; // all bins nearly full -> open new bin
        } else {
            score += 20.0 + 2.0 * open_bins_count as f64;
        }
        let _ = dead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-item fill: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too; reward tighter leftover after the pair.
            let pair_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.35 * pair_left;
            // Extra reward if pair leaves a tiny, still-usable gap.
            if pair_left <= 10.0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit in this bin after placement: penalize by the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.25 * shortfall;
        }
    }

    // Reward leaving a residual close to (i.e. well below) the current mean residual:
    // tight packing relative to the fleet of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize creating large dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, prefer closing bins tightly rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // Slight preference to fill existing bins when many are open.
    score -= 0.05 * open_bins_count as f64;

    // New-bin candidate: keep it neutral-ish; only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it only
    // when existing bins are crowded and the fit is poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so open bins with decent fits win.
        score += 40.0;
        // More attractive late in the stream or when few bins remain open.
        score -= 20.0 * progress;
        score -= 2.0 * open_bins_count as f64;
        // If mean residual is small (bins nearly full), a new bin is reasonable.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 25.0;
    }

    // Mild pressure toward consolidating into bins below mean residual (balance).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Time-horizon modulation: early on, be greedy about tight fits; later, be
    // more conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 8.0 * fit_ratio;
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 - 1.8 * t + 1.2 * t * t; // smooth decay curve
    score *= poly;

    // Reward tight fits: quadratic bonus as post_residual shrinks
    let tight = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 14.0 * tight * (0.4 + 0.6 * t);

    // Penalize dead space that cannot fit next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 10.0 + 6.0 * (1.0 - t);
    }

    // Reward exact lookahead fit
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 18.0;
    }

    // Last-chance bonus: strongly prefer filling a bin when few alternatives
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening new bins when open bins have room, scaled by progress
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * (1.0 - t) + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins below mean residual (fill emptier bins first) — smooth coupling
        score += 0.15 * (mean_residual - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class via integer division on post_residual (classes of size 10):
    // residuals that are "nice" (small or exactly reusable) get rewarded.
    let class = post_residual / 10;
    match class {
        0 => score -= 40.0,            // nearly full bin: excellent
        1 => score -= 20.0,            // 10-19 left: still useful for small items
        2 | 3 => { score += 5.0; }     // mediocre dead space
        4 | 5 => { score += 15.0; }    // half-empty: wasteful unless item was large
        _ => { score += 25.0; }        // large residual left: poor packing
    }

    // Continuous fraction penalty, quadratic in wasted fraction.
    score += frac * frac * 60.0;

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize leaving residual that just barely fails to fit next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += miss * 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if item is large relative to capacity, new bin is fine.
        score -= (item_size as f64 / cap) * 30.0;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.8 {
        score -= 25.0 * (fill - 0.8);
    }

    // Modulo harmonic on post_residual: residuals divisible by 5 are more reusable
    // under common item sizes.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Mild pressure to reduce number of open bins when mean residual is small.
    if (mean_residual - pr).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
