    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; residual likely becomes dead space
        score += 12.0;
    }

    // Last chance: this is the only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(1.3) * (0.4 + 0.6 * progress);

    // Mean residual coupling: if this bin is above mean residual, it's a good host
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // but if item is huge, opening fresh bin is reasonable
        if item_size > 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
