    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 - gap.min(25.0);
    }
    // If next item is bigger than post_residual but fits elsewhere, mild penalty for wasting space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual (best-fit-like sharpening).
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fullness;

    // When many bins are open, consolidation is valuable; when few, new bins are cheap.
    let open_pressure = open_bins_count as f64;
    score += (post_residual as f64) * (1.0 + 0.02 * open_pressure);

    // New-bin candidate handling: empty bin should only win when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if post_residual > 30 { 1.0 } else { 0.0 };
        score += 35.0 - 20.0 * poor_fit - 10.0 * (1.0 - progress);
        // If next item is huge and this item nearly fills a bin, opening fresh is fine.
        if next_item_size >= 60 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty if this bin's residual deviates far below mean (fragmentation risk).
    let dev = mean_residual - post_residual as f64;
    if dev > 15.0 {
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth interaction: residual waste penalized more as stream progresses
    score *= 1.0 + 0.6 * progress * norm_pr;

    // Tight fit reward (quadratic bowl around zero post-residual)
    score -= 10.0 * (1.0 - norm_pr).exp() * (item_size as f64 / cap);

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: penalize if next item fits the post-residual poorly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (pr - nxt) / cap;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.5 * (mean_residual - pr);

    // Slight new-bin penalty to prefer filling existing bins early
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let post = post_residual as u32;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Reward residuals that fall into "usable" harmonic classes (multiples of 10/20)
    let class_mod = post % tenth;
    if class_mod == 0 {
        score -= 6.0; // perfectly aligned residual, easy to fill later
    } else if class_mod <= 2 {
        score -= 2.0;
    } else {
        score += class_mod as f64 * 0.8; // penalize off-class dead space
    }

    // Quarter-class logic: residual near half or quarter capacity is valuable
    let half = bin_capacity / 2;
    if post >= half {
        score -= 3.0;
    } else if post >= quarter {
        score -= 1.0;
    } else if post < fifth {
        // tiny residual: near-dead space unless exactly consumed by next item
        score += 5.0;
    }

    // Lookahead coupling: does next_item_size fit the post_residual harmonically?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == post {
            score -= 12.0; // perfect future fill
        } else if nxt <= post {
            let new_res = post - nxt;
            score -= 4.0;
            score += (new_res % tenth) as f64 * 0.5;
            if new_res == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize more if residual is mid-sized
            if post > quarter && post < half {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 30.0;
        // but attractive early in the stream or when many bins already open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // if mean residual across open bins is small (fragmented), new bin is fine
        if mean_residual < cap * 0.2 {
            score -= 8.0;
        }
    } else {
        // Prefer filling bins with larger current residual (best-fit-ish)
        score += (cap - bin_residual as f64) * 0.05;
        // Many open bins: encourage consolidation into existing bins
        score -= (open_bins_count.min(20) as f64) * 0.15;
    }

    // Mild late-stream tightening: waste hurts more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (>=10) are wasted space; penalize them quadratically.
    if post_residual > 0 {
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 40.0 * dead * dead / 10.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Prefer bins whose residual tightly matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new bin has bin_residual == bin_capacity and large post_residual anyway).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead space relative to next item.
        score += 10.0;
    }

    // Keep score anchored to post_residual scale.
    score += mean_residual * 0.05 - 0.05 * bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
