pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large unusable leftovers (dead space below typical item sizes).
    if post_residual < 10 {
        score -= 25.0; // near-perfect closure
    } else if post_residual < item_size {
        score -= 8.0; // dead space too small for anything
    } else {
        // Small leftovers that still fit small items are fine
        score -= 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 + 25.0 * progress;
        // If the item barely fits anywhere, opening a new bin is reasonable.
        if fill_ratio > 0.9 {
            score -= 30.0;
        }
        // If many open bins already exist, discourage spreading.
        score += 2.0 * open_bins_count as f64;
        // If the mean residual is large, existing bins are roomy; prefer them.
        score += 0.3 * mean_residual;
    }

    // Lookahead: if next item can exactly use the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use leftover: penalize proportionally to wasted space.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Mild global pressure: when open bins are numerous, favor filling existing ones.
    if bin_residual != bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let x = pr / cap; // normalized post residual in [0,1]
    let t = progress.clamp(0.0, 1.0);
    let coupling = x * x * (1.0 - x) * (1.0 + 3.0 * t) + x * (1.0 - t) * 0.5;
    score += 40.0 * coupling;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 30.0 * t);

    // Penalize creating residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (nxt - pr) * (1.0 + t);
        } else if pr >= nxt {
            score -= 5.0 * (pr / nxt.min(cap)) * t;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residuals below mean (avoid fragmenting large residual bins)
    score += 0.3 * (pr - mean_residual).max(-cap) * 0.1;

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln() * (1.0 - t) * 2.0;

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        score -= 5.0;
        if pr < 20.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead space" classes
    // (small residuals unlikely to fit typical items) get penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 30.0 * (dead_threshold - post_residual) as f64;
    }

    // Modulo classes on post_residual: values near multiples of common item sizes
    // (10,20,25,50) are reusable, reward them.
    let reusable_mods = [10u32, 20, 25, 50];
    for m in reusable_mods.iter() {
        let r = post_residual % m;
        let dist = (*m - r).min(r);
        if post_residual > 0 {
            score -= 6.0 * (1.0 - dist as f64 / (*m as f64 / 2.0)) * (post_residual.min(*m) as f64 / 10.0);
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally
            let over = next_item_size - post_residual;
            score += 8.0 * over as f64 / 10.0;
        }
    } else {
        // last item: prefer tightest fit (post_residual base already does this)
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let good_fit = post_residual as f64 <= 20.0;
        if good_fit {
            score += 60.0; // don't open new bin for a tight fit
        } else {
            score += 5.0 + 10.0 * (1.0 - progress);
        }
        // more open bins => less eager to open another
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are "dead". Penalize the
    // dangerous band (1..=9) heavily, scaled by how close to death it is.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Exact lookahead match is even better.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Bin becomes unusable for the known next item: penalize.
        score += 6.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but discourage opening new bins when the count is already high.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make empty bins moderately unattractive unless
    // nothing better exists; the base residual (=capacity) already ranks
    // it poorly, add a mild extra penalty that grows with stream progress.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Prefer bins whose residual is below the mean (consolidating
        // nearly-full bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // Penalize opening new bins when good alternatives exist
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 0.5;
    }

    // Early stream: be a bit more conservative (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing useful can occupy (dead-space band).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    }
    // If the next item cannot fit here but would fit elsewhere, mild penalty for blocking.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_capacity {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress;
        // More open bins -> prefer packing into existing ones.
        score += 2.0 * open_bins_count as f64;
        // If open bins are fragmented (high mean residual spread across many bins), new bin is fine.
        if open_bins_count > 0 && mean_residual > 40.0 {
            score -= 12.0;
        }
    } else {
        // Slight preference for bins already below average residual (consolidating waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // Reward filling nearly-full bins to close them out.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Mild time-horizon modulation: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals become more valuable (harder to fill later)
    let coupling = (pr * pr) / (cap * cap) * (progress * (1.0 - progress) * 4.0);
    score += coupling * (pr - 0.5 * cap) * 0.5;

    // Penalize residuals that cannot fit the lookahead item (smoothly)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) as f64;
        score += (gap * gap) / cap * 2.0;
        // Reward residuals that nicely fit the next item
        let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
        score -= fit_quality.max(0.0) * 6.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open and this placement wastes space
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins whose residual is typical or small
    score += ((pr as f64 - mean_residual) / cap).abs() * 3.0;

    // New-bin candidate: mild bias so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable space" classes.
    let class = post_residual % 10;
    // Dead-space penalty: small nonzero residues are worst (wasted slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if class == 0 {
        // Perfect multiple-of-10 residual is highly reusable.
        score -= 8.0;
    } else if class >= 5 {
        score -= 3.0;
    } else {
        score += 4.0;
    }

    // Integer-division threshold: how many "average items" still fit.
    let avg_item = 45.0f64;
    let fits_avg = (post_residual as f64 / avg_item).floor();
    score -= fits_avg * 5.0;

    // Capacity fraction coupling: tight fill reward.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: prefer leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how well next item slots into post_residual (harmonic match).
            let next_class = (post_residual - next_item_size) % 10;
            let match_bonus = if next_class == 0 { 12.0 } else if next_class >= 5 { 6.0 } else { 2.0 };
            score -= match_bonus;
        } else if post_residual > 0 {
            // This placement strands the next item.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or residuals are fragmented.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score += 10.0 + congestion * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Stream progression: early on, be conservative with new bins; late, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (mean_residual / 10.0);

    // Spread pressure: many open bins with high mean residual -> favor filling existing.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Mid-range dead space (10..=20) also mildly penalized.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Mean residual coupling: prefer bins deviating below the mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate: keep it competitive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.2;
        // Late in the stream, opening new bins is cheaper than long dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize dead space below a usable threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable slivers
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here: strong chain bonus scaled by tightness.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 8.0 * (gap / bin_capacity as f64);
        }
        // Exact 2-item chain fill (post_residual == next_item_size) is ideal.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: minimize waste directly.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins tighter than average are precious; waste them only if fit is near-perfect.
    let tightness = mean_residual - bin_residual as f64;
    score += 0.25 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer the bin with the smallest post_residual.
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Penalize new bin slightly when open bins exist and can fit; reward when none do.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 35.0 * urgency;
        } else {
            score -= 10.0;
        }
        // Late in stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Mild progression scaling: as stream advances, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual more than linearly
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize bins whose residual is far from mean residual (outlier bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Lookahead: if next item could use the post_residual, reward leaving useful space
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Leaving space exactly useful for next item is good
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Post-residual too small for next item: dead space risk
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.3;
        }
    }

    // New-bin candidate handling: only attractive when current bins are poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win
        score += 120.0;
        // More attractive early (many future items justify a fresh bin)
        score -= (1.0 - progress) * 40.0;
        // More attractive when many bins are open and fragmented
        score -= (open_bins_count as f64).min(20.0) * 2.0;
        // Attractive if mean residual is low (open bins are mostly full)
        score -= mean_residual * 0.3;
        // Attractive if no bins fit (item_size > all residuals) — but only via fitting_bins_count==0 case handled by caller; still soften
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // If next item is huge, a fresh bin with full residual is valuable
        if next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Mild preference for filling fuller bins as stream progresses
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    // Small tie-breaker noise-free deterministic term
    score += (bin_residual as f64 * 0.001);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: waste hurts more as stream progresses.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * (post / cap) * post * 0.02;

    // Reward near-perfect fits (post_residual close to 0) with a smooth dip.
    let tight = (-post / 12.0).exp();
    score -= 8.0 * tight;

    // Lookahead synergy: if the next item could fill the remaining space, reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let synergy = (-gap / 15.0).exp();
        score -= 6.0 * synergy * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: sole fitting bin is precious.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize opening new bins when many bins are open and mean residual is high.
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if new_bin {
        score += 5.0 + 4.0 * (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).sqrt() + 10.0 * progress;
    } else {
        // Slight preference for bins below mean residual (balancing load).
        score += 0.05 * (post - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let post = post_residual as f64;
    let post_mod = post_residual % 10; // fine granularity class
    let post_mod20 = post_residual % 20;
    let post_quarter = post_residual / (bin_capacity / 4); // quarter-capacity class

    // Penalize dead space: small but nonzero post_residual is worst (unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64; // tiny leftover heavily penalized
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic quarter-class bonus: leaving residuals in coarse classes
    // (>= half, or small multiples of 20) keeps future pairing viable
    if post_quarter >= 2 {
        score -= 6.0; // residual >= half capacity is reusable
    }
    if post_mod20 == 0 && post_residual > 0 {
        score -= 4.0; // residual aligned to 20-grid pairs with mid-size items
    }
    if post_mod == 0 && post_residual > 0 {
        score -= 2.0; // aligned to 10-grid
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect pairing bonus scaled by how well it fills
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 10.0 + 15.0 * fill;
            // harmonic match: next item's class aligns with residual class
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize unless residual is large anyway
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer opening when existing residuals are poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.6;
        if mean_residual < 12.0 && open_bins_count > 0 {
            score -= 20.0; // existing bins nearly full -> new bin reasonable
        }
        if next_item_size > 0 && next_item_size >= 60 && item_size >= 60 {
            score -= 10.0; // two big items: fresh bin keeps them separable
        }
    }

    // Slight preference for tighter bins among equals
    score += 0.05 * (bin_residual as f64 - post);

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, DEAD_MAX] are nearly unusable.
    const DEAD_MAX: u32 = 9;
    if post_residual > 0 && post_residual <= DEAD_MAX {
        score += 45.0; // heavy penalty for creating a dead gap
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward leaving space exactly usable by the next item (lookahead k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + DEAD_MAX {
        score += 8.0; // next item would leave a dead gap here
    }

    // Tight fit bonus: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure from open bins and mean residual.
        score += 20.0 + 2.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing bins have plenty of room; avoid new bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else {
        // Mild bonus for filling existing bins when many are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Early stream: be slightly greedy on existing bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled against mean residual.
    score += (post_residual as f64 - mean_residual).max(-50.0) * 0.15;

    // Aggressive 2-step lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: strong reward proportional to how well it fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 + (slack_after_next as f64).min(40.0) * 0.25;
        } else {
            // Post-residual becomes dead space relative to the next item.
            score += 6.0 + (post_residual as f64).min(50.0) * 0.1;
        }
    } else {
