        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize leaving large unusable gaps (below typical small item size).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral baseline; slight penalty so tight fits in open bins win,
        // but large items with no good home can still open a new bin.
        score += 10.0;
        if item_size > 60 && next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // Big item followed by another big item: opening fresh bins is good.
            score -= 18.0;
        }
    }

    // Late-stream consolidation: favor reusing bins as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64).min(20.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits strongly (small post_residual relative to item)
    score -= (item_size as f64) * (1.0 - (post_residual as f64 / bin_capacity as f64)) * 1.5;

    // Penalize large dead space: post_residual too small for any plausible future item (min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // nearly unusable sliver
    }

    // Lookahead coupling: bonus if next item fits exactly into the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: prefer the one with least waste, penalize slack mildly
        score += (bin_residual as f64 - item_size as f64) * 0.1;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation into existing bins
    if open_bins_count > 4 && mean_residual > (item_size as f64) {
        score -= 5.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    // Prefer existing bins generally; open new bin only when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base penalty for new bin; waived when it's the only option or late stream
        score += 25.0 * pressure * (1.0 - progress);
        // If current item is large and would leave awkward residue elsewhere, new bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 18.0;
        }
    }

    // Time horizon: early on, keep bins flexible (penalize very tight closes); late, greedily fill
    if progress < 0.3 && post_residual < 20 && post_residual > 0 {
        score += 8.0 * (0.3 - progress) * 10.0;
    } else if progress > 0.7 {
        score -= (bin_capacity - post_residual) as f64 * 0.05;
    }

    // Slight preference for bins with below-mean residual (consolidate emptier bins)
    score += ((mean_residual - bin_residual as f64).abs()) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

