    let smooth = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * norm_pr * norm_pr * (1.0 + smooth);
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * smooth;

    // Penalize dead space relative to mean residual
    score += 10.0 * (pr - mean_residual).abs() / cap;

