        }
        // late in stream, avoid new bins more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Crowding: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10) can use
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Small-but-usable residual: mildly reward tight packing.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins rather than spreading; with few bins, be pickier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * (1.0 - progress));

    // Prefer bins whose residual is below the stream mean (fill the emptier ones less).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // or no bin fits well. Baseline keeps it competitive but slightly disfavored.
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * pressure.min(3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Next item fits comfortably in the post residual (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize dead space proportional to gap.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post residual) relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current item is huge relative
    // to typical residuals, or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if big_item || open_bins_count > 8 {
            score += 25.0 - 20.0 * progress; // mild penalty, decreasing late
        } else {
            score += 80.0; // discourage wasting a fresh bin early
        }
    }

    // Slight preference for bins with less residual overall (fill fuller bins).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let tight = if post_residual == 0 {
        -60.0
    } else {
        let r = post_residual as f64;
        -(20.0 * (1.0 - r / bin_capacity as f64).powi(6))
    };
    score += tight;

    // Penalize dead space that can't fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits in post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else if next_item_size == post_residual {
            score -= 30.0;
        } else {
            // Next item won't fit; penalize proportionally to wasted chain potential.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many fitting bins: mild penalty for using a scarce-residual bin when alternatives exist.
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Global state: when mean residual is low, conserve remaining space more aggressively.
    let mr = mean_residual / bin_capacity as f64;
    score += 8.0 * mr * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in stream, prefer closing bins tightly; early, keep options open.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * (post_residual as f64 / bin_capacity as f64) * 10.0;
    score -= (1.0 - t) * 3.0;

    // New-bin candidate: only attractive when current fit is bad and open bins are few.
    if bin_residual == bin_capacity && item_size > 0 {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if poor_fit && open_bins_count > 0 {
            score += 15.0; // discourage new bin when decent fits exist
        } else if open_bins_count == 0 {
            score -= 20.0; // must open first bin
        }
        score += 0.3 * open_bins_count as f64;
    }

    // Mild penalty for bins that are already quite full (prefer filling emptier bins first).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score += 4.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual, with non-linear shrink of large residuals as stream progresses
    let mut score = pr * (1.0 + 0.6 * progress * (pr / cap).powi(2));

    // Penalize residuals that are small but nonzero (dead space) — quadratic coupling
    if pr > 0.0 {
        score += 8.0 * (1.0 - pr / cap) * (pr / cap).powf(1.5) * cap;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 12.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - pr / nxt.max(1.0)) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Mean residual alignment: prefer bins near the mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: prefer opening a new bin when current fits are tight
    if bin_residual == bin_capacity {
        score = pr + 5.0 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (dead-space granularity)
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    // Penalize awkward residues that few item sizes can ever fill (items 1..100)
    // Residue 0 is perfect; small residues (1..9) are hard to fill exactly.
    if pr > 0 && pr < 10 {
        score += 12.0 + residue; // tiny dead space is nearly worthless
    } else if pr >= 10 {
        // reward post_residuals that are exact multiples of common item sizes
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
    }

    // Fraction-of-capacity harmonic thresholds on post_residual
    let frac = post_residual as f64 / cap;
    if frac > 0.5 { score -= 6.0 * frac; }          // roomy remainder is good
    else if frac > 0.25 { score -= 2.0 * frac; }
    else if frac > 0.0 { score += 4.0 * (0.25 - frac) * 4.0; } // thin slivers penalized

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 { score -= 10.0 - gap as f64; }
            else { score += gap as f64 * 0.15; }
        } else {
            // next item won't fit here; residual becomes dead space unless large
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // all open bins would leave bad fits; scale with stream progress & congestion
    if bin_residual == bin_capacity {
        score = 40.0 + (post_residual as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;                 // later: new bins cheaper to open
        score += 2.0 * open_bins_count as f64;    // congestion: prefer reusing bins
        if mean_residual > item_size as f64 {
            score += 5.0;                          // some open bin likely fits better
        }
    }

    // Mild tie-break: prefer tighter (already-used) bins
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized,
    // since item sizes can be as small as 1 under the interface contract.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect closure is highly desirable: subtract a large bonus.
        score -= 60.0;
    } else {
        // Mild reward for leaving a gap that can still fit a typical small item.
        score -= 5.0;
    }

    // Open-bins pressure: prefer reusing existing bins; opening new bins is costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (20.0 + 30.0 * progress + 2.0 * open_bins_count as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor fit elsewhere.
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly in the post_residual,
    // reward this placement strongly; if post_residual cannot fit the next
    // item but is too large to be dead space, mildly penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.2 * tight;
        } else {
            score += 8.0;
        }
    }

    // Coupling with mean residual: bins with residual below the mean are
    // already "tight"; filling them further is good (reduces fragmentation).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0 * ((res - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward: post_residual == 0 is perfect.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size
    // (either it fits exactly, or next item can also go elsewhere).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 50.0; // chain fit: next item fills this bin exactly
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit here: leftover becomes dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual: leaving a residual far
    // below mean means we consumed a large chunk of a relatively roomy bin.
    let cap = bin_capacity as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 0.3 {
            score += 8.0 * (0.3 - ratio); // drained a roomy bin
        } else if ratio > 1.5 {
            score -= 4.0 * (ratio - 1.5).min(2.0); // kept roomy bins roomy
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the fit into open bins is poor (large post_residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more as stream progresses (consolidate late).
        score += 25.0 + 40.0 * progress;
        // But if this is a tight fit (small post_residual), new bin is fine.
        score -= (100.0 - pr) * 0.1;
        // If no open bin fits well, allow new bin: fitting_bins_count == 0
        // means only the new-bin candidate exists besides poor options.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Small penalty for tiny dead space (< 10) that nothing can use later,
    // scaled by how many bins are already open (fragmentation cost).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    // Mild normalization by open bins: prefer spreading load when many bins open.
    score -= 0.1 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize bins whose residual after placement is small.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness).powi(3);

    // Lookahead: if the next item can exactly fit the post-residual, strongly favor.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving large residuals.
            score += 3.0 * tightness;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 0.5 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_quality = (mean_residual - item_size as f64).abs();
        score += 30.0 + 10.0 * progress;
        if avg_fit_quality > 20.0 {
            score -= 15.0; // existing bins are poor fits, allow new bin
        }
    }

    // Penalize bins that are outliers vs. mean residual (keep bin states homogeneous).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    // Mild preference for bins with more residual when many bins are open (balance load).
    score += 0.05 * (post_residual as f64) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are acceptable; late, they become costly.
    let norm_res = pr / cap;
    score += progress * (norm_res * norm_res) * cap * 0.8;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - norm_res) * (1.0 - norm_res) * (1.0 + progress) * 6.0;

    // Perfect fit reward (smooth, non-linear).
    if pr == 0 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward leaving space for the next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= (1.0 - g * g) * 8.0;
        } else {
            score += (-gap / cap) * (1.0 + progress) * 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // Penalize spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - norm_res);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalized non-linearly.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.5;

    // New-bin candidate: penalize opening a fresh bin, more so later in the stream
    // and when other bins could fit.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 20.0 + 25.0 * progress + 15.0 * fit_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: dead space is "reusable" if it matches common size classes
    let r = post_residual;
    let reusable = |x: u32| -> bool {
        x % 10 == 0 || x % 25 == 0 || x % 20 == 0
    };
    if r > 0 && r < 10 {
        score += 15.0; // tiny dead space is nearly useless
    }
    if reusable(r) {
        score -= 8.0;
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack_after_next = r - next_item_size;
            score -= 20.0 + 0.1 * slack_after_next as f64;
            if slack_after_next % 10 == 0 {
                score -= 10.0; // leaves a clean class
            }
        } else {
            score += 12.0; // closes the bin for the next item
        }
    } else {
        score -= 5.0; // last item, just fill anything
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 60.0; // big next item: better to start fresh bin
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Progress-aware mild pressure to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * mean_residual * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
