    // Non-linear penalty on residual relative to capacity: gaps that can't
    // plausibly hold a typical small item are dead weight.
    let r = post_residual as f64 / bin_capacity as f64;
    if r > 0.0 && r < 0.15 {
        score += 15.0 * (0.15 - r) / 0.15;
    }

    // Tightness reward: the closer the fit, the better.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are badly congested
    // (this bin's residual is a poor fit) or many bins are already open.
    if bin_residual == bin_capacity {
        let congestion = (bin_residual as f64 - post_residual as f64 - item_size as f64).abs();
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        // Default: opening a new bin is discouraged.
