        if mean_residual < item_size as f64 * 1.1 {
            score -= 45.0;
        }
        if pressure > 8.0 {
            score -= 10.0;
        }
        let _ = congestion;
    }

    // Lookahead: if the next item would fit into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in post residual but would fit a fresh bin,
    // slightly penalize leaving a nearly-full bin when a new bin is cheap.
    if next_item_size > post_residual as u32 && next_item_size > 0 && post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Mild open-bins pressure over long streams: consolidate as stream matures.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match bonus (strong), scaled down for near matches.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score -= (20.0 / (1.0 + gap * 0.05)) * (next_item_size as f64 / bin_capacity as f64);
        }
        // If next item cannot fit into post_residual, penalize proportionally to wasted lookahead.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: simply minimize residual, with slight exact-fill bonus.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Prefer tight fits relative to mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize creating tiny unusable slivers (< 10, minimum item size for classic range; use 1 for unknown).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly early in stream (keep bins consolidated),
    // but allow opening a new bin when existing bins would leave large waste.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0; // fresh bin fits both current and next item well
        }
    }

    // Slight preference for bins with more residual when many bins are open (consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Reward near-perfect fills of the current bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear dead-space penalty.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead;

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < item_size.min(10) {
        score -= 10.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins -> we can afford to be picky; penalize loose fits more.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0) * dead;
    }

    // Lookahead coupling: if next item fits into this bin's post_residual, reward;
    // if post_residual is small but nonzero and next item is large, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // chain fit quality
            let chain = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * (1.0 - chain);
        } else {
            // next item cannot use leftover: leftover is dead space unless tiny
            if post_residual >= next_item_size * 2 {
                score += 2.0;
            }
        }
    } else {
        // last item: maximize fill
        score -= 40.0;
    }

    // Global residual state: if mean residual is high, prefer consolidating into
    // already-open bins rather than opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // opening a new bin: penalize, less so late in stream or when item is large
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_penalty = 35.0;
        open_penalty -= 15.0 * progress;
        open_penalty -= (item_size as f64 - 50.0) * 0.1;
        // if mean residual across open bins can't plausibly host future items, new bin ok
        if mean_residual < item_size as f64 * 0.5 {
            open_penalty -= 10.0;
        }
        // if next item is huge and no open bin has room for it, new bin is fine
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            open_penalty -= 8.0;
        }
        score += open_penalty.max(0.0);
    } else {
        // using an existing bin: small reward scaled by how average it is vs mean
        score -= 5.0;
        if (bin_residual as f64 - mean_residual).abs() < 10.0 {
            score -= 3.0;
        }
    }

    // Early stream: be conservative, keep bins balanced; late stream: fill aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - dead);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual) but keep some slack for future items.
    // Late stream: strongly penalize large residuals (dead space can't be recovered).
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like base in [0,1]
    let coupling = poly * (1.0 - progress) * 20.0 + poly * progress * 45.0;
    score += coupling;

    // Reward filling bins tightly when item fits well (smooth quadratic in wasted space).
    let waste = (x * x) * cap * (0.5 + progress);
    score += waste;

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if next item could fit in post_residual, reward leaving usable space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 10.0 * fit_quality * (1.0 - progress);
        } else {
            // next item won't fit: penalize large residual less at end of stream
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mild penalty for opening new bins when many open bins have slack.
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 15.0 + 25.0 * slack * (1.0 - progress);
    }

    // Encourage consolidating among many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * (x * 3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues near multiples of common
    // small item sizes are "reusable classes". Class via integer division.
    let class = post_residual / 10; // 0..10 classes of width 10
    let in_class = post_residual % 10;

    // Reward small post_residual (tight fit) super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead harmony: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt = next_item_size as f64;
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 + 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize if next item barely misses this residual (dead space trap).
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 15.0;
    }

    // Harmonic class reward: residuals divisible by 10 (class 0 boundary)
    // are more likely to accommodate future integer items.
    if in_class == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Odd / prime-ish residues are poor classes; penalize.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Many fitting bins -> prefer tightest (already via post_residual),
    // but penalize spreading across too many open bins.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate: penalize so it only wins when all open bins fit badly.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
    }

    // Early stream: be slightly conservative, keep residuals balanced vs mean.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical items are wasted.
    // Penalize sharply when post_residual falls into the "unusable gap" zone (1..=15).
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 30.0 * (1.0 - slack / 10.0);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: dead space unless another bin helps.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing) — penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: opening a fresh bin should only win when the fit elsewhere
    // is terrible. Give the empty bin a moderate baseline penalty.
    if bin_residual == bin_capacity {
        score += 15.0 + post_residual as f64 * 0.5;
        // But if the current item is large relative to capacity, a fresh bin is fine.
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fit with the NEXT item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward tight chaining.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize wasted space.
            score += 0.5 * gap;
        }
    }

    // Favor bins whose residual is already below mean (tight bins get closed out).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 0.3 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item leaves a useful chunk and
    // existing bins are all poor fits (high post_residual everywhere).
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual non-linearly (dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can pair into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize residuals that are too small to be useful for the next item.
            let waste = (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs()) * 0.05;
            score += waste.max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: only attractive when current open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 15.0;
        // Cheaper to open new bin when many bins have large mean residual (fragmentation).
        score -= 0.05 * mean_residual;
        // Early in stream, opening bins is fine; late in stream, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If several bins fit, discourage opening yet another.
        score += 6.0 * (fitting_bins_count as f64).min(4.0);
    } else {
        // Prefer bins with residual close to item_size (minimize leftover gap).
        let gap = (bin_residual - item_size) as f64;
        score += 0.1 * gap;
        // Slight preference for bins whose residual is below mean (pack tight bins first).
        score += 0.03 * (mean_residual - bin_residual as f64);
    }

    // Mild exploration coupling with open bin count: many open bins -> encourage filling.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // later in the stream, dead space matters more (quadratic growth).
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward filling a bin nearly exactly, smoothly via cubic term
    score -= 25.0 * (1.0 - pr_norm).powi(3) * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item won't fit here anyway; mild penalty for wasting large residual
        score += 5.0 * pr_norm;
    }

    // Penalize bins far from mean residual (prefer homogeneity), smooth term
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for opening new bins when many are open, smooth in open count
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space in (0,10) is nearly unusable
    // for items in [1,100]; residual classes by integer division thresholds.
    let dead = post_residual < 10;
    if dead {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Modulo-class coupling: a residual that is an exact multiple of common
    // item sizes (10,20,25,50) is more reusable -> reward.
    let r = post_residual;
    if r == 0 {
        score -= 40.0; // perfect fill
    } else if r % 50 == 0 || r % 25 == 0 || r % 10 == 0 {
        score -= 15.0;
    } else if r % 20 == 0 {
        score -= 12.0;
    }

    // Lookahead harmony: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size <= r {
            score -= (r - next_item_size) as f64 * 0.15;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 90 {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.1;
        if post_residual >= 90 {
            score -= 30.0;
        }
    }

    // Progress: later in the stream, prefer tighter packing (waste less).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Prefer bins already below mean residual (concentrate usage).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small to be useful later.
    let dead_threshold = 10.0f64;
    if post_residual < dead_threshold && post_residual > 0.0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Strongly reward tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual as u32 {
        score += 3.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // But if current bin would leave a bad dead space, opening fresh is better.
        if post_residual > 0 && post_residual < dead_threshold as u32 {
            score -= 45.0;
        }
        // With few open bins, opening a new one is less costly.
        if open_bins_count < 3 {
            score -= 15.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - tightness);

    // Mean residual coupling: if mean residual is high, prefer bins below mean (fill fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: massive reward.
        if diff == 0.0 {
            score -= 1000.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits here: mild reward proportional to tightness.
            score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit after placement: penalize dead space.
            score += 20.0 + diff * 0.5;
        }
    }

    // Prefer filling bins that are already relatively full (below mean residual).
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no existing bin fits well. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 100.0 * fill_ratio;
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 60.0; // new bin can also host the next item
        }
        // Late in stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Tight fits (small post_residual) are generally good.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (1.0 - progress);
    } else {
        score += 4.0 * progress;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 30.0 * scarcity - 20.0 * big_item + 10.0 * progress;
    }

    // Mild preference for bins that are already fairly full.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic penalty on leftover space (dead space grows quadratically worse).
    let mut score = post * post / cap;

    // Tight fits are strongly rewarded: smooth non-linear coupling of fit ratio.
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (post / cap).exp();

    // Late in the stream, prefer filling existing bins aggressively (avoid new bins).
    let late = progress * progress;
    score -= 25.0 * late * (bin_residual as f64 / cap);
    score += 20.0 * late * (1.0 - (bin_residual as f64 / cap));

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * late;
    }

    // Many open bins with high mean residual: discourage spreading waste.
    let open_norm = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_norm * (post / cap);

    // Lookahead: penalize bins whose leftover cannot host the next item,
    // reward bins whose leftover leaves a good slot for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (1.0 - post / cap);
        }
        // If next item fits perfectly after this placement, big reward.
        if (post - nxt).abs() <= 1.0 {
            score -= 15.0;
        }
    }

    // Slight bias toward emptier bins early on (keep flexibility).
    let early = 1.0 - progress;
    score += 5.0 * early * (1.0 - bin_residual as f64 / cap);

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score = 8.0 + 60.0 * (1.0 - fragmentation) * (1.0 - late) - 30.0 * late * fragmentation;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a unique fitting bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals that nothing can pair with.
        // Class A: pr in (50, 80) -> too small for large items, too big to waste.
        if pr > 50 && pr <= 80 {
            score += 30.0 + (pr as f64 - 50.0) * 2.0;
        }
        // Class B: pr in (30, 50) -> mid dead zone.
        if pr > 30 && pr <= 50 {
            score += 12.0;
        }
        // Harmonic division: reward residuals that divide capacity nicely (capacity % pr small).
        let div = bin_capacity % pr.max(1);
        score += (div as f64) * 0.8;

        // Reward residuals that are harmonic with common item sizes (modulo classes).
        let harm = (10..=80).step_by(10).map(|s| ((pr as i64 - s as i64).abs()) as f64).fold(f64::INFINITY, f64::min);
        score += harm * 0.15;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bins are nearly full / bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = 1.0 - (mean_residual / cap).min(1.0);
        score = cap - 60.0 * tight + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= (1.0 - bin_residual as f64 / cap) * 20.0;

    // Tie-break with open bin count: consolidate when many bins open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Small residuals (< 10, min item size) are pure dead space.
        if post_residual < 10 {
            score += 50.0 + (10.0 - dead) * 8.0;
        } else if post_residual <= 25 {
            // Small but potentially usable gaps: moderate penalty scaled by tightness.
            score += (25.0 - dead) * 1.5;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly reward using the only fitting bin to avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no good fit exists.
    if bin_residual == bin_capacity {
        // Opening a new bin is neutral baseline; add mild cost so good existing fits win.
        score += 5.0;
        // But if existing fit would leave tiny dead space, new bin becomes attractive
        // (handled implicitly by the dead-space penalty above).
        if post_residual == bin_capacity - item_size {
            // Large item in fresh bin: reward if item is big (efficient fill).
            score -= item_size as f64 * 0.3;
        }
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit post residual but fits elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Stream progression: later in stream, slightly more consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // Mean residual coupling: penalize placements that deviate far from mean residual
    // (keeps bin residuals homogeneous, easier future packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 45.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(25.0); // exact match for next item => big bonus
            if slack == 0.0 {
                score -= 20.0; // perfect chaining
            }
        } else {
            // next item cannot fit here; penalize proportionally to wasted opportunity
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.6;
        }
    }

    // Penalize small unusable dead space (< 10) relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.35;

    // New-bin candidate: penalize mildly, but allow it when open bins are all poor fits
    if bin_residual == bin_capacity {
        let base = 20.0;
        let crowd = (open_bins_count as f64).sqrt() * 1.5;
        let lookahead_ok = next_item_size > 0 && post_residual >= next_item_size;
        score += base + crowd - if lookahead_ok { 10.0 } else { 0.0 };
        // late in the stream, consolidation matters more
        score += (step_index as f64 / total_items.max(1) as f64) * 8.0;
    }

    // Mild tie-break toward denser bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fills get a strong discount.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted space, amplified for large items.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * waste_ratio * 40.0 * (item_size as f64 / 100.0);
    }

    // Lookahead: favor bins whose post_residual can host the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + next_item_size as f64 / 10.0;
        } else {
            // Penalize leaving a sliver that nothing can use later.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more selective (avoid fragmenting);
    // late in the stream, pack greedily into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;
    score += (1.0 - progress) * (post_residual as f64 / 100.0) * 5.0;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (compact bins), keep big-residual bins free.
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or no reasonable fit exists; otherwise penalize spreading.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.9 {
            score -= 20.0; // big item: fresh bin is fine
        } else {
            score += 15.0 + (1.0 - tightness) * 20.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0; // don't open fresh bins when chaining is possible elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    score += norm_pr * norm_pr * cap * (0.35 + 0.45 * p2);
    score -= 18.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > pr {
        score += 12.0 * (1.0 - progress) * (pr / cap);
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild preference for bins tighter than the mean residual
    score += 0.15 * (pr - mean_residual) * (0.5 + progress);

    // New-bin candidate: penalize slightly so it is chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: residual mod 10 defines "waste class"
    let waste_class = post_residual % 10;
    score -= (10 - waste_class) as f64 * 0.5; // prefer residuals near multiples of 10

    // Dead zone: residuals that cannot fit the smallest plausible item
    let min_item: u32 = 10;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0; // unusable sliver
    }

    // Lookahead coupling: does post_residual fit next item exactly?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // chain perfect fit
        } else if post_residual >= next_item_size {
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 200.0;
            } else if post2 < min_item {
                score += 20.0; // creates sliver for the future
            }
            // harmonic residue match between post2 and capacity fractions
            let frac = (post2 * 100) / bin_capacity;
            if frac % 4 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; slight penalty if this was its only chance
            score += 10.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins early in the stream or when many fit
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 30.0 * (fitting_bins_count as f64).sqrt();
        }
        // but reward it if the current item is huge relative to typical residuals
        if (item_size as f64) > mean_residual {
            score -= 45.0;
        }
    }

    // Tightness reward: item fills a large fraction of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 25.0;

    // Mean residual coupling: prefer bins far from the mean (extremes are useful)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    // Integer division threshold on post_residual vs capacity quarters
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual < 2 * quarter {
        score -= 3.0; // residual in a "usable band"
    } else if post_residual >= 3 * quarter {
        score += 2.0; // large leftover suggests item was too small for this bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead space penalty: residuals too small for the next item are wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Unusable gap for the lookahead item: penalize proportionally to how close it is to zero.
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        } else {
            // Gap still usable: mild bonus.
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open bin pressure: mild preference to consolidate into existing bins
    // when many bins are already open.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: make the empty bin unattractive unless the fit is bad
    // (post_residual == bin_capacity - item_size is large, meaning a small item
    // into a fresh bin wastes capacity). Base cost for opening a new bin:
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow new bin if placing here would leave a very tight residual elsewhere:
        // i.e., if this item is large relative to capacity, a fresh bin is fine.
        score -= 10.0 * fill_ratio;
    }

    // Slight stream-progression adaptation: as the stream nears its end,
    // prefer tighter packing (dead space matters more since no future recovery).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Prefer bins whose residual deviates from the mean less (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / (bin_capacity as f64));
            if slack == 0.0 {
                score -= 50.0; // perfect 2-step chain
            }
        } else {
            // dead space relative to lookahead item
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize leaving residuals in the awkward zone (1..10) that few items fit
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Prefer bins below mean residual (keep large residuals available for big items)
    score += 0.4 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Mild penalty for opening a new bin when other bins fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // But allow new bin early in stream or when open bins are crowded
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 12.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 60.0;
    }

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current item is large
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = (mean_residual - item_size as f64).abs();
        let mut new_bin_penalty = 55.0
            - 20.0 * progress
            - 0.3 * open_bins_count as f64;
        if item_size >= 50 {
            new_bin_penalty -= 25.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            new_bin_penalty -= 15.0;
        }
        if waste_elsewhere < 15.0 {
            new_bin_penalty += 20.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Mild preference for bins with smaller residual among open bins.
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Time-horizon term: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post-residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 4.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Penalize dead space that cannot fit a typical next item (smooth quadratic)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let gap = x - nx;
        if gap < 0.0 {
            score += 3.0 * gap * gap;
        } else {
            score -= 1.5 * gap * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 2.5 + 2.0 * progress;
    }

    // Mild pressure to prefer bins below mean residual (balance load smoothly)
    score += 0.5 * (pr - mean_residual) / cap;

    // Slight penalty for very fragmented state late in stream
    score += 0.3 * (open_bins_count as f64) * x * progress;

    // New-bin candidate: neutral baseline with smooth decay as stream progresses
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) - 1.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste classes in mod-10 arithmetic.
    let waste_class = post_residual % 10;
    // Dead space penalty grows super-linearly for small unusable remainders.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - waste_class) as f64;
    }

    // Capacity-fraction classes: prefer post_residual that is a "harmonic" fill
    // (exact quarters / halves of capacity leave clean future fits).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == quarter || post_residual == half || post_residual == 0 {
        score -= 12.0;
    } else if post_residual % quarter == 0 {
        score -= 6.0;
    }

    // Integer-division threshold on next_item_size: does the lookahead item
    // divide cleanly into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Perfect harmonic match: lookahead divides post-residual exactly.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 8.0;
            }
            // Lookahead leaves a good class after its own placement.
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Lookahead cannot use this bin's remainder; penalize slightly
            // proportional to how "wasted" the residual is.
            score += 0.05 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < 10 {
            score -= 15.0; // near-perfect packing, seal it
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive when existing residuals are large
        // (item fits poorly everywhere) but unattractive when this bin would
        // be a great fit in an open bin.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 5.0; // big items: fresh bin is fine
        } else {
            score += 30.0; // prefer existing bins for small/medium items
        }
        // More open bins with slack -> less reason to open another.
        score += 0.5 * open_bins_count as f64;
        // If mean residual across open bins is small, new bin is reasonable.
        score -= 0.3 * mean_residual;
        // Early stream: allow opening bins more freely.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer tighter fits among open bins: reward low post-residual.
        score -= 0.1 * (bin_capacity - post_residual) as f64;
        // Prefer bins whose residual is close to the item (harmonic match).
        let gap = bin_residual.saturating_sub(item_size);
        if gap % 10 == 0 {
            score -= 3.0;
        }
    }

    // Modulo-class tie-break on item size classes (harmonic bins).
    let item_class = item_size % 10;
    if item_class >= 8 && post_residual < 15 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, or below
    // the smallest conceivable item) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Penalize gaps that are too small for the lookahead item but nonzero:
    // they are dead space for at least the next placement.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward residual close to the mean residual (keeps bin population uniform,
    // preserves flexibility across bins).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * drift;

    // Open-bin pressure: discourage opening new bins early in the stream;
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize so it is only chosen when open bins fit badly.
        score += 25.0 + new_bin_bonus;
        // But if the item is large relative to capacity, a fresh bin is attractive.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    } else {
        // Reward using bins that are already committed.
        score -= 0.3 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer it to avoid opening a bin that will
    // otherwise hold only this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer bins whose leftover can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect 2-chain match: strong reward.
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Reward proportional to how snugly the next item fits after this one.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize if we leave a large dead gap.
        let dead = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
        score += 0.5 * dead;
    }

    // Penalize leaving residuals below the smallest possible item (unusable dead space),
    // scaled by how tight the item was (small item into big bin is wasteful unless chain exists).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins that are already partially filled relative to the fleet mean (tight packing).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current item is large and would leave a big gap elsewhere).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste_if_used = (bin_capacity - item_size) as f64;
        // Base penalty so open bins win when they fit decently.
        score += 45.0;
        // A new bin becomes attractive for very large items (small waste) or when many bins are open with high mean residual.
        score -= 0.8 * waste_if_used * (1.0 - progress);
        score -= 0.2 * mean_residual * (open_bins_count as f64).ln().max(1.0);
        // Late in the stream, prefer consolidating into open bins.
        score += 40.0 * progress;
    }

    // Mild reward for tighter fits overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear dead-space penalty).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 300.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64 / bin_capacity as f64) * 60.0;
    }
    // Penalize leaving a gap that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Time horizon: early in the stream, allow more freedom to open bins;
    // late in the stream, strongly prefer existing bins to avoid waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when other bins fit.
        let mut new_bin_penalty = 20.0 + 80.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 50.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual && item_size <= bin_residual {
            // item fits trivially in a new bin anyway; no special reward
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: reward slightly more as stream progresses.
        score -= 10.0 * progress;
    }

    // Mild penalty for having many open bins already (encourage consolidation).
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 2.0 * progress * (1.0 - x) * (1.0 - x));

    // Penalize large dead space quadratically, damped early in the stream
    score += 0.5 * x * x * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only one that fits
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 1.5 * (next_item_size as f64 / cap);
    }

    // Mild penalty when bin residual deviates from mean residual
    score += 0.1 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / cap;
    // Dead-space classes: post_residual in [0..=10] excellent, (10..=25] ok, (25..=50] poor, >50 bad.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 25 {
        score -= 40.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        score += 30.0; // large dead space penalized
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10 align with
    // typical item-size classes (sizes often multiples of 5/10), making the
    // leftover reusable. Reward harmonic alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 35.0;
    } else if post_residual % 5 == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let nfrac = next_item_size as f64 / cap;
            // reward proportionally, favoring tight next fits
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            // harmonic class of next leftover
            let nl = post_residual - next_item_size;
            if nl % 10 == 0 {
                score -= 25.0;
            }
            let _ = nfrac;
        } else {
            // next item cannot use this bin's leftover: penalize small leftovers mildly
            score += 10.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it moderately
    // attractive only when current fit is poor or no good residual exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many items remain
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 60.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // pairing large items together in fresh bin
        }
        return score;
    }

    // Prefer tighter bins: reward small pre-fit residual relative to item.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * tightness * tightness;

    // Slightly prefer bins with below-mean residual (compact usage pattern).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Late in stream: be greedy, minimize waste aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - frac);

    // Integer division threshold: post_residual / item_size class
    let div_class = if item_size > 0 { post_residual / item_size } else { 0 };
    if div_class >= 2 {
        score += 15.0; // leftover could hold 2+ more items: keep such bins flexible, mild penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual that is too small to hold even the smallest item (1)
    // is pure waste; penalize hard if it's a "dead" gap.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: heavily reward
    } else if post_residual < 10 {
        // unusable sliver under typical min item size: strong penalty
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap cannot fit the lookahead item: dead space risk
        score += 12.0;
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 8.0;

    // --- Open bins pressure: discourage hoarding many open bins ---
    score += open_bins_count as f64 * 1.5;

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- New bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if existing bins fit poorly
        // (large post_residual elsewhere) or many bins are already open.
        let baseline = 55.0 + mean_residual * 0.15 + open_bins_count as f64 * 2.0;
        score = baseline + post_residual as f64 * 0.5;
        // Late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Mean residual coupling: bins far below mean residual are "fresher";
    // slightly prefer filling bins with larger residuals first (keep small gaps together).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: penalize dead space quadratically (small residuals are fine only if usable).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward if the next item fits exactly/well into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect match for next item is strongly rewarded.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward if the pair (item + next) nearly fills the bin.
            if gap <= 5.0 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to the overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 20.0;
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, more when many bins are open.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the current item is large and would leave a bad residual elsewhere,
        // the penalty shrinks (handled implicitly since open-bin scores get lookahead penalties).
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Late in the stream: prioritize consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by relative fill of the bin.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large post-residual dead space, especially small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // sliver penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure bonus
    }

    // Lookahead coupling: reward if next item can fit into post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 3.0 * open_pressure;

    // Time horizon: early in stream, allow new bins more freely; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 8.0 - progress * 10.0;

    // Mean-residual alignment: prefer bins whose residual is below mean (tighter bins).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: only attractive when current bin would leave bad waste.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;
    let mut score = r as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_r * (1.0 - norm_r); // peaks at half-full bins
    score -= 18.0 * poly * (1.0 + t);
    score += 10.0 * norm_r * norm_r * (0.5 + t);

    // Tight fit reward, stronger late in stream
    let tight = (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    score -= 15.0 * tight * (0.4 + 0.6 * t);

    // Lookahead: reward if next item fits post residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= r {
        let fit_q = (next_item_size as f64 / cap).powi(2);
        score -= 8.0 * fit_q;
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance fitting bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize divergence from mean residual (keeps bin pool homogeneous)
    score += 0.08 * ((r - mean_residual).abs());

    // Slight new-bin penalty when few bins open
    score += 4.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large powers
    // of 2 (or by 5) tend to accommodate future items drawn from typical
    // granularity classes, so reward them; odd/small-class residuals penalized.
    let pr = post_residual;
    let class2 = if pr == 0 { 6 } else if pr % 10 == 0 { 4 } else if pr % 5 == 0 { 2 } else if pr % 2 == 0 { 1 } else { 0 };
    score -= 2.5 * class2 as f64;

    // Integer-division thresholds on post_residual: dead space below the
    // minimum plausible item size is worthless.
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr >= 10 && pr < 20 {
        score += 8.0;
    }

    // Perfect fill is ideal.
    if pr == 0 {
        score -= 100.0;
    }

    // Coupling with next item: reward residuals that exactly or nearly fit
    // the lookahead item (harmonic resonance between classes).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += pressure + 0.5 * open_bins_count as f64 + 0.2 * mean_residual;
        // Late in the stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild preference for tighter bins overall.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize when this placement blocks the next item from fitting here
    // while the residual is still technically usable.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, spreading is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 20.0);
    score += bin_pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only make it attractive when the current bin would leave a bad gap
    // or when existing bins are already tight.
    if bin_residual == bin_capacity {
        let bad_gap = post_residual > 0 && post_residual < 10;
        if bad_gap {
            score -= 30.0; // opening a fresh bin beats creating dead space
        } else {
            score += 25.0 + mean_residual * 0.3; // prefer existing bins otherwise
        }
    }

    // Mild preference for bins tighter than the average residual
    // (best-fit flavor with dead-space awareness).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero dead space)
    if post_residual == 0 {
