    }

    // Penalize leaving tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Early in the stream, mildly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing bins fit poorly or are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_state = (mean_residual / bin_capacity as f64 - 0.2).clamp(0.0, 1.0);
        let pressure = 60.0 * scarcity + 30.0 * poor_state * (1.0 - progress);
        // Base cost of a fresh bin, discounted by pressure.
        score = 55.0 - pressure;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 5.0; // large item first, small item later fits the fresh space
        }
    }

    // Mild dispersion penalty: prefer bins whose residual is near the mean
    // (keeps the pool of usable residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late stream: consolidate aggressively into fewer bins.
    score += 0.01 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth polynomial shaping
    let x = pr / cap; // in [0, 1]
    // Favor small post-residuals (tight fits) via convex penalty on wasted space
    let waste_term = x.powf(2.2) * 60.0;

    // Smooth interaction: waste matters more as the stream progresses
    let progress_coupling = waste_term * (0.6 + 1.2 * progress);

    // Reward tight fit (small x) with a smooth negative dip
    let tight_fit_reward = -(1.0 - x).powf(3.0) * 25.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    let last_chance = if fitting_bins_count <= 1 { -18.0 } else { 0.0 };

    // Lookahead coupling: prefer residuals that can still host the next item
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr >= next_item_size as f64 {
            -8.0 * (1.0 - nx) // reward if next item fits in leftover
        } else {
            6.0 * nx // penalize dead space unusable by next item
        }
    } else {
        0.0
    };

    // Mild penalty for spreading across many bins late in stream
    let spread = (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    let dev_term = dev * dev * 10.0;

    let score = pr + progress_coupling + tight_fit_reward + last_chance + lookahead + spread + dev_term;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 25 (C/4)
    let class = post_residual % 25;
    // Classes with small residue (0,1,2) are "perfect fits" — strongly reward
    if class == 0 {
        score -= 30.0;
    } else if class == 1 || class == 2 {
        score -= 12.0;
    } else if class >= 3 && class <= 10 {
        // mid-dead-space: mildly penalize
        score += 4.0 + 0.3 * class as f64;
    } else {
        // large leftover but still reusable
        score -= 2.0;
    }

    // Integer-division thresholds on post_residual: chunks of 20
    let chunks = post_residual / 20;
    score -= 6.0 * chunks as f64;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // harmonic class coupling: next item leaves perfect residue
        if (post_residual - next_item_size) % 25 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize small leftovers more
        if post_residual < 20 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: discourage opening a new bin unless the item is large
    // or stream is early and many bins will be needed anyway
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_bonus = (open_bins_count as f64).sqrt() * 2.0;
        score += 18.0 + open_bonus - 10.0 * progress;
        if item_size >= 50 {
            score -= 8.0; // large items pair well in fresh bins
        }
    }

    // Fraction-of-capacity coupling: reward filling to capacity fractions
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
