    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += crowding * 0.8 * (1.0 - progress);

    // Mean residual alignment: bins close to mean residual are "typical"; slight reward.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: only attractive when item is huge relative to capacity
