    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let best_open_fit = if fitting_bins_count > 0 { mean_residual } else { cap };
        if item_frac > 0.6 || mean_residual < item_size as f64 * 0.5 {
            score -= 5.0;
        } else {
            score += 8.0 + open_bins_count as f64 * 0.5;
        }
        let _ = best_open_fit;
    }

    // Prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Early in the stream, keep residuals flexible (favor balanced splits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are wasted. Penalize sharply in the "dead zone".
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling with dead space: if post_residual is small but still usable
    // by the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: potential dead space.
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: only attractive when current bins are
    // heavily fragmented (high mean residual spread) or item is large and
    // fits nowhere well.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins mildly by default; reduce penalty when existing
        // bins are very fragmented and the item is large.
        let large_item_bonus = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        score += 30.0 + fragmentation * 0.3 - large_item_bonus;
        // Late in the stream, opening a fresh bin is less harmful.
        score -= progress * 10.0;
    }

    // Mild preference for bins with residual close to item (best fit flavor)
    // beyond raw post_residual ordering.
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
