pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: small post-residual that is unusable relative to typical item sizes
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If next item cannot fit in post_residual, mild penalty proportional to wasted opportunity
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer tighter bins relative to mean residual
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Penalize placing small items into large-residual bins (save space for big items)
    if item_size < 40 && bin_residual > 80 {
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early or when
    // no open bin fits well. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 15.0 + openness * 2.0 - progress * 10.0;
        // If this is a last-chance situation, don't open a new bin
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 60.0;
        }
    }

    // Mild time-horizon term: later in the stream, consolidate more aggressively
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64;
    let prog2 = progress * progress;
    let coupling = pn * pn * (1.0 - progress) + pn * prog2 * 2.0;
    score += coupling * bin_capacity as f64 * 0.5;

    // Penalize large dead space more aggressively as stream progresses.
    score += (pr / bin_capacity as f64).powi(3) * 30.0 * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth quadratic bonus.
    let tightness = 1.0 - pn;
    score -= tightness * tightness * 10.0;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot use the post_residual.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 6.0 + 0.1 * next_item_size as f64 * (0.5 + progress);
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // New-bin candidate: prefer it only when existing fit is terrible.
    if bin_residual == bin_capacity {
        let base = 55.0 + 20.0 * progress;
        score += base;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight penalty for bin much emptier than mean residual (keep bins balanced).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "useful" residue classes (multiples of common item sizes) are favored.
    let cap = bin_capacity as f64;

    // Dead-space penalty: leftover that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: reward post_residual divisible by small common sizes.
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 8.0 + (d as f64) * 0.2;
        }
    }

    // Integer-division threshold: leftover that can host next_item_size exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact harmonic match with the lookahead item.
            if post_residual == next_item_size {
                score -= 60.0;
            } else if post_residual % next_item_size == 0 {
                score -= 15.0;
            } else {
                // Penalize leftovers that leave awkward fragments after next item.
                let frag = post_residual % next_item_size;
                if frag > 0 && frag < 10 {
                    score += 12.0;
                }
            }
        } else {
            // This bin becomes dead after placement; penalize proportionally.
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score = cap - item_size as f64; // its post_residual is what matters
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // If a decent fit exists elsewhere, discourage opening new bins.
        if fitting_bins_count > 0 && (bin_residual - item_size) as f64 > mean_residual {
            score += 25.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    } else {
        // Mild preference for tighter bins: compare residual to mean.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Progress-aware: late in the stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * (post_residual as f64).sqrt() * 2.0;
    }

    // Fraction-of-capacity coupling: penalize large leftover fractions.
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score += 5.0 * (frac - 0.5);
    }

    // Open-bin count pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space): post_residual in [1, 9]
    // is nearly useless for future items (min size 1..100 unknown, but tiny gaps waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits generally: smaller post_residual relative to bin capacity
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Penalty proportional to open bins count: discourage spreading across many bins
    score += open_bins_count as f64 * 2.5;

    // Penalize bins whose residual is far above mean (fragmentation avoidance)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 70.0;
        } else if slack < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this bin's leftover: mild dead-space penalty
        score += 20.0;
    }

    // New-bin candidate: prefer opening a new bin when existing residuals are large
    // and item is big, but avoid opening bins too eagerly early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * big_item - 10.0 * progress;
        // If no open bin fits well (post_residual huge waste elsewhere), new bin attractive
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Dead-space penalty: penalize residuals that are hard to fill later
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 25.0; // tiny residual is fine
        } else if dead > 50.0 {
            score += dead * 0.3; // large wasted space
        }
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain placement possible: strong reward proportional to tightness
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 40.0 - chain_tight.min(30.0) * 0.5;
        } else {
            // Next item won't fit: penalize based on how much we "stranded"
            let stranded = (next_item_size - post_residual) as f64;
            score += stranded * 0.4;
        }
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (consolidating) unless this bin would become a perfect match
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.25;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists. Penalize new bin moderately; exact fits elsewhere win.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But if next item is huge and current item small, new bin can be OK
        if next_item_size > 70 && item_size < 30 {
            score -= 40.0;
        }
    }

    // Late in stream: be more conservative, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty for leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: penalize if leftover space is small but nonzero and unusable by next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving space exactly usable by the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Prefer filling bins that are already mostly empty (consolidate waste).
    if bin_residual < bin_capacity {
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 20.0 * fill_ratio;
    } else {
        // New-bin candidate: penalize slightly so we only open new bins when fits are bad.
        score += 25.0;
        // But if existing bins leave large dead space for the next item, new bin becomes attractive.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer packing into existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // Time horizon: late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very small leftovers that nothing (10..80 range) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post-residual, quadratic coupling with stream progress:
    // early on, small residuals are fine; late in the stream, waste is penalized harder.
    let norm_pr = pr / cap;
    score += (norm_pr * norm_pr) * (1.0 + 40.0 * progress) * cap * 0.1;

    // Smooth cubic interaction: penalize mid-range residuals that become dead space as stream advances.
    score += (norm_pr * pr * 0.001) * (progress * progress) * 10.0;

    // Last-chance bin: strongly reward using it (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Reward tight fits: item fills most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * fill * 8.0;

    // Lookahead: bonus if next item fits the post-residual.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that no future item likely uses.
        score += (pr / (next_item_size as f64).max(1.0)) * 2.0;
    }

    // Fragmentation pressure: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 1 {
        score += (mean_residual / cap) * (open_bins_count as f64).ln() * 3.0;
    }

    // New-bin candidate should score moderately high unless open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: prefer residuals that are
    // multiples of 10 (classic item-size quantum), penalize odd residues.
    let class = post_residual % 10;
    score += match class {
        0 => -6.0,
        5 => -2.0,
        2 | 8 => 1.5,
        _ => 2.5,
    };

    // Integer-division threshold: how many "typical" small items (size 10)
    // still fit after placement. Reward more divisible residual space.
    let slots = post_residual / 10;
    score -= slots as f64 * 1.2;

    // Coupling with lookahead: if the next item fits exactly into the
    // post_residual, strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use the leftover: penalize dead space more
            // when the gap is small-but-unusable.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded (low mean residual) or many bins already exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - 20.0 * crowding - 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
        if post_residual == 0 {
            score -= 10.0; // perfect fit in a fresh bin
        }
    }

    // Prefer bins with residual close to the item (tight fits) via
    // capacity-fraction term.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (below the minimum plausible item footprint) are
    // effectively wasted, so punish them hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Non-linear penalty: small-but-usable gaps are risky dead space.
    if post_residual > 0 {
        score += (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 0.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward heavily (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space locked against the known next item.
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // mean residual already suggests slack capacity.
    let pressure = open_bins_count as f64 * 0.05;
    score += pressure;

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the residual (good fit ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit or open bins are saturated.
    if bin_residual == bin_capacity {
        let decent_fits = if mean_residual >= item_size as f64 { 1.0 } else { 0.0 };
        if fitting_bins_count == 0 || decent_fits == 0.0 {
            score -= 25.0; // opening a fresh bin is better than forcing a bad fit
        } else {
            score += 20.0; // prefer existing bins when they fit reasonably
        }
    }

    // Mild stream-progression adaptation: later in the stream, be more
    // conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize leftover space, normalized.
    let mut score = post / capacity;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect packing of the following item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        score += diff / capacity;                       // penalize mismatch
        if post >= nxt {
            score -= 0.6 * (nxt / capacity);            // reward feasibility of lookahead
        }
        // Exact wrap (post == next): strongly favored.
        if (post as u32) == next_item_size {
            score -= 0.8;
        }
        // Lookahead leaves near-zero residue after next item too.
        if post >= nxt {
            let post2 = post - nxt;
            if post2 <= 5.0 {
                score -= 0.4 * (1.0 - post2 / 5.0);
            }
        }
    } else {
        // Last item: minimize leftover hard.
        score += 0.5 * (post / capacity);
    }

    // Compare against mean residual of open bins: prefer bins whose post
    // residual lands near the fleet mean (keeps flexibility balanced),
    // but strongly prefer dumping into already-fragmented bins.
    let dev = (post - mean_residual).abs() / capacity;
    score += 0.3 * dev;
    if bin_residual as f64 <= mean_residual {
        score -= 0.25; // favor below-average-residual bins (tight fit first)
    }

    // Last-chance bin: if this is the only bin that fits, strongly avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins; the penalty shrinks if the item is large
        // relative to capacity (little to gain from squeezing) and if the
        // current fit would leave large dead space anyway.
        let dead = post / capacity;
        let tightness = (item_size as f64) / capacity;
        score += 0.9 - 0.5 * tightness - 0.4 * dead;
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 0.5 * progress;
        // Many open bins with slack: discourage proliferation.
        score += 0.05 * open_bins_count as f64;
    } else {
        // Reward using existing bins, more so as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 0.3 * (1.0 - progress);
    }

    // Slight preference for near-full outcomes regardless of path.
    if post <= 2.0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (waste minimization with diminishing returns).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize bins whose leftover would be a "dead zone": too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // leftover in this band is often reusable; mild reward
        score -= 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot follow here; mild penalty proportional to mismatch
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (miss / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64) * 0.05);
    score += 8.0 * pressure * tightness;

    // Bin much emptier than average: slight penalty (save big bins for big future items).
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 5.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 3.0;
    }

    // Late in the stream: be conservative, close out bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * tightness;

    // NEW-BIN CANDIDATE handling: only attractive if current fit is bad or no real alternative.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // perfect-fit items (>80) justify a fresh bin; otherwise discourage.
        if fit_ratio > 0.8 {
            score -= 20.0;
        } else {
            score += 35.0 + 20.0 * (1.0 - fit_ratio);
            if fitting_bins_count == 0 {
                score -= 60.0; // no alternative: must open
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let shape = 1.0 + progress * (norm_pr * norm_pr) - (1.0 - progress) * (norm_pr * 0.5);
    score *= shape;

    // Penalize wasted space more aggressively late in the stream
    score += progress * norm_pr * norm_pr * cap * 0.3;

    // Reward tight fits
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can hold next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Penalize proliferation of open bins relative to mean residual
    score += open_bins_count as f64 * (mean_residual / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (small remainders that many future items can fill).
    let pr = post_residual;
    // Dead-space penalty grows super-linearly for tiny unusable remainders.
    if pr > 0 {
        let dead = (1.0 - (pr as f64) / cap).powi(6);
        score += 40.0 * dead;
    }

    // Reward near-perfect fits (post_residual in {0,1,2,3,5}) via modulo classes.
    let perfect_class = pr == 0 || (pr <= 5 && (pr % 2 == 0 || pr % 5 == 0));
    if perfect_class {
        score -= 60.0;
    } else if pr % 10 == 0 {
        // Residual divisible by 10 is highly reusable for 10..80 items.
        score -= 25.0;
    } else if pr % 5 == 0 {
        score -= 12.0;
    }

    // Integer-division threshold: bins whose residual can host the lookahead item get a bonus.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Chain potential: this bin can also serve the next item.
            let chain = (pr / next_item_size.max(1)) as f64;
            score -= 10.0 + 5.0 * chain.min(3.0);
        } else {
            // Post-residual too small for the next item: penalize proportionally.
            score += 8.0 * (1.0 - (pr as f64) / (next_item_size as f64));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter fits (smaller post_residual already encoded).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Fresh bin: score is full capacity minus small structural discount.
        score = cap;
        // Discount if current item leaves a reusable harmonic residual.
        let ipr = bin_capacity - item_size;
        if ipr % 10 == 0 { score -= 20.0; }
        else if ipr % 5 == 0 { score -= 8.0; }
        // If existing bins are fragmented (high mean residual spread), opening new is fine.
        score -= 6.0 * (mean_residual / cap);
        // Early in the stream, prefer packing into open bins less aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    } else {
        // Filling an open bin reduces fragmentation slightly relative to mean.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream urgency: squeeze items into open bins to avoid leftover bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for unusable dead space: residuals too small for the
    // smallest possible item (size 1..100 unknown distribution -> treat < ~15 as risky).
    let dead_threshold = 15.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that block it while remaining large-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
        // Perfect chain: this item plus next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: opening a fresh bin is only attractive if the
    // current item would leave a very awkward residual in any existing bin.
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 {
            (post_residual > 0 && post_residual < next_item_size.max(15)) || post_residual == 0
        } else {
            post_residual > 0 && post_residual < 15
        };
        if awkward {
            score -= 45.0; // open a new bin rather than create dead space
        } else {
            score += 55.0; // strongly prefer reusing an existing bin
        }
    }

    // Mild deviation from mean residual: prefer bins whose residual is already tight.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Slight preference to fill earlier bins as the stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space (quadratic dead-space pressure)
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fit_ratio; // next item fits, tighter is better
        } else {
            // next item won't fit here; penalize small leftovers that become dead space
            let waste = post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless no decent fit exists
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.2;
        // allow opening a new bin late in the stream when leftovers are large
        if next_item_size > 0 && next_item_size >= item_size && post_residual == 0 {
            score -= 50.0;
        }
    }

    // Progression: as stream advances, prefer tighter packing (reduce openness)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / bin_capacity as f64);

    // Prefer bins with small residual when many bins are open
    if open_bins_count > 3 {
        score += 0.1 * (open_bins_count as f64) * (post_residual as f64) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize scattering across many open bins when plenty fit.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-mean-residual bin consolidates near-full bins.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Time horizon: early in the stream, be conservative (favor new bins for
    // large items to keep flexibility); late, squeeze into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 20.0 * (1.0 - t);
        score += 15.0 * t;
        // Never open a new bin if a perfect fit exists elsewhere is handled by
        // the low score of post_residual == 0 above.
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    } else {
        score -= 10.0 * t;
    }

    // Slight preference for bins with larger residual when item is large.
    if item_size > bin_capacity / 2 {
        score += (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let shape = 1.0 + 0.6 * progress - 0.8 * progress * progress + 0.5 * progress * progress * progress;
    score += 12.0 * norm_pr * shape;

    // Reward tight fits (high fill fraction)
    score -= 18.0 * fit_frac * fit_frac * (0.5 + 0.5 * progress);

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        score += 0.35 * waste * (1.0 + progress);
        if nxt <= pr {
            score -= 10.0; // lookahead fits: reward
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild preference for bins below mean residual (consolidation)
    score += 0.08 * (mean_residual - pr);

    // New-bin candidate: penalize opening new bins unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = avg_open / cap;
        score += 30.0 * (1.0 - pressure) * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 3.0 * cap;
    }

    // Small post_residual classes (harmonic buckets): reward tight fits.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        score -= 2.0 * cap - 20.0 * pr;
    } else if post_residual <= 20 {
        score -= cap - 5.0 * pr;
    }

    // Dead space penalty: residual too small to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0 * cap;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 2.5 * cap;
        } else if next_item_size < post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here: leftover is likely dead space
            score += 0.3 * pr;
        }
        // Harmonic pairing: post_residual + next_item_size close to capacity fractions
        let sum = pr + nxt;
        if (sum - cap * 0.5).abs() < 1.0 || (sum - cap * 0.25).abs() < 1.0 {
            score -= 0.8 * cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 * cap;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let baseline = if fitting_bins_count == 0 { 0.0 } else { 0.6 * cap };
        // Prefer new bin if mean residual is large but fragmented (item barely fits)
        let fragmentation = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs()
        } else {
            0.0
        };
        score += baseline + fragmentation * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 0.4 * cap;
        }
    }

    // Prefer reusing bins over spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Mild stream-progress modulation: tighten packing later in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Dead space that cannot host the lookahead item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few -> encourage filling.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { -50.0 } else { 15.0 };
        score += pressure + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for upcoming large item
        }
    }

    // Mild preference to use bins whose residual is close to item size.
    score -= (mean_residual - item_size as f64).abs().max(0.0).min(50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = (pr - next) as f64;
            // Perfect chain fill: strong reward.
            if gap == 0.0 {
                score -= 30.0;
            } else {
                score -= 15.0 * (1.0 - gap / pr.max(1.0));
            }
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += (next - pr) * 0.15;
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0 * fit_ratio;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average leftover is good (consolidation).
    score -= (mean_residual - post_residual as f64) * 0.10;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins are very full / few fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item is large and current fits are poor, opening fresh is OK.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Mild pressure as stream progresses: prefer consolidating early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (next_item_size as f64);
    }
    // Penalize post-residuals that are small but useless for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mildly discourage spreading into nearly-empty bins,
    // prefer bins with lower residual (denser bins) for consolidation.
    if fitting_bins_count > 1 {
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Early in stream: favor opening fresh bins to build structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let new_bin_bonus = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            -10.0 // pairing potential with lookahead
        } else {
            5.0
        };
        score += new_bin_bonus + 20.0 * (1.0 - progress) * -1.0 + 10.0 * progress;
        // Penalize opening new bins when good fits exist elsewhere.
        if fitting_bins_count > 0 && post_residual == bin_capacity - item_size {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Late in stream: consolidate aggressively; avoid leaving many open bins.
    score += 0.1 * open_bins_count as f64 * progress;

    // Dead-space avoidance: residuals below typical minimum item size are dead.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // as the stream advances, tight fits (small post_residual) become more valuable.
    let norm_post = post / cap;
    let tightness = 1.0 - norm_post;
    score -= 30.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize post_residual that cannot accommodate the lookahead item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 20.0 * gap * gap * (1.0 + progress);
        } else {
            // Reward leaving room exactly for the next item (smooth bonus).
            let fit_q = (post - nxt) / cap;
            score -= 12.0 * (1.0 - fit_q) * (1.0 - fit_q);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation risk),
    // smoothly coupled with mean residual across open bins.
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * norm_post * (mean_residual / cap);

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual on an empty bin equals capacity).
    if bin_residual == bin_capacity {
        let base = cap - item_size as f64;
        let pressure = 1.0 + 2.0 * (1.0 - progress);
        score += 15.0 * pressure + 0.5 * open_f;
        // If item is large, filling a fresh bin is less wasteful later in the stream.
        score -= 10.0 * (item_size as f64 / cap) * progress;
        let _ = base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes are best.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space bounded
    } else if pr < 20 {
        score -= 5.0;
    } else {
        // dead space penalty grows super-linearly beyond the small-item threshold
        score += ((pr as f64) - 20.0) * 0.35;
    }

    // Harmonic class of next_item_size relative to post_residual:
    // reward bins whose residual is a natural complement class for the lookahead item.
    if next_item_size > 0 {
        let n = next_item_size;
        if n == pr {
            score -= 30.0; // exact complement next step
        } else if pr >= n {
            // residual divisible into harmonic sub-classes (n divides pr)
            if pr % n == 0 {
                score -= 12.0;
            }
            score -= ((pr as f64) - (n as f64)).min(20.0) * 0.4;
        } else {
            // next item cannot use this residual at all -> dead space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins below mean residual (tighter bins), mild coupling.
    score -= (mean_residual - (post_residual as f64)) * 0.15;

    // New-bin candidate: penalize opening a bin unless the fit is exceptionally tight
    // or no reasonable alternative exists.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / cap;
        let base = 45.0 - 20.0 * tight; // large items justify new bins more
        let pressure = (open_bins_count as f64).min(20.0) * 0.5;
        score += base + pressure;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin will serve the lookahead item well
        }
    }

    // Slight stream-phase modulation: early on, be more conservative about waste.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.08 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Medium gaps (10..30) get a milder penalty scaled by their unusability.
    else if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 60.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder: penalize dead space more.
        score += (post_residual as f64) * 1.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening new is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 2.0 * progress);
    score += pressure * 0.5;

    // Compare against mean residual: bins with residual far below mean are better used.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it as a viable fallback when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad existing fits are.
        score = 40.0 + open_bins_count as f64 * 1.0 - (mean_residual - item_size as f64).max(0.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (exact or near-exact placement)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * tightness * tightness * tightness;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 8.0 + 6.0 * chain_tight;
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item almost fits (dead space)
        let gap = post_residual as f64;
        if gap > 0.0 && (next_item_size as f64) > gap {
            score += 3.0 * (1.0 - gap / (next_item_size as f64));
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins already below-mean residual are good targets
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score -= 4.0 * (1.0 - rel);
        } else {
            score += 2.0 * (rel - 1.0);
        }
    }

    // New-bin candidate: prefer it only when no open bin is a decent fit
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred
        score += 12.0;
        // If many bins already open, mildly discourage fragmentation
        score += 0.3 * open_bins_count as f64;
        // If the item is large relative to capacity, opening fresh is more attractive
        score -= 6.0 * (item_size as f64) / (bin_capacity as f64);
        // If next item is large too, a fresh bin chains better
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= bin_capacity as f64 {
            score -= 4.0;
        }
    }

    // Mild late-stream conservatism: consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    score -= 40.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(6);

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0
            + 1.5 * open_bins_count as f64
            + 0.05 * mean_residual;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score += 30.0; // new bin leaves big usable residual for future items
        }
    }

    // Lookahead coupling: reward leaving exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balance residuals).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;

    // Base: prefer small post-residual (tight fit), scaled smoothly.
    let mut score = pr;

    // Non-linear tightening: reward very small post_residual more strongly.
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score -= 12.0 * tightness * (0.6 + 0.4 * progress);

    // Penalize dead space: residuals too small to ever fit a future item are wasted.
    let dead = if pr > 0.0 { ((10.0 - pr).max(0.0) / 10.0).powf(2.0) } else { 0.0 };
    score += 8.0 * dead;

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - (gap / cap).min(1.0)).powf(3.0);
    }

    // New-bin candidate: penalize opening a bin, less so late in the stream
    // or when few bins fit the item (last-chance avoidance).
    if is_new_bin {
        let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 18.0 * (1.0 - progress) * (1.0 - last_chance) + 4.0;
        // A fresh bin has residual = cap - item_size; if that's a great fit, soften penalty.
        let fresh_tight = 1.0 - (pr / cap).powf(2.0);
        score -= 10.0 * fresh_tight * (0.5 + 0.5 * progress);
    }

    // Mild preference to fill bins with larger residuals when many bins are open.
    score += 0.02 * (bin_residual as f64 - mean_residual) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fits and tiny residues are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Modulo-10 harmonic classes: residues divisible by 10 are more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Penalize dead-space bands: residues that few item sizes (1..100) can use.
    let usable = (pr as f64).sqrt() * (pr as f64 / cap).ln_1p().max(0.0);
    score -= 5.0 * usable;

    // Coupling with lookahead item: if next item fits post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 15.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        // open new bin when open bins are nearly full on average
        score = 40.0 + 50.0 * (1.0 - pressure) - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity as u32 / 2 {
            score -= 10.0;
        }
    } else {
        // Prefer tighter bins: reward small pre-residual usage ratio.
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 12.0 * fill * fill;
    }

    // Mild preference to spread across fewer bins when many are open.
    score += 0.15 * open_bins_count as f64 * (pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }
    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward gaps that can still host a typical small item.
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, strong bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 25.0; // next item would create a sliver here
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless the fit is perfect.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 8.0 * (1.0 - progress);

    // New-bin candidate: acceptable only when the fit into open bins is poor.
    if bin_residual == bin_capacity {
        let tight_fit = (bin_residual - item_size) as f64;
        // Opening a new bin costs a fixed premium, softened by mean residual waste.
        score = 45.0 + tight_fit * 0.3 - mean_residual * 0.2;
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to what we leave behind (compactness).
    score += ((bin_residual as f64) - (item_size as f64) - (post_residual as f64)).abs() * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            score -= 60.0 * (1.0 - slack_after_next / bin_capacity as f64);
            if slack_after_next == 0.0 {
                score -= 200.0;
            }
        } else {
            // Next item won't fit here; penalize leaving residual that's likely dead space.
            let gap = nxt - post;
            score += 0.5 * gap.min(40.0) as f64;
        }
