    score += 0.3 * (mean_residual - post_residual as f64).max(-50.0).min(50.0);

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 40.0; // an existing bin likely serves the next item too; avoid opening
        }
    }

    // Slight preference to spread load early when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
