        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // If next item exactly matches post_residual, big reward
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Global pressure: many open bins with slack -> prefer consolidating into low-residual bins
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in stream, be choosy (penalize mediocre fits); later, fill greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: make it less attractive unless item is very large and nothing fits well
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size as f64 > 0.7 * cap {
            score -= 22.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild penalty for proliferating bins when residual slack is high
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) emphasis
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr) + 12.0 * norm_pr * norm_pr * norm_pr;

    // Lookahead coupling: reward if next item fits in post_residual (smooth sigmoid-like gate)
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let tightness = 1.0 - (next_item_size as f64 / cap).min(1.0);
        score -= 18.0 * fits * tightness * (1.0 + 0.5 * progress);
        // Penalize post_residual that is close to but below next item (dead space)
        let gap = pr - next_item_size as f64;
        if gap < 0.0 && pr > 0.0 {
            score += 6.0 * (1.0 - (gap.abs() / cap)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Stream-progress coupling: as stream advances, favor tighter packing (larger weight on pr)
    score *= 1.0 + 0.6 * progress * progress;

    // Mean-residual interaction: if this bin's residual is far below mean, it's a good fit target
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * (1.0 - dev * dev).max(0.0);

    // New-bin candidate handling: only open a new bin if all open bins are poor fits
    let is_new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let avg_bad = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
    let openness = (avg_bad - norm_pr).max(0.0);
    score += is_new_bin * (10.0 + 20.0 * (1.0 - openness)) * (0.6 + 0.4 * progress);
    // Encourage opening fresh bins early when few bins are open
    score -= is_new_bin * 3.0 * (1.0 - progress) / (1.0 + open_bins_count as f64);

    // Mild penalty for many open bins (fragmentation control)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual bucketed by capacity fractions
    let pr = post_residual as f64;
    let class = (pr * 8.0 / cap).floor(); // 0..8 harmonic classes of residual
    // Penalize small unusable leftovers (classes 1..3 => residual < 37.5)
    if class >= 1.0 && class <= 2.0 {
        score += 18.0;
    } else if class == 3.0 {
        score += 6.0;
    } else if class == 0.0 {
        score -= 25.0; // perfect/near-perfect fit
    } else if class >= 5.0 {
        score -= 8.0; // big leftover stays reusable
    }

    // Integer-division threshold: can next item fit in post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // reward chains: exact division bonus when next item divides residual nicely
            let div = (pr / nxt).floor();
            score -= 10.0 + 5.0 * div.min(3.0);
        } else {
            // dead space equal to residual if next item can't use it
            score += 0.15 * pr;
        }
    } else {
        // last item: prefer tightest fit, weight less
        score *= 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current bins are crowded or residual tiny
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score = 55.0 - 5.0 * crowding.min(6.0);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open new bin anyway
        }
    }

    // Late-stream consolidation: favor filling existing bins harder as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * progress;

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap - 0.5).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized
    // unless the gap is exactly zero (perfect fit).
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strong reward
    } else if post_residual <= 10 {
        score += 45.0; // dead space: nearly unusable gap
    } else if post_residual <= 25 {
        score += 12.0; // marginal gap
    }

    // Reward bins whose post_residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 6.0; // lookahead won't fit here: slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing bins
    // over spreading; a new empty bin candidate gets a baseline penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * 4.0 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Prefer bins with residual below the mean (tighter bins get filled first).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(40.0) * 0.25;
    }

    // Mild preference for high fill ratio of the current placement.
    score -= (item_size as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: residual consumed by next item
        } else if post_residual >= next_item_size {
            // next item fits, but leaves more waste: mild penalty proportional to leftover
            let leftover = (post_residual - next_item_size) as f64;
            score -= 30.0 - leftover * 0.5;
        } else {
            // next item cannot fit here: penalize wasted residual, worse when small
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + gap * 0.3;
        }
    } else {
        // Last item: only current fit matters; small residual is fine.
        score -= 10.0;
    }

    // Coupling with mean residual across open bins: placing into a bin whose
    // residual deviates strongly from the mean is either great (close it out) or bad.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        // Below-average residual bin: filling it reduces bin count pressure.
        score -= dev.abs() * 0.4;
    } else {
        // Above-average residual bin: consuming from it wastes potential space.
        score += dev * 0.15;
    }

    // Last-chance bin: strongly reward using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the tightest, discourage hoarding space in others.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (post_residual would be large waste elsewhere).
    if bin_residual == bin_capacity {
        // Cost of a fresh bin: penalize, but discount when many items remain
        // (future flexibility worth more early in the stream).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + progress * 30.0 + open_bins_count as f64 * 2.0;
        // If next item is huge and would only fit an empty bin, favor opening it.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Mild stream-position modulation: early on, keep bins open (flexibility);
    // late, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever fit a future item
    // (items are >= 1, but small slivers are still waste; use next item as probe).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Lookahead: if the next item also fits here, this bin is extra valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin's post-fit residual is very poor (near-full or tiny).
    if bin_residual == bin_capacity {
        // Cost of a fresh bin, discounted slightly late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 30.0 - 8.0 * progress;

        // If the item fits almost perfectly in an empty bin, new bin is great.
        if item_size >= 80 {
            score -= 20.0;
        }
        // If many open bins already fit the item, discourage opening another.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // If mean residual across open bins is large, better to use those.
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0;
        }
    }

    // Mild preference for bins with residual close to mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for using more-opened bins early (keep bin count low).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += 12.0 * coupling * pr_norm * pr_norm;

    // Penalize large post_residual more aggressively as stream progresses
    score += 20.0 * progress * pr_norm;

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 15.0 * (-pr / 25.0).exp();

    // Reward bins that can also fit the next item (lookahead pairing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * coupling;
    } else if next_item_size > 0 {
        // Smooth penalty when next item won't fit
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 4.0 * (1.0 - (-gap / 30.0).exp());
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * progress);

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize slightly unless residuals of open bins are poor
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * mean_residual / bin_capacity as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes get strong rewards.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 5 {
        score -= 300.0;
    } else if pr <= 12 {
        score -= 120.0;
    } else {
        // Dead-space penalty grows superlinearly for large residuals, but
        // modulate by whether a residual is "harmonically reusable":
        // residuals that are multiples of common item sizes (10, 20, 25, 50)
        // are more likely to be filled later.
        let reusable = pr % 10 == 0 || pr % 25 == 0 || pr % 20 == 0;
        let dead = (pr as f64).powi(2) / bin_capacity as f64;
        if reusable {
            score -= dead * 0.5;
        } else {
            score += dead * 0.6;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 800.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            score -= 200.0 - (leftover as f64) * 2.0;
            // Harmonic class of leftover after lookahead
            if leftover % 10 == 0 {
                score -= 80.0;
            }
        } else {
            // Next item cannot use this bin's remainder: slight penalty,
            // worse when remainder is awkwardly small.
            if pr < 10 {
                score += 150.0;
            }
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only
    // attractive when the current item would leave a bad, non-reusable
    // remainder in every existing bin.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, scaled by how crowded the fleet is.
        score = 60.0 + 10.0 * (open_bins_count as f64).sqrt();
        // If this item leaves a harmonically nice residual in the new bin,
        // make the new bin slightly more attractive.
        let nr = bin_capacity - item_size;
        if nr % 10 == 0 || nr % 25 == 0 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * progress;
        }
    }

    // Prefer tighter bins when many bins can fit the item: best-fit bias.
    if fitting_bins_count > 1 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 50.0 * tightness;
    }

    // Mild coupling with mean residual: bins far below mean residual are
    // "wasted" capacity; prefer bins near or below mean.
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (size 1..~12) are effectively dead space. Penalize the "unusable zone"
    // super-linearly so tight fits are strongly preferred.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Penalize leaving a gap that the lookahead item cannot use but another
    // placement could have: wasted opportunity.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 4.0;
    }
    // Reward gaps that exactly accommodate the lookahead item (chain fits).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into more of
    // them; consolidate unless the fit is tight.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.5;
    score += pressure * (1.0 - fill_ratio);

    // Prefer bins whose residual is close to the item (best-fit shaping).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // New-bin candidate: empty bin gets a moderate default score; only win when
    // no open bin offers a decent fit. Scale with stream progression so late in
    // the stream we slightly prefer closing out open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9 + progress * 10.0 + open_bins_count as f64 * 0.5;
        // Allow opening a new bin when the item barely fits nothing well.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good.
    score -= (post_residual as f64).powi(2) / cap;

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            let gap = pr - nx;
            // Perfect chain fit reward
            score -= 12.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large unusable residue
            let waste = pr.min(nx - 1.0);
            score += 0.35 * waste;
        }
    }

    // Relative to mean residual: prefer filling bins that are tighter than average
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // or when this bin's fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (post_residual as f64) > 40.0 && next_item_size > 0 && (next_item_size as f64) > post_residual as f64;
        if bad_fit {
            score -= 6.0; // allow opening a fresh bin on a poor fit
        } else {
            score += 10.0 + 8.0 * progress; // discourage proliferation, esp. late
        }
        if open_bins_count > 12 {
            score += 2.0 * (open_bins_count as f64 - 12.0).min(10.0);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: tiny post-residual is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; leftover is dead space unless small.
            if post_residual < 10 {
                score -= 5.0; // small leftover acceptable
            } else {
                score += 3.0; // large leftover likely wasted
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins have plenty of room and few bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a bin.
        score += 40.0;
        if open_bins_count <= 2 {
            score += 15.0;
        }
        if mean_residual > (item_size as f64) * 1.5 {
            score += 10.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit) via deviation term.
        let dev = (bin_residual as f64 - item_size as f64).abs();
        score += dev * 0.15;

        // Prefer bins with residual below mean (consolidate emptier space elsewhere).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual.min(20) as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: quadratic waste penalty (dead space hurts super-linearly).
    let mut score = 1.0 + (pr / cap) * (1.0 + 2.5 * pr / cap) * 100.0;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - pr / cap;
    score -= 60.0 * tightness * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly,
    // penalize residuals that leave the next item stranded.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = pr - nx;
            if gap == 0.0 {
                score -= 120.0; // perfect pairing
            } else {
                score -= 40.0 * (1.0 - gap / cap);
            }
        } else {
            score += 30.0 * (nx - pr) / cap; // next item won't fit here
        }
    }

    // Smooth non-linear coupling with stream progress: early on, prefer
    // spreading (keep residuals flexible); late, prefer tight packing.
    let spread_bias = (1.0 - progress) * (1.0 - progress);
    score += 25.0 * spread_bias * (pr / cap);
    score -= 20.0 * progress * progress * (pr / cap);

    // Penalize bins whose residual deviates far from mean (fragmentation).
    score += 8.0 * ((pr - mean_residual) / cap).abs();

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are
    // nearly full or very fragmented; scale with number of open bins.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() / (1.0 + cap / 10.0);
        let mean_fullness = 1.0 - mean_residual / cap;
        score += 45.0 + 10.0 * crowding - 60.0 * mean_fullness * mean_fullness;
        // Late in stream, opening fresh bins is more acceptable.
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill / small-dead-space classes rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit
    } else {
        // Class by integer division thresholds on post_residual.
        let class = pr / 10; // 0..=10 harmonic class
        score -= (10 - class as i32) as f64 * 8.0;

        // Modulo coupling: residuals divisible by common item sizes are reusable.
        for m in [5u32, 10, 20, 25, 50] {
            if pr % m == 0 && pr > 0 {
                score -= 15.0;
                break;
            }
        }
        // Dead-space penalty grows super-linearly for tiny unusable residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * 20.0;
        }
    }

    // Coupling with next item: reward residuals that exactly or nearly fit the lookahead.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= (40.0 - slack.min(40) as f64) * 0.8;
        } else {
            // Lookahead won't fit here; penalize mildly.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = 60.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: open new bin
        } else if (post_residual as f64) < mean_residual * 0.5 {
            score += 30.0; // poor fit among existing bins -> opening is fine
        }
    }

    // Slight preference to fill older/crowded states as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to host
    // even the smallest future item (1..=3) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 4 {
        score += 40.0;
    }
    // Residuals below 10 can host nothing from the classic 10..80 regime;
    // treat as near-dead space with a graded penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10.0 - post) / 10.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Reward fits that still allow the lookahead item to land here later.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0;
            if post_residual as f64 - nxt <= 3.0 {
                score -= 6.0; // leaves a nearly-consumed residual again
            }
        } else if nxt > post {
            // lookahead cannot use this residual: mild penalty scaled by gap
            let gap = nxt - post;
            if gap <= 10.0 {
                score += 0.6 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // are open; makes the fresh-bin candidate less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize so it only wins when the fit is truly bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If no open bin fits well, the penalty is what the fresh bin must overcome;
        // keep it high but not insurmountable for large items.
        score -= 0.1 * item_size as f64;
    }

    // Slight pull toward bins whose residual is close to the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (dead-space penalty curve).
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 14.0 * tight * tight;

    // Aggressive 2-step lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 10.0 * (1.0 - slack);
            if post_residual as u32 == next_item_size {
                score -= 8.0; // perfect chaining: this bin + next item = full bin
            }
        } else {
            // Cannot host next item: penalize proportionally to the miss.
            let miss = (nxt - post_residual as f64) / cap;
            score += 6.0 * miss;
        }
    } else {
        // Last item: strongly prefer filling a bin as much as possible.
        score -= 20.0 * tight;
    }

    // Relative-to-mean anchoring: prefer bins whose post-residual beats the mean.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or no open bin looks promising; otherwise penalize spreading.
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / cap;
        score += 4.0 - 6.0 * ratio;
        if next_item_size > 0 && (item_size as u32).saturating_add(next_item_size) <= bin_capacity {
            score -= 3.0; // fresh bin can host a perfect pair
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 2.0; // mild bias to reuse existing bins
        }
    }

    // Early-stream: be slightly more willing to open bins for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 1.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed — a soft time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (low post_residual) with a nonlinear squash.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if the next item can still fit in the post-residual,
    // this bin is extra valuable (chaining placements). If not, post-residual
    // is likely dead space — penalize it more.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - progress);
        } else {
            // Dead-space penalty scaled by how badly the next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss.min(60.0);
        }
        // Perfect chain: post_residual exactly equals next item.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        // Extra reward if the fit is decent.
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // Many fitting bins: competition exists, mildly prefer the tightest.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: when mean residual across open bins is high, bins are
    // fragmented — prefer consolidating into existing bins rather than
    // opening new ones.
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: opening a new bin is expensive early and when the
    // item fits poorly in existing bins. Penalize moderately by default;
    // relieve the penalty when this is a large item late in the stream or
    // when no other bin fits well.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 25.0;
        // Large items late in stream: fresh bins are useful.
        if item_size > 60 {
            new_bin_penalty -= 8.0;
        }
        if progress > 0.7 {
            new_bin_penalty -= 5.0;
        }
        // If no open bin fits at all, opening is forced — soften penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 20.0;
        }
        // Lookahead: a fresh bin can host the next item after this one.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            new_bin_penalty -= 5.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild entropy term: tiny dynamic tie-breaker coupling step and bin count
    // to break ties deterministically across the stream without randomness.
    score += 0.001 * ((step_index % 7) as f64) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let p = progress;
    // Quadratic + cubic interaction terms: waste matters more as stream advances.
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * p) + pr_norm * pr_norm * pr_norm * (1.0 + 3.0 * p * p);
    score += 10.0 * coupling;

    // Lookahead: reward residuals that can host the next item, smoothly scaled.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post_residual as f64 - nxt).max(0.0);
        let next_fit_quality = fits_next / cap;
        // Smooth reward decaying with progress (future packing less certain).
        score -= 6.0 * next_fit_quality * (1.0 - 0.5 * p);
        // Penalize residuals that are just barely too small for the next item.
        let miss = (nxt - post_residual as f64).max(0.0) / cap;
        score += 4.0 * miss * miss * cap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * p;
    }

    // Tight fit reward: smooth function of how fully the item fills the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill;

    // Prefer bins below mean residual slightly (balance residuals smoothly).
    score += 0.05 * (post_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly so it only wins when fits are bad,
    // with the penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - 0.4 * p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Dead-space penalty: post_residual too small to ever be useful
    // (below the minimum plausible item size of 1..=100 stream, treat
    // "waste" as post_residual that cannot fit a meaningful chunk).
    let waste = post_residual as f64 / bin_capacity as f64;
    if waste > 0.0 && waste < 0.10 {
        score += 40.0; // tiny unusable sliver
    } else if waste >= 0.10 && waste < 0.25 {
        score += 8.0; // marginal leftover
    }

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    // Residuals in the "half bin" class (40..60) are highly reusable.
    let pr = post_residual;
    let class = pr / 20; // integer division buckets: 0..=5
    match class {
        2 => score -= 25.0,           // 40..59: golden residual zone
        3 => score -= 15.0,           // 60..79: good reusable zone
        1 => score -= 5.0,            // 20..39: okay
        0 => { if pr > 0 { score += 30.0; } }, // 1..19: near-dead
        _ => {}                        // 80..100: fresh bin class
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Perfect chaining: next item exactly fills what we leave.
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 - slack * 0.5;
        } else {
            // Next item cannot use our leftover: mild penalty scaled by gap.
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.20;
        }
        // Exact-fill lookahead bonus (harmonic pairing).
        if next_item_size == pr {
            score -= 50.0;
        }
    } else {
        // Last item: minimize leftover waste only.
        score += waste * 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: neutral-ish, but prefer it when current
    // open bins are fragmented (high mean residual spread) or many bins open.
    if bin_residual == bin_capacity {
        // Fresh bin: score is post_residual = capacity minus tight-fit bonus.
        // Penalize opening new bins when the item fits an existing bin well.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 - open_bins_count as f64 * 0.5 + fragmentation * 0.3;
        // If nothing fits anywhere except this call, it wins naturally.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: late in the stream, consolidation matters more;
    // penalize spreading across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Fill-ratio reward: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // future item (min item size 1, but realistically small gaps) are wasted.
    // Penalize a "dead zone" super-linearly once post_residual drops below a
    // usable threshold, but reward near-perfect fits (post_residual == 0).
    let dead_threshold = 10.0f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if (post_residual as f64) < dead_threshold {
        // Unusable sliver: heavy penalty on top of the small base value.
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else {
        // Usable leftover: mild reward for keeping gaps large enough to matter,
        // scaled by how much of the bin remains usable.
        score -= (post_residual as f64 / bin_capacity as f64) * 4.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance pressure: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; opening yet another bin is penalized implicitly by
    // raising the score of the new-bin candidate (empty bin) when open_bins_count
    // is low relative to stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by how many
        // bins are already open and how spread out the residuals are.
        let mut new_bin_cost = 30.0;
        new_bin_cost += open_bins_count as f64 * 3.0;
        // If mean residual is large, existing bins likely have room: discourage new bin.
        new_bin_cost += mean_residual * 0.3;
        // Early in the stream, opening bins is cheaper (build flexibility);
        // late in the stream, consolidate.
        new_bin_cost *= 0.5 + progress;
        // If no bin actually fits (fitting_bins_count counts only open bins that
        // fit; the empty bin always "fits"), the empty bin here is the fallback.
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        }
        // If the next item could use the leftover of this placement, mild bonus.
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            new_bin_cost -= 5.0;
        }
        score = new_bin_cost;
    } else {
        // Existing bin: lookahead coupling — if the next item fits exactly in
        // the post residual, reward this placement.
        if next_item_size > 0 {
            if (next_item_size as u32) == post_residual {
                score -= 15.0;
            } else if next_item_size as f64 <= post_residual as f64 {
                score -= 5.0;
            } else {
                // Next item cannot use the leftover: penalize proportionally to dead space risk.
                score += (post_residual as f64) * 0.2;
            }
        }
        // Mild consolidation bonus when many bins are open.
        score -= open_bins_count as f64 * 0.5;
        // Prefer bins whose residual is close to the item (best-fit flavor),
        // penalizing waste relative to the mean residual.
        score += (mean_residual - bin_residual as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect two-item pairing bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If next item cannot fit after placement, penalize dead space
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.15 * post_residual as f64;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates favorably
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Tight fit reward: small post residual is good
    score += 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        score += 20.0 + 10.0 * pressure;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score += 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 12.0 + 0.4 * (nxt - post_residual as f64);
        } else {
            // reward leaving room exactly for the next item
            let gap = (post_residual as f64 - nxt).abs();
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless open bins are congested
    if bin_residual == bin_capacity {
        let congestion = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            0.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 25.0 * congestion - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Mild penalty for proliferating bins with large mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64;
    score += 0.02 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: quadratic in post_residual (dead-space penalty grows super-linearly)
    let mut score = pr * pr / cap;

    // Smooth coupling of post_residual with stream progress:
    // early on, tolerate large residuals (bins may fill later);
    // late, strongly penalize leftover space.
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * pr;

    // Cubic interaction: residual^3 normalized, modulated by progress
    score += (pr / cap).powi(3) * cap * (0.2 + 0.8 * progress);

    // Fit tightness: reward placements that nearly fill the bin
    let tightness = 1.0 - pr / cap;
    score -= 4.0 * tightness * tightness * it;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 6.0 * it;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 3.0 * (1.0 - gap / cap) * nx / cap * 10.0;
        // penalize if post_residual is too small for the next item (dead space)
        if pr < nx {
            score += 2.0 * progress * (nx - pr);
        }
    }

    // New-bin candidate: penalize mildly when other bins exist and mean residual is high;
    // reward opening a new bin late in the stream or when current bins are fragmented.
    if is_new_bin {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let spread = (mean_residual - pr).abs() / cap;
        let penalty = if open_bins_count == 0 {
            -20.0
        } else {
            3.0 + 8.0 * (1.0 - fragmentation) + 4.0 * progress
        };
        score += penalty - 2.0 * spread * spread * cap;
    } else {
        // Reward using existing bins whose residual is below average (consolidation)
        let diff = mean_residual - bin_residual as f64;
        score += 0.5 * diff;
    }

    // Mild diversity pressure on open bin count
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands (dead-space classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: unusable sliver (< 10) -> heavy penalty (dead space).
    if post_residual < 10 {
        score += 40.0;
    }
    // Class 1: tiny leftover 10..=20 -> moderate penalty unless it can host the next item.
    else if post_residual <= 20 {
        score += 12.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }
    // Class 2: quarter-band 21..=25 -> mild penalty, reward if next item fits exactly-ish.
    else if post_residual <= 25 {
        score += 4.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }
    // Class 3: half-band 26..=50 -> neutral/slightly good.
    else if post_residual <= 50 {
        score -= 3.0;
    }
    // Class 4: large leftover > 50 -> reward keeping big space.
    else {
        score -= 8.0;
    }

    // Integer-division harmonic classes: post_residual mod 10 granularity.
    // Leftovers that are multiples of 10 pair well with common item sizes.
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 2.0;
    } else if rem10 >= 7 {
        score += 3.0; // awkward sliver of 7..9 units
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: strongly reward bins whose post_residual exactly
    // accommodates the next item (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // reward proportional to how snugly the next item fits afterwards
            let after_next = post_residual - next_item_size as f64;
            if after_next < 10.0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; penalize less if this bin is near-closed anyway
            score += 3.0;
        }
    } else {
        // Last item of the stream: prefer tightest closure.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, discourage wasting it
    // on a bad fit; encourage using it when fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 20 && post_residual > 0 {
            score += 15.0; // poor fit in the only option -> consider new bin
        } else {
            score -= 5.0; // decent fit -> use the last-chance bin
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Opening a new bin is more attractive when few bins are open
        // (amortize overhead) or late in the stream is irrelevant; slightly
        // cheaper when many open bins have small mean residual (fragmentation).
        if mean_residual < cap * 0.25 && open_bins_count > 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 5.0; // reserve fresh space for a big upcoming item
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 && post_residual < 15 {
        score += 8.0;
    }

    // Mild tie-breaker toward tighter fits overall.
    score += (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // A residual is "unusable" if it is smaller than the smallest plausible item.
        // Weight it super-linearly as it approaches zero.
        let dead = (10.0f64 - post_residual as f64).max(0.0);
        score += 3.0 * dead * dead / 10.0;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward leaving room for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual wasted relative to lookahead need.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage new bins and
    // favor consolidating into existing ones (tighter residual wins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual deviates downward from the mean (tighter bins).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += (post_residual as f64) * (post_residual as f64) * 0.02;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to leftover
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * ratio;
        } else {
            // next item can't use this leftover: penalize dead space
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless it's genuinely needed (item barely fits
    // nowhere well): new-bin candidate gets mild penalty, relaxed when crowded.
    if bin_residual == bin_capacity {
        score += 30.0 - 2.0 * (open_bins_count as f64);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed — late items favor tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward small post-residual (tight fit), amplified late in the stream.
    score -= (bin_capacity as f64 - post_residual as f64) * (0.15 + 0.35 * progress);

    // Penalize dead space: post-residual too small for typical future items.
    if post_residual < 10 {
        score += 6.0 * (1.0 - progress);
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 3.0; // residual can't host the lookahead item
    } else if next_item_size > 0 {
        // Reward residual that can host the next item (chaining potential).
        score -= 2.5 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
    }

    // Last-chance bonus: only fitting bin — strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Many fitting bins: competition, mild penalty to spread load.
        score += 0.8 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Coupling with global mean residual: prefer bins below mean residual
    // (keep big holes for big future items), more so early on.
    let diff = mean_residual - bin_residual as f64;
    score += 0.25 * diff.max(0.0) * (1.2 - progress);

    // Many open bins: discourage spreading, favor consolidation.
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to residuals) or stream is early.
    if bin_residual == bin_capacity {
        let tight = fitting_bins_count == 0 || (item_size as f64) > mean_residual;
        if tight || progress < 0.25 {
            score -= 10.0 + 5.0 * (1.0 - progress);
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (low post_residual); later,
    // allow slightly larger residuals since future items are fewer.
    let progress_warp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += pr * (1.0 - progress_warp) * 0.35;
    score -= pr * progress_warp * 0.15;

    // Non-linear penalty for very small residuals (dead space), scaled by progress
    let dead = (1.0 - pr / cap).powi(6);
    score += dead * cap * (0.15 + 0.25 * (1.0 - progress));

    // Reward exact-ish fits: post_residual near 0 strongly favored
    score -= (1.0 - pr / cap).powi(3) * 20.0;

    // Lookahead coupling: if next item fits into resulting residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit; penalize proportionally to wasted potential
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: only one bin fits the item; avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild regularization toward mean residual to spread load smoothly
    score += 0.05 * (pr - mean_residual);

    // Slight preference for consolidating into fewer bins as stream ends
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into "nice"
    // residue classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fit is always excellent
    } else if pr <= 10 {
        6.0 // tiny dead space, nearly unusable
    } else if pr % 10 == 0 {
        -12.0 // decadal leftover: highly reusable
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        0.0
    } else {
        5.0 // odd leftovers couple poorly with even item sizes
    };
    score += harmonic_bonus;

    // Integer-division threshold: leftover of 20..50 is the "sweet spot" band.
    let band = pr / 20; // 0..=5
    score -= match band {
        1 => 8.0,             // 20..39
        2 => 10.0,            // 40..59
        3 => 6.0,             // 60..79
        _ => 0.0,
    };

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        score -= 10.0;
        if slack % 10 == 0 { score -= 4.0; }
        if slack == 0 { score -= 12.0; } // leaves exact room for next item
    } else if next_item_size > 0 {
        // cannot host next item: penalize proportionally to how close it was
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large relative to capacity or residuals are tight everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 1.2;
        if item_size >= 50 || (tight && fitting_bins_count <= 1) {
            score = 5.0 + progress * 5.0; // competitive low score
        } else {
            score = (bin_capacity as f64) * 1.5; // keep using open bins
        }
        return score;
    }

    // Mild penalty for fragmenting a very full bin when other options exist.
    if pr > 0 && pr < 10 && fitting_bins_count > 1 {
        score += 4.0;
    }

    // Slight preference for bins deviating below the mean residual (tighter fit).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the minimum item size are wasted forever.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize residuals that the lookahead item cannot use (dead space relative to next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 4.0;
    }
    // Reward bins whose post-residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has residual == capacity, so add a penalty there
    // that grows with the number of open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 3.0;
        // But if no existing bin fits well, opening a new bin is fine (handled by
        // the last-chance penalty being absent for new bins).
    }

    // Mild penalty for leaving large-ish gaps that are still hard to fill:
    // prefer residuals near multiples of common item sizes.
    let gap = post_residual as f64;
    score += 0.05 * (gap - (gap / 20.0).round() * 20.0).abs();

    // Slight progression term: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item fill
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space more
            score += 10.0;
        }
    }

    // Reward tight fits relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: penalize opening a new bin unless item is large
    // or no good fit exists (encoded via fitting_bins_count == 1 and mean residual low).
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 60 {
            score -= 30.0; // large items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // pair large items together in a fresh bin
        }
    }

    // Early in stream, slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // This placement blocks the next item from this bin; mild penalty.
            score += 6.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let waste_here = bin_residual - item_size;
        let poor_fit = waste_here as f64 > 0.5 * bin_capacity as f64;
        if poor_fit {
            score -= 8.0; // opening a fresh bin may be fine
        } else {
            score += 35.0; // prefer existing bins for decent fits
        }
    }

    // Time horizon: early in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins.
    if mean_residual > 0.0 {
        let relative_fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score -= 8.0 * relative_fullness * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * 0.5;
    score += poly * cap * 0.3;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 10.0;

    // Penalize near-mean residuals (wasted space relative to average).
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (ni / cap) * (1.0 + progress);
        } else {
            score += 6.0 * (1.0 - ni / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue modulo capacity quarters.
    // Leftovers in small classes are "dead space" -> penalize.
    let q = bin_capacity / 4; // 25
    let class = post_residual % q;
    if post_residual > 0 {
        // Dead-space penalty grows for tiny unusable leftovers
        if class < 10 {
            score += 18.0 - 1.5 * class as f64;
        } else if class < q / 2 {
            score += 3.0;
        } else {
            // Large classes are reusable -> reward
            score -= 6.0;
        }
    } else {
        // Perfect fit: big reward
        score -= 40.0;
    }

    // Integer-division threshold on post_residual vs next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bin can host the lookahead item: reward proportional to fit tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.1 * slack;
        } else {
            // Lookahead won't fit here: penalize proportionally to the miss
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
        // Harmonic pairing: item + next summing near capacity is ideal
        let pair = item_size + next_item_size;
        if pair <= bin_capacity {
            let pair_class = (bin_capacity - pair) % q;
            if pair_class == 0 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 15.0 + 8.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0)) - crowded.min(20.0);
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild preference for tighter bins overall
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit any plausible item are wasted.
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual < dead_threshold {
        score += 500.0 * (dead_threshold - post_residual) as f64;
    }
    // Penalize residuals that cannot fit the lookahead item when the lookahead
    // could otherwise have shared this bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0 + 0.5 * next_item_size as f64;
    }
    // Reward perfect or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it attractive only when the item fits badly elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * item_size as f64 - 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Mild preference for tighter bins (small residual before placement).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into
    // the post residual (chained perfect fit), penalize when it barely
    // misses leaving dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-slack / 20.0).exp();
        } else {
            // Next item cannot use this bin's leftover: dead space risk.
            let dead = (next_item_size - post_residual) as f64;
            score += 8.0 * (dead / 30.0).min(2.0);
        }
    }

    // Relative to mean residual: prefer bins that absorb more than average
    // waste, keep tighter-than-average bins for future large items.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large (hard to place
    // later) or no good existing fit exists; penalize opening bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let mut new_bin_score = 25.0;
        if large_item {
            new_bin_score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 10.0; // pairing large items into fresh bin is fine
        }
        new_bin_score += 10.0 * progress; // opening bins later is cheaper
        score += new_bin_score;
    }

    // Mild penalty for leaving awkward mid-range residuals (hard to fill).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 6.0 * (10.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize dead space that is too small for any plausible future item
    // (items >= 1, but typical items are sizable): waste if post_residual is
    // small but nonzero relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, mildly prefer tighter bins (already via post_residual).
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // current bin would leave a large awkward residual AND the next item could
    // use the fresh capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slight early preference for opening bins (spread items), later prefer filling.
        score += 5.0 + 20.0 * (1.0 - progress);
        // If next item fits into the residual left after placing this item here,
        // discourage opening a new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
        // If many open bins already, discourage spreading further.
        score += 3.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // If the next item would be stranded by this placement (post_residual
        // positive but smaller than next item), penalize.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
        // Reward bins whose residual is below mean (already tight bins absorb items).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if next item exactly fills post_residual, big reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 40.0;
    }

    // Time-horizon modulation: early in stream, be slightly greedy toward
    // compacting; late in stream, prioritize minimizing open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference toward bins with larger current residual when item is large
    // (avoid fragmenting big items into nearly-full bins is already handled, but
    // add safety margin against infeasible-looking fits).
    if item_size as f64 > 0.8 * bin_residual as f64 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fits (low post_residual); late, waste matters less.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Smooth penalty on very small post residuals (dead space) that grows with progress.
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Reward near-perfect fits more strongly as stream progresses.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item cannot use this residual anyway: slight penalty coupling
        score += 3.0 * progress * norm_pr;
    } else if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        score += 2.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward, smoothly modulated by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * progress);
    }

    // Coupling with mean residual: prefer bins below mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + 0.5 * progress) + 2.0 * dev * (1.0 - progress);

    // Mild penalty for spreading across many open bins early on.
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress) * norm_pr;

    // New-bin candidate: make it attractive only when the fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - item_size as f64 / cap) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are gold: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class of post_residual: residues near capacity fractions matter.
    // Dead space that can never be filled by typical items (1..=100) is penalized
    // via modular arithmetic on post_residual.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // tiny slivers are near-useless
        score += 30.0;
    }
    // Modulo classes: post_residual divisible by common item sizes (10,20,25,50)
    // is more likely fillable by future items -> reward.
    if pr >= 10 {
        let mut fillable_bonus = 0.0;
        if pr % 10 == 0 { fillable_bonus += 25.0; }
        if pr % 20 == 0 { fillable_bonus += 10.0; }
        if pr % 25 == 0 { fillable_bonus += 10.0; }
        if pr % 50 == 0 { fillable_bonus += 15.0; }
        score -= fillable_bonus;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 120.0;
            } else if gap <= 15 {
                score -= 40.0;
            }
            // next item leaves another harmonically nice residual
            let pr2 = gap;
            if pr2 % 10 == 0 { score -= 15.0; }
        } else {
            // next item cannot use this bin's leftover at all
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current placement would create large, awkward dead space.
    if bin_residual == bin_capacity {
        // base new-bin score: its residual is capacity (already high),
        // add penalty so it is only chosen for very poor fits elsewhere,
        // relaxed when many bins are open (consolidation pressure low).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 90.0 + 60.0 * (1.0 - progress);
        score += penalty;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 25.0; // fresh bin can host next item nicely
        }
    }

    // Prefer filling bins whose residual is far below the mean (consolidate).
    let diff = mean_residual - bin_residual as f64;
    score -= 0.5 * diff;

    // Slight preference for bins with less absolute residual as stream grows.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual < 10 cannot hold any item)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Dead-space ratio penalty relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 - step_index as f64 / total_items.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post-residual exactly matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            // next item fits here: reward tight chains
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 25.0; // perfect 2-chain
            }
        } else {
            // dead space the next item can't use: penalize proportionally
            score += 0.5 * diff;
        }
    }

    // Prefer bins tighter than the mean residual (well-packed bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // = capacity - item
        score += 20.0 + 0.6 * waste;
        // allow new bin only if item is large relative to capacity
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Slight preference for filling bins earlier in the stream (fewer open bins)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero
    // in a non-linear way (small dead space is worse than near-empty or exact fit).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr);
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin; otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // Prefer bins with below-average residual (consolidate fullness),
    // scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    // Prefer fuller bins overall as the stream progresses.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    // Mild penalty for proliferating open bins when item fits poorly.
    if open_bins_count > 0 && post_residual > 40 {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Penalize new bins mildly; last-chance logic and tight fits in open
        // bins will outcompete this. Reduce penalty late in stream.
        score += 12.0 - 4.0 * progress;
        // If the item is large relative to capacity, opening fresh may be fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, quadratically for small residuals (dead space)
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic dead-space penalty grows as residual shrinks
    score -= 40.0 * (1.0 - x) * (1.0 - x) * x; // peaks mid-range, favors tight fits
    score += 12.0 * x * x * progress;          // late stream: larger residuals are worse to leave

    // Exact fit reward (smooth via small-residual term)
    score -= 30.0 * (-(pr as f64) / 8.0).exp();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    }

    // Prefer filling bins when many are open (avoid bin proliferation)
    score += 0.5 * open_bins_count as f64 * x;

    // Pull toward mean residual: prefer balanced residual distribution
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into buckets.
    // Class 0: perfect fit (post_residual == 0) -> strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Integer-division thresholds on post_residual: bins whose residual
        // falls in "useful" harmonic bands are preferred.
        let band = post_residual / 10; // 0..=9 harmonic decile
        match band {
            0 => score -= 15.0,          // residual 1..9: nearly perfect
            1 => score -= 8.0,           // residual 10..19: still very usable
            2 => score -= 3.0,           // residual 20..29
            3 => score -= 1.0,
            6 | 7 => score += 4.0,       // residual 60..79: awkward zone
            8 => score += 10.0,          // residual 80..89: large dead space
            9 => score += 18.0,          // residual 90..99: worst waste
            _ => {}
        }
        // Modulo arithmetic: residuals that are multiples of small harmonics
        // (5, 10) align better with typical item sizes -> reward them.
        if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 5 == 0 {
            score -= 2.5;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (10.0 - slack as f64 / 10.0).max(0.0);
        } else {
            // Next item cannot use the leftover -> penalize proportionally
            // to how far off it is (harmonic mismatch).
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 20.0).min(12.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when the item is large relative to capacity or when
    // open bins are very fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin for small items; big items justify it.
        score += 30.0 * (1.0 - frac);
        if mean_residual > 40.0 && fitting_bins_count > 2 {
            score -= 10.0; // fragmentation high: spreading load is fine
        }
    }

    // Slight preference to fill earlier-opened bins as stream progresses
    // (keeps open bin count low).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: gaps that are small but nonzero are the worst.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver: waste of the tightest kind
        } else if post_residual <= 20 {
            score += 25.0; // nearly dead space
        }
    } else {
        // Perfect fit is the ideal outcome: heavily reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity (post_residual small fraction).
    score += 0.4 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Open-bin pressure: prefer reusing existing bins over spreading load.
    score += 3.0 * open_bins_count as f64;

    // New-bin candidate handling: only attractive if current bins are crowded.
    if bin_residual == bin_capacity {
        score += 40.0; // base penalty for opening a new bin
        if fitting_bins_count == 1 && post_residual < 15 {
            // Last-chance bin with terrible fit: allow new bin to win.
            score -= 55.0;
        }
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 20.0; // existing bins nearly full anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // leftover blocks the known next item
    }

    // Early stream: be slightly more willing to open bins (flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item's size (perfect chained fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // strong reward for near-exact 2-step fit
        // If next item cannot fit anywhere else after this placement, penalize.
        if post_residual < next_item_size {
            score += 25.0;
        }
        // Reward leaving exactly enough room for next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: purely minimize waste.
        score -= 20.0;
    }

    // Relative residual coupling: penalize bins far below mean residual
    // (they are "tight" bins better used for small items), reward bins above mean.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (mean_residual - res);
    }

    // Dead-space penalty: residuals too small to fit typical items are waste.
    if res < 10.0 && res > 0.0 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin if current placement
    // would create large dead space relative to remaining stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in stream: new bins are cheap; late: avoid fragmentation.
        score += 10.0 * (1.0 - progress);
        // Never open a new bin if a perfect 2-step fit exists elsewhere
        // (handled implicitly since that bin gets big discounts).
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Mild penalty for very tight fits that leave awkward residuals
    // (encourage filling bins to exactly zero when possible).
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit tightness: how well the item fills the bin's current residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    // Reward tight fits (post_residual small relative to capacity)
    let tight_bonus = (1.0 - post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight_bonus * tight_bonus;

    // Penalize leaving dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // perfect dead space (unusable anyway, but small)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0; // awkward gap: too small for min item, too big to ignore
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 25.0;
        // Penalize more when many bins are already open (fragmentation)
        score += 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper (future items can fill them)
        score -= 20.0 * (1.0 - progress);
        // If the item fits poorly in typical residual, new bin more attractive
        if fit_ratio < 0.5 {
            score -= 10.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 * 0.9 {
            score -= 12.0;
        }
    } else {
        // Lookahead synergy: prefer bins whose post_residual matches next item
        if next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 20.0 / (1.0 + diff);
        }
        // Prefer bins with residual below mean (consolidate fragmented space)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild global pressure: many open bins -> favor filling existing ones
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap;

    // Base: penalize post_residual, with smooth polynomial coupling to stream progress.
    // Late in the stream, dead space matters more (fewer chances to fill it).
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth quadratic reward for tight fits (small post_residual relative to capacity).
    score -= 30.0 * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Smooth coupling: a large post_residual is worse when mean residual is small
    // (this bin would be the outlier waster).
    score += 0.5 * pr * (1.0 - mean_residual / cap).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // Perfect post-fit: smooth reward peaking when next item exactly fills remainder.
            score -= 15.0 * (1.0 - (gap / cap).abs());
        } else {
            // Next item cannot fit here; mildly penalize near-miss dead space.
            score += 0.3 * (-gap);
        }
    }

    // Smooth penalty for opening new bins when many bins already exist late in stream.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 10.0 + 15.0 * progress + 0.5 * open_bins_count as f64;
        // But allow new bin if this bin's fit would be terrible anyway.
        score -= 0.4 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap;

    // Perfect-fit reward: post residual in {0, 10, 20, 25, 50} classes are highly reusable.
    let harmonic = post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 10 == 0;
    if harmonic {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Small dead space is bad if nothing small can ever fill it (sizes >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline, opened only if placement is poor.
    if bin_residual == bin_capacity {
        score = 45.0 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big item coming, fresh bin attractive
        }
    }

    // Prefer tighter bins relative to mean residual (best-fit flavor).
    score += (post_f - mean_residual) * 0.15;

    // Late in the stream, consolidate harder.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.7 {
        score += 0.05 * post_f;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize gaps too small for the lookahead item if it would otherwise
    // have needed a bin (wasted potential pairing).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty to encourage spreading across fitting bins sensibly.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Open-bin pressure: when many bins are open, favor consolidating into
    // this bin (larger fill) to avoid bin sprawl.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (0.3 + progress);

    // Prefer bins whose residual is already below average (tighter bins
    // fill better); penalize very loose bins when many are open.
    let resid = bin_residual as f64;
    if resid > mean_residual {
        score += 0.15 * (resid - mean_residual) * (1.0 + open_bins_count as f64 / 10.0);
    } else {
        score -= 0.10 * (mean_residual - resid);
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., this empty bin is a clean slate), but discourage it when tight
    // fits exist elsewhere.
    if bin_residual == bin_capacity {
        let fresh_bonus = 15.0 + 3.0 * open_bins_count as f64;
        score -= fresh_bonus;
        if fitting_bins_count >= 1 {
            // some open bin fits; opening new should lose unless fit is bad
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual {
        // next item can't follow here: mild penalty proportional to gap
        score += (next_item_size.saturating_sub(post_residual)) as f64 * 0.3;
    }

    // Last-chance bin: strong preference to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize bins far from the mean residual (prefer bins similar to average fill)
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // New-bin candidate: penalize opening a new bin unless current residuals are all tight
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5;
    }

    // Early in stream: slightly discourage hoarding many open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual), especially with lookahead synergy.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        // Perfect pairing: post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            // Penalize leaving slack the next item can't fully use.
            score += slack as f64 * 0.25;
            if slack < 10 {
                score -= 4.0; // near-perfect chain is still good
            }
        } else {
            // Next item can't fit here anyway; mild reward for compactness.
            score -= 2.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Penalize creating unusable dead space relative to the smallest possible item (1).
    // Dead space = residual that no future item can plausibly use; approximate via
    // how far post_residual is below the mean of remaining demand.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about this bin's quality.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins
    // to avoid bin proliferation.
    score -= mean_residual * 0.05;
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Time horizon: early in the stream, keep bins flexible (avoid tiny residuals);
    // late in the stream, pack aggressively.
    score += t * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // It should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + mean_residual * 0.1;
    }

    // Slight preference for bins whose current residual was already small
    // (best-fit flavor on top of post-residual).
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep residuals flexible; late, chase tight fits harder.
    let progress_coupling = post * (1.0 - progress) * (1.0 - progress) * 0.5
                         - post * progress * progress * 0.6;
    score += progress_coupling;

    // Penalize dead space relative to mean residual across open bins (smooth quadratic).
    let dead = (post - mean_residual) / cap;
    score += 12.0 * dead * dead * cap;

    // Lookahead: reward bins whose post_residual fits the next item (smooth trough).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (-gap / 15.0) * gap / 15.0 * 15.0 / (gap + 15.0);
        // exact match bonus, smoothly scaled
        score -= 6.0 * (1.0 - gap / (gap + 1.0));
    }

    // Last-chance bin: strong reward, fading smoothly with fitting bin availability.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 10.0 * scarcity * (1.0 + progress);

    // Mild penalty for crowding many open bins when residuals are large (encourage consolidation).
    score += 0.05 * open_bins_count as f64 * norm_post * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = post + 25.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: classify post_residual into
    // capacity fractions / integer-division buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fill reward: post_residual of 0 is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small to hold the smallest item (1)
    // are fine, but residuals in awkward harmonic classes are penalized.
    // Class by modulo 10 bands (classic harmonic classes).
    let class = post_residual % 10;
    if post_residual > 0 && class != 0 {
        score += (10 - class) as f64 * 0.5; // non-aligned residuals slightly penalized
    }

    // Reward residuals that are exact multiples of common item classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual % next_item_size == 0 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to wasted lookahead.
        score += (next_item_size as f64 - pr) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bins get a baseline score that depends
    // on how fragmented the current bins are.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it competitive only when existing
        // residuals are fragmented (high mean residual spread).
        score = cap - 10.0;
        if mean_residual > cap * 0.5 {
            score += (mean_residual - cap * 0.5) * 0.5;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If only one bin fits the item, opening a new bin is wasteful.
        if fitting_bins_count >= 1 {
            score += 40.0;
        }
    }

    // Mild pressure toward tighter bins overall.
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, or too small for the
    // lookahead item) are essentially unusable — penalize them hard.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual) as f64;
    }

    // If the leftover gap cannot fit the next item, it is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; also mildly favor reusing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses and when
        // many bins are already open.
        score += 60.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score += 0.3 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Slight preference for bins whose residual is near the mean (keep a
    // balanced pool of residuals, avoiding many tiny gaps).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * fill;
        } else {
            // next item does NOT fit in the leftover: penalize dead space
            score += 50.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small unusable gaps (< 10% of capacity)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to open new bins for large items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize mildly unless item is large or stream is early
        score += 120.0 - 30.0 * (item_size as f64 / bin_capacity as f64) - 100.0 * (1.0 - progress);
    }

    // Slight preference for filling larger-residual bins when many bins open
    score -= 0.1 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty curve.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space: residuals that can no longer fit typical items.
    if post_residual < 10 {
        score -= 5.0; // near-perfect fill bonus
    } else if post_residual < 20 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many bins compete, prefer keeping flexibility.
        score += 0.5 * (fitting_bins_count as f64).min(5.0);
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // If leftover is smaller than the next item, penalize creating waste
            // unless the leftover is tiny (unusable anyway).
            if post_residual >= 1 && post_residual < next_item_size {
                score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
            }
        }
    }

    // Global state: prefer filling bins when the average residual is large
    // (lots of slack in the system), discourage fragmenting tight systems.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more open to opening new bins
    // (spread items); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by progress and open-bin pressure.
        score += 45.0 - 20.0 * progress;
        if open_bins_count > 8 {
            score += 5.0; // discourage bin proliferation
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // reserve fresh bins for big upcoming items
        }
    }

    // Prefer bins whose residual is close to item_size (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Squared coupling: dead space becomes increasingly costly as the stream advances.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean residual (outlier bins).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // Mild penalty spread over many fitting bins (competition discount).
        score += 2.0 / (fitting_bins_count as f64);
    }

    // Lookahead: reward if the next item fits into the resulting post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            // Next item won't fit: penalize leaving residual that is nearly-but-not-quite usable.
            let gap = (nxt - pr) / cap;
            score += 5.0 * gap * (1.0 - progress);
        }
    }

    // Slight preference for consolidating into fewer bins early on.
    score += 0.4 * open_bins_count as f64 * progress;

    // New-bin candidate handling: make empty bins moderately attractive only when
    // current item leaves an awkward residual or late in the stream.
    if bin_residual == bin_capacity {
        let awkward = 1.0 - ((cap - pr) / cap); // == 1 when item_size small? pr == cap here
        let _ = awkward;
        let fill = item_size as f64 / cap;
        let awkwardness = (1.0 - fill) * (1.0 - fill);
        score = pr + 10.0 - 18.0 * awkwardness * (1.0 - progress) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of the leftover space: leftovers divisible into
    // common item-size classes (multiples of 10) are more reusable.
    let class = post_residual % 10;
    score += (10 - class) as f64 * 0.6; // penalize awkward leftovers

    // Dead-space penalty: leftovers too small for typical items.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - progress);
    }

    // Lookahead compatibility: can next_item_size fit in the leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains that keep the next item in this bin.
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Penalize leaving a gap that forces a new bin for next item.
            score += 6.0;
        }
        // Harmonic coupling: leftover mod next_item_size near zero is ideal.
        if next_item_size > 0 && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    if open_bins_count > 4 {
        score -= 2.0 + (open_bins_count as f64).sqrt();
    }

    // Compare against mean residual: bins far below mean are good to drain.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        let poor_fit = post_residual > 25;
        if big_item || poor_fit {
            score -= 10.0;
        } else {
            score += 15.0; // discourage wasting fresh bins on small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space (gap too small for any item, min size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // small gap, only very small items can use it
    }

    // Reward tight fits
    score -= 0.5 * item_size as f64;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item almost fits (small miss), slight penalty
    else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Prefer bins with residual below the mean (tighter bins used first)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: make it less attractive unless existing fit is bad
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward post_residual == next_item_size (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // next item can also fit here: mild bonus proportional to how close post_residual stays
        score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit in residual: penalize dead space relative to next item
        score += 8.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize residuals that are unlikely to be reusable (small dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins with residual above mean (consume large leftovers)
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in stream, new bins are cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Reward tight fits relative to capacity (relative waste term).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 60.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this bin;
    // if next item would NOT fit even in a fresh bin, ignore lookahead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 80.0;
        } else {
            // Dead space penalty scaled by how much of next item is wasted here.
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += gap * 0.8;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score += fill_ratio * open_bins_count as f64 * 4.0;

    // Mean-residual coupling: penalize bins far above mean residual (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Time horizon: early in stream, slightly favor new bins for flexibility;
    // late in stream, favor packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly as stream progresses.
        score += 30.0 + progress * 120.0;
        // Early stream: new bins are cheap; also reward when item is large.
        score -= (1.0 - progress) * 40.0;
        if item_size >= 50 {
            score -= 20.0;
        }
    } else {
        score -= progress * 25.0;
    }

    // Large items: prefer bins where they leave a useful (>= next small item) gap.
    if item_size >= 60 && post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny dead space after a big item is bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: minimize post residual, but with a smooth "sweet spot" dip
    // around small residuals (tight fits) via a quadratic coupling.
    let mut score = pr;

    // Smooth tight-fit reward: quadratic bowl in normalized post residual,
    // scaled by stream progress (tight fits matter more late in stream).
    let tight = norm_pr * norm_pr * cap;
    score -= (1.0 - progress) * 0.0 + progress * tight * 2.0;

    // Penalize large dead space quadratically (unusable gaps).
    let dead = (norm_pr - 0.2).max(0.0);
    score += dead * dead * cap * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= (1.0 - slack) * 5.0 * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Smooth penalty for blocking next item, proportional to miss size.
        let miss = (next_item_size as f64 - pr) / cap;
        score += miss * miss * 10.0;
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Diversification: if many open bins, mildly favor filling existing ones
    // over opening new bins (new-bin candidate has pr == cap, so its tight/dead
    // terms are neutral; add a smooth open-bins pressure term).
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    score += open_pressure * (norm_pr * cap / 25.0).min(4.0);

    // Deviation from mean residual: prefer bins near the mean (smooth coupling).
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev.abs() * 3.0 * (0.5 + progress);

    // Item-size interaction: big items should prefer very tight fits.
    score -= (item / cap) * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: residues divisible by small amounts
    // (10, 20) are "reusable" slots for typical item sizes; odd/prime-like
    // residues are dead space. Penalize dead-space classes.
    let r = post_residual;
    let class: f64 = if r == 0 {
        -30.0 // perfect fit, excellent
    } else if r % 10 == 0 {
        -8.0 * (r / 10) as f64 // clean multiple of 10, reusable
    } else if r % 5 == 0 {
        2.0
    } else {
        6.0 // awkward residue, likely dead space
    };
    score += class;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score += 0.3 * slack;
            // Harmonic check: does the pair leave a clean residue?
            let post2 = r - next_item_size;
            if post2 % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot follow into this bin; slight penalty,
            // worse if this bin would be left with tiny unusable residue.
            if r > 0 && r < 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // leave heavy dead space or no bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { -10.0 } else { 15.0 };
        score += pressure;
        // Early in the stream, building fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.15 * mean_residual;
    }

    // Mild preference to consolidate: fewer open bins -> favor existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (<=10)
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < item_size.min(20) {
        // Gaps smaller than the current item's small-threshold are likely dead too
        score += (20 - post_residual.min(20)) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: if the residual can host the next item, reward; else penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: discourage scattering across many bins unless fit is tight
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        score -= 5.0;
    }

    // Slight preference to fill older bins as stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but heavily penalize
    // leaving dead space that is too small for typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && dead < next_item_size as f64 {
            // Dead space cannot host the next item -> penalty scaled by item size.
            score += dead * (next_item_size as f64 / 40.0);
        }
        if dead < 10.0 {
            score += 25.0; // unusable sliver
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Also reward near-matches within a small tolerance.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap <= 5.0 {
            score -= 20.0 * (1.0 - gap / 5.0);
        }
    }

    // Relative to mean residual: prefer bins whose post_residual stays close
    // to the mean (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins moderately unattractive unless the
    // item fits very poorly everywhere (handled by last-chance bonus above).
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the next item is large and this item is small, a fresh bin
        // can be worthwhile to preserve tight open bins.
        if next_item_size > 0 && item_size <= 20 && next_item_size >= 60 {
            score -= 55.0;
        }
    }

    // Late in the stream, tighten packing further (less room to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Mild bonus for using existing bins when many are open.
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small nonzero leftovers are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.5 * post_residual as f64;
    }

    // Tight-fit reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: reward bins whose leftover can host the next item (chaining),
    // penalize bins that strand the next item unless a new bin would open anyway.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins relative to the fleet average (best-fit style balancing).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in the stream, avoid spreading items across many bins.
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    // (no good existing fit or item nearly fills a fresh bin).
    if bin_residual == bin_capacity {
        let fresh_leftover = bin_capacity - item_size;
        if fitting_bins_count > 0 {
            // An open bin can fit: only open a new bin if the item would leave
            // a very clean small leftover or existing options are poor.
            if fresh_leftover <= 5 {
                score -= 60.0; // item almost fills a fresh bin: good dedicated bin
            } else if fresh_leftover > 50 && next_item_size > 0 && next_item_size <= fresh_leftover {
                score -= 20.0; // new bin can chain the next big item
            } else {
                score += 120.0; // prefer existing bins
            }
        } else {
            score -= 50.0; // forced new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) - norm_pr * (1.0 - progress);
    score += 20.0 * poly;

    // Penalize tight fits that create dead space, reward good utilization
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (nxt / cap);
        } else {
            score += 3.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure to prefer fuller bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Deviation from mean residual: prefer bins near the mean to balance
    score += 0.5 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (multiples of 10) are more valuable later.
    let post = post_residual;
    if post > 0 {
        let cls = post % 10;
        // residue 0 = perfect harmonic slot, best; larger residue = more waste
        score -= (10 - cls) as f64 * 0.35;
        if cls == 0 {
            score -= 4.0;
        }
        // very small leftovers are dead space unless near-perfect
        if post < 10 && cls != 0 {
            score += 6.0;
        }
    } else {
        score -= 8.0; // perfect closure
    }

    // Integer-division threshold: post_residual bucketed by quarters of capacity
    let quarter = cap / 4.0;
    if (post as f64) <= quarter {
        score += 1.5; // tight fit, little future flexibility
    } else if (post as f64) >= 2.0 * quarter {
        score -= 1.5; // roomy bin stays flexible
    }

    // Lookahead coupling: does next item fit in the harmonic class of leftover?
    if next_item_size > 0 {
        if next_item_size <= post {
            // check harmonic compatibility: leftover after next item
            let post2 = post - next_item_size;
            score -= 2.0;
            if post2 % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: keep empty bins neutral-to-slightly-averse
    // so we only open when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        // empty bin's post_residual == capacity - item; treat as baseline
        score += 2.0 + 0.02 * open_bins_count as f64;
    }

    // Progress pressure: late in the stream, prefer compacting into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Prefer bins below mean residual (denser bins) slightly
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }
    // Medium gaps (11..=25) are moderately wasteful.
    if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Reward very tight fits (waste <= 3) strongly.
    if post_residual <= 3 {
        score -= 40.0;
    }

    // If the leftover could exactly host the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leftovers that are too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer packing into existing bins
    // (penalize the new-bin candidate implicitly by rewarding existing bins).
    if bin_residual < bin_capacity {
        score -= 2.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize more when many bins are already open.
        score += 5.0 + 3.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively at scale
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * item_size as f64;

    // 2-step lookahead: perfect match between post_residual and next item
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect chaining: this bin will be exactly refilled
            score -= 40.0;
        } else if diff > 0 && diff <= 20 {
            // Next item fits well after this one
            score -= (20 - diff) as f64 * 1.5;
        } else if diff < 0 {
            // Next item would not fit; penalize proportionally
            score += (-diff) as f64 * 0.8;
        }
        // If next item is large, prefer leaving larger residuals
        if next_item_size >= 50 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Relative to mean residual: prefer bins with below-average residual
    // (consume fuller bins first, keep roomy bins for big future items)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, relaxed early / when many bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        // Large next item with no room anywhere: opening fresh bin is fine
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Penalize unusable dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post-residual, with mild superlinearity to punish dead space.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 12.0 * (1.0 - gap);
        } else {
            // Next item won't fit here: penalize wasted residual that next item can't use.
            let waste = (pr - nxt).max(0.0);
            let _ = waste;
            score += 3.0 * (nxt - pr).min(30.0) / 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-ish default; encourage new bin only when
    // existing bins fit poorly (large post-residual spread) or many open bins with
    // high mean residual (fragmentation) suggest consolidation is failing.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        let frag = if open_bins_count > 0 {
            (mean_residual - (bin_capacity as f64 - item_size as f64)).max(0.0) / bin_capacity as f64
        } else {
            0.0
        };
        let t = step_index as f64 / total_items.max(1) as f64;
        score = 0.5 * pr + 25.0 - 18.0 * frag - 10.0 * t;
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> reward filling existing bins more aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln1p();
    score -= 2.0 * pressure * (0.5 + t);

    // Tight-fit reward: near-perfect packing gets extra discount.
    if post_residual > 0 && post_residual <= 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let size_frac = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear polynomial emphasis
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: as stream advances, penalize waste more strongly
    score += 25.0 * progress * norm_pr * (1.0 + size_frac);

    // Quadratic waste penalty with mean-residual coupling
    score += 8.0 * norm_pr * norm_pr * (mean_residual / cap);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / cap;
        score -= 6.0 * (1.0 - norm_pr) * (1.0 - chain_fit.abs() - 0.5).abs() * 0.0
            - 6.0 * (1.0 - (pr / (next_item_size as f64 + 1.0)) * 0.3);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: discourage opening a new bin unless residuals are large
    if bin_residual == bin_capacity {
        score = pr + 30.0 + 20.0 * progress * (mean_residual / cap).min(1.0)
            - 15.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Base penalty for opening a new bin when others might fit the item.
        score += 55.0;

        // Reward opening a fresh bin for large items or when the lookahead
        // item cannot share the current stream of partial bins.
        let item_f = item_size as f64;
        if item_f > 0.5 * cap {
            score -= 25.0;
        }
        if next_item_size > 0 && (next_item_size as u32).saturating_add(item_size) > bin_capacity {
            score -= 20.0;
        }
        // Late in the stream, consolidating is less valuable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;

        // Harmonic class: if post residual lands exactly on a coarse class
        // boundary (multiple of 20), a fresh bin is more reusable.
        if post_residual % 20 == 0 {
            score -= 8.0;
        }
    } else {
        // Reward tight fits: subtract proportional fill achieved.
        score -= (1.0 - post_residual as f64 / cap) * 10.0;

        // Perfect fit is highly desirable.
        if post_residual == 0 {
            score -= 25.0;
        }

        // Last-chance bin: if this is the only bin that fits, strongly favor it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }

        // Lookahead compatibility: reward residuals that can host the next item.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 4.0;
                // Harmonic bonus: residual class matches next item class.
                if post_residual % 10 == next_item_size % 10 {
                    score -= 2.0;
                }
            } else {
                // Penalize dead space the next item cannot use.
                score += (next_item_size - post_residual) as f64 * 0.35;
            }
        }

        // Dead-space harmonic penalty: residuals in (0,10) are nearly unusable
        // since minimum item size is small but fragmentation compounds.
        if post_residual > 0 && post_residual < 10 {
            score += 9.0;
        }

        // Fine-grained harmonic term: prefer residuals near class centers.
        score += (post_residual % 10) as f64 * 0.25;

        // Discard bins far below the mean residual (they are already tight;
        // keep looser bins flexible) unless the fit is very tight.
        if (post_residual as f64) < mean_residual * 0.4 && post_residual > 15 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are fine, but residuals in the awkward
    // low band (1..=12) are likely unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting the item into an existing bin when few bins can fit it
    // (last-chance bin): avoid opening a new bin when alternatives are scarce.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins; few open bins -> new bins are cheaper.
    let pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= 8.0 * (pressure / (pressure + 5.0));
    } else {
        // New-bin candidate: penalize when many bins are open or when this
        // bin would fit fine in an existing one; reward when item is large
        // and existing residuals are small.
        score += 12.0 * (pressure / (pressure + 5.0));
        let tightness = mean_residual / bin_capacity as f64;
        score -= 20.0 * tightness;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If post residual is smaller than the next item but nonzero, it is
    // likely dead space for the lookahead -> penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Prefer tight fits overall: normalized fill ratio bonus.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill * fill;

    // Stream progression: later in stream, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual slightly larger than next item: good but not perfect
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual as f64 - next_item_size as f64).sqrt() * 2.0;
    }

    // Dead space: post_residual too small for the next item (unusable unless tiny)
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
        // Extra penalty if the dead space is small but nonzero (worst kind of gap)
        if post_residual > 0 {
            score += 5.0;
        }
    }

    // Prefer tight fits overall: small post_residual relative to capacity is good
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: filling a below-average-residual bin is efficient
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins would leave large dead space; otherwise penalize the fresh bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 30.0;
        // But if the item is large and would leave big dead space elsewhere, new bin helps
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 40.0;
        }
        // Late in the stream, discourage creating bins that will barely be used
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero residual).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // stranded space relative to lookahead
        }
        // If next item exactly matches post_residual, strong chaining bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Global pressure: many open bins with slack -> discourage new-bin sprawl.
    let pressure = open_bins_count as f64 / (mean_residual + 1.0);
    score += 0.05 * pressure;

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        // Base penalty so a new bin is chosen only with good reason.
        score += 45.0;
        // Late in stream or many open bins: opening a fresh bin is worse.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        score += 0.3 * open_bins_count as f64;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= item_size {
            score -= 20.0;
        }
        // If very few bins can fit the item, new bin becomes attractive.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    // Mild time-horizon coupling: early on, be conservative with tight fits.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - horizon);

    // Prefer bins closer to mean residual (balanced usage) slightly.
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty coupled with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 6.0 * norm_pr * norm_pr * cap;

    // Reward tight fits: smooth interaction of post_residual with item_size
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * (1.0 - norm_pr) * cap;

    // Lookahead coupling: smooth polynomial interaction with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0) / cap;
        score -= 10.0 * usable * (1.0 + progress);
        // penalize when next item exactly fills residual (smooth term)
        let exact = 1.0 - ((pr - nx).abs() / cap).min(1.0);
        score -= 8.0 * exact * exact * (1.0 - progress);
    }

    // Last-chance bonus: smooth function of fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * scarcity * (1.0 - norm_pr);

    // Mean residual coupling: penalize bins far from the mean (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Penalize opening new bins as stream progresses (smooth)
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    } else {
        score -= 3.0 * (1.0 - progress);
    }

    // Mild open-bin pressure
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (dead-space classes)
    let r = (post_residual % 10) as f64;
    score -= 3.5 * r; // prefer post-residuals landing on "useful" residue classes (multiples of 10)

    // Integer-division thresholds on post_residual
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score += 10.0; // awkward dead zone
    } else if post_residual < 40 {
        score += 18.0;
    }

    // Capacity fraction coupling: item_size relative to capacity thirds
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.66 {
        score -= 20.0; // large items should go into tight residual bins
    } else if frac < 0.34 {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic compatibility: residue match between next item and post_residual
            let compat = (next_item_size % 10) as f64;
            score -= 12.0 + 0.3 * compat;
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only prefer when open bins are mostly full
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 40.0 + 60.0 * (1.0 - pressure) - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Stream progression: tighten packing toward the end
    let t = step_index as f64 / total_items.max(1) as f64;
    score += t * (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is expensive: strong penalty unless it is genuinely needed.
        score += 60.0;
        // If no open bin fits, opening is forced: reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        // Late in the stream, prefer closing out open bins rather than spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the item nearly fills a fresh bin, a new bin is fine.
        if post_residual <= 5 {
            score -= 40.0;
        }
    } else {
        // Strict dead-space avoidance: residuals in [1, 12] are likely unusable
        // (min item size historically >= 10), so penalize creating them.
        if post_residual >= 1 && post_residual <= 12 {
            score += 25.0;
        }
        // Perfect or near-perfect fits are highly desirable.
        if post_residual == 0 {
            score -= 30.0;
        } else if post_residual <= 3 {
            score -= 12.0;
        }
        // Last-chance bin: if this is the only bin that fits, strongly favor using it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Lookahead: if the next item could exactly use the post_residual,
        // reward leaving that gap; otherwise, if next item won't fit the gap,
        // mild penalty for hoarding space.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 20.0;
            } else if next_item_size > post_residual && post_residual > 0 {
                score += 8.0;
            }
        }
        // Prefer filling bins with already-small residuals (consolidation pressure).
        score += (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.1;
        // Open-bin pressure: many open bins -> favor placements that reduce spread.
        score += open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: strongly reward, more so when the leftover after the next item is small.
            let leftover2 = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.15 * leftover2;
        } else {
            // Dead space for the next item: penalize proportionally to the mismatch.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss;
        }
    } else {
        // Last item: pure best-fit on post residual.
        score += 0.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Compare residual against mean residual: bins tighter than average are better to fill.
    score -= 0.30 * (mean_residual - post_residual as f64);

    // Penalize very wasteful placements relative to capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste * waste;

    // New-bin candidate: only attractive when open bins are quite full or none fit well.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Prefer new bin late in stream or when bins are packed tight.
        if avg_fullness > 0.75 {
            score -= 8.0;
        } else {
            score += 20.0;
        }
        // Discourage hoarding many open bins early.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild stream-phase modulation: be more conservative (favor existing bins) early on.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * phase * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead item: penalize small unusable gaps.
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Crowding: when many bins are open, favor consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * progress;
    } else {
        // New-bin candidate: penalize opening bins early or when mean residual is large.
        score += 8.0 + 6.0 * (1.0 - progress) + 0.05 * mean_residual;
        // Allow new bin if current item would leave a very awkward remainder in any open bin.
        if post_residual > 40 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with residuals near mean (keeps balance).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, but nonlinearly (quadratic/cubic coupling)
    let mut score = x * (1.0 + 1.5 * x * x);

    // Smooth stream-progress coupling: waste matters more early, tight fits favored late
    let early = (1.0 - progress).powi(2);
    let late = progress.powi(2);
    score += 2.0 * early * x * x;
    score -= 1.2 * late * x * (1.0 - x) * 4.0; // reward mid-range tight fits late

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = if pr as u32 >= next_item_size { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= fit * (0.8 + 1.5 * late) * closeness.max(0.0);
        score += (1.0 - fit) * nx * (0.5 + late);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * late;
    }

    // Mean residual coupling: deviating below mean residual is good (tight packing)
    let mean_x = mean_residual / cap;
    score += 0.6 * (x - mean_x).abs() * (1.0 - late);

    // Mild penalty for opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += 0.5 + 0.3 * (open_bins_count as f64).sqrt();
        score -= 1.0 * late; // late in stream, fresh bins are fine
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: residues modulo 10 (since sizes 1..100)
    let residue = post_residual % 10;
    // Residue 0 means post_residual is a "harmonic" multiple of 10 — likely reusable by future items
    score -= match residue {
        0 => 8.0,
        5 => 4.0,
        _ => 0.0,
    };

    // Integer division thresholds: post_residual in [1,9] is dead space unless a small item comes
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
        // If next item can fill this dead space exactly, reward instead
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Next-item lookahead: reward leaving space that exactly accommodates the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            // Prefer leaving a harmonic leftover (multiple of 10)
            if leftover % 10 == 0 {
                score -= 12.0;
            }
            score -= (post_residual.min(next_item_size * 3)) as f64 * 0.3;
        } else {
            // Next item won't fit here: penalize tight fits that strand the bin
            score += 6.0;
        }
    }

    // Capacity fraction classes: bins whose fill crosses quarter thresholds are "committed"
    let fill = bin_capacity - post_residual;
    let quarter = bin_capacity / 4;
    if fill / quarter >= 3 {
        score -= 10.0; // strongly prefer filling nearly-full bins
    } else if fill / quarter == 0 {
        score += 5.0; // discourage scattering into nearly-empty bins
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // New bin starts fresh; penalize mildly so it's chosen only when open bins score badly
        score += 15.0;
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Stream progression: late in stream, prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean residual coupling: if mean residual is low, preserve remaining large-capacity bins
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item (>=1) can
    // use well are heavily penalized. Treat gaps <= 10 as dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave a "usable" gap sized for common items.
    if post_residual >= 10 {
        // favor residual close to typical item sizes (multiples of ~10..50)
        let r = post_residual as f64;
        let target = (r / 25.0).round() * 25.0;
        score -= 0.6 * (r - target).abs();
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to mean residual (existing bins would leave big dead space)
    // or when there are no open bins.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 {
            0.0
        } else {
            let waste_if_open = mean_residual; // space left stranded in open bins
            30.0 + 0.8 * waste_if_open + 4.0 * open_bins_count as f64
        };
        score += pressure;
        // Opening a new bin is fine if item is big and would fragment an old bin
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits snugly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item would NOT fit here, mildly penalize hoarding a large gap.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    score += 0.15 * open_bins_count as f64;

    // Stream progression: early on, be more willing to open bins (explore);
    // later, be conservative and pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Baseline cost of opening a new bin.
        score += 25.0 + 15.0 * (1.0 - progress);
        // Reward if the next item can also fit into this fresh bin (2-step lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // Penalize a fresh bin that will be left with a large unusable gap.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Lookahead: reward bins whose post-residual matches the next item well.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 45.0; // perfect 2-step match: bin fully closed after next item
            } else if post_residual > next_item_size {
                score -= (post_residual - next_item_size) as f64 * 0.3;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.2;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Reward tight fits relative to mean residual.
        let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
        if (post_residual as f64) < mean_r {
            score -= (mean_r - post_residual as f64) * 0.4;
        }

        // Penalize tiny dead space that likely becomes unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Reward perfect or near-perfect fill strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last chance: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize leaving a gap just barely smaller than the next item (dead space trap).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Penalize spreading across many open bins when residuals are large (encourage consolidation).
    if bin_residual as f64 > mean_residual {
        score -= 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive late in the stream or when current bin is a bad host.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.4 * bin_capacity as f64;
        if poor_fit && progress > 0.2 {
            score -= 10.0 * progress;
        } else {
            score += 25.0; // discourage opening new bins when open bins fit reasonably
        }
    }

    // Mild time-horizon modulation: early stream, be conservative (prefer tight packing);
    // late stream, prefer closing bins out.
    score += 10.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling: waste decays in value as stream progresses
    let waste_weight = 1.0 + 1.5 * progress * progress;
    score += waste_weight * (pr / cap).powi(3) * cap * 0.5;

    // Reward tight fits (low post residual relative to item size)
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * 10.0;

    // Penalize dead space that next item likely can't use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: slightly penalize early, mildly favor late when residuals fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score += 8.0 - 12.0 * progress + 10.0 * fragmentation * progress;
    }

    // Mild pressure against scattering across many open bins
    score += 0.3 * (open_bins_count as f64).sqrt() * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by a coarse
    // quantum are more reusable by future items drawn from an unknown but
    // likely quantized distribution.
    let quantum: u32 = 10;
    let class = post_residual / quantum;
    score -= (class as f64) * 3.0;

    // Exact-fit reward: dead space of zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize tiny dead spaces (1..quantum) that are hard to reuse.
    if post_residual > 0 && post_residual < quantum {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly placement; reward proportionally to slack left
            // after the hypothetical next placement.
            let post2 = post_residual - next_item_size;
            score -= 40.0 + (post2 as f64) * 0.5;
            // Harmonic bonus if chained residual is again class-aligned.
            if post2 % quantum == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; mildly penalize, scaled by how much
            // it overshoots.
            let overshoot = next_item_size - post_residual;
            score += (overshoot as f64).min(60.0) * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good reuse exists (large item, small residual
    // elsewhere implied via mean_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // If mean residual across open bins is small, opening is justified.
        if mean_residual < item_size as f64 {
            score -= 120.0;
        }
        // Large items prefer fresh bins to avoid fragmentation.
        if item_size > bin_capacity * 3 / 4 {
            score -= 60.0;
        }
        // Late in the stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Prefer tighter bins generally: reward closeness of item to residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Mild penalty when many bins are open (discourage sprawl).
    score += (open_bins_count as f64) * 0.5;

    // Deviation from mean residual: placing into bins below the mean keeps
    // larger residuals available for larger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for even the minimum item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit region: strongly reward filling the bin completely.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space (below the smallest possible item) -> heavy penalty.
        score += 60.0;
    } else {
        // Usable residual: reward tight fits proportionally to how snug the placement is.
        let snugness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * snugness;
        // Small-but-usable gaps are risky; gently discourage leaving tiny usable slivers.
        if post_residual < 20 {
            score += 8.0;
        }
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // this placement strands the next item
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    // (placing into a bin with residual near/above mean keeps the pool balanced).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 20.0 * dev;

    // New-bin candidate: only attractive when the item is large relative to a fresh bin
    // or the current fit is terrible. Bias slightly against opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = post - next;
        if diff >= 0.0 {
            // Next item fits after this placement: reward tight 2-step packing.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted residual.
            score += 12.0 + (-diff / bin_capacity as f64) * 20.0;
        }
        // Bonus for perfect two-item fill.
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 25.0;
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Favor keeping small residuals usable; penalize very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for compacting many items into few bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when current fit is very poor.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes capacity when open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early (lots of stream left to fill them) and when the
        // fit in existing bins is terrible (large post_residual relative to capacity).
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score -= 20.0 * (1.0 - progress) * poor_fit;
        score += 10.0 * progress;
        // If open bins are already crowded (low mean residual), a new bin is fine.
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Favor bins with residual above the mean (keep small holes consolidated).
        if (bin_residual as f64) < mean_residual {
            score += 3.0;
        }
    }

    // Mild preference for bins that will be left with residual divisible-ish sizes.
    if post_residual % 10 == 0 {
        score -= 2.0;
    }

    // Slight time pressure: late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress
    let p = progress;
    let poly = 1.0 + p * (1.0 - p) * 4.0; // peaks at 1.0 mid-stream, 1.0 at ends
    score *= poly;

    // Penalize dead space non-linearly: squared normalized residual
    score += (norm_pr * norm_pr) * cap * 0.5 * (0.5 + p);

    // Reward tight fits: post_residual near zero gets bonus
    score -= (1.0 - norm_pr).powi(3) * cap * 0.4;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 10.0 * norm_next * (1.0 - norm_pr);
        } else {
            score += 3.0 * norm_next * cap * norm_pr;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild penalty relative to mean residual to prefer below-average emptiness
    score += (mean_residual - pr) * 0.05;

    // New-bin candidate: prefer opening new bin only for large items or late stream
    if bin_residual == bin_capacity {
        let openness = 0.5 * cap + norm_item * cap * 0.5;
        score = openness * (1.0 - 0.3 * p) + (1.0 - norm_item) * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity quarters
    let q = (post_residual % bin_capacity.max(1)) as f64;
    let quarter = cap / 4.0;

    // Reward residuals that are "harmonically useful": multiples of small classes
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual <= 10 {
        score += 40.0; // dead space below min item size
    } else if (post_residual % 10) == 0 {
        score -= 8.0; // decade-aligned residual is reusable
    }

    // Quarter-class logic: residuals near capacity fractions
    if (q - quarter).abs() < 5.0 || (q - 2.0 * quarter).abs() < 5.0 || (q - 3.0 * quarter).abs() < 5.0 {
        score -= 5.0;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0; // next item won't fit here -> dead space risk
        } else {
            score -= (next_item_size as f64) * 0.15; // residual matches lookahead
            if post_residual - next_item_size <= 10 && post_residual - next_item_size > 0 {
                score += 6.0; // would leave tiny dead space after next
            }
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we prefer filling open bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 0.5;
    }

    // Prefer bins tighter than the mean residual (good fill)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.1;
    }

    // Late-stream pressure: be greedier as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" zone
    // (1..=20) is heavily penalized — such slivers rarely fit future items.
    if post_residual > 0 && post_residual <= 20 {
        score += 40.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small but not zero post_residual is good when > 20).
    if post_residual > 20 && post_residual <= 40 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Lookahead dead zone: next item just barely misses the leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 12.0;
    }

    // Open-bins pressure: more open bins -> prefer consolidating into existing
    // bins rather than spawning new ones.
    let bin_pressure = open_bins_count as f64 * 2.0;

    if is_new_bin {
        // New-bin candidate baseline: penalize so it only wins when existing
        // fits are poor (large post_residual or dead-zone leftovers).
        score += 55.0 + bin_pressure + 10.0 * progress;
        // If no other bin fits, new bin is the only real option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Slight preference for bins with below-average residual (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward scaled by slack quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - 0.6 * slack;
        } else {
            // next item cannot fit here: penalize proportionally to the leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving more than average waste is bad; tighter-than-average is good.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
        if post_residual <= 15 {
            score -= 100.0; // near-perfect squeeze, definitely use it
        }
    }

    // New-bin candidate handling: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins usually win...
        score += 60.0;
        // ...but if the item is large relative to capacity, opening a fresh bin
        // avoids fragmenting an existing bin badly.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= 40.0 * (fill_ratio - 0.6);
        }
        // If the next item is also large, a fresh bin keeps pairing options open.
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 30.0;
        }
        // Late in the stream, avoid spawning bins that will never be filled.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 80.0 * progress;
        }
    }

    // Slight penalty for creating tiny unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly (small post_residual gets extra bonus).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        } else if post_residual >= next_item_size {
            score -= 6.0; // next item can still land here
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalized, but attractive when all open bins fit poorly.
    if is_new_bin {
        let open_fit_quality = if open_bins_count > 0 {
            (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64
        } else { 0.0 };
        let mean_fit = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score = 100.0 + 30.0 * (1.0 - progress) - 20.0 * (1.0 - mean_fit);
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits; must open
        }
        let _ = open_fit_quality;
    }

    // Encourage consolidating into bins with below-average residual (fill emptier-space bins).
    if !is_new_bin {
        score += 0.05 * (mean_residual - bin_residual as f64);
        // Slight preference to use more-loaded bins early, keep slack bins for big items.
        score += 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate looser fits; late, demand tighter packing
    let progress_coupling = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Penalize residuals that cannot fit the lookahead item (smoothly)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (ni - pr).max(0.0);
        score += 0.35 * waste * (1.0 + progress);

        // Reward bins whose post_residual still accommodates next item
        let fits_next = (pr - ni).max(0.0) / cap;
        score -= 0.25 * fits_next * cap * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Slight preference for consolidating into already-open bins vs new bin
    if bin_residual < bin_capacity {
        score -= 2.0;
    } else {
        // New-bin candidate: penalize mildly unless open bins are very fragmented
        score += 4.0 + 0.05 * open_bins_count as f64;
    }

    // Mean-residual coupling: when open bins are fragmented, favor using them
    let frag = (mean_residual - pr).abs() / cap;
    score += 0.5 * frag * frag * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division. Small post_residual classes are
    // "dead space" classes -> penalize; large ones keep bins useful.
    let class = post_residual / 10;
    match class {
        0 => score += 30.0,                      // 0..9: nearly dead space
        1 => score += 12.0,                      // 10..19
        2 => score += 4.0,                       // 20..29
        3 => score -= 2.0,                       // 30..39
        4 | 5 => score -= 5.0,                   // 40..59: versatile leftovers
        _ => score -= 8.0,                       // 60+: very reusable
    }

    // Perfect fill reward: post_residual in {0} is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling with lookahead item: reward if next item exactly fits
    // the post residual (harmonic resonance), penalize near-misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0_f64.min((10 - slack / 5) as f64 * 1.5);
        } else {
            // next item cannot use this leftover: mild penalty scaled
            // by how much of the leftover is wasted for the lookahead.
            let waste = (post_residual as f64 - (post_residual % next_item_size.max(1)) as f64) * 0.1;
            score += waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bins should only win when the item
    // is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score = score * 0.5 + (bin_capacity as f64 - post_residual as f64) * (0.3 + 0.7 * pressure * large_item);
        if pressure > 0.0 {
            score -= 15.0; // no open bin fits: opening new bin is fine
        } else {
            score += 10.0; // discourage wasteful new bins
        }
    }

    // Stream-phase modulation: early on, prefer tight packing of current
    // bins; late in the stream, be greedier about near-perfect fills.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= phase * (post_residual as f64) * 0.15;

    // Mean-residual coupling: if average leftover is high, closing gaps
    // (small post_residual) is more valuable.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Modulo-5 harmonic bonus: residuals that are multiples of 5 align
    // with common item-size classes.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps below the minimum item size are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing bins over
    // opening new ones; the empty-bin candidate has the largest residual so it
    // naturally loses unless other terms dominate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress);

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover: mild penalty for stranding space
        score += 3.0;
    }

    // Deviation from mean residual: prefer bins whose residual is already low
    // (concentrate packing), penalize placing into unusually empty bins.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but a post_residual
    // that exactly absorbs the NEXT item is even better (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item still fits here afterwards; mild reward scaled by tightness.
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 12.0 * tight;
        } else {
            // Next item cannot use the leftover: penalize dead space, worse when
            // the leftover is tiny (unusable sliver).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0 * (1.0 - dead / 10.0);
            }
        }
    } else {
        // Last item: purely reward tightest fit.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "junk drawers" — discourage dumping into them unless the fit is tight.
    let dev = (bin_residual as f64) - mean_residual;
    if dev < -10.0 {
        score += 0.15 * (-dev - 10.0);
    } else if dev > 10.0 {
        score -= 0.05 * (dev - 10.0);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for opening a brand-new bin when decent fits exist:
    // the empty-bin candidate has post_residual == bin_capacity - item_size,
    // which is large, so add a penalty proportional to wasted open-bin potential.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
    }

    // Late-stream consolidation: as the stream progresses, favor filling
    // existing bins tighter to avoid straggler bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize large dead space more than linearly.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // small leftover often reusable
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 3.0; // awkward mid-range dead space
    } else if post_residual > 60 {
        score += 6.0; // huge leftover means poor fit here
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if next_item_size as f64 > post_residual as f64
            && next_item_size as f64 <= bin_residual as f64
        {
            // next item fits only before placement -> mild penalty
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when current bins are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened when existing bins are fragmented
        // or when item is large relative to residual of typical open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 - 8.0 * fragmentation - 6.0 * progress;
        if item_size >= 60 {
            score -= 5.0; // big items are fine in fresh bins
        }
    }

    // Slight preference to keep mean residual balanced: avoid bins far below mean.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Late in the stream, consolidate aggressively into open bins.
    if step_index as f64 > 0.8 * total_items as f64 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let x = r / cap; // normalized post residual
    let p = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic in normalized post-residual, progress-coupled
    let mut score = r as f64;

    // Smooth non-linear coupling: tight fits rewarded more as stream progresses
    let tight = (1.0 - x) * (1.0 - x); // 0 = perfect fit, 1 = empty
    score -= 40.0 * tight * (0.5 + p);

    // Penalize mid-range dead space with cubic term (unusable residuals)
    let dead = x * (1.0 - x) * (x - 0.5);
    score += 25.0 * dead * (1.0 - p);

    // Last-chance bonus: smooth in fitting_bins_count
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 30.0 * last_chance * tight;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let fits_next = if (r as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = (r as f64 - next_item_size as f64) / cap;
        score -= 15.0 * fits_next * (1.0 - gap.abs()) * (0.3 + 0.7 * p);
    }

    // Crowding pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + x) * 4.0;

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 0.15 * (r - mean_residual).abs();

    // New-bin candidate penalty: opening a bin should only win for large items
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += 20.0 + 30.0 * (1.0 - item_size as f64 / cap) * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    let mut score = post;

    // Harmonic class of post_residual: dead space divisible into useful chunks is less bad.
    // Class A: post_residual <= 10 -> near-perfect fit, strong reward.
    // Class B: post_residual in (10,20] -> still usable for smallest items.
    // Class C: post_residual in (20,35] -> moderate dead space.
    // Class D: post_residual > 35 -> wasteful.
    if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 35 {
        score += 6.0;
    } else {
        score += 14.0;
    }

    // Modulo arithmetic: post_residual that is a multiple of 5 or 10 aligns with
    // typical item-size granularity, making leftovers reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Integer-division threshold: leftover floor(post/10) small chunks are good.
    let chunk_usability = (post_residual / 10) as f64;
    score -= chunk_usability.min(3.0) * 2.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Extra reward if next item nearly fills the bin exactly.
        let next_left = post_residual - next_item_size as f64;
        if next_left <= 10.0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Penalize if the next item cannot use this leftover.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when it creates a good
    // future structure and existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a new bin early in the stream (more future items to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many open bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If mean residual of open bins is large, they can absorb the item; penalize new bin.
        score += (mean_residual / cap).clamp(0.0, 1.0) * 15.0;
        // If the next item is large, a fresh bin with full capacity is valuable.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Slight preference for tighter (fuller) bins in general.
    score += (1.0 - (bin_residual as f64) / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible item (min size 1, but practically small gaps < ~15) are
    // "dead space". Penalize them quadratically.
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 1.5;
    } else {
        // Prefer filling bins tightly: reward small-but-usable post residuals.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.05;
    }

    // Reward leaving a gap that exactly fits the lookahead item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }
    // Penalize if the leftover cannot host the next item but is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // (especially the emptiest that still fits well); discourage new bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate.
        score += 5.0 + open_pressure * 0.8;
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= open_pressure * 0.15;
    }

    // Prefer bins whose residual is below the mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Late in the stream, avoid creating tiny unusable gaps even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64).min(dead_threshold) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // Reward exact/near-exact chaining
            score -= 30.0 * (1.0 - (leftover_after_next as f64 / bin_capacity as f64));
            // Penalize if leftover after next item becomes dead space (< 10)
            if leftover_after_next < 10 {
                score += 8.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and could reasonably fit
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && next_item_size > 0 {
            // Opening a new bin is only attractive if item is large and fit is poor elsewhere
            score += 12.0 + 0.2 * (bin_capacity - item_size) as f64;
            // If next item is small, a fresh bin wastes potential
            if next_item_size < 30 {
                score += 10.0;
            }
        }
        // Late in the stream, avoid opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Small bonus for many open bins being consolidated (reduce bin count growth)
    score += 0.3 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness * tightness);

    // Penalize large post_residual nonlinearly (unusable gap).
    if post_residual > 0 {
        score += 0.05 * (post_residual as f64).powf(1.3);
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits into the resulting residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Waste if residual can't hold the next item but is large.
            score += 0.1 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless it's the only option or residual
    // of open bins is fragmented (high mean residual spread vs item).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If mean residual across open bins is high, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    }

    // Mildly prefer bins with below-average residual (consolidate waste).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted post residual, softly (quadratic in normalized waste)
    let norm_waste = pr / cap;
    let mut score = pr as f64 * (1.0 + norm_waste * norm_waste);

    // Non-linear coupling of waste with stream progress:
    // late in the stream, tight fits (small post_residual) matter more;
    // early on, larger residuals are acceptable (future items can fill them).
    let progress_coupling = 1.0 + progress * (1.0 - progress) * 4.0; // peaks at 2.0 mid-stream
    score *= progress_coupling;

    // Smooth polynomial reward for near-perfect fits: post_residual near zero
    let tightness = 1.0 - norm_waste;
    score -= tightness * tightness * tightness * cap * 0.5;

    // Penalize bins whose residual is far from mean residual (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + progress);
    }

    // Lookahead: reward leaving space compatible with next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = gap / cap;
        // smooth penalty: post_residual close to next item size is valuable
        score += gap_norm * gap_norm * cap * 0.6;
        // extra reward if next item fits exactly into post residual
        if pr >= nx {
            score -= (1.0 - gap_norm) * 8.0;
        }
    }

    // Mild penalty for opening a new bin when many bins are open and could fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += cap * (0.4 + 0.6 * progress) + it * 0.5;
    }

    // Slight preference to fill emptier bins first (balance load)
    score -= (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and modulo 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: small nonzero residues are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Residue classes that pair well with common item sizes get a bonus
    score -= match r10 {
        0 => 12.0,
        5 => 8.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,
    };
    // Modulo 25 classes: perfect quarter fills are valuable
    if r25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: does next_item_size divide into post_residual harmonically?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            let q = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            // next item fits exactly: strong reward
            if rem == 0 {
                score -= 25.0 + 5.0 * q as f64;
            } else {
                // partial fit: mild reward scaled by fill fraction
                score -= 8.0 * (next_item_size as f64 / post_residual as f64);
            }
            // integer-division threshold: if next item leaves residue < 10, penalize
            let post2 = post_residual - next_item_size;
            if post2 > 0 && post2 < 10 {
                score += 15.0;
            }
        } else {
            // next item cannot use this bin's residual: penalize slightly
            score += 5.0;
        }
        // harmonic class match between item and next item (same decade)
        if next_item_size / 10 == item_size / 10 {
            score -= 3.0;
        }
        let _ = nx;
    }

    // Tight fit reward: fill fraction of the bin
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets a baseline cost
    if bin_residual == bin_capacity {
        score = cap * (1.0 - fill) + 55.0
            - if next_item_size > 0 && next_item_size <= bin_capacity && bin_capacity % next_item_size.max(1) <= 10 { 10.0 } else { 0.0 };
    }

    // Stream progression: early on, be conservative about perfect-fit bonuses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (r10 == 0) as i32 as f64;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.15 * (mean_residual - post_residual as f64).abs() * (post_residual as f64 > mean_residual) as i32 as f64;

    // Open bins count: discourage bin proliferation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item would leave a large,
    // reusable gap in existing bins or bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 15.0 - 2.0 * pressure;
        if post_residual >= 20 {
            score += 10.0;
        }
        if fitting_bins_count == 1 {
            score += 45.0; // never open a bin when a last-chance bin exists
        }
    }

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // dead space relative to lookahead
    }

    // Mild preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far below mean residual (keeps residuals balanced).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (base score already does this).

    // 2-step lookahead: reward exact match of post_residual with next item size,
    // penalize post_residual that is too small to hold the next item (dead space).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can fit here afterwards: reward closeness to exact match.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize dead space.
            score += 6.0 + 0.35 * diff;
        }
        // Extra bonus for perfect two-item fill (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Penalize bins far from the mean residual (outliers tend to become dead space).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the fullest (smallest post_residual) more aggressively.
        score += 0.05 * (fitting_bins_count as f64);
    }

    // New-bin candidate handling: make an empty bin moderately attractive only when
    // no open bin fits well (large post_residual means bad fit).
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish, penalized slightly so we prefer reusing bins,
        // but the lookahead penalty on bad-fit bins can override this.
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Opening a fresh bin allows a clean two-item packing.
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly favor bins whose post-residual is small
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tight * tight;

    // Penalize unusable dead space: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin so that
    // reasonable fits into existing bins win, but allow it when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * progress;
        // If many bins are open and mean residual is fragmented, opening fresh is fine
        score -= 0.05 * open_bins_count as f64;
        // If mean residual is large (plenty of slack), discourage new bins
        score += 0.1 * mean_residual;
        // Perfect fit of the item into a fresh bin (item near capacity) is attractive
        if item_size >= 90 { score -= 40.0; }
    } else {
        // Reward using bins that are already partially filled (reduces bin count pressure)
        score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Late-stream consolidation: prefer filling existing bins as the stream ends
    score -= 8.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress + 0.4 * progress);

    // Reward tight fits (low post_residual) more strongly as stream matures.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (1.5 + 2.0 * progress);

    // Penalize dead space that is too small to plausibly fit future items.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) / cap * (1.0 + 2.0 * progress);
        } else {
            // Reward bins whose residual still accommodates the lookahead item.
            score -= 0.5 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless existing residuals are all badly fragmented.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 2.5 - 1.5 * fragmentation * (1.0 + progress);
    }

    // Mild preference for bins deviating from the mean residual (consolidation).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Harmonic class of post_residual: classify dead space into residue classes.
    // Classes divisible by common item sizes (10, 20, 25, 50) are reusable; odd/prime-ish gaps are dead.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fill
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -14.0
    } else if pr % 20 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -9.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward odd gap: dead space penalty
    };
    score += class_bonus;

    // Integer-division threshold bands on post_residual.
    let band = pr / 10; // 0..10
    score += match band {
        0 => -8.0,               // 0..9: nearly full
        1 => -3.0,               // 10..19: fits smallest items
        2 => 2.0,                // 20..29
        3 => 4.0,
        4 => 6.0,
        _ => 8.0,                // large leftover: wasteful unless reusable class
    };

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits but not perfectly; check modulo harmony
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize less if post_residual is reusable class
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it only wins
    // when open bins have bad scores (large dead-space penalties).
    if bin_residual == bin_capacity {
        score += 14.0;
        // If stream is early or many bins open, slightly discourage proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - progress);
    }

    // Spread-awareness: prefer bins below mean residual when mean is high (rebalance).
    let resid_f = bin_residual as f64;
    if open_bins_count > 1 {
        let diff = resid_f - mean_residual;
        score += 0.05 * diff;
    }

    // Small item into large residual is wasteful unless it harmonizes.
    if item_size < 20 && bin_residual > 70 && pr % 10 != 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny gap: pure dead space
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        } else {
            score -= 6.0; // large residual may still fit future items
        }
    } else {
        score -= 40.0; // perfect closure is excellent
    }

    // Tight fit reward: fraction of residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score += 0.8 * pressure * (1.0 - fit_ratio);

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (gap slightly too small), mild penalty.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += desperation + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
