pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that cannot fit the average item.
    if (post_residual as f64) < mean_residual {
        score += 6.0 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size {
            // Next item would fit here only if current item goes elsewhere: mild penalty.
            score += 4.0;
        }
        // Exact chain fit reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 14.0 * (1.0 - 0.5 * progress);
        // If no open bin fits, opening a new bin is necessary: reduce cost.
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        // Lookahead: an empty bin can host both current and next item.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    // Prefer placing into bins with below-average residual (balance consolidation).
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Non-linear coupling of post-residual with stream progress:
    // early on, waste matters less; late in the stream, penalize dead space more
    let progress_coupling = pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 20.0 * progress_coupling;

    // Reward tight fits via smooth term (post_residual near zero)
    score -= 15.0 * (1.0 - pr_norm).powi(3) * (1.0 - progress);

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr_norm);
    } else if next_item_size > 0 {
        // next item cannot follow here: mild penalty scaled by leftover
        score += 4.0 * pr_norm * progress;
    }

    // Spread across open bins: encourage balancing when many bins open
    let deviation = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * deviation * deviation * (1.0 - progress);

    // New-bin candidate: keep it attractive early, discourage late
    if bin_residual == bin_capacity {
        score += 10.0 * progress - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual is a multiple of 25 (perfect harmonic slot: 25/50/75/0)
    // Class 1: multiple of 10 (decimal harmonic)
    // Class 2: multiple of 20
    let harmonic_bonus = if post_residual % 25 == 0 {
        18.0
    } else if post_residual % 20 == 0 {
        12.0
    } else if post_residual % 10 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division dead-space class: leftover in the smallest "common slot" band.
    // If post_residual < 10 it is nearly dead space -> heavy penalty.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Lookahead coupling: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fit_ratio; // good chaining
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely bad fits among open bins cause opening a new bin.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - 15 {
            score -= 10.0; // big next item: fresh bin useful
        }
        return score;
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.9 {
        score -= 22.0;
    } else if fill > 0.7 {
        score -= 10.0;
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual divergence: bins far below mean residual are "odd" bins;
    // prefer placing into them to balance.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual in (0, 10) is essentially dead space (min item size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gap only usable by very small items: moderate penalty scaled by gap smallness.
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is well-matched to the item (tight packing).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Open-bins pressure: penalize placements that keep many bins open,
    // but relax pressure late in the stream when consolidation matters less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 - progress);

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when the item is large
    // relative to mean residual (poor fits everywhere) or when next item is big.
    if bin_residual == bin_capacity {
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        if mean_fit < 0.6 {
            // Existing bins fit reasonably well; discourage opening a new bin.
            score += 40.0;
        } else {
            // Poor fits elsewhere: make new bin attractive.
            score -= 35.0;
        }
        // If lookahead item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // If the next item is large and this bin's post_residual cannot hold it,
        // slight penalty for consuming residual that could serve the next item.
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to overshoot.
        let over = (next_item_size - post_residual) as f64;
        score += 0.5 * over;
    }

    // Penalize dead space that no plausible item (>=1) can ever use well:
    // very small post-residuals are good (tight fit), mid residuals are bad.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 25.0; // nearly perfect packing
    } else if pr >= 10.0 && pr <= 30.0 {
        score += 10.0; // awkward dead zone
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - pr);

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If lookahead item won't fit any open residual well anyway, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 30.0;
        }
    }

    // Late in the stream: consolidate harder to avoid leftover bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.25 * next_item_size as f64;
        } else {
            score += 8.0;
        }
        // If next item is huge, prefer bins where it can also fit after placement.
        if next_item_size >= 60 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Time horizon: early in stream, be conservative (prefer good fits);
    // late in stream, consolidate to avoid opening extra bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tight;

    // Many open bins: encourage filling existing ones rather than opening new.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residual below mean (fill emptier-wasted space first),
    // i.e., larger residual bins get penalized slightly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Empty new-bin candidate: penalize unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let waste_here = poor_fit - (poor_fit.min(15.0));
        score += 30.0 - 0.3 * waste_here;
        // Opening a new bin is fine early or when item is small relative to residual pattern.
        if item_size >= 50 && progress < 0.5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer large post_residual waste less; late stream: penalize small residuals (dead space).
    let early = (1.0 - progress).powi(2);
    let late = progress.powi(2);

    // Quadratic dead-space penalty growing with progress
    score += late * pr_norm * pr_norm * cap * 0.5;

    // Early phase: mild cubic reward for tight fits (small post_residual)
    score -= early * (1.0 - pr_norm).powi(3) * 8.0;

    // Interaction: residual vs mean residual deviation, scaled by progress
    let dev = pr - mean_residual;
    score += progress * dev * 0.15;

    // Last-chance bin: smooth sigmoid-like boost via fitting_bins_count
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead coupling: penalize if next item could use the post residual well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let waste = if pr >= nxt { pr - nxt } else { 0.0 };
        // reward leaving room for next item with small leftover
        score -= fit_next * (1.0 - waste / cap) * 5.0 * (0.5 + 0.5 * progress);
        // penalize leaving a sliver that next item cannot use
        score += (1.0 - fit_next) * pr_norm * 10.0;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.1;

    // Slight bias against opening new bins mid-stream, smoothed
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: classify leftover space by
    // integer-division thresholds (dead-space bands).
    let c = bin_capacity as u32;
    let class = post_residual / (c / 5).max(1); // 5 harmonic bands
    score += class as f64 * 7.0;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Reward filling the majority of the bin.
    score -= fill * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item can use the post_residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chaining
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here: leftover may become dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Modulo arithmetic on post_residual: values divisible by common
    // small sizes (10, 20, 25) are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Penalize new-bin candidate unless few alternatives or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (fitting_bins_count == 0) as i32 as f64 * 40.0;
        score += 55.0 - pressure - progress * 10.0 + mean_residual * 0.1;
    }

    // Slight preference to keep bins balanced when many are open.
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: residuals in (0, 10] are nearly unusable
    // since item sizes are >= 1 but small gaps rarely match future demand.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0;
    } else if post_residual <= 20 {
        // Moderately tight gaps: mild penalty to prefer larger leftover space.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): apply pressure so a new
    // bin is only opened when it clearly avoids creating dead space elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0 + 1.5 * open_bins_count as f64;
    }

    // Open-bins pressure: mildly discourage scattering across many bins.
    score += 0.3 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would no longer fit here after this placement; slight penalty.
        score += 8.0;
    }

    // Late in the stream: tighten packing, discourage new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: low post_residual is good, but only if usable.
    if post_residual == 0 {
        score -= 500.0; // perfect fit, close bin
    } else if post_residual < 10 {
        score -= 150.0; // near-perfect fit, dead space is tiny
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size exactly (chained fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 400.0; // next item will fill this bin perfectly
        } else if diff <= 5 {
            score -= 200.0;
        } else if diff <= 15 {
            score -= 80.0;
        } else {
            // Penalize residuals that can't host the next item at all
            if post_residual < next_item_size {
                score += 60.0;
            }
        }
        // If post_residual can hold next item but is much larger, mild penalty
        // to avoid hoarding space when a tighter bin exists.
        if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.5;
        }
    } else {
        // Last item: prefer minimizing leftover as much as possible.
        score += post_residual as f64 * 2.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tight;
    // filling them is generally good unless it creates dead space.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
        if post_residual < 10 {
            score -= 80.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good (small, usable) residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 90.0;
        // Large items (relative to capacity) benefit from a fresh bin.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 70.0;
        }
        // If existing bins are very fragmented (low mean residual), fresh bin
        // becomes more attractive.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // If next item is large, a fresh bin can host both current and next.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Slight preference for tighter existing bins overall.
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 0.9 * (item_size as f64);

    // Penalize dead space: small post_residual that cannot host any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // useless sliver
    } else if post_residual >= 10 {
        // bonus proportional to usability of remaining space
        score -= (post_residual as f64 / 100.0) * 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.3 * (next_item_size as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage closing them out (favor bins with small residual).
    if open_bins_count > 4 {
        score += 0.25 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    // Global residual coupling: prefer bins below mean residual (tighter than average).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more willing to open fresh bins for good structure;
    // late in stream, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when item is large and few bins fit it
        let large = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large && fitting_bins_count <= 2 {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 15.0 + 30.0 * progress;
        }
    } else if progress > 0.7 {
        score -= 10.0 * progress; // pack tightly near the end
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress + 0.4 * progress);

    // Penalize residual that is too small to be useful (dead space), smoothly.
    let dead = (1.0 - pr).clamp(0.0, 1.0);
    score += 12.0 * dead * dead * dead;

    // Reward tight fits smoothly (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Last-chance bin: reward smoothly as fitting bins become scarce.
    if fitting_bins_count <= 1 {
        score -= 8.0;
    } else {
        score -= 4.0 / (fitting_bins_count as f64);
    }

    // Lookahead: bonus if next item fits the post residual, smooth decay otherwise.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (-gap / cap);
        }
    } else {
        // Last item: prefer tightest packing.
        score += 0.0;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post);

    // New-bin candidate: neutral-ish baseline with progress-aware penalty.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are golden.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Dead-space penalty grows superlinearly for awkward residual classes.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.1 {
        score += 30.0; // unusable sliver
    }

    // Reward tight fits (small post_residual relative to item).
    score -= 0.5 * (item_size as f64);

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= 0.3 * (next_item_size as f64);
        } else {
            score += 15.0; // next item won't fit here; bin likely closed anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening unless current fit is terrible
    // and next item is large (needs fresh space).
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 40 && next_item_size > post_residual;
        if bad_fit {
            score -= 40.0;
        } else {
            score += 90.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Prefer filling bins with large residuals when mean residual is high (fragmentation pressure).
    score -= 0.05 * mean_residual * (bin_residual as f64 / cap);

    // Modulo-10 harmonic bonus: residuals divisible by 10 pair better with typical sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual below the minimum item size (1..100 unknown, assume ~10) is pure waste.
    if post_residual > 0 {
        // Dead-space penalty grows steeply for tiny residuals.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 25.0 * (20.0 - post_residual as f64) / 10.0;
        }

        // If the gap cannot fit the lookahead item either, it is likely dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: lower post_residual relative to capacity.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by how many bins are already open
        // and how large the item is (small items should go into existing bins).
        score += 45.0 + 3.0 * open_bins_count as f64;
        if item_size <= 30 {
            score += 25.0; // small items should almost never open a bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Favor bins below the mean residual (i.e., filling fuller bins first),
    // which keeps large residuals available for large future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 25.0 / (1.0 + gap);
        if post_residual as i64 == next_item_size as i64 {
            score -= 35.0; // exact two-item completion
        }
        // Penalize post_residual too small to ever be useful.
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (compact bins), unless it's the last chance to use this bin.
    let rel = (bin_residual as f64 - mean_residual) / (mean_residual.max(1.0));
    score += 8.0 * rel.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).sqrt();

    // New-bin candidate: make it unattractive unless open bins are very full/fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively when many bins compete.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 60.0;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that blocks the next item: penalize more when this bin was a rare fit.
        score += 5.0 + (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins already have plenty of room.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1 + (open_bins_count as f64) * 0.5;
    }

    // Prefer filling bins with larger residuals early; late in the stream, prefer exactness.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - item_size as f64) * (0.1 - 0.15 * progress);

    // Mild bonus for aligning with mean residual (balance load across bins).
    score -= ((bin_residual as f64) - mean_residual).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 30.0 * poly;

    // Dead-space penalty: small post-residual that can't fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 12.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Reward tight fits, more so late in the stream
    score -= 8.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Prefer fuller bins relative to mean residual
    score -= (mean_residual - pr) * 0.05;

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=10, 21..=30, etc.) are good sinks.
    let q = post_residual / 10; // coarse harmonic bucket (0..=10)
    let r = post_residual % 10;
    score += (q as f64) * 2.0;      // prefer smaller coarse buckets
    score -= (r as f64) * 0.25;     // tiny reward for near-bucket-boundary fit

    // Perfect or near-perfect fill is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead space: leftover that likely cannot host future items (typical sizes 10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 10.0;
            if rem2 <= 5 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally to overshoot class
            score += ((next_item_size - post_residual) / 20) as f64 * 5.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are large
    // (i.e., current bins are poor fits) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_open = (mean_residual - item_size as f64).max(0.0);
        let bias = 30.0 + poor_open * 0.5 - progress * 10.0;
        score += bias;
        if open_bins_count == 0 {
            score -= 100.0; // must place somewhere
        }
    }

    // Mild global pressure: many open bins -> tighten packing (favor tight fits more).
    score -= (open_bins_count as f64).sqrt() * (bin_capacity - post_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong discount.
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64) * 4.0;
    } else {
        // Perfect fit: massive reward.
        score -= 500.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item
    // (assume items >= 1, but small gaps < 10 are rarely usable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard penalty for creating tiny dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // mild penalty for marginal gaps
    }

    // If the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 300.0; // chains a perfect follow-up fit
        } else if slack < 10 {
            score += 10.0; // follow-up would create dead space
        } else {
            score -= 20.0; // next item still fits reasonably
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate handling: an empty bin has high post_residual, but we
    // adjust so it's chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins already fit.
        score += 30.0 + 25.0 * fitting_bins_count as f64;
        // Late in the stream, opening new bins is more wasteful.
        score += 40.0 * progress;
        // If mean residual of open bins is large, prefer reusing them.
        score += mean_residual * 0.3;
    } else {
        // Favor bins whose residual is close to the item (good utilization).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 30.0;
    }

    // Mild tie-break: prefer bins with lower residual overall (denser bins).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward small leftover after the chain.
            let chain_left = post_residual - next_item_size;
            score -= 120.0 - (chain_left as f64) * 3.0;
        } else {
            // Next item won't fit here: penalize dead space proportionally.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Prefer bins with residuals below the mean (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless residuals are large (waste management phase).
    if bin_residual == bin_capacity {
        let avg_open_waste = mean_residual;
        if avg_open_waste > item_size as f64 * 1.2 {
            score += 60.0; // there's room elsewhere; discourage new bin
        } else {
            score -= 20.0; // open bins are tight; new bin is fine
        }
    }

    // Mild early-stream preference for consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(60) {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 15.0 + 3.0 * crowd;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large item may deserve fresh space
        }
    }

    // Time horizon: early in the stream, be conservative about filling bins; late, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual far from mean (avoid fragmenting average bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for bins that can still accept a mid-size item later.
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let tight = (pr as f64 / cap).powi(2);

    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space is penalized more aggressively (quartic growth).
    score += 40.0 * tight * (progress * progress * (3.0 - 2.0 * progress));

    // Reward tight fits, more so late in the stream (smooth cubic coupling).
    score -= 12.0 * fill * fill * (0.5 + progress);

    // Last-chance bin: strong smooth bonus decaying with progress.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress) * (1.0 - progress) + 8.0;
    }

    // Lookahead: if next item fits in the post residual, reward (smoothly scaled).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 10.0 * (ns / cap) * (1.0 + progress);
        } else {
            score += 6.0 * (ns / cap) * progress;
        }
    }

    // Penalize bins far from mean residual (fragmentation pressure), quadratic.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild penalty for many open bins to discourage sprawl.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    // modulo 10 (typical item granularity) and treat "perfect / near-perfect" fits specially.
    let pr = post_residual;
    let class = pr % 10;

    // Perfect fit or dead-space-free leftover: strong reward.
    if pr == 0 {
        score -= 60.0;
    } else if class == 0 {
        // Leftover is a multiple of 10 -> likely reusable by future items.
        score -= 25.0;
    } else if class <= 3 {
        // Small awkward remainder -> dead space risk, penalize.
        score += 18.0;
    } else if class >= 7 {
        // Large-ish remainder in class 7..9 still leaves a chunk usable.
        score += 5.0;
    }

    // Fractional capacity coupling: leftover as fraction of capacity.
    let frac = pr as f64 / cap;
    if frac < 0.05 {
        score += 10.0; // tiny sliver, nearly dead
    } else if frac > 0.4 {
        score -= 8.0; // plenty of room left, bin stays flexible
    }

    // Lookahead: can next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly or snugly: reward harmonic alignment.
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap <= 5 {
                score -= 20.0;
            } else {
                score -= gap as f64 * 0.3;
            }
        } else {
            // Next item won't fit here; if post-residual is small it's stranded.
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit or open bins are very full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // If mean residual across open bins is small, opening is reasonable.
        score -= (mean_residual / cap) * 30.0;
        // Late in the stream, avoid opening bins for marginal gain.
        score += progress * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item is larger: a fresh bin may serve it well.
            score -= 12.0;
        }
    }

    // Mild preference for tighter existing bins relative to mean residual.
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to fit any plausible item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // risky small gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // Usable gap: mild quadratic penalty to prefer tighter fits
        score += 0.05 * (post_residual as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward exact or near-exact fits strongly
    if post_residual <= 2 {
        score -= 30.0;
    }

    // Last chance: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But allow new bin when existing residuals are all poor fits
        if (post_residual as f64) < mean_residual * 0.5 {
            score -= 15.0;
        }
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits snugly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space for the known next item
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins already tighter than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to mean residual (waste beyond typical slack).
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
