    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Tight fits are good: small post_residual is already the base score.
    // Bonus for near-perfect single-item fill.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

