    }

    // Perfect or near-perfect fits get a big reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), smoothly scaled.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, small residuals are less valuable; late, they matter more.
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= t * (pr * pr) / cap;

    // Reward tight fits more strongly as progress advances (cubic coupling).
    let tightness = 1.0 - pr / cap;
    score -= 10.0 * t * tightness * tightness * tightness * fit_ratio;

    // Penalize leaving residuals that are too small to be useful later,
    // with a smooth quadratic bump around mid-residuals.
    let mid = cap * 0.5;
    let dev = (pr - mid) / cap;
    score -= 5.0 * (1.0 - dev * dev) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * t;
    }

    // Mild penalty for spreading across too many bins relative to stream progress.
    score += (open_bins_count as f64) * 0.3 * (1.0 - t);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Prefer bins whose residual deviates from the mean (consolidation),
    // smoothly interpolated over the stream.
    score += 0.5 * (pr - mean_residual).abs() * (1.0 - t);

    // New-bin candidate: penalize opening a bin unless the item is large
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * fit_ratio - 6.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = post_residual % quarter;

    // Reward residual classes that are "harmonically useful": near 0 (perfect fit)
    // is best; residual in (0, quarter) is dead space; residual near half is reusable.
    if post_residual == 0 {
        score -= 500.0; // perfect packing
    } else if post_residual <= quarter / 2 {
        score += 40.0; // tiny dead space, hard to reuse
    } else if post_residual <= quarter {
        score += 15.0;
    } else if post_residual <= half {
        score -= 30.0; // half-bin residual is highly reusable
    } else {
        score -= 10.0; // large residual, still flexible
    }

    // Modulo-10 class coupling: residuals divisible by 10 pair well with
    // typical item sizes (1..100 stream, often multiples of 10)
    if post_residual % 10 == 0 {
        score -= 20.0;
    }
    if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible
            let chain_waste = post_residual - next_item_size;
            score -= 60.0 - (chain_waste as f64).min(50.0);
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // Next item fits the bin but only if we DON'T take a bigger bite now
            score += 25.0;
        }
        // Integer-division threshold: if post_residual / next_item_size >= 2,
        // this bin can host two future-class items
        if next_item_size > 0 && post_residual / next_item_size.max(1) >= 2 {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize spreading when many bins are open and mean residual is low
    // (fragmentation regime): prefer tight fits
    let frag = (open_bins_count as f64).ln() * (100.0 - mean_residual).max(0.0) / 20.0;
    score += frag * (post_residual as f64 / bin_capacity as f64);

    // Progress-based modulation: late in stream, prioritize closing bins (perfect fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 100.0 * progress;
    } else if post_residual < quarter {
        score += 30.0 * progress; // late-stage small residuals are worthless
    }

    // New-bin candidate handling: empty bin gets a moderate default score so
    // it is only chosen when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score = 60.0 + (item_size as f64) * 0.2 - 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
        return score;
    }

    // Mild tie-breaker toward tighter fits overall
    score += (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: penalize unusable tiny gaps (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize medium dead space that next item likely cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward bins whose leftover can host the lookahead item.
        score -= 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and progress.
        score += 15.0 + open_bins_count as f64 * 2.5 + progress * 20.0;
    } else {
        // Mild reward for filling already-open bins tightly.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Tie-break toward bins below mean residual (consolidating space).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // 2-step lookahead: strongly reward bins where the next item fits exactly
    // into the post residual (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // next item fits, but leaves more dead space; mild reward scaled
            // by how well the chain continues.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.4 * slack;
        } else {
            // next item cannot follow: penalize proportional to overshoot.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    }

    // Penalize leaving dead space that no item of size >= 10 could use.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Compare residual against mean residual: prefer using bins with
    // above-average residual (keep tight bins free for better fits).
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is
    // terrible or the stream is early (building a diverse pool is fine early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 40.0;
        if fitting_bins_count > 0 && !poor_fit {
            score += 60.0 - 30.0 * progress;
        }
    }

    // Slight preference to consolidate into fewer bins late in the stream.
    score += 2.0 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
