pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    score += 0.35 * pr * t * t;
    score -= 0.15 * pr * (1.0 - t);

    // Penalize large dead space relative to capacity, amplified late in stream
    let dead_frac = pr / cap;
    score += 12.0 * dead_frac * dead_frac * (0.5 + t);

    // Reward tight fits (small post_residual) with smooth quadratic bonus
    score -= 8.0 * (1.0 - dead_frac) * (1.0 - dead_frac) * 0.05;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 4.0 * t;
    }

    // Lookahead: penalize if next item won't fit in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 2.0 + 3.0 * (nxt - pr) / cap;
        } else {
            score -= 1.5 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Mild pressure to prefer fuller bins among many open bins
    score += 0.02 * open_bins_count as f64 * dead_frac;

    // New-bin candidate: prefer opening fresh bin only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (pr - item_size as f64) / cap;
        score += 4.0 - 3.0 * (1.0 - t);
        score += 5.0 * (1.0 - poor_fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that form "usable" pairing classes
    // (small gaps 1..=10 are dead space; large gaps are still useful).
    let dead_zone = (post_residual <= 10) as i32 as f64;
    score += dead_zone * 25.0;

    // Harmonic classes via modulo: gaps congruent to small residues mod common
    // item sizes (e.g. 10/20/25/50) are more likely to be filled later.
    let r10 = (post_residual % 10) as f64;
    let r25 = (post_residual % 25) as f64;
    score += 0.4 * r10 + 0.2 * r25;

    // Integer-division thresholds: post_residual in [25,50) or [50,75) or [75,100)
    // indicate how many half-capacity items could still pair.
    let half_class = (post_residual / 25) as f64;
    score -= 3.0 * half_class;

    // Tight fit reward: exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    if fitting_bins_count == 0 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin offers a good fit. New bin residual == capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size >= 60) as i32 as f64;
        // Prefer new bin for large items late in stream; otherwise discourage.
        score += 30.0 - large_item * 35.0 - 15.0 * progress;
        // If next item is large too, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below mean residual = tighter bin, place here).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: tiny positive gaps that no future item (1..=100) can exploit well.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead gap: nothing smaller than 10 can ever fit
        } else if post_residual < 20 {
            score += 18.0; // very tight gap, few item sizes fit
        } else if post_residual < 35 {
            score += 6.0;  // moderately awkward gap
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward using a bin whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so bias against it
    // unless it is truly needed (few fitting bins or huge item).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0;
        let last_chance_bonus = if fitting_bins_count <= 1 { 0.0 } else { 25.0 };
        let big_item_bonus = if item_size >= bin_capacity / 2 { 0.0 } else { 15.0 };
        score += pressure + last_chance_bonus + big_item_bonus;
    }

    // Last-chance bin: strongly favor filling the only bin that fits,
    // avoiding proliferation of partially filled bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0; // sets up a perfect fit for the next item
        } else if gap < 10 {
            score += 10.0; // leaves a dead gap for the next item
        }
    }

    // Mild preference for fuller bins relative to the fleet mean residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Slight late-stream tightening: as the stream progresses, prefer exact fills more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64) * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        // exact 2-step chain completion
        if gap == 0.0 {
            score -= 800.0;
        } else {
            // prefer small leftover after the lookahead placement
            score -= 200.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize dead space proportionally
        score += 0.5 * post_residual as f64;
        // extra penalty if leftover is small-but-unusable (worst dead space)
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Discourage spreading across too many open bins late in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 120.0 + 200.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 50.0; // fresh bin guarantees fit for next item
        }
    } else {
        score += 0.1 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: post residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins when mean residual is large.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Slight preference for fuller bins over emptier ones.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill;

    // New-bin candidate: neutral-to-slightly-penalized so it's chosen only
    // when all open bins fit poorly (large post_residual relative to others).
    if bin_residual == bin_capacity {
        score += 10.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Time-horizon modulation: early on, be conservative (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, dead space matters more
    let p2 = progress * progress;
    score += 25.0 * norm_pr * p2;

    // Reward tight fits (small post residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: bonus if next item fits into post residual (chain packing)
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            // penalize leaving residual that nothing typical can use
            let gap = pr - (next_item_size as f64);
            score += 0.3 * gap * (1.0 - progress);
        }
    }

    // Mean residual context: penalize bins far from mean residual (outliers)
    score += 0.15 * ((pr - mean_residual).abs());

    // Prefer filling already-open bins over opening new ones, more so as bins accumulate
    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small sizes are reusable.
    let cap_frac = (post_residual as f64) / (bin_capacity as f64);
    let q = post_residual / 10; // integer-division class (sizes are multiples of 10 typically)
    let r = post_residual % 10;
    score += r as f64 * 0.8; // penalize non-aligned residues (dead space)

    // Reward small post_residual (tight fit) nonlinearly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, more if it fills well
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 20.0 * next_fill;
        } else {
            score += 6.0; // next item won't fit here; mildly penalize
        }
        // Harmonic pairing: next_item_size divides post_residual exactly
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New-bin candidate handling: neutral baseline, slightly higher than decent fits
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.62; // ~62; good tight fits score below this
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // if next item is large, opening fresh bin is more attractive
            let prog = step_index as f64 / (total_items.max(1) as f64);
            score -= 8.0 * prog * (next_item_size as f64 / bin_capacity as f64);
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
        return score;
    }

    // Fraction-of-capacity harmonic thresholds on post_residual
    if cap_frac > 0.0 && cap_frac <= 0.1 {
        score -= 12.0;
    } else if cap_frac > 0.5 {
        score += 5.0 * cap_frac; // large leftover less attractive early
    }

    // Stream progression: late in stream, consolidate into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is below mean, it's a good squeeze
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Prefer reusing existing bins over opening many
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading items;
    // prefer tighter bins (smaller residual) via coupling with mean_residual.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.5 * pressure;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-costly unless open bins are tight.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Progression: later in the stream, be slightly more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if (post_residual as i64) >= next_item_size as i64 {
            // next item can also fit here: strong reward scaled by tightness.
            score -= 150.0 * (1.0 - gap / 100.0);
        } else {
            // next item cannot follow: penalize proportionally to the leftover gap.
            score += 30.0 + 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize the brand-new empty bin candidate, unless current fit is bad
    // and lookahead suggests a fresh bin is useful.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 40 && next_item_size > post_residual as u32;
        if bad_fit && next_item_size > 0 {
            score -= 60.0;
        } else {
            score += 80.0;
        }
    }

    // Late in the stream, tighten placements further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * (1.0 - progress) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible item (10..80) can ever use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 80 {
        // residual too large to matter much; mild penalty for waste
        score += 3.0;
    }

    // Lookahead: reward if next item fits exactly in the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(30.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= 8.0 * fill_frac * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, be pickier (avoid fragmenting bins);
    // late in stream, just pack greedily into anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.08 * post_residual as f64;

    // Global residual context: if mean residual is low, preserve large-residual bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 2.0 * (rel - 1.0).clamp(-1.5, 1.5);
    }

    // New-bin candidate: only attractive when it enables a perfect future fit
    // or current alternatives are terrible. Base cost of opening a bin:
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 12.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: favor small post_residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: post_residual quality weighted by stream progress
    // Early on, waste is cheap; late, tight packing matters more.
    let tightness_weight = 0.5 + 1.5 * progress * progress;
    score += tightness_weight * norm_pr * pr * 0.05;

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((pr - nx) / cap).max(0.0);
        score += 30.0 * unusable * unusable * (1.0 - progress);
        // Reward if next item fits exactly in post_residual
        let gap = (pr - nx).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual across open bins
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Smooth pressure term: many open bins -> prefer filling existing ones
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * open_pressure * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals near multiples of
    // common item sizes (10..80) are more reusable. Penalize residuals
    // that fall into "dead zones".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Dead-space penalty: residuals that are too small to be useful
    // (below the minimum plausible item size class) are worthless.
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Modulo harmony: residual divisible by small classes (10, 20, 25)
    // tends to admit future items exactly.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 25 == 0 { score -= 4.0; }
        if r % 20 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward a residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Perfect fit for the lookahead item: big reward
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys the ability to host the lookahead item
        // even though the bin could have held it.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate base cost so it
    // only wins when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If the item is huge, a fresh bin guarantees a clean fit.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Tight fit reward: near-exact fills are excellent.
    if post_residual <= 5 {
        score -= 12.0;
    }

    // Mild pressure toward bins with below-mean residual (compact fullness).
    score += 0.15 * (mean_residual - pr).max(0.0);

    // Scale by capacity fraction to keep magnitudes consistent.
    score * (0.5 + frac)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual > 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: favor bins whose leftover can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 20.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins tighter than the mean residual (better consolidation).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Mild bias toward new bins early vs late in the stream: late stream,
    // avoid opening new bins unless the fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 25.0 + 50.0 * progress; // new-bin candidate penalty grows over time
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect/near-perfect fits (dead space penalty).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 60.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match bonus for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize proportionally to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.6 * overflow;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 + 10.0 * progress;
    } else {
        // New-bin candidate: penalize mildly unless it promises a great 2-step fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly be reused by the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && post_residual > 0 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        } else if gap >= 0.0 {
            score -= 0.15 * gap;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 5.0 * (bin_residual as f64 - item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 + 0.05 * open_bins_count as f64;
    }

    // Prefer fuller bins among many open bins (best-fit-like pressure).
    score += 0.02 * (mean_residual - post_residual as f64);

    // Time-horizon coupling: early in the stream, be more willing to open
    // new bins (keep residuals large for future items); late in the stream,
    // pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        score -= 6.0 * (1.0 - progress);
        score += 4.0 * progress;
        // Opening a bin when none fit is inevitable; if no other bin fits,
        // this is fine (fitting_bins_count == 0 among open bins).
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        score -= 2.0 * progress;
    }

    // Slight penalty for spreading across too many open bins when residuals
    // are fragmented.
    if open_bins_count > 4 {
        score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * (40.0 + 120.0 * p2) * cap;
    score -= norm_pr * (30.0 + 60.0 * p3) * cap;
    score += (norm_pr - 0.5) * (norm_pr - 0.5) * 25.0 * (1.0 - p3);

    // Penalize dead space relative to mean residual across open bins.
    score += (pr - mean_residual) * (0.3 + 0.5 * p2);

    // Reward tight fits strongly as the stream progresses.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 80.0 * progress);

    // Last-chance bin bonus: strongly prefer when few fitting bins remain.
    if fitting_bins_count <= 1 {
        score -= 60.0 + 40.0 * progress;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 4.0;
    }

    // Lookahead: encourage leaving room for the next item, smoothly scaled.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 10.0 + (-gap / cap) * 30.0 * (0.5 + progress);
        }
    }

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += (open_bins_count as f64).powf(1.2) * (2.0 + 3.0 * p3);

    // Slight preference for new-bin candidate early vs late.
    if bin_residual == bin_capacity {
        score += 8.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // capacity-fraction buckets. Residuals in the "small dead space" classes
    // (< 10, i.e. below the minimum item size) are worthless -> penalize.
    let cap = bin_capacity as f64;
    if post_residual < 10 {
        // Dead space: nothing can ever use it.
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 34 {
        score += 6.0;
    } else if post_residual <= 50 {
        // Sweet spot: half-capacity residual, highly reusable.
        score -= 14.0;
    } else {
        // Large residual: fine, but not as good as a perfect half fill.
        score -= 4.0;
    }

    // Perfect fit reward (harmonic class 0).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo coupling: residuals that are multiples of common item sizes
    // (10, 20, 25, 40, 50) are more likely to be filled later.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead: strongly reward a bin that leaves exactly enough space for
    // the next item (chained packing), penalize leaving almost-but-not-quite.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 12.0;
            } else {
                score -= (20.0 / (1.0 + slack / 30.0)).min(12.0);
            }
        } else {
            // Next item won't fit here: leftover likely becomes dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += (waste / 10.0).min(15.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and few bins exist, or early in
    // the stream. Otherwise bias toward open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = (item_size as f64 / cap) > 0.6;
        let mut new_bin_bonus = -10.0;
        if big_item {
            new_bin_bonus -= 8.0;
        }
        if open_bins_count == 0 {
            new_bin_bonus -= 100.0; // must open
        }
        if progress < 0.15 {
            new_bin_bonus -= 6.0;
        }
        // Penalize new bins when many open bins could absorb the item.
        new_bin_bonus += (open_bins_count as f64).min(20.0) * 1.5;
        score += new_bin_bonus;
    }

    // Mild preference for tighter bins (low residual) among open bins.
    score += (bin_residual as f64 / cap) * 6.0;

    // Slight preference to balance residual mass across bins.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible follow-up item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 60.0;
    }
    // Dead space that cannot fit the lookahead item is extra wasteful.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still absorb the next item after this placement.
        score -= 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 20.0 / (1.0 + (post_residual as f64 / item_size.max(1) as f64));

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new one is cheap.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean-residual coupling: placing into a bin far below mean residual
    // (larger residual than average) is mildly favored to balance bins.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when current fit is bad or
    // the item is large and no tight option exists.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 45.0
            + 0.5 * open_bins_count as f64
            + 10.0 * bad_fit_penalty
            + (item_size as f64 / bin_capacity as f64) * 10.0;
        // Late in the stream, consolidating is cheaper than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near-perfect lookahead match (small slack after next item)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 30.0 - slack * 2.0;
        }
    }

    // Penalize post-residual that is too small to ever fit another item (dead space)
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 100.0;
    }

    // Penalize leaving residuals far from the mean (fragmentation signal)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when the item is large relative
    // to residuals or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        // Large items prefer a fresh bin; small items should reuse open bins.
        score += 40.0 - fill * 60.0;
        // If many bins are open and mean residual is large, discourage new bins.
        score += mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild reward for tight fits overall (low post residual already does this,
    // but emphasize relative tightness)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 5.0;

    // Slight time-decay: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 6.0 * (1.0 - post_residual as f64 / 50.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin could have fit the next item but won't after placement.
            score += 4.0;
        }
    }

    // Prefer using bins with larger residuals when many bins are open
    // (keeps small residuals from proliferating).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be conservative (favor new bins
    // less), late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * tightness;

    // New-bin candidate: baseline cost of opening a fresh bin, modulated
    // by how poorly the item fits existing bins and stream progress.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 10.0;
        // Cheap to open early; expensive late.
        new_bin_cost += 20.0 * progress;
        // Expensive if many bins are already open (fragmentation risk).
        new_bin_cost += 0.8 * (open_bins_count as f64);
        // If only this new bin fits, it's mandatory.
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        }
        // Large items relative to capacity justify fresh bins.
        new_bin_cost -= 4.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic in post-residual, weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * pr_norm * pr_norm;

    // Smooth cubic coupling: penalize mid-range dead space more as stream advances
    score += 25.0 * progress * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.5 * progress);
    }

    // Tight fit reward (smooth, non-piecewise)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: reward leaving room for the next item (smooth gaussian-like)
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let sigma = 20.0;
        score -= 15.0 * (-(diff * diff) / (2.0 * sigma * sigma)).exp();
    } else {
        // Last item: strongly minimize waste
        score += 50.0 * pr_norm;
    }

    // Prefer consolidating into bins with small residual relative to mean
    score += 10.0 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 35.0 + 40.0 * (1.0 - progress);
        // But if no open bin fits well, allow it: soften when others barely fit
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo 10: small odd residues are dead space.
    let r_mod = post_residual % 10;
    let dead_penalty = match r_mod {
        1 | 2 | 3 => 12.0,
        4 | 5 | 6 => 5.0,
        7 | 8 => 1.5,
        _ => 0.0, // 0 and 9 are "clean" classes
    };
    score += dead_penalty;

    // Integer-division threshold classes on post_residual relative to capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual <= quarter / 2 {
        score -= 10.0; // near-perfect class
    } else if post_residual > half {
        score += 4.0; // leaves a half-capacity hole; often fine, slight penalty
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: next item leaves a clean residual class too.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item won't fit here; penalize small residuals more (dead space locked).
            if post_residual < next_item_size && post_residual < quarter {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 20.0 + 10.0 * progress;
        if open_bins_count > 4 {
            open_cost += 3.0 * (open_bins_count as f64 - 4.0).min(6.0);
        }
        // If next item is large relative to capacity, a fresh bin is more attractive.
        if next_item_size >= half {
            open_cost -= 8.0;
        }
        // Large items prefer fresh bins over fragmenting tight bins.
        if item_size > bin_capacity * 3 / 4 {
            open_cost -= 6.0;
        }
        score = open_cost + post_residual as f64 * 0.05;
    }

    // Tie-break toward bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residuals that no typical item can use
    // are worse than exact fits. Penalize gaps in (0, 10) heavily, and gaps in
    // (10, 20) mildly since only tiny items can fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward bins whose residual can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0; // this bin becomes dead after this placement
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 45.0 + 8.0 * open_bins_count as f64;
        // Opening a new bin is acceptable only if all fits would create dead space
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // Mild preference for tighter (smaller residual) bins among open bins.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Early stream: be slightly more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Lookahead: reward when next item exactly fills post_residual.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if gap == 0.0 {
                score -= 500.0;
            } else if post_residual >= next_item_size {
                score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            } else {
                // Dead space that next item cannot use: penalize.
                score += 0.5 * gap;
            }
        }
        // Penalize small unusable leftovers relative to item scale.
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Prefer tight fits: reward small post_residual relative to mean residual.
    score -= 2.0 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: avoid opening a new bin if this fits reasonably.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Slight preference for fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count <= 3 {
        score -= 10.0 * (3 - fitting_bins_count) as f64;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward;
    // otherwise penalize leaving a residual that teases but fails.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 10.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Global state: prefer filling bins when many are open (bin consolidation),
    // allow opening new bins when few are open.
    let open_f = open_bins_count as f64;
    let fill_pressure = (open_f / (open_f + 4.0)).min(1.0);
    score += 15.0 * fill_pressure * (bin_residual as f64 / bin_capacity as f64 - 0.5);

    // Mean residual coupling: if this bin's residual deviates from the mean,
    // favor bins with below-mean residual (reduce variance of leftovers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very empty existing bins (save them for big items),
    // unless late in the stream.
    let emptiness = bin_residual as f64 / bin_capacity as f64;
    if emptiness > 0.9 && progress < 0.5 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: penalize post-residual more strongly as stream progresses
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Reward tight fits (low post residual) especially mid-stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (progress * (1.0 - progress) * 4.0).sqrt();

    // Lookahead: bonus if next item fits into post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - fit_quality) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - progress);
    }

    // Penalize last-chance bin lightly (avoid wasting it on bad fit)
    if fitting_bins_count == 1 {
        score += 5.0 * norm_pr * (1.0 - progress);
    }

    // Slight preference for filling bins with low residual relative to mean
    score += 3.0 * ((pr - mean_residual) / cap);

    // New-bin candidate: mild penalty so it's only chosen when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Penalize dead space that cannot host small items: harmonic residue classes.
    // post_residual % 10 classes: small residues (1..9) are hard to fill.
    let residue = post_residual % 10;
    if post_residual > 0 {
        if residue == 0 {
            score -= 6.0; // perfectly aligned leftover, easy to fill later
        } else if residue >= 7 {
            score -= 2.0; // large residue, likely fillable by small items
        } else if residue <= 2 {
            score += 12.0; // tiny sliver: near-dead space
        } else {
            score += 5.0; // mid residue: moderately awkward
        }
    }

    // Integer-division thresholds: how many size-10 items could still fit.
    let slots = post_residual / 10;
    score -= slots as f64 * 1.5;

    // Tight fit reward: post_residual small relative to capacity is good.
    if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    } else if frac > 0.6 {
        score += 6.0; // leaving more than 60% empty is wasteful
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        if diff <= 3 {
            score -= 14.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize near-full bins to keep flexibility.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when existing bins have bad residuals.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.15 * (open_bins_count as f64);
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.05);

    // Mean residual coupling: prefer bins close to mean residual (balanced packing).
    score += 0.1 * ((post - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are pure waste. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        // Tightness bonus: smaller post_residual relative to capacity is better.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 45.0; // perfect chain placement
        } else {
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover gap: penalize proportional to gap smallness.
        score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> consolidate, favor existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is well below the mean,
    // using it reduces fragmentation variance (good).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 8.0 * (1.0 - res / (mean_residual + 1.0));
    } else {
        score += 4.0 * (res - mean_residual) / (bin_capacity as f64);
    }

    // New-bin candidate baseline: an empty bin should only win when open bins
    // offer poor fits. Give it a mild penalty so decent fits in open bins win.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if next item is large and current bins are fragmented, allow new bin.
        if next_item_size >= item_size && mean_residual < next_item_size as f64 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: dead space of 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (creates a perfect second placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves more waste; mild reward proportional to tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - tight * 0.35;
        } else {
            // Next item won't fit here; penalize leaving residual that is close
            // but insufficient (unusable dead space relative to the lookahead).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Relative residual vs mean: bins with more room than average are better
    // targets for large items; tight bins should absorb small items.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel < 1.0 {
            score -= (1.0 - rel) * 8.0; // tighter-than-average bin favored
        } else {
            score += (rel - 1.0) * 4.0; // looser-than-average bin mildly penalized
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins could fit, unless the item
    // is large and the residual waste would be big.
    if bin_residual == bin_capacity {
        // New bin candidate: waste is the entire capacity minus item; prefer it
        // only when current placement would leave large unusable leftovers.
        score += 45.0;
        // Large items benefit from a fresh bin early in the stream.
        if item_size > 60 {
            score -= 20.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Small penalty for leaving residual below the minimum item size (1),
    // scaled: residuals < 10 are near-dead space.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        score -= 0.9 * (item_size as f64) * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Penalize small dead space that nothing (esp. next item) can use.
    if post_residual > 0 {
        let dead = if (next_item_size as u64) > (post_residual as u64) { 1.0 } else { 0.35 };
        score += 6.0 * dead * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (next_item_size as u64) <= (post_residual as u64) {
        score -= 4.0 + 0.05 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: prefer consolidation onto existing bins.
    score += 0.15 * open_bins_count as f64;

    // Time horizon: early on, be picky (penalize loose fits); late, just fill.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.5 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64 - item_size as f64).max(0.0);

    // New-bin candidate: only attractive when residuals are fragmented or bin is truly needed.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let avg_fit = mean_residual / bin_capacity as f64;
        let fragmentation = if avg_fit > 0.0 && (item_size as f64) > mean_residual { 1.0 } else { 0.0 };
        score += 30.0 - 20.0 * fragmentation - 5.0 * (1.0 - avg_fit);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // pair large consecutive items in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: tight fit reward, non-linear in post_residual (quartic-ish shaping)
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Penalty for leaving a sliver too small for the smallest plausible item,
    // smoothed via a bump function around the dead-space zone.
    let dead = (post > 0.0 && post < 10.0) as i32 as f64;
    score += 12.0 * dead * (1.0 - post / 10.0);

    // Smooth interaction: as stream progresses, prefer ever-tighter packing.
    score -= progress * 8.0 * (1.0 - post / cap).powi(3);

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 10.0 * (-gap / 15.0).exp() * (1.0 - progress * 0.5);
        // Penalize leaving space that next item nearly but not quite fits (waste trap)
        if nxt > post && nxt <= cap {
            score += 4.0 * (1.0 - (post / nxt));
        }
    }

    // Mild penalty for spreading across many open bins vs consolidating.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // New-bin candidate adjustment: only attractive when residual is huge and
    // current item is large (poor fit elsewhere), decaying with progress.
    if bin_residual == bin_capacity {
        let poor_fit = (item / cap).powi(2);
        score += 25.0 * (1.0 - progress) - 15.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Perfect-fit reward: post_residual exactly 0, or in a "composable" class
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    }

    // Penalize dead space that cannot fit typical small items (1..=10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Next-item coupling: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when fits are bad
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.15 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin guarantees a clean class for the next item
            score -= 10.0;
        }
    }

    // Stream progression: late in stream, prefer tighter packs
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Many open bins: discourage spreading; prefer filling existing ones
    score += open_bins_count as f64 * 0.4;

    // Mean residual alignment: prefer bins near the mean (balanced packing)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (min item size is 1 in the interface, but tiny gaps still waste capacity).
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Penalize small gaps super-linearly; a gap that can't fit the next item
        // is likely dead unless a small item arrives.
        if post_residual < 10 {
            score += (10.0 - pr) * 12.0;
        } else if post_residual < 20 {
            score += (20.0 - pr) * 4.0;
        }
        // If next item can't fit in the gap, the gap is dead for lookahead too.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0;
        }
        // Perfect fit: fully reward.
        if post_residual == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0;
    }

    // Reward tight fits: ratio of item to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bins pressure: discourage spreading across many bins unless the fit is tight.
    score += (open_bins_count as f64) * 0.8;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless the current
    // item is large and residuals elsewhere are small (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + progress * 10.0;
        // Allow new bin when item is huge and mean residual can't host it well.
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        // Lookahead: if next item is large, prefer fresh bin for the current big item.
        if next_item_size >= 60 && item_size >= 50 {
            score -= 15.0;
        }
    }

    // Slight bonus for placing into bins with above-average residual (keeps
    // small bins from fragmenting).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: exact match of next item into post_residual is ideal
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, penalize leftover after that placement (dead space over 2 steps)
            let two_step_waste = (post_residual - next_item_size) as f64;
            score += 0.6 * two_step_waste;
            // reward if the two-step placement leaves a nearly perfect fit
            let second_tight = 1.0 - two_step_waste / (bin_capacity as f64);
            score -= 15.0 * second_tight * second_tight;
        } else {
            // next item does NOT fit after this placement: penalize proportionally
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.35 * overflow;
        }
    }

    // Compare against mean residual: bins below mean residual are scarcer, prefer filling them
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = (item_size as f64) / (bin_capacity as f64);
        // opening is attractive only for large items or when no good fit exists
        score += 45.0 - 40.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late in the stream: consolidate, avoid spreading across many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post residual quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize wasted space relative to bin capacity (dead space creation).
    let waste = (bin_residual - item_size) as f64;
    score += (waste / bin_capacity as f64) * 15.0;

    // Last-chance bonus: if this is the only bin that can fit, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // Mild penalty when many alternatives exist; keep flexibility.
        score += (fitting_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 25.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to how close it was.
        let miss = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += miss * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Time horizon: early in stream, prefer opening new bins to spread load;
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 - 5.0;

    // Global state: many open bins -> favor filling existing ones (penalize new-bin candidate).
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate handling: empty bin gets a baseline penalty that shrinks
    // as the stream progresses and when mean residual across bins is high.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 35.0 - progress * 20.0 - (mean_residual / bin_capacity as f64) * 10.0;
        score += new_bin_penalty.max(-5.0);
    }

    // Mean residual coupling: if this bin's residual is far below mean (it's tight),
    // reward using it; if it's far above mean (it's roomy), slight penalty.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 12.0;

    // Small residual bins are precious; penalize dumping large items creating mid-range gaps.
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: post residual (waste), scaled down as stream progresses
    let mut score = post * (1.0 - 0.3 * progress);

    // Non-linear penalty for small-but-not-zero dead space (unusable slivers)
    score += 18.0 * norm_post * (1.0 - norm_post) * (1.0 - norm_post);

    // Coupling post_residual with mean residual: prefer bins near the mean
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Reward tight fits via cubic term on normalized post residual
    score -= 10.0 * (1.0 - norm_post).powi(3);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if post residual can't fit next item
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += 6.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // reward leaving space for next item
        score -= 3.0 * (post - next_item_size as f64) / cap;
    }

    // Crowding: slight penalty when many bins open (encourage consolidation)
    score += 0.4 * open_bins_count as f64;

    // Smooth new-bin bias: empty bin candidate gets moderate score that
    // decreases with progress so late stream favors new bins over bad fits
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.25 * progress) + 12.0 * norm_post * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: exact-fit classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr < 10 {
        score -= 120.0; // near-perfect dead space
    } else if pr % 10 == 0 {
        score -= 40.0; // decadal residual, easy to refill
    } else if pr % 5 == 0 {
        score -= 15.0;
    } else {
        score += (pr % 5) as f64 * 6.0; // odd residues are harder to reuse
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 60.0 + 0.5 * (next_item_size as f64);
        // harmonic bonus if next item leaves a clean residual too
        let npr = pr - next_item_size;
        if npr % 10 == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        score += 10.0; // cannot host lookahead
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Fractional capacity logic: penalize leaving > half-empty bins early,
    // reward compact bins late in the stream.
    let frac = post_residual as f64 / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if frac > 0.5 {
        score += 30.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Spread control: prefer bins near the mean residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 70.0 + 0.5 * open_bins_count as f64;
        score = base + if fitting_bins_count == 0 { -200.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, unusable gap)
    // is heavily penalized. Dead zone: residual too small to fit even the smallest
    // plausible future item relative to what remains.
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 10.0;

    // Open-bin pressure: penalize using bins when many are open, to avoid
    // spreading items across too many bins and fragmenting residuals.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bin by default; discount if item is large and current
        // bins have poor (fragmented) residuals.
        score += 20.0 - large_item * 15.0 - fragmentation * 0.3;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post_residual is too small for the next item (wasted space ahead).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Stream progression: early on, be more conservative (favor new bins less);
    // later, pack tighter into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how snugly the next item fits the leftover.
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 40.0 + 0.5 * next_item_size as f64 - 0.3 * slack_after_next;
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += 0.4 * next_item_size as f64;
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score -= 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when other bins could fit,
    // unless the current bin would leave a large unusable fragment.
    if bin_residual == bin_capacity {
        let fragment = post_residual as f64;
        if next_item_size > 0 && fragment < next_item_size as f64 {
            // new bin would create dead space immediately: slight penalty
            score += 10.0;
        } else {
            // neutral-ish: prefer reusing bins generally
            score += 15.0;
        }
    }

    // Progress-scaled tightness: as stream advances, prefer minimal waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins that are well-filled by this item (high fill fraction).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Lookahead: if the next item can still fit in the leftover space,
    // this placement is composition-friendly.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        } else {
            // Dead space for the lookahead: penalize proportional to waste,
            // but only if the waste is small enough to be truly dead.
            if post_residual < next_item_size {
                score += 0.12 * post_residual as f64;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Brand-new bin candidate: add a mild opening cost so it only wins
    // when every open bin is a poor fit (its tight-fit scores still compete).
    if bin_residual == bin_capacity {
        score += 9.0;
        // A fresh bin is more attractive early in the stream and when the
        // fleet of open bins is small.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 4.0;
        score -= (open_bins_count.min(10) as f64) * 0.3;
    }

    // Slight preference for keeping residuals near the global mean
    // (avoids extreme fragmentation outliers).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // Penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: penalize wasted residual, with stream-progress-dependent curvature
    let mut score = r * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear coupling: quadratic waste term that intensifies late in stream
    score += 25.0 * norm_r * norm_r * (0.5 + progress);

    // Reward tight fits smoothly (low post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness * tightness * (1.0 - progress * 0.5);

    // Lookahead coupling: if next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / r.max(1.0);
        score -= 10.0 * fit_ratio * (1.0 - fit_ratio) * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mean-residual coupling: prefer bins near the mean residual (smooth deviation penalty)
    let dev = (r - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * norm_r;

    // New-bin candidate: make empty bins attractive only when the fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - tightness) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small dead space is fine, mid-range waste is bad
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f;

    // Penalize mid-range residuals (30..60) that few future items can use
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 12.0; // near-perfect fit, reward strongly
        } else if post_residual < 30 {
            score -= 4.0;
        } else if post_residual < 60 {
            score += 10.0 + 0.2 * (post_residual as f64); // dead zone penalty
        } else {
            score -= 1.0; // large residual still reusable
        }
    } else {
        score -= 20.0; // exact fill is ideal
    }

    // Modulo class logic: residuals divisible by small item sizes are more reusable
    let reuse_bonus = if post_residual >= 10 {
        let mut bonus = 0.0;
        if post_residual % 10 == 0 { bonus += 6.0; }
        if post_residual % 20 == 0 { bonus += 4.0; }
        if post_residual % 5 == 0 { bonus += 2.0; }
        bonus
    } else { 0.0 };
    score -= reuse_bonus;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 0.15 * (next_item_size as f64);
        } else {
            // next item can't use this bin's remainder: penalize wasted space more
            score += 0.1 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = 55.0;
        // cheaper to open a bin when many bins are already open (consolidation pressure low)
        score -= 0.3 * open_bins_count as f64;
        // if item is large relative to capacity, opening fresh bin is fine
        if item_size > 50 { score -= 8.0; }
        // late in stream, prefer using existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for tighter existing bins relative to mean residual
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

