    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual after placement can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bins pressure: discourage scattering items across many bins,
    // but relax pressure when this bin is the last chance (avoid new bin).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.4 * progress);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so it is only chosen when
    // existing bins have truly bad fits (their dead-space penalty dominates).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect chain (post_residual == next_item_size) gets a big bonus.
        if post_residual as f64 == next {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: reward closeness to perfect chaining.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the residual: penalize dead space relative to mean residual.
            score += 0.5 * diff + 0.3 * (mean_residual - post_residual as f64).abs();
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize very small residuals (unusable dead space) more than linear.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward placing into bins with below-mean residual (consolidate fullness),
    // slightly scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 0.2 * (mean_residual - post_residual as f64).max(0.0) * (0.5 + progress);
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (large leftover would be created) or few bins are open.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        // Base cost of a fresh bin; discount if it promises a good chain with next item.
        let mut new_bin_score = waste_if_open + 30.0;
        if next_item_size > 0 {
            let chain = (bin_capacity - item_size - next_item_size) as i64;
            if chain >= 0 {
                new_bin_score -= 35.0;
            } else {
                new_bin_score += (chain.abs() as f64) * 0.4;
            }
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // forced: no open bin fits
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never host a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver under the minimum item size
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 3.0; // awkward zone
    }

    // Last-chance bonus: only this bin can fit the item -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Chain fit: post residual fits next item, and post-after-next residual still usable.
        if post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual {
            score -= 3.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so existing bins usually win; decays when open bins are crowded.
        let mut new_bin_penalty = 30.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = -5.0; // no open bin fits: opening is necessary
        } else {
            // If the best existing fit is loose (large post_residual), allow new bin more readily.
            if post_residual > bin_capacity / 2 {
                new_bin_penalty -= 10.0;
            }
            // Late in stream, consolidating into open bins matters more.
            new_bin_penalty += 20.0 * progress;
        }
        // Many open bins with slack: discourage opening yet another.
        if mean_residual > 30.0 && open_bins_count > 3 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    } else {
        // Mild reward for using bins that are already fairly full (best-fit flavor).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * fill_ratio;
        // Slight penalty when many bins are open and this one is nearly empty (fragmentation).
        if bin_residual as f64 > mean_residual + 40.0 && open_bins_count > 2 {
            score += 6.0;
        }
    }

    // Global pressure: when many open bins exist, favor consolidating (tight placements).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * tightness * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit)
    let mut score = post;

    // Non-linear penalty for awkward dead space: post_residual squared, normalized
    let x = post / cap; // in [0,1]
    score += 30.0 * x * x * (1.0 - x) * (1.0 - x) * cap * 0.1;

    // Smooth coupling with stream progress: later in stream, punish waste more
    score += 10.0 * x * x * (0.5 + progress);

    // Reward tight fits more strongly as the stream advances
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits the post residual (smooth bump)
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap) / cap;
        let fit_quality = 1.0 - ((post - next_item_size as f64).abs() / cap);
        score -= 6.0 * fit_quality * nx * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - x);
    } else {
        // Slight penalty when many bins compete, favor consolidation
        score += 2.0 * ((fitting_bins_count as f64).ln() + 1.0) * x;
    }

    // Mean residual coupling: if this bin is far below mean residual, mildly discourage
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, unless current bin waste is large
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 10.0 * (1.0 - x * 0.0);
        // discount penalty late in the stream when consolidation matters less
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

