    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    } else if post_residual <= 30 {
        score -= 20.0;
    }

    // Harmonic classes via integer division of post_residual by 10:
    // residual classes 0-9, 10-19, ... — penalize dead space in low-utility classes.
    let class = post_residual / 10;
    score -= (class as f64) * 2.0;

