            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only open a new bin when existing fits are bad
    // (post_residual large relative to capacity and item small).
    if bin_residual == bin_capacity {
        // new bin: baseline score = full capacity minus item
        score = (bin_capacity - item_size) as f64;
        // discourage opening new bins when a decent fit exists elsewhere
        if post_residual == bin_capacity - item_size && fitting_bins_count > 0 {
            score += 50.0;
        }
        if item_size >= 50 {
            score += 20.0; // big items fine in fresh bins
        }
    }

    // Prefer bins below mean residual (keeps bin residuals balanced).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Modulo harmonic: residuals that are multiples of common item sizes (10,20,25,50)
    // are reusable; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Slight preference for earlier bins as stream progresses (stabilize open set).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

