    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize new bins more when mean residual is high (space is being wasted).
        score += 30.0 + 40.0 * fragmentation + 10.0 * (1.0 - progress);
        // If no open bin fits at all, allow opening a new bin more readily.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Prefer bins with residual close to item_size (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * fit_gap;

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Base: post residual, slightly sub-linear to tolerate small leftovers early.
    let mut score = pr.powf(0.85);

    // Non-linear coupling: residual waste penalized more as stream progresses.
    let waste_coupling = (pr / cap).powi(2) * (1.0 + 3.0 * progress * progress);
    score += waste_coupling * cap;

    // Reward tight fits (small post_residual relative to item) with smooth term.
    let tightness = (1.0 - fit).powi(2);
    score -= (1.0 - tightness) * 8.0;

    // Last-chance bonus: only one bin fits, smooth reward.
    if fitting_bins_count <= 1 {
        score -= 6.0 * (1.0 - progress * 0.3);
    }

    // Penalize bins with residual far below mean (fragmented bins) smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs().powi(3) * 5.0;

    // Lookahead: penalize leaving residual that neither fits next item well nor is tiny.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let after_next = pr - nx;
            score += (after_next / cap).powi(2) * 10.0 - 2.0;
        } else {
            score += 3.0 * (1.0 - pr / nx.max(1.0));
        }
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized early, viable late.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 2.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are near-perfect packs.
    let cls = post_residual % 10;
    score -= match cls {
        0 => 6.0,
        1 | 2 => 4.0,
        3 | 4 => 2.0,
        _ => 0.0,
    };

    // Integer-division threshold on post residual: dead space tiers.
    let dead = post_residual / 10;
    score += (dead as f64).powi(2) * 0.15;

    // Reward tight fits strongly.
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this is a great two-item chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin
    // would leave large unusable residue.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size >= 70 {
            score -= 10.0; // big items are fine in fresh bins
        }
    }

    // Late in stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Slight preference toward bins below mean residual (balance avoidance
    // of fragmenting already-loose bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize mid-range dead space that few future items can use.
    if post_residual > 0 && post_residual < item_size {
        score += 0.5 * (item_size - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open bins pressure: discourage spreading across many open bins.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item does NOT fit post residual but would fit a fresh bin, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.4 * next_item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when the item fits terribly everywhere (large post_residual relative).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual relative to capacity)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can chain into this bin
            score -= 3.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally
            score += 0.3 * gap;
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.2 * post_residual as f64;
    }

    // Compare post_residual against mean residual: avoid creating outliers
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pairing potential: slightly soften new-bin penalty
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        }
    }

    // Late in stream: consolidate, discourage new bins further
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual barely exceeds item size.
    let fit_gap = (bin_residual as i64 - item_size as i64).max(0) as f64;
    score -= 12.0 * (1.0 - fit_gap / bin_capacity as f64).max(0.0) * (fit_gap as f64).min(10.0);

    // Penalize small dead space that nothing small can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits
    // poorly everywhere else or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_gap > 15.0;
        if poor_fit && open_bins_count > 2 {
            score -= 18.0 + 10.0 * (1.0 - progress);
        } else {
            score += 15.0 + fragmentation * 0.2;
        }
    }

    // Mild preference to fill bins with larger residuals when many bins are open.
    score += 0.05 * open_bins_count as f64;
    score -= 0.02 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let t = progress * std::f64::consts::PI;
    let wave = 0.5 * (1.0 - t.cos()); // smooth 0->1 ramp
    score += 8.0 * (pr / cap) * (pr / cap) * (1.0 + wave);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev.abs();

    // Lookahead: favor bins whose post-residual can host the next item smoothly
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // Mild penalty on proliferating open bins late in the stream
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 granularity
    let harmonic = post_residual % 10;
    // Small leftover fragments (< 10) are dead space; penalize them
    if post_residual < 10 {
        score += 25.0;
    }
    // Penalize non-zero harmonic classes slightly (wasted fraction of capacity)
    score += harmonic as f64 * 0.8;

    // Perfect or near-perfect fits get strong rewards
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Big item classes (integer division thresholds)
    let item_class = item_size / 20; // 0..4
    let next_class = next_item_size / 20;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += (post_residual as f64) * 0.3;
        }
        // Same harmonic class pairing bonus
        if next_item_size > 0 && (post_residual % 10) == (next_item_size % 10) && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Capacity fraction coupling: bins with low remaining fraction are precious
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += residual_frac * 10.0;

    // Prefer filling bins that are already mostly full when many bins are open
    if open_bins_count > 4 {
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Stream progression: early on, be more willing to open new bins (penalize tight fits less)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if residual_frac > 0.4 && progress > 0.5 {
        score += 10.0; // avoid leaving huge holes late in the stream
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when all open bins score worse
    if bin_residual == bin_capacity {
        score = 55.0 + item_class as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin attractive
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when a last-chance bin exists
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier hole
    let diff = mean_residual - post_residual as f64;
    if diff > 15.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be used again are very costly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }
    // Residual too small for the lookahead item is half-dead.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }
    // Reward when post_residual exactly accommodates the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Tight-fit reward relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: prefer consolidating into existing bins; penalize new-bin creation.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: bins far below mean residual are "wasted" targets; prefer bins
    // whose residual is close to the item so mean residual shrinks toward usable chunks.
    let res_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * res_gap;

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: low post_residual is good (already the base).
    // Penalize post_residual that is small but unusable (dead space).
    if post_residual > 0 {
        let dead_threshold = 9.0; // smallest item is 1; anything tiny is near-dead
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // 2-step lookahead: reward if next_item_size fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent — the residual is reusable immediately.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 20.0 * tightness;
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce-space bins;
    // filling them is good if the fit is tight, bad if it creates dead space.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            // Below-mean residual: scarcer space, favor using it when tight.
            score -= 8.0 * (1.0 - rel);
        } else {
            // Above-mean residual (roomy bin): mild penalty to prefer tighter bins.
            score += 3.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= bin_capacity / 4 {
            score -= 30.0; // good fit in the only option: strong reward
        } else {
            score -= 5.0; // weak encouragement anyway
        }
    }

    // New-bin candidate handling: make a fresh bin moderately attractive only when
    // the current fit is bad (large post_residual) or lookahead fails.
    if bin_residual == bin_capacity {
        // Base score for a new bin is bin_capacity (large = unattractive),
        // but discount it so it can win over truly poor fits.
        score = score * 0.55 - 10.0;
        // If lookahead item is large, a fresh bin is a safe bet.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny dead space
    // that is likely unusable (below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item can still fit here afterward: mild bonus.
        score -= (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the remaining space: penalize creating waste
        // proportional to how much would be stranded.
        score += post_residual as f64 * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: competition is high, slight penalty to encourage
    // diversity of residuals across bins (keep some bins for future items).
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Global state: if mean residual across open bins is large, the fleet is loose;
    // prefer filling this bin well to consolidate (subtract for low post_residual
    // relative to mean).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Too many open bins relative to progress: encourage consolidation by
    // penalizing less-full bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > progress * 20.0 + 5.0 {
        score += post_residual as f64 * 0.2;
    }

    // Late in the stream: prioritize closing out bins tightly, avoid new bins.
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it unattractive unless nothing reasonable fits.
    // An empty bin has huge post_residual, which already scores high; add extra
    // penalty that shrinks when the item is large (large items justify new bins).
    if bin_residual == bin_capacity {
        score += 15.0 - (item_size as f64 * 0.12);
        // But if no open bin can fit, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly squashed.
    let mut score = (norm_pr.powi(2) * 60.0) - (norm_pr * 20.0);

    // Smooth coupling of post_residual with stream progress:
    // early on, be lenient with leftover space; later, punish waste harder.
    let waste_penalty = norm_pr.powf(1.5 + 2.5 * progress) * (40.0 + 80.0 * progress);
    score += waste_penalty;

    // Interaction: post_residual vs mean residual — avoid bins that end far from the pack's typical leftover.
    let mean_norm = mean_residual / cap;
    score += ((norm_pr - mean_norm) * (norm_pr - mean_norm)) * 25.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0 + 45.0 * progress;
    }

    // Lookahead: reward if next item fits snugly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= (1.0 - slack / cap) * 18.0;
        } else {
            score += (nxt - pr) / cap * 12.0;
        }
    }

    // Mild preference for consolidating into fewer bins as stream advances.
    score += (open_bins_count as f64) * 0.6 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_bonus = (item_size as f64 / cap).powf(2.0) * 70.0;
        score -= large_bonus;
        score += 8.0; // slight default cost so decent existing fits win
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 granularity (dead-space classes)
    let pr = post_residual as i64;
    let class = pr % 10;
    // Small leftovers are fine (likely fillable); mid-range leftovers are dead space
    if pr > 0 {
        if class == 0 {
            score -= 20.0; // leaves round residual, easy to fill later
        } else if class <= 3 {
            score -= 8.0;
        } else if class >= 6 {
            score += 10.0 + (class as f64 - 5.0) * 4.0; // awkward dead space
        }
    }

    // Integer-division threshold: post_residual divisible by small sizes is reusable
    if pr > 0 {
        let mut reusable = 0.0;
        for d in [10i64, 20, 25, 50] {
            if pr % d == 0 {
                reusable += 6.0;
            }
        }
        score -= reusable;
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Bonus scaled by how snugly the next item fits
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize unless this bin is nearly full anyway
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer tighter existing bins over emptier ones (mild)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Penalize wasting a large-capacity fresh bin on a small item
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac < 0.5 {
            score += 60.0 * (0.5 - frac);
        } else {
            score -= 10.0; // large item into fresh bin is reasonable
        }
        // Early stream: opening bins is cheap; late stream: prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Slight preference to fill bins with more residual when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are nearly unusable
    // for future items (sizes >= 1, but typically >= 10 in classic streams).
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 + 4.0 * (12 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 100.0;
    }

    // Nonlinear penalty for leaving residual that cannot fit the lookahead item
    // while the lookahead would otherwise fit this bin's current residual.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size as f64
            && bin_residual as f64 >= next_item_size as f64 {
            score += 25.0;
        }
        // Reward bins that can also take the next item (chaining).
        if post_residual as f64 >= next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> new bins are cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open-bin pressure is high.
        score += 30.0 + 20.0 * pressure;
    } else {
        score -= 10.0 * pressure.min(5.0);
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (tighter bins) to preserve large residuals elsewhere.
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack.min(100.0);
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual > 40 {
            score += 120.0; // would create large dead space; prefer new bin
        }
    }

    // Penalize new-bin candidate slightly so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Late-stream pressure: consolidate into open bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 20.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit, residual likely dead space anyway
    }

    // Penalize leaving residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        // already handled above
    }
    if post_residual > 80 {
        score -= 10.0; // large residual still very usable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted space
            score += 8.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when it beats bad fits.
        score += 15.0;
        // Early in stream or many open bins with low mean residual -> prefer reusing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 20.0; // existing bins have room; opening new bin wasteful
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // big pair coming, fresh bin may serve both
        }
    }

    // Encourage consolidation when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // Mild time-dependent exploration term.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (progress * std::f64::consts::PI).sin() * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // later in stream -> penalize large residuals more (want tight fits)
    let progress_coupling = pr * (1.0 - progress) * 0.3
        - pr * progress * (1.0 - progress) * 0.6;
    score += progress_coupling;

    // Interaction: small post_residual is valuable late; cubic smooth term
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize creating dead space unusable by next item (smooth gate)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let unusable = (next_item_size as f64 - pr).max(0.0);
        score += 0.4 * unusable - 0.15 * gap / cap * pr;
    }

    // Last-chance bonus: smooth exponential reward when few fitting bins
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr).powi(2);
    }

    // Mild preference for bins with residuals near mean (balance load)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight penalty for spreading across many bins early
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: size mod 10 buckets
    let item_class = item_size % 10;
    let next_class = if next_item_size > 0 { next_item_size % 10 } else { 0 };

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space penalty: residuals that few future items can use
    let small_class_penalty = match post_residual {
        1..=9 => 60.0,
        10..=19 => 25.0,
        20..=29 => 8.0,
        _ => 0.0,
    };
    score += small_class_penalty;

    // Harmonic compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // perfect chain
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= (40.0 - chain_waste.min(40) as f64) * 0.8;
        } else {
            score += 15.0; // next item won't chain here
        }
        // Reward when post_residual is a harmonic multiple region of next item
        if post_residual >= next_item_size && (post_residual % next_item_size.max(1)) < 10 {
            score -= 20.0;
        }
    } else {
        // Last item: prefer filling as much as possible
        score -= item_size as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bin when existing bins are roomy and item fits well somewhere
        score += 30.0 + fragmentation * 40.0;
        // But if item is large, new bin is often fine
        score -= item_size as f64 * 0.3;
        // Late in stream, fewer open bins -> keep consolidation
        if open_bins_count > 3 && fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Prefer tighter bins (small residual before placement)
    score += bin_residual as f64 * 0.15;

    // Prefer bins below mean residual slightly (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Progress-based nudge: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100 - post_residual.min(100)) as f64 * 0.2;

    // Class-alignment bonus: same residue class items pack well together
    if item_class == next_class && next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Define a "useful gap" threshold relative
    // to capacity; gaps below it are dead space.
    let dead_threshold = (bin_capacity as f64 * 0.10).max(1.0);
    if (post_residual as f64) < dead_threshold {
        // Perfect fit is great; near-perfect fit leaving a tiny sliver is bad.
        if post_residual == 0 {
            score -= 40.0;
        } else {
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
    }

    // Reward tight fits (small post_residual) with a super-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 20.0;

    // Open-bin pressure: when many bins are open, prefer filling existing ones;
    // opening new bins is cheap when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (0.5 + progress);
    score -= pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize if it creates dead space.
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the empty bin mildly by default so
    // existing bins are preferred, scaled by how bad the best fit would be.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.5;
        // Late in the stream, opening fresh bins is less attractive.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        let lookahead = post_residual as f64 - next_item_size as f64;
        if lookahead == 0.0 {
            score -= 800.0; // chain of perfect fits
        } else if lookahead < 0.0 {
            // next item won't fit here: penalize wasting space that could have been tighter
            score += 0.3 * (-lookahead);
        } else {
            // next item fits: reward proportional to tightness of the chain
            score -= 2.0 * (1.0 - lookahead / bin_capacity as f64);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins could still fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if post_residual matches next item or few bins open
        score += 150.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 900.0;
        }
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 50.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    // Small penalty for leaving dead space below minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item packing
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize more if this was a last-chance bin.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: discourage fragmentation, prefer filling existing bins.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += 5.0 * open_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate: make empty bins attractive only when the item is large
    // or the fit into existing bins would be very loose.
    if bin_residual == bin_capacity {
        let looseness = post_residual as f64 / bin_capacity as f64;
        if item_size >= 60 || looseness > 0.5 {
            score -= 15.0 + 10.0 * looseness;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate loose fits (large post_residual); late: penalize dead space quadratically.
    let tightness = (pr / cap) * (1.0 + progress * 3.0) + (pr / cap) * (pr / cap) * (progress * 5.0);
    score += tightness * 8.0;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * (2.0 + 6.0 * progress);

    // Penalize opening new bins early; encourage consolidation late.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 6.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // Dead space unusable by next item: mild quadratic penalty.
        let waste = (pr - next_item_size as f64).max(0.0);
        score += (waste / cap) * (waste / cap) * 3.0;
    }

    // Mean-residual coupling: prefer bins near the mean residual (keeps bin states balanced).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 4.0 * (0.5 + progress);

    // More open bins -> prefer filling existing ones rather than spreading.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large enough for typical items) are penalized less.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits: bonus proportional to fill fraction of the bin.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 30.0 * fill * fill;

    // Dead-space penalty: leftover that is too small to hold any plausible
    // item (assume items >= 1, but small slivers < 10 are near-wasted).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Modulo-class coupling: leftover that is congruent to a "chunky" class
    // (multiples of 10 remaining) is more reusable than odd remainders.
    let class = post_residual % 10;
    score += class as f64 * 0.5;

    // Harmonic threshold on integer division: post_residual / 25 classes.
    let harmonic_class = post_residual / 25;
    score -= harmonic_class as f64 * 2.0;

    // Lookahead: prefer leaving space for the next item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // leftover can host next item: reward, stronger for exact match
            let slack = post - nxt;
            score -= 8.0 - (slack / cap).min(1.0) * 6.0;
        } else {
            // leftover cannot host next item: penalize proportionally
            score += 4.0 * (1.0 - post / nxt.min(cap));
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin.
        score += 35.0;
        // Reduce penalty when open bins are crowded (mean residual small)
        // and few bins can fit the item.
        let crowded = (mean_residual / cap).min(1.0);
        score -= 20.0 * (1.0 - crowded) * (1.0 - crowded);
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        score += 10.0 * progress;
        // If next item is huge, a fresh bin with full capacity is valuable.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * cap {
            score -= 12.0;
        }
    }

    // Mild pressure against proliferation of many open bins.
    score += (open_bins_count as f64).sqrt() * 0.3 * (post_residual as f64 / cap);

    // Tie-break noise-free deterministic jitter by item class.
    score += ((item_size % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // for future items (min size 10), so penalize them heavily.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: prefer reusing bins when many are already open,
    // to avoid bin proliferation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when the item is large (would leave a bad gap in any open bin) or
    // when the next item pairs well with the leftover space.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 60 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual.max(item_size) {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (minimize waste).
        score += (bin_residual as f64 - item_size as f64).abs() * 0.3;
    }

    // Lookahead synergy: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mild preference for bins with residuals near the mean (balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 - 0.4 * slack;
        } else {
            // Next item cannot chain here; penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize dead space that is too small to ever be useful (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin.
        score += 55.0 + 20.0 * (1.0 - progress);
        // If an existing bin fits tightly, discourage the new bin more.
        if post_residual == bin_capacity - item_size {
            let wasted = post_residual as f64;
            if wasted <= 15.0 {
                score += 60.0;
            }
        }
        // When many bins are open with large mean residual, opening new bins is wasteful.
        if open_bins_count > 0 && mean_residual > item_size as f64 * 2.0 {
            score += 15.0;
        }
    } else {
        // Mild bonus for using existing bins relative to mean residual.
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly than linear.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting the gap
            score += 4.0 * next_item_size as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.3 * crowd;

    // Mean residual context: if this bin's residual is far below mean, it's
    // an outlier gap — deprioritize it slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // New-bin candidate handling: empty bin gets a mild baseline cost so it
    // only wins when open bins fit poorly.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    // Late stream: consolidate harder as the stream nears its end.
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit_norm = pr_norm * pr_norm;
    let mut score = pr;

    // Smooth non-linear interaction: residual quality vs stream progress
    score += 40.0 * fit_norm * (1.0 - progress) * (1.0 - progress);
    score += 25.0 * fit_norm * progress;

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dead = ((mean_residual - pr) / cap).max(0.0);
    score += 60.0 * dead * dead * dead;

    // Last-chance bonus: smooth sigmoid-like term
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - fit_norm);
    }

    // Lookahead: reward residual that can still fit the next item (smooth)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = (pr - ni) / cap;
        if slack >= 0.0 {
            score -= 15.0 * slack * (1.0 - slack);
        } else {
            score += 10.0 * (-slack) * (-slack);
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer opening fresh bin early or when fit is terrible
    if bin_residual == bin_capacity {
        score = pr + 35.0 * fit_norm * (1.0 - progress) - 20.0 * (1.0 - fit_norm) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (residue < 10) are nearly perfect fits.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 18.0; // perfect decade alignment, ideal packing
    } else if residue_class <= 3 {
        score -= 9.0;  // near-perfect, tiny dead space
    } else if residue_class >= 7 {
        score += 7.0;  // awkward large-ish gap, likely unusable
    }

    // Integer-division thresholds on post_residual: dead-space zones
    let dead_zone = post_residual / 10;
    match dead_zone {
        0 => score -= 6.0,                 // post_residual < 10: excellent
        1 => score -= 2.0,                 // 10..19: usable for small items
        2 | 3 => score += 3.0,             // 20..39: mediocre zone
        _ => score += 8.0,                 // >= 40: wasteful placement
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item slots cleanly, extra reward for decade fit
            let pair_res = post_residual - next_item_size;
            score -= 8.0;
            if pair_res % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit here anyway; slight penalty for hoarding space
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // many options, less urgency, mild exploration bias
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * (open_bins_count as f64);
    }

    // Capacity-fraction tightness reward: item filling a large fraction
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * fill_frac;

    // Progression term: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Slight preference toward bins below mean residual (tighter bins first)
    score += 0.03 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill, extremely desirable
    } else if post_residual < 10 {
        // gap below the classic minimum item size: pure dead space, heavy penalty
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap can't host the lookahead item: moderate dead-space penalty
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else {
        // usable gap: reward tightness relative to what fits next
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Reward tight fits: small item_size relative to residual means efficient packing.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer using it
    // over opening a new bin (avoiding item fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current
    // item would leave a bad gap in every existing bin, or when bins are saturated.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let bad_existing = fitting_bins_count == 0
            || (next_item_size > 0 && mean_r < next_item_size as f64);
        if bad_existing {
            score -= 30.0; // prefer fresh capacity
        } else {
            score += 40.0 + mean_r * 0.3; // keep using open bins when they fit well
        }
    }

    // Slight preference for bins whose residual deviates below the mean (they are the
    // ones closest to closing out; consolidate toward near-full bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
