pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to zero is good.
    let tight = if post_residual <= 5 { 12.0 } else { 0.0 };
    score -= tight;

    // Penalize large dead space proportionally, with non-linear penalty
    // for residuals too small to fit any plausible item (dead space).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 0.0; // already small residual, fine
    } else if post_residual > bin_capacity / 2 {
        score -= 3.0; // big leftover space is reusable
    } else {
        score += 2.0; // medium leftover space tends to become dead
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // current item is large relative to residual or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 8.0 + waste * 0.3 - 10.0 * (1.0 - progress);
        // opening new bins late is expensive; early is cheaper
        if item_size >= 70 {
            score -= 10.0; // big items fit best in fresh bins
        }
    }

    // Global state coupling: many open bins with high mean residual
    // suggests scattered capacity; favor filling existing bins harder.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 2.0;
    }
    if open_bins_count > 10 {
        score -= 1.5; // consolidate into open bins
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, reward tight fills strongly.
    let tightness = 1.0 - post / cap; // 0..1, higher = tighter fit
    let progress_weight = 2.0 * progress * progress + 0.5 * progress;
    score -= progress_weight * 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (quadratic in waste).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            let waste = (next - post) / cap;
            score += 6.0 * waste * waste * cap;
        } else {
            // reward leaving exactly enough space for the lookahead item
            let gap = (post - next) / cap;
            score -= 3.0 * (1.0 - gap * gap);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * tightness + 5.0;
    }

    // Mild penalty for bins with residual far from mean residual (fragmentation avoidance),
    // scaled smoothly by number of open bins.
    let dev = (post - mean_residual) / cap;
    score += (1.0 + open_bins_count as f64).ln() * 2.0 * dev * dev;

    // Slight preference for using existing bins over opening new ones,
    // weakening as stream progresses (late stream: consolidation matters more).
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space penalty grows quadratically for tiny unusable leftovers,
    // but leftovers that form "harmonic classes" (nice fractions) are less penalized.
    let class = (post_residual / (bin_capacity / 10).max(1)) as f64; // decile class 0..10
    score += 8.0 * (1.0 - frac) * (1.0 - frac); // waste shaping
    score -= 3.0 * (class as i32 % 2 == 0) as i32 as f64; // even deciles are reusable-friendly
    score -= 2.0 * (post_residual % 10 == 0) as i32 as f64; // round leftovers are harmonic

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving room exactly for the next item (harmonic pairing).
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 25.0; // chain fit: this bin then perfectly fits next item
        } else if diff > 0 && diff <= 10 {
            score -= 10.0; // next item still fits snugly
        } else if diff < 0 {
            score += 5.0; // next item won't fit here; dead end risk
        }
        // Harmonic class match: leftover divisible by next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or many bins open.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        if item_size > bin_capacity / 2 {
            score -= 20.0; // big items are fine in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Tight fits preferred: reward small post_residual relative to item.
    score -= 5.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Mild time drift: later in stream, be greedier about tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - frac);

    // Prefer bins below mean residual (keep residuals balanced downward).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

