    score += (open_bins_count as f64) * 0.5;

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the dead space created, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for typical items (unusable gap).
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 25 {
            score += 20.0;
        }
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits here too: good chaining, mild reward proportional
            // to how much would remain after the next item.
            let after_next = post_residual - next_item_size;
            score -= 40.0 - (after_next as f64).min(40.0);
            if after_next < 10 {
                score += 15.0; // but avoid leaving a tiny gap after next
            }
        } else {
            // Next item won't fit after this placement: penalize relative
            // to how badly it misses, scaled by lookahead size.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 2.0;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // prefer bins whose remaining space stays close to (or above) average,
    // avoiding fragmentation of the bin pool.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits among fitting bins.
        score += (fitting_bins_count as f64 - 1.0) * 5.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize opening a new bin progressively,
    // more so early in the stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 60.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is
        // sometimes the cleanest home for future large items.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalized super-linearly.
    let waste = post_residual as f64;
    score += (waste * waste) / bin_capacity as f64;

    // Reward near-full bins strongly (small post_residual).
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill * fill;

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward this placement; otherwise penalize dead space that blocks it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill;

    // Relative-to-mean residual: bins with residual below mean are "saturated",
    // prefer filling them; bins above mean stay as reservoirs.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.1 * (mean_residual - res);
    } else {
        score += 0.05 * (res - mean_residual);
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - fill);

    // Brand-new bin candidate: mild penalty so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let base = pr;
    // smooth non-linear coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 3.0 * pr_norm) * (0.5 + progress) - 2.0 * pr_norm * progress;
    let mut score = base + 20.0 * poly;
    // penalize dead space relative to next item fit
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap);
        } else {
            score += 4.0 * (-gap / cap) * (1.0 - progress);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }
    // mild penalty for spreading across many bins late
    score += 0.5 * (open_bins_count as f64).ln() * (0.3 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain residue classes.
    // Small residues (1..=9) are almost unusable -> strong penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 12.0;
    }
    // Medium dead zones (10..=19) can only take the smallest items: moderate penalty.
    if post_residual >= 10 && post_residual <= 19 {
        score += 5.0;
    }
    // Large usable space is good: reward proportional to post_residual class width.
    if post_residual >= 20 {
        score -= 3.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Integer-division thresholds on post_residual (capacity quarters).
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 2.0; // sub-quarter leftovers are hard to fill
    } else if post_residual >= 2 * quarter {
        score -= 2.0; // half-full or more remains flexible
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving space it almost fits
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 6.0; // tantalizing but unusable
            }
        }
    }

    // Last chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open when open bins are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if open bins are all quite full on average, opening is fine.
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    }

    // Slight preference to fill fuller bins early vs late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.05;

    // Tie-break: prefer bins whose residual is close to the mean residual (harmonic balance).
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest item
    // (size 1) are fine, but gaps below the typical minimum (10) are dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard penalty for creating unusable slivers
    }
    // Penalize small-but-usable gaps less harshly; they are still wasteful.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Exact match with lookahead item: reserve space cleverly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If the next item cannot fit in the post-residual, this placement is fine
    // (no opportunity lost) — small reward.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further
    // unless the fit is very tight; with few bins, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented — prefer filling fragmented bins.
    let this_residual = bin_residual as f64;
    if this_residual < mean_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress and
        // current open-bin count.
        let mut new_bin_cost = 35.0 + 0.4 * (open_bins_count as f64);
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            new_bin_cost *= 1.0 + 0.5 * progress;
        }
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            new_bin_cost -= 10.0;
        }
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // leftover after a hypothetical second placement
            let second_leftover = post_residual - next_item_size;
            score -= 60.0 * (1.0 - second_leftover as f64 / 100.0);
        } else {
            // next item won't fit here: penalize small dead space
            score += 40.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Penalize dead space relative to mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    // Mild pressure toward consolidation as stream progresses
    score += 0.1 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strong reward for near-perfect fit (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 20 {
        score -= 100.0;
    }

    // Penalize dead space relative to item size: wasting a big bin on a small item.
    let fill_ratio = item / cap;
    score -= fill_ratio * 60.0;

    // Lookahead: reward bins whose post_residual can host the next item (good chaining),
    // penalize bins that will strand unusable space relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 80.0;
            // Extra reward if next item fits almost exactly after this placement.
            let gap = post - nxt;
            if gap <= 5.0 { score -= 60.0; }
        } else {
            // Dead space the next item cannot use.
            score += (nxt - post) * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when the
    // item is large relative to capacity or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post) / cap;
        // Early stream / large items / fragmented state -> favor new bin.
        score -= 50.0 + item * 0.8 + fragmentation * 150.0 - progress * 40.0;
        // Penalize opening new bins when many bins already fit the item.
        score += fitting_bins_count as f64 * 30.0;
    } else {
        // Prefer bins with larger residual among open bins (leave small bins for small items).
        score -= (bin_residual as f64) * 0.2;
        // Slight preference for bins below mean residual when state is tight.
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    score -= (open_bins_count as f64).ln().max(0.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Penalize dead space quadratically, amplified as stream progresses.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: subtract more when post_residual is small relative to capacity.
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Interaction: post_residual vs mean residual — prefer bins that keep mean spread low.
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward post-residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins as stream matures.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize mildly early, allow late when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are heavily rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fit class (post_residual == 0) -> strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes on post_residual: leftovers divisible by small strides
        // are more likely to absorb future items.
        let strides: [u32; 4] = [10, 20, 25, 50];
        for s in strides.iter() {
            if post_residual % s == 0 {
                score -= 8.0 + (post_residual / s) as f64 * 0.5;
            }
        }
        // Penalize dead-space classes: residuals too small for the smallest item.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic match: reward proportional to tightness of that future fit.
            let future_tight = (post_residual - next_item_size) as f64;
            score -= 40.0 - future_tight.min(40.0);
        } else {
            score += 15.0;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when all open bins are crowded
    // or the fit would be very loose.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let crowded = open_bins_count as f64 * mean_r / cap; // avg fill fraction
        let loose_fit = item_size as f64 / cap;
        // New bin is penalized by how empty the fleet is, rewarded when fleet is full.
        score += 50.0 * (1.0 - crowded) - 30.0 * loose_fit;
        // Early stream: opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for bins already below-average residual (keeps fleet balanced).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Small tie-break toward tighter fits scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.1 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, the historical minimum item
    // size) are pure waste; penalize them extra hard.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Gaps too small for the lookahead item are also semi-dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64 + 1.0);
    score -= 25.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With several options, mildly prefer fuller bins.
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: many open bins -> encourage consolidation into
    // existing bins rather than opening new ones.
    score += 0.8 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate: make an empty bin attractive only when the current
    // item would leave a large awkward gap or no fitting bin exists.
    if bin_residual == bin_capacity {
        let bad_fit = item_size as f64 <= 0.5 * bin_capacity as f64 && post_residual as f64 > 0.4 * bin_capacity as f64;
        if bad_fit {
            score -= 10.0; // big item, big leftover: fresh bin is fine
        } else {
            score += 20.0; // otherwise discourage opening new bins
        }
        // If no open bin fits, new bin is the only option anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, squeeze harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates below the mean (filling the emptiest
    // usable bins first keeps a portfolio of varied residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tiny post_residual is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    // (chained perfect fit), penalize when next item fits too loosely.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 40.0; // perfect 2-chain
        } else if post_residual as u32 >= next_item_size {
            // next item fits: reward proportional to tightness of chain
            let chain_waste = post_residual as f64 - next;
            score -= 15.0 - chain_waste.min(15.0) * 0.5;
        } else {
            // next item won't fit here: penalize dead space that can't be chained
            score += (next - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter"
    // and better candidates; bins far above mean waste capacity.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(40.0) * 0.3;
    } else {
        score += (res - mean_residual).min(40.0) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // base penalty so new bins are used sparingly
        score += 35.0;
        // large items early in stream: opening fresh bins can pay off
        if fill_ratio > 0.5 && open_bins_count > 2 {
            score -= 20.0 * fill_ratio * (1.0 - progress * 0.5);
        }
        // if many bins fit the item, avoid fragmentation via new bin
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 11..20 dead zone
    if post_residual >= 11 && post_residual <= 20 {
        score += 5.0;
    }

    // Slight preference for bins opened earlier (denser packing, fewer bins)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space relative to the next item's needs (lookahead k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.9 * (next_item_size - post_residual) as f64;
        } else {
            // Residual that can still host the next item is valuable.
            score -= 0.25 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // the item fits poorly everywhere. Base cost of a fresh bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, cheap to open bins; later, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many bins are open with large mean residual, prefer reusing them.
        score += 0.6 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 0.5 * (mean_residual - item_size as f64);
        }
    }

    // Mild preference for bins with residual close to item (best-fit coupling).
    score += 0.15 * ((bin_residual - item_size) as f64);

    // Slight penalty for very large leftover fragments that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: penalize wasted space, with non-linear (quadratic) dead-space term.
    let mut score = pr as f64 + 8.0 * x * x * cap;

    // Smooth interaction: tight fits are more valuable late in the stream.
    let tightness = 1.0 - x; // 1.0 = perfect fit
    score -= 30.0 * tightness * (0.3 + 0.7 * progress);

    // Cubic coupling: strongly penalize mid-range residuals (awkward dead space),
    // smooth polynomial rather than piecewise.
    let mid = (x - 0.5) * (x - 0.5);
    score += 12.0 * (0.25 - mid) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item,
    // penalize bins that would strand a large next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 + 0.1 * nxt;
        }
    }

    // Mild global pressure: when many bins are open, prefer consolidation.
    score += 0.15 * open_bins_count as f64 * (x + 0.1);

    // Deviation from mean residual: prefer bins that reduce dispersion smoothly.
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make opening a fresh bin moderately expensive so it
    // only wins when open bins offer a genuinely poor fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    // Small, "dead" leftovers (post_residual < 10) are nearly unusable -> heavy penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // dead space penalty
    }

    // Harmonic class via integer division: leftover buckets of 10 units.
    // A leftover that is a multiple of 10 aligns with the smallest item size (10),
    // making it reusable -> reward.
    let bucket = post_residual / 10;
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0 * (bucket as f64).min(5.0);
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item fills the leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill_ratio;
        } else {
            // next item cannot use this leftover: penalize large leftovers slightly
            score += 0.05 * post_residual as f64;
        }
    }

    // Last chance: only one bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // is large and would leave a bad residual in existing bins, or when no bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // large items pair well with a fresh bin (room for companions)
        if item_size >= 50 {
            score -= 25.0;
        }
        // many open bins with slack -> discourage new bins
        score += 2.0 * open_bins_count as f64;
        // early in stream, new bins are cheap; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // prefer bins whose residual is tight relative to mean residual
        score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Modulo threshold on item_size: items in [10..=20] are flexible fillers,
    // reward placing them anywhere that keeps residual harmonic (multiple of 10).
    if item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Gap too small for the minimum item: pure dead space.
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 20 {
            // Likely dead space given typical minimum sizes.
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to residual (fill ratio of the placement).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bins pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && (post_residual as f64) < 20.0;
        if poor_fit {
            score -= 55.0; // opening fresh bin beats leaving a dead gap
        } else {
            score += 35.0 + 5.0 * open_bins_count as f64; // keep using open bins
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates a gap the next item cannot use
    }

    // Mild preference for bins whose residual deviates favorably from the mean.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: minimize post_residual (tight fit), but not to the
    // point of leaving dead space that cannot host the next item.

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards -> strong reward proportional
            // to how snugly the next item would nest.
            let nest_tightness = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * next_item_size as f64 - 0.2 * nest_tightness;
        } else {
            // Post residual becomes dead space w.r.t. the next item:
            // penalize proportionally to wasted capacity.
            score += 0.6 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "almost full" -> prefer filling them to close them out.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.8 * (mean_residual - res);
    } else {
        score += 0.4 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.3 * item_size as f64;
        // Early in the stream, new bins are cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Slight preference for using more of the current bin (waste minimization).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space: small post_residual is good, but tiny unusable
    // slivers (< 10, min item size) are wasted either way — slight penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize placements that leave residual too small for the
    // next item but nonzero (blocking useful residual).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            score -= 8.0; // next item still fits here — good chaining
        } else if post_residual > 0 {
            // residual becomes dead unless tiny
            score += 0.35 * (nr - post_residual as f64);
        }
    }

    // New-bin candidate logic: empty bin should only win when the item fits
    // poorly everywhere else. Base new-bin score on raw post_residual (high
    // for empty bin = capacity - item), so add penalty that decays with
    // scarcity of fitting bins and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        score += 30.0 * (1.0 - 0.5 * progress) * scarcity;
    } else {
        // Prefer reusing bins with larger residuals (keep tight bins for
        // small future items): mild reward proportional to bin_residual.
        score += 0.10 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let fit_norm = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear amplification of tight fits.
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm);

    // Reward tight fits more strongly as the stream progresses (smooth coupling).
    score -= (1.0 - fit_norm) * (1.0 - fit_norm) * (20.0 + 30.0 * progress);

    // Penalize dead space that is too small for typical future items: smooth valley
    // around small-but-unusable residuals. Use next_item_size when available.
    let nxt = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        score += 10.0 * (1.0 - gap / cap).abs() * (pr / cap);
        // Reward leaving room for the lookahead item (smooth, not piecewise).
        score -= 15.0 * (1.0 - gap / cap).max(0.0) * (1.0 - pr / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin, smoothly more
    // when existing bins are underutilized (high mean residual) or late in stream.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) / (1.0 + mean_residual / cap.max(1.0));
        score += 30.0 + 25.0 * progress + 5.0 * crowding;
        // But soften the penalty if the item is large (poor fit anywhere).
        let large = item_size as f64 / cap;
        score -= 40.0 * large * large;
    }

    // Mild diversity pressure: many open bins with large residuals -> prefer
    // consolidating into bins above the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10
    let post = post_residual as i64;
    let cap = bin_capacity as i64;
    let r = post % 10;

    // Perfect fits are golden
    if post == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual that no typical item (1..=100) can pair with
    if post > 0 && post < 10 {
        score += 60.0; // tiny sliver = dead space
    }

    // Harmonic reward: residual in "usable" classes (multiples of 5 or 10)
    if r == 0 {
        score -= 25.0; // residual divisible by 10 -> easy to fill
    } else if r == 5 {
        score -= 15.0; // divisible by 5 -> decent
    }

    // Lookahead coupling: does next_item_size divide or fit the post residual?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n == post {
            score -= 200.0; // perfect follow-up fit
        } else if n <= post {
            // harmonic class match: next item keeps residual in a good class
            let nr = (post - n) % 10;
            if nr == 0 {
                score -= 40.0;
            } else if nr == 5 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's residual: mild penalty scaled by gap
            score += ((n - post) as f64) * 0.3;
        }
        // residue pairing: post + next == capacity-like harmony
        if post + n == cap {
            score -= 120.0;
        }
    }

    // Integer division threshold on post_residual: coarse fill tiers
    let q = post / 25; // 0..4 quarters
    score -= q as f64 * 5.0; // prefer bins whose leftover is a large chunk (still reusable)

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else {
        // spread load when many bins fit: prefer tighter bins (base post_residual already does)
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost,
    // unless current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin when open bins are fairly full; penalize opening early
        score += 30.0 + pressure * 40.0 - (open_bins_count as f64) * 2.0;
        // late in stream, reusing is cheaper
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += t * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste. Penalize hard as post_residual approaches the unusable zone.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Moderate dead space (hard to fill but not impossible) gets a softer penalty.
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0 * (1.0 - (post_residual - 10) as f64 / 20.0);
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 8.0 / (1.0 + tightness);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: penalize so it only wins when all open bins fit badly.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if the item fits perfectly in a fresh bin, soften the penalty.
        if item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Lookahead: favor bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness reward: prefer minimal post_residual, with slight superlinearity.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // 2-step lookahead: strongly reward when the NEXT item fits into the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how well next item fills the leftover space.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Perfect 2-step fill: near-zero total leftover across two placements.
            if slack == 0.0 {
                score -= 50.0;
            }
        } else {
            // Next item cannot use the leftover: dead space penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" bins;
    // placing there is good (consolidation). Bins far above mean are wasteful.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so mid-stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is even more wasteful.
        if total_items > 0 {
            score += 30.0 * (step_index as f64 / total_items as f64);
        }
        // But if the item is large and leaves little residual, a fresh bin is fine.
        score -= 0.6 * (post_residual as f64).max(0.0);
    }

    // Slight penalty for very small unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize leaving dead space that nothing can ever use well.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0 * (1.0 - gap as f64 / 100.0);
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Creates a sliver the next item cannot use: penalize.
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item fits poorly everywhere (large post_residual in any open bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with progress (waste more costly later).
        let mut new_bin_cost = 30.0 + 40.0 * progress;
        // If many bins are open and mean residual is high, prefer reusing them.
        new_bin_cost += (mean_residual / 10.0).min(20.0);
        // If the item is huge, a fresh bin is a natural home.
        if item_size >= 70 {
            new_bin_cost -= 20.0;
        }
        // If no other bin fits (this call is the only fitting one = fresh bin),
        // the cost is unavoidable; soften it.
        if fitting_bins_count == 0 {
            new_bin_cost -= 45.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for filling already-open bins rather than spreading load:
    // penalize bins whose residual is far above mean (they are underused).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Slight global pressure: when many bins are open, discourage opening more
    // (already handled) and encourage consolidation into emptier bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: post residual, mildly discounted by stream progress (late stream tolerates tight fits)
    let mut score = pr * (1.0 - 0.35 * progress * progress);

    // Non-linear coupling: reward filling bin tightly, quadratic in fit ratio
    score -= 18.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = ((nx - pr) / cap).max(0.0);
        score += 30.0 * waste * waste / (1.0 + pr / cap);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Prefer bins below mean residual (consolidate emptier bins) via smooth cubic term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.signum() * 0.5 + 4.0 * dev;

    // Mild penalty for opening new bins when many are open and item fits existing
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space: small post_residual that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward tight fits (perfect packing classes)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer division thresholds: post_residual in "useful" bands
    let band = post_residual / 25; // 0..4 harmonic band
    score -= band as f64 * 5.0;

    // Modulo coupling: post_residual mod 10 — residuals divisible by 10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else {
        score += 3.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra reward for near-exact chain fit
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit: this residual becomes dead-ish unless large
        if post_residual < 20 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New bin candidate handling: only prefer it if current residual is very small
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // bias toward new bins slightly when open bins are fragmented
        score += 10.0 + mean_residual * 0.1 + progress * 5.0;
    } else {
        // reward using existing bins relative to mean residual
        score -= (mean_residual - pr) * 0.05;
    }

    // Waste fraction coupling: penalize proportion of capacity wasted
    score += (pr / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for small unusable gaps (cannot fit even the
    // smallest plausible item), scaled by how close post_residual is to the
    // danger zone (1..~20).
    if post_residual > 0 {
        let dead = (20u32).saturating_sub(post_residual) as f64;
        score += 3.5 * dead;
    }

    // Perfect / near-perfect fits get a big reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward using a bin whose residual was large (avoid fragmenting fresh space)
    // but only when the fit is reasonably tight relative to residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.7 {
        score -= 8.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residual below the mean residual (filling emptier-ish bins
    // keeps large residuals available for large future items).
    if (post_residual as f64) > mean_residual {
        score += 2.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would NOT fit but post_residual is small anyway, minor bonus.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score -= 3.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a good fit. Penalize the empty bin mildly so tight fits beat it,
    // but not so much that a bad fit (large post_residual) beats it.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Late in the stream, prefer reusing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits the post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits after placement -> strong reward, scaled by how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit -> penalize wasted residual
            score += 8.0;
        }
        // Perfect 2-step match: post_residual exactly equals next item
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below/at mean (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize very small dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: neutral-ish score; only attractive when fits are poor
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // later in stream, slightly discourage opening new bins if fits exist
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted space is quadratic in dead space).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tight * tight;

    // Penalize small unusable post-residuals (dead space < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: reward if next item can use the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // Penalize if post-residual is just barely too small for the next item.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 6.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score -= 0.15 * open_bins_count as f64 * tight;

    // Prefer bins below mean residual (fill emptier bins less, keep big gaps).
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 1.5;
    }

    // Time horizon: early in the stream, be more willing to spread (mild);
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tight;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 * desperation + 5.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // fresh bin pairs poorly with the upcoming item chain
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 30.0 * poly * (1.0 - progress);

    // Penalize dead space more as the stream progresses
    score += 20.0 * norm_pr * norm_pr * progress;

    // Tight fits are valuable: reward small normalized post_residual non-linearly
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when item leaves awkward residual vs typical residual
    if bin_residual == bin_capacity {
        let awkward = (norm_pr - 0.3).abs();
        score += 10.0 * awkward + 5.0 * progress;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 * (next_item_size as f64 / cap);
    }

    // Coupling with mean residual: avoid bins far from the mean when mean is low
    score += 3.0 * (mean_residual - pr).abs() / cap * (1.0 - progress);

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward small-but-usable residuals.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 30.0;

    // Harmonic class of post_residual: residuals divisible by small classes
    // (e.g. multiples of 10) pair well with common item sizes -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 5 == 0 {
            score -= 3.0;
        }
        // Dead zone: residuals that almost no item can use (1..=9 gap)
        if pr < 10 {
            score += 25.0;
        }
        // Harmonic sweet spots: residual in ranges matching typical item sizes
        if pr >= 10 && pr <= 80 {
            score -= 6.0;
        }
    }

    // Perfect fit: absolute best.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this placement is part of a perfect chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 5.0;
        }
        // Harmonic pairing: next_item_size divides residual nicely
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 15.0; // finishing a bin completely is great
        }
    }

    // New-bin candidate handling: opening a new bin is penalized unless the
    // current fit is very poor or stream is early with many bins open.
    if bin_residual == bin_capacity {
        // new empty bin baseline: moderately high score so it only wins
        // when open-bin fits are bad.
        score = 55.0 + frac * 10.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item: fresh bin may be wise
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 4 && progress < 0.5 {
            score += 10.0; // avoid bin proliferation early
        }
    }

    // Spread-awareness: prefer bins whose residual is close to the mean
    // (keeps residuals homogeneous and combinable).
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.15;

    // Small bonus for using fuller bins (low residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are the worst
    // outcome (unusable gap). Penalize gaps in the "dead zone" [1, 15].
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - pr) * 12.0; // smaller gap => harsher penalty
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Moderate leftover that can plausibly host the next item is mildly rewarded.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // If leftover cannot fit the known next item, penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size as f64 - pr) * 0.5;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate gets residual == capacity == 100, so add a surcharge
    // scaled by open_bins_count to bias toward existing bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But allow new bin when existing bins would leave big dead space anyway.
        if pr_mean_gap_ok(mean_residual) {
            score -= 15.0;
        }
    } else {
        // Mild bonus for using a bin that is already relatively empty (consolidation).
        score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

// Helper-free inline check replaced: keep everything in one function instead.
#[inline(always)]
fn pr_mean_gap_ok(_m: f64) -> bool { false }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits, but leaves more dead space — mild penalty proportional to slack
            score += 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here: penalize relative to how much it overshoots
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of waste
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize large dead space that can never fit typical items
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny residual is nearly a perfect fill
    }

    // Early in the stream, be more willing to spread items (favor low post_residual less aggressively)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    // New-bin candidate: make empty bins mildly attractive only when open bins are scarce or fit is poor
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else {
            score += 150.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space, especially small unusable slivers
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 30.0; // tiny dead space is nearly useless
        }
        // Reward leaving space usable by the next item (lookahead)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        }
        // Penalize residual that no plausible item can use later
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter ones
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: penalize unless current item is large or no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit_exists = fitting_bins_count > 0 && (bin_residual - item_size) as f64 <= mean_residual;
        let mut open_cost = 60.0;
        // Early in stream, opening bins is cheaper; late, prefer packing into existing
        open_cost *= 0.5 + 0.8 * progress;
        // Large items are hard to place later; new bin may be fine
        if item_size > bin_capacity / 2 {
            open_cost -= 25.0;
        }
        // If next item is big, a fresh bin helps
        if next_item_size > bin_capacity / 2 {
            open_cost -= 15.0;
        }
        if tight_fit_exists {
            open_cost += 20.0;
        }
        score += open_cost;
    } else {
        // Prefer filling bins that are already relatively full (low residual)
        score += 0.3 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);
        // Reward using bins whose residual is close to item size (tight fit)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 10.0 * tightness;
    }

    // Mild preference to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits, non-linearly (quadratic in post_residual)
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Stream-progress coupling: penalize wasted space more as stream advances
    let waste_penalty = (pr / cap) * (pr / cap);
    score += progress * 25.0 * waste_penalty;

    // Penalize residuals too small to fit typical future items (dead space)
    let dead = ((cap * 0.15 - pr).max(0.0)) / cap;
    score += 40.0 * dead * dead;

    // Reward when this bin can also fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalty if lookahead barely misses
        let miss = (next_item_size as f64 - pr) / cap;
        score += 10.0 * miss;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild preference for consolidating into bins below mean residual (balancing)
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Encourage using existing bins as stream progresses over opening new ones
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual by integer
    // division into capacity-fraction buckets. Residuals in "usable" classes
    // (>= 1/4 of capacity) are worth keeping; tiny residuals are dead space.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic class
    match class {
        0 => score += 60.0,                 // dead space (< 1/8 capacity)
        1 => score += 25.0,                 // barely usable
        2 | 3 => score -= 5.0,              // quarter-class: good
        4 | 5 | 6 => score -= 10.0,         // half-class: excellent
        _ => {}                             // near-empty bin
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // harmonic slot, reward strongly; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if post_residual >= next_item_size && post_residual - next_item_size < eighth {
                score -= 40.0; // next item fills this bin almost perfectly
            } else {
                score -= 10.0;
            }
        } else {
            score += 15.0; // leftover can't host next item
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only choose a fresh bin when the current
    // item would leave a bad harmonic class in every existing bin, or when
    // no bins exist. Otherwise make the fresh bin unattractive.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        } else {
            // Fresh bin attractive only if item is large and would leave a
            // "clean" half-class residual, and existing bins are fragmented.
            let fresh_left = bin_capacity - item_size;
            if fresh_left >= quarter && mean_residual < quarter as f64 {
                score -= 30.0;
            } else {
                score += 120.0;
            }
        }
    }

    // Prefer bins whose residual is below the mean (fill the emptiest of the
    // tight bins first keeps many mid-size residuals available).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild stream-phase term: late in the stream, consolidate aggressively.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small gaps that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap -> extra dead-space pressure.
        score += 6.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.15 * pressure * (1.0 - fill_ratio);

    // Deviation from mean residual: prefer bins that are notably fuller than average.
    if bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate: penalize mildly so it wins only when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if current item is large relative to mean residual, opening is fine.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits here too: favor leaving space usable by it,
            // scaled by how snug the combined fit is.
            let snug = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += 12.0 + 0.15 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare residual against mean residual of open bins:
    // prefer bins with smaller residual (tighter packing).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate: mild penalty so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize large post-residuals that are too small to be useful later.
    if post_residual > 0 {
        let smallest = 1.0;
        if (post_residual as f64) < smallest {
            score += 30.0; // dead space: unusable gap
        }
    }

    // Reward tight fits.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Exact match with next item is great.
        if next_item_size as u32 == post_residual {
            score -= 15.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / cap);
    score -= 6.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Compare against mean residual: avoid bins that deviate wildly upward.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in stream, be more willing to open new bins (spread load);
    // late in stream, consolidate tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as time progresses (favor consolidation),
        // but early on allow it when current bin fit is poor.
        score += 20.0 + 30.0 * t;
        if tightness < 0.5 {
            score -= 10.0 * (1.0 - t);
        }
    }

    // Small bonus for perfectly filling the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr_norm * (1.0 + 0.8 * pr_norm * pr_norm);

    // Stream-progress coupling: as stream advances, penalize large residuals more strongly
    score += 0.6 * progress * pr_norm * pr_norm;

    // Dead-space penalty: residuals too small to fit typical items (below min item size 10)
    let dead = ((10.0 - pr) / cap).max(0.0);
    score += 1.5 * dead * dead;

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.5 * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // Slight preference for bins with residuals below mean (consolidate waste)
    score += 0.15 * (pr_norm - mean_residual / cap).abs();

    // Mild pressure against opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 0.3 + 0.2 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals that are exact divisors
    // of the capacity (or near-divisor classes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let class = if bin_capacity % pr == 0 {
            -12.0 // perfect harmonic class: leftover can be exactly filled later
        } else if pr <= 10 {
            -6.0 // tiny leftover but still very reusable
        } else {
            let half = pr / 2;
            if bin_capacity % half.max(1) == 0 { -4.0 } else { 0.0 }
        };
        score += class as f64;

        // Dead space penalty: leftovers below the minimum item size are waste.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // Non-harmonic mid residuals are the worst kind of dead space.
        if pr > 10 && bin_capacity % pr != 0 {
            score += (pr as f64) * 0.35;
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // partial credit scaled by how well it fits
            let fit_ratio = next_item_size as f64 / pr as f64;
            score -= 18.0 * fit_ratio;
        } else {
            // next item cannot use this leftover: penalize large wasted leftovers
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score = cap * 0.85;
        // If many bins already fit the item, opening a new bin is bad.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 8.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If only this new bin fits, allow opening it (remove the barrier).
        if fitting_bins_count == 0 {
            score -= cap * 0.9;
        }
    }

    // Mild preference for tighter bins overall.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, or below min item size) are unusable.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 25 {
        score += (26.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: penalize adding bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but avoid opening new bins
    // when mean residual across open bins is large.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.5;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would be blocked by post_residual being a small gap, penalize.
    if next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item fits within post_residual, mild reward proportional to fit quality.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Penalize if post_residual cannot fit the next item (dead space risk).
    if next_item_size > post_residual {
        score += 4.0;
    }

    // Penalize wasted space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Slight preference for filling bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted space is quadratic-ish).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space if it cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 4.0; // next item may chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual below mean (fill the emptier-tail bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize unless current bin would leave unusable scrap.
    if bin_residual == bin_capacity {
        let scrap_penalty = if next_item_size > 0 && post_residual < next_item_size {
            0.0
        } else {
            20.0
        };
        score += 35.0 - scrap_penalty - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling: reward small post_residual non-linearly
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize dead space that cannot fit plausible future items (smooth ramp)
    let dead = if next_item_size > 0 {
        (next_item_size as f64 - pr).max(0.0) / cap
    } else {
        0.0
    };
    score += 60.0 * dead * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: smooth exponential reward when few fitting bins
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 25.0 * last_chance * (1.0 - norm_pr);

    // Prefer bins tighter than mean residual (smooth quadratic divergence)
    let diff = (mean_residual - bin_residual as f64) / cap;
    score += 15.0 * diff * diff;

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 30.0 * (0.3 + 0.7 * progress) * (1.0 + open_bins_count as f64 / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible into small
    // denominations are more reusable than awkward primes.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for d in [1u32, 2, 4, 5, 10, 20, 25, 50].iter() {
            if pr % *d == 0 {
                reuse_bonus += 3.0;
            }
        }
        score -= reuse_bonus;
        // Penalize prime / awkward leftovers via integer-division thresholds
        if pr % 10 != 0 {
            score += 8.0;
        }
        if pr % 7 == 0 || pr % 11 == 0 || pr % 13 == 0 {
            score += 6.0;
        }
    }

    // Capacity fraction classes: exact halves/quarters are premium fits.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if (frac - 0.5).abs() < 1e-9 { score -= 12.0; }
    else if (frac - 0.25).abs() < 1e-9 || (frac - 0.75).abs() < 1e-9 { score -= 6.0; }

    // Lookahead coupling: does the leftover accommodate the next item's class?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // harmonic alignment: leftover divisible by next item's decile class
            let next_class = (next_item_size / 10).max(1);
            if pr % next_class == 0 {
                score -= 4.0;
            }
        } else {
            // leftover too small for next item: dead space penalty grows
            score += 5.0 + (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when this item is
    // large and current bins would leave highly fragmented space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if item_size > 60 && fragmentation > 20.0 {
            score -= 5.0;
        } else if fitting_bins_count > 0 {
            score += 10.0 + 10.0 * progress;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    // Tight fit reward: exact or near-exact fills are best.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Reward leaving gaps that still fit plausible small items.
        score -= (post_residual as f64 / 10.0).floor() * 2.0;
    }

    // Last-chance pressure: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates dead space for the known next item
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmenting).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // New-bin candidate: prefer it only when it avoids a very poor fit.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: decent residual (100 - item) minus a fixed
        // opening cost so we only open when existing bins score worse.
        score = (bin_capacity - item_size) as f64 + 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover space exactly matches the next item (2-step lookahead match).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect match bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual near the mean (balanced packing),
    // penalize extreme outliers slightly.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Early in the stream, be slightly more willing to open new bins (spread items);
    // late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later and when many bins are open.
        score -= 20.0 * (1.0 - progress);
        score += 15.0 * progress;
        score += 2.0 * open_bins_count as f64;
        // Don't open a new bin if current bin would end up nearly full (good fit).
        if post_residual <= 10 {
            score += 50.0;
        }
    } else {
        // Tight-fit reward for existing bins: small post_residual is good.
        if post_residual <= 5 {
            score -= 15.0;
        }
        // Penalize very full bins slightly less than wasteful ones as stream progresses.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let w = 1.0 + 0.6 * progress - 0.4 * progress * progress;
    score += w * 40.0 * pr_norm * pr_norm;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = ((ns - pr) / cap).max(0.0);
        score += 25.0 * waste * waste;
        // Reward residuals that exactly accommodate the next item.
        let match_term = 1.0 - ((pr - ns) / cap).abs();
        if match_term > 0.0 {
            score -= 15.0 * match_term * match_term;
        }
    }

    // Reward tight fits (small post-residual relative to item).
    score -= 20.0 * fit_ratio * (1.0 - pr_norm);

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize so it's chosen only for poor fits,
    // with the penalty easing as the stream progresses.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.5 * progress);
    }

    // Smooth coupling with mean residual: prefer bins below mean (tighter).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left after placement

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space (< 10) is nearly unusable for items >= 10: penalize mildly.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic class via integer division: residuals in [0,10), [10,25), [25,50), [50,100)
    let class = post_residual / 25;
    score -= match class {
        0 => 40.0,               // tiny leftover: only good if exactly 0
        1 => 10.0,               // moderate
        2 => 0.0,                // half-full-ish: fine
        _ => 5.0,                // near-empty bin: wasteful placement
    };

    // Modulo coupling: residuals divisible by common item sizes (10/20/25/50) are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: reward when next item fits exactly in post_residual (harmonic chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin: penalize large leftover fractions
            score += 20.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; discourage unless item leaves a "clean" harmonic residual.
        let clean = item_size % 10 == 0;
        score += if clean { 45.0 } else { 80.0 };
        // Late in the stream, opening bins is less attractive (waste carries to the end).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer bins tighter than the mean residual (good packing progress).
    score += 0.3 * (pr - mean_residual);

    // Mild preference for fewer open bins when fit is tight.
    if post_residual < 15 {
        score -= 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any plausible item (<=9)
    // are pure waste; penalize them heavily.
    if post_residual <= 9 {
        score -= 40.0; // perfectly closed or near-closed bin is great
    } else if post_residual < 20 {
        // small dead zone: unlikely to be filled later
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    // (favor closing bins / fewer open bins) mildly.
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate handling: only attractive when the item is large
    // relative to what open bins can absorb, or no real bin is decent.
    if bin_residual == bin_capacity {
        let next_pressure = if next_item_size > 0 {
            // opening now leaves room for the next item too?
            (post_residual >= next_item_size) as i32 as f64
        } else {
            0.0
        };
        // base penalty so a new bin is only chosen when placements are bad
        score += 25.0;
        // if next item fits comfortably in this fresh bin, ease the penalty
        score -= next_pressure * 10.0;
        // late in the stream, new bins are less useful (less time to fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // reward keeping this residual; if next item can't fit, penalize mildly.
    if next_item_size > 0 && bin_residual < bin_capacity {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (compactness).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect matches of post_residual to next_item_size (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0) * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Exact match bonus: item + next item fill the bin exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize post_residual too small for the next item (dead space for lookahead).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0;
    }

    // Reward bins that are already substantially filled (low residual relative to mean).
    let fill_ratio = (bin_residual as f64) / bin_capacity as f64;
    score -= 8.0 * (1.0 - fill_ratio);

    // Penalize bins far above mean residual (wasteful choice).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could fit, unless the item is large
    // and would leave an awkward residual.
    if bin_residual == bin_capacity {
        let awkward = (bin_capacity - item_size) as f64;
        let next_fits = next_item_size > 0 && awkward >= next_item_size as f64;
        let mut new_bin_score = 25.0 + 0.2 * awkward;
        if next_fits {
            new_bin_score -= 10.0;
        }
        // Later in the stream, slightly discourage proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 10.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness * (0.5 + fit_ratio);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover
            score += 4.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    } else {
        // Last item: minimize waste entirely.
        score += 5.0 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowd control: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.3 + progress);

    // Compare against mean residual: prefer bins whose residual deviates
    // favorably (using bins with less residual keeps big holes available).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual < 10 { 1.0 } else { 0.0 };
        let no_alt = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 18.0 - 12.0 * bad_fit - 10.0 * no_alt - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space quadratically, stronger late in stream
    score += 2.0 * post_norm * post_norm * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item)
    score -= 6.0 * (1.0 - post_norm) * fit_ratio * cap * (1.0 - progress * 0.5);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward bins whose post residual matches next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs() / cap;
        score -= 3.0 * (1.0 - gap) * (1.0 - gap) * (1.0 + progress);
        // Penalize if post residual cannot fit next item (wasted lookahead)
        if post < nx {
            score += 2.0 * (nx - post) / cap * cap * 0.1;
        }
    }

    // Mild preference for bins deviating from mean residual (balance preservation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * 0.1;

    // Discourage opening new bins when decent fits exist, more so early
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes are more likely to become dead space; penalize them.
    let r = post_residual;
    let r_mod = (r % 10) as f64;
    let r_div = (r / 10) as f64;

    // Fine-grained dead-space penalty for awkward leftovers (1..=9 units).
    if r > 0 && r < 10 {
        score += (10 - r) as f64 * 2.5;
    }

    // Reward leftovers that sit in "useful" harmonic classes (multiples of 10,
    // or leftovers large enough to host typical next items).
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    }
    if r >= 40 && r <= 70 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it nearly fits, mildly penalize the near-miss.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 12.0;
        } else if next_item_size < r {
            let slack = (r - next_item_size) as f64;
            score -= (10.0 - slack.min(10.0)) * 0.8;
        } else {
            // next item cannot fit here: penalize proportionally to the miss
            score += ((next_item_size - r) as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // New-bin candidate handling: prefer an empty bin only when existing
    // residuals are fragmented and mean residual is low relative to item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.55
            + mean_residual * 0.3
            - progress * 5.0
            + open_bins_count as f64 * 0.4;
        // If the item is large, opening a fresh bin is more attractive.
        score -= item_size as f64 * 0.25;
    }

    // Tie-breaking nudge toward tighter fills using integer-division classes.
    score -= r_div * 0.15;
    score += r_mod * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
