pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer tight fits (small post_residual), with superlinear penalty on waste.
    score += 0.35 * post * post / cap;

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap < 1.0 {
            score -= 60.0; // perfect chain: next item exactly consumes leftover
        } else if post >= nxt {
            // next item fits: reward proportional to how much it consumes
            score -= 25.0 * (nxt / post.max(1.0));
            // extra reward if it leaves near-zero again
            let post2 = post - nxt;
            if post2 < 5.0 { score -= 20.0; }
        } else {
            // next item cannot use this residual: penalize proportionally to gap
            score += 0.5 * gap.min(40.0);
        }
    }

    // Compare against mean residual: bins tighter than average are precious.
    if post < mean_residual {
        score -= 8.0 * (mean_residual - post) / cap;
    } else {
        score += 6.0 * (post - mean_residual) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is huge or residual is unusable.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // penalize opening a new bin for small items; allow for large ones
        score += 30.0 - 25.0 * fill_frac;
        if next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
