            score -= 10.0;
        } else {
            // Penalize leaving a residual that wastes space relative to the next item.
            let waste_gap = (next_item_size - post_residual) as f64;
            score += 0.15 * waste_gap;
        }
    }

    // Penalize opening new bins when there are many open bins with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_slack = mean_residual.max(0.0);
        score += 10.0 + 0.1 * open_bins_count as f64 + 8.0 * (1.0 - progress) * (avg_slack / bin_capacity as f64);
        // But near the end of the stream, a fresh bin is less costly.
        if progress > 0.9 {
            score -= 6.0;
        }
    }

    // Mild preference for bins with below-average residual (pack tighter bins first).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.05 * diff;

    // Slight bias toward fuller bins as stream progresses.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * fill_ratio * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Stream-progress coupling: later in stream, dead space matters more
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += post * post / cap * (0.5 + progress_coupling);

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - norm_post;
    score -= item_size as f64 * fit_quality * fit_quality * 0.3;

    // Last-chance bonus: only fitting bin -> strong reward
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_quality;
    }

    // Penalize bins whose residual deviates from mean residual (keeps pool uniform)
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev;

    // Lookahead: if next item fits in post-residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 8.0 * (1.0 - (post - nx) / cap);
        } else {
            score += 3.0 * ((nx - post) / cap);
        }
    }

    // Mild penalty for opening new bins when many bins are open and fit exists
    if bin_residual == bin_capacity {
        score += 6.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small dead space is good, but
    // perfectly zero residual is best. Bucket post_residual by capacity/8.
    let class = post_residual / (bin_capacity / 8);
    score += match class {
        0 => -40.0,                       // near-perfect fit
        1 => 10.0,
        2 => 20.0,
        3 => 25.0,
        _ => 0.0,
    };

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead synergy: if the next item exactly fills the post residual,
    // this bin is a chain; reward heavily. Penalize if next item cannot
    // use the leftover (wasted dead space given lookahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: does next item divide/align with residual?
            let compat = post_residual % next_item_size.max(1);
            if compat == 0 {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            // next item can't fit here; leftover likely dead space unless small
            if post_residual < 10 {
                score += 5.0;
            } else {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 35.0;
        if post_residual > bin_capacity / 2 {
            score += 25.0; // fit is poor; soften the reward
        }
    }

    // New-bin candidate: empty bin. Prefer keeping it pristine unless all
    // open bins fit poorly. Penalize opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits anywhere: must open
        }
    }

    // Modulo harmonic class on item_size: items that align with capacity
    // (divisors / multiples classes) pack better into tight bins.
    let harm = bin_capacity % item_size.max(1);
    if harm == 0 {
        score -= 8.0;
    }

    // Mean residual coupling: when mean residual across open bins is large,
    // we can afford looser fits; when small, be greedy about tight fits.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Late in stream: prefer closing bins (small post residual) more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps (below min item size) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Prefer bins whose residual is "consumed" proportionally well.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here: post residual likely dead space
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, consolidation is fine.
    score += 2.0 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: attractive early, or when the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64 && item_size < 50;
        if poor_fit || progress < 0.15 {
            score -= 45.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving a gap that is too small for any plausible future item (dead space).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Reward bins tighter than the mean residual (good compact fits).
    let mean_res_u = mean_residual;
    if (post_residual as f64) < mean_res_u {
        score -= (mean_res_u - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_res_u) * 0.3;
    }

    // New-bin candidate: only attractive when nothing fits well (large item relative to residuals).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win; reduced when stream is late
        // and open bins are fragmented (high mean residual spread).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin perfectly fits the next item too; make it attractive then.
            if item_size + next_item_size >= bin_capacity {
                score -= 30.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space non-linearly: small residuals are hard to fill later.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 40.0 / (pr * pr).sqrt();
    }

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement;
    // if post-residual is too small for the next item, penalize creating unusable space.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 10.0 * (ni / 100.0);
        } else {
            score += 8.0 * (1.0 - ni / 100.0);
        }
    }

    // Global state coupling: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, so it gets penalized).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (open_bins_count as f64 / 20.0).min(1.0);
        score += 6.0 + 18.0 * congestion * (1.0 - progress);
        // But late in the stream, a fresh bin's big residual is less valuable anyway.
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is close to mean residual (keep residuals balanced),
    // with a mild pull toward using bins with larger residuals first.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * diff;

    // Slight preference for fuller bins early (best-fit flavor).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr + 20.0 * poly;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let waste = gap / cap;
            score += 15.0 * waste * waste * (1.0 - progress);
        } else {
            // next item fits exactly in the leftover: reward
            score -= 8.0 * (-gap / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only option
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress;
    }

    // Slight preference for bins below mean residual (balances load)
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0.0 .. 1.0

    // Integer-division thresholds on post_residual: class 0 = tiny dead space (great),
    // higher classes = increasingly unusable space.
    let class = (post_residual / 10).min(10) as f64;
    score += 6.0 * class;

    // Modulo arithmetic: residues near multiples of 10 are "harmonic" — they pair
    // well with typical item granularities. Penalize odd/unharmonic leftovers.
    let m = post_residual % 10;
    if m == 0 {
        score -= 12.0;
    } else if m <= 3 || m >= 7 {
        score += 4.0;
    } else {
        score += 1.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward when next item exactly fits the post residual (harmonic chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // favor chains that keep post residual in a good class
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score += next_post as f64 * 0.3;
        } else {
            // next item won't fit here; penalize more if this bin is the only option
            if fitting_bins_count == 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline slightly above decent fits, but beats
    // very poor fits (large post_residual classes).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * mean_residual;
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Reward tight fits (small post_residual relative to item size).
    score -= (item_size as f64) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.6;

    // Prefer bins below mean residual (pack fuller bins together).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Lookahead: reward leaving space for the next item if it fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // New-bin candidate: neutral baseline with mild penalty so it is chosen
    // only when open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
            // penalize leftover after hypothetical next placement
            let left2 = post_residual - next_item_size;
            if left2 < 10 {
                score += 15.0; // dead space after two placements
            }
        } else {
            // next item won't fit here after this placement
            score += 8.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let resid_f = bin_residual as f64;
    score += 0.35 * (resid_f - mean_residual);

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty, relaxed when few fitting bins
        let pressure = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += 30.0 + 10.0 * pressure;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild penalty for waste proportional to post residual squared (dead space growth).
    score += 0.02 * (post_residual as f64).powi(2) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
