pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // in [0,1]
    let p2 = norm_post * norm_post;
    let p3 = p2 * norm_post;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = post
        - 30.0 * p2 * (1.0 - norm_post)
        + 20.0 * p3 * progress;

    // Early stream: keep residuals large/flexible; late stream: consolidate tightly.
    score += 15.0 * (1.0 - progress) * p2;

    // Dead-space penalty: residuals too small to fit typical future items.
    if post < next_item_size as f64 && next_item_size > 0 {
        score += 10.0 + 0.3 * (next_item_size as f64 - post);
    }

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for scattering across many open bins vs mean residual alignment.
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (post - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, favored when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead" (unusable by
    // typical small items) get penalized. Classes mod 10.
    let dead = post_residual % 10;
    let dead_penalty = match dead {
        1 | 2 | 3 => 6.0,
        4 | 5 => 3.0,
        6 | 7 => 1.5,
        _ => 0.0,
    };
    score += dead_penalty * (post_residual as f64 / 10.0);

    // Perfect fit reward: strong harmonic alignment with capacity fractions.
    if post_residual == 0 {
        score -= 100.0;
    } else if bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 2 {
        // residual is an exact divisor class of capacity (e.g. 50, 25, 20, 10)
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // penalize wasting space the next item could otherwise use elsewhere
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.3;
            if slack % 10 == 0 {
                score -= 4.0; // aligned slack class is reusable
            }
        } else {
            // next item cannot fit here; residual becomes a waiting class
            score += 2.0;
            if post_residual < 10 {
                score += 10.0; // true dead space
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Prefer tighter bins overall: reward below-mean residuals.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    // Integer-division threshold on item_size: large items prefer near-full bins.
    if item_size / 20 >= 3 && post_residual <= 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln1p() * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate: penalize moderately so it's chosen only when all
    // open bins offer bad fits (dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize if next item can't fit in post-residual but could fit elsewhere better.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins whose residual is already below average (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step match: this bin's leftover becomes next item's perfect fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // leftover can still host the next item: mild reward proportional to snugness
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space: next item cannot fit in the leftover -> penalize
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Prefer tight fits overall: small post_residual relative to mean residual is good.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score -= 0.25 * (mean_r - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when decent existing options exist.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - item_size as f64 / bin_capacity as f64;
        score += 25.0 * tightness;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // a fresh bin can host both current and next item: discount the penalty
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate: favor existing bins over proliferation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Penalize post residual that is too small to ever be useful
    // (dead space below the minimum plausible future item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // next item won't fit here: mild penalty, this bin becomes dead-ish
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // many alternatives: slightly discourage hoarding in this one
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large and open bins would waste a lot of space.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // baseline cost of a fresh bin: capacity of unused space
        score = (bin_capacity - item_size) as f64;
        // discourage new bins early / when few bins exist
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 20.0 + open_bins_count as f64 * 1.5;
        // if a decent fit exists elsewhere (post residual small), punish new bin more
        if post_residual == 0 {
            score += 0.0; // exact fit in new bin is fine
        }
        // reward new bin when mean residual of open bins is small (all bins tight)
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
        // if next item is large and wouldn't fit typical residual, new bin helps
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global balance: prefer bins with residual above the mean (spread usage evenly)
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.15;

    // Slight time-varying exploration: as the stream progresses, be greedier
    // about tight fits (weight fit more) and less tolerant of slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= fit_ratio * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly relative to remaining capacity
    let progress_coupling = pr * (0.8 + 1.2 * progress * progress);
    score += 0.35 * progress_coupling;

    // Reward filling a bin almost completely, stronger late
    let tightness = (cap - pr) / cap;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: bonus if next item fits the post residual exactly or well
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = pr - ns;
            score -= 4.0 * (1.0 - slack / cap) * (0.6 + 0.4 * progress);
        } else {
            // post residual can't host next item: penalize proportionally
            score += 2.5 * (ns - pr) / cap;
        }
    } else {
        // last item: strongly prefer minimal post residual
        score += 0.5 * pr;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (0.5 + progress);
    }

    // Mean residual context: prefer bins near the mean residual (balanced packing)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: penalize opening a new bin mildly, more when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward exact closure of a bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space class: tiny nonzero residuals are nearly unusable.
    if post_residual > 0 && post_residual <= 3 {
        score += 15.0;
    }

    // Harmonic class: residuals on coarse capacity fractions (multiples of 10)
    // are more likely reusable by future items; mild reward.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 5.0;
    }
    // Odd/bad harmonic classes: residuals in (capacity/4, capacity/3) band are
    // awkward middling slivers; mild penalty.
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    if post_residual > quarter && post_residual < third {
        score += 4.0;
    }

    // Lookahead coupling with next item (k=2).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Next item exactly closes this bin: excellent.
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Leftover is dead space for the next item; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // Next item still fits afterwards; mild reward.
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): add a penalty so that
    // open bins are preferred, growing slightly with stream progress; but if
    // no open bin can fit the item at all, the new bin is the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 20.0 + 10.0 * progress;
        }
    }

    // Mild dispersion term: prefer placing into bins whose residual is above
    // the mean (consolidating space into fewer, tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // an item (min item size 1, but practically < ~10) are pure waste.
    if post_residual > 0 {
        let dead = (post_residual < 10) as f64;
        score += dead * 1000.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness bonus: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize leaving gaps that exactly block mid-size items but reward
    // residuals that can still accommodate typical next items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // are very fragmented or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.5 * open_bins_count as f64 - 2.0 * fill_ratio * 100.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // Late in stream, prefer consolidation into open bins.
        score += 50.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Open-bins pressure: mild reward for filling already-open bins to keep
    // the active set small.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 25.0 * fit_ratio;
    } else if fit_ratio > 0.5 {
        score -= 8.0 * fit_ratio;
    } else {
        // Poor fit: item leaves a large awkward gap -> penalize dead space.
        score += 6.0 * (1.0 - fit_ratio);
    }

    // 2-step lookahead: strongly reward bins whose post residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or near-exactly -> big reward.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will not fit here: mild penalty for blocking.
            score += 4.0 + gap / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer bins that are already fuller than average
    // (consolidate waste into few bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless open bins are all badly fragmented.
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / bin_capacity as f64;
        // Only attractive if existing bins are very full/fragmented (mean residual small)
        // or this is a huge item relative to mean residual.
        let pressure = (item_size as f64 / mean_residual.max(1.0)).min(3.0);
        score += 45.0 - 15.0 * avg_fragmentation - 12.0 * pressure;
        // Late in the stream, avoid opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for fewer open bins overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by the base term,
    // but amplify it super-linearly to strongly prefer near-exact fills.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can fit here: reward keeping room for it.
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - (slack as f64 / bin_capacity as f64));
        } else {
            // Dead space: post_residual too small for the next item.
            let waste = post_residual as f64;
            score += 3.0 * (waste / 100.0) * (waste / 100.0) * 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes (bin_capacity - item_size)
    // of usable space. Only allow it when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // More open bins -> higher chance a future item fits an existing bin,
        // so opening new bins becomes relatively less attractive.
        score -= 1.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If the item is large, a fresh bin wastes little absolute space.
        score -= 0.2 * item_size as f64;
        // If no existing bin fits (fitting_bins_count includes this new bin only),
        // opening is mandatory: make it clearly attractive.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
        // If the next item is also large, a fresh bin gives flexibility.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is below mean residual when the fit is good
    // (consolidate space into fuller bins, keep emptier bins flexible).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 2.0 * diff / bin_capacity as f64;
        } else {
            score += 1.0 * (-diff) / bin_capacity as f64;
        }
    }

    // Mild penalty for very large leftovers that few items can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, slightly compressed non-linearly
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: waste penalized more early, residual-hoarding penalized late
    let tight = 1.0 - norm_pr;
    score += 30.0 * tight * tight * (1.0 - progress);
    score += 20.0 * norm_pr * progress;

    // Reward filling bin tightly when next item fits post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - pr / (next_item_size as f64 + pr));
    } else if next_item_size > 0 {
        // dead-space penalty if next item cannot use the leftover
        score += 8.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (pack big into emptier bins lightly)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate: penalize mildly unless current bins are very full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 40.0 - 60.0 * avg_fill * avg_fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (dead space in {0..3})
    if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class: items whose size divides capacity nicely pair well
    let class = |s: u32| (bin_capacity % s.max(1) == 0) as i32;
    let harmony = class(item_size) + if next_item_size > 0 { class(next_item_size) } else { 1 };
    score -= 8.0 * harmony as f64;

    // Reward leaving room exactly for the lookahead item (perfect pairing)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 35.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space smaller than next item is likely unusable
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 40.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let bad_fit = (post_residual as f64) > 60.0;
        if fitting_bins_count == 0 || bad_fit {
            score -= 55.0 + 10.0 * crowded;
        } else {
            score += 45.0 + 5.0 * crowded;
        }
    } else {
        // Slight preference for bins below mean residual (consolidate waste)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Prefer filling larger residual bins to keep small residuals flexible
        score += 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Late in the stream, tighten packing (avoid spreading)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (post_residual <= 15) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Favor bins whose residual was already fragmented (mean residual low = tight packing).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Open-bin pressure: discourage opening new bins when many bins exist,
    // but allow relief when the stream is nearly done.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if this is a last-chance-free situation
        // or the item leaves a large usable gap relative to typical next needs.
        score += open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 {
            score += 40.0 * (1.0 - progress);
        }
        // Slightly prefer new bin late in the stream when future items are large.
        if next_item_size > item_size.saturating_mul(2) {
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin before opening a new one.
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 12 {
        score -= 20.0;
    }

    // Mild preference for keeping a small number of open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // 2-step lookahead: reward a post-residual that exactly hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain (post_residual == next_item_size) gets a big bonus.
        score -= 45.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: dead space penalty, scaled by how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 12.0 * (miss / 100.0).min(1.0);
    }

    // Penalize leaving residual far below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean residual: prefer bins already below-average residual (consolidation).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so we only open when no decent fit exists,
    // but relax the penalty early in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 20.0 * (1.0 - progress) - 3.0 * open_bins_count as f64;
        // If the next item is huge, opening a fresh bin early can be smart.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Late-stream urgency: consolidate harder as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted space.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 2.5 * fill_ratio * bin_residual as f64;

    // Lookahead: if the next item fits into the post-residual, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }
    // If next item would exactly fill the bin after this placement, huge bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize leaving residual that no typical item can use (dead space).
    if post_residual > 0 && next_item_size > post_residual {
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and existing residuals are small, opening a new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Mild reward for using existing bins as pressure grows.
        score -= 0.05 * open_bins_count as f64;
    }

    // Time horizon: early in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Global coupling: prefer bins whose residual deviates from mean (consolidate).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like
    score += 12.0 * poly * (1.0 - progress) - 8.0 * poly * progress;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 10.0 * (1.0 - pr / nx.max(1.0)) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild penalty for spreading residual far from mean (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * dev / cap;

    // Prefer using existing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    } else {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward placing item into residual in the same size class
    let item_class = (item_size as f64 / cap * 4.0).floor() as u32; // 0..3
    let resid_class = (bin_residual as f64 / cap * 4.0).floor() as u32;
    if item_class == resid_class {
        score -= 30.0;
    }

    // Dead space penalty: post_residual too small for likely future items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when decent fits exist; reward new bin only for big items
    if bin_residual == bin_capacity {
        // new-bin candidate
        if item_size > 60 {
            score -= 60.0;
        } else if open_bins_count > 0 {
            score += 80.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in stream: favor closing out bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
