pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (waste minimization is primary).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or closely matches the next item's size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - next).abs();
        if pr >= next {
            if diff == 0.0 {
                score -= 200.0; // perfect 2-step chain
            } else if diff <= 5.0 {
                score -= 90.0;
            } else if diff <= 15.0 {
                score -= 30.0;
            }
            // Penalize leaving a residual that is too small for the
            // next item but still wasteful (dead space).
            if pr < next {
                score += (next - pr) * 1.5;
            }
        } else {
            // Post-residual can't fit next item: penalize proportional
            // to unusable leftover relative to mean residual.
            score += (next - pr) * 0.8;
        }
        // If next item fits better elsewhere, mildly discourage hogging.
        let mean = mean_residual.max(1.0);
        score += ((pr - mean) / mean) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 - 50.0 * progress;
        if fitting_bins_count > 0 && post_residual as f64 > (bin_capacity as f64 - item_size as f64) * 0.25 {
            score += 60.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * fit_quality * fit_quality;

    // Penalize dead space: residuals too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 25.0;
    }
    // Dead space relative to capacity
    let dead_ratio = (post_residual as f64) / (bin_capacity as f64);
    if dead_ratio > 0.0 && dead_ratio < 0.1 {
        score += 15.0 * (0.1 - dead_ratio) / 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        // More open bins with high residuals => better to use them.
        let congestion = mean_residual / (bin_capacity as f64);
        score += base_penalty * (1.0 - 0.5 * congestion);
        // Early in stream, prefer consolidating; later, allow spreading.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - t);
        // If item is large, new bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // Next item can also go here; mild reward proportional to remaining slack after.
            let after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (after_next as f64) / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for leaving awkward residual.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 8.0;
            }
        }
    }

    // Prefer bins with residual close to item size (best-fit behavior).
    let closeness = 1.0 - ((bin_residual as f64 - item_size as f64) / (bin_capacity as f64)).abs();
    score -= 12.0 * closeness;

    // Encourage balancing residuals toward mean when many bins are open.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild preference for filling more-full bins as stream progresses.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * t * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: penalize large post residuals, with non-linear growth
    let mut score = norm_r * norm_r * cap + 0.5 * r;

    // Smooth coupling of residual with stream progress: later in the stream,
    // dead space matters more (less chance to fill it)
    let progress_coupling = progress * (norm_r * (1.0 - norm_r) * 4.0);
    score += progress_coupling * cap * 0.75;

    // Reward tight fits: small post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    }

    // Prefer bins with below-mean residual (consolidate emptiness)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0 - dev * 5.0;

    // Many open bins: mild pressure to fill existing ones rather than open new
    score += (open_bins_count as f64).ln() * 1.5 * norm_r;

    // New-bin candidate: keep it competitive only when current bin fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits, but discount residual in harmonic classes.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division class of the post residual: bins whose leftover falls
    // into "usable" buckets (>= 50, or small-but-clean like 0..=10) are favored.
    let class = post_residual / 10; // 0..=10 harmonic class
    let class_bonus: f64 = match class {
        0 => -18.0,               // near-perfect fill
        1 => -6.0,                // small dead space, still usable
        2 | 3 | 4 => 4.0,         // awkward mid-range leftover
        5 | 6 => -3.0,            // leftover 50-69: fits most items
        _ => 0.0,
    };
    score += class_bonus;

    // Modulo coupling: leftover congruent to 0 mod 10 pairs well with
    // round-number items; penalize leftovers that are odd/awkward mod 10.
    let m = post_residual % 10;
    score -= (10.0 - (m as f64 - 5.0).abs()) * 0.6;

    // Lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // exact match is gold
            if next_item_size == post_residual {
                score -= 15.0;
            }
            // next item leaves a good class too
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 12.0;
    }

    // Progress-scaled tightness pressure: later in the stream, be greedier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity as f64 - post_residual as f64) * (0.4 + 0.4 * progress);

    // Mean-residual coupling: placing into a bin below-average residual
    // (tight bin) is good; above-average (loose bin) is mildly penalized.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Fractional threshold on residual fraction: prefer keeping residuals
    // either below 10% or above 50% of capacity.
    if frac > 0.1 && frac < 0.5 {
        score += 5.0;
    }

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 3.0; // slight default preference for reusing open bins
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the minimum item
    // (1..=10) are unusable gaps; penalize them steeply but reward a perfect fit.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0; // unusable dead space
    } else {
        // Usable gap: mildly reward larger usable leftovers only if they can
        // plausibly hold the lookahead item.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (sets up a perfect follow-up fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
        // But allow a new bin if this bin would otherwise leave dead space.
        if post_residual < 10 && post_residual > 0 {
            score -= 40.0;
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, prefer it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Reward tight fits relative to mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when every existing bin is a poor fit (few fitting bins, large leftover).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin by default; relax when it's a last resort.
        let mut nb = 60.0;
        if fitting_bins_count <= 1 {
            nb -= 45.0;
        }
        if post_residual as f64 > mean_residual + 30.0 {
            nb -= 10.0;
        }
        // Late in the stream, prefer tightening existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 15.0;
        return nb;
    }

    // Aggressive 2-step lookahead: perfect match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item exactly fills this bin: extremely desirable.
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: good, scaled by how tight the future fit is.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 25.0 * tightness;
        } else {
            // Next item won't fit here; penalize leaving awkward space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Penalize small dead space that no item (min size 1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to the current item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Compare against mean residual: prefer bins that deviate favorably
    // (using up more space than average keeps residual distribution balanced).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in the stream, allow more bins to be opened; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
