        }
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 2.5; // this bin's remainder is useless for next item
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Compare against mean residual: bins with residual far from mean
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // New-bin candidate logic: only attractive when item is large or nothing fits well
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 18.0 + 0.15 * open_bins_count as f64;
        }
        // late in stream, prefer filling existing bins
        score += 10.0 * progress;
    }

    // Mild preference for bins with smaller current residual (better fill)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.6 * prn * prn);

    // Smooth coupling: post-residual that matches next item is valuable late
    let match_term = (prn - nxt).abs();
    score += 12.0 * match_term * match_term * (0.4 + 0.6 * progress);

    // Reward tight fits (post residual near zero) more strongly as stream progresses
    score -= 18.0 * (1.0 - prn).powi(3) * (0.3 + 0.7 * progress) * fit;

    // Penalize opening new bins early / when alternatives exist
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) + 1.5 * open_bins_count as f64;
    }

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 8.0 * scarcity * (1.0 - prn);

    // Small tie-breaker coupling with mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead-space classes".
    let residue_class = post_residual % 10;
    // Perfect-fit residue (0) is ideal; small residues (1..5) are dead space.
    let harmonic_penalty: f64 = match residue_class {
        0 => -40.0,
        1..=3 => 18.0 + 6.0 * residue_class as f64,
        4..=6 => 8.0 + 2.0 * (residue_class as f64 - 3.0),
        _ => -6.0, // residues 7..=9 can still host medium items
    };
    score += harmonic_penalty;

    // Integer-division threshold: post_residual / 10 gives usable "slots" for small items.
    let slots = post_residual / 10;
    score -= 4.0 * slots as f64;

    // Lookahead coupling: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 { score -= 25.0; } else { score += (post2 % 10) as f64 * 1.5; }
        } else {
            // next item won't fit here; penalize leaving large residual that becomes waste
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in stream, keep bins consolidated less aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Tight fits (small relative waste) get extra reward.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Slight preference for bins below mean residual (balance load).
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: penalize placements when many bins are already open,
    // encouraging consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Coupling with mean residual: prefer bins whose residual is below average
    // (i.e., nearly full bins get filled first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0 - gap * 1.5;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use.
        score += 12.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item is
    // large or no existing bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 70.0 - tightness * 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline score so open bins with good fits win.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 * 0.75 + (post_residual as f64) * 0.25;
    }

    // Tight fit reward: small post_residual is good (already in base score).
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // perfect chained fit
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 20.0 * (1.0 - slack / 10.0); // next item fits snugly
            } else {
                score += 2.0; // wasteful leftover even after next item
            }
        } else {
            // next item won't fit; penalize dead space relative to smallest items
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 3.0; // dead space below min item size is fine if tight
            } else {
                score += (dead - 10.0).min(30.0) * 0.6;
            }
        }
    }

    // Compare post_residual against mean residual: prefer bins driven toward the mean
    // (balanced bins) but strongly prefer driving residual to zero.
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Penalize leaving residuals that no item (10..80 range) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0; // small unusable gap, but tight fits already rewarded
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio;
    }

    // Penalize small post-residuals that become dead space (unusable for typical items),
    // but only mildly, since tight fits are also good.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item could fit exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits here; the tighter, the better.
            let lookahead_tightness = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * lookahead_tightness;
        } else {
            // Placing here leaves a residual that cannot host the next item;
            // penalize more when the bin was otherwise a good fit (blocking risk).
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize spreading across too many open bins (encourages consolidation),
    // scaled by how average this bin's residual is.
    if open_bins_count > 0 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * (open_bins_count as f64) + 0.03 * deviation;
    }

    // New-bin candidate logic: an empty bin has bin_residual == bin_capacity.
    // Prefer opening a new bin only when existing fits are poor (large post_residual waste)
    // or when the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If no other bin fits comfortably, opening a new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Large items relative to capacity benefit from a fresh bin.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, avoid opening new bins (few remaining items to amortize).
        score += 15.0 * progress;
    }

    // Time horizon: early in the stream, be slightly more willing to consolidate
    // (many future items can use leftovers); late, prioritize immediate tightness.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight-fit reward: strongly favor small post_residual (quartic coupling)
    score -= 6.0 * (1.0 - pr / cap).powi(4);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: mid-range residuals are least useful (cubic bump)
    let half = cap / 2.0;
    let dead = (pr - half) / half;
    score += 4.0 * dead * dead * dead * dead;

    // Lookahead: reward if next item fits in post_residual, penalize otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 5.0 * (1.0 - nx / cap);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Late in the stream, consolidate: favor bins with low residual relative to mean
    let mean_gap = (pr - mean_residual) / cap;
    score += progress * 6.0 * mean_gap;

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it attractive only when open bins would waste space
    if bin_residual == bin_capacity {
        let best_open_waste = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            cap
        };
        score += 8.0 - 6.0 * (best_open_waste / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead space" classes (small, hard-to-fill remainders) get penalized.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Class-based penalty on post_residual via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always great
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space, nearly unusable
    } else if post_residual <= quarter {
        score += 12.0; // small leftover, hard to fill
    } else if post_residual <= half {
        score -= 8.0; // half-class leftover: still very reusable
    } else {
        score -= 15.0; // large leftover: most reusable
    }

    // Modulo harmonic classes: leftover congruence to common item sizes.
    // Items are often multiples of 5 or 10; leftovers matching those
    // residues are more likely to be exactly filled later.
    let r = (post_residual % 10) as f64;
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    } else {
        score += r * 0.4; // awkward residue penalized proportionally
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0;
    }

    // Progress-aware conservatism: later in the stream, prefer tightening
    // existing bins over spreading (fewer total bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: an empty bin gets a baseline score that
    // makes it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are pure waste; penalize them steeply, worst near the middle of the gap band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that the lookahead item can exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize a gap that is useless for the next item (too small for it but not zero).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits relative to the bin: small post_residual fraction.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins; penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the
    // item need (keeps residual distribution tight).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream, tighten up: value compact bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // New empty bin candidate: strong penalty unless it looks genuinely better
    if bin_residual == bin_capacity {
        score += cap * 0.75;
        // Reward opening a new bin when existing residuals are large (poor fits elsewhere)
        score -= (mean_residual / cap) * cap * 0.5;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 * 0.9 {
            score -= cap * 0.2;
        }
        return score;
    }

    // Perfect fit reward: item exactly fills the bin
    if post_residual == 0 {
        score -= cap * 2.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // 2-step lookahead: does the post residual match the next item well?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits after this placement; reward tight coupling
            score -= (1.0 - gap / cap) * cap * 0.8;
            // Extra reward for exact match
            if gap < 1.0 {
                score -= cap * 0.5;
            }
        } else {
            // Next item cannot fit; penalize proportionally to the shortfall
            score += (nxt - pr) * 0.5;
        }
    }

    // Penalize small dead space that is hard to reuse (relative to typical item sizes)
    if post_residual > 0 && post_residual < 10 {
        score += cap * 0.3;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Reward perfect/near-perfect fits heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for chain-friendly residual (>= 2x next item).
            if post_residual >= 2 * next_item_size {
                score -= 6.0;
            }
        } else {
            // Penalize creating residual too small for the next item (dead space).
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far below the mean residual (wasteful use of a fuller bin).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate: only attractive when fit is very poor or no real option.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.4 * bin_capacity as f64;
        let desperate = fitting_bins_count <= 1 && post_residual as f64 > 0.3 * bin_capacity as f64;
        if bad_fit || desperate {
            score -= 20.0;
        } else {
            // Default: prefer existing bins.
            score += 35.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), scaled by stream progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Smooth coupling: post-residual x progress cubic interaction
    score += norm_pr * norm_pr * norm_pr * 40.0 * (0.5 + progress);

    // Reward tight fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Penalize bins with residual far from mean (fragmentation pressure)
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Mild preference to keep few open bins early, more freedom late
    score += (open_bins_count as f64) * (0.3 - 0.3 * progress);

    // New-bin candidate: neutral-ish baseline, increasingly discouraged early
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by
    // integer division into capacity fractions (16ths of capacity).
    let unit = bin_capacity / 16;
    let class = post_residual / unit; // 0..16

    // Reward residual classes that are either near-perfect fits or large
    // enough to be reusable; penalize the awkward middle band (1..=3 units).
    match class {
        0 => score -= 40.0,                       // perfect fit
        1 | 2 | 3 => score += 25.0,               // unusable dead space
        4 | 5 | 6 => score += 8.0,                // marginal
        _ => {}                                   // large residual stays usable
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: only attractive when current open bins
    // are heavily loaded or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early or when mean residual is small (bins nearly full)
        let open_pressure = mean_residual / bin_capacity as f64;
        score = 55.0 - 40.0 * (1.0 - open_pressure) * (1.0 - progress) - 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild tie-break: prefer bins with residual close to the mean (balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste; penalize them extra.
    if post_residual < 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 3.0;
    } else if post_residual <= 20 {
        // Small but potentially usable gap: mild penalty.
        score += 6.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; dead space likely locked in.
            score += 3.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless the
    // current item is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_cost = 40.0
            + 20.0 * progress
            + 2.0 * open_bins_count as f64;
        // Opening is attractive only for big items (little waste potential).
        let big_item_bonus = if item_size >= 60 { 45.0 } else if item_size >= 40 { 15.0 } else { 0.0 };
        score += new_bin_cost - big_item_bonus;
    }

    // Mild preference for bins below mean residual (spread usage evenly),
    // keeping larger residuals available for future large items.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Open-bin pressure: discourage accumulating many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: low post_residual is good (already baseline).
    // Penalize post_residual that is small but nonzero and unlikely to be filled
    // by the next item (dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // 2-step lookahead: next item fits here -> strong reward.
            score -= 25.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space: next item cannot use the leftover.
            let waste = post_residual as f64;
            score += 0.35 * waste.min(next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.1 * post_residual as f64;
    }

    // Prefer bins with residual below mean (already "tight"), i.e. reward
    // placing into tighter-than-average bins to consolidate space.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a very usable residual, or no good alternative exists.
    if bin_residual == bin_capacity {
        let usable = post_residual as f64;
        // New bins are attractive only for large items leaving big, flexible space,
        // or when many bins already fit the item (spread load).
        score += 40.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if usable >= 60.0 {
            score -= 10.0;
        }
        if fitting_bins_count > 2 {
            score -= 15.0;
        }
    }

    // Early in stream: slightly favor spreading into new bins to build a
    // diverse residual portfolio.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no small item (min size 1) could use well:
    // tiny post-residuals are excellent; large ones are wasteful.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else if post_residual > 50 {
        score += 6.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here after this placement; slight penalty unless
            // post-residual is small anyway (dead space is negligible).
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: late in the stream, avoid opening new bins; consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins open.
        score += 20.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin fits tightly, new bin becomes more attractive:
        score -= 15.0 * (1.0 - fit_ratio);
    } else {
        // Early stream: mildly encourage spreading into fresh-ish bins to keep options.
        score += 8.0 * (1.0 - progress);
    }

    // Global residual context: prefer bins below mean residual (consolidating small
    // leftovers) when mean residual is low.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling: post-residual penalty grows superlinearly with stream progress
    let base = pr;
    let poly = 24.0 * norm_post * norm_post * (0.5 + progress) + 18.0 * norm_post * norm_post * norm_post * (1.0 + 2.0 * progress);

    // Tight fits are rewarded more as the stream progresses
    let tight = (1.0 - norm_post).powi(3) * 30.0 * (0.6 + 0.8 * progress);

    // Dead-space penalty: residual that is small but unusable for the next item
    let mut dead = 0.0;
    if next_item_size > 0 && pr > 0 && (next_item_size as u32) > post_residual {
        dead = 12.0 + 20.0 * progress * (1.0 - pr / cap);
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward
    let mut synergy = 0.0;
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        synergy = 25.0 + 15.0 * progress;
    }

    // Last-chance bin bonus
    let last_chance = if fitting_bins_count == 1 { 15.0 } else { 0.0 };

    // New-bin candidate handling: mildly penalize opening new bins early, allow late when open bins are fragmented
    let new_bin = if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        20.0 + 40.0 * (1.0 - progress) - 25.0 * progress * fragmentation
    } else {
        0.0
    };

    // Slight preference to spread across bins when many are open with high mean residual
    let spread = 6.0 * ((mean_residual / cap).max(0.0).min(1.0)) * (1.0 - norm_post);

    base + poly - tight + dead - synergy - last_chance + new_bin + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but heavily penalize dead space that is
    // unlikely to be reusable. Dead space value depends on harmonic class
    // of post_residual modulo small integers.
    let dead = post_residual as f64 / bin_capacity as f64;

    // Harmonic class: residuals that are "nice" (multiples of 10 / common
    // item sizes) are more reusable than awkward ones.
    let mut reusability = 0.0;
    for m in [5u32, 10, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            reusability += 1.0;
        }
    }
    // awkward residuals (prime-ish, small odd slivers) are penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver (items >= 1..100 but typically larger)
    }

    // Reward reusable residual classes (subtract), scaled by how much dead space exists
    score -= reusability * dead * 12.0;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 40.0
            - 25.0 * big_item
            - 20.0 * crowding
            - 10.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // this placement chains nicely.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for leaving medium gaps
            score += 3.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate waste)
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the minimum item (1..=3) are pure waste; penalize them heavily.
    if post_residual >= 1 && post_residual <= 3 {
        score += 40.0;
    }
    // Small-but-usable gaps are risky: penalize moderately if they can't
    // plausibly host the lookahead item.
    if post_residual > 3 && post_residual < 12 {
        score += 12.0;
        if next_item_size > post_residual && next_item_size > 0 {
            score += 8.0;
        }
    }

    // Reward tight fits: filling most of the bin reduces fragmentation.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins when
    // the current fit is mediocre; encourage consolidation when mean residual
    // is low (bins nearly full).
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    score -= (mean_residual / bin_capacity as f64) * 4.0;

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward strongly (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has no dead space yet; make it
    // attractive only when the item leaves a large usable residual anyway,
    // otherwise prefer existing bins with tight fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset if the item is large.
        score += 10.0 - 20.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    } else if post_residual < 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Slack left after the next placement; penalize proportional waste.
            let slack_after_next = post_residual - next_item_size;
            score -= 120.0 - (slack_after_next as f64) * 4.0;
        } else {
            // Next item cannot fit here; penalize bins whose residual is close
            // but insufficient (wasted potential), scaled by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare against mean residual across open bins: prefer tightening bins
    // whose residual is above average (reduce fragmentation).
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item leaves a
    // large usable residual and open bins are already tight.
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin can chain with the next item
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late in the stream, consolidate: slightly favor existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space: small post_residual that can't fit typical items is bad,
    // but perfect fit (0) is great.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if this bin would give a perfect fit for the item and lookahead, allow it.
        if post_residual == 0 {
            score -= 40.0;
        }
        // Late in stream, prefer closing out open bins rather than opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins above the mean residual (drain the emptiest bins less).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Prefer filling bins with less residual overall (compact packing).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.35 * progress * progress);

    // Smooth penalty for large residual that is unlikely to be filled later
    let fill_ratio = item_size as f64 / cap;
    score -= 12.0 * fill_ratio * (1.0 - norm_post) * (1.0 - norm_post);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual across open bins
    if post > mean_residual {
        score += 0.25 * (post - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - post_residual as f64 / cap) * progress;
    }

    // New-bin candidate: penalize opening new bins unless residuals are low
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0 * (mean_residual / cap);
    }

    // Mild regularization against bin proliferation
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
