    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use this residual; slight penalty for wasteful fit
            score += 6.0;
        }
    }

    // Prefer filling already-open bins when many are open (bin-count pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (balanced packing) unless it's a near-exact fit.
    let dev = (pr - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate: only attractive when nothing fits well anywhere.
    if bin_residual == bin_capacity {
        let best_alt = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Penalize new bins mildly; the last-chance / tight-fit bonuses of real
        // bins will usually beat this unless no open bin fits.
        score += 15.0 - best_alt * 0.0 + (item_size as f64) * 0.05;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Non-linear penalty on residual waste, scaled by residual magnitude.
        let r = post_residual as f64;
        score += (r * r) / (2.0 * bin_capacity as f64);
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0;
        } else if gap > 0 && gap < 10 {
            score += 20.0; // sets up an unusable sliver for the next item
        } else if gap < 0 {
            score += 8.0; // next item won't fit here either
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: discourage proliferation of open bins.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate: only attractive when current bin fits are terrible
    // (large dead space) or no real bin fits well; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    } else {
        // Prefer bins whose residual is already below the mean (tighter bins).
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Slight late-stream tightening: waste matters more as stream completes.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: leave exactly enough space for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Room for next item, penalize proportional slack to discourage waste.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack / 20.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the next item: penalize if unusably small.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Slight preference for filling bins more fully as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    // Penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = bin_capacity as f64 - mean_residual;
        if avg_fill > 35.0 {
            score += 40.0;
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
        // Perfect pairing: item + next exactly fills bin.
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 30.0 * (1.0 - crowding) + 10.0 * progress;
        // Discourage opening new bins when a last-chance fit exists.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // If next item is large, fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + (1.0 - x) * (1.0 - x) * progress;
    score += 12.0 * poly;

    // Reward tight fits, stronger later in the stream
    score -= (1.0 - x) * (1.0 + 2.0 * progress) * 6.0;

    // Penalize leaving residual that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - pr) * (0.5 + progress);
    }

    // Reward using the last fitting bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 5.0 + 8.0 * progress;
    }

    // Mild penalty when many bins are open and residual is wasteful
    score += 0.05 * open_bins_count as f64 * x * x;

    // Encourage keeping residuals near mean (balance)
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity quartiles
    let quart = bin_capacity / 4;
    let class = post_residual / quart;
    score += match class {
        0 => -6.0,  // tiny dead space left -> great fit
        1 => -2.0,
        2 => 0.0,
        _ => 3.0,   // large residual wasted on a small item
    };

    // Exact-fill / near-fill reward
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits perfectly here -> strong reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize more if this bin becomes dead
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.08;
            if post_residual < 10 {
                score += 4.0; // dead space class
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish, only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64) * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.05;
        }
    }

    // Prefer tight bins when many bins are open (consolidation pressure)
    score += mean_residual * 0.02;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.15 * progress;

    // Item size coupling: large items should prefer emptier bins
    if item_size > bin_capacity / 2 {
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Dead-space penalty: small unusable gaps (post_residual < 10) are strongly penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit: zero waste
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / 100.0);
    }
    // If next item does not fit post-residual and gap is small, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless waste is large
    if bin_residual == bin_capacity {
        // New bin is attractive if mean residual across open bins is small (all bins nearly full)
        let mean_r = mean_residual;
        if mean_r < item_size as f64 {
            score -= 15.0;
        } else {
            // discourage opening new bins when existing bins have room
            score += 12.0 + 0.3 * open_bins_count as f64;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Open bins pressure: with many open bins, favor placements that fill bins tightly
        score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to item size (best-fit coupling)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chained packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Strong bonus for exact lookahead match.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Penalize tiny dead space that likely cannot be used later (items >= 1,
    // but very small residuals relative to capacity are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins that keep the fleet's
    // residuals balanced (avoid creating an outlier hole).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: penalize opening a new bin when the
    // current item fits well in an existing bin.
    if bin_residual == bin_capacity {
        // New bin: its post_residual equals capacity - item_size.
        // Make it attractive only when the fit is tight (large item).
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - tightness);
        // Discourage new bins when other bins can fit the item.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * (1.0 - item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that can never be used by the smallest possible item.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys room for the next item in this bin; mild penalty
            score += 3.0;
        }
    }

    // New-bin candidate logic: opening a new bin is attractive only when fits are poor
    // or many bins are badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (early on, keeping options open is cheaper).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.85 - 10.0 * progress;

        // If existing fits are all bad (large post residual relative to mean), new bin is fine.
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
        // If the only alternative is a bad fit, opening a new bin is worse than using it.
        if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
            score += 20.0;
        }
    } else {
        // Prefer filling bins that are already relatively full compared to the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild preference to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // late in the stream, tight fits (small post_residual) are increasingly rewarded.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let progress_coupling = pr_norm * (1.0 + 2.0 * progress * progress);
    score += progress_coupling * 10.0;

    // Penalize dead space quadratically when the leftover cannot plausibly
    // hold the next item (smooth soft penalty, no hard threshold).
    if next_item_size > 0 {
        let shortfall = (next_item_size as f64 - pr).max(0.0) / bin_capacity as f64;
        score += 15.0 * shortfall * shortfall;
    } else {
        // Last item: reward filling the bin as tightly as possible.
        score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth exponential reward).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (-pr_norm * 4.0).exp();
    }

    // Mild dispersion pressure: prefer bins whose residual is below the mean
    // when many bins are open (balances load smoothly).
    let mean_diff = (mean_residual - pr) / bin_capacity as f64;
    score += 5.0 * mean_diff * (1.0 + open_bins_count as f64).ln() * (0.5 + progress);

    // Penalize opening a new bin when open bins exist and could fit,
    // scaled smoothly by how much of the bin the item would fill.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 8.0 * (1.0 - fill) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual is a multiple of 25 (very reusable: 25/50/75/100)
    // Class 1: multiple of 10
    // Class 2: small leftover (<= 20) -> mostly dead space
    // Class 3: awkward mid-size leftover
    let pr = post_residual;
    let class: u32 = if pr % 25 == 0 { 0 } else if pr % 10 == 0 { 1 } else if pr <= 20 { 2 } else { 3 };

    // Reward good harmonic classes by subtracting from score
    let class_bonus: f64 = match class {
        0 => 18.0,
        1 => 12.0,
        2 => 6.0,   // small dead space is tolerable
        _ => 0.0,   // awkward leftover
    };
    score -= class_bonus;

    // Exact fit is perfect
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits into the leftover: strong reward, scaled by tightness
            let tight = (next_item_size as f64) / (pr as f64);
            score -= 10.0 + 14.0 * tight;
            // Harmonic bonus: leftover exactly matches next item size
            if next_item_size == pr {
                score -= 20.0;
            } else if pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // Leftover too small for next item: penalize awkward mid-size dead space
            if pr > 0 && pr < 25 {
                score += 5.0;
            }
            // Integer-division threshold: leftover in a "dead band" (21..=34)
            if pr >= 21 && pr <= 34 {
                score += 6.0;
            }
        }
    } else {
        // Last item: just minimize leftover
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        // Extra pressure late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Make it mildly unattractive so we prefer reusing open bins with decent fits,
    // but attractive when all open-bin fits would create bad harmonic classes.
    if bin_residual == bin_capacity {
        score += 4.0; // baseline penalty for opening a new bin
        if open_bins_count > 0 && class == 3 && next_item_size > 0 && next_item_size > pr {
            // opening fresh is fine when reuse would create awkward leftovers
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open the first bin
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way
    // (filling below-mean-residual bins balances the pool).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev;

    // Mild scaling of the raw leftover term by stream progress:
    // early on, waste matters less (many items left to fill gaps);
    // later, tightness matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, ideal
    } else if post_residual > 0 && post_residual < 10 {
        // tiny unusable gap: strongly penalize so it loses to a new bin unless it's the last chance
        score += 60.0;
    } else {
        // graded penalty for leftover space, harsher for large leftovers relative to capacity
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * frac * frac;
    }

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * (item_size as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits the post_residual, reward keeping this bin usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // dead space for the known next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: penalize adding to bins when many are open, to spread load
    // and consolidate; but only mildly so tight fits still win.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate handling: an empty bin has full residual; make it moderately
    // attractive only when the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, grows with number already open
        score += 30.0 + (open_bins_count as f64) * 2.0;
    }

    // Slight preference for bins with residuals near the mean (keeps bin population balanced)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Late in the stream, consolidate more aggressively (avoid leftover partial bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: hugely reward zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly in the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if post_residual >= next_item_size {
            // Next item fits: reward closeness to an exact 2-item chain.
            score -= 120.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 400.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a small unusable gap.
            score += 60.0 * (1.0 - post / (next_item_size as f64));
        }
    }

    // Penalize tiny dead space (< 10, unusable since min item is small but gaps breed fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins that already have content over opening new bins.
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual, especially exact fits)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // penalize dead space that is too small to fit a typical future item
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // post_residual can't hold next item: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Time horizon: early in stream, be more willing to open new bins (keep flexibility);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin baseline: attractive early, unattractive late
        score = 30.0 - 25.0 * progress + (bin_capacity - item_size) as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // consolidation bonus late
        score -= 15.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * (4.0 + mean_residual * 0.05);
    } else {
        score += mean_residual * 0.02;
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation)
    let slack = (bin_residual - item_size) as f64;
    score += (slack / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    // Base: prefer tight fits (small post_residual), smoothed polynomial
    let mut score = pr;

    // Non-linear coupling: post_residual squared, modulated by stream progress
    // Early on, dead space matters less; later, tighten packing aggressively.
    score += 60.0 * fit_ratio * fit_ratio * (0.4 + 1.2 * progress);

    // Interaction: post_residual vs mean_residual — avoid bins that leave
    // residual far from the pack-wide average (smooth divergence penalty).
    let div = pr - mean_residual;
    score += 0.35 * div * div / cap;

    // Reward using nearly-full bins: strong subtraction when post_residual tiny
    score -= 25.0 * (1.0 - fit_ratio).powi(3) * (0.5 + progress);

    // Last-chance bin: if only one bin fits, strongly favor it to avoid new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: penalize leaving a residual that barely fails to fit next item,
    // reward residuals that can host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 12.0 * (1.0 - ((pr - ni) / cap));
        } else if pr > 0.0 {
            let gap = (ni - pr) / cap;
            score += 18.0 * gap * (1.0 + progress);
        }
    }

    // Mild penalty when many bins are open (encourage consolidation early)
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when item is large and no good fit exists
    if bin_residual == bin_capacity {
        score = pr + 55.0 - 0.5 * item_size as f64 * (1.0 + progress)
            + 10.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small residue" classes (unusable dead space) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows super-linearly once residual is below the
    // minimum plausible item size band (use 1..=100 range: treat < 20 as dead).
    if post_residual < 20 {
        score += (20.0 - post) * 3.0;
    }

    // Modulo-class logic: residuals divisible by common item-size divisors
    // (e.g. multiples of 25/50) are more likely reusable.
    let r = post_residual;
    if r > 0 && (r % 25 == 0 || r % 50 == 0 || r % 10 == 0) {
        score -= 8.0;
    } else if r > 0 && (r % 5 == 0) {
        score -= 3.0;
    }

    // Perfect fit reward: residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: penalize if next item cannot use post_residual,
    // reward if next item fits snugly (post_residual == next_item_size).
    if next_item_size > 0 {
        if (next_item_size as f64 - post).abs() < 1.0 {
            score -= 15.0;
        } else if next_item_size > post_residual {
            score += 4.0;
        } else {
            // harmonic class match on next item divisibility
            let n = next_item_size;
            if n % 10 == 0 && r % 10 == 0 {
                score -= 5.0;
            }
            score += (post - n as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate bias: opening a new bin should only win when the
    // current bin fit is poor (large post_residual) or few bins open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score = post + 25.0 - pressure * 6.0;
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 10.0; // next item can't fit an empty bin anyway
        }
    }

    // Mild stream-position scaling to break ties adaptively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    // Prefer tighter-than-average bins.
    score -= (mean_residual - post) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space trap: small unusable gaps (below min item size 1..~10) are worthless.
    if post_residual < 10 {
        score += 60.0;
    }

    // Penalize gaps too small for the lookahead item (k=2 lookahead awareness).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Reward gaps that exactly fit the next item (great chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }

    // Tight fill preference: reward small post_residual relative to item size.
    score += 0.3 * (post_residual as f64 / item_size.max(1) as f64) * 10.0;

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are truly bad,
    // but scale penalty down as stream progresses / many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 + 50.0 * (1.0 - progress) + 0.2 * open_bins_count as f64;
        // If mean residual of open bins is large, opening new bin is less attractive.
        score += 0.5 * mean_residual;
        // If nothing open can fit (fitting count includes new bin only), allow new bin.
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 300.0; // perfect 2-step chain
            }
        } else {
            // next item cannot fit here after placement; penalize dead space
            score += 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: prefer leaving typical-sized space
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 120.0 * (1.0 - pressure);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 80.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins tighter as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize less if post residual is near zero.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: fresh empty bins should only win when no
    // open bin offers a decent fit. Give the empty bin a mild penalty that
    // shrinks as the stream progresses (more bins amortized later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 12.0 * progress;

        // If many open bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        // If next item is large and this item is small, a fresh bin preserves
        // flexibility for the big item.
        if next_item_size > 60 && item_size < 40 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (denser bins),
    // keeping sparse bins available for large future items.
    score += 0.08 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for spreading across too many open bins early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > 4.0 + 20.0 * progress {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize large post-residual more as stream progresses
    let pr_norm = pr / cap;
    score += pr_norm * pr_norm * (1.0 + 2.0 * progress) * 10.0;

    // Reward tight fits (small post-residual) with smooth quadratic bonus
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (1.0 + 3.0 * progress) * 8.0;

    // Interaction with mean residual: prefer bins whose residual is near mean (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 6.0;

    // Last-chance bonus: strongly reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits smoothly in post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs() / cap;
        score -= (1.0 - fit_gap.min(1.0)) * 5.0 * (1.0 - progress);
        if pr < nxt {
            score += 4.0 * progress;
        }
    }

    // Penalize opening new bins late in the stream
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 10.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: exact-fill classes are best.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0; // near-perfect dead space is small anyway
    } else {
        // Modulo-10 harmonic classes: residuals that are multiples of 10
        // can still host common item sizes (10,20,...).
        let m10 = pr % 10;
        if m10 == 0 {
            score -= 18.0;
        } else if m10 <= 3 || m10 >= 7 {
            score += 4.0; // awkward classes
        }
        // Modulo-5 secondary class
        if pr % 5 == 0 {
            score -= 5.0;
        }
        // Dead-space threshold via integer division: pr / 10 gives usable decade count
        let decades = pr / 10;
        if decades == 0 {
            score += 25.0; // residual < 10 is unusable dead space
        } else if decades <= 2 {
            score += 6.0;
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic bonus if next item exactly consumes remainder class
            if next_item_size == pr {
                score -= 45.0;
            } else if pr % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly
    if bin_residual == bin_capacity {
        // penalize opening new bins early, reward late in stream or when mean residual is tight
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 * (1.0 - progress);
        if mean_residual < 25.0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 15.0;
        }
    }

    // Slight preference for fuller bins among equals
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
