    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Near match: next item fits with little waste left over.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot follow in this bin: penalize dead space creation.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Reward bins that are tighter than the mean residual (good packing).
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Penalize leaving small unusable fragments (< 10 cannot fit any item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer keeping residual aligned with common item sizes (divisibility bonus).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    score += 20.0 * (frac * std::f64::consts::PI).sin().abs();

    // Slight preference to fill bins earlier in the stream (reduce open-bin spread).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: prefer filling bins when many bins are open (reduce fragmentation).
    score -= 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean residual coupling: penalize bins whose residual deviates above the mean
    // (keeps residuals homogeneous and combinable).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.3 * (residual_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - residual_f);
    }

    // Time horizon: early in the stream, be more willing to keep bins flexible;
    // later, prioritize closing bins out completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 * 0.4);
    score += (1.0 - progress) * 6.0;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score = bin_capacity as f64 * 0.9 + desperation - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post residual in [0,1]
    let x = pr / cap;

    // Base: reward small post residual (good fit) with non-linear shaping
    let mut score = 2.0 * x - x * x;

    // Smooth polynomial coupling with stream progress:
    // late in the stream, tighter fits matter more; dead space penalized increasingly
    let coupling = (1.0 - progress) * 0.5 + progress * 1.5;
    score += coupling * (x * x * (1.0 - x));

    // Penalize post residual that is too small to hold the smallest plausible item,
    // expressed smoothly via sigmoid-like term on x
    let dead = 1.0 / (1.0 + (x * 25.0).exp());
    score += 4.0 * dead * (0.5 + progress);

    // Lookahead: if next item fits into post residual, reward this bin smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = ((pr - next_item_size as f64) / cap).max(0.0);
        let bonus = fits * (1.0 - nx);
        score -= 1.5 * bonus * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 && open_bins_count > 0 {
        score -= 3.0 * (1.0 - x);
    }

    // Slight penalty for very full bins early (keep flexibility), smooth in progress
    score += (1.0 - progress) * 0.8 * (1.0 - x);

    // Mean residual deviation: prefer bins whose residual is near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // New-bin candidate: neutral-ish baseline; opening a new bin only attractive
    // when item is large relative to capacity or stream is early
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score = 0.9 - 1.2 * large * (1.0 - progress) - 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small leftovers are valuable
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 30.0;
    } else if pr <= 15 {
        score -= 10.0;
    }

    // Modulo-class penalty: residuals that are unusable by common small sizes
    let half = bin_capacity / 2;
    if pr > half {
        score += (pr - half) as f64 * 0.8; // large dead space
    }

    // Integer-division threshold: residual divisible into chunks of 10 is reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr < 10 && pr > 0 {
        score += 12.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
    } else if next_item_size > pr && next_item_size > 0 {
        score += 6.0;
    }

    // Stream progression: early on, be conservative about spreading bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 10.0 + (gap as f64).min(20.0);
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately attractive only when existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled softly.
    score = post_residual as f64 * 1.0;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item size -> huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit: reward proportionally to how well it fills.
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space, more so for small leftovers.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }

        // Exact 2-step chain: item + next item fills bin perfectly.
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize post residual strongly.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if next item pairs perfectly with this item in a fresh bin, allow it.
        if next_item_size > 0 && (bin_capacity - item_size) as i64 == next_item_size as i64 {
            score -= 45.0;
        }
    }

    // Slight stream-position term: early on, be a bit more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize dead space that no future item (min size 1, typical small) can use:
    // prefer residuals that are either 0 or large enough to be reusable.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item can't follow here; slight penalty proportional to wasted potential
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state: if many open bins with slack, prefer consolidating into fuller bins.
    let slack_pressure = mean_residual / bin_capacity as f64;
    score += 15.0 * slack_pressure * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in the stream, be more conservative about filling bins
    // (leave room); late in the stream, close bins out aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - tightness);

    // New empty bin candidate: generally discouraged; only attractive when
    // item is huge relative to typical residual pressure and no tight option exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 70.0
            - 30.0 * desperation
            - 20.0 * (item_size as f64 / bin_capacity as f64) * progress;
    }

    // Mild preference for bins whose residual is close to the mean (stability).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, non-linearly warped by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - x));

    // Smooth polynomial coupling: penalize large dead space more as stream advances.
    score += 18.0 * progress * x * x * x;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: favor leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 8.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mild penalty relative to mean residual: avoid wasting well-filled bins' context.
    score += 0.15 * (mean_residual - pr).abs();

    // Slight pressure to consolidate when many bins are open.
    score += 0.4 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets mimic classic capacity-fraction classes
    let class = post_residual % 10;
    // Dead-space penalty: residuals that no item (min size 1, but typical >=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic bucket penalty: residual classes near half/full capacity are more reusable
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let dist_half = (post_residual as i32 - half as i32).abs() as f64;
    let dist_quarter = (post_residual as i32 - quarter as i32).abs() as f64;
    score += 0.15 * dist_half + 0.10 * dist_quarter;

    // Modulo threshold on post_residual: multiples of 10 are "harmonic" residual targets
    if class == 0 {
        score -= 12.0;
    } else if class <= 5 {
        score += 3.0 * class as f64;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward smooth chaining, especially exact harmonic class match
            score -= 8.0;
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize if this bin becomes stranded
            score += 10.0 + 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // default: new bin is worse than any reasonable existing fit
        score += 40.0;
        if pressure > 0.0 {
            score -= 80.0;
        }
        // late in stream, prefer closing out with new bins less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins tighter than the mean residual (better packing density)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for bins that are already partially filled (consolidation)
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual that cannot hold even the smallest item (1) is pure waste;
    // small residuals below a "dead zone" threshold are strongly penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 + (20.0 - post_residual as f64) * 0.5;
    }

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap that the next item cannot use: dead space penalty.
        score += 5.0 + (next_item_size as f64 - post_residual as f64).min(15.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out; penalize new-bin creation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 5.0 + pressure * 2.0;
        // Early in the stream with few bins, opening a new bin is cheap.
        if open_bins_count < 3 {
            score -= 8.0;
        }
    } else {
        // Reward using existing bins proportionally to open-bin pressure.
        score -= pressure.min(10.0);
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // filling a bin that is already tight keeps the pool of usable bins balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if (bin_residual as f64) < mean_residual {
        score -= dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // next fits, but imperfectly: penalize leftover dead space
            let chain_leftover = post_residual - next_item_size;
            score -= 200.0 - chain_leftover as f64;
        } else {
            // next item cannot use the leftover: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow new bin if lookahead suggests a good chain can be built
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Mild pressure to consolidate early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Penalize small dead space (post_residual that no typical item can use).
    if post_residual > 0 && post_residual < 10 {
