        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize large wasted residuals relative to next item
            score += 0.15 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Global state: with many open bins, discourage spreading into new bins
    // unless the fit is good; encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it's a loose bin — mildly prefer filling loose bins to consolidate.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.08 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to exploit them); late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, and when
        // many bins are already open; reward early when few bins exist.
        score += 30.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > item_size {
            score -= 10.0; // big next item: fresh bin may help
        }
    } else {
        // Existing bin: more attractive later in the stream.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, quadratically (dead space is superlinear bad).
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Reward tight fits: small post_residual relative to bin gets extra discount.
    let tightness = 1.0 - (pr / cap);
    score -= 6.0 * tightness * tightness * (item_size as f64 / cap);

    // Non-linear stream-progress coupling: early on, prefer flexibility
    // (keep bins open for pairing); late, consolidate aggressively.
    let flex = (1.0 - progress) * (progress * std::f64::consts::PI * 2.0).sin().abs();
    score += 8.0 * flex * (pr / cap);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // Next item cannot use this residual: mild penalty proportional to gap.
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high; only wins when
    // open bins are all poor fits. Scale penalty with mean residual mismatch.
    if bin_residual == bin_capacity {
        score = cap as f64 * 1.1 + 0.3 * mean_residual - 2.0 * progress;
    }

    // Mild penalty for scattering across many open bins when residual is large.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-16 residue encodes "slot" structure
    let residue_class = post_residual % 16;
    score += match residue_class {
        0 => -8.0,               // perfect slot, dead space is reusable
        1 | 2 | 3 => 6.0,        // tiny sliver, near-dead
        4 | 5 | 6 | 7 => 2.0,    // awkward small zone
        8 | 9 | 10 | 11 => -2.0, // half-bin zone, decent
        _ => -4.0,               // large zone, very reusable
    };

    // Penalize post_residual that is strictly below the smallest possible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.3 * slack;
        } else {
            // next item can't use this bin's leftover; mild penalty proportional to gap
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Fraction-of-capacity thresholds on bin_residual (integer division style)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if bin_residual <= quarter {
        score += 5.0; // nearly full bin, low value as a target unless last chance
    } else if bin_residual <= half {
        score -= 1.0;
    } else {
        score -= 3.0; // roomy bin, prefer filling big bins first
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Progress-based adjustment: late in the stream, avoid opening wasteful bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so it's chosen only when open bins are bad
        score += 30.0 - 10.0 * progress;
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Small tie-breaker on tightness of fit
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable small gap"
    // band (too small for the minimum plausible item) is heavily penalized.
    let dead_threshold = 30.0f64;
    if (post_residual as f64) < dead_threshold {
        // Quadratic escalation toward zero-gap: near-zero leftovers are good
        // (perfect fit), but 1..dead_threshold gaps are dead space.
        let gap = dead_threshold - post_residual as f64;
        score += 2.5 * gap * gap / dead_threshold;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize leaving a gap that exactly wastes capacity relative to mean residual.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is genuinely good; encourage consolidation when many bins are open.
    score += 0.35 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Lookahead coupling: if the next item fits the post residual, reward this
    // placement (chaining placements in the same bin).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would NOT fit here anyway, mildly favor using this bin now.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
        score += 0.2 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // fallback unless open bins give a poor fit. Penalize opening new bins
    // more as the stream progresses and bins accumulate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // But if no open bin fits at all, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match (next item exactly fills remaining space)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Reward: next item can also fit into the post residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Penalize dead space: residual smaller than the smallest plausible item
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Slight preference for reusing bins vs opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize progressively, but allow it when post
        // residual would be attractive for the next item
        let mut new_bin_score = 60.0 + 40.0 * progress;
        if next_item_size > 0 {
            let after_two = bin_capacity - item_size - next_item_size.min(bin_capacity - item_size);
            new_bin_score += after_two as f64 * 0.5;
        }
        score = score.max(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to ever be useful (below min item size 1..100, keep threshold adaptive).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // This bin could have held the next item too; slight penalty for blocking.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = fit_ratio < 0.6;
        if poor_fit {
            // Opening a fresh bin preserves large residual for future large items.
            score -= 20.0 + 15.0 * (1.0 - progress);
        } else {
            // Discourage wasting a fresh bin on a good existing fit.
            score += 45.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing emptier bins.
    if !is_new_bin {
        let rel = bin_residual as f64 / bin_capacity as f64;
        score += 8.0 * (rel - mean_residual / bin_capacity as f64).abs();
        score -= 5.0 / (open_bins_count as f64 + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual scaled by stream progress (later: keep bins tighter)
    let mut score = pr * (0.6 + 0.8 * progress);

    // Smooth non-linear penalty for awkward dead space (mid-size residuals least useful)
    let awkward = norm_pr * (1.0 - norm_pr);
    score += 40.0 * awkward * (0.5 + progress);

    // Reward tight fits with a saturating quadratic
    score -= 30.0 * fit_norm * fit_norm * (1.0 - norm_pr);

    // Lookahead coupling: bonus if next item fits the post residual smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (pr - next_norm * cap) / cap;
        score -= 15.0 * (1.0 - gap * gap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins score poorly
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * progress - 6.0 * (open_bins_count as f64).ln();
    }

    // Mean residual interaction: avoid scattering residual space unevenly
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by integer division
    // into "dead" (small unusable), "medium", and "useful" (large) classes.
    let quarter = bin_capacity / 4;          // 25
    let eighth = bin_capacity / 8;           // 12
    let cap_f = bin_capacity as f64;

    // Dead-space penalty: leftover that no plausible item (1..=100) can use is fine,
    // but tiny leftovers (1..=eighth) are the worst: they waste capacity without
    // guaranteeing a future fit. Penalize quadratically within the dead band.
    if post_residual <= eighth && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / eighth as f64);
    }

    // Perfect-fit harmonic classes: leftover divisible into common item sizes is great.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 7.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much of the leftover it consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
            // Bonus if after the next item the leftover lands in a "round" class.
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item does NOT fit here: penalize more if this bin was the only option.
            score += 12.0;
            if post_residual < next_item_size {
                score += 0.05 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // (avoid opening a new bin) unless the leftover would be truly dead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= quarter {
            score -= 15.0; // still prefer consuming this bin's space
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current item is large (harmonic class of item_size).
    if bin_residual == bin_capacity {
        let item_class = item_size as f64 / cap_f;
        // Large items (> 3/4 capacity) deserve a fresh bin; small items should reuse.
        if item_class > 0.75 {
            score -= 25.0;
        } else if item_class > 0.5 {
            score -= 5.0;
        } else {
            score += 20.0; // small items: discourage opening new bins
        }
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Spread-awareness: if this bin's residual deviates strongly from the mean,
    // prefer bins with less residual (tighter packing) via mild penalty.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild pressure to keep the number of open bins low late in the stream.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is nonzero but too small for next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mild preference toward bins with below-average residual (fill emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: make it slightly less attractive unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect two-item fill).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect pair: bin will be exactly full after next item
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0; // near-perfect pair
        } else if post_residual > next_item_size {
            score -= 8.0; // next item still fits after this one
        } else {
            score += 10.0; // next item won't fit here; dead space likely
        }
    } else {
        // Last item: just minimize waste directly.
        score -= 15.0;
    }

    // Compare post_residual relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(30.0) * 0.5; // tighter fit than average
    } else {
        score += (pr - mean_residual).min(30.0) * 0.3; // looser than average
    }

    // Penalize tiny unusable post_residual gaps that are not zero-waste.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // dead space trap
    }
    if post_residual == 0 {
        score -= 40.0; // perfectly closed bin
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow opening a new bin late in the stream when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0 * progress;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a nonlinear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.8;
        } else {
            // next item won't fit here; small penalty for stranding space
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (i.e., item barely fits anywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (bin_residual - item_size) as f64;
        // Perfect placement in a fresh bin is great.
        score -= 8.0;
        // Late in the stream, discourage opening new bins unless post-residual is large.
        score += progress * (60.0 - fit_quality.min(60.0)) * 0.5;
        // If many bins are open and one fits tightly, prefer existing bins.
        if fitting_bins_count > 0 {
            score += 10.0 + (open_bins_count as f64).sqrt() * 2.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidate small remainders).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.15;
    }

    // Mild preference for filling nearly-full bins as the stream progresses.
    let fill_ratio = 1.0 - res_f / (bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base cost: wasted space after placement, weighted by stream progress
    // (later in the stream, dead space is more costly to recover).
    let mut score = post * (0.5 + progress);

    // Non-linear polynomial coupling: penalize mid-range residuals quadratically,
    // but reward near-perfect fits (small post_residual) with a cubic discount.
    score += 40.0 * norm_post * (1.0 - norm_post) * (0.5 + progress);
    score -= 60.0 * (1.0 - norm_post).powi(3);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: penalize leaving a residual that is too small for the next item
    // (unusable sliver), but reward residuals that can exactly host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post as f64 >= nxt {
            let gap = post as f64 - nxt;
            score -= 20.0 * (1.0 - gap / cap); // residual usable by next item
            score += 5.0 * (gap / cap);        // slight penalty for leftover after that
        } else {
            // sliver: post_residual too small for next item -> dead space penalty
            score += 15.0 * (1.0 - post / nxt) * (0.5 + progress);
        }
    }

    // Prefer placing into already-open bins over opening new ones; scale
    // pressure with the number of open bins and mean residual dispersion.
    let mean_gap = (mean_residual - post).abs() / cap;
    score += 8.0 * mean_gap * (1.0 - progress);

    // New-bin candidate (empty bin): add an opening cost that shrinks with
    // progress, so late in the stream reusing bins is strongly favored.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "useful" class (small or exactly reusable) should be preferred.
    // Class by capacity fraction: post_residual / capacity.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Sweet spots: leftover that can host a typical next item (10..80 range).
    // Penalize leftovers that are neither near-zero nor large enough to be useful.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        // Dead zone: leftover too small for the smallest plausible item (1..)
        // but wasted anyway -> strongly penalize.
        if post_residual < 10 {
            score += 45.0 * (10.0 - post_residual as f64);
        }
        // Usable leftover: reward proportionally to how well the NEXT item fits.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // lookahead fits: reward tightness of the future packing
                let tight = (post_residual - next_item_size) as f64;
                score -= 30.0 - 0.25 * tight.min(60.0);
            } else {
                // lookahead does NOT fit: penalize proportional to overshoot
                let over = (next_item_size - post_residual) as f64;
                score += 0.6 * over.min(80.0);
            }
        }
        // Harmonic residue classes on post_residual (mod 10): multiples of 10
        // align with common item sizes -> slightly reward them.
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else {
            score += 2.0 * (post_residual % 10) as f64;
        }
    }

    // Fractional capacity coupling: bins with residual close to a half or
    // quarter of capacity are flexible; treat via frac.
    let half = (frac - 0.5).abs();
    let quarter = (frac - 0.25).abs();
    score -= 8.0 * (1.0 - half.min(1.0)) + 4.0 * (1.0 - quarter.min(1.0));

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only prefer
    // it when the current item leaves a very awkward residual in every open bin.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a decent fit, better than a terrible one.
        score = bin_capacity as f64 * 0.62 - 0.35 * item_size as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Stream progression: early on, be conservative (prefer tight fits to build
    // dense bins); late in the stream, closing bins cleanly matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - frac);

    // Crowd control: many open bins -> favor consolidating into existing ones.
    if open_bins_count > 4 {
        score -= 0.8 * (open_bins_count.min(40) as f64) * (1.0 - frac);
    }

    // Mean residual coupling: if this bin is far below the mean residual, its
    // space is scarcer -> prefer using it now.
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to
    // plausibly hold a future item (dead zone), scaled non-linearly.
    if post_residual > 0 {
        let r = post_residual as f64;
        // Dead space threshold: gaps below ~25% of capacity are hard to reuse
        let dead_zone = 0.25 * bin_capacity as f64;
        if r < dead_zone {
            // Quadratic penalty peaking just below the threshold
            score += 3.0 * (dead_zone - r) * (dead_zone - r) / dead_zone;
        }
    }

    // Perfect fit reward: strong bonus for zero waste
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if post_residual can exactly fit next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // post-residual too small for the lookahead item: extra penalty
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open
    // (a new-bin candidate has bin_residual == bin_capacity, so post_residual
    // is large; the penalty below counteracts its low base score).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0)) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild preference for tight fits relative to mean residual state
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize wasted leftover space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Slight preference to fill bins earlier in the stream
    score += (step_index as f64 / total_items.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small, hard-to-use dead space (post_residual in 1..=10 is worst).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 15.0 * next_fit;
        } else {
            // Next item won't fit here; mild penalty for blocking good residual.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current
    // residuals are fragmented / poorly matched to the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open a new bin when many bins are open with high mean residual
        // (fragmentation) or when the item is large and nothing fits well.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (mean_residual / bin_capacity as f64);
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        score -= 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Prefer bins whose residual is close to the mean (balance residual distribution).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins late in the stream (consolidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: prefer tight fits (low post_residual), with mild non-linear penalty
    let mut score = post * (1.0 + 0.6 * pr * pr);

    // Dead-space penalty: residuals too small to be useful later
    let dead = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
    score += dead * (1.0 - progress);

    // Stream-progress coupling: later in stream, value compacting residual more
    score -= 8.0 * progress * (1.0 - pr);

    // Reward exact/very tight fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 6.0 * (nxt / cap);
        } else {
            score += 4.0 * (nxt / cap) * pr;
        }
    }

    // Many open bins: encourage filling existing ones rather than spreading
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr;

    // Mean-residual coupling: if this bin is below-mean residual, it's a good filler
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev;

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Primary: prefer small post-residual, with a quadratic dead-space penalty.
    score += 0.015 * post * post / cap;

    // Harmonic classes: reward post_residual divisible by common size classes (10/20/25/50),
    // since leftover space in such classes is reusable by typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 2.0; }
        // Penalize awkward dead zones (prime-ish residuals in (0,10) are unusable for most items)
        if pr < 10 { score += 12.0; }
    } else {
        score -= 15.0; // perfect fill
    }

    // Lookahead: strongly reward bins whose post-residual can fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * (next_item_size as f64);
        // Extra reward if next item exactly fills the remaining space.
        if post_residual == next_item_size { score -= 10.0; }
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize proportionally to wasted potential.
        score += 0.08 * (next_item_size as f64 - post as f64).max(0.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin; reduced when many bins are open (fragmentation)
        // or the current item is large relative to capacity.
        let mut penalty = 18.0
            - 2.0 * (open_bins_count as f64).min(6.0)
            - 8.0 * (item_size as f64 / cap);
        // Late in the stream, prefer consolidating into open bins.
        penalty += 6.0 * progress;
        // If item leaves a reusable residual in the fresh bin, soften penalty slightly.
        if (bin_capacity - item_size) % 10 == 0 { penalty -= 3.0; }
        score += penalty;
    }

    // Mild preference toward bins with below-mean residual (denser bins first).
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the smallest plausible future item
    // are pure waste: penalize them super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Treat residuals < ~10 as unusable dead space (hard quadratic penalty).
        if post_residual < 10 {
            score += 60.0 + (10.0 - gap) * 8.0;
        } else {
            // Mildly reward leaving roomy gaps that can still fit items.
            score -= gap * 0.35;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward when the leftover gap can exactly host the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize a gap that cannot host the lookahead item but is close to it
    // (near-miss dead space for the known future demand).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // --- Open-bin pressure ---
    // Discourage opening new bins when many bins are already open; encourage
    // consolidation into existing bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.25;

    // If this is the only bin that can fit the item, strongly favor using it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin is a costly fallback.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 55.0;
        // Escalate the cost when decent alternatives exist.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // Opening a new bin is acceptable when mean residual of open bins is
        // too small to be useful (fragmented open bins).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
        }
        // Late in the stream, prefer closing out existing bins.
        score += 20.0 * progress;
    }

    // Tie-breaker: prefer bins whose residual is closest above the item
    // (tightest fit) via a smooth nudge.
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left over after hypothetically placing the next item too.
            let second_residual = post_residual - next_item_size;
            score -= 40.0 + second_residual as f64 * 0.5;
            if second_residual == 0 {
                score -= 150.0; // perfect two-item packing
            }
        } else {
            // Post residual is dead space relative to the next item: penalize proportionally.
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.6;
        }
    } else {
        // Last item: minimize post_residual aggressively.
        score += 0.0;
    }

    // Compare post_residual against mean residual: avoid creating outliers far below mean
    // (fragmentation) while rewarding consolidation of large residuals.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 0.3 {
            score += (0.3 - ratio) * 80.0; // creates unusably small residual vs. fleet average
        } else if ratio > 1.5 {
            score -= (ratio - 1.5) * 10.0; // keeps big residual bins attractive
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score += 250.0 + open_bins_count as f64 * 15.0;
        // If the current item is large relative to capacity, a fresh bin is reasonable.
        score -= item_size as f64 * 0.8;
        // If next item is also large, fresh bin keeps flexibility.
        if next_item_size > 60 {
            score -= 60.0;
        }
        // Late in the stream, avoid opening bins needlessly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    } else {
        // Mild preference for tighter existing bins as the stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // Slight penalty when many bins compete, encouraging spreading load evenly.
        if open_bins_count > 1 {
            score += open_bins_count as f64 * 0.3;
        }
    }

    // Penalize large residual waste (dead space) with a mild quadratic term.
    if pr > 30.0 {
        score += (pr - 30.0) * (pr - 30.0) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible item (>=1) can use well:
    // residuals below the smallest item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if post-residual is close to next item (good chaining).
            let chain_gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain_gap as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins generally, more so early
    // in the stream and when many bins are already open but underused.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 22.0 + 10.0 * (1.0 - progress);
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0; // existing bins have plenty of room; don't open new
        }
    } else {
        // Mild reward for using bins that are already fragmented (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Slight preference for filling fuller bins as stream progresses.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill_ratio * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;

    // Quadratic + cubic interaction: dead space penalized more as stream progresses
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * progress)
                 + pr_norm * pr_norm * pr_norm * (2.0 * progress);

    score += 30.0 * coupling;

    // Tight fits rewarded more later in the stream
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * (0.5 + progress);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + progress);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (0.5 + progress);
    } else {
        // Last item: strongly prefer minimal post residual
        score += 10.0 * pr_norm;
    }

    // Mean residual context: prefer bins below mean residual (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // Mild penalty for scattering across many open bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by 10 pair
    // well with the common item granularity, so prefer them.
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0;
    } else if r <= 3 {
        score += 4.0 + 2.0 * r as f64; // tiny dead space is worthless
    } else if r >= 7 {
        score -= 2.0; // large residue still has pairing chances
    }

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 5.0; // bin still more than half full of space: very reusable
    } else if frac < 0.1 {
        score += 3.0; // nearly closed bin: dead space risk
    }

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap <= 5 {
            score -= 10.0;
        } else {
            score -= 3.0 * (gap as f64).min(15.0) / 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot fit here: this residual becomes dead space.
        score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize spreading residual mass when many bins are open with slack.
    if post_residual as f64 > mean_residual {
        score += 0.05 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    // Mild pressure to close bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - frac);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 4.0 };
        score += 10.0 + desperation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin helps chain large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item (1..100 unknown distribution -> treat < 10 as likely dead)
    // are heavily penalized; exact fits rewarded.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always best
    } else if post_residual < 10 {
        score += 200.0; // unusable sliver: strong penalty
    } else {
        // mild superlinear penalty on growing gap
        let pr = post_residual as f64;
        score += (pr / cap) * (pr / cap) * 30.0;
    }

    // Reward bins whose residual is "consumed" efficiently (tight fit)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 25.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins
    // and encourage filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 40.0 + 25.0 * pressure;
        // Allow new bin only if no decent fit exists: if the current bin leaves
        // a large gap, slightly reduce the new-bin penalty.
        if post_residual > 40 {
            score -= 20.0;
        }
    } else {
        // Favor bins with residual close to mean (keep balance) slightly.
        score += ((bin_residual as f64) - mean_residual).abs() * 0.05;
    }

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 35.0; // sets up a near-perfect follow-up fit
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use the leftover -> leftover becomes dead space
        score += 15.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 15.0;
    } else {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into the
    // post-residual (chain match), mild reward if it fits at all.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Dead space for the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Tightness reward relative to mean residual: bins tighter than average
    // are good candidates; looser than average are penalized.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            -1000.0
        } else {
            let worst_gap = mean_residual - item_size as f64;
            if worst_gap > 30.0 { 100.0 } else { 400.0 }
        };
        // Base penalty keeps new bins from winning unless rewards above flip it.
        score += desperation + 150.0;
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing
    // bins tightly over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 80.0;
    }

    // Mild preference for bins with many siblings (diversity of choice is fine).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual relative to item size is fine,
    // but large post_residual that can't fit the next item is waste.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // lookahead fits, reward
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5; // dead space for next item
        }
    }

    // Prefer tight fits: reward small post_residual non-linearly
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let mut new_bin_score = item_size as f64 + 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 5.0;
        }
        // Late in stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= progress * 5.0;
        // Many open bins with slack: avoid opening more
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            new_bin_score += 10.0;
        }
        score = new_bin_score.max(score);
    }

    // Mild preference for bins below mean residual (consolidate slack)
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64).max(-50.0) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Core: reward tight fits via quadratic in normalized fill
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill;

    // Dead-space penalty: post_residual too small for the lookahead item is wasted
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if pr < nxs {
            score += 8.0 * (nxs - pr) / cap;
        } else {
            // Reward residuals that can still host the next item
            score -= 3.0 * (1.0 - (pr - nxs) / cap);
        }
    }

    // Smooth non-linear coupling of fill with stream progress
    score -= 10.0 * fill * fill * (1.0 - progress) * progress * 4.0;

    // Last-chance bin: strongly prefer using it over opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // New-bin candidate: post_residual == capacity; add a fixed opening cost
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (use up emptier space first)
    score -= 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual that is "harmonious" with common
    // item sizes (divisible into nice chunks), penalize dead space classes.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // modulo classes on post_residual: 0 mod 10 residuals are reusable
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else {
            // awkward residual: penalize proportional to distance from next multiple of 10
            score += (10 - (pr % 10)) as f64 * 1.5;
        }

        // small dead space (< 10) is nearly unusable given min item size 1..100
        if pr < 10 {
            score += 40.0 * (10 - pr) as f64;
        }

        // harmonic coupling with next item: reward exact fit for lookahead
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0;
            } else if pr >= next_item_size {
                score -= (pr - next_item_size) as f64 * 0.5;
            } else {
                score += (next_item_size - pr) as f64 * 0.3;
            }
            // integer-division threshold: how many lookahead items fit
            let k = pr / next_item_size.max(1);
            score -= (k.min(4) * 5) as f64;
        }
    }

    // last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // new-bin candidate: penalize opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 90.0 };
        score += pressure;
        score -= mean_residual * 0.2;
    }

    // late in stream: prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.3;

    // many open bins: discourage spreading, favor tight fits
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual matches the item size closely (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Penalize placements that leave a gap the next item cannot use but is small.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < 15 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    if new_bin > 0.0 {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to typical residuals, opening a new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Slight stream-progression tilt: later in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post residual relative to capacity, the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / 100.0); // chain still possible, tighter is better
        } else {
            // next item would not fit here: penalize wasted chain opportunity,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.4 * miss;
        }
    }

    // Compare against mean residual: prefer bins that are already more filled
    // (below-mean residual) to consolidate waste into few bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when the item is large
    // relative to capacity or no good chain exists; otherwise discourage.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0; // an open bin could chain, don't open new
        }
        score -= 40.0 * large; // big items benefit from a fresh bin
        score += 0.5 * open_bins_count as f64; // mild pressure to reuse open bins
    }

    // Slight stream-position modulation: early on, be more open to new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0;
            } else if gap < 10 {
                score -= 20.0;
            } else {
                score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; slight penalty proportional to wasted lookahead potential.
            score += 5.0 + 0.2 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    } else {
        // Last item: just minimize post residual (already base score).
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * fit_ratio;
    } else {
        // More competing bins: mild penalty to break ties toward tightest fit (handled by fit_ratio).
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with slack -> discourage spreading, prefer filling existing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (1.0 - progress) * (1.0 - fit_ratio);

    // If this bin's residual is far above the mean residual, it's roomy; slight penalty
    // so we prefer bins closer to being filled (below-mean residual bins get bonus).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.1 * diff;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Base score would be capacity (large), but add explicit calibration:
    // opening a new bin is only good when the item fits poorly everywhere else.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Penalize new bin, but relax the penalty when the fit ratio would be low
        // (large item into empty bin is actually efficient).
        let new_fit = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 25.0 * new_fit;
        // Late in the stream, opening fresh bins is less attractive (fewer future items
        // to fill them); scale penalty with progress.
        score += 25.0 * progress;
        // If many bins are already open and slacking, avoid another one.
        if open_bins_count > 4 && mean_residual > 30.0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping.
    let mut score = pr;

    // Smooth polynomial coupling: post_residual squared term penalizes large gaps more,
    // weighted by stream progress (late in stream, dead space is costlier).
    let poly = norm_pr * norm_pr * cap;
    score += poly * (0.3 + 0.9 * progress);

    // Cubic interaction: very large residuals get extra penalty that grows with progress.
    score += norm_pr.powi(3) * cap * (0.5 + 1.5 * progress * progress);

    // Lookahead coupling: reward bins whose post_residual can hold the next item,
    // with a smooth saturating function of the match quality.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = (nxt / pr.max(1.0)) * (nxt / pr.max(1.0));
            score -= 12.0 * fit_quality * (1.0 + progress);
        } else {
            // Post-residual too small for the next item: smooth penalty for dead space.
            score += 6.0 * (1.0 - (pr / nxt).min(1.0)) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mean-residual coupling: placing into a bin above mean residual helps homogenize,
    // use a smooth exponential term.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * (0.4 + progress);

    // New-bin candidate: penalize opening a new bin mildly, more so early in the stream
    // and when open bins exist; smooth in progress.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 8.0 + 10.0 * (1.0 - progress) + 0.5 * openness;
    } else {
        // Slight reward for using existing bins as the stream progresses.
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Integer division thresholds: classify post_residual into dead-space classes.
    let dead_class = post_residual / 10; // 0..10 harmonic class
    match dead_class {
        0 => score -= 8.0,          // near-perfect fit, reward strongly
        1 => score -= 4.0,          // small gap, still attractive
        2 | 3 => score += 0.5,      // moderate gap, neutral-ish
        4 | 5 => score += 2.0,      // half-empty, wasteful
        _ => score += 3.5,          // large leftover, penalize
    }

    // Modulo arithmetic on post_residual: gaps that are multiples of common
    // small item sizes (e.g. 10, 20, 25) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 2.0; }
        if post_residual % 20 == 0 { score -= 1.0; }
        if post_residual % 25 == 0 { score -= 1.5; }
        if post_residual % 50 == 0 { score -= 1.0; }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (3.0 + slack as f64 * 0.05).min(4.0);
            if slack == 0 { score -= 5.0; } // perfect chain fit
        } else {
            // Next item cannot use this bin's leftover: mild penalty.
            score += 1.0;
            // Harmonic check: leftover is a multiple of next item's likely companions
            if post_residual % 10 == 0 { score -= 0.5; }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless stream is
    // early and current item is large (future packing value is high).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        score += 4.0 + 10.0 * progress - 6.0 * item_frac;
        // If plenty of open bins with loose residual, opening new bins is fine.
        if open_bins_count > 3 && mean_residual > 30.0 {
            score -= 3.0;
        }
        // Small items should almost never open a new bin.
        if item_size <= 20 { score += 5.0; }
    }

    // Mild preference for tighter bins among similar fits (tie-break on residual).
    score += bin_residual as f64 * 0.02;

    // Penalize bins that deviate strongly from mean residual (keep packing balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 10) are unusable for the
    // minimum item size; penalize them hard, scaled by how close to waste.
    let dead = post_residual as f64;
    if dead > 0.0 && dead <= 10.0 {
        score += (11.0 - dead) * 25.0;
    } else if dead == 0.0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    } else if dead <= 20.0 {
        // Moderately tight fit still useful for mid-size items.
        score -= (20.0 - dead) * 3.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // filling existing bins; few open bins -> tolerate new bins.
    let pressure = (open_bins_count as f64).sqrt() * 4.0;
    score += pressure;

    // New-bin candidate: only attractive when current bins are nearly full
    // or the fit would leave a large unusable gap.
    if bin_residual == bin_capacity {
        let gap_penalty = if dead > 0.0 && dead <= 10.0 { 0.0 } else { 30.0 };
        score += mean_residual * 1.5 - 20.0 + gap_penalty;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0;
        // Extra reward if next item exactly fills the remaining gap.
        if post_residual as u32 == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Dead space for the known next item: penalize.
        score += (post_residual as f64) * 2.0;
    }

    // Mild late-stream tightening: near the end, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact chain fit (item + next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            // reward tight-but-feasible fits for the next item
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
        // Penalize residual that is just barely too small for next item (dead space trap)
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Reward tight fit relative to current residual (best-fit behavior)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Penalize creating very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins whose residual is below mean (consume fragmented space first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; lookahead exact-fit can still override
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0; // fresh bin can host the next item too
        }
        // Later in the stream, discourage proliferation of open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: small leftover relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that can't fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; penalize moderately
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // current bins are fragmented or the fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = (mean_residual - (bin_capacity - item_size) as f64).abs();
        // penalize new bin by default, less so when open bins are fragmented
        score += 40.0 + fragmentation * 0.5 - 30.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 20.0; // big items deserve fresh bins
        }
    }

    // Encourage filling bins that are already mostly full (below mean residual)
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Mild pressure to consolidate bins as stream progresses
    score += 0.02 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space (bins can still be filled);
    // late in the stream, dead space becomes costly.
    let progress_coupling = (pr / cap) * (pr / cap) * (0.5 + 2.0 * progress * progress);
    score += progress_coupling * cap;

    // Lookahead: if the next item fits exactly in post_residual, reward this bin strongly;
    // if post_residual is smaller than next item, mild penalty for stranded space.
    if nx > 0.0 {
        let gap = (nx - pr).abs();
        let fit_bonus = (1.0 - gap / cap).max(0.0);
        score -= 3.0 * fit_bonus * fit_bonus;
        if nx > pr {
            score += 0.5 * (nx - pr) * progress;
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else {
        score += 0.4 * fitting_bins_count as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream
    // and when other bins could fit the item.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 2.0 * (fitting_bins_count as f64);
    }

    // Prefer bins with residuals above the mean (consolidate emptier space),
    // smooth quadratic term.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev * dev / cap;

    // Mild reward for filling large items into already-open bins.
    score -= 0.05 * it;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity classes (capacity fractions)
    let q = bin_capacity / 4; // 25
    let item_class = item_size / q;           // 0..3 (0..=2 for 1..100)
    let next_class = (next_item_size as u32) / q;

    // Perfect-fit reward: zero dead space
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post_residual, but penalize "awkward" dead space classes.
    // Dead space that is too small to fit the smallest item (1) is fine; but
    // residual in the harmonic "dead zone" (1..10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are acceptable-ish but slightly penalized
    }

    // Modulo-10 harmonic classes on post_residual: multiples of 10 pair well
    // with the classic 10..80 item grid.
    let post_mod = post_residual % 10;
    if post_mod == 0 && post_residual > 0 {
        score -= 12.0; // round residual likely reusable
    } else if post_mod >= 8 {
        score += 8.0; // near-round residual wastes 8-9 units
    }

    // Exact pairing: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 300.0;
    }
    // Near pairing: post_residual can host next item with small waste
    else if next_item_size > 0 && post_residual >= next_item_size as u32 {
        let waste = post_residual - next_item_size as u32;
        score -= 60.0 * (1.0 - waste as f64 / q as f64);
    }
    // Next item cannot fit here: this bin becomes dead space for the lookahead
    else if next_item_size > 0 && post_residual < next_item_size as u32 {
        score += 40.0 + 0.5 * (post_residual as f64);
    }

    // Integer-division thresholds: favor placing large items (class >= 2)
    // into bins with small residual (tight fits), penalize large items
    // fragmenting roomy bins.
    if item_class >= 2 && bin_residual <= 2 * q {
        score -= 30.0;
    }
    if item_class <= 1 && post_residual > 3 * q {
        score += 10.0; // small item in a big empty bin wastes capacity
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 80.0;
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with how many open bins already exist, so we only open when no good fit.
    if bin_residual == bin_capacity {
        score = 60.0 + 3.0 * open_bins_count as f64;
        // Opening is attractive if item is huge and nothing else fits well
        if item_size as f64 > 0.8 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * (open_bins_count as f64 - mean_residual / 10.0);

    // Mild bonus for bins whose residual is below the mean (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1) are pure waste,
    // but residuals too small for typical items create unusable gaps.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // impossible, should never happen
    }

    // Penalize "almost-full" residuals that no future item can plausibly use:
    // gaps in (0, 10] are dead space under the classic regime; scale penalty sharply.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (post_residual near 0 relative to bin_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and bins we'd rather not touch).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 25.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no bin fits well or bins are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let last_chance = if fitting_bins_count == 1 { 0.6 } else { 0.0 };
        let lookahead_mismatch = if next_item_size > 0 && next_item_size > bin_residual { 0.5 } else { 0.0 };
        score += 90.0 - 70.0 * (scarcity + last_chance + lookahead_mismatch).min(1.0);
        score += 10.0 * pressure;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff <= 5.0 {
            score -= 30.0 * (1.0 - diff / 5.0);
        }
        // Penalize leaving a gap the next item just barely misses.
        if next_item_size > post_residual && next_item_size - post_residual <= 8 {
            score += 10.0;
        }
    }

    // Mild drift: early in the stream keep bins flexible (larger post_residual ok);
    // late in the stream, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // Prefer bins below mean residual when many bins are open (balance avoidance of
    // many half-empty bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0) * pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward bins whose post_residual closely matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact 2-step chain: item + next item fills the bin completely
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Last item: prefer minimal leftover
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare residual against mean residual across open bins
    let cap = bin_capacity as f64;
    let mean_frac = mean_residual / cap;
    let post_frac = post_residual as f64 / cap;
    score += 10.0 * (post_frac - mean_frac);

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the item is large relative to capacity (then opening is fine).
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (item_size as f64 / cap);
    }

    // Early in stream: encourage consolidation; late: prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_frac);

    // Many open bins: encourage filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // wasted space w.r.t. lookahead
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
        } else {
            // bonus if next item fits exactly-ish in the post residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (-gap / 20.0).exp();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but reward it when the item is large and fits are poor.
    if bin_residual == bin_capacity {
        let frac_fit = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 1.0 };
        score += 30.0 * frac_fit;
        // large items justify new bins
        score -= 0.35 * item_size as f64;
        // early in stream, new bins are cheap (long horizon to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual when residuals are large (spread load),
    // prefer bins above mean when residuals are small (consolidate).
    let diff = bin_residual as f64 - mean_residual;
    if mean_residual > bin_capacity as f64 * 0.4 {
        score += 0.15 * diff;
    } else {
        score -= 0.10 * diff;
    }

    // Slight preference for fuller bins overall.
    score -= 0.08 * (bin_capacity - bin_residual) as f64;

    // Mild exploration noise-free diversity term: discourage too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize post_residual, with non-linear (quadratic) waste growth.
    let mut score = pr * (1.0 + 0.9 * (pr / cap) * (pr / cap));

    // Smooth progress coupling: later in the stream, waste matters more.
    let progress_coupling = 1.0 + 0.6 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of item/capacity ratio.
    let tightness = it / cap;
    score -= 12.0 * tightness * (1.0 - tightness) * (1.0 - tightness);

    // Penalize bins with residuals far from the mean (fragmentation signal),
    // smoothly damped.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving space for the next item via smooth interaction.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).max(0.0);
        score -= 6.0 * (slack / cap) * (1.0 - (pr / cap));
        // Penalize if post_residual barely accommodates the next item (creates near-zero leftover).
        let near = (pr - nx) / cap;
        if near < 0.05 {
            score += 4.0 * (0.05 - near) / 0.05;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: smooth nudge so it loses only against genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are golden.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward near-perfect fits (small post_residual) strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for unusable slivers.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 20.0;
        }
        // Harmonic class: modulo classes of post_residual relative to small item sizes.
        let class = post_residual % 10;
        score -= match class {
            0 => 40.0,             // leaves room divisible by 10, very reusable
            5 => 25.0,             // half-class, still reusable
            2 | 8 => 10.0,
            _ => 0.0,
        };
    }

    // Tightness ratio: prefer bins where item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 60.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / cap).max(0.0);
        } else {
            // Next item cannot fit here; penalize leaving large residual that
            // neither helps nor hurts: mild penalty scaled by fraction.
            score += frac * 15.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; scale penalty with how many bins already fit.
        score += 90.0 + 10.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (consolidate fullness).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference to spread across bins when many are open.
    if open_bins_count > 8 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Dead space relative penalty: small residuals after large items are worse
    if post_residual > 0 {
        score += (10.0 - post_residual.min(10) as f64) * 2.0;
    }

    // Last-chance bin bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= item_size {
        // next item bigger than current, dead space bad
        score += post_residual as f64 * 0.3;
    }

    // New-bin candidate: penalize opening a new bin mildly unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * (-0.3);
        // but if fitting bins are scarce relative to open bins, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: high mean residual means plenty of slack overall
    if mean_residual > item_size as f64 * 2.0 {
        score -= 5.0;
    }

    // Stream progression: early on, be more willing to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect two-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: bin will be exactly filled by next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item also fits here: strong bonus scaled by leftover after that.
            let second_left = post_residual - next_item_size;
            score -= 30.0 - second_left as f64 * 0.4;
        } else {
            // Next item will NOT fit: dead space penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Penalize very small unusable leftovers (dead space < min plausible item).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Relative-to-mean coupling: bins with residual near the mean are
    // "average" targets; strongly empty bins (large residual) are better
    // reserved for big items, so mildly penalize placing into them if item is small.
    let residual_dev = bin_residual as f64 - mean_residual;
    score += residual_dev * 0.05 * (item_size as f64 / 100.0);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it only
    // wins when all open bins are poor fits (their penalties push them above).
    if bin_residual == bin_capacity {
        // Slight preference to open new bins early in the stream when few bins open;
        // later, discourage proliferation of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + open_bins_count as f64 * (2.0 + 10.0 * progress);
        // But if next item is huge and would need a fresh bin anyway, encourage it.
        if next_item_size > 70 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual is good, but perfect fits are golden).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space that likely can't be reused by future items (sizes 1..100).
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * dead * dead;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves further waste — mild reward scaled by leftover
            let leftover = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize bins that would become nearly empty shells
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.35 * dev;

    // Encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins (penalize
    // filling an old bin slightly less); late in the stream, squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately attractive only when it beats wasteful fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if the current item is large relative to capacity, a fresh bin is natural
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: quadratic preference for small post-residual (tight packing),
    // smoothed with a cubic term to avoid over-rewarding zero slack.
    let mut score = norm_post * norm_post * (1.0 + 0.5 * norm_post) * cap;

    // Stream-progress coupling: later in the stream, tight fits matter more.
    score *= 1.0 + 0.8 * progress * norm_post;

    // Reward bins whose residual can still host the next item (lookahead k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack_fit) * (1.0 - 0.5 * progress);
        } else {
            // Post-residual is dead space for the next item: penalize proportionally.
            score += 6.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Deviation from mean residual: prefer bins whose remaining space is close
    // to the fleet average (keeps residuals balanced and usable).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless the fit is very tight
    // (item nearly fills a fresh bin) or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 30.0 * (1.0 - tightness) * (1.0 - tightness);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 8.0;
        }
        score += 2.0 * (1.0 - progress) * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Harmonic class logic: post_residual modulo 10 — small remainder classes
    // represent "dead space" fragments that are hard to fill later.
    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Perfect closure class: post_residual is an exact multiple of 10
    // (clean harmonic slot for typical small items).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling with next item (k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post == nxt {
            // Perfect wrap-around: bin closes exactly with next item.
            score -= 25.0;
        } else if post < nxt {
            // Next item won't fit here: penalize proportionally to the gap.
            score += (nxt - post) * 1.5;
        } else {
            // Next item fits: reward, more so if the leftover stays in a good class.
            score -= 8.0;
            if ((post - nxt) as u32) % 10 == 0 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Reward larger items entering this bin (tighter packing per placement).
    score -= (1.0 - item / cap) * 5.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default mild penalty so we prefer existing bins with decent fits...
        score += 6.0;
        // ...but if open bins are nearly exhausted (low mean residual),
        // opening a fresh bin is attractive.
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 12.0;
        }
        // Also open a new bin early in the stream when few bins exist.
        if open_bins_count == 0 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: mildly amplify differences so tight fits win.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + open_bins_count as f64 * 2.0 + progress * 8.0;

        // Opening a new bin is acceptable if no open bin leaves a good residual.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Don't open a new bin when next item could pair with this one's residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is close to the item (waste minimization).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // Slightly prefer bins below mean residual (use up the emptiest bins first,
    // keeping tight bins for tight items).
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still fit: mild reward proportional to slack left after next
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64) * 0.5;
        } else {
            // post residual cannot host next item: penalize dead space
            let dead = next_item_size - post_residual;
            score += (dead as f64) * 1.5;
        }
    }

    // Penalize very small unusable residuals (dead space), scaled by item size range
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last fitting bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 150.0;
        // opening a new bin is fine if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Prefer bins tighter than the mean residual (waste-wise)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in stream: be greedier about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * (0.2 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - 4.0 * tightness).max(0.0);

    // Penalize dead space that can't plausibly fit future items (min size 1, typical mid sizes).
    let usable = post_residual as f64 / 100.0;
    score += 10.0 * usable * usable;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / bin_capacity as f64);
        }
    }

    // Compare against mean residual: placing into a bin with residual far below mean
    // balances the pool; placing into an above-mean bin wastes large space.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.max(0.0) - 0.08 * (-dev).max(0.0);

    // Many open bins: encourage closing out bins (prefer fuller ones), reduce fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.05 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Late in the stream, prefer consolidating into existing bins over opening new ones.
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    // New-bin candidate: only attractive when current item is large relative to all residuals
    // or the pool is saturated; otherwise discourage.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let scarcity = (item_frac - avg_fit).max(0.0);
        score += 15.0 - 20.0 * scarcity;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= (bin_capacity as f64 - item_size as f64) {
            score -= 5.0; // new bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let mut score = pr as f64;
    // Smooth non-linear interaction: tight fits rewarded, modulated by progress
    score -= 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);
    // Penalize dead space that is too small to be useful (below min item size), smoothly
    let dead = (12.0 - pr).max(0.0) / 12.0;
    score += 60.0 * dead * dead;
    // Lookahead coupling: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 25.0 * (-gap / 20.0).exp() * (1.0 - progress);
    }
    // Last-chance bonus when few fitting bins remain
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - fit_norm);
    }
    // Mild pressure to prefer already-open bins as stream progresses
    score += 10.0 * progress * (pr / cap);
    // Divergence from mean residual: prefer bins near the mean (balance)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into nice chunks
    // (multiples of 5/10) are more "reusable", so reward them.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -40.0,                       // perfect fit
        _ if pr % 10 == 0 => -12.0,
        _ if pr % 5 == 0 => -6.0,
        _ if pr <= 9 => 10.0,             // tiny dead space
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: classify leftover size bands
    let band = pr / 10; // 0..=10
    score -= (band as f64) * 1.5;

    // Coupling with next item: if the next item fits exactly into post_residual,
    // strongly reward; if it nearly fits, mildly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 20.0).max(0.0);
        }
        // Harmonic residue match: next_item_size mod 10 equals pr mod 10
        if pr >= next_item_size && (pr % 10) == (next_item_size % 10) {
            score -= 5.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // worth it only if existing bins are fragmented or this is a big item
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        if item_size >= 60 { score -= 15.0; }
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Prefer filling fuller bins: reward low relative residual fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 10.0;

    // Late-stream consolidation: as stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * progress * 15.0;

    // Mean-residual coupling: when open bins are full on average, be pickier.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps that no plausible item can fill well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from open bins: with many open bins, favor consolidation;
    // with few open bins, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: mildly penalize opening new bins unless residual spread is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    // Deviation from mean residual: prefer bins whose residual stays coherent.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer post_residual that exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.9;

        // Exact match bonus: next item will fill this bin completely.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after the next placement: penalize proportionally to dead space.
            let dead = post_residual - next_item_size;
            score += dead as f64 * 0.35;
        }
        // If next item won't fit here at all, mild penalty for small post_residual.
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual), already in base score.
        score += 10.0; // slight extra tightening when no lookahead exists
    }

    // Reward bins tighter than the mean residual (good fits concentrate space usage).
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f).min(50.0) * 0.25;
    } else {
        score += (residual_f - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize leaving awkward small dead space (<10 unusable for min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: keep it expensive early, cheaper as stream matures or when
    // current bin fits would waste a lot of space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (post_residual as f64 - item_size as f64).max(0.0);
        score = bin_capacity as f64 * 0.9 + progress * 40.0 - waste_pressure * 0.1;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 30.0; // fresh bin can chain the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + gap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).sqrt();
        score += 18.0 + 15.0 * (1.0 - progress) + 4.0 * pressure;
    }

    // Prefer bins whose residual deviates below the mean (consolidate small leftovers).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Mild penalty for very large leftover fragments (unusable space).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 3.0; // awkward fragment zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual (0..1)
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    let mut score = post;

    // Core non-linear coupling: prefer small post_residual, with polynomial shaping.
    // Quadratic + cubic reward for tight fits.
    score -= 30.0 * (1.0 - pr) * (1.0 - pr);
    score -= 15.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - pr);

    // Penalize dead space: residuals too small to be useful later are costly.
    // Smooth dead-space term: residual below typical item floor (~0.1 of capacity).
    let dead = (0.10 - pr).max(0.0);
    score += 120.0 * dead * dead;

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 25.0 * snug * snug;
    } else if next_item_size > 0 {
        // next item won't fit here after placement; mild penalty scaled by how close it was
        let gap = ((next_item_size - post_residual) as f64 / cap).min(1.0);
        score += 20.0 * gap * gap;
    }

    // Stream-progress coupling: late in the stream, tighten up (favor fuller bins more).
    score -= 10.0 * progress * (1.0 - pr) * (1.0 - pr);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - pr);
    } else if fitting_bins_count > 1 {
        // mild penalty to encourage spreading among many fitting bins only when fit is loose
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt() * pr;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Default penalty so existing bins with decent fits win.
        score += 35.0;
        // But if the item leaves a very small post residual (near-full packing),
        // opening a fresh bin is fine; and if no open bin fits, this is the fallback.
        score -= 45.0 * (1.0 - item) * (1.0 - item);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: if open bins are already slack on average, penalize adding
    // more slack; if mean residual is low (bins nearly full), reward using remaining space.
    score += 8.0 * (mean_r - pr).abs() * (mean_r - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: residual buckets by integer division on capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class of post-residual: which quarter of the bin remains.
    let quarter = (post_residual * 4) / bin_capacity; // 0..3
    match quarter {
        0 => score -= 30.0, // near-perfect fill
        1 => score += 6.0,  // dead space risk
        2 => score += 2.0,
        3 => score -= 4.0, // roomy bin still
        _ => {}
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes (10s)
    // leave harmonically reusable space.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match is excellent.
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                let fit_ratio = next_item_size as f64 / post_f;
                score -= 15.0 * fit_ratio;
            }
        } else {
            // Next item cannot use this residual: penalize proportional waste.
            score += 8.0 * (next_item_size as f64 - post_f).min(30.0) / 30.0;
        }
    } else {
        // Last item: any residual is pure waste; prefer tightest.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
    }

    // Late-stream consolidation: fewer open bins is better near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.5;

    // Mild preference for bins below mean residual (tighter bins first).
    score += 0.1 * (mean_residual - post_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual below the minimum item size (1) is impossible, but gaps that
    // cannot accommodate typical items (<= ~20) are near-dead; penalize hard.
    if post_residual > 0 && post_residual < 20 {
        score += 30.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if post_residual >= 20 && post_residual < 40 {
        // Medium gap: mildly attractive.
        score -= 10.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    if bin_residual > 0 {
        let waste_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * waste_ratio;
    }

    // Open-bin pressure: when many bins are open, discourage opening more.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 25.0 + 3.0 * open_bins_count as f64 + 0.2 * mean_residual;
        // But if nothing fits well (few fitting bins), allow opening a new bin
        // when the current bin would leave a bad gap anyway.
        if post_residual < 20 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward using it when bins are plentiful.
        score -= 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward leaving room.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 5.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (spread risk);
    // late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (0.5 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 120.0;
            } else if slack <= 15 {
                score -= 40.0;
            } else {
                // Next item fits but leaves slack: mild penalty scaled by slack.
                score -= 20.0 - (slack as f64).min(20.0);
            }
        } else {
            // Next item does NOT fit after this placement: penalize relative gap,
            // but soften if the leftover is tiny (near-full bin is fine).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
            if post_residual < 10 {
                score -= 30.0; // bin essentially closed anyway
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // penalize dumping into loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when the item is
    // huge relative to capacity (poor fit everywhere else) or many bins open.
    if bin_residual == bin_capacity {
        score += 40.0 - (item_size as f64 / bin_capacity as f64) * 30.0;
        score += (open_bins_count as f64).min(10.0) * 2.0;
        // Discourage opening new bins late in the stream.
        if total_items > 0 {
            score += (step_index as f64 / total_items as f64) * 20.0;
        }
    }

    // Slight preference for filling larger-residual bins when nothing else
    // discriminates (keeps small residuals available for small items).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract for small post_residual (best-fit base already does this).
    // Extra reward when the fit is very tight (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Lookahead: if next item fits into the post residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 8.0 - 4.0 * (slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize creating dead space proportional to unused gap.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 0.15 * (next_item_size as f64 - dead);
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 10.0 + 15.0 * progress;
        // If many bins fit already, opening a new bin is wasteful.
        let crowding = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += base_penalty + 2.0 * (1.0 + crowding).ln();
        // Late in the stream, avoid opening new bins even more (consolidation phase).
        if progress > 0.7 {
            score += 10.0 * (progress - 0.7);
        }
    }

    // Global balance: prefer bins whose residual is close to the mean (avoid fragmentation outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild reward for filling bins that are already quite full (encourage closing bins out).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.6 * t - 0.4 * t * t;
    score = score * poly;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 18.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space that is too small to be useful
    if norm_pr > 0.0 && norm_pr < 0.1 {
        score += 12.0 * (0.1 - norm_pr) * 10.0;
    }

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 + t);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t * 0.5);
    }

    // Mild penalty proportional to crowding of open bins
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantization.
    // Residuals that are small (<=10) are perfect closures; medium ones are wasteful.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: bin closed, ideal
    } else if pr <= 10 {
        score -= 35.0; // near-perfect: dead space likely unusable anyway
    } else if pr <= 20 {
        score -= 5.0;  // small item (10-80 range) may still fill it
    } else if pr <= 50 {
        score += 8.0;  // awkward middle dead space
    }

    // Modulo-harmonic penalty: residuals divisible by common item sizes (10,20,25,50)
    // are "reusable classes" — reward them.
    if pr > 0 && pr < bin_capacity {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // prime-ish / odd residuals are harder to fill later
        if pr % 2 == 1 { score += 3.0; }
    }

    // Lookahead: if the next item exactly matches the post residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally to how much it consumes
            let fill = next_item_size as f64 / pr as f64;
            score -= 20.0 * fill;
        } else {
            // next item cannot use this residual: penalize leaving big gaps
            score += (next_item_size as f64 - pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among competitors, prefer tighter fits (implicit via post_residual already),
        // slight bonus for using fuller bins
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fullness;
    }

    // New-bin candidate handling: an empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when many bins fit the item
        // and the current residual is well-formed.
        score += 30.0 + 5.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build capacity for future).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If mean residual across open bins is small, new bin is more attractive.
        score -= (mean_residual / 10.0).min(20.0);
    }

    // Mild global pressure: when many bins are open, consolidate to avoid sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 8) are pure waste; penalize them extra hard.
    if post_residual > 0 && post_residual < 8 {
        score += 40.0;
    }
    // Post-residual too small for the lookahead item: likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 15.0 + 0.5 * post_residual as f64;
    }
    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward tight-but-usable fits (residual still >= next item or >= 10).
    let tight = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tight) * 10.0;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if mean residual across open bins is very low, opening fresh is fine.
        if mean_residual < 15.0 {
            score -= 35.0;
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.2 * (bin_residual as f64 - mean_residual).max(-50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // exact match for next item is excellent
        if post_residual == next_item_size {
            score -= 250.0;
        }
        // penalize leaving dead space the next item cannot use
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins (tighter bins)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 120.0 * (1.0 - step_index as f64 / total_items.max(1) as f64) + 50.0;
    }

    // Mild penalty for large open_bins_count fragmentation
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus when leftover still fits the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Dead space: waste proportional to unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * gap / (bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it enables a large item soon or
    // when open bins are badly fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_score = 30.0;
        // Attractive if next item is large and nothing fits it well.
        if next_item_size > 0 && next_item_size >= 50 {
            new_bin_score -= 12.0;
        }
        // Early in stream, opening bins is cheaper; late, prefer filling.
        new_bin_score -= 10.0 * (1.0 - progress);
        // If existing bins have low residual (well packed), new bin less costly.
        new_bin_score -= 5.0 * fragmentation / (bin_capacity as f64);
        score += new_bin_score;
    } else {
        // Mild penalty for very small leftovers that are hard to reuse later.
        if post_residual > 0 && post_residual < 10 {
            score += 5.0;
        }
        // Prefer bins whose residual is below mean (filling the tightest first),
        // unless it is the last chance.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Slight preference to balance open bin count growth late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear growth for tiny dead zones
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Quadratic penalty on very small post-residuals (unusable dead space)
    let dead = (12.0 - pr).max(0.0) / 12.0;
    score += 15.0 * dead * dead;

    // Smooth stream-progress coupling: late in stream, tighten bins more
    let tighten = 1.0 + 0.6 * progress * (1.0 - 0.5 * norm_pr);
    score *= tighten;

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 6.0 * (1.0 - (n / pr.max(1.0) - 1.0).abs().min(1.0)) * (1.0 + progress);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.35 * (mean_residual - pr);

    // Mild penalty for opening brand-new bins when others fit
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * (1.0 - progress);
    }

    // Slight crowding penalty to discourage proliferating bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low modulo classes is worse
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize small unusable remainders (dead space < 10)
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Modulo class reward: residual in {0, 25, 50, 75} are "harmonic" sweet spots
    let m = post_residual % 25;
    if m == 0 {
        score -= 12.0;
    } else if m == 10 {
        score -= 6.0;
    } else if m == 5 {
        score += 4.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here: penalize proportionally to waste
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only if this bin would leave large junk
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral baseline: new bin has residual = capacity
        score -= 5.0;
        // if current best-fit options are poor (many open bins but bad fit), new bin attractive
        if post_residual < 20 {
            score -= 30.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Tightness reward: filling a bin nearly full is good
    let fill = 1.0 - pr / cap;
    score -= 10.0 * fill * fill;

    // Slight preference for bins below mean residual (balance)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Many open bins: prefer tightening existing ones over spreading
    if open_bins_count > 4 {
        score -= 0.02 * open_bins_count as f64 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 {
        score += 40.0 * ((100.0 - post_residual as f64) / 100.0).powi(6);
    }
    // Sweet spot: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // residual can still serve the lookahead item mildly.
        score -= 0.15 * (post_residual as f64 - next_item_size as f64).min(30.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space relative to lookahead
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    // rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins and
    // prefer consolidating into existing ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only when existing bins are tight
        // or the item would leave a bad gap elsewhere.
        score += 15.0 + 8.0 * open_pressure - 0.1 * mean_residual;
    } else {
        score -= 2.0 * open_pressure;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Late in the stream, be more aggressive about closing gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: strong default penalty unless current bin
    // choice would create awkward dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If next item is large, a fresh bin is actually attractive.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // Last-chance bin exists: opening new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 20.0;
        }
        return score;
    }

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect two-item packing: strongly reward.
            score -= 60.0;
        } else if diff > 0 {
            // Next item fits after this one: reward proportionally to tightness.
            let tight = 1.0 - (diff as f64 / bin_capacity as f64);
            score -= 40.0 * tight;
        } else {
            // Next item won't fit: penalize dead space creation.
            let dead = (-diff) as f64;
            score += dead * 0.9;
            // Very small dead space is the worst kind of fragmentation.
            if dead <= 10.0 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize residual.
        score += 10.0;
    }

    // Relative-to-mean coupling: bins with residual near the mean are "normal"
    // targets; avoid dumping into already-tight bins unless it finishes them.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();
    if post_residual == 0 {
        score -= 50.0; // perfectly closing a bin is excellent
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    // Progress-based tightening: early stream, keep bins flexible (favor mid
    // residuals); late stream, favor tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space penalty (nonlinear)
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 150.0;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 40.0;
        } else {
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        score -= 200.0 * (1.0 - crowded);
        // penalize opening a new bin early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 * (1.0 - progress);
        if post_residual + item_size as u32 > bin_capacity {
            score += 500.0; // should not happen; guard
        }
        // if item is small, prefer filling existing bins
        if item_size < bin_capacity / 2 {
            score += 60.0;
        }
    }

    // Mild preference for tighter bins relative to mean residual
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Encourage consolidation when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear base: quadratic in normalized post residual.
    let pr_norm = pr / cap;
    let mut score = 2.0 * pr_norm - 1.5 * pr_norm * pr_norm;

    // Coupling of post_residual with stream progress (polynomial).
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score += pr * (0.5 + 1.0 * prog_poly) / 100.0;

    // Penalize large dead space more as stream progresses (bins get locked in).
    score += 3.0 * pr_norm * pr_norm * prog_poly;

    // Lookahead: reward leaving space near next item size (smooth gaussian-ish coupling).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let gap_norm = gap / cap;
        score -= 1.2 * (-gap_norm * gap_norm * 8.0);
    }

    // Last-chance bin: strongly favor using it (avoid opening new bins needlessly).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Mild penalty when many bins are open and this one has big residual.
    score += 0.05 * (open_bins_count as f64) * pr_norm * pr_norm;

    // Slight preference toward bins with residual near mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead zones"
    let residue_class = post_residual % 10;
    // Penalize small nonzero residues (unusable slivers)
    if post_residual > 0 {
        if residue_class <= 2 {
            score += 12.0 * (1.0 - residue_class as f64 / 3.0);
        } else if residue_class >= 8 {
            score -= 4.0; // near-perfect fit class, reward
        }
    } else {
        score -= 50.0; // perfect closure
    }

    // Integer-division thresholds on post_residual
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 6.0; // bin nearly saturated, dead space risk
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.0;
    }

    // Lookahead coupling: does next item fit harmonically?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, especially if post_residual % next_item_size == 0
            score -= 8.0;
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 10.0; // perfect harmonic partition
            }
        } else {
            // next item won't fit here: penalize leaving large residual it can't use
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.15;
        }
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening new bin is unattractive unless residual waste would be huge
        score += 30.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // nothing fits current bins well anyway
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open
    score += (open_bins_count as f64) * 0.05;
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: gaps too small for the minimum plausible item are waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, ideal
    } else if post_residual <= 10 {
        // small unusable-ish gap: heavy penalty
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual <= 25 {
        // moderately small gap: moderate penalty
        score += 18.0 - (post_residual as f64) * 0.4;
    }

    // Reward tight fits (small waste relative to bin capacity)
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 15.0;

    // Lookahead: if next item fits into post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // extra reward if next item nearly fills the gap
        let next_left = post_residual - next_item_size;
        if next_left <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the gap: penalize proportionally
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a new bin is cheap.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean-residual coupling: prefer bins deviating favorably from mean (tighter than average).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in stream, opening new bins is fine; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / 10.0);

    // New-bin candidate: neutral-ish base; only chosen when open bins look bad.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead affinity: next item still fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 0.3 * (item_size as f64);

    // Penalize when the residual deviates far from the mean residual (fragmentation signal).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if current bins are heavily fragmented
    // (mean residual large) or many bins already struggle.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 110.0 - 40.0 * fragmentation - 30.0 * pressure - 0.1 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post_residual too small for smallest item (1) is fine,
    // but mid-range dead space is waste. Dead-space quadratic penalty.
    let pr = post_residual as f64;
    score += 0.06 * pr * (100.0 - pr).max(0.0) * 0.01 * pr;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // next item won't fit here; leftover must be valuable for others
            score += 5.0;
        }
    } else {
        // last item: minimize leftover aggressively
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Time horizon: early in stream, keep bins flexible (penalize low residual);
    // late in stream, just pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let flex_weight = 20.0 * (1.0 - t);
    score += flex_weight * (pr / 100.0) * (1.0 - pr / 100.0) * 2.0;

    // Global state coupling: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 4 && mean_residual > 40.0 {
        score -= 8.0 * (mean_residual / 100.0);
    }
    // Few open bins -> prefer spreading slightly to keep options open early
    if open_bins_count <= 2 && t < 0.5 {
        score += 6.0 * t;
    }

    // New-bin candidate handling: empty bin has no sunk cost; only open when current bin fit is bad
    if bin_residual == bin_capacity {
        // Empty bin baseline: penalize so we only open when fits elsewhere are poor
        score += 55.0;
        // But if item is large relative to capacity and stream is late, opening is cheap
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_sq = pr * pr / (bin_capacity as f64 * bin_capacity as f64);
    score += pr_sq * (10.0 + 30.0 * progress);

    // Reward tight fits (small post_residual), stronger as stream progresses
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Lookahead: penalize if leftover space cannot fit the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - 1.0) > pr {
            score += (next - pr) * (5.0 + 15.0 * progress);
        } else {
            score -= 5.0 * (1.0 - pr / next.max(1.0)).abs();
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 / 2.0)).abs();
        let penalty = 15.0 + 25.0 * (1.0 - progress) + fragmentation * 0.3;
        score += penalty;
        // Late in the stream, opening new bins is cheaper
        score -= 30.0 * progress * progress;
    }

    // Mild penalty for spreading across too many open bins early
    score += open_bins_count as f64 * (2.0 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // ---- Harmonic class of post_residual (dead-space classification) ----
    // Class 0: perfect fit (0). Class 1: tiny unusable slivers (1..=9).
    // Class 2: mid residuals (10..=49). Class 3: large usable residuals (>=50).
    let post_class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 9 {
        1
    } else if post_residual <= 49 {
        2
    } else {
        3
    };

    match post_class {
        0 => { score -= 60.0; }                      // perfect fit: strongly favored
        1 => { score += 35.0; }                      // sliver: near-dead space, penalize
        2 => { score -= 5.0 + (post_residual as f64) * 0.3; } // decent usable space
        3 => { score -= 10.0; }                      // large residual is flexible
    }

    // ---- Lookahead coupling: does the next item fit into post_residual? ----
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic bonus scaled by how well next item fills the remainder
        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 + 20.0 * next_fill;
    } else if next_item_size > 0 && next_item_size > post_residual && post_class == 1 {
        // Sliver that next item cannot use: extra penalty
        score += 10.0;
    }

    // ---- Modulo / integer-division harmonic thresholds on item size ----
    // Items that are divisors or near-divisors of capacity leave friendly residuals.
    let item_mod = item_size % 10;
    if item_mod == 0 {
        score -= 8.0; // round classes (10,20,...) pack predictably
    } else if item_mod <= 3 {
        score += 4.0; // awkward near-round sizes
    }

    // ---- Last-chance logic: if this is the only fitting bin, avoid opening a new one ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Base cost of opening a fresh bin; compare against worst open-bin option.
        score += 45.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 30.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the item is huge, a fresh bin may still be the right call:
        // reduce penalty so big items can open bins when fits elsewhere are awful.
        if item_size > 70 {
            score -= 35.0;
        }
        // If next item is also huge, a fresh bin keeps flexibility.
        if next_item_size > 60 && item_size > 50 {
            score -= 15.0;
        }
    } else {
        // Mild reward for using existing bins, stronger when bins are plentiful.
        score -= 5.0 + 0.5 * (open_bins_count as f64).min(20.0);
    }

    // ---- Mean-residual coupling: if this bin is far below mean residual, ----
    // it is relatively full; filling full bins is good (keeps empties flexible).
    let residual_gap = mean_residual - post_residual as f64;
    if residual_gap > 0.0 {
        score += 0.15 * residual_gap; // bin leaves less than average: good
    } else {
        score -= 0.05 * (-residual_gap); // bin leaves more than average: mild penalty
    }

    // ---- Small tie-breaker on tightness ----
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item (1..=10, plus a small buffer) are wasted forever -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 + (12 - post_residual) as f64 * 4.0;
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large and fragmented (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Penalize new bins moderately; less so late in the stream or when
        // many bins are open with large mean residual (fragmentation).
        score += 30.0 - 10.0 * progress - (open_pressure / 20.0).min(10.0);
        if mean_residual > 40.0 {
            score -= 12.0; // existing bins are roomy -> prefer spreading
        }
        // If the next item could use the leftover of a tight placement elsewhere,
        // slightly discourage hoarding a fresh bin.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 8.0;
        }
    } else {
        // Mild pressure to prefer bins with smaller residual (best-fit flavor)
        score += (bin_residual as f64) * 0.05;
    }

    // Lookahead coupling: if the post residual exactly accommodates the next
    // item, this placement sets up a future perfect fit -> reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 10.0;
    }

    // Open-bin count pressure: discourage spawning many half-empty bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, strongly reward this placement (chained perfect fit).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item can still fit: mild reward proportional to how much
            // slack remains after the hypothetical second placement.
            let second_post = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - second_post / bin_capacity as f64);
        } else {
            // Next item cannot fit into this bin afterwards: penalize,
            // scaled by how much dead space we would strand.
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins whose residual is already tight relative to the mean:
    // filling a below-average-residual bin is more valuable.
    let dev = mean_residual - bin_residual as f64;
    score += 0.6 * dev;

    // Penalize creating small unusable slivers (dead space 1..=5).
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and open bins are already fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let frac = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 55.0 + 30.0 * fragmentation + 20.0 * frac
            - 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a fresh bin for a big item that leaves room for next is fine
            if item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
                score -= 25.0;
            }
        }
    }

    // Mild pressure against proliferating many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that can never fit a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if it wastes this bin's remaining space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (fill fuller bins first).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.5;
    } else {
        score += (bin_res_f - mean_residual) * 0.3;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let size_pressure = item_size as f64 / bin_capacity as f64;
        // Base penalty for wasting a fresh bin; reduced when item is large and bins are crowded.
        let mut new_bin_penalty = 55.0 - 35.0 * size_pressure - 8.0 * crowding.min(3.0);
        // Early in the stream, be conservative (avoid too many open bins).
        new_bin_penalty += 15.0 * (1.0 - progress);
        // If no open bin leaves a good residual, opening a new bin is fine.
        if post_residual == 0 {
            new_bin_penalty -= 40.0;
        }
        score += new_bin_penalty.max(-10.0);
    }

    // Mild time-horizon shaping: later in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows quadratically with residual,
    // and more strongly late in the stream.
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item (smooth sigmoid-ish coupling)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = pr / ns.max(1.0);
        let mismatch = (1.0 - fits_next).max(0.0);
        score += 12.0 * mismatch * mismatch * (0.3 + 0.7 * progress);
    }

    // Reward last-chance bins (fitting_bins_count == 1) with a smooth discount
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 15.0 * last_chance * last_chance;

    // Slight preference for bins below mean residual early (keep big holes for later)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (1.0 - progress);

    // Mild discouragement of opening new bins when many bins already open
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (8.0 + 10.0 * (1.0 - progress)) - new_bin * 20.0 * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: which "slot" of capacity it falls in.
    // Classes: 0 (perfect), 1..=9 (tight), 10..=29 (medium), 30..=59 (loose), 60+ (dead).
    let class = match post_residual {
        0 => 0.0,
        1..=9 => 1.0,
        10..=29 => 2.0,
        30..=59 => 3.0,
        _ => 4.0,
    };
    score += class * 6.0;

    // Reward when next item fits exactly into post residual (chained perfect fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 - slack * 0.35;
        // extra reward if the chain leaves a perfect zero
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    // Penalize when next item is small enough to waste in a large residual
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // residual is unusable for the lookahead item: penalize proportionally
        score += (post_residual as f64) * 0.25;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Modulo harmonic: residual divisible by common item granularity is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // New-bin candidate handling: only attractive when open bins are very fragmented
    // or this bin would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // average dead space if we place here vs using an open bin
        let open_frag = mean_residual / cap;
        // open a new bin when existing bins are tight (little residual) or late in stream
        let bias = 55.0 - open_frag * 70.0 - progress * 12.0;
        score += bias;
        // never open a new bin if a near-perfect fit exists elsewhere is handled by their low scores
    }

    // Slight preference for fuller bins overall (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: if open bins are on average roomy, be pickier (raise scores
    // of loose fits) to encourage consolidation.
    if post > mean_residual {
        score += (post - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never fit a plausible
    // future item are punished super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 8.0; // tiny dead space is very costly
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.5;
        }
        // Reward gaps that can still host the lookahead item exactly
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize gaps too small for the next item if next item would fit here
        if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight relative fit
    score -= (item_size as f64 / bin_residual as f64) * 12.0;

    // Open-bin pressure: prefer compacting into fewer bins when many open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New empty bin candidate: penalize opening unless this is a large item
    // that wastes space in existing bins or few bins exist.
    if bin_residual == bin_capacity {
        let base = 30.0 + mean_residual * 0.4;
        let discount = if item_size > 60 { 12.0 } else { 0.0 }
            + if open_bins_count == 0 { 40.0 } else { 0.0 };
        score += base - discount;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: aggressive 2-step lookahead matching.
    // Perfect fit bonus: post_residual equal to next_item_size means the next
    // item exactly fills this bin -> strongly reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match, penalize near-misses mildly.
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0) * (1.0 - gap / 20.0).max(0.0);
        score += 0.05 * gap;

        // If next item cannot fit post_residual at all, mild penalty unless
        // post_residual is tiny dead space anyway.
        if post_residual < next_item_size {
            score += 2.0;
        }
    } else {
        // Last item: reward tightest packing.
        score -= 3.0;
    }

    // Compare post_residual relative to mean residual across open bins.
    // Leaving post_residual well below mean creates outlier dead space -> penalize.
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev.max(0.0);
    score -= 0.03 * (-dev).max(0.0);

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // very poorly everywhere (high post_residual means big item, fine there).
    if bin_residual == bin_capacity {
        score += 10.0;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.05 * item_size as f64;
        // If few bins fit the item, opening new is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    // Slight preference for filling fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.02 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space, nonlinearly worse for small leftovers
        let pr = post_residual as f64;
        score += (bin_capacity as f64 - pr).max(0.0) * 0.0; // neutral placeholder coupling
        score += (100.0 / (pr + 5.0)) * 2.0;
    }

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize creating a residual too small for anything useful
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    // Many fitting bins: mild penalty to keep fragmentation low
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Tightness reward: bins with small residual are precious, fill them
    let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= tightness * 10.0;

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    if mean_residual > 30.0 && open_bins_count > 3 {
        score += (mean_residual - 30.0) * 0.15;
    }

    // Time horizon: early in stream, be more open to new bins; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus early-stream discount
        score += 25.0 - 20.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (low post residual)
    let mut score = post;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, keep bins flexible (favor larger residuals slightly);
    // later, strongly prefer tight packing.
    let w = 1.0 + 0.8 * progress;
    score += w * (x * x * cap) * 0.5;

    // Cubic dead-space penalty: unusable slivers (post residual too small
    // for typical items) are punished super-linearly.
    score += 30.0 * x * x * x * cap;

    // Lookahead coupling: reward residual that still fits the next item,
    // penalize post residual that wastes space relative to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - progress) * (post - nxt) / cap * 10.0;
        } else {
            score += 8.0 * (post - nxt).abs() / cap * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild pressure toward reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * open_bins_count as f64;
    }

    // Smooth interaction with mean residual: prefer bins below mean residual
    // (denser bins) via a quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual divided into
    // capacity-fraction classes (0, small, medium, large leftovers).
    let post_f = post_residual as f64;
    let class = (post_f / cap * 8.0).floor() as i32; // 0..=7 classes

    // Dead-space penalty: leftovers that no future item (1..=100) can ever
    // pair with are the worst. Class 1 (residual <= 12.5) is nearly dead.
    if post_residual > 0 && post_residual < 13 {
        score += 60.0;
    }
    // Class 2: 13..25 — only very small items fit; mild penalty.
    if post_residual >= 13 && post_residual < 26 {
        score += 18.0;
    }

    // Perfect fit bonus via modulo arithmetic on capacity fractions.
    // post_residual == 0 is a perfect closure: reward heavily.
    if post_residual == 0 {
        score -= 120.0;
    }
    // Harmonic complements: residual is an exact fraction of capacity
    // (25, 50, 75) -> these are reusable "harmonic" classes.
    if post_residual == 25 || post_residual == 50 || post_residual == 75 {
        score -= 25.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward, scaled by tightness
            let tight = 1.0 - (post_f - next_item_size as f64) / cap;
            score -= 40.0 + 30.0 * tight;
        } else {
            // next item will NOT fit here: this bin becomes dead space
            // for the known future -> penalize proportionally to waste.
            score += 12.0 + 0.3 * post_f;
        }
    }

    // Last-chance logic: if this is the only fitting bin, using it avoids
    // opening a new bin; reward unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
        if post_f < 0.10 * cap && post_residual > 0 {
            score += 30.0; // but terrible fit cancels the reward
        }
    }

    // New-bin candidate (empty bin): only attractive when open bins are
    // congested (low mean residual) or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        }
        if mean_residual < 15.0 {
            score -= 55.0; // existing bins nearly full -> open fresh one
        }
        // Harmonic: opening a bin when the item is large leaves a
        // "complementary" residual that pairs with small items well.
        if item_size >= 50 && item_size <= 90 {
            score -= 10.0;
        }
    }

    // Stream progression: early on, prefer consolidation (keep few bins);
    // late in the stream, closing bins perfectly matters more.
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress * (1.0 - post_f / cap);

    // Prefer bins whose residual deviates favorably from the mean
    // (use the tightest bins first to preserve large residuals).
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..12)
    // are pure waste; penalize them heavily so tight fits win.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the known next item.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // Opening a bin is cheap late in the stream (few future regrets).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Mild pressure against accumulating many open bins with scattered space.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight fit).
    score += 0.2 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead-space penalty (quadratic in waste)
        let waste = post_residual as f64;
        score += 0.02 * waste * waste / bin_capacity as f64;
    }

    // 2-step lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit: leftover after both placements
            let chain_left = post_residual - next_item_size;
            score -= 60.0 + 0.5 * (chain_left as f64);
        } else {
            // next item cannot chain here; penalize proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
        // bonus if next item fits *exactly* after this placement
        if post_residual == next_item_size {
            score -= 80.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score += 0.0;
    }

    // Compare against mean residual: prefer bins tighter (or looser) than average
    // depending on whether this bin is above/below mean residual
    if (bin_residual as f64) > mean_residual {
        // this bin is roomier than average -> placing here reduces fragmentation
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score += 30.0;
        // but attractive if item is large relative to capacity (hard to place later)
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // if next item is large too, a fresh bin pairs well with big items
        if next_item_size > 0 && (next_item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Early in stream: slightly discourage new bins (build up reuse pool)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: penalize large post_residual more aggressively as it grows
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight_fit * tight_fit;

    // Lookahead: if next item fits exactly in the post residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining: leaves exactly the space the next item needs
        } else if post_residual >= next_item_size {
            // next item fits after this placement; reward proportionally to how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item would not fit here; slight penalty proportional to waste
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: prefer minimizing leftover but new-bin opening is pointless
        score += 5.0; // discourage opening a fresh bin for the final item
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny dead space (unusable slivers) that no plausible item fits
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare bin residual against the mean residual across open bins:
    // prefer filling bins with above-average residual (keep small-residual bins for small items)
    if bin_residual as f64 > mean_residual {
        score -= 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Early in the stream, opening new bins is cheaper; late, consolidate tightly
    let time_pressure = progress * progress;
    score += 10.0 * time_pressure * (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * (1.0 - progress) * tight_fit;

    // Mild penalty when many bins are already open and we'd keep fragmenting capacity
    if bin_residual == bin_capacity {
        // new-bin candidate: acceptable early or when open bins have poor fits
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 8.0 * (1.0 - progress) * poor_fit_elsewhere;
        score += 14.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, but with a smooth non-linear (quartic-ish) decay
    // so that small post-residuals are strongly preferred (tight packing).
    let mut score = pr * pr / cap * (1.0 + pr / cap) - 2.0 * pr;

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly (fewer chances to fill it).
    let progress_coupling = 1.0 + progress * (pr / cap) * (1.0 - progress);
    score += progress_coupling * (pr / cap).powi(3) * cap * 0.5;

    // Reward bins whose post-residual smoothly matches the next item size
    // (polynomial interaction instead of hard thresholds).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        let match_term = (diff * diff) / cap; // 0 when next item fits perfectly
        score -= (1.0 - progress) * match_term * 0.8;
        // penalize when next item cannot fit at all (post_residual < next)
        let cannot_fit = ((nxt - pr).max(0.0) / cap).powi(2) * cap;
        score += 1.5 * cannot_fit;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin, scaled smoothly by how well it fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (pr / cap);
        score -= 8.0 * tightness;
    }

    // Slight preference for bins with below-mean residual (consolidate fuller bins),
    // smoothly interpolated.
    score += 0.3 * ((mean_residual - bin_residual as f64) / cap).max(-1.0).min(1.0);

    // New-bin candidate: give it a moderate baseline so it's chosen only when
    // open bins have genuinely poor fits (high post-residual or mismatch).
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity divided into 5 classes
    let item_class = item_size / 20; // 0..4
    let post_class = post_residual / 20;

    // Reward tight fits (small post_residual), strongly for exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Dead-space penalty: post_residual too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Harmonic coupling: reward when post_residual class matches a useful
    // companion class (e.g. residual that pairs with a small item)
    let pair_bonus = match (post_class, item_class) {
        (4, 0) => 40.0, // big residual left, small item used: good
        (3, 1) => 30.0,
        (2, 2) => 25.0,
        (1, 3) => 20.0,
        _ => 0.0,
    };
    score -= pair_bonus;

    // Modulo arithmetic on post_residual: multiples of 10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead: penalize if next item cannot fit the post_residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 10.0; // wasted opportunity for lookahead item
        } else if post_residual - next_item_size <= 5 {
            score -= 60.0; // lookahead completes the bin nearly perfectly
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 60.0;
        // But if item is huge and mean residual is small, new bin is fine
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 100.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild pressure against leaving many bins with tiny residuals
    if mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.3 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Dead space that cannot fit the next item is worse
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open bins pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
    } else {
        // Last chance bin bonus
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Slight preference toward bins with below-mean residual (keep some large bins for big items)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Later in the stream, be slightly more tolerant of new bins to avoid over-tight packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- 2-step lookahead: reward exact match with next item ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits here too: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack / 20.0);
        } else {
            // Next item cannot use the leftover: penalize dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.6;
        }
    }

    // ---- Tightness of current placement ----
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 30.0; // small leftovers are fine, mid-size waste is bad

    // ---- Compare against mean residual across open bins ----
    // Favor bins that are already below-average filled (concentrate waste),
    // penalize dipping into the fullest bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.35;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // ---- Last-chance bonus: only bin that fits avoids opening a new bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin gives a tight fit.
        // If this item leaves a very tight residual in an open bin, prefer it.
        if post_residual <= 5 {
            score += 80.0; // an open bin is nearly perfect -> don't open new bin
        } else {
            // Encourage new bin when current fit is loose and mean residual is low.
            score -= 10.0 + mean_residual * 0.05;
            if fitting_bins_count == 0 {
                score -= 40.0; // forced new bin anyway
            }
        }
    }

    // ---- Stream progression: early on, keep bins flexible; late, pack tight ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared dead-space penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Lookahead: strongly reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / 10.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // penalize leaving a sliver that the next item cannot use
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless open bins are very full
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 40.0 - pressure * 25.0 - progress * 8.0 + openness * 2.0;
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (consolidation)
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post residual, with quadratic tightening over time.
    let base = post + 0.35 * post * post / cap;

    // Smooth progress coupling: later in stream, penalize leftover space more aggressively.
    let progress_coupling = base * (0.5 + 1.5 * progress * progress);

    // Reward filling bins well (large item fraction of capacity).
    let fill_bonus = -6.0 * (item / cap) * (item / cap) * (1.0 + progress);

    // Penalize creating dead space relative to mean residual of open bins.
    let dead_space_penalty = 0.25 * (post - mean_residual).abs() / cap;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -12.0 } else { 0.0 };

    // Lookahead: if next item fits exactly into post residual, big reward.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= post {
        -5.0 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        // penalize post residual that next item cannot use proportionally to gap
        0.10 * ((next_item_size as f64 - post) / cap)
    } else {
        0.0
    };

    // New-bin candidate handling: empty bin gets a smooth opening cost that
    // decreases as stream progresses or when few bins fit the item.
    let new_bin_cost = if bin_residual == bin_capacity {
        8.0 - 6.0 * progress + 2.0 * (fitting_bins_count as f64).ln().max(0.0)
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins.
    let spread_penalty = 0.02 * open_bins_count as f64;

    progress_coupling + fill_bonus + dead_space_penalty + last_chance + lookahead + new_bin_cost + spread_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity left after placement

    // Integer-division threshold on post_residual: bins with tiny leftovers are "sealed" well.
    let class = post_residual / 10; // harmonic class bucket of width 10
    match class {
        0 => score -= 30.0,                 // 0..=9 leftover: excellent sealing
        1 => score -= 18.0,                 // 10..=19
        2 => score -= 10.0,                 // 20..=29
        3 => score -= 4.0,                  // 30..=39
        4 | 5 => score += 6.0,              // 40..=59: mediocre leftover
        6 | 7 => score += 12.0,             // 60..=79: large leftover, wasteful
        _ => score += 20.0,                 // 80+: very wasteful placement
    }

    // Non-linear reward for exact or near-exact fits (modulo arithmetic on residual).
    let m = post_residual % 10;
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if m <= 2 {
        score -= 8.0;  // near-exact fit
    } else if m >= 8 {
        score += 5.0;  // awkward remainder class
    }

    // Penalty scaled by waste fraction, superlinear to punish dead space.
    score += 25.0 * frac * frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let nxt_class = (post_residual - next_item_size) / 10;
            if nxt_class <= 1 {
                score -= 15.0; // next item leaves a well-sealed bin
            } else if nxt_class >= 5 {
                score += 8.0;  // next item would leave huge slack
            }
        } else {
            // next item cannot fit here: mildly penalize leaving mid-range slack
            score += 4.0 * (1.0 - frac);
        }
    }

    // New-bin candidate logic: only attractive early in the stream or when few bins fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score = c * 0.75 + 25.0 * progress * openness - 20.0 * (1.0 - frac);
        if fitting_bins_count <= 2 {
            score -= 15.0; // few alternatives, new bin is fine
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin serves next item too
        }
    }

    // Mild tie-breaker toward denser bins (low mean residual means bins are getting full).
    score += (mean_residual / c) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual == 0 {
        score -= 60.0; // perfect closure is ideal
    } else if post_residual < 10 {
        score += 45.0; // tiny unusable sliver -> strong penalty
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild alignment with mean residual state.
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Early in stream: be slightly more willing to open bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 - progress * 4.0; // new-bin candidate baseline
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize wasting a large residual.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 15.0 * waste;
        }
    }

    // Compare residual against mean residual: prefer bins that absorb slack.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score = (bin_capacity as f64) * 0.6
            + 50.0 * (1.0 - tightness)
            - 20.0 * poor_fits
            + if fitting_bins_count <= 1 { 0.0 } else { 30.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: penalize large post_residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Reward small residuals (good fill), but avoid exact zero residual too early (keep flexibility).
    if post_residual == 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
    }

    // Lookahead coupling: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Even better: next item would nearly fill post_residual.
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving large unusable space.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let residual_spread = bin_residual as f64 - mean_residual;
    if mean_residual > item_size as f64 {
        score -= 5.0;
    }
    score += residual_spread * 0.15;

    // Time horizon: early in stream, opening new bins is cheaper (exploration);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized late.
        score += 20.0 * progress;
        score -= 10.0 * (1.0 - progress);
        // Penalize new bin more if existing bins fit well already.
        if post_residual > bin_capacity / 2 {
            score += 15.0 * progress;
        }
    } else {
        // Existing bin: bonus grows with progress (consolidation pressure).
        score -= 10.0 * progress;
    }

    // Open bins count pressure: too many open bins -> discourage new bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // Small regularization noise-free tiebreak: prefer bins with moderate residual.
    score += ((bin_residual as f64 - bin_capacity as f64 * 0.5) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with non-linear emphasis on tight fits.
    let mut score = pr * (1.0 + 0.8 * pr / cap) + 12.0 * (pr / cap).powi(3);

    // Smooth stream-progress coupling: late in the stream, tolerate residual more
    // (fewer future items), early in the stream penalize dead space more.
    let prog_term = 1.0 + 1.5 * progress * progress;
    score *= prog_term;

    // Reward bins that can also fit the next item (lookahead synergy), smoothly.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let tightness = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 10.0 * fits_next * tightness.max(0.0);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild pressure toward consolidating into few bins.
    score += 0.05 * open_bins_count as f64;

    // Penalize bins far from mean residual (prefer homogeneity), smooth quadratic.
    score += 0.02 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Discourage opening a new bin unless current fit is poor (smooth gate).
    let new_bin = (bin_residual == bin_capacity) as f64;
    let fit_quality = 1.0 - pr / cap; // high when post_residual small
    score += new_bin * (30.0 - 25.0 * fit_quality.max(0.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it falls in
    let item_class = (item_size * 4) / bin_capacity; // 0..3 (small, medium, large, huge)
    let residual_class = (post_residual * 4) / bin_capacity;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residual that no typical item can use
    // Items are >= 1, but small residuals (< next plausible item) are wasteful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Harmonic pairing: does post_residual exactly complement the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect lookahead fit
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            // reward leaving room for next item, scaled by how close the fit is
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty unless bin nearly full
            score += 6.0 * (1.0 - tightness);
        }
        // modulo coupling: same harmonic class pairing bonus
        let next_class = (next_item_size * 4) / bin_capacity;
        if next_class + item_class == 3 && post_residual >= next_item_size {
            score -= 12.0; // complementary classes summing to full capacity band
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate handling: empty bin gets a moderate default score
    if bin_residual == bin_capacity {
        // opening a new bin is good when existing residuals are large and fragmented
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin late in stream or when open bins are mostly full
        score = 45.0 - 30.0 * fragmentation - 15.0 * progress;
        // if many bins can fit, discourage new bin mildly
        if fitting_bins_count > 0 {
            score += 8.0;
        }
        // big items prefer fresh bins
        if item_class >= 2 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier bins first
    // keeps fuller bins available for large items)
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += 4.0;
    }

    // Integer division threshold: post_residual in the "awkward" 30..50 band is bad
    let half = bin_capacity / 2;
    if post_residual >= half && post_residual < half + 20 && next_item_size > 0 && next_item_size > post_residual {
        score += 9.0;
    }

    // Slight preference for bins with residual exactly in an item-class complement
    let complement = bin_capacity.saturating_sub(item_size);
    if bin_residual == complement {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps too small for typical next items (non-linear dead zone).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 + (10.0 - post_residual as f64).max(0.0) * 2.0;
    }

    // Reward tight fits (exact or near-exact fill).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (its post_residual is huge, so base score already disfavors it;
    // add mild penalty so it only wins when open bins have terrible fits).
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if this is the last item stream region and bins are crowded,
        // new bin becomes relatively cheaper.
        score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Slight preference for bins below mean residual (balancing load).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: residual after placement equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Softer reward if next item still fits after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.35 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Penalize dead space that next item cannot use (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Tight fits are good: small post_residual relative to capacity is rewarded.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare residual against mean residual: prefer filling below-average bins.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if lookahead item is large and no good fit exists, opening is less bad.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Early in the stream, be more willing to open bins (build diversity of residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Slight penalty for item sizes that leave awkward residuals (not multiples of 10).
    let r = post_residual % 10;
    if r != 0 {
        score += 2.0 + 0.1 * r as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 12.0;

    // Penalize dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty if we leave a large odd gap.
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (reduce fragmentation).
    if open_bins_count > 4 {
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score -= dev * 0.3;
        } else {
            score += (-dev) * 0.3;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins over
    // wrecking big residuals); late in the stream, squeeze every bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - fit_ratio);
    score += (1.0 - progress) * 5.0 * fit_ratio;

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // fits well (large post_residual relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += open_pressure;
        score += (1.0 - progress) * 20.0;
        score += mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on, tolerate slack; later, demand tight fits.
    score *= 1.0 + 0.35 * progress * (1.0 - norm_pr);

    // Dead-space penalty: quadratic in unusable residual relative to mean residual.
    let dead = (pr - mean_residual).abs() / cap;
    score += 12.0 * dead * dead * cap * 0.01;

    // Lookahead coupling: reward post_residual that can still host the next item,
    // penalize residual that neither fits next item nor is small.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - (nxt / cap)) * (pr / cap).sqrt();
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild preference for consolidating among many open bins.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make empty bin unattractive unless item is huge or no good fit exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 60.0 - 45.0 * fill * fill - 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by residue modulo 10
    let class = post_residual % 10;
    match class {
        0 => score -= 15.0,            // clean decade residual, reusable
        1 | 2 => score += 20.0,        // tiny slivers, nearly dead
        3 | 4 => score += 8.0,         // awkward small residual
        5 => score -= 5.0,             // half-decade, moderately reusable
        6 | 7 => score += 3.0,
        8 | 9 => score -= 2.0,
        _ => {}
    }

    // Integer-division thresholds: how many "size-10 slots" remain
    let slots = post_residual / 10;
    if slots >= 5 {
        score -= 10.0; // bin still half-full-ish, good target
    } else if slots == 0 && post_residual > 0 {
        score += 25.0; // sub-10 dead space
    }

    // Next-item coupling: reward if next item fits post_residual exactly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap < 10 {
            score -= 25.0;
        } else {
            score -= (10.0 - (gap % 10) as f64) * 0.5;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; penalize small residuals that become dead
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
    }

    // Last-chance bonus: only one bin fits, prefer using it over new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when residuals are messy
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 20.0 + 30.0 * pressure - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size >= 60 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are high
    if mean_residual > 50.0 && open_bins_count > 3 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 40.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor compacting.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
    score += 5.0 * pressure;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless the current
    // fit is poor (dead space) or no bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is an ideal chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 100.0 * snug;
        } else {
            // Next item cannot fit in this bin's leftover: penalize dead space.
            score += 50.0 + (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual to mean residual: leaving less than average
    // leftover is good (compact packing).
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // would create large dead space.
    if bin_residual == bin_capacity {
        score += 300.0;
        if post_residual as f64 > mean_residual {
            score += 100.0;
        }
    }

    // Late in the stream, tighten packing to avoid leftover sprawl.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize tight-but-wasteful fits: dead space below the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward good fill ratio, stronger early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        }
        // Penalize if post residual can't fit next item but is large-ish (fragmentation risk).
        if post_residual as f64 > next_item_size as f64 * 0.5 && (post_residual as u32) < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate handling: neutral baseline, slightly favored when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else if mean_residual < item_size as f64 * 0.6 {
            score -= 20.0; // open bins are too full to be attractive
        }
    }

    // Prefer bins with residual far from mean (use outlier space) mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild pressure against accumulating too many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: normalized post residual, polynomial shaping
    let x = pr / cap; // in [0,1]
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like dead-space penalty
    score += 12.0 * poly;

    // Reward near-perfect fills with a smooth quadratic bonus
    let tightness = 1.0 - x;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: penalize leaving residual that wastes space relative to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 {
            let gap = (pr - nxt).abs();
            score += 0.15 * gap;
            // Reward residuals that exactly or nearly fit the next item
            if nxt <= pr {
                score -= 0.5 * (1.0 - gap / cap) * 10.0;
            }
        }
    }

    // Stream progress: as stream advances, be more conservative about spreading
    // across bins; prefer tighter packing (amplify dead-space penalty late)
    score += progress * 8.0 * poly;

    // Mild penalty for bins already far below mean residual (fragmentation spreading)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: make empty bin mildly attractive only when current
    // fit is poor; otherwise discourage opening new bins unnecessarily
    if bin_residual == bin_capacity {
        score += 6.0;
        if pr > 20.0 {
            score += 0.3 * pr;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions) ---
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // 0.0 .. 1.0

    // Dead-space penalty grows super-linearly for tiny unusable slivers.
    // Slivers below 10 (min legacy item) are pure waste; below 1/4 of
    // capacity they are hard to fill for arbitrary distributions.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: heavily reward
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver: heavy penalty
    } else if frac < 0.25 {
        score += 25.0 * (0.25 - frac);
    } else if frac < 0.5 {
        score += 6.0 * (0.5 - frac);
    }

    // --- Integer-division thresholds on post_residual ---
    // Harmonic classes: residuals in [k*25, (k+1)*25) get class-graded
    // bonuses; quarter-class boundaries are natural fill targets.
    let quarter_class = (post_residual / 25) as f64;
    score -= 4.0 * quarter_class; // larger usable residual classes mildly favored over tight-but-fragile fits

    // Modulo arithmetic: residuals that are multiples of common item
    // granularities are easier to fill exactly later.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // --- Lookahead coupling with next item ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item still fits here: reward keeping this bin viable.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 0.1 * slack;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0; // chained harmonic fit
            }
        } else {
            // Next item won't fit after this placement: penalize,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.15 * miss.min(50.0);
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only open bin that fits: strongly prefer using it over a new bin.
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild diversity bonus: keep alternatives alive.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline cost of opening. Beat it only when
        // existing fits are poor (large residuals / dead space).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - 10.0 * progress
            + 0.5 * (bin_capacity as f64 - item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0; // fresh bin accommodates lookahead cleanly
        }
        if item_size > 60 {
            score -= 15.0; // huge items: fresh space is usually right
        }
    }

    // --- Stream-phase modulation ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    // Late in the stream, avoid leaving many half-empty bins: penalize
    // spread, reward consolidating into already-open bins.
    score += progress * 0.05 * open_bins_count as f64;
    if mean_residual > 0.0 {
        // Prefer bins below mean residual (tighter packing) early,
        // but near the end prefer bins above mean (burn down slack).
        let dev = (bin_residual as f64 - mean_residual) / cap_f;
        score += (if progress < 0.7 { dev } else { -dev }) * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 6.0; // tiny leftovers are almost worthless
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.0;
        }
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to item size (small relative slack).
    let rel_slack = post_residual as f64 / bin_capacity as f64;
    score += rel_slack * rel_slack * 30.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
    }

    // Lookahead: if next item fits exactly in the post residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next == 0 {
            score -= 20.0;
        } else if leftover_after_next < 10 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item won't fit here; small penalty for stranding residual
        score += 4.0;
    }

    // Mild preference for bins below mean residual (balance spreading).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight nonlinearity.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Aggressive 2-step lookahead: reward if the next item exactly matches
    // the post_residual (perfect chaining), penalize if next item cannot fit.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain: next item fills this bin completely
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how much it would consume
            let chained_post = post - nxt;
            score -= 15.0 * (1.0 - chained_post / bin_capacity as f64);
            // extra reward if chain is near-perfect
            if chained_post <= 5.0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow into this bin: penalize dead space
            score += 8.0 + 0.1 * (nxt - post);
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 10.0;
    }

    // Relative-to-mean-residual coupling: bins with residual far below mean
    // are "almost full" -> good to pack into; above mean -> less attractive.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or residuals across open bins are all small.
    if bin_residual == bin_capacity {
        let open_fits_poorly = mean_residual < item_size as f64 * 1.2;
        if open_fits_poorly {
            score -= 5.0; // fresh bin better than stuffing tiny residual
        } else {
            score += 12.0; // discourage opening new bins when decent fits exist
        }
    }

    // Slight phase awareness: early in stream, keep bins flexible (avoid
    // creating tiny residuals); late, just minimize waste.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - phase) * (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small dead space is nearly as good.
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual as u32 {
            score -= 4.0;
        } else {
            // Next item cannot use the leftover; slight penalty for creating waste.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when no open bin
    // fits well. Penalize opening new bins when open bins are fairly empty,
    // reward it when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins early; allow more freely late when fragmentation is high.
        score += 30.0 - 20.0 * progress + fragmentation * 0.1;
        // If many open bins exist and item is large, opening a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate emptier bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.05;
    }

    // Global load balancing: discourage spreading across too many open bins
    // when they are all nearly full anyway.
    if open_bins_count > 8 && post_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling: small post-residuals are better; effect grows with progress
    let tightness = (1.0 - norm_pr).powi(3);
    score -= tightness * (20.0 + 30.0 * progress);

    // Penalize mid-range dead space (unusable gaps), smooth quadratic bowl
    let dead = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at 0.5
    score += dead * dead * 12.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize lightly early, more when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(5.0);
        score += 10.0 + fragmentation * 3.0 - 10.0 * progress;
    }

    // Lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let compat = if pr >= ns { 1.0 - (pr - ns) / cap } else { 0.0 };
        score -= compat * compat * 8.0;
    }

    // Mild penalty for scattering across many bins
    score += (open_bins_count as f64).sqrt() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (low post_residual).
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    score += 40.0 * post_frac * post_frac;

    // Harmonic class of post_residual: bins whose residual falls into
    // "dead space" classes (small, unusable remainders) get penalized.
    let dead_threshold = bin_capacity / 10; // residual < 10 is dead space
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // creating unusable sliver
    }

    // Integer-division thresholds on post_residual: classify leftover into
    // harmonic bands of capacity/4 and reward bands matching common item sizes.
    let band = (post_residual / (bin_capacity / 4)) as f64;
    score -= 6.0 * band;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize more if post_residual is large
            score += 8.0 * post_frac;
        }
        // modulo coupling: next item leaves another clean quarter-band
        if post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain % (bin_capacity / 10) == 0 && chain > 0 {
                score -= 7.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - post_frac);
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening new bins moderately, more early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let mean_fit = 1.0 - (mean_residual / cap).min(1.0);
        score += 55.0 * (1.0 - progress) * (0.5 + 0.5 * open_pressure) + 20.0 * mean_fit;
        // but if item is huge relative to typical residual, new bin is attractive
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Mild penalty for spreading across too many open bins when mean residual is high.
    if bin_residual < bin_capacity {
        score += 0.05 * open_bins_count as f64 * post_frac;
    }

    // Small harmonic tie-breaker on residual modulo class to stabilize choices.
    score += ((post_residual % 7) as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 150.0;
    } else {
        // Larger leftover gaps: mild penalty scaled by gap size.
        score += 0.5 * post_residual as f64;
    }

    // Reward filling bins deeply (high fill ratio).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 90.0 + 8.0 * open_bins_count as f64;
        // If the new bin would leave a large gap, extra penalty.
        if post_residual < 20 {
            score += 100.0;
        }
    } else {
        // Reusing an existing bin reduces fragmentation: reward.
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the resulting gap, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 100.0;
    }
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item cannot use this gap: penalize leaving a gap the lookahead can't fill.
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Early stream: be slightly more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward exact/near-exact fits extra.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Perfect chain: next item exactly fills this bin -> big bonus.
            if gap < 1.0 {
                score -= 40.0;
            } else {
                // Proportional reward for closeness of the chain fit.
                score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
            }
        } else {
            // Next item cannot use this bin's leftover; penalize proportionally to waste.
            score += 6.0 * (1.0 - pr / (bin_capacity as f64));
        }
        // If chain leaves a very small unusable sliver after the next item, penalize.
        let post2 = pr - nxt;
        if post2 >= 0.0 && post2 < 3.0 && post2 > 0.0 {
            score += 10.0; // dead sliver
        }
    } else {
        // Last item: only tightness matters (already applied).
    }

    // Relative-to-mean coupling: bins with residual well below mean are precious tight fits.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish base; look at best alternative implicitly via fitting count.
        score = 55.0;
        if fitting_bins_count <= 1 {
            // No real alternative (or only one weak option): encourage opening new bin.
            score -= 20.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * (bin_capacity as f64) {
            // Big next item: keeping current bins' large residuals may matter; slight new-bin push.
            score -= 5.0;
        }
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Mild penalty for spreading across many open bins when stream is early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > 4.0 + 20.0 * (1.0 - progress) {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, but only when it's truly unusable
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dead = if next_item_size > 0 && (next_item_size as f64) > pr { 1.0 } else { 0.0 };
        score += dead * pr * pr * 0.02;
    }

    // Reward tight fits
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 8.0;

    // Last-chance bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0;
        // extra reward if next item fills it well
        let gap = post_residual - next_item_size as u32;
        score -= (gap as f64).min(10.0) * 0.3;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item won't fit here; mild penalty proportional to waste
        score += ((next_item_size as f64) - pr) * 0.15;
    }

    // Late in the stream, consolidate into fewer bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0;

    // Prefer bins with below-average residual (denser bins) when many bins are open
    if open_bins_count > 2 {
        let dev = (bin_residual as f64) - mean_residual;
        score += dev * 0.08 * (open_bins_count as f64).ln().max(1.0);
    }

    // Mild penalty for opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 4.0;
        if fitting_bins_count > 0 && (item_size as f64) / cap > 0.5 {
            score += 6.0; // large items should go into existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 12.0 * x * x * (0.5 + progress);
    score += 20.0 * x * x * x * (1.0 - progress);
    score -= 15.0 * (1.0 - x) * (1.0 - x) * progress * progress;

    // Tight fit reward (small post residual relative to item)
    let tightness = 1.0 - x;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress);
    }

    // Lookahead: penalize if next item fits poorly in post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = nx - x;
        if gap > 0.0 {
            score += 10.0 * gap * gap * cap;
        } else {
            score -= 6.0 * (-gap) * (1.0 - progress);
        }
    }

    // Crowding penalty relative to mean residual
    score += 5.0 * ((x * cap - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common size classes
    // (10..80 items => residues in {0,10,...}) are more reusable.
    let class = |r: u32| (r / 10).min(10) as f64;

    // Reward small post_residual, but reward reusability more strongly.
    score -= 2.0 * class(post_residual);

    // Penalize dead space that is too small to fit even the smallest plausible item (1..100).
    // Leftovers < 10 are nearly dead; leftovers in [10,30) are semi-dead.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use this leftover: penalize large wasted leftovers
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be tiny).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it mildly
    // attractive only when current fit is poor (large post_residual or dead space).
    if bin_residual == bin_capacity {
        // Base preference for fresh bin scaled by progress (early: open freely).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - 20.0 * progress;
        if post_residual < 10 { score -= 30.0; } // keep penalty visible via item fit? (not applicable)
        // If many bins already open, discourage proliferation.
        score += open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin is fine.
        if next_item_size >= 50 { score -= 10.0; }
    }

    // Mean residual context: when average residual is high, prefer tight fits.
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Modulo harmonic: leftover that is a multiple of 10 is reusable by typical items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: residuals below the minimum item size (1)
    // are unavoidable, but residuals in the "awkward" small range are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Strong reward for exact fit (perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space avoidance: penalize residuals that cannot fit the next item,
    // rewarding bins whose leftover still accommodates the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; when few bins are open, allow
    // opening new bins more freely.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins would leave
        // large dead space or fitting options are scarce.
        score += 25.0 + 8.0 * pressure;
        if fitting_bins_count <= 1 && post_residual > 0 {
            score -= 35.0; // last-chance bin: strongly prefer using it
        }
    } else {
        // Reward using tight fits among open bins.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * pressure.recip();
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // already "wasted"; prefer filling it to catch up with the mean.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer opportunities to amortize them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual,
    // this bin chains perfectly — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // If next item fits into post-residual, mild reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack * 0.5;
    }

    // Penalize dead space that the next item cannot use (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let dead = post_residual as f64;
        score += dead * 1.5;
        // Extra penalty for small unusable gaps (classic bad residual).
        if dead < 10.0 {
            score += 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual space
    // elsewhere is badly fragmented. Scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual - post_residual as f64;
        // Prefer existing bins when mean residual is reasonably large.
        if mean_residual >= item_size as f64 {
            score += 300.0;
        } else {
            score -= 100.0 + fragmentation * 0.5 + progress * 50.0;
        }
    }

    // Mild preference for tighter (smaller-residual) bins relative to the mean.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin now but not after this placement -> mild penalty.
            score += 6.0;
        }
        // If next item is large, prefer keeping big residual bins intact.
        if next_item_size > post_residual && post_residual < next_item_size {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate logic: empty bin gets a baseline cost so it's chosen only when
    // open bins fit poorly; the cost shrinks as the stream progresses (sunk bins matter less).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 * (1.0 - 0.5 * progress);
    } else {
        // Slight reward for using already-open bins to consolidate.
        score -= 2.0;
    }

    // Global state: when mean residual is high, avoid spreading; prefer bins below mean residual
    // (concentrate filling), penalize picking bins above mean.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    if (bin_residual as f64) > mean_r && bin_residual != bin_capacity {
        score += 3.0;
    } else if bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // Many open bins: encourage closing them out (prefer bins with small residual).
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer larger leftovers (flexibility);
    // late in the stream, prefer tight fills (minimize dead space).
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);
    score += w_early * 0.35 * (post / cap) * (1.0 - post / cap) * cap;
    score -= w_late * 0.30 * (1.0 - post / cap) * cap;

    // Penalize new-bin candidate unless it yields a very tight fill.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let tightness = 1.0 - post / cap;
        score += 12.0 - 20.0 * tightness.powi(2);
    }

    // Last chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize residual just barely below next item (near-miss dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 2.5 * (1.0 - ((post - nxt) / cap).min(1.0));
        } else {
            score += 1.5 * (nxt - post) / cap;
        }
    }

    // Mild pull toward bins below mean residual (consolidate fragmentation).
    score += 0.10 * (post - mean_residual).max(0.0) / cap;
    // Slight penalty for proliferating open bins.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic classes: dead space in low residue classes is unusable for typical items.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny gap likely dead space
    }

    // Modulo-arithmetic classes on post_residual: residues that pair well with
    // small items (multiples of 10) are more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    } else if pr % 10 != 0 && pr < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - slack * 0.5;
        } else {
            // next item cannot use this bin's remainder: penalize small remainders
            if pr < next_item_size && pr < 30 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral baseline: prefer open bins unless they leave bad residue.
        score = 55.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // large next item: fresh bin is attractive
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.05;

    // Progress-based gentle scaling: early stream, be frugal with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 20.0;
    }

    // Mean-residual context: if average residual is large, tolerate imperfect fits.
    if mean_residual > 30.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Tight fit: post_residual small relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 8.0 * tightness;

    // Last chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize proliferation of open bins.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins below mean residual (filling emptier bins keeps tight bins flexible).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Lookahead: post_residual too small for next item but nonzero = dead space risk.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: neutral baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer filling bins tightly (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect 2-step match: big reward.
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64 * 0.5)).max(0.0);
        // Exact match bonus.
        if gap == 0.0 {
            score -= 25.0;
        }
        // Slight bonus if next item fits at all in the residual.
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize post_residual that is too small to ever be useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins with residual below mean
    // (tighter bins get emptied first), penalize very loose bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bin unattractive unless it enables
    // a perfect 2-step match that no open bin can offer.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // But if next item would perfectly fill this fresh bin after placement,
        // relax the penalty (large item + perfect follow-up).
        if next_item_size > 0 && post_residual == next_item_size && item_size >= 50 {
            score -= 70.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // Many open bins: opening another is cheaper than fragmenting.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Small reward for placing larger items into emptier bins (balance residuals).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the only chance for the next item in this bin.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            18.0 + 10.0 * (1.0 - progress)
        };
        score += pressure;
        // Late in the stream, opening new bins is even worse.
        if progress > 0.7 && fitting_bins_count > 0 {
            score += 10.0;
        }
        // If no open bin fits, the new bin is required; soften penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild diversity pressure: many open bins -> favor consolidating into fuller ones.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual) mildly;
    // late in the stream, penalize large residuals more strongly.
    let progress_poly = 0.5 + 2.5 * progress * progress;
    score += progress_poly * (pr / cap) * (pr / cap) * cap * 0.3;

    // Reward filling a bin nearly exactly, more so late in the stream.
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * fill * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            // small reward if lookahead fits snugly
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight preference for bins with residuals below the mean (consolidation).
    score += 2.0 * (pr - mean_residual) / cap;

    // Mild penalty for spreading across many open bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals
    // of open bins are very small (nothing fits well).
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * (mean_residual / cap).powi(2) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / cap;
    let class = (frac * 4.0).floor() as u32; // 0..3 harmonic quarters

    // Penalize dead space non-linearly; small residuals (<20) are nearly useless.
    if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 35 {
        score += 12.0;
    } else {
        score -= 6.0 * (1.0 - frac);
    }

    // Modulo-arithmetic pairing: reward when next item divides into post_residual cleanly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let r = post_residual % next_item_size.max(1);
            if r == 0 && next_item_size <= post_residual {
                score -= 25.0; // perfect modular fill
            } else {
                score -= 10.0 * (r as f64 / next_item_size as f64);
            }
            // harmonic class match: next item fits exactly in one quarter-class
            let next_class = ((next_item_size as f64 / cap) * 4.0).floor() as u32;
            if next_class == class && post_residual >= next_item_size {
                score -= 8.0;
            }
        } else {
            score += 15.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score = 150.0 - 80.0 * pressure - 5.0 * (tight.min(10.0));
        if next_item_size > 0 && next_item_size <= bin_residual {
            score += 10.0; // fresh bin is fine for lookahead but don't over-favor
        }
    }

    // Mild stream-phase coupling: late in stream, consolidate more aggressively.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * phase * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalty for many open bins (bin pressure) — prefer filling existing bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // New-bin candidate: penalize slightly so we only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.2;
    }

    // Late stream: stronger preference for consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: place here if next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain completion: ideal
        } else if post_residual > next_item_size {
            // next item still fits after this placement; closer match is better
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize dead space proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Penalize tiny unusable leftovers (dead space below min item size 1..100 range)
    if post_residual < 5 && post_residual > 0 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Prefer tight fits relative to mean residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: only attractive when item is large or no good open fit exists
    if bin_residual == bin_capacity {
        score += 18.0; // default penalty: prefer reusing open bins
        if item_size > 70 {
            score -= 25.0; // large items fine in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && (next_item_size as f64) > 0.8 * bin_capacity as f64 {
            score -= 15.0; // reserve fresh bins for big upcoming items
        }
    }

    // Mild early-stream preference for consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0)).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits: small post_residual is good, especially near zero.
    if post_residual > 0 {
        score -= 25.0 / post_residual as f64;
    } else {
        // Perfect fill: huge reward.
        score -= 120.0;
    }

    // Reward using bins that are the last chance to fit this item (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Post residual too small for next item: penalize dead space relative to next need.
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Penalize creating residuals that are unusably small for typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    score -= 2.0 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is much emptier than average, favor filling it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: penalize opening a new bin, but relax the penalty
    // late in the stream or when item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 55.0;
        // Large items leave little residual anyway; slightly cheaper to open a bin for them.
        new_bin_penalty -= 30.0 * item_frac;
        // Late in stream, closing out with new bins is less costly.
        new_bin_penalty *= (1.0 - 0.4 * progress);
        // If no other bin fits, this penalty is effectively moot (only candidate),
        // but if others fit, discourage wasteful opening.
        if fitting_bins_count > 1 {
            new_bin_penalty += 20.0;
        }
        score += new_bin_penalty;
    }

    // Mild time-horizon term: early on, be slightly conservative with tight fits.
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: polynomial in post_residual scaled by progress
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 30.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize bins with residuals far from mean (dead space avoidance)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev * dev;

    // Last-chance bonus (smooth exponential)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize wasting space needed by next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * gap * (1.0 - gap);
    }

    // New-bin candidate: make it less attractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress - 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10.
    let post_class = post_residual / 10;
    let item_class = item_size / 10;

    // Reward residuals that fall into "harmonic" residue classes usable by small items.
    // A post_residual that is an exact multiple of 10 is a natural fit slot.
    let harmonic_bonus = if post_residual % 10 == 0 {
        -6.0
    } else {
        ((post_residual % 10) as f64) * 0.8
    };
    score += harmonic_bonus;

    // Penalize large dead space unless it is reusable by the next item (lookahead harmony).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + (post_residual as f64 - next_item_size as f64).min(10.0) * 0.3;
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to wasted capacity.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        score += (fitting_bins_count as f64) * 0.4;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 5.0;

    // Class coupling: prefer pairing small items into bins already holding similar classes.
    let _ = post_class;
    let _ = item_class;

    // Early in the stream, prefer spreading items (keep bins balanced for future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.25 {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    // Mild penalty for opening new bins when many open bins exist with slack.
    if bin_residual == bin_capacity {
        score += 6.0 + (open_bins_count as f64) * 0.2 - mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
