    if bin_residual == bin_capacity {
        score += 18.0;
        // Exception: if this bin would otherwise waste a lot, opening new is fine.
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Progression: later in the stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: fill bin completely
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next fits, but how snugly? smaller leftover after next is better
            let after_next = post_residual - next_item_size;
            score -= 200.0 - (after_next as f64) * 1.5;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.8;
        }
    }

    // Dead-space penalty: residual too small to hold anything useful (min item ~1..100, be cautious)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        // opening new bin is attractive only for very large items or many open bins
        score += 250.0 - fit_quality * 150.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count > 0 {
            score += 400.0; // don't open new bin when existing bins can fit
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good packing)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0; // leftover too small for next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual deviates below the mean (consolidate large gaps).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - (bin_residual as f64)).max(0.0);

    // Time horizon: early in stream, favor filling existing bins less aggressively
    // (keep flexibility); late in stream, pack tightly into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tightness;

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere else. Empty bin gets a baseline handicap that shrinks with progress.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress);
        // Opening a bin is more attractive when many bins are already open and
        // mean residual is low (fragmentation).
        score -= 0.05 * open_bins_count as f64;
    }

    // Mild penalty for very full bins when many open bins remain (keep spread).
    if post_residual == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows quadratically for tiny residuals
    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Progress coupling: later in the stream, tight fits matter more (favor small post_residual)
    score -= 25.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Perfect-fit reward via smooth bell around post_residual == 0
    let fit = 1.0 - norm_pr;
    score -= 30.0 * fit * fit * fit * fit;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward if next item fits smoothly into resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Prefer bins with residual close to mean (balance preservation), smooth term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for many open bins to discourage bin sprawl early
    score += (open_bins_count as f64).sqrt() * 0.5 * (1.0 - progress);

    // New-bin candidate: make empty bin less attractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic dead-space penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 120.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual divisible into useful chunks
    let pr = post_residual;
    if pr > 0 {
        // post_residual matching common size classes (mod 10)
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // post_residual that could host next item exactly
        if next_item_size > 0 && pr == next_item_size {
            score -= 25.0;
        }
        if next_item_size > 0 && pr >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && pr < next_item_size {
            // dead space relative to lookahead
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Integer-division thresholds on residual capacity fractions
    let quarter = bin_capacity / 4;
    if pr <= quarter && pr > 0 {
        score += 12.0; // tiny unusable sliver
    } else if pr > quarter && pr <= bin_capacity / 2 {
        score -= 4.0;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: only prefer when no good fit exists
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing lookahead in fresh bin is fine
        }
    }

    // Slight preference for fuller bins (lower residual before placement)
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Progress-coupled mild pressure to consolidate late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: small leftover gaps (< 10) are almost
    // unusable for future items; penalize them heavily beyond their raw size.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Moderate dead space (10..25) is only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward leaving this residual; if it cannot fit, penalize the gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > post_residual {
            score += 0.4 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits, but leaves another gap: mild reward proportional to fill
            score -= 0.2 * next_item_size as f64;
        }
    }

    // Bin pressure: with many open bins, prefer filling existing ones
    // to avoid fragmentation; subtract proportional to open bin count.
    score -= 0.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large relative to capacity (large items deserve fresh space).
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= bin_capacity / 2 { 40.0 } else { 0.0 };
        score += 120.0 - large_item_bonus;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier bin worth closing out.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.3 * (mean_residual - residual_f);
    }

    // Progress pressure: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space)
    score += 2.0 * (post_residual as f64 / bin_capacity as f64).powi(3) * 50.0;

    // Reward exact fits heavily
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
            // extra bonus if next item then fits snugly too
            let second_residual = post_residual - next_item_size;
            if second_residual < 10 {
                score -= 30.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to the waste
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare residual against mean residual across open bins
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // But allow new bin if the current item is large and would leave awkward space elsewhere
        if item_size as f64 > bin_residual as f64 * 0.9 {
            score -= 40.0;
        }
        // Late in the stream, prefer closing out existing bins
        if total_items > 0 && (step_index as f64 / total_items as f64) > 0.8 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space: post residual that can never be reused.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 12.0; // tiny unusable slivers are bad
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.25 * next_item_size as f64;
        } else {
            // Post residual too small for next item: penalize proportionally.
            let waste = (post_residual as f64) / (next_item_size as f64);
            if post_residual < next_item_size {
                score += 4.0 * (1.0 - waste.min(1.0));
            }
        }
    }

    // Prefer filling more-emptied bins when many bins are open.
    let open_f = open_bins_count as f64;
    score -= 3.0 * (bin_residual as f64 / bin_capacity as f64) * (open_f / (open_f + 5.0));

    // Time horizon: early in the stream, be more willing to consolidate;
    // late in the stream, prioritize perfect fits to close bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * t * tightness;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.05 * dev.abs();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let best_possible = (bin_residual - item_size) as f64;
        // Open a new bin if existing bins would leave worse residuals.
        score = best_possible + 6.0 * pressure - 15.0 * (1.0 - pressure);
        if fitting_bins_count <= 1 {
            score -= 20.0; // keep last-chance bins preferred over new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on dead space
    let mut score = pr;

    // Non-linear coupling: squaring normalized residual penalizes large leftover
    // space more as stream progresses (favor tight fits late, keep slack early)
    let tightness_penalty = norm_pr * norm_pr * cap * (0.5 + progress);
    score += tightness_penalty;

    // Smooth interaction with mean residual: bins far from mean residual get
    // a smooth quadratic correction to balance the pool
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.3 * (1.0 + progress);

    // Last-chance bonus: smooth reward when few fitting bins, scaled by fit quality
    if fitting_bins_count == 1 {
        let fit_quality = 1.0 - norm_pr;
        score -= 15.0 + 20.0 * fit_quality * (0.5 + progress);
    }

    // Lookahead coupling: smooth polynomial reward if next item fits post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_after_next = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack_after_next * slack_after_next) * (0.5 + progress);
    }

    // Mild penalty for many open bins to encourage consolidation, smoothly scaled
    score += open_bins_count as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10 units.
    let post_class = post_residual / 10;

    // Dead-space penalty grows super-linearly for small unusable leftovers,
    // but leftovers that match "harmonic" sizes (multiples of 10, and 25/50/75)
    // are more likely reusable, so reward them.
    let harmonic_bonus: f64 = if post_residual == 0 {
        -30.0 // perfect fit
    } else if post_residual % 50 == 0 {
        -12.0
    } else if post_residual % 25 == 0 {
        -6.0
    } else if post_residual % 10 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize tiny dead space (1..=9) heavily: unlikely any future item fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Class-based nonlinearity: middle classes (20..40) are awkward; extremes fine.
    score += match post_class {
        0 => -5.0,
        1 => -2.0,
        2 | 3 => 4.0,
        4 | 5 => 0.0,
        _ => -1.0,
    };

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Reward proportional closeness of next item to post residual.
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here regardless; mild penalty if we'd strand space.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 0.5 + mean_residual / bin_capacity as f64 * 5.0;
        score += 40.0 - crowded;
    }

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are almost unusable for future
    // items (sizes >= 1, but realistically >= 10 in classic streams). Penalize
    // sharply when post_residual falls into an unusable small band.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 8.0; // strong penalty for 1..9 dead space
    }
    if pr == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Reward tight fits generally: smaller post_residual relative to capacity.
    score -= (bin_capacity as f64 - pr as f64) / bin_capacity as f64 * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins would waste space
    // badly or no bin fits well. Penalize opening new bins when a decent fit
    // exists.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count > 0 {
            // if some open bin fits, new bin should only win on very poor fits
            score += (item_size as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // Open-bin pressure: mild penalty scaling with number of open bins to
    // discourage bin proliferation, applied to real bins.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward
    // leaving that space; if next item cannot fit, the residual is dead space.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size > pr {
            score += (next_item_size - pr) as f64 * 0.5;
        } else {
            // next item fits but leaves further residual: mild coupling
            score += (pr - next_item_size) as f64 * 0.2;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling fuller bins first, classic best-fit behavior).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let match_err = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-match_err / 12.0).exp(); // exact lookahead match bonus
        // Penalize leaving residuals slightly larger than next item (dead space).
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 25.0;
        }
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: minimize waste only.
        score += 10.0; // lookahead bonus unavailable, slightly deprioritize nothing special
    }

    // Relative to mean residual: prefer bins whose residual deviates usefully.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev; // prefer below-average residual (tighter bins)

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score += 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        score += 15.0 * pressure;
        // If item perfectly matches a fresh bin (item_size == capacity), allow it.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate into open bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good, but dead space below
    // the smallest plausible item is wasted. Penalize small-but-nonzero gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // gap smaller than typical minimum item (10) is dead space
        if gap < 10.0 {
            score += (10.0 - gap) * 2.5; // strong penalty for unusable slivers
        } else {
            // mild preference for smaller gaps overall
            score += (gap / bin_capacity as f64) * 8.0;
        }
    } else {
        // perfect fill
        score -= 15.0;
    }

    // Fill-rate reward: how well this item exploits the bin's original space
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this placement (preserves useful pairings).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            // next item fits after this placement: excellent
            score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < 10 {
            // next item cannot use the tiny gap created: extra penalty
            score += 6.0;
        }
        // If next item barely misses, small penalty
        let miss = next - post_residual as f64;
        if miss > 0.0 && miss <= 10.0 {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        // but if it creates a dead sliver, soften the bonus
        if post_residual > 0 && post_residual < 10 {
            score += 14.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when existing
    // fits are poor or the item perfectly fills a fresh bin.
    if bin_residual == bin_capacity {
        // base handicap against opening new bins
        score += 18.0;
        // large items (hard to place later) justify opening a fresh bin
        if item_size > 60 {
            score -= 10.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // if many bins are open with big residuals, discourage new bins
        if mean_residual > 40.0 {
            score += 10.0;
        }
        // if next item is large, a fresh bin with full residual is valuable
        if next_item_size > 50 && item_size <= 30 {
            score -= 8.0;
        }
    }

    // Global state: many open bins with scattered residuals -> prefer
    // consolidating into bins with larger residuals (best-fit-ish).
    if open_bins_count > 4 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05; // prefer bins near the mean residual (typical bins)
    }

    // Early stream: encourage keeping residuals flexible (moderate gaps),
    // late stream: pack tightly regardless.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 + progress * 1.5;
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * (2.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual [0,1]
    let coupling = prn * prn * (1.0 + 2.0 * progress) - 0.5 * prn * progress;
    score += 8.0 * coupling;
    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 1.5 * (gap / cap) * (1.0 + progress);
    }
    // Reward last-chance bins smoothly (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - prn);
    }
    // Mild penalty for proliferating open bins relative to stream length
    score += 0.05 * (open_bins_count as f64).powf(1.2) / (1.0 + total_items as f64);
    // Smooth deviation from mean residual
    score += 0.3 * (pr - mean_residual).abs() / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of common small item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap; // fill ratio after placement

    // Reward tight fits strongly (non-linear)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class: post_residual divisible by small sizes 10..=50 -> leftover reusable
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmonic_bonus -= 12.0; }
        else if pr % 20 == 0 { harmonic_bonus -= 10.0; }
        else if pr % 25 == 0 { harmonic_bonus -= 8.0; }
        else if pr % 5 == 0 { harmonic_bonus -= 4.0; }
    }
    score += harmonic_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 18.0 - 0.15 * slack;
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; penalize creating dead space
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, discounted when stream is late or bins crowded
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 20.0 * progress - 2.0 * (open_bins_count as f64).min(10.0);
        // opening a new bin is fine if the current item is large (poor fit elsewhere)
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // keep a fresh bin attractive if mean residual is small (all bins nearly full)
        if mean_residual < 12.0 {
            score -= 20.0;
        }
    } else {
        // mild penalty for very low occupancy placements into half-empty bins
        if fill < 0.3 {
            score += 10.0;
        }
    }

    // Integer-division threshold: avoid leaving residuals in dead zone (11..19, 21..24 etc.)
    if pr >= 11 && pr <= 19 {
        score += 6.0;
    }
    if pr >= 51 && pr <= 59 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>=1, realistically
    // small items are rare) can use are pure waste. Penalize tiny post_residuals hard
    // via a nonlinear "dead zone" term.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // residuals below 10 are unusable if min item is 10; below min(next_item) too
        let dead_threshold = if next_item_size > 0 { (next_item_size as f64).min(10.0) } else { 10.0 };
        if pr < dead_threshold {
            score += (dead_threshold - pr) * 3.0; // harsh penalty for unusable slivers
        }
    }

    // Reward tight fits (waste minimization): subtract for high fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // with few open bins, mildly encourage consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the direction that reduces fragmentation (prefer bins tighter than mean).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        if (pr - next_item_size as f64) < 5.0 {
            score -= 10.0; // near-perfect chain fit
        } else {
            score -= 2.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh start; make it attractive
    // only when the item is large relative to residual or stream is early.
    if bin_residual == bin_capacity {
        let stream_pos = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = if item_size >= 50 { 6.0 } else { 0.0 };
        score += 25.0 - stream_pos * 10.0 - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let look_fit = post_residual >= next_item_size;
        if look_fit {
            // Tight 2-chain: post_residual close to next_item_size is excellent
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally to dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Compare against mean residual: prefer filling below-average-residual bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when decent fits exist (early/mid stream)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        // New bin only attractive if no open bin gives a tight 2-chain
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference for keeping many small open bins consolidated
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

