            score += 4.0 * ((next_item_size - post_residual) as f64) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to avoid squandering scarce-fit bins elsewhere.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins with residual below the mean (consolidating fuller bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, favor filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins open.
        score += 10.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 6.0 * progress;
    }

    // Mild bonus for very full bins to keep them attractive targets.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear reward for tight fits: quadratic decay of wasted space.
    let tight = 1.0 - (pr / cap);
    score -= 40.0 * tight * tight;

    // Smooth polynomial coupling with stream progress: tighter packing valued more late.
    let prog2 = progress * progress;
    score -= 30.0 * tight * (0.5 + prog2);

    // Penalize leaving residuals that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward reserving space for a next item that fits snugly.
        let snug = 1.0 - ((pr - nx) / cap).abs();
        if snug > 0.0 {
            score -= 15.0 * snug * snug * (1.0 - progress);
        }
    }

    // Last-chance bin bonus (smooth in fitting_bins_count).
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for fragmenting many open bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Prefer bins below mean residual slightly (balance residuals smoothly).
    score += 0.1 * (pr - mean_residual);

    // Penalize opening a new bin when decent fits exist: new-bin candidate has pr == cap.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 20.0 + 30.0 * (1.0 - tight) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
