            score -= 25.0;
        } else {
            // leftover wasted w.r.t. lookahead: penalize proportional mismatch
            let waste = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.35 * waste;
        }
        // Chain fit: next item exactly seals the bin
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else {
        // Last item: prefer fullest packing, any residual is pure waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // late in the stream, squeeze hard into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.15 * post_residual as f64;
    score -= progress * 10.0 * tightness;

    // Global state: many open bins with slack -> discourage opening new bins / spread.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when plenty of open bins have room.
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 12.0 + 10.0 * pressure;
        // But if item is large and mean residual is small, opening a fresh bin is fine.
        score -= 0.2 * item_size as f64;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor),
        // modulated by how far the bin deviates from the mean residual.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * deviation;
    }

    // Mild penalty on accumulating too many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / c;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = norm_pr.powf(1.5) * 10.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (keep bins flexible); later, demand tight fits
    let progress_coupling = norm_pr * (1.0 + 3.0 * t * t) - norm_pr * norm_pr * (2.0 + 4.0 * t);
    score += progress_coupling * 5.0;

    // Reward bins whose residual closely matches the lookahead item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / c;
        score += gap * gap * 4.0 * (0.5 + t);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * t;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 0.15;

    // Slight preference for bins below mean residual (consolidate emptier space)
    score += (mean_residual - bin_residual as f64) * 0.01;

    // New-bin candidate: neutral baseline with smooth early-stream openness
    if bin_residual == bin_capacity {
        score = 6.0 + 4.0 * (1.0 - t) * (1.0 - t) - 2.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: partition residual space into
    // capacity-fraction classes. Small residuals (dead space) are penalized
    // super-linearly; large residuals are mildly rewarded.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    // Class index via integer-division thresholds: 0..=4
    let class = (post_residual * 5) / bin_capacity; // 0..4
    let class_penalty = match class {
        0 => 40.0,                       // residual <= 20: near-dead space
        1 => 12.0,                       // <= 40
        2 => 3.0,                        // <= 60
        3 => -4.0,                       // <= 80: good usable space
        _ => -10.0,                      // nearly full bin: excellent fit
    };
    score += class_penalty;

    // Super-linear dead-space penalty for tiny residuals.
    if pr < 0.25 * c {
        score += (0.25 * c - pr) * 0.8;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    // (harmonic pairing), penalize if next item barely misses.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = pr - ni;
            if slack < 0.1 * c {
                score -= 15.0; // perfect chain placement
            } else {
                score -= 5.0 * (1.0 - slack / c);
            }
        } else {
            // next item does not fit: penalize proportionally to overflow
            score += (ni - pr).min(c) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer tightening existing bins.
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 0.5;
    }

    // Prefer bins tighter than the mean residual (good fits cluster together).
    score += (pr - mean_residual) * 0.3;

    // Modulo / divisibility harmony: residual that is a multiple of common
    // item sizes (10, 20, 25, 50) is more likely reusable.
    let common: [u32; 4] = [10, 20, 25, 50];
    let mut harmony = 0.0;
    for &m in &common {
        if post_residual % m == 0 && post_residual > 0 {
            harmony += 4.0;
        }
    }
    score -= harmony;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no decent open bin exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * c;
        if big_item || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0; // discourage opening new bins for small items
        }
    }

    // Slight late-stream tightening: as stream progresses, favor closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 30.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 12.0;
        }
    } else {
        score -= 15.0; // perfect fit is excellent
    }

    // Reward residual that can still hold typical future items.
    if post_residual >= next_item_size as f64 && next_item_size > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer tight fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // Prefer bins tighter than the mean residual (waste consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight nudge against opening new bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly prefer bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if gap == 0.0 {
            score -= 40.0; // perfect pairing: item + next item fill the bin
        } else if post_residual as f64 >= next {
            // next item can still fit: reward proportionally to tightness
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            // extra reward when next item leaves a still-usable remainder
            if (post_residual as f64 - next) >= 10.0 {
                score -= 3.0;
            }
        } else {
            // next item will NOT fit after this placement: penalize dead space
            score += 0.8 * (next - post_residual as f64);
        }
    }

    // Penalize creating tiny unusable residuals (dead space < 10, min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fills of the current bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins tighter than average are better
    // candidates for consolidation.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual pool; late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded.
        score += 10.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; mildly penalize hoarding space.
            score += 2.0;
        }
    }

    // Last chance: this is the only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Compare residual to the mean: prefer bins below-average residual (fuller than average).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in the stream, be more conservative (avoid new bins / favor exact fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 3.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual
    let t = progress;
    // Smooth interaction: residual value weighted by progress-dependent polynomial
    let w = 1.0 + 2.0 * t * (1.0 - t) * 4.0; // peaks mid-stream
    score += 6.0 * w * prn * prn * cap * (0.5 + t);

    // Penalize large dead space quadratically, smoothed by progress
    score += 0.02 * pr * pr * (0.3 + 0.7 * t);

    // Reward tight fits (small post residual) with smooth saturation
    score -= 12.0 * (1.0 - prn).exp() * (1.0 + t);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + t);
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - ((pr - nx).abs()) / cap;
            score -= 8.0 * tight * tight * (1.0 - t);
        } else {
            score += 3.0 * (nx - pr) / cap * t;
        }
    }

    // Mild penalty for spreading across many open bins early on
    score += 0.5 * open_bins_count as f64 * t * prn;

    // New-bin candidate: penalize slightly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class of post_residual: waste buckets by modulo classes
    let pr = post_residual;
    let class_penalty = match pr % 10 {
        0 => -8.0,           // reusable round residual
        1 | 2 | 3 => 6.0,    // awkward slivers
        4 | 5 | 6 => 2.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Dead-space threshold: residuals below typical small item size are dead
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
            // harmonic check: next item leaves a round residual too
            if (pr - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow in this bin; slight penalty if this bin was the only option
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        if mean_residual < 20.0 || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 30.0 + crowding;
        }
        // early stream: prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
    }

    // Prefer filling bins that are already mostly full (low residual relative to mean)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Integer-division threshold: bins whose residual is in the top quartile get mild penalty
    if bin_residual > bin_capacity * 3 / 4 && bin_residual != bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact-fit lookahead: if next item exactly fills the post residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: residual becomes dead space for lookahead.
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (1.0 - progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mean residual alignment: prefer bins close to the mean (balanced packing).
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    // New-bin candidate: only attractive when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let bad_fit_exists = post_residual > 0 && post_residual < 10;
        if !bad_fit_exists && fitting_bins_count > 0 {
            score += 25.0 + open_bins_count as f64 * 0.3;
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: mild bonus proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64).min(50.0) * 2.0;
        } else {
            // Next item cannot use this residual: penalize dead space relative to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(80.0) * 1.5;
        }
    } else {
        // Last item: prefer minimal residual.
        score -= 100.0;
    }

    // Compare residual against mean residual across open bins.
    let resid = post_residual as f64;
    if resid > mean_residual {
        score += (resid - mean_residual) * 0.8; // hoarding space in one bin
    } else {
        score -= (mean_residual - resid) * 0.3; // balanced packing preferred
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 300.0;
        // But if next item is large and no good fit exists, allow opening.
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 50.0;
        }
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0 * (open_bins_count as f64).sqrt().recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space ratio.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward using a bin that is the only fitting option (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Slight penalty when many bins compete — encourage consolidation on tightest ones.
        score += 0.5 * (fitting_bins_count as f64).min(10.0);
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items (they'd leave huge waste elsewhere anyway),
        // bad for small items (fragmenting).
        score += 30.0 * (1.0 - size_frac);
        // If this is the last-chance bin scenario, opening new bin is less needed.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            // Next item won't fit here; leaving too-small residual is dead space.
            score += 8.0;
        }
    }

    // Prefer bins with residual below mean (consolidate fuller bins).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Prefer fewer open bins overall (mild consolidation pressure).
    score += 0.2 * open_bins_count as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);
    // smooth coupling of post residual with stream progress
    score += 12.0 * norm_pr * (0.5 + progress) * (1.0 - norm_pr);
    // penalize large post residual more as stream progresses (dead space late = costly)
    score += 20.0 * progress * norm_pr * norm_pr * norm_pr;
    // reward tight fits especially when this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0) * norm_pr;
    }
    // lookahead: reward residual that can host next item, smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (n - pr) / cap;
        }
    }
    // mild preference to spread load when many bins open relative to progress
    score += 1.5 * (open_bins_count as f64).sqrt() * (1.0 - progress) * norm_pr;
    // mean residual coupling: avoid deviating strongly from mean residual state
    score += 0.05 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    let band = (frac * 4.0).floor() as u32; // 0..3
    score += match band {
        0 => -15.0,  // post_residual <= 25: small dead space, good
        1 => 5.0,    // 26..50: moderate
        2 => 12.0,   // 51..75: large gap
        _ => 20.0,   // 76..99: nearly empty bin used poorly
    };

    // Modulo arithmetic on post_residual: residual divisible by small items is reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0);
    if reusable {
        score -= 8.0;
    }

    // Lookahead: strongly favor bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // Harmonic pairing: next item fills bin nearly exactly.
            if post_residual == next_item_size {
                score -= 25.0;
            }
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            score += 10.0;
            if post_residual < 10 {
                score -= 5.0; // tiny residual is fine (effectively full)
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discourage opening new bins early in the stream; encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded or mean residual is tiny.
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 - 40.0 * pressure;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild penalty when many bins are open: encourage filling existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    let dead_zone: f64 = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual was already small (tight packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a good next fit
        // or current bin would leave a bad gap.
        score = 100.0 + pressure;
        if next_item_size > 0 && next_item_size <= post_residual.min(bin_capacity) {
            score -= 30.0;
        }
        if post_residual < dead_zone && post_residual > 0 {
            score -= 25.0;
        }
        // Late in the stream, prefer reusing existing bins.
        score += progress * 20.0;
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Lookahead: reward bins where the next item still fits after placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Mild preference toward bins below mean residual (consolidate slack).
        score += ((bin_residual as f64) - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly consumes post residual.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + gap);
            if gap == 0.0 {
                score -= 20.0; // exact 2-item fill bonus
            }
        } else {
            // Next item cannot follow here; penalize proportionally to wasted space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead.min(60.0);
        }
    }

    // Compare post_residual against mean residual: leaving this bin near the mean
    // keeps flexibility; extreme residuals (too small) are penalized.
    let diff = post_residual as f64 - mean_residual;
    score += 0.08 * diff.abs();

    // Penalize unusable dead space: small post_residual that likely can't fit
    // typical items (below minimum plausible item size ~10).
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin only when the item is large
    // relative to residuals of open bins (encoded via mean_residual) or few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / (bin_capacity as f64);
        // If mean residual across open bins is small, opening fresh bin is attractive.
        score -= 18.0 * (1.0 - pressure) * (0.5 + progress);
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Discard new bin if next item would pair poorly with a fresh bin anyway.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 8.0; // pairing possible elsewhere; keep item in open bins
        }
    }

    // Mild preference for bins with larger residual among equals (keep small holes tight).
    score += 0.05 * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize small dead space that is hard to fill later (post_residual in awkward range)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is large and no good fits exist
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items, bad for small ones
        score += (1.0 - fill_frac) * 40.0;
        // If many bins could fit the item, discourage opening a new one
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the next item could exactly fill this bin's post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to how well it uses the remainder
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize leaving a residual just below next item size
            if post_residual > 0 && post_residual < next_item_size {
                score += 4.0;
            }
        }
    }

    // Global state: if mean residual is high, prefer bins below mean (balance residuals)
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    } else {
        score -= 1.5;
    }

    // Many open bins: favor filling existing ones rather than spreading
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post-residual, with a non-linear polynomial shaping term.
    // Small post_residual is good (tight fit), but very small residuals risk dead space.
    let norm_post = post / cap;
    let mut score = post - 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * cap * (0.5 + progress);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, prefer tighter packing more aggressively.
    score += 0.35 * norm_post * norm_post * cap * (0.5 + progress * progress);

    // Penalize creating dead space smaller than the typical next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            score += 8.0 * (nxt - post) / nxt * (1.0 + progress);
        } else if post >= nxt {
            // Reward leaving room that can still serve the next item.
            score -= 4.0 * (1.0 - (post - nxt).min(cap) / cap) * (0.5 + progress);
        }
    } else {
        // Last item: purely minimize waste.
        score += 0.0;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Coupling with mean residual: bins far below mean residual are less attractive
    // (they keep flexibility), bins above mean are good consolidation targets.
    let dev = (post - mean_residual) / cap;
    score -= 6.0 * dev * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable
    // since items are >= 10 on average; penalize small non-zero remainders.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class: post_residual divisible by common item sizes (10, 20, 25, 50)
    // is more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // Next item fits in the leftover: mild reward proportional to fit quality.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }
    // Next item cannot use the leftover at all: penalize proportionally.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins that are already relatively full (tighter packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // New-bin candidate handling: an empty bin gets a baseline score equal to its
    // full residual; bias it so it is chosen only when fits into open bins are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: if open bins are on average spacious, slightly prefer
    // consolidating into tighter ones (penalize bins above mean residual).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    // Many open bins: encourage closing them out by using existing space.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the minimum
    // item (<= 9) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements whose leftover could still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if leftover just barely fails to hold the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets a
    // large additive offset that grows with open_bins_count).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 6.0;
        // But allow a new bin when the current bin would leave a dead gap.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is above the
    // mean (consolidating space into fewer bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for filling older bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // 2-step lookahead: reward if next item fits into post_residual exactly/well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.35; // perfect chain gets big discount
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space for the lookahead item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Compare post_residual against mean residual: avoid fragmenting bins
    // when other bins are already loose.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when all open bins are truly bad fits (large post_residual already
    // gives it a high base score; add a small opening cost).
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, opening new bins is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = next_item_size as f64 / post_residual as f64;
        score -= 20.0 + 15.0 * snug;
    }

    // Dead-space penalty: post_residual that no future item (known) can use is waste,
    // super-linear so large dead space is punished hard.
    if next_item_size == 0 || next_item_size > post_residual {
        score += 0.35 * (post_residual as f64).powf(1.25);
    }

    // Last-chance bonus: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) over loose fits.
    score += 0.08 * (bin_residual as f64 - item_size as f64).abs();

    // Time horizon: later in the stream, favor filling existing bins deeply.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let fill_frac = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= t * 10.0 * fill_frac;

    // Global coupling: if this bin's post-residual deviates favorably (small) from mean
    // residual, it consolidates space; slight reward for below-mean post residual.
    score += 0.05 * (post_residual as f64 - mean_residual);

    // New-bin candidate decision: open a new bin only when the fit is poor and the
    // next item is large (better chance to pair big items in fresh bins).
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) < 20;
        let next_big = (next_item_size as f64) > 0.5 * bin_capacity as f64;
        if poor_fit && next_big {
            score -= 6.0;
        } else {
            score += 18.0;
        }
        // Late in stream, discourage opening new bins even more.
        score += t * 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with non-linear sharpening (waste avoidance).
    let mut score = post * (1.0 + 0.02 * (post / cap) * (post / cap));

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fills matter more (dead space is costlier).
    let coupling = post * (1.0 - progress) * (1.0 - progress)
                 + 2.0 * post * progress * (1.0 - progress)
                 + 3.0 * post * progress * progress;
    score += 0.05 * (coupling - post);

    // Reward near-perfect fits smoothly (quadratic in fill ratio).
    let fill = 1.0 - (post / cap);
    score -= 8.0 * fill * fill * fill;

    // Penalize leaving residual that no typical next item can use:
    // smooth valley around small residuals, penalize mid-range leftovers.
    let nr = next_item_size as f64;
    if nr > 0.0 {
        let gap = (post - nr).abs();
        score += 0.15 * gap * gap / cap;
        // Reward if next item fits exactly into post-residual.
        if nr <= post {
            score -= 3.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    // Penalize bins far from mean residual (smooth dispersion penalty).
    score += 0.05 * (post - mean_residual) * (post - mean_residual) / cap;

    // New-bin candidate: make it moderately attractive only when post-residual
    // of existing bins would be very wasteful relative to capacity.
    if bin_residual == bin_capacity {
        score = 0.35 * cap - 0.5 * item_size as f64 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "usable" vs "dead" space classes. Residues 0 (perfect fit) and
    // small residues that typical small items (1..10) can still fill
    // are rewarded; large awkward gaps are penalized.
    let residue = post_residual % 10;
    match residue {
        0 => score -= 30.0,                    // perfect harmonic class
        1 | 2 | 3 => score -= 8.0,             // nearly perfect
        4 | 5 | 6 => score -= 2.0,             // neutral
        7 | 8 => score += 6.0,                 // awkward gap
        _ => score += 12.0,                    // worst class: 9 residue
    }

    // Integer-division thresholds on post_residual: classify leftover
    // into fillable bands by common item sizes.
    if post_residual == 0 {
        score -= 60.0; // exact fit, ideal
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    } else if post_residual > 80 {
        score += 15.0; // huge leftover: bin was nearly empty, wasteful
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual (harmonic match), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 15.0;
            } else {
                score += (gap as f64) * 0.3;
            }
        } else {
            // next item won't fit here; slight penalty unless this is
            // the only fitting bin (last-chance placement).
            if fitting_bins_count > 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only open bin that fits,
    // prefer using it over opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when no open bin offers a decent harmonic fit,
    // i.e. when mean residual is small (open bins are nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let threshold = 0.35 * bin_capacity as f64 * (1.0 - 0.3 * progress);
        if mean_residual < threshold && fitting_bins_count >= 1 {
            score += 40.0; // keep filling existing bins
        } else {
            score -= 10.0; // open bins too full, new bin reasonable
        }
    }

    // Mild pressure to consolidate: many open bins with large mean
    // residual suggests fragmentation; prefer tighter fits.
    if open_bins_count > 3 {
        score += (post_residual as f64) * 0.05 * ((open_bins_count as f64).ln());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    // (items are 1..=100, but tiny gaps below ~10 are waste magnets).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: perfect closure is ideal.
    if post_residual == 0 {
        score -= 15.0;
    } else {
        // Non-linear tightness reward: squared relative fill.
        let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill * fill;
    }

    // Penalize large leftover gaps that nothing meaningful can use later:
    // gap in (0, 20) is dangerous dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // open_bins_count grows; encourage consolidation.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid needless bin creation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item would leave a bad gap elsewhere or bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty: prefer existing bins by default.
        score += 20.0;
        // But relax when existing bins would produce dead space or mean
        // residuals are already fragmented.
        if post_residual == 0 {
            score -= 35.0; // fresh bin closes perfectly with this item
        }
        if mean_residual > 0.75 * bin_capacity as f64 {
            score -= 10.0; // open bins are full-ish; new bin is fine
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 8.0; // lookahead pairs well with a fresh bin
        }
    }

    // Lookahead: if next item exactly fits the post-residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item could still fit in the resulting gap, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 3.0;
    }

    // Slight late-stream consolidation: as the stream progresses, prefer
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: strong reward for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are attractive targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist, except when the fit is poor.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 10.0 + 0.4 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Late in the stream, consolidate: slightly favor existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere or the stream is early with few bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early stream: opening bins is cheap and useful for future flexibility.
        if progress < 0.25 {
            score -= 18.0 * (1.0 - progress * 4.0);
        }
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0 * (fitting_bins_count as f64 - 2.0);
        }
        // If item leaves large post space in a new bin and next item is small,
        // a fresh bin can be attractive.
        if next_item_size > 0 && post_residual >= next_item_size + 20 {
            score -= 10.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mild global pressure: pull toward bins below mean residual (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with a non-linear (quadratic-cubic) coupling
    // that grows stronger as the stream progresses (late items should pack tighter).
    let mut score = pr * (1.0 + 2.0 * progress * progress) + norm_pr * norm_pr * 40.0 * (0.5 + progress);

    // Cubic dead-space penalty: residuals that are too small to ever host a
    // typical item are quadratically worse late in the stream.
    let dead = norm_pr * (1.0 - norm_pr);
    score -= 20.0 * dead * (1.0 - progress);

    // Lookahead: reward this bin if it leaves room (or fits) the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - ((pr - nxt) / cap).abs()) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (penalize the alternative implicitly).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for proliferating bins relative to mean residual state.
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    // Small tie-breaker favoring tighter fits regardless of progress.
    score += (item_size as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity fractions)
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Reward near-perfect fills: post_residual in small harmonic classes
    // Class 0: exact fill (residual 0) -> strong reward
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Integer-division thresholds: residual bucketed by capacity/8
        let eighth = bin_capacity / 8;
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;

        if post_residual <= 4 {
            score -= 120.0;
        } else if post_residual < eighth {
            score -= 60.0;
        } else if post_residual < quarter {
            score -= 25.0;
        } else if post_residual < half {
            score -= 5.0;
        } else {
            // Large leftover dead space: penalize
            score += 15.0;
        }

        // Modulo-arithmetic coupling: does post_residual pair with next item?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 90.0; // perfect pair lookahead
            } else if next_item_size < post_residual {
                // Harmonic residue: how divisible is the leftover by next item
                let r = post_residual % next_item_size.max(1);
                if r == 0 {
                    score -= 40.0;
                } else {
                    score -= 15.0 * (1.0 - r as f64 / next_item_size as f64);
                }
            } else {
                // Next item cannot fit here: leftover likely dead space
                score += 20.0;
            }
        } else {
            // Last item: any residual is pure waste
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > bin_capacity / 2
            || (next_item_size > 0 && next_item_size > post_residual);
        if poor_fit {
            score -= 55.0;
        } else {
            score += 80.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate: fewer open bins -> favor existing bins
    score += open_bins_count as f64 * 0.3;
    score -= mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (<10) heavily; treat as wasted bin.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    }
    // If next item almost fits (miss by small margin), slight penalty for stranding.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size - 5 {
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, favor using it
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if post_residual < 10 {
            score -= 25.0; // still better than opening a new bin
        }
    }

    // New-bin candidate: prefer opening a new bin only when no open bin gives
    // a decent fit; make the empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open new bin
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins with residual far from mean residual (better "shape match" for big items).
    if item_size > bin_capacity / 2 {
        score += 0.1 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-exact packing.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else if gap <= 10 {
            score -= 150.0;
        } else {
            // penalize leaving space just above next item (dead space for lookahead)
            score += gap as f64 * 0.5;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: post_residual below next_item_size is dead space
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward tight fits relative to mean residual: prefer bins with residual close to item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Relative to mean residual: bins with less residual than average are more "used",
    // prefer filling them (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin unless the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral baseline plus penalty scaled by how many bins fit.
        score += 60.0 + (fitting_bins_count as f64) * 20.0;
        // allow new bin if item is big relative to capacity (few future fits anyway)
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        // late in stream, prefer consolidation into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Prefer bins with many open bins to close them early (reduce spread).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post-residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * (item_size as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large awkward residual.
            score += 0.15 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Prefer bins with residuals below the current mean (consolidate small holes).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.08 * residual_diff;

    // Mild pressure to fill existing bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate logic: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 12.0; // discourage new bin when alternatives exist
        }
        // If item is large relative to capacity, new bin is more acceptable.
        score -= 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual
    let t = progress;
    // Smooth interaction: dead-space penalty grows as stream progresses
    let dead = prn * prn * (0.5 + 2.0 * t * t);
    score += 40.0 * dead;

    // Reward tight fits (small post residual) more strongly later in the stream
    let tightness = 1.0 - prn;
    score -= 15.0 * tightness * (1.0 + t);

    // Penalize when this bin is the only fitting bin (last chance) — prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * t;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins vs mean residual alignment
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: neutralize baseline so it competes fairly
    if bin_residual == bin_capacity {
        score += 6.0 + 12.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable"
    // (common small-item sizes 1..20) are less penalized than dead zones.
    let r = post_residual;
    let class: f64 = if r == 0 {
        -30.0 // perfect fit: strongly reward
    } else if r <= 10 {
        0.0
    } else if r % 10 == 0 {
        -12.0 // decadal residual: reusable by many item classes
    } else if r % 5 == 0 {
        -6.0
    } else if r % 3 == 0 {
        -2.0
    } else {
        6.0 // awkward residue: penalize dead space
    };
    score += class;

    // Integer-division thresholds: how many "standard chunks" of 10 remain
    let chunks = r / 10;
    score -= chunks as f64 * 1.5;

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= r {
            // modular match: next item's class aligns with residual class
            let align = (r % 10).min(next_item_size % 10);
            score -= 8.0 + align as f64 * 0.4;
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    } else {
        // last item: prefer tightest packing, no future concern
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.5;
        if r >= item_size + next_item_size && next_item_size > 0 {
            score -= 20.0; // but if a fresh bin can host both items, favor it
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (fill fuller bins first), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 3.0 * (1.0 - progress);
    } else {
        score += 1.5 * progress;
    }

    // Mild preference to keep bin count low late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, minimum item size).
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 25.0 + (min_item - post_residual as f64) * 3.0;
    }

    // Penalize moderate dead space (hard to fill later) more than large residuals.
    if post_residual >= 10 && post_residual <= 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 2.5 * (item_size as f64 / (post_residual as f64 + item_size as f64));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // Lookahead: if the next item fits in this bin's post-residual, reward the placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item almost fits (small shortfall), slight penalty for creating a near-miss gap.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins deviating below the mean (consolidate small residuals).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when no open bin leaves a decent residual,
    // i.e. all fits would create tiny dead space, or open-bin pressure is low.
    if bin_residual == bin_capacity {
        let would_open = open_bins_count as f64 * 3.0 + mean_residual * 0.4;
        score = bin_capacity as f64 - would_open;
        // Strongly discourage a new bin if this is the only fitting bin (avoid waste).
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // Discourage new bin late in the stream when consolidation matters.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64;
        } else {
            // dead space for the next item: penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // penalize opening new bins moderately; lookahead may override
        score += 250.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= next_item_size as f64 * 0.5;
        }
    }

    // mild progression scaling: early on, be slightly conservative about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 50.0 * (bin_residual - post_residual) as f64 / item_size.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize large dead space: post_residual too small to ever be useful.
    if post_residual < 10 {
        score += 18.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving medium-sized gaps.
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage
    // unless the item is large relative to the best available fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Prefer new bin when few bins open or item is large.
        score += 45.0 - 10.0 * (item_size as f64 / bin_capacity as f64) * 20.0
            - 5.0 * progress
            - open_pressure.min(10.0) * 1.5;
    }

    // Prefer bins with residual far from mean (deviate to preserve average bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Mild preference for fuller bins as stream progresses.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * (0.5 + 0.5 * (step_index as f64 / (total_items.max(1) as f64)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress
    let mut score = pr_norm * pr_norm * (1.0 + 0.5 * progress) * 100.0;

    // Reward tight fits (small post_residual) with smooth exponential coupling
    score -= 40.0 * (-8.0 * pr_norm).exp() * (0.5 + fit);

    // Smooth interaction: item size vs post residual coupling (avoid leaving space
    // just below the next item size)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (pr_norm - nx).max(0.0);
        score += 60.0 * gap * gap * (1.0 - fit);
        // Reward if post_residual exactly accommodates next item
        score -= 25.0 * (-200.0 * (pr_norm - nx).abs()).exp();
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty proportional to congestion (many open bins with slack)
    let mean_norm = mean_residual / cap;
    score += 0.3 * mean_norm * open_bins_count as f64 * (0.2 + 0.8 * progress);

    // Slight penalty for very small items wasting a nearly-full bin late in stream
    score += 10.0 * progress * (1.0 - fit) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space thresholds.
    // Residuals <= 10 are nearly unusable (min item size class), reward creating them
    // only if the next item can consume them; otherwise penalize.
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size >= post_residual {
            // next item cannot fit here anyway -> dead space penalty
            score += 40.0;
        }
    }

    // Modulo-10 classes: residuals that are multiples of 10 align with
    // typical item granularity, making them reusable -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division thresholds: classify residual into usable bands.
    let band = post_residual / 25; // 0,1,2,3,4
    match band {
        0 => score += 20.0,          // tiny residual: poor flexibility
        1 => score -= 5.0,           // 25-49: decent
        2 => score -= 10.0,          // 50-74: good
        _ => score -= 12.0,          // large residual: bin barely used
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // harmonic class of the gap
            if gap % 10 == 0 {
                score -= 25.0;
            } else if gap < 10 {
                score += 15.0; // would leave tiny dead space
            } else {
                score -= gap as f64 * 0.3;
            }
        } else {
            // next item won't fit here: mild penalty unless this is last-chance bin
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        // baseline: new bin starts with full residual; make it competitive only
        // when no good fit exists. Scale with stream progress (waste less early).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    }

    // Prefer bins tighter than average (better packing density).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.4;
    } else {
        score += (resid_f - mean_residual) * 0.2;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fit, ideal — but residual 0 already lowest; keep safe
    }
    // Penalize gaps that are small but nonzero: they are likely unusable dead space.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score -= 5.0 * (dead_threshold - post_residual as f64); // small gap slightly better than medium waste
    }
    // Medium gaps (10..=30) are the worst kind of dead space when nothing small may come:
    if post_residual > 0 && post_residual <= 30 {
        score += 8.0;
    }
    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead: if the next item fits in the post_residual, reward this placement (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Extra reward if next item nearly fills the remaining space.
        let next_left = post_residual - next_item_size;
        if next_left <= 5 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; a large leftover gap becomes dead space.
        score += 3.0;
    }

    // Open-bins pressure: discourage proliferation of bins when few are open,
    // but relax pressure as many bins are already open (consolidation mode).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * (2.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with residual already below mean (consolidate waste into fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Slight penalty for using a fresh bin unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 20.0;

    // Aggressive 2-step lookahead: reward when next item fits the post_residual exactly.
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 60.0; // perfect closure
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Reward chains: next item leaves little dead space.
            score -= 40.0 * (slack as f64 / 10.0).min(1.0);
            // Extra reward if the chain then closes the bin.
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item cannot use the residual -> dead space risk.
            let dead = post_residual as f64;
            score += dead * 0.5;
        }
    } else {
        // Last item: just close bins tightly.
        score -= 10.0 * (post_residual == 0) as i32 as f64;
    }

    // Compare post_residual against mean residual of open bins.
    // Leaving this bin above-average residual is fine (others can absorb);
    // creating a tiny unusable residual below mean is penalized.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.35 && post_residual > 0 {
            score += 25.0 * (0.35 - rel); // awkward tiny hole
        } else if rel > 1.5 {
            score += (rel - 1.5) * 5.0; // too much leftover vs peers
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer opening a fresh bin when the
    // current item is large and residual elsewhere is fragmented.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / total_items.max(1) as f64;
        // Fresh bin bonus when open bins are crowded and item is big.
        let crowded = (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (mean_residual / bin_capacity as f64).min(1.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        let bonus = 45.0 * big_item * crowded * (0.5 + early);
        score += 30.0; // default cost of opening a new bin
        score -= bonus;
        // Keep a fresh bin unattractive if item is small.
        if item_size <= 30 {
            score += 40.0;
        }
    }

    // Mild penalty per residual unit to break ties toward tightness.
    score += post_residual as f64 * 0.15;

    // Slight time pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor minimal post-residual (non-linear).
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tightness * 60.0;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Lookahead coupling: reward if next item can use the post-residual,
    // penalize if it cannot (wasted gap for the upcoming demand).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // If next item exactly fills the gap, big reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open a new bin when many bins exist and mean residual is high
        // (fragmentation) or when few bins can fit the item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= open_bins_count as f64 * 0.8;
        score -= mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 20.0;
    }

    // Prefer filling bins that are already relatively full (large item_size
    // relative to residual means a good chunk usage).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Mild preference to balance residual spread: avoid dumping into bins far
    // from the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: quadratic decay of waste, strengthened as stream progresses.
    let tightness = 1.0 - (post / cap);
    score -= 24.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual far from the "useful" small-residual band (smooth coupling).
    let x = post / cap;
    score += 18.0 * x * x * (1.0 - x) * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item, penalize near-miss blocking.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 12.0 * miss * miss;
        }
    }

    // Mild penalty when this bin is much tighter than average (keep balanced spread).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: prefer opening fresh bins early or when fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < 0.5 * cap;
        let bias = 8.0 - 14.0 * progress;
        score += if poor_fit { bias - 6.0 } else { bias };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that lie in
    // "useful" classes (divisible by common small sizes), penalize dead space.
    let pr = post_residual;
    if pr > 0 {
        // Fraction of capacity wasted
        let waste_frac = pr as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;

        // Harmonic bonus: residuals in classes 0 mod 10 are most reusable
        let class10 = (pr % 10) as f64;
        score += 3.0 * class10; // off-class residual penalty
        let class5 = (pr % 5) as f64;
        score += 1.5 * class5;

        // Integer division thresholds: very small residuals are near-dead
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        } else if pr < 35 {
            score += 3.0;
        } else if pr >= 50 {
            score -= 6.0; // half-empty bin still very flexible
        }

        // Reward exact-ish fills strongly
        if pr == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap <= 10 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - (gap as f64 / bin_capacity as f64));
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; slight penalty unless residual is tiny anyway
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 55.0 + 30.0 * progress;
        if open_bins_count > 4 {
            open_cost += 8.0 * (open_bins_count as f64 - 4.0).min(10.0);
        }
        // If mean residual of open bins is large, opening new bin is less attractive
        open_cost += 0.6 * mean_residual;
        score += open_cost;
    }

    // Mild preference for tighter bins among open ones
    score -= 0.05 * (bin_capacity.saturating_sub(bin_residual)) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward bins whose residual after placement can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // creates dead space relative to lookahead
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
        // But allow opening when existing bins would leave bad dead space.
        if post_residual >= bin_capacity - item_size && item_size > 60 {
            score -= 20.0;
        }
    } else {
        // Last-chance bin bonus: strongly prefer filling the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // Prefer bins tighter than the mean residual (good fits).
        score -= 0.4 * (mean_residual - bin_residual as f64);
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins where the next item also fits (2-step lookahead match).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chains that keep the stream flowing in this bin.
            score -= (next_item_size as f64) * 0.6;
            // Extra reward for a near-perfect two-item packing.
            let two_item_slack = post_residual - next_item_size;
            score -= (two_item_slack as f64) * 0.8;
        } else {
            // Next item won't fit here: penalize leaving awkward space.
            score += (next_item_size as f64) * 0.3;
        }
    }

    // Reward tight fits (small post residual) relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 10.0;

    // Penalize deviation from mean residual: prefer bins with more slack than average
    // (keeps small bins for small items), unless this is a tight fit.
    score += (post_residual as f64 - mean_residual) * 0.05;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // no good chain exists. Make the empty bin attractive only for big items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let big_item_bonus = (item_size as f64 / 100.0) * 20.0;
        score += 30.0 - big_item_bonus - progress * 5.0;
    }

    // Mild penalty for too many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small for the smallest plausible item (<=10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize wasted lookahead space mildly.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items early, or when few fitting bins exist.
        score -= 15.0 * poor_fits * (0.5 + big_item) * (1.0 - 0.5 * progress);
        // Slight default penalty so new bins are not overused.
        score += 10.0;
    }

    // Global state: when mean residual is high, encourage consolidating into
    // bins with low residual (below mean) to reduce fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0 * (mean_residual - bin_residual as f64).min(20.0) / 20.0;
    }

    // Late in stream: discourage opening new bins (fewer items left to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Mild preference for bins with more residual among equally tight fits.
    score += 0.01 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - norm_pr) * (0.5 + progress);
    score -= 8.0 * coupling;

    // Penalize large dead space more than linearly as stream progresses
    score += norm_pr * norm_pr * 10.0 * (0.3 + 0.7 * progress);

    // Reward tight fits
    score -= (item_size as f64 / cap) * 3.0;

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Lookahead: favor bins whose post_residual fits next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // New-bin candidate: mildly penalize early, allow late when residuals fragmented
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    // Diversification pressure when many bins open
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 quantizes dead space quality
    let class = post_residual % 10;
    match class {
        0 => score -= 8.0,          // perfectly aligned residual, reusable
        5 => score -= 4.0,          // half-class, still reusable
        1 | 9 => score += 3.0,      // awkward slivers
        2 | 8 => score += 1.5,
        _ => score += 0.5,
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 10;
    if q == 0 {
        score += 25.0;              // dead space (<10): unusable for smallest items
    } else if q <= 2 {
        score -= 5.0;               // small but usable pocket
    } else if q <= 5 {
        score -= 10.0;              // sweet spot for medium items
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 6.0 + slack as f64 * 0.3;
        } else {
            score += 4.0;           // next item won't chain here
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it competitive only when current bins are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 30.0 * progress - mean_residual * 0.15;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;           // pairing potential in fresh bin
        }
    }

    // Mild penalty for opening bins when many already open with slack
    if (bin_residual as f64 - item_size as f64) > mean_residual + 20.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the
    // smallest possible item are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that are usable only by tiny items are semi-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // next item would leave dead space; discourage
            score += 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual too small for the upcoming item -> likely dead space
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless the fit
    // is good; scale penalty with number of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean residual (balance),
    // slightly reward tighter-than-average bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: neutral baseline so it only wins when open bins
    // would create substantial dead space or the fit is poor.
    if bin_residual == bin_capacity {
        score = 45.0 + bin_pressure * 0.3;
        // In late stream, opening a new bin is more acceptable.
        score -= 20.0 * progress;
        if next_item_size > 0 && item_size >= 50 && next_item_size >= 50 {
            score -= 30.0; // two large items: fresh bin is wise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly in post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0;
            // Bonus proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= (50.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // Next item won't fit here: penalize wasting space that could chain.
            let deficit = (next_item_size - post_residual) as f64;
            score += 40.0 * (deficit / bin_capacity as f64);
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Slight preference for filling already-open bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Progress-based mild pressure to consolidate early, spread late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress;

    // New-bin candidate: keep it neutral-ish, only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * (bin_capacity as f64);

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward if next item fits in the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Penalize waste if next item cannot follow into this bin.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the item fits poorly everywhere else or open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 15.0 + fragmentation;
        // Opening a new bin early in the stream is cheap insurance.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Prefer bins with residual close to mean (balanced usage), avoid
        // fragmenting many nearly-full bins.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Slight preference for using more-filled bins as stream progresses.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * 5.0;

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits quadratically (small post_residual -> low score)
    let mut score = 100.0 * x * x;

    // Smooth non-linear coupling with stream progress: later in stream,
    // value tight fits more (penalize waste progressively).
    score *= 0.5 + 1.5 * progress * progress;

    // Interaction: post_residual vs mean residual — prefer bins whose leftover
    // is close to the fleet mean (keeps residuals homogeneous and reusable).
    let mean_x = mean_residual / cap;
    let spread = (x - mean_x).abs();
    score += 30.0 * spread * spread;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x) * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score += 25.0 * gap * gap - 15.0 * (1.0 - gap);
    } else {
        // Last item: prefer filling an existing bin completely.
        score += 40.0 * x;
    }

    // Mild penalty for spreading across too many bins when residual is large.
    score += 5.0 * x * (open_bins_count as f64).ln();

    // New-bin candidate: neutral-ish baseline, penalized unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0 + 25.0 * progress - 20.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
