        let mean_tightness = 1.0 - (mean_residual / cap);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5 + pressure * 8.0 + mean_tightness * 40.0 + progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // fresh bin guarantees fit for lookahead too
        }
    }

    // Slight penalty when many bins compete: prefer tighter consolidation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
