pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact-ish fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Crowding: penalize when many bins are open but residuals are scattered.
    if open_bins_count > 1 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.15 * spread;
    }

    // Time horizon: late in the stream, be more conservative (favor filling existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // New-bin candidate handling: opening a new bin is only attractive if no open bin
    // fits well, or the item is large and current residuals are fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else {
            // Penalize new bin when decent alternatives exist.
            let fragmentation = (mean_residual - item_size as f64).abs();
            score += 55.0 + 0.4 * fragmentation - 30.0 * (item_size as f64 / bin_capacity as f64);
            if fitting_bins_count == 1 {
                score += 40.0; // never waste the last fitting bin's purpose on speculation
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: minimize wasted post residual, with non-linear (quadratic/cubic) shaping
    let mut score = post + (post / cap).powi(3) * 120.0;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills; later, tolerate slack less strongly
    let coupling = (post / cap) * (1.0 - progress) * 40.0 + (post / cap).powi(2) * progress * 60.0;
    score += coupling;

    // Reward near-perfect fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fit_ratio.powi(4)) * 25.0;

    // Dead-space penalty: post_residual that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post) * (0.5 + progress);
    }
    // Bonus if post residual exactly accommodates lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strong smooth reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Mild penalty proportional to crowding of open bins
    score += (open_bins_count as f64).ln() * 2.0;

    // Penalize bins far below mean residual (fragmentation tendency)
    score += ((mean_residual - post) / cap).abs() * 10.0;

    // New-bin candidate: neutral-ish baseline with slight preference early, penalty late
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - fit_ratio * 0.0;
        // discourage opening new bins when a decent fit exists elsewhere
        if fitting_bins_count >= 1 {
            score += 25.0 + 30.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste buckets via integer division.
    let class = post_residual / 10;
    score += match class {
        0 => -25.0,                 // near-perfect fit (post_residual < 10)
        1 => -10.0,                 // good fit
        2 => 0.0,
        3 => 5.0,
        4 => 10.0,
        5 => 14.0,
        6 => 18.0,
        _ => 22.0,                  // large dead space
    };

    // Reward using bins whose residual is in a harmonic residue class that
    // pairs well with typical item sizes (mod 10 granularity).
    let residue = bin_residual % 10;
    if residue == 0 {
        score -= 6.0;               // clean multiples are reusable
    } else if residue >= 5 {
        score -= 2.0;
    } else {
        score += 3.0;               // awkward small residues
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0;      // perfect chain
            } else if slack < 10 {
                score -= 15.0;
            } else {
                score -= (10.0 / (1.0 + slack as f64 / 20.0));
            }
        } else {
            // next item cannot follow here; penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + gap / 10.0;
        }
    }

    // Last-chance bonus: only one fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins have poor residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let residual_pressure = (mean_residual - post_residual as f64) / bin_capacity as f64;
        let bonus = 40.0 * (1.0 - progress) - 20.0 * residual_pressure - 2.0 * open_bins_count as f64;
        score += bonus; // net effect decides new bin vs. reuse
        if score < 0.0 { score *= 0.5; }
    }

    // Mild global pressure: many open bins -> prefer consolidation.
    score += open_bins_count as f64 * 0.3;

    // Slight preference for tight fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable gaps: post_residual in 1..10 is dead space
        // since future items are >= 1 but typically larger.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 15.0;
        }
        // Mild reward for leaving room that could fit a typical next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Pressure from number of open bins: prefer compacting into fewer bins
    // when many bins are open, but allow new bins early in the stream.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.5;
    }

    // Late in the stream, compact harder.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match reward: next item fits tightly with small slack
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space that no typical item can use (below min item size)
    if post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins that stay near the mean packing density
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin before opening a new bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave very tight/awkward space
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 15.0; // base cost of opening a new bin
        if next_item_size > 0 && post_residual >= next_item_size && waste <= 40.0 {
            score -= 10.0; // fresh bin still supports the lookahead item
        }
        if post_residual == bin_residual {
            score += 5.0; // avoid opening new bins when a perfect fit exists elsewhere
        }
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit: tight fits are heavily rewarded.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never hold a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size {
            // This bin could have hosted the next item; placing here wastes that.
            score += 4.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, new bins are more acceptable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many bins are open with large mean residual, discourage new bins.
        score += 0.05 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (consolidating fuller bins).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: polynomial coupling of post_residual with stream progress.
    // Small post_residual (tight fit) is good -> lower score; but too small
    // (dead space) is bad late in the stream. Smooth cubic in x.
    let mut score = x * (2.0 - x) * (1.0 + 0.5 * progress);

    // Reward tight fits more strongly as stream progresses (consolidation).
    score -= (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nx = next_item_size as f64 / cap;
        score -= 0.6 * (1.0 - nx) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty, worse when post residual tiny.
        score += 0.2 * (1.0 - x);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - x);
    }

    // Penalize bins far from mean residual (fragmentation balancing).
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-high baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.4 * (1.0 - progress);
    }

    // Mild penalty for many open bins with large residuals (encourage closing).
    score += 0.1 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item quantum) are favored.
    let pr = post_residual;
    let quantum: u32 = 10;
    let residue = pr % quantum;
    if residue == 0 && pr > 0 {
        score -= 8.0; // perfectly reusable leftover
    } else {
        score += (quantum - residue) as f64 * 0.6; // penalize awkward leftover
    }

    // Dead-space penalty: tiny leftovers that nothing (min size 1..100) can use well
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            score -= 6.0 + (slack as f64).sqrt() * 1.5;
        } else {
            score += 4.0; // forces a new bin for the next item
        }
        // Harmonic check: post_residual divisible into next item size
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless their fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.3;
        // If mean residual is fragmented, opening fresh is more attractive
        score -= mean_residual * 0.05;
    }

    // Penalize bins far below mean residual (hoarding large space) mildly
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Fractional capacity thresholds: reward placing into bins whose fill
    // crosses harmonic fractions of capacity.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    for &frac in &[0.25f64, 0.5, 0.75, 1.0] {
        if fill >= *frac {
            score -= 2.0;
        }
    }

    // Integer-division threshold on post_residual: leftovers in [10,50) are
    // prime reuse targets; [50,100) are half-empty bins worth consolidating.
    if pr >= 50 && pr < bin_capacity {
        score += 5.0;
    } else if pr >= 10 && pr < 50 {
        score -= 4.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (fitting_bins_count as f64).recip().max(0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size 10), so heavily penalize tiny gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps slightly above the minimum item size are also risky dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; a new bin (residual == capacity) gets penalized
    // proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But if this is the only fitting bin, opening a new bin may be fine.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual cannot host the next item: mild dead-space penalty.
        score += 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already a "junk" bin — filling it is good (reduce its residual).
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.15 * residual_gap;

    // Early-stream exploration: keep scores slightly compressed early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: reward proportionally to how well it fills.
            score -= 25.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item does NOT fit the leftover: penalize dead space relative to next item.
            score += 0.35 * (post_residual as f64).min(next_item_size as f64);
            if post_residual > 0 && post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Compare post_residual against mean residual: leaving more than average is bad.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalty when many bins are open: encourage consolidation.
    score += 0.4 * (open_bins_count as f64);

    // Small penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Mild stream-progression pressure: as stream advances, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // New-bin candidate: neutral baseline so it's only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that can never be used by typical items.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty for chaining badly
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Reward using bins whose residual is below the mean (consolidation).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: late in the stream, prefer closing bins tightly (exact fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Discard brand-new-bin preference unless current open bins fit poorly.
    if bin_residual == bin_capacity {
        // New bin is attractive when item is large or few fitting bins exist.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 6.0 * large_item;
        if fitting_bins_count > 0 {
            // mild penalty so open bins are preferred unless their fit is bad
            score += 4.0 + 0.5 * post_residual as f64;
        }
    }

    // Prefer keeping number of open bins from exploding.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let next = next_item_size as f64;

    // Core: prefer small post_residual, with non-linear (quadratic) coupling.
    let mut score = post + 0.6 * (post * post) / cap;

    // Smooth progress coupling: early on, tolerate larger leftovers slightly;
    // late in the stream, tighten aggressively (dead space matters more).
    let progress_tighten = 1.0 + 1.5 * progress * progress;
    score *= progress_tighten;

    // Reward exact/near-exact fits (post_residual near 0) with a smooth term.
    let tightness = 1.0 - post / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // If the next item would fit into the post residual, reward preserving utility.
    if next > 0.0 && next <= post {
        let slack_util = 1.0 - (post - next) / cap;
        score -= 5.0 * slack_util * slack_util;
    } else if next > 0.0 {
        // Leftover too small for the next item: penalize dead space smoothly.
        let deadness = post / cap;
        score += 4.0 * deadness * deadness;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Mild penalty spread over many alternatives.
        score += (fitting_bins_count as f64).ln().max(0.0);
    }

    // New empty bin candidate: only attractive when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * progress;
        // Discourage bin proliferation when many bins are already open.
        score += 0.5 * (open_bins_count as f64);
    }

    // Nudge toward bins with residual close to the item (smooth coupling).
    let residual_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 3.0 * residual_gap * residual_gap;

    // Slight preference for bins below mean residual (consolidation).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod capacity/4 (25 units)
    let quarter = bin_capacity / 4;
    let residue = post_residual % quarter;
    score -= (quarter - residue) as f64 * 0.15; // reward residuals near class boundaries

    // Perfect-fit harmonic classes: post_residual divisible by 4 or 10
    if post_residual % 4 == 0 { score -= 2.0; }
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual == 0 { score -= 12.0; }

    // Integer-division threshold: small post_residual is dead space
    if post_residual < 10 {
        score += 25.0; // unusable dead space penalty
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 + (next_item_size as f64) * 0.05;
            // harmonic match: next item keeps residual in same mod class
            let next_res = post_residual - next_item_size;
            if next_res % quarter == 0 { score -= 3.0; }
            if next_res % 10 == 0 { score -= 2.0; }
        } else {
            score += 2.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / (bin_capacity as f64);
        score = 45.0 + 20.0 * fragmentation - 15.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 10.0; // item won't fit anyway elsewhere handled by fitting count
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer fuller bins: deviation from mean residual
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Mild pressure to consolidate as stream progresses
    score -= (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Anything <= 10 is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward excellent fits (small but usable leftover).
    if post_residual <= 15 && post_residual > 0 {
        score -= 20.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual unusable for next item: mild dead-space penalty.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (penalize the empty-bin candidate implicitly via residual scaling) and
    // encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // and mean residual is high (existing bins have plenty of room).
        score += 45.0 + pressure * 10.0 + mean_residual * 0.3;
    } else {
        // Existing bin: reward relative to how full it already is (good
        // consolidation), scaled by open-bin pressure.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 15.0 + pressure * 2.0;
    }

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            // Perfect 2-step fit: strong reward.
            score -= 60.0;
        } else if pr > nxt {
            // Next item fits too: reward proportional to leftover after both.
            score -= 15.0 + 0.25 * (pr - nxt);
        } else {
            // Next item will NOT fit in this bin's remainder: penalize dead space.
            score += 8.0 + 0.5 * (nxt - pr);
        }
    }

    // Penalize creating very small unusable remainders (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // Compare against mean residual across open bins: prefer bins with residual
    // close to mean (balanced packing) when not a great fit otherwise.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the item is large relative to capacity or few bins fit the item.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score = 45.0 - 30.0 * fill_frac - 10.0 / pressure;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 - item_size as f64 {
            score -= 20.0; // next item pairs well with fresh bin
        }
    }

    // Mild stream-progression term: late in stream, tighten packing (prefer tight fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full packing (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for exact-ish chain fits
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 6.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_score = 55.0;
        // Cheaper to open new bins early; expensive late in the stream
        new_bin_score -= 20.0 * (1.0 - progress);
        // More open bins => prefer filling existing ones
        new_bin_score += 2.5 * open_bins_count as f64;
        // If many bins fit, opening a new one is wasteful
        new_bin_score += 4.0 * fitting_bins_count as f64;
        // Small items are fine to start a fresh bin with
        if item_size <= 30 {
            new_bin_score -= 10.0;
        }
        // Large items near capacity: starting fresh can be good
        if item_size >= 60 && mean_residual < item_size as f64 {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    } else {
        // Prefer bins below mean residual (fill emptier bins to balance)
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late stream: be greedier, minimize post residual aggressively
    if progress > 0.7 {
        score += 0.25 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), non-linearly scaled
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (fewer chances to fill it)
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.5;
    score += coupling;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item can fit the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for leaving residual far from mean (fragmentation control)
    score += 0.15 * (pr - mean_residual).abs();

    // Penalize opening new bins when open bins are underutilized
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 3.0 + 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible into 5-unit bands.
    let residue_class = post_residual % 10;
    // Dead-space penalty: residuals in (0..10) are nearly unusable (min item 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-5 harmonic bands: residuals that are multiples of 5 align with
    // common item-size granularities, making them more reusable.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual > 0 {
        // Penalize odd residues slightly more than even non-multiples of 5.
        if post_residual % 2 == 1 {
            score += 3.0;
        } else {
            score += 1.0;
        }
    }

    // Integer-division threshold: can the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward leaving room for the next item, scaled by how snugly it fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 15.0 - snug * 0.25;
            // Harmonic bonus: next item exactly divides the residual band.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // Penalize blocking the next item, worse when it would have fit exactly.
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: it has residual == capacity. Favor it only
    // when the fit here is poor and many bins are open (fragmentation risk).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild intrinsic penalty so tight fits into open bins win.
        score += 12.0;
        // But if the current fit is loose (post_residual large) and stream is
        // early/mid, opening a fresh bin is attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= post_residual as f64 * 0.15 + progress * 5.0;
        if open_bins_count > 3 && mean_residual > 30.0 {
            score -= 10.0; // plenty of slack elsewhere; a fresh bin is cheap
        }
    } else {
        // Slight preference for bins with residual far below capacity (denser bins).
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Global scaling toward the mean residual: keep bins balanced in mid-stream.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (post_residual as f64 - mean_residual) * 0.1 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical minimum items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact / near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space pressure: small post_residual relative to bin capacity is bad
    // unless it's zero (perfect fit handled above).
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    if dead_ratio > 0.0 && dead_ratio < 0.15 {
        score += 25.0 * (0.15 - dead_ratio) / 0.15;
    }

    // Open bins pressure: when many bins are open, prefer consolidation
    // (favor bins with small residual => lower post_residual naturally),
    // add penalty proportional to open_bins_count scaled by post_residual.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and would leave a big usable gap elsewhere anyway.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin for large items when open bins are numerous
        if item_size >= 60 && open_bins_count > 3 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item would fit the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps a balanced portfolio of bin gaps).
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += residual_gap * 0.15;

    // Stream progression: later in the stream, be more conservative about
    // leaving tiny dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the leftover (but not exact): moderate reward, scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Next item does NOT fit the leftover: penalize dead space, worse when leftover is tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += 15.0 + 40.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for tighter bins among many candidates.
        score += 3.0 * ((fitting_bins_count - 1) as f64).min(5.0);
    }

    // Prefer bins tighter than the mean residual (leave larger bins for larger items).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty for opening a brand-new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0;
    }

    // Late in the stream: consolidate, penalize spreading into new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else {
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // If next item would NOT fit here, slight penalty for wasting the lookahead opportunity
    // only when this bin is a poor fit anyway.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Fragmentation-aware: prefer bins whose residual is already small relative to mean.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += 4.0 * (rel - 1.0);
    }

    // Time horizon: later in the stream, consolidation matters more; penalize spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: opening a new bin wastes (capacity - item) immediately.
    // Prefer new bin only when no open bin fits well (large post_residual would result
    // elsewhere) or stream is early and many items remain to fill fresh capacity.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let early_bonus = (1.0 - progress) * 15.0;
        score = waste + 30.0 - early_bonus;
        // If a fresh bin enables an exact fit for the lookahead item, make it attractive.
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            let gap = bin_capacity - item_size - next_item_size;
            if gap == 0 {
                score -= 35.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear polynomial coupling: penalize mid-range residuals more as stream advances.
    let mid = norm_pr * (1.0 - norm_pr);
    score += 40.0 * mid * mid * (0.5 + progress);

    // Dead-space penalty: tiny post residuals that cannot host small future items.
    if pr > 0 && pr < 10 {
        score += (10.0 - pr as f64) * 3.0;
    }

    // Perfect fit reward, stronger late in the stream.
    if pr == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits exactly in post residual; penalize near-miss waste.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = (pr - n) / cap;
            score -= 15.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 8.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Crowd-out: with many open bins, prefer filling existing ones over new bins.
    score += 2.0 * open_bins_count as f64 * norm_pr;
    score += 5.0 * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate should only win when residuals are poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: partition residual space into capacity/8 classes
    let class = post_residual / (bin_capacity / 8);
    score -= class as f64 * 2.0;

    // Penalize small unusable dead space (1..=5) strongly
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    // Reward tight fits (post_residual small relative to item)
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty for wasting capacity
            score += post_residual as f64 * 0.05;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins have poor fits. New bin has post_residual == capacity - item_size.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slight bias toward reusing bins early, opening later
        score += 5.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Modulo coupling on post_residual: residues divisible by 4 are more reusable
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 2 == 1 && post_residual < 10 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let pressure = (open_bins_count as f64).sqrt() * 4.0;
    if bin_residual < bin_capacity {
        score -= pressure;
    }

    // New-bin candidate: default slightly penalized; only attractive when it enables
    // a good fit for the next item while current fit would leave bad dead space.
    if bin_residual == bin_capacity {
        let base_new_bin = 25.0 + pressure;
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            // Current bin would leave a gap the next item cannot use -> new bin attractive.
            score = base_new_bin - 40.0;
        } else {
            score = base_new_bin;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Mean residual coupling: if mean residual is large, favor consolidating into fuller bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Lookahead: reward leaving room for the next item if it fits.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward bins whose leftover exactly accommodates the next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 800.0; // exact match for next item
        } else if diff > 0 {
            // leftover can hold next item; prefer tighter containment
            score -= (60.0 - (diff as f64).min(60.0)) * 1.5;
            // penalize leaving exactly awkward space slightly larger than next item
            if diff < 10 {
                score += 40.0;
            }
        } else {
            // leftover too small for next item: dead-space risk scaled by how close
            let near_miss = (-diff) as f64;
            if near_miss <= 10 {
                score += near_miss * 6.0; // nearly fitting is the worst waste
            } else {
                score += 20.0;
            }
        }
    }

    // Relative tightness vs mean residual of open bins.
    let tightness = post_residual as f64 - mean_residual;
    score += tightness * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 50.0 * progress;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    }

    // Lookahead coupling: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 22.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize if we waste a near-perfect residual now.
            score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding effect: with many open bins, prefer consolidating into fuller bins.
    let crowding = (open_bins_count as f64).ln().max(1.0);
    score += 3.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins whose residual is near the mean (keeps bin profile uniform),
    // but only mid-stream; early on, allow exploration of diverse residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 8.0 * progress * dev / bin_capacity as f64;

    // Time horizon: late in the stream, be conservative — reward using existing space more.
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Baseline mild penalty so existing bins win on good fits.
        score += 12.0;
        // But if this is a last-chance situation with no alternatives, opening new is fine.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // Large items relative to capacity justify fresh bins early.
        if (item_size as f64) > 0.6 * bin_capacity as f64 && progress < 0.5 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping.
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Dead-space penalty: small but nonzero post_residual wastes capacity.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (2.0 + 3.0 * progress);
    }

    // Smooth coupling with stream progress: tighten selection as stream advances.
    score *= 1.0 + 0.35 * progress * (1.0 - norm_post);

    // Last chance: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward leaving space usable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: penalize mildly so it only wins when fits are poor,
    // with the penalty easing late in the stream.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score = cap * (1.05 + 0.25 * progress) - fit_pressure * 15.0;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 4.0;
        }
    }

    // Mild tie-break toward consolidating among many open bins.
    score += 0.05 * open_bins_count as f64;

    // Nudge toward bins whose residual is near the mean (keeps residuals uniform).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual divisible by small integers (usable splits)
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // perfectly harmonic residual
        } else if pr % 5 == 0 {
            score -= 7.0;
        } else if pr % 2 == 0 {
            score -= 3.0;
        } else {
            score += 2.0; // odd residuals are awkward
        }
        // dead-space penalty: tiny unfillable slivers
        if pr < 10 {
            score += 15.0;
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Lookahead coupling: does post_residual fit the next item's harmonic class?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // exact integer division: next item splits residual harmonically
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: keep it competitive only when current fits are poor
    if bin_residual == bin_capacity {
        score -= 6.0 + 0.05 * open_bins_count as f64;
    }

    // Prefer tight fills relative to mean residual state
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Late-stream urgency: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        // Perfect fit is highly rewarded.
        score -= 100.0;
    }

    // Reward bins that can also host the lookahead item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the next item.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when few bins fit,
    // otherwise prefer reusing open bins.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += pressure + open_bins_count as f64 * 0.5;
        // Late in the stream, prefer consolidating rather than opening bins.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the next item can fit into the
    // post-residual (chain packing), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: post_residual exactly matches next item.
            let match_bonus = if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
                25.0
            } else {
                12.0
            };
            score -= match_bonus;
        } else {
            // Next item won't fit here after this placement; penalize dead space
            // proportional to how close it is to blocking the next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(30.0);
        }
    }

    // Compare against mean residual: bins with residual near/below mean are
    // natural candidates; very large residuals should be preserved unless fit is tight.
    score += 0.25 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits
    // well — penalize opening new bins while good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = (open_bins_count as f64) * 2.0;
        score += 15.0 + open_penalty + 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Late-stream bias: consolidate into fewer bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: penalize wasted space quadratically (dead space is the enemy).
    let mut score = (post_residual as f64) * (post_residual as f64) * 0.02;

    // Reward tight fits: residual close to 0 gets a strong discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this bin
    // (keeps future options open). If not, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Chain fit: next item fills the leftover exactly or near-exactly.
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: an empty bin gets a baseline score that is
    // competitive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral baseline: slightly worse than a good fit, better than a bad one.
        score = (bin_capacity as f64) * 0.55;
        // Late in the stream, prefer consolidating into open bins a bit more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // If only one fitting bin exists, make new bin less attractive.
        if fitting_bins_count == 1 {
            score += 15.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer bins that reduce fragmentation (tight fits already rewarded);
    // when mean residual is low, be more tolerant of larger leftovers.
    let mean_dev = ((bin_residual as f64) - mean_residual).abs();
    score += mean_dev * 0.05;

    // Prefer bins with smaller current residual among equals (pack fuller bins first).
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Quadratic/cubic shaping of post residual: penalize large dead space superlinearly
    score += 12.0 * norm_pr * norm_pr * cap;
    score -= 8.0 * norm_pr * norm_pr * norm_pr * cap;

    // Progress coupling: early on, prefer tight fills less aggressively; later, tighten more
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 10.0 * prog_poly * norm_pr * cap;
    score -= 6.0 * (1.0 - prog_poly) * norm_item * cap;

    // Interaction: dead space weighted by how much it can still host a future item
    let next_fit = if next_item_size as f64 <= pr { 1.0 } else { 0.0 };
    score -= 9.0 * next_fit * (1.0 - norm_pr) * cap * (0.5 + 0.5 * prog_poly);

    // Last-chance bonus: strongly favor using a nearly-unique fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + prog_poly);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: avoid bins far from the fleet mean (keeps residual spread tight)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Prefer filling bins with small residual relative to item (good fit)
    let fit_ratio = norm_item / (bin_residual as f64 / cap).max(1e-6);
    score -= 4.0 * fit_ratio * fit_ratio.min(1.0);

    // New-bin candidate: penalize opening a new bin unless residual is essentially unused
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - prog_poly);
        if next_item_size as f64 > item_size as f64 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // divisors of capacity are more reusable by future items.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit, ideal
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr < 10 {
        12.0 // dead space: unusable for any item >= 10 (classic range)
    } else {
        0.0
    };
    score += class_bonus;

    // Harmonic coupling with next item: residual exactly matching next item
    // (or a harmonic divisor/multiple relation) is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual && post_residual % next_item_size == 0 {
            score -= 10.0; // residual can be tiled by copies of next item
        } else if next_item_size > post_residual {
            score += 3.0; // next item can't use this residual anyway
        }
        // integer-division threshold: how many times next item fits
        let fits = post_residual / next_item_size.max(1);
        score -= (fits.min(4) as f64) * 2.5;
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins with
    // decent fits, but allow opening when all fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 2.0;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Progress-aware small tilt: later in the stream, tighten packing
    // (prefer small post_residual even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (harmonic alignment), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 unknown distribution, assume >= 10 typical)
    // are wasted. Penalize hard if the gap can't fit the lookahead item
    // or a plausible future item.
    let min_plausible = 10u32;
    if post_residual > 0 && post_residual < min_plausible {
        // Unusable sliver: heavy penalty proportional to wasted capacity.
        score += 40.0 + (min_plausible - post_residual) as f64 * 2.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is dead with respect to lookahead item.
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        // Perfect lookahead fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 20.0;

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, allow opening new bins (score for empty bin
    // candidate is naturally high post_residual, so subtract mildly there).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline competitive score plus mild
        // scaling with stream position.
        score = (bin_capacity - item_size) as f64
            - 8.0 * (1.0 - step_index as f64 / total_items.max(1) as f64)
            + open_bins_count as f64 * 0.5;
    } else {
        // Existing bins get slight bonus when many bins are open
        // (encourage consolidation).
        score -= open_bins_count as f64 * 0.3;
        // Deviation from mean residual: prefer bins already tighter
        // than average to keep a spread of usable gaps.
        let dev = post_residual as f64 - mean_residual;
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize residuals too small for the next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no good fit exists.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference to fill older bins as the stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight packing.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness;

    // Lookahead (k=2): reward bins whose leftover can host the next item,
    // penalize leftovers that are dead space for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            // Perfect chaining bonus: leftover exactly consumed next step.
            let chain = 1.0 - ((post_residual as f64) - next) / (bin_capacity as f64);
            score -= 4.0 * chain;
        } else {
            // Dead space relative to the lookahead: penalize proportionally.
            let waste = ((post_residual as f64) - next) / (bin_capacity as f64);
            if post_residual < next_item_size {
                score += 2.0 * waste;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
        if post_residual <= 5 {
            score -= 2.0; // near-perfect closure of the bin
        }
    }

    // New-bin candidate handling: opening a bin is justified for large items
    // or when no bin fits well; otherwise penalize proliferation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let load_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Large items early in the stream benefit from fresh bins.
        if item_size >= 60 {
            score -= 5.0 + 3.0 * (1.0 - progress);
        } else if item_size >= 40 {
            score -= 2.0 * (1.0 - progress);
        } else {
            // Small item into a fresh bin is wasteful when other bins exist.
            score += 4.0 + 0.3 * load_pressure;
        }
        // If many bins are already open and mean residual is high, discourage new bins.
        score += 0.15 * open_bins_count as f64 * (mean_residual / (bin_capacity as f64));
    }

    // Global state coupling: when mean residual is low (bins nearly full),
    // favor consolidating into the emptiest viable bins.
    if bin_residual as f64 > mean_residual && fitting_bins_count > 1 {
        score -= 1.5 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // Time horizon: late in the stream, avoid leaving large unusable gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 2.0 * progress * (post_residual as f64) / (bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, prefer larger leftovers (flexibility); late, prefer tight fits.
    let shape = 0.5 + 0.5 * progress;
    score += shape * norm_pr * norm_pr * 40.0;
    score -= (1.0 - shape) * norm_pr * 15.0;

    // Reward tight fit (small post_residual relative to item) with smooth term
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * norm_item * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0 + 25.0 * progress;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 12.0 * (nx - pr as f64) / cap;
        } else {
            score -= 8.0 * (pr - nx as f64) / cap;
        }
    }

    // Slight penalty for contributing to residual spread across open bins
    score += (pr - mean_residual).abs() * 0.05;

    // New-bin candidate: mildly discouraged unless residual is tiny elsewhere
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual divisible by 10 (clean slot, likely reusable by mid-size items)
    // Class 1: divisible by 5 but not 10
    // Class 2: odd / awkward remainder
    let pr = post_residual;
    let class = if pr == 0 { 0 } else if pr % 10 == 0 { 0 } else if pr % 5 == 0 { 1 } else { 2 };
    score += class as f64 * 3.0;

    // Reward tight fits strongly (small post_residual is good, but zero residual is best).
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 15.0;
    } else if pr <= 20 {
        score -= 6.0;
    }

    // Lookahead: does the next item fit into the post residual? Reward harmony.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly-ish: reward proportional closeness.
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0; // harmonic divisibility bonus
            }
        } else {
            // Next item won't fit here; penalize more if post residual is large dead space.
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual is large (lots of slack around), discourage new bin.
        score += 55.0 - 30.0 * pressure;
        // Early in stream, opening bins is fine; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild penalty proportional to item size fraction consumed imbalance.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 5.0 * fill;

    // Penalize bins whose residual deviates wildly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Harmonic threshold on residual via integer division: bins in "high band" (residual > 50)
    // are more flexible; keep them slightly preferred for large items.
    if bin_residual / 25 >= 2 && item_size >= 50 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is unusable
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    }

    // Reward tight fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin should only win when existing
    // bins would leave a really bad fit, or when the next item pairs well
    // with the leftover space.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only for poor fits elsewhere.
        score += 35.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // This new bin will nicely hold the next item too.
            score -= 30.0;
        }
    }

    // Lookahead: if the leftover space exactly matches the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover too small for the next item -> penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Progress-based mild tightening: later in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // to keep balance, unless it's the last chance.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Dead space relative to next item: penalize.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual: prefer leaving less-than-average waste.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin unless the fit is genuinely tight.
    if bin_residual == bin_capacity {
        score += 80.0;
        if post_residual <= 10 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Early in the stream, allow more bins (spread risk); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 20.0;

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item's likely need.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 6.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Post-residual can host the next item: reward.
            score -= 4.0;
        }
    } else {
        // Last item: prefer fullest packing, no future concerns.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins fit the item, prefer the one with least waste; add mild
    // penalty proportional to open bins to discourage bin sprawl.
    if fitting_bins_count > 1 {
        score += 0.05 * (open_bins_count as f64);
    }

    // Time horizon: early in the stream, be conservative about fragmenting
    // bins (keep large residuals for future large items); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * (post_residual as f64);
    score -= progress * 3.0 * tightness;

    // Compare against mean residual: bins already below-average residual are
    // good candidates to close out; bins above-average should stay open.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to typical residuals or all fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64
            && open_bins_count > 0;
        if poor_fit {
            score -= 10.0; // opening fresh bin beats wasting an open bin
        } else {
            score += 20.0; // prefer existing bins with decent fits
        }
        // Early stream with few bins: opening a new bin is cheap and keeps
        // flexibility for future items.
        if progress < 0.3 && open_bins_count < 4 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nis = next_item_size as f64;

    // Core: quadratic in post_residual, scaled by stream progress
    let mut score = pr * (1.0 + 0.9 * pr / cap) * (0.6 + 0.8 * progress);

    // Non-linear coupling: post_residual vs item size (tight fits rewarded)
    let fit_ratio = it / cap;
    score -= 12.0 * fit_ratio * (1.0 - pr / cap) * (1.0 + progress);

    // Lookahead: does the next item fit into post_residual? Reward if yes.
    if nis > 0.0 {
        let nx = nis / cap;
        let fits_next = if pr >= nis { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * nx * (1.0 + progress);
        // Penalize residual that is just barely too small for next item (dead space)
        let gap = (nis - pr).max(0.0) / cap;
        score += 6.0 * gap * gap * (1.0 - fits_next);
    }

    // Mean residual divergence: prefer bins whose residual deviates from mean
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bin bonus (smooth via inverse fitting count)
    score -= 10.0 / (fitting_bins_count as f64) * fit_ratio;

    // New-bin candidate: penalize mildly, relax late in stream
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64 * (1.0 - progress);
        // But reward new bin if item is large relative to typical residuals
        score -= 10.0 * fit_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact small remainders are good.
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect fit
    } else if post <= 10 {
        score -= 15.0;
    } else if post <= 20 {
        score -= 5.0;
    } else if post > 60 {
        score += 10.0; // leaves large unusable-ish gap
    }

    // Modulo-10 harmonic class: dead space in residues 1..9 within a decade is bad.
    let r10 = post % 10;
    if r10 != 0 && post > 0 && post < 30 {
        score += 6.0 - r10 as f64 * 0.5;
    }

    // Coupling with next item: reward exact harmonic match of post_residual with next item.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / cap);
        } else {
            score += 4.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits poorly.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open new bin
        }
        // early stream: slightly cheaper to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to mean residual.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference for fuller bins overall.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium gaps (10..20) are mildly wasteful too.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins
    // unless this fit is genuinely tight.
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // Coupling: prefer bins whose residual is close to the mean residual
    // (keeps bin population homogeneous, easier to combine future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item could have used this bin but we leave too little room.
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score -= 40.0; // opening a bin is fine when existing bin is last resort
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 3.0 * overflow / bin_capacity as f64;
        }
    }

    // Penalize dead space relative to mean residual.
    if (post_residual as f64) > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * fit_ratio;
    }

    // Late-stream pressure: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item cannot fit post-residual, penalize leaving that dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.15 * next_item_size as f64;
        }
    }

    // Global state coupling: prefer filling bins when many are open and mean residual is low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);
    score += 0.4 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate handling: empty bin should only win when fit is poor
    // and other bins are crowded.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 55.0 * (1.0 - poor_fit) - 8.0 * fitting_bins_count as f64;
        // Late in stream, avoid opening new bins unless necessary.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post_residual, with non-linear penalty on dead space
    let mut score = pr * (1.0 + 0.8 * norm_post * norm_post);

    // Non-linear coupling: residual waste matters more as stream progresses
    score += 30.0 * progress * norm_post * norm_post * norm_post;

    // Tight fits reward: item fills bin well
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * (1.0 - norm_post);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 10.0 * (nxt / cap) * (1.0 - progress);
        } else {
            // penalize leaving residual that nothing useful follows
            score += 8.0 * norm_post * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize adding to bins whose residual is already low relative to mean (fragmentation)
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 6.0 * ((mean_residual - res_f) / cap).abs() * progress;
    }

    // New-bin candidate: make it moderately attractive only for large items / late stream
    if bin_residual == bin_capacity {
        score = pr + 18.0 - 20.0 * fill - 15.0 * progress + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification by integer division
    let post = post_residual;
    let class = post / 10; // coarse residual class (0..10)

    // Perfect fits are gold: reward strongly
    if post == 0 {
        score -= 1000.0;
    } else if post <= 5 {
        score -= 50.0; // near-perfect fit, negligible dead space
    } else if post < 10 {
        score -= 10.0;
    }

    // Penalize unusable dead space: residual too small for the smallest item class
    if post > 0 && post < 10 {
        score += 200.0; // dead space below min item size
    }

    // Harmonic modulo logic on post_residual: favor residuals that are
    // "smooth" multiples of common item granularities (10, 20, 25, 50)
    if post % 10 == 0 {
        score -= 15.0;
    }
    if post % 25 == 0 {
        score -= 10.0;
    }
    if post % 50 == 0 {
        score -= 10.0;
    }

    // Class-based decay: higher residual classes waste more potential
    score += (class as f64) * 2.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 300.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            score -= 40.0 - (slack as f64).min(40.0);
            // harmonic check: does next item leave a clean residual class?
            let post2 = post - next_item_size;
            if post2 == 0 {
                score -= 100.0;
            } else if post2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            let gap = (next_item_size - post) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current bin fit is bad (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin: its post_residual == capacity - item_size
        // add a fixed handicap so good fits into open bins win
        score += 30.0;
        // but if open bins are congested, new bins become better
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if open_bins_count as f64 > mean_residual / (bin_capacity as f64) * 4.0 {
            score -= 20.0 * progress;
        }
    }

    // Tie-break: prefer fuller bins (smaller bin_residual) among equals
    score += (bin_residual as f64) * 0.05;

    // Mild penalty for spreading across too many open bins
    if open_bins_count > 10 {
        score += (open_bins_count as f64 - 10.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100 stream),
    // use a soft threshold around 10 (min item size historically), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward near-perfect fits superlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: residual == capacity. Prefer keeping items in open bins
    // unless the new bin gives a better long-term shape. Penalize mildly so a
    // new bin wins only when open-bin fits create big dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * open_bins_count as f64;
        // If the next item would fit well in the leftover of this new bin, ease penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Open-bin pressure: many open bins -> favor filling existing ones (higher score for new bins
    // already handled); also favor bins with below-average residual (tighter bins first).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
        score += 1.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }

    score
}

