pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let p2 = progress * progress;
    // Early stream: strongly prefer tight fills (small post_residual) but
    // keep some slack for future items; late stream: dead space matters more.
    let tightness = x * x * (1.0 - progress) + x * x * x * progress;
    score += 40.0 * tightness;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_frac * fit_frac * (1.0 - progress);

    // Penalize leaving residual that no plausible next item can use:
    // smooth interaction between post_residual and lookahead size.
    if next_item_size > 0 {
