    // Mild preference for consolidating into bins below mean residual.
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).max(-1.0).min(1.0);

    // Late stream: slightly discourage opening new bins (smooth in progress).
    if bin_residual == bin_capacity {
        score += 15.0 * progress * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
