    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo coupling: does post_residual + next_item_size land on a harmonic
    // fraction of capacity (e.g. exactly capacity/2, capacity/3, capacity/4)?
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo = post_residual + next_item_size;
        if combo == bin_capacity / 2 || combo == bin_capacity / 3
            || combo == bin_capacity / 4 || combo == bin_capacity {
            score -= 15.0; // next item will land on a clean harmonic split
        } else if next_item_size == post_residual {
            score -= 30.0; // exact fill with lookahead item
        }
        // Integer-division threshold: post_residual in same "decade class" as next item
        if post_residual / 10 == next_item_size / 10 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Lookahead item cannot use the leftover -> leftover is dead for the future
        score += 8.0;
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 3 {
        // Many options: be pickier about wasted space.
        score += post_residual as f64 * 0.05;
