    // Reward tightness relative to mean residual state.
    let tightness = post_residual as f64 - mean_residual;
    score += 0.15 * tightness;

    // Stream progression: early on, prefer keeping bins balanced (open new bins
    // freely to build a good pool); late, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.25);

    // New-bin candidate handling: empty bin has full residual; make it attractive
    // only when the item is large or current residuals are poor.
    if bin_residual == bin_capacity {
        if item_size >= 60 || mean_residual < 15.0 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
