    // Global state coupling: many open bins with high mean residual -> avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 4.0 * mean_residual / 100.0;
    }

    // Late in stream: consolidate more aggressively
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        + 60.0 * pr_norm * pr_norm * pr_norm;

    // Smooth progress coupling: as stream progresses, tighten residual preference
    score *= 1.0 + 0.5 * progress * pr_norm;

    // Reward tight fits (small post residual) more strongly when item nearly fills bin
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill * (1.0 - pr_norm);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Lookahead: bonus if next item fits in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins vs mean residual
    score += 0.05 * (open_bins_count as f64 - mean_residual / cap).max(0.0);

    // New-bin candidate: make it slightly unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near 0 are good,
    // residues just above small thresholds are dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that cannot fit the smallest plausible item (<= 10)
    if post_residual < 10 {
        score -= 25.0; // perfect closure, tiny residue is fine
    } else {
        // residue bands: penalize awkward leftovers in [10, 30)
        if post_residual < 30 {
            score += 8.0 * (1.0 - post / 30.0);
        }
    }

    // Modulo-class logic on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 5.0; // aligns with capacity fractions, likely reusable
    }
    if post_residual > half {
        score -= 6.0; // still roomy bin, good
    }

    // Lookahead coupling: if next item fits the post-residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving mid-sized residue
            score += (next_item_size - post_residual).min(20) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let waste_if_open = cap - post as f64; // = item_size
        score += 30.0
            - 0.1 * open_bins_count as f64
            - (cap - waste_if_open) * 0.05; // slightly cheaper for large items
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 10.0; // next item big too; fresh bin may be wise
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post).clamp(-20.0, 20.0) * 0.2;

    // Prefer tighter fits overall
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are "unusable" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Lookahead dead zone: next item almost fits but not quite.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer tighter bins
    // (smaller residual relative to mean) and discourage opening yet another bin.
    let pressure = open_bins_count as f64 * 0.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 20.0 + pressure * 2.0;
        // Late in the stream, opening a new bin is even less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    } else {
        // Prefer bins tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Mild penalty proportional to open bins to consolidate.
        score += pressure * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and next_item_size (perfect pair packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // exact lookahead match: place here
        } else {
            // penalize proportionally to mismatch, but only if item would still fit
            if next_item_size <= post_residual {
                score += 0.35 * diff as f64;
            } else {
                // next item cannot fit here regardless; mild penalty scaled by overflow
                score += 0.10 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Penalize tiny unusable dead space (dead space < typical min item size 10)
    if post_residual < 10 {
        score -= 15.0; // dead space is fine if bin is essentially closed out
    } else {
        score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Favor tight fits relative to mean residual
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, prefer closing bins tightly over spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Mildly discourage opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (items >= 1 here, but penalize very small unusable gaps lightly).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item can fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Penalize leaving a gap that just barely misses the next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 0.6 * miss;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more selective (favor new bins
    // for good structure); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> encourage
    // filling existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln1p();
    score += 2.0 * open_pressure * (1.0 - tightness);
    if mean_residual > (item_size as f64) {
        score -= 1.5;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But early on, opening a well-structured new bin is okay.
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        - 12.0 * prn * (1.0 - prn)
        + 18.0 * progress * prn * prn
        - 9.0 * (1.0 - progress) * (1.0 - prn) * (1.0 - prn);

    // Penalize dead space relative to mean residual
    score += 0.25 * (pr - mean_residual) * (1.0 - prn);

    // Last-chance bonus: only one bin fits, prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild penalty for spreading across many open bins early in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-ish, penalize slightly unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (common small item sizes) are rewarded.
    let pr = post_residual;
    // Dead-space penalty: leftover that is too small to fit typical items (1..10)
    // is nearly useless; penalize heavily.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Harmonic classes: leftover that exactly matches common size classes
    // (multiples of 10 up to 80) is highly reusable.
    let class_match = pr >= 10 && pr <= 80 && pr % 10 == 0;
    if class_match {
        score -= 15.0;
    }

    // Perfect fit is best.
    if pr == 0 {
        score -= 50.0;
    }

    // Integer-division thresholds on post_residual: leftover in [10,25] is a
    // "small change" zone - mildly penalize to prefer compacting elsewhere.
    let small_zone = pr / 25; // 0 for pr<25
    if small_zone == 0 && pr >= 10 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual; evaluate its class
            let nr = pr - next_item_size;
            if nr % 10 == 0 && nr <= 80 {
                score -= 20.0;
            } else if nr < 10 {
                score += 15.0;
            }
        }
        // If next item is large, keep large residuals free for it.
        if next_item_size >= 60 && pr >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Penalize the fresh bin mildly, more so early in stream
    // when consolidating is cheap, and when mean residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress) + 0.3 * mean_residual;
        // But if the item is huge and nothing sensible fits, opening is fine:
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Mild preference for tighter bins (small residual) scaled by occupancy.
    score += (bin_residual as f64) * 0.05;

    // Modulo tie-breaker on capacity fractions: bins whose residual is in the
    // lower half of capacity are slightly preferred (denser bins first).
    if (bin_residual * 2) < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // moderate dead space
    }

    // Reward tight fits (exact or near-exact).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space
    // or the next item would benefit from a fresh full bin.
    if bin_residual == bin_capacity {
        let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        let next_helps = next_item_size > 0 && next_item_size >= post_residual && post_residual > 0;
        score = 55.0 + dead * 30.0 + if next_helps { -10.0 } else { 0.0 }
            + (open_bins_count as f64) * 0.5;
    }

    // Open-bins pressure: mildly discourage scattering across many open bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 15.0;

    // Progress-aware tiebreak: late in the stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            // Dead space that cannot fit the next item: penalize.
            score += 30.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 80.0;
        // New bin is attractive only if item is large relative to capacity
        // and current open bins are crowded.
        score += 0.3 * (open_bins_count as f64).max(0.0) * -1.0;
        score += 0.2 * item_size as f64;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits (small post residual) non-linearly.
    score -= (1.0 - fit) * (1.0 - fit) * 40.0;

    // Penalize dead space that cannot plausibly be filled later.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // tiny gap nearly always wasted -> but tight fit good
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // awkward medium gap
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 18.0 + 0.3 * next_item_size as f64;
        } else {
            // penalize leaving a gap that blocks the next item slightly
            score += 4.0;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if is_new_bin {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = crowding * (open_bins_count as f64).ln().max(0.0);
        // base penalty so new bins are used only under pressure
        score += 55.0;
        score -= pressure * 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer filling existing bins a bit less strictly
        score -= progress * 10.0;
    }

    // Mild preference to spread across many open bins when residuals are large.
    if !is_new_bin && mean_residual > 0.6 * bin_capacity as f64 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) coupling in post_residual
    let mut score = post + 0.9 * post * (post / cap) - 0.35 * post * (post / cap) * (post / cap);

    // Smooth progress coupling: later in the stream, penalize slack more aggressively
    let progress_coupling = 0.5 * progress * post * fill;
    score += progress_coupling;

    // Dead-space penalty: small post_residual that can never fit typical items
    let dead = (1.0 - post / cap) * (1.0 - post / cap);
    score += 4.0 * dead * (1.0 - fill);

    // Mean residual interaction: placing into a bin below mean residual is favored
    score -= 0.3 * (mean_residual - post) * (mean_residual / cap).tanh();

    // Last-chance bonus: only bin that fits -> strongly reward using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * fill;
    }

    // Lookahead: reward if next item can fit into post_residual (chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let slack = (post - nxt).max(0.0);
        score -= fits_next * (5.0 + 3.0 * (1.0 - slack / cap)) * (0.5 + 0.5 * progress);
        // Penalize post_residual that blocks the next item
        score += (1.0 - fits_next) * 3.0 * (nxt / cap) * (1.0 - progress);
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation
    let pressure = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score += 2.0 * pressure * post / cap;

    // Slight bias against opening a new empty bin unless item is large
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * (cap - item) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover is.
    // Residuals that are multiples of common item classes (10, 20, 25, 50) are valuable.
    let post = post_residual as u32;
    let mut reusability = 0.0f64;
    for m in [10u32, 20, 25, 50].iter() {
        if post >= *m && post % m == 0 {
            reusability += 1.0;
        }
    }
    if post == 0 {
        reusability += 3.0; // perfect fill
    }
    score -= reusability * 4.0;

    // Penalize dead space: small unusable leftovers (1..10 and odd residues)
    if post > 0 && post < 10 {
        score += 12.0;
    }
    if post % 10 != 0 && post > 0 {
        score += 2.5;
    }

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 15.0; // exact future fill
        } else if next_item_size < post {
            let slack = (post - next_item_size) as f64;
            score += slack * 0.3; // imperfect future fit
            if post % next_item_size == 0 {
                score -= 6.0; // harmonic divisibility
            }
        }
    }

    // Last-chance bonus: only this bin fits -> strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Tight fit reward: fraction of bin consumed
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Prefer denser bins among many open bins
    if bin_residual < mean_residual as u32 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Early stream: slightly prefer opening bins to spread capacity
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if current fit would be poor
        let waste = post as f64;
        score = 40.0 + waste - fill_frac * 30.0 - progress * 5.0;
        if fitting_bins_count == 1 {
            score += 30.0; // never open when it's the last chance
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // room for a known pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0;
    } else if post_residual > 9 && post_residual < 20 {
        // Moderately awkward gap: mild penalty scaled by gap smallness.
        score += (20.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (small post_residual in the usable range).
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual <= 20 {
        score -= (20 - post_residual) as f64 * 1.2;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins whose residual is close to what we consume (relative fit quality).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual too small for next item: penalize mildly.
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // fallback unless the item is large relative to capacity or no bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with number of open bins
        // and shrinks late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.75
            + open_bins_count as f64 * 2.0
            - progress * 15.0
            - item_size as f64 * 0.5;
        // If the item is big, opening a fresh bin is more attractive.
        if item_size >= 60 {
            score -= 15.0;
        }
        // If only one bin fits the item, strongly discourage opening a new one.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // If the next item is large, a fresh bin preserves flexibility.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // 2-step lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize if next item cannot use the leftover (wasted space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.3 * post_residual as f64;
    }

    // Penalize bins with residual far below mean (poor relative fit).
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect chain.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.3 * item_size as f64;
        let chain = if next_item_size > 0 { (item_size + next_item_size) as f64 } else { item_size as f64 };
        if chain <= bin_capacity as f64 {
            score = base - 20.0;
        } else {
            score = base;
        }
    }

    // Early in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

