    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 1.5
            - (item_size as f64 / bin_capacity as f64) * 40.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // If few bins fit the item, opening a new one is more attractive.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Lookahead: if next item pairs well with this one in a fresh bin, favor opening.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        return score;
    }

    // Tight fit reward: minimize wasted space quadratically.
    let pr = post_residual as f64;
    score += pr * pr * 0.01;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead synergy: if the next item fits the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (post_residual as f64 - next_item_size as f64).abs() * -0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we waste space.
        score += pr * 0.05;
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual coupling: if this bin is tighter than average, prefer it.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Time horizon: late in the stream, be more aggressive about tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += pr * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
