}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual, non-linearly amplified
    let mut score = post * (1.0 + 0.6 * post / cap);

    // Tight-fit reward: strongly favor bins where item fills most of residual
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: small post_residual that is hard to reuse
    let dead = (post / cap).powi(3);
    score += 30.0 * dead * (1.0 - progress);

    // Smooth polynomial coupling with stream progress: late in the stream,
    // consolidate aggressively (prefer filling existing bins)
    let coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 8.0 * coupling * (post_residual as f64 / cap);

    // Last-chance bonus: only one bin fits -> strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 10.0 * (1.0 - slack);
        } else {
            // penalize leaving residue that cannot host the next item
            score += 3.0 * (1.0 - progress) * (nxt / cap);
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post).abs();
        // penalize opening a new bin mildly, more early in the stream
        score += 6.0 + 10.0 * (1.0 - coupling);
        // but if mean residual of open bins is small (they're full), new bin is fine
        score -= 4.0 * (mean_residual / cap);
        let _ = spread;
    }

    // Mild penalty for proliferating bins
    score += 0.3 * open_bins_count as f64 * coupling;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small dead-space" classes are strongly preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr <= 10 {
        score -= 60.0; // near-perfect, likely unusable sliver anyway
    } else if pr <= 20 {
        score -= 25.0;
    } else if pr <= 35 {
        score -= 8.0;
    }

    // Dead space penalty: leftover smaller than the lookahead item is wasted
    // (modulo-style class: pr % 100 vs next_item_size).
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 30.0;
    }
    // If lookahead fits exactly into post_residual, big reward.
    if next_item_size > 0 && pr == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 15 {
        score -= 35.0; // leaves a good class for the next item
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class of bin_residual via capacity fractions (1/4, 1/2, 3/4).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if bin_residual <= quarter {
        score += 5.0; // cramped bin, mild penalty to deprioritize
    } else if bin_residual <= half {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it
    // on a bad fill; but if fill is good, reward it.
    if fitting_bins_count == 1 {
        if fill_frac > 0.5 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 50.0 + 0.3 * mean_residual
            + (open_bins_count as f64).sqrt() * 2.0
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 }
            - if next_item_size > 0 && next_item_size > post_residual { 40.0 } else { 0.0 };
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
