    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin when all open fits would create
    // severe dead space or the item barely fits nothing well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced when many bins are open anyway
        // or when the current bin fit would be very wasteful.
        score += 40.0 - 0.5 * open_bins_count as f64;
        if post_residual > 40 {
            // Large residual after placement in a fresh bin is fine (roomy).
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual deviates below the mean
    // (tighter bins get filled first, keeping roomier bins flexible).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect closure bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is nearly unusable.
        score += 25.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers.
            score += 0.15 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual above mean can absorb
    // slack better; bins below mean should be closed out with tight fits.
    if (bin_residual as f64) >= mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or stream is early and we have few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        if next_item_size > 0 && item_size >= 70 {
            score -= 10.0; // big items start fresh bins more readily
        }
    }

    // Slight preference to fill bins with many open bins (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 + 0.3 * next_item_size as f64;
        } else {
            // Next item won't fit here: penalize wasting a "good" bin.
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins with larger residuals when many bins are open.
    score -= 0.05 * bin_residual as f64 * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be more conservative about creating dead space;
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * fit_ratio;
    score -= progress * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Global balance: penalize bins far from the mean residual to keep diversity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty: opening a new bin is costly.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and would leave tiny waste anyway, new bin is fine.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 45.0;
        }
        // If many fitting bins exist, new bin is less needed.
        score += 5.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear penalty on wasted residual, amplified by stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let waste = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 40.0 * waste;

    // Reward tight fits: perfect fit bonus decaying smoothly with residual
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score -= 25.0 * (-norm_pr * 12.0).exp();
    }

    // Penalize bins far from mean residual (prefer homogeneity), coupling with progress
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni) / cap;
        if gap >= 0.0 {
            score -= 20.0 * gap * (1.0 - gap) * 4.0;
        } else {
            score += 15.0 * (-gap) * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate into fewer bins as many bins accumulate
    score += (open_bins_count as f64).ln().max(0.0) * (norm_pr * 10.0) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual usage elsewhere
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 25.0 - 45.0 * size_frac * size_frac + 20.0 * progress;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot" of the capacity it falls into.
    let harmonic = bin_capacity / 5; // 20-unit classes
    let post_class = (post_residual / harmonic) as f64;
    score += post_class * 3.0;

    // Dead-space penalty: residuals that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect packing (small post residual classes).
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class of the gap after hypothetically placing next item.
            let gap = post_residual - next_item_size;
            let gap_class = (gap / harmonic) as f64;
            score -= 6.0 - gap_class * 2.0;
            if gap == 0 {
                score -= 20.0; // perfect chain
            }
        } else {
            // Next item won't chain; penalize proportionally to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += (overflow / 20.0).min(10.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Prefer filling bins that are already mostly full (low residual class).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_frac * 12.0;

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64).sqrt() * 2.0;
        // But allow a new bin if current item is huge and would leave bad residue elsewhere.
        if item_size > bin_capacity / 2 && post_residual < 10 {
            score -= 15.0;
        }
    }

    // Stream progression: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.05 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        // Unusable dead space: heavily penalize.
        score += (11 - post_residual) as f64 * 8.0;
    } else {
        // Usable leftover: mild reward for larger usable gap.
        score -= post_residual as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure: many open bins -> discourage opening new ones,
    // favor spreading load across existing bins.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // Early stream: new bins are cheap; late stream: expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        score -= open_bins_count.min(10) as f64 * 0.5;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Would strand space the next item can't use.
        score += 6.0;
    }

    // Favor bins tighter than the mean (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty on dead space.
    let cap = bin_capacity as f64;
    score += 0.35 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // chain fit: this bin will be perfectly filled next step
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tightly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty scaled by overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / cap);
        }
    }

    // Relative-to-mean-residual coupling: placing into a bin with residual
    // far above the mean tends to waste its larger space; prefer bins near/below mean.
    let res = bin_residual as f64;
    if res > mean_residual {
        score += 0.25 * (res - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that would be left nearly empty anyway
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Late in the stream, consolidate aggressively; early on, allow new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate: penalize opening a new bin, more so mid/late stream
    // or when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0 + 15.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.6 {
            score += 8.0; // big next item: better keep fresh bin for it
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty on wasted space
    score += 0.15 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if the next item can fit into the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward for near-exact two-item packing
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 8.0;
            }
        } else {
            // penalize leaving residual that is just slightly too small for the next item (dead space)
            let overshoot = (next_item_size as f64 - post_residual as f64).min(30.0);
            score += 0.4 * overshoot;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when few bins are open or the item is large
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score = item_size as f64 * 0.5 + pressure * 2.0 + progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if item_size >= 60 {
            score -= 20.0; // large items prefer fresh bins
        }
        // discourage opening new bins when many open bins have ample residual
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 30.0;
        }
    } else {
        // Slight preference for bins with smaller current residual (best-fit bias)
        score += 0.1 * (bin_residual as f64 - post_residual as f64).signum();
        // Favor bins below mean residual (tighter bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = post / cap;

    let mut score = post;

    // Non-linear waste penalty: quadratic coupling of post_residual with progress
    score += 6.0 * fit_norm * fit_norm * (0.5 + progress);

    // Reward tight fits smoothly
    score -= 4.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * item_size as f64 / cap;

    // Last-chance bonus (smooth sigmoid-like weight)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 8.0 * last_chance * (1.0 - fit_norm);

    // Lookahead: reward bins whose post-residual can still fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let can_fit = if post >= nx { 1.0 } else { 0.0 };
        score -= 5.0 * can_fit * (nx / cap);
        // Penalize leaving residual just below next item (dead space coupling)
        let gap = (nx - post).max(0.0) / cap;
        score += 7.0 * gap * gap * (1.0 - progress);
    }

    // Pressure from many open bins vs mean residual: prefer bins near mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight preference for keeping bin count low early, reusing bins late
    score += (open_bins_count as f64).ln().max(0.0) * 0.4 * (1.0 - progress) * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on fine
    // granularity (small modulo classes) are more reusable.
    let pr = post_residual;
    let class_bonus = match pr % 10 {
        0 => 6.0,
        1 | 2 | 3 => 3.0,
        4 | 5 | 6 => 1.5,
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize residuals too small to be useful: dead space below typical
    // item granularity gets progressively punished.
    if pr > 0 && pr < 10 {
        score += 12.0 * (10 - pr) as f64;
    }

    // Perfect fit reward: harmonic alignment with capacity fractions.
    if pr == 0 {
        score -= 30.0;
    } else if pr % 25 == 0 {
        score -= 8.0;
    } else if pr % 20 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 6.0 * (1.0 - waste as f64 / cap);
        } else {
            // next item cannot fit here; slight penalty scaled by gap class
            let gap = (next_item_size - pr) % 20;
            score += 1.0 + gap as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless residual would be terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if pr < 10 {
            score += 6.0; // still punish near-dead space
        }
    }

    // New-bin candidate handling: an empty bin is attractive when the
    // current item is large (little fragmentation risk) or when open bins
    // are crowded (mean residual small) late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / cap;
        let crowded = 1.0 - (mean_residual / cap).min(1.0);
        score -= 18.0 * large_item + 14.0 * crowded * progress;

        // Opening a new bin when few bins are open keeps flexibility.
        if open_bins_count <= 2 {
            score -= 5.0;
        }
    }

    // Prefer filling fuller bins: tie-break by residual fraction.
    score += (bin_residual as f64 / cap) * 2.0;

    // Mild preference to keep mean residual balanced (avoid many tiny
    // residual bins plus one huge one).
    score += ((mean_residual - bin_residual as f64) / cap).abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small for typical items are wasted.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 40.0;
    } else {
        // Reward tightness relative to capacity.
        score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Penalize large leftover that could still host big items less harshly.
    if post_residual >= 40 {
        score -= 8.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; dead space likely.
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate.
        score += 20.0 + 4.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > item_size {
            score += 5.0;
        }
    } else {
        score += 1.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a laggard; use it.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev;
    }

    // Slight stream progression: tighten packing later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item (perfect chain), penalize wasted gaps.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Reward proportional to how well next item fits the leftover space.
        score -= 60.0 - gap.min(60.0);
        if gap == 0.0 {
            score -= 40.0; // perfect 2-step match
        }
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the leftover.
        score += 0.35 * (post_residual as f64);
    }

    // Compare post_residual against mean residual: leaving more than average
    // is wasteful unless it enables the next item.
    score += 0.25 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could reasonably hold the item,
    // unless the item is large relative to capacity (better in a fresh bin).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.55 {
            score += 45.0 * (1.0 - fill_ratio);
        } else {
            score -= 10.0 * fill_ratio; // big items prefer fresh bins
        }
    }

    // Early in the stream, be more willing to open bins (keeps flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= 15.0 * (1.0 - progress);
    }

    // Tight fits are good: minimize leftover fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for the smallest possible item.
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    }

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if the next item can use the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Creating a residual the next item cannot use: penalize proportionally.
            score += 3.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Prefer filling bins with large mean residual (reduce spread of wasted space).
    score -= 0.3 * mean_residual;

    // Prefer using more-opened bins (consolidation) rather than spreading out.
    if open_bins_count > 0 {
        score += 40.0 / (open_bins_count as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to exploit); later, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with progress and item size.
        let mut new_bin_cost = 30.0 + 25.0 * progress;
        if item_size >= 50 {
            new_bin_cost -= 10.0; // large items justify fresh bins early
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_cost += 12.0; // opening a bin that serves next item too is fine
        }
        score += new_bin_cost;
    } else {
        // Existing bin: mild progress-dependent bonus for reusing.
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.5 * progress * norm_pr) - 1.8 * progress * norm_pr * norm_pr;

    let mut score = poly * 10.0;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr).powi(3) * 8.0 * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += ((pr - mean_residual) / cap).powi(2) * 4.0;

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Slight penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" residue classes (multiples of 10, or small dead space) are
    // more likely to absorb future items.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit is always great
    } else if pr % 10 == 0 {
        -25.0 // leftover in the same decimal grid as typical item sizes
    } else if pr <= 10 {
        -15.0 // small dead space, still usable by small items
    } else if pr % 25 == 0 {
        -18.0 // quarter-capacity grid leftover
    } else {
        8.0 * ((pr % 10) as f64) / 10.0 // penalize awkward residues
    };
    score += class_bonus;

    // Harmonic class of the item itself relative to capacity fractions.
    let item_class = item_size % 10;
    if item_class == 0 {
        score -= 6.0; // item on the decimal grid pairs well with grid residuals
    } else {
        score += 3.0 + item_class as f64 * 0.4;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 15.0 - (gap as f64).min(40.0) * 0.25;
        } else {
            score += 10.0; // next item cannot use this bin's leftover
        }
        // Harmonic match between next item and post residual modulo classes
        if pr % 10 == next_item_size % 10 && next_item_size <= pr {
            score -= 8.0;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score -= pr as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if pr <= 5 {
            score -= 10.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // and existing residuals are fragmented or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64)) / (bin_capacity as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
        let _ = fragmentation;
        let _ = pressure;
        // Penalize new bins mildly so they only win when fits are poor...
        score += 35.0;
        // ...unless the item is huge (harmonic class near capacity) and
        // would leave a very awkward residual anywhere.
        if item_size >= 60 {
            score -= 20.0;
        }
        if item_size % 10 == 0 && item_size >= 50 {
            score -= 12.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.25 {
            score -= 15.0;
        }
    } else {
        // Prefer tighter fits among open bins: reward low post residual.
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Mean-residual alignment: bins close to the mean are "typical"; prefer
    // consuming outliers with large residuals first when item is big.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold on post residual: leftovers in (10, 20]
    // are a dead zone for items of size >= 20 but fine for tiny items.
    if pr > 10 && pr <= 20 {
        score += 6.0;
    }
    if pr > 50 {
        score += 10.0; // wasteful large leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Dead space penalty: quadratic growth as residual shrinks below item sizes.
    let dead = (post_residual as f64).powi(2) / 100.0;
    score += dead;

    // Reward tight fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins when few are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins near the mean residual (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // Progress-based pressure: as stream progresses, prefer reusing bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement sets up a perfect follow-up — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterwards: mild reward proportional to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * tight;
        } else {
            // Next item cannot use the post-residual: penalize dead space creation,
            // worse when post-residual is too small to ever be useful.
            let waste = post_residual as f64 / bin_capacity as f64;
            if post_residual < 10 {
                score += 60.0 * (1.0 - waste);
            }
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 100.0;
    }

    // Compare post-residual against mean residual across open bins:
    // leaving a residual near the mean keeps the pool of bins flexible.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bin (only fitting bin): avoid forcing a new bin unless fit is tight.
    if fitting_bins_count == 1 {
        score -= 30.0 * (item_size as f64 / bin_residual as f64);
    }

    // Prefer using nearly-full bins (small residual) over sparse ones.
    score += 0.3 * (bin_residual as f64 - post_residual as f64);

    // Mild penalty for proliferating bins when the fit is loose.
    if post_residual > bin_capacity / 2 {
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to spread across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.8 * (waste / cap) * (waste / cap) * cap;

    // Reward perfect fill strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well,
    // strongly prefer this bin (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual as u32 - next_item_size) as f64;
            score -= 18.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; slight penalty scaled by overflow size.
            score += 0.15 * (nxt - post_residual as f64).min(cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 40.0;
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If item is large relative to capacity, a fresh bin is more reasonable.
        score -= 0.3 * item_size as f64;
        // If open bins are crowded (low mean residual), a new bin is fine.
        score -= (cap - mean_residual).max(0.0) * 0.2;
    } else {
        // Existing bin: slight reward when its residual is close to item size.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fit_ratio.min(1.0);
    }

    // Mild preference for fuller bins among open bins.
    score -= 0.05 * (cap - bin_residual as f64);

    // Small tie-breaker noise-free deterministic term.
    score += 0.001 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let npr = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear (quadratic) coupling
    let mut score = npr * (1.0 + 1.5 * npr * npr);

    // Dead-space penalty: residual too small for the next item is wasted
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            // unusable for lookahead: penalize proportionally to how close it is to wasted
            score += (ns - pr) / cap * (2.0 + 2.0 * progress);
        } else {
            // reward residual that still accommodates the next item
            score -= 0.4 * (pr / ns).min(3.0).ln().max(0.0) * (1.0 - 0.5 * progress);
        }
    }

    // Smooth interaction: as stream progresses, tighter packing matters more
    score += npr * npr * progress * 3.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 2.5 + 2.0 * progress;
    } else if fitting_bins_count > 1 {
        // abundance of alternatives: mild penalty for using a scarce-fit bin is wrong;
        // instead reward bins with average-ish residuals when many choices exist
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: residual == capacity. Penalize opening a new bin,
    // but relax the penalty late in the stream or when few bins fit.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        let scarcity = if fitting_bins_count >= 1 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        score += 1.2 + 2.0 * (1.0 - progress) + 1.5 * scarcity;
    } else {
        // reward using an open bin, especially one tighter than the mean residual
        let dev = (mean_residual - pr) / cap;
        score -= 0.3 * dev; // smaller residual than mean => negative deviation => lower score
        score += 0.15 * ((open_bins_count as f64).ln() - 1.0).max(0.0);
    }

    // Smooth fill-ratio coupling: reward high utilization quadratically
    let fill = (cap - pr) / cap;
    score -= 1.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into buckets of 10
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { (next_item_size + 9) / 10 } else { 0 };

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward if next item exactly matches the post_residual class (harmonic match)
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        score -= (20 - diff.min(20)) as f64 * 2.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space: next item cannot use this residual
        score += (post_residual as f64) * 1.5;
    }

    // Penalize residuals in awkward classes (1..9 of a decade) that few items fit
    let rem = post_residual % 10;
    if post_residual > 0 && rem != 0 && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New bin candidate: penalize mildly unless current bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (fitting_bins_count == 0) as i32;
        score += 30.0 - congestion as f64 * 100.0 - progress * 10.0;
    }

    // Prefer bins tighter than the mean residual (fill fuller bins first)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny (unusable gaps)
    // are heavily penalized; residuals that are large are mildly penalized
    // (wasted space in a mostly-empty bin).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small but not unusable post residual).
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a perfect fit with
        // the lookahead item or existing bins are badly fragmented.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.3;
        }
        // Late in the stream, opening new bins is less costly.
        score -= progress * 20.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the mean (below-mean residual means well-utilized bin).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving a gap it can't use.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual.
    score += 0.5 * (post_residual as f64).powf(1.3);

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 10 {
            score -= 25.0 - gap as f64;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover space: penalize proportional to leftover.
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize wasting space in a fresh bin unless it's a big item.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - fill);
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Penalize large post_residual that is likely unusable dead space:
    // dead space is worst when it can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + item_size as f64 * 0.1;
    }

    // Global fragmentation pressure: when many bins are open with high mean residual,
    // prefer filling existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= mean_residual * 0.15 * (0.5 + progress);
    }

    // New-bin candidate handling: an empty bin should only win when it offers
    // a better long-term structure. Penalize opening new bins mildly, more
    // so early when few bins exist (keep bin count low), less when stream
    // is nearly done.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() * 2.0;
        score += 15.0 + open_pressure * (1.0 - progress * 0.5);
        // If next item is large, an empty bin preserves flexibility.
        if next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Mild preference for bins with less residual overall (fill fuller bins first).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Tight fit reward: smooth quadratic in item usage fraction
    let tight = (norm_item * (1.0 - norm_item)) * 4.0; // peaks at 0.5
    score -= 12.0 * tight * (1.0 + progress);

    // Lookahead: penalize residual that fails next item, reward residual that fits it
    if next_item_size > 0 {
        let fits_next = if pr >= norm_next * cap { 1.0 } else { 0.0 };
        let gap = (pr - norm_next * cap).abs() / cap;
        score += 8.0 * (1.0 - fits_next) * (1.0 + gap);
        score -= 6.0 * fits_next * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for proliferation of open bins relative to mean residual
    score += 0.5 * (open_bins_count as f64).sqrt() * norm_pr;
    score += 2.0 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Class 0: post_residual divisible by 10 (aligns with common item sizes) -> reward.
    // Class 1: leaves awkward 1..9 sliver -> penalize.
    let pr = post_residual;
    let class = (pr % 10) as i32;
    match class {
        0 => { score -= 12.0; }
        1..=4 => { score += (5 - class) as f64 * 2.0; }
        5 => { score += 4.0; }
        _ => { score += (class - 5) as f64 * 2.5; }
    }

    // Dead-space penalty: tiny unusable residue (cannot hold min item of 1... but
    // with unknown distribution treat < 15 as likely dead unless next item fits).
    if pr > 0 && pr < 15 {
        score += 20.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward when the next item fits exactly into post_residual
    // (harmonic chaining), penalize when next item nearly fits but not quite.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // harmonic class of the chain gap
            if gap % 10 == 0 { score -= 8.0; } else { score += (gap % 10) as f64 * 0.8; }
        } else {
            // next item won't fit here regardless; slight penalty for tight bin
            score += 3.0;
        }
    }

    // Integer-division threshold on residual fraction: bins below half capacity
    // that still can't be closed cheaply get a mild penalty.
    let residual_frac = pr as f64 / cap;
    if residual_frac < 0.5 && residual_frac > 0.0 {
        score += (0.5 - residual_frac) * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or this bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / cap + 1.0);
        let awkward_current = (bin_residual - item_size) % 10 != 0;
        if open_bins_count > 0 && (mean_residual / cap > 0.6 || awkward_current) {
            score += 30.0; // discourage new bin when existing bins are roomy
        } else {
            score -= congestion.min(15.0);
        }
    }

    // Late-stream consolidation: as the stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - residual_frac);

    // Mild preference for fuller bins overall (relative to mean residual).
    score += (mean_residual - pr as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 range, use 10 as safe floor) are wasted.
    if post_residual < 10 {
        // Perfectly tight fit: heavily reward.
        score -= 40.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste * waste;
    }

    // Reward tight fits generally (small post_residual relative to bin_residual).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra bonus if next item fills the bin completely after placement.
        if post_residual - next_item_size == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for lookahead: mild penalty, it's likely dead space.
        score += 5.0;
    }

    // Open-bins pressure: discourage scattering across many bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a moderate base cost so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If nothing else fits, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in stream with many bins, opening new bins is cheaper than fragmenting.
        if progress > 0.5 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual close to item (best-fit core) plus mean-residual coupling.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * diff;
    score -= 0.03 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
