pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // Penalize creating small unusable dead space (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste: mild bonus scaled by fit quality
            let q = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 15.0 * q;
        } else {
            // next item won't fit here: penalize leaving a big but insufficient gap
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // many options: prefer the fullest bin (smallest residual before placement)
        score += (bin_residual as f64) * 0.15;
    }

    // Global state coupling: prefer bins below mean residual when many bins open,
    // to balance residuals and keep larger gaps available.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev;
    }

    // Time horizon: early in stream, be conservative about filling bins (favor new bins
    // for large items to keep flexibility); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0;
    score += (1.0 - progress) * (item_size as f64 / cap) * 6.0;

    // New-bin candidate: only attractive if current item is large and no tight fit exists,
    // or late in stream with many bins nearly full.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 35.0 * (1.0 - tightness) - progress * 20.0
            + if fitting_bins_count == 0 { 50.0 } else { 0.0 };
        score += new_bin_bonus.max(-10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let p = progress;
    score += 20.0 * norm_post * norm_post * (0.5 + 0.5 * p) * cap / 100.0;

    // Reward tight fits more strongly later in the stream.
    score -= (1.0 - norm_post) * (1.0 + 2.0 * p) * 5.0;

    // Penalize dead space that is too small for the smallest possible item.
    if post_residual < next_item_size && next_item_size > 0 {
        score += 8.0 * (1.0 - post / (next_item_size as f64 + 1.0));
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 4.0 * (1.0 - post_residual as f64 / (post_residual as f64 + next_item_size as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + p);
    }

    // Prefer bins with below-mean residual (consolidating space).
    score -= 3.0 * ((mean_residual - bin_residual as f64) / cap);

    // New-bin candidate: penalize opening new bins, less so early or when it's the only option.
    if bin_residual == bin_capacity {
        let base = 25.0 + 20.0 * p;
        let relief = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += base - relief - 10.0 * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    // (capacity fractions / integer-division thresholds).
    let cls = post_residual / 10; // 0..10 harmonic class
    // Dead-space penalty: very small post_residual is fine (near-perfect fit),
    // but mid-range leftovers (20..50) are "awkward" classes.
    match cls {
        0 => score -= 8.0,                       // perfect / near-perfect fit
        1 => score -= 5.0,                       // excellent
        2 => score += 2.0,                       // awkward small leftover
        3 => score += 6.0,                       // awkward
        4 => score += 8.0,                       // worst class (~40-50 leftover)
        5 => score += 4.0,
        6 => score -= 1.0,                       // half-full-ish, still usable
        7 => score -= 2.0,
        8 => score -= 3.0,
        9 => score -= 4.0,                       // mostly empty, flexible
        _ => score -= 6.0,                       // fresh bin class (100)
    }

    // Lookahead coupling: penalize if next item cannot use the leftover class.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item won't fit here regardless; leftover likely wasted
            score += 3.0;
        } else {
            // leftover that exactly chains with next item is valuable
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 6.0;
            } else if chain < 20 {
                score -= 3.0;
            }
            // reward when next item fits snugly into this bin's post-residual
            let fit_frac = next_item_size as f64 / post_residual as f64;
            if fit_frac > 0.8 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if post_residual < 10 {
            score -= 5.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: keep it attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // fragmentation measure: how much mean residual deviates from ideal
        let frag = (mean_residual - 50.0).abs() / 50.0;
        score += 12.0 - 10.0 * frag - 4.0 * progress;
        // never open a new bin for a tiny item when decent bins exist
        if item_size <= 30 && mean_residual > item_size as f64 + 20.0 {
            score += 15.0;
        }
    }

    // Mild preference for filling fuller bins when many bins are open.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 2.0 * fullness * (open_bins_count.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: best-fit style preference for tight fits.
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a
    // meaningful item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small unusable-ish gaps are mildly penalized.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when no open bin fits well. Give the empty bin a neutral-ish
    // baseline plus pressure from open bin count.
    if bin_residual == bin_capacity {
        // New bin starts with a moderate score; it beats only bad fits.
        score = 75.0 + open_bins_count as f64 * 0.5;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
        // Early in the stream, fresh bins are cheap; late, avoid sprawl.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is near the mean (spread waste evenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.5; // good but imperfect chain
        } else {
            // next item won't fit here; penalize leaving a small dead zone
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.6;
        }
    }

    // Penalize large post_residual if it's unusably small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is nearly worthless
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when current item is large
    // and would leave a bad fit elsewhere
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 / bin_capacity as f64;
        score = 110.0 - tight_fit * 60.0;
        if next_item_size > 0 && next_item_size >= post_residual && next_item_size <= bin_residual {
            score -= 20.0; // fresh bin can host the next item too
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize wasted dead space (non-linear: small residuals are much worse).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 40.0 * (1.0 - pr / bin_capacity as f64).powi(3);
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // creates a gap the next item cannot use
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize the new-bin candidate unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        // If current item is large and would leave a big residual anyway, opening is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 50.0;
        }
        // Near end of stream, avoid opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Prefer tighter bins (small residual before placement) slightly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, waste matters more
    let progress_coupling = 1.0 + 0.5 * progress * progress;
    score *= progress_coupling;

    // Tight fit reward: strong non-linear bonus when post_residual is small
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize bins far below mean residual (fragmentation avoidance)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let fit_gap = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize small post_residuals (dead space)
        score += 5.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins mildly, more so early on
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    // Mild penalty for too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does leftover space align
    // with common small-item sizes (capacity fractions)?
    let pr = post_residual;
    if pr > 0 {
        // Perfect "harmonic" leftovers that future small items can fill.
        let mut harmonic_bonus = 0.0;
        for &h in &[10u32, 20, 25, 33, 50, 66] {
            if pr % h == 0 {
                harmonic_bonus += 12.0;
            }
        }
        score -= harmonic_bonus;

        // Dead space penalty: leftovers below the minimum item size are wasted.
        if pr < 10 {
            score += 30.0 + 2.0 * pr as f64;
        } else if pr < 20 {
            score += 8.0;
        }

        // Integer-division threshold: leftover divisible by 25 is a good slot.
        if pr / 25 > 0 && pr % 25 == 0 {
            score -= 10.0;
        }
    } else {
        // Perfect fill is ideal.
        score -= 60.0;
    }

    // Penalize tight fits that leave awkward remainders (modulo classes).
    let m = post_residual % 7;
    score += m as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation).
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 10.0 * (open_bins_count.min(20) as f64).sqrt();

    // Early in the stream, allow opening new bins for big items (flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when item is huge.
        let big_item = item_size >= 60;
        if progress < 0.15 || big_item {
            score -= 18.0 + 10.0 * (1.0 - progress);
        } else {
            score += 12.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already "junk"; using it consolidates waste.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it cannot fit even the smallest plausible item (<= 20),
    // and grows worse the smaller the gap is.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0;
    }

    // Perfect fit bonus: strong reward for zero waste.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Near-perfect fit: reward tiny residuals only if next item could use them.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0; // residual is reusable by lookahead item
    } else if post_residual > 0 && next_item_size > 0 {
        score += 15.0; // residual cannot host next item: mild dead-space penalty
    }

    // Open bins pressure: discourage spreading across many bins when
    // this placement leaves a large residual (fragmentation risk).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (1.0 - progress);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a forced new bin for a poor fit later.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., consuming a large chunk of a fuller bin) is efficient.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit in an open bin,
        // so new bins are opened only when open bins score badly.
        score += 40.0;
        // Late in the stream, be more conservative about opening bins.
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead k=2: reward exact/near-exact match with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Compare against mean residual: prefer filling below-average-residual bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when
    // open bins fit poorly (large post_residual / dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 45.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (wasted capacity grows quadratically).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Reward tight fits: small post residual relative to item size.
    if post_residual > 0 {
        score -= (item_size as f64 / post_residual as f64) * 3.0;
    } else {
        score -= 10.0; // perfect fill
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // If next item would leave big dead space anyway, mild penalty.
            let gap = (next_item_size - post_residual.min(next_item_size)) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Encourage consolidating into fewer bins when many are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Compare against mean residual: bins with residual below mean are "tight",
    // filling them is good; bins above mean have room to spare.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be slightly more willing to open bins (long horizon);
    // late in the stream, prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 20.0 * progress;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress) - 12.0 * norm_pr * (1.0 - progress);

    // Penalize dead space relative to the mean residual across open bins
    score += 0.08 * (pr - mean_residual).abs();

    // Lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        score -= 6.0 * (gap / cap).tanh() * (1.0 - progress);
        if gap < 0.0 {
            score += 0.5 * (-gap);
        }
    }

    // Last-chance bonus: strongly favor using a scarce fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it competitive only for large items
    if bin_residual == bin_capacity {
        score += 30.0 - 0.4 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small remainders in low classes are dead space.
    let pr = post_residual;
    let class = pr / (bin_capacity / 4); // 0..3 integer class
    score += match class {
        0 => 6.0,          // tiny sliver: nearly unusable
        1 => 2.0,
        2 => 0.0,
        _ => -2.0,         // roomy leftover is fine
    };

    // Modulo-10 harmony: residuals divisible by 10 align with typical item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        score -= 2.0;
    } else if next_item_size > 0 && next_item_size > pr && next_item_size <= bin_residual - 0 {
        // next item won't fit here; slight penalty for wasting a big residual
        score += 1.5;
    }

    // Prefer filling bins tightly relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5 * ((post_residual as f64) - mean_residual) / cap;
    }

    // Discourage opening new bins when many bins are open and this is a decent fit.
    if bin_residual < bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = (1.0 - t) * 4.0 + open_bins_count as f64 * 0.3;
        score -= new_bin_penalty * 0.5;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (min item size 1, but practically small gaps) are heavily penalized.
    if post_residual > 0 {
        // dead space in the "unusable" band gets a large multiplicative penalty
        let unusable_threshold = 10.0f64;
        if (post_residual as f64) <= unusable_threshold {
            score += 60.0 * (unusable_threshold - post_residual as f64 + 1.0);
        }
        // mild penalty proportional to wasted fraction of capacity
        score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        score -= 10.0 * (item_size as f64 / (item_size + post_residual) as f64);
    }

    // Open-bin pressure: discourage scattering across many bins when
    // consolidation is possible; encourage new bin only if open bins are crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (below-mean residual means this bin is already tight -> good target).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly into the resulting residual,
    // reward; if next item would be blocked by tiny residual, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // New-bin candidate baseline: empty bin gets a mild handicap so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is heavily penalized).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if post_residual >= next_item_size {
            score -= (30.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here; penalize proportional to wasted potential
            score += diff as f64 * 0.15;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 + 20.0 * pressure - 10.0 * progress;
        // Opening a new bin is bad if the item fits well somewhere already.
        if post_residual == 0 || next_item_size == 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count > 0 {
            // if any existing bin leaves room for next item, discourage new bin
            score += 10.0;
        }
    }

    // Mild penalty for leaving awkward mid-range gaps.
    if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize large dead space, especially dead space below the
    // minimum plausible item size (wasted capacity).
    let dead = post_residual as f64;
    score += dead * dead * 0.02;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= tightness * 30.0;

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // leaving a tiny unusable gap is fine if next item is large
            score -= 5.0;
        } else {
            // gap blocks the next item: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor average slack or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins when open bins are roomy on average.
        score += mean_residual * 0.5;
        // Early on, avoid bin proliferation; later, more willing to open.
        score += (1.0 - progress) * 25.0;
        // Large items justify fresh bins more than small ones.
        score -= item_frac * 30.0;
        // If several bins already fit, discourage opening yet another.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
    } else {
        // Slight preference for filling more-occupied bins.
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
        // Spread load when many bins are open and mean residual is high.
        if mean_residual > (item_size as f64 * 1.5) && open_bins_count > 3 {
            score += 3.0;
        }
    }

    // Late in the stream, consolidate: prefer bins that end closer to full.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: reward tight fits via non-linear decay of post_residual
    let mut score = 40.0 * (norm_post * norm_post * 3.0 + norm_post * 0.5);

    // Polynomial coupling: as stream progresses, small residuals become more costly
    let progress_coupling = progress * (norm_post * norm_post) * 30.0
        + (1.0 - progress) * (norm_post * norm_post * norm_post) * 15.0;
    score += progress_coupling;

    // Perfect-fill bonus (smooth, non-piecewise)
    let fill = (cap - post) / cap;
    score -= 25.0 * fill * fill * fill;

    // Penalize residual that is close to but not enough for the next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt) * (0.5 + 0.5 * progress);
        } else {
            // reward leaving room for the lookahead item (smooth)
            score -= 8.0 * (post / (post + nxt)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Mild pressure against accumulating many open bins late in the stream
    score += (open_bins_count as f64).ln() * 1.5 * (0.3 + 0.7 * progress);

    // Pull toward mean residual: prefer bins whose post-residual stays near average
    score += 3.0 * ((post - mean_residual) / cap).powi(2);

    // New-bin candidate: neutral-ish baseline so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small remainders is costly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Penalize unusable dead space: residual below typical small item size.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Sweet spots: residuals that later items (10..80) can still use well.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 12.0;
    } else if post_residual > 20 && post_residual <= 40 {
        score -= 6.0;
    }

    // Modulo-10 class logic: residuals divisible by 10 align with common item sizes.
    let r10 = post_residual % 10;
    score -= (10 - r10) as f64 * 0.8;

    // Integer division thresholds on post_residual: quarter classes.
    let quarter = post_residual / 25; // 0..4
    score -= quarter as f64 * 3.0;

    // Lookahead harmony: if next item fits the post residual exactly-ish, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) % 10;
        score -= 8.0 - slack as f64 * 0.5;
    }
    // If next item will NOT fit here, mild penalty for blocking the stream.
    if next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tight fit reward: near-exact packing.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= tightness * 10.0;

    // Progress-aware: early in stream, tolerate new bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        let mut nb = 55.0;
        nb -= progress * 20.0;
        nb += open_bins_count as f64 * 1.5;
        nb += (mean_residual / cap) * 15.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            nb += 30.0;
        }
        score = score.max(nb);
        score = nb + score * 0.0; // new bin scored purely by its own cost
    } else {
        // Existing bin: nudge toward consolidation when mean residual is high.
        score += (mean_residual - frac * cap) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space, nothing can ever fill it
    } else if post_residual >= 10 && post_residual <= 25 {
        // gap only usable by small items; mild penalty scaled by gap smallness
        score += 0.6 * (25.0 - post_residual as f64);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if item_size >= bin_residual {
        // cannot happen, but guard
        score += 100.0;
    }

    // Tightness bonus: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage proliferation unless fit is great.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual equals capacity - item
        score -= 12.0;
        // if current bin would leave a bad gap, opening fresh is better
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // next item could still use this bin; mild reward
        score -= 3.0;
    }

    // Prefer bins whose residual is below average (consolidate fullness).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect/near-perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 30.0;
        } else if diff <= 5 {
            score -= 15.0;
        } else {
            score += diff as f64 * 0.3;
        }
        // Next item too big for this residual: residual likely wasted, penalize.
        if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer keeping many small-residual bins consolidated; penalize opening new bins early.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        score += 10.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Late in the stream, tighten up: avoid leaving many tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (items >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, encouraging diversity
        score += 2.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 4.0;
        }
        // reward leaving exactly room for the next item (perfect chaining)
        if post_residual == next_item_size {
            score -= 14.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (consolidate space)
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Progress-based modulation: late in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // When many bins are open, discourage spreading into yet another bin
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless item is large relative to capacity
        // or open bins are already crowded
        let crowd = open_bins_count as f64;
        let big_item = (item_size as f64) / (bin_capacity as f64);
        score += 8.0 + 3.0 * crowd.sqrt() - 25.0 * big_item;
        // if next item is large and nothing may fit it later, opening fresh bin is ok
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Small penalty proportional to wasted fraction of the bin
    score += 0.05 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on post residual (dead space), steeper late in stream
    let mut score = post * (1.0 + 1.5 * progress) + 40.0 * norm_post * norm_post;

    // Reward tight fits: small post_residual relative to item size
    let tightness = post / (item_size as f64 + 1.0);
    score -= 25.0 / (1.0 + tightness * tightness);

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish score; penalize if many open bins or item fits well elsewhere
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) + 5.0 * open_bins_count as f64;
        // If next item could pair with current item in this fresh bin, encourage opening
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        // Late in stream, prefer filling existing bins
        score += 20.0 * progress * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 / (1.0 + slack as f64);
    }

    // Mild coupling with mean residual: prefer bins deviating from mean (diversify residual sizes)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Many open bins: discourage spreading, favor consolidation
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic class reward: residuals divisible by common item sizes (10..=40)
    // are more likely to be filled by future items.
    let mut harmonic_bonus = 0.0;
    for d in [10u32, 20, 25, 40, 50].iter() {
        if pr % d == 0 && pr > 0 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Dead-space penalty: small unusable leftovers (1..=9)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Fractional capacity coupling: prefer bins whose post_residual is a
    // "nice" fraction of capacity (quarter / half)
    let frac = pr as f64 / cap;
    if (frac - 0.25).abs() < 0.001 || (frac - 0.5).abs() < 0.001 {
        score -= 8.0;
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0 + (pr - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > pr {
        // next item won't fit here; penalize proportionally to tightness
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless fit is poor, but keep it competitive.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.2;
    }

    // Late in stream: consolidate, penalize spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - mean_residual / cap.max(1.0)) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than linear.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean-residual coupling: a bin far below mean residual is a poor filler choice.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    // Slight bias toward filling fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate: keep it moderately attractive only when open bins are scarce.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // chain completion: ideal
        } else if post_residual >= next_item_size {
            // Next item fits; prefer small leftover after that hypothetical placement.
            let post2 = post_residual - next_item_size;
            score -= 12.0;
            score += post2 as f64 * 0.45;
        } else {
            // Next item won't fit: penalize dead space beyond what it costs anyway.
            score += 6.0;
        }
    } else {
        // Last item: any placement is fine, mild preference for tight fit.
        score -= 5.0;
    }

    // Relative residual coupling: bins with residual near mean are "typical";
    // avoid leaving much more dead space than the average open bin.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.10; // slight reward for tighter-than-average bins
    }

    // Last-chance bonus: if this is the only bin that fits, opening a new bin
    // is costly, so strongly prefer using it (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; relax if many open bins are fragmented.
        let mut newbin = 20.0;
        if mean_residual < 25.0 {
            newbin -= 18.0; // open bins are nearly full -> new bin is good
        }
        if fitting_bins_count == 0 {
            newbin -= 30.0;
        }
        score += newbin;
    }

    // Tight-fit reward: small post residual relative to item size.
    score -= (item_size as f64) / (bin_residual as f64).max(1.0) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that can never fit even the smallest plausible item.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual > 60 {
        score += 15.0; // leaving a huge unusable gap
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward if next item fits nearly perfectly after this one
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // this placement strands the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins below mean residual (fill emptier-ish bins to balance).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Time horizon: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: usually bad early, only acceptable for very poor fits.
        score += 20.0 + 30.0 * (1.0 - progress);
        if post_residual > 50 && fitting_bins_count <= 2 {
            score -= 35.0; // allow fresh bin when fit would be terrible
        }
    } else {
        // Late stream: extra pressure to close out existing bins tightly.
        score -= 15.0 * progress * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual reshaped by stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate slack.
    let shape = 1.0 + 0.6 * progress - 0.8 * progress * progress;
    score *= shape.max(0.3);

    // Penalize large dead space super-linearly, scaled by fraction of capacity.
    let frac = pr / cap;
    score += 12.0 * frac * frac * cap * (0.5 + 0.5 * progress);

    // Reward near-perfect fits strongly (smooth, non-piecewise).
    score -= 20.0 * (-6.0 * frac).exp();

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (-10.0 * slack).exp();
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mildly discourage spreading across many open bins when residuals are large.
    let mr = mean_residual / cap;
    score += 2.0 * (open_bins_count as f64).ln() * mr;

    // New-bin candidate: make empty bins moderately attractive only for poor fits.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Residuals that are common divisor multiples (10, 20, 25, 50) pair well with
    // typical item sizes; odd/prime-like leftovers are dead space.
    let r = post_residual;
    let harmonic: f64 = if r == 0 {
        -30.0 // perfect fit: strongly reward
    } else if r % 50 == 0 {
        -8.0
    } else if r % 25 == 0 {
        -5.0
    } else if r % 10 == 0 {
        -3.0
    } else if r % 5 == 0 {
        -1.0
    } else {
        4.0 // non-multiple: penalize awkward leftover
    };
    score += harmonic;

    // Dead-space threshold: leftovers below the smallest useful pairing size.
    if r > 0 && r < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0; // perfect chained fit
        } else if next_item_size < r {
            let slack = r - next_item_size;
            // reward tight fits, penalize large slack after next item
            score += (slack as f64) * 0.4;
            // harmonic bonus if the chained leftover is a good class
            if slack % 10 == 0 { score -= 2.0; }
        } else {
            // next item cannot use this bin's leftover; leftover risk grows
            score += (next_item_size - r) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate logic: an empty bin should only win when this item is
    // large and open bins are crowded (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // penalize new bins early, less when bins are nearly full on average
        score += 18.0 - 10.0 * mean_residual / bin_capacity as f64 - 6.0 * progress
                 - 2.0 * crowded;
        // very large items prefer fresh bins
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for filling bins that are already more than half used.
    if bin_residual < bin_capacity / 2 {
        score -= 3.0;
    }

    // Small global pressure: fewer open bins relative to stream -> consolidate.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual < item_size.min(80) {
        // Gap too small even for the smallest plausible next item.
        score += 25.0;
    }

    // Tight fit reward: closeness of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over spreading.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the gap -> mild penalty if gap is tiny.
        if post_residual < next_item_size && post_residual < 20 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: only attractive when no good existing fit
    // exists (poor fits elsewhere) or bins are getting very full on average.
    if bin_residual == bin_capacity {
        let poor_existing = mean_residual < item_size as f64;
        if poor_existing || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // Discourage opening bins when existing bins fit fine.
            score += 15.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Mild progression coupling: later in stream, prefer filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // Exact match is perfect chaining.
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space: penalize dead space, worse for tiny leftovers.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 15.0; // nearly unusable sliver
        } else {
            score += 0.35 * (dead - next_item_size as f64).abs();
        }
    }

    // Compare residual against the mean residual of open bins.
    // Bins with residual below mean are "wasted" if we leave them; prefer filling below-mean bins.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, consolidate: prefer existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins are open.
        score += 12.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
        // But if next item is large and no open bin chains well, a fresh bin is less bad.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let fit_ratio = post_residual as f64 / cap;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // post-residual unusable for next item: mild penalty
            score += 12.0;
        }
    }

    // New-bin candidate handling: make empty bin attractive only when
    // no open bin fits well or many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // Prefer new bin when mean residual is large but fragmented,
        // or late in the stream with many open bins.
        score += 25.0 - progress * 15.0 + congestion * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Favor already-open bins mildly to keep bin count low.
        score -= 5.0;
    }

    // Global balance: prefer bins whose residual is below mean (consolidate).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 10.0;

    // Time horizon: early in stream, be pickier about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += fit_ratio * (1.0 - progress) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 15.0;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let gap = norm_pr - norm_next;
    if next_item_size > 0 {
        let waste = gap.max(0.0) * gap.max(0.0);
        score += 20.0 * waste * (0.5 + progress);
        // Bonus if post residual still fits next item
        let fits = (norm_next - norm_pr).max(0.0);
        score -= 10.0 * fits * (1.0 - fits);
    }

    // Last-chance bin bonus: avoid opening new bins when few fit
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * 0.5);
    }

    // Mild penalty for proliferation of open bins with large mean residual
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 2.0 * bin_pressure * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize unless item is large or bin would be near-empty
    if bin_residual == bin_capacity {
        let emptiness = 1.0 - norm_item;
        score += 8.0 + 30.0 * emptiness * (1.0 - progress);
    }

    // Small smooth jitter-free regularizer on item size vs residual
    score += 5.0 * (norm_item * (1.0 - norm_item)) * (norm_pr + 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of the leftover space (decile buckets)
    let class = post_residual / 10;

    // Reward tight fits: post_residual near 0 is good
    score -= 40.0 * ((bin_capacity - post_residual) as f64 / cap);

    // Dead-space penalty: residuals in the "awkward" band (1..=9) are hard to reuse
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }
    // Harmonic classes: residuals divisible by 10 are more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Odd classes leave less flexible space
    if class % 2 == 1 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slightly penalize wasting this bin's future
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large or nothing fits well
    if is_new_bin {
        score += 35.0;
        if item_size >= 50 {
            score -= 30.0; // big items justify fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        // as stream progresses, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // favor bins whose residual is far above mean (use the loosest fitting bin)
        score -= 5.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    // Many open bins: encourage filling existing ones
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps that cannot fit even the smallest plausible next item are risky.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; add pressure proportional to open_bins_count.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * next_item_size as f64;
    }
    // If next item cannot fit in post_residual but could fit in a fresh bin,
    // penalize slightly less when post_residual is large.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make opening a fresh bin moderately attractive only
    // when no open bin gives a decent fit; base penalty keeps it conservative.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, opening a new bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 500.0;
        } else if post_residual as f64 >= next {
            // next item fits: bonus scaled by how snugly
            let snug = 1.0 - (post_residual as f64 - next) / bin_capacity as f64;
            score -= 100.0 * snug;
        } else {
            // next item won't fit here: penalize leaving a gap that blocks it
            let gap = post_residual as f64;
            if gap < next * 0.5 {
                score += 60.0 * (next - gap) / 100.0;
            }
        }
    } else {
        // Last item: minimize waste aggressively.
        score -= 200.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are better targets.
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // Penalize opening a new bin when plenty of open bins exist and item is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64 / (1.0 + progress)).min(10.0);
        score += 120.0 + 15.0 * pressure;
        // But if item is large relative to capacity, opening a fresh bin is fine.
        score -= item_size as f64 * 0.8;
        // If next item is large and current bin is fresh, opening new bin is good.
        if next_item_size >= 50 {
            score -= 150.0;
        }
    }

    // Mild penalty for creating mid-range dead space that nothing will fill.
    if post_residual > 10 && post_residual < 30 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 4.0; // tiny unusable slivers
        } else {
            score -= dead * 0.3; // larger residual is reusable
        }
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward heavily
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 20.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // Prefer filling bins with low residual relative to mean (consolidate)
    score += (mean_residual - post_residual as f64) * 0.2;

    // Time horizon: early in stream, be pickier (favor tight fits more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.3 * progress;

    // Discourage spreading across many bins when many are open
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it slightly unattractive unless nothing else works
    if bin_residual == bin_capacity {
        score += 15.0 + fit_ratio * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and fill ratio
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Non-linear polynomial coupling: reward high fill non-linearly
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Penalize dead space that is too small to be useful (smoothly, via quadratic)
    let dead = pr_norm * pr_norm;
    score += 25.0 * dead * (1.0 - dead);

    // Tight-fit reward: item_size close to bin_residual (smooth interaction)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio * (1.0 - fit_ratio);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        let slack = (pr - next_item_size as f64).abs();
        if next_fits {
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Prefer spreading across bins when many are open with large mean residual
    let mean_norm = mean_residual / cap;
    score += 10.0 * mean_norm * mean_norm * progress;

    // Mild pressure against opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 * (1.0 - progress) + 4.0 * mean_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (or small classes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that fall into "useful" harmonic classes.
    // Class A: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space: too small for any item (min size 1..100 unknown, but
        // small residuals are weak) -> penalize.
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10, 20, 25, 50
    // are "harmonic" with typical capacity fractions.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer division thresholds: residual >= next item means the bin
    // remains usable for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 8.0;
            // Extra reward if post_residual is an exact harmonic multiple
            // of the next item size (perfect future fit).
            if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot fit here; mild penalty scaled by gap.
            score += (next_item_size as f64 - pr).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a baseline offset so it
    // is chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (better fill).
    score += (mean_residual - pr).clamp(-30.0, 30.0) * 0.3;

    // Slight preference for fuller bins relative to capacity fraction.
    score += (1.0 - (bin_residual as f64) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are small but nonzero are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is excellent
    } else {
        // Larger leftovers are more reusable; soften the linear penalty.
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Reward using bins that are already tight (low residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(15.0);
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless current fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear penalty on waste
    score += (post_residual as f64).powi(2) * 0.01;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let gap = post_residual as f64 - next;
            // Perfect chain: post_residual == next_item_size -> strong reward
            score -= 30.0 * (-gap / 8.0).exp();
        } else {
            // Next item cannot fit here; penalize proportional to shortfall
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or no good fit
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 35.0 * fill_ratio;
        if next_item_size > 0 && (bin_residual as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Last chance: strongly favor using this bin if it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward if next item exactly fills remaining space.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Dead space for the next item: penalize proportionally.
            let waste = post_residual as f64 - next_item_size as f64;
            score += waste * 0.15;
        }
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only late in stream or when many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        if item_size <= 10 {
            score += 20.0; // tiny items don't justify a fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins below mean residual (balance residual spread).
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
    }

    // Penalize leaving residuals that are hard to fill (small odd gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in low residues is worse.
    let r = post_residual;
    if r == 0 {
        score -= 50.0; // perfect fit
    } else {
        // penalty grows when residual falls into "unusable" classes
        let class = r % 10;
        score += (10 - class) as f64 * 0.5; // prefer residuals that are multiples of 10
        if r < 10 {
            score += 30.0; // tiny dead space, nearly wasted bin
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if next_item_size <= r {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty for leaving large gap
            score += (next_item_size - r) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residual below mean (consolidate small gaps)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Modulo harmony: residual that is multiple of common item sizes (5,10,20,25)
    if r % 5 == 0 { score -= 2.0; }
    if r % 20 == 0 { score -= 2.0; }
    if r % 25 == 0 { score -= 1.0; }

    // Integer-division threshold: bins whose remaining capacity class matches item class
    let item_class = item_size / 20;
    let res_class = bin_residual / 20;
    if item_class == res_class { score -= 3.0; }

    // New-bin candidate: only attractive when no good fits exist (late stream or crowded)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score += 15.0;                 // base cost of opening a new bin
        score -= progress * 20.0;      // late in stream, consolidation matters less
        score -= (crowding - 1.0) * 5.0; // many bins but few fitting -> open new
        if fitting_bins_count <= 1 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=9) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Medium gaps (10..=19) are only usable by tiny items; moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // If the next item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in the residual, the gap risks becoming dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate: make it attractive only when the current bin would leave
    // a large unusable residual or the item barely fits.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if item_size > 0 && post_residual < 10 {
            score -= 50.0; // opening a fresh bin for a big item is fine
        } else if tightness < 0.35 {
            score += 20.0; // don't open bins for small items
        } else {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score -= (bin_residual - item_size) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fit / near-perfect fit (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // 2-step lookahead: reward if the NEXT item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportional to how snugly it fits afterwards.
            let post2 = post_residual - next_item_size;
            if post2 <= 2 {
                score -= 500.0;
            } else {
                score -= 100.0 / (post2 as f64);
            }
        } else {
            // Next item cannot fit here: penalize leaving a gap smaller than next item.
            score += 50.0 + (post_residual as f64) * 0.5;
        }
    }

    // Penalize large leftover residual that is unlikely to be usable,
    // especially when it deviates above the mean residual (fragmenting bins).
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - res) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 250.0;
        // More attractive late in the stream (fewer future chances to reuse bins).
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 150.0 * progress;
        }
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 200.0;
        }
        // If the next item is large relative to residual, a fresh bin helps it.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0;
        }
    }

    // Mild preference for tighter existing bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual dominates).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that likely becomes unusable: small residuals that
    // cannot host a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted lookahead.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Encourage consolidation when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Prefer bins with below-average residual (fill emptier bins less, keep
    // large residual bins flexible) — mild coupling to global state.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, tighten up and avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * fit_ratio;

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 30.0;
        // Late in stream: new bins are more expensive.
        score += 20.0 * progress;
        // If many bins are open already, discourage proliferation.
        score += 1.5 * open_bins_count as f64;
        // But if it's the last item, a new bin wastes almost a whole bin.
        if next_item_size == 0 {
            score += 40.0;
        }
    }

    // Prefer using bins whose residual is close to item_size (perfect-ish fit).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: prefer small post residual, with smooth non-linear amplification
    // (quadratic + cubic coupling) so tiny leftovers are strongly favored.
    let mut score = pr + 0.35 * (pr * pr) / cap + 0.15 * (pr * pr * pr) / (cap * cap);

    // Smooth interaction: normalized post residual vs stream progress.
    let prn = pr / cap;
    score += 12.0 * prn * prn * (0.5 + progress);

    // Reward filling a bin deeply (large item relative to residual).
    let fill = it / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Lookahead: penalize if post residual can't fit the next item (dead space),
    // but reward if it fits exactly-ish.
    if nx > 0.0 {
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - progress * 0.5);
        } else {
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap * (1.0 + progress);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty relative to mean residual: avoid scattering space unevenly.
    score += 0.08 * (pr - mean_residual).abs();

    // New-bin candidate: smooth adaptive penalty; early on opening bins is cheap,
    // later it is expensive, with smooth dependence on open_bins_count.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let new_bin_pen = 20.0 + 30.0 * progress + 2.0 * open_f.sqrt() * 10.0 * progress;
        // If the item is huge and nothing open fits well, allow opening.
        let tightness = 1.0 - (it / cap);
        score += new_bin_pen * (0.4 + 0.6 * tightness);
        // If this is the only option, soften the penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter / eighth / sixteenth classes of capacity
    let q = item_size / (bin_capacity / 4);          // 0..3 quarter class
    let h = item_size / (bin_capacity / 8);          // 0..7 eighth class
    let post_q = post_residual / (bin_capacity / 8); // eighth class of post residual

    // Reward tight fits: post_residual in a small harmonic class
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_q == 0 {
        score -= 12.0; // near-perfect fit (< 1/8 capacity dead space)
    } else if post_q == 1 {
        score -= 4.0;
    }

    // Penalize dead space that no future item can plausibly fill.
    // Items are >= 1, but typical useful chunks are >= 10; dead space below the
    // smallest plausible item is pure waste.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 25.0;
    }

    // Harmonic complementarity: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward when the leftover still accommodates the lookahead,
            // scaled by how tight the chain is
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
        } else {
            // lookahead won't fit here: mild penalty, stronger if this was the only fitting bin
            if fitting_bins_count == 1 {
                score += 8.0;
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual,
    // but sometimes opening fresh is better than fragmenting a semi-full bin.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted when existing bins are crowded
        // (mean residual low) or many bins are already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score = score.max(0.0) + 60.0 - crowding * 25.0 - progress * 10.0
            - (open_bins_count as f64 * 0.5);
        // If no open bin fits at all (fitting_bins_count reflects only this new bin),
        // the new bin must be used.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Modulo tie-breaker on post_residual to spread placements across
    // harmonic residue classes, favoring residues that combine well (multiples of 4/8).
    let r = post_residual % 8;
    score += match r {
        0 => -2.0,
        4 => -1.0,
        _ => 0.5 * (r as f64),
    };

    // Large-item harmonic class: big items (>= 3/4 capacity) should go into
    // the emptiest available bins to avoid stranding small leftovers elsewhere.
    if h >= 6 {
        score += (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small positive gaps are the worst outcome.
    // Penalize gaps that are unusable for typical items (below ~min item size),
    // with a super-linear blowup as the gap shrinks toward zero.
    if post_residual > 0 {
        let gap = post_residual as f64;
        let min_item = 1.0f64;
        if gap < 20.0 {
            // dead-space zone: the smaller the gap, the harsher the penalty
            score += (20.0 - gap) * (20.0 - gap) * 0.35;
        }
        // exact fit is gold
        if gap <= min_item {
            score -= 60.0;
        }
    }

    // Reward filling bins that are relatively full (small residual before placement).
    let pre_fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= pre_fill_ratio * 25.0;

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // strongly reward this placement (chains items nicely).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // placement leaves a gap the next item cannot use -> extra penalty
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; when few bins are open, allow more spread.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin — finishing it off is good (reduces fragmentation).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin has full residual. It should only
    // win when no open bin offers a decent fit — i.e., when the best use of an
    // open bin would leave heavy dead space. Give the empty bin a moderate
    // baseline so tight fits in open bins beat it, but dead-space penalties
    // on open bins let it win.
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in the stream or when next item is large, a fresh bin is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        if next_item_size > 60 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            score -= 60.0; // perfect two-step chain
        } else if post > next {
            // slack left over after next item fits: penalize proportionally to waste
            score -= 25.0 - (post - next).min(50.0) * 0.3;
        } else {
            // next item cannot follow: penalize dead space severity
            score += (next - post).min(60.0) * 0.8;
        }
    } else {
        // last item: just minimize post_residual
        score -= 10.0;
    }

    // Reward tight fits relative to mean residual of open bins
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 0.4;
    } else {
        score += (post_f - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score = post_f + 45.0;
        if next_item_size > 0 {
            let next = next_item_size as f64;
            if post_f == next {
                score -= 55.0; // fresh bin chains perfectly with next item
            } else if post_f < next {
                score += (next - post_f) * 0.8;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin can fit: must open new bin
        }
    }

    // Late-stream urgency: consolidate into existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= progress * 8.0;
    }

    // Mild penalty for leaving tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear coupling: quadratic penalty on post_residual scaled by capacity
    let x = pr / cap;
    score += 12.0 * x * (1.0 - x) * (1.0 - progress);

    // Penalize unusable dead space (post_residual smaller than any possible item)
    let dead = (10.0f64 - pr).max(0.0);
    score += dead * dead * 0.08;

    // Reward tight fits that leave room for the lookahead item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New empty bin candidate: penalize mildly unless current fit is poor
    if bin_residual == bin_capacity {
        let waste = pr / cap;
        score += 8.0 * (1.0 - waste) - 20.0 * (1.0 - waste) * (1.0 - waste);
    }

    // Slight preference for bins deviating from mean residual (balance fragmentation)
    score -= 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space classes.
    // Residuals that are "harmonically useful" (small, or common divisors like 10/20/25/50)
    // are less penalized than awkward residuals.
    let pr = post_residual;
    let awkward = if pr == 0 {
        -3.0 // perfect fit, strongly rewarded
    } else if pr <= 10 {
        0.0
    } else if pr % 10 == 0 {
        2.0 // round residual, still reusable by 10-multiples
    } else if pr % 5 == 0 {
        4.0
    } else if pr < 20 {
        6.0
    } else {
        8.0 // large awkward leftover
    };
    score += awkward;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill_frac;

    // Penalize leaving a residual that no plausible next item can use.
    if next_item_size > 0 {
        if next_item_size > pr && pr > 0 {
            // this bin becomes dead for the next item
            score += 5.0 * (pr as f64 / bin_capacity as f64);
        } else if next_item_size > 0 && pr >= next_item_size {
            // bonus if this bin can also host the lookahead item
            let left2 = pr - next_item_size;
            score -= 2.0 * (1.0 - left2 as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: opening a bin is discouraged unless the item
    // is large or all existing fits are terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 12.0 + 10.0 * progress;
        // big items justify fresh bins
        new_bin_cost -= 0.08 * item_size as f64;
        // many open bins with high mean residual => prefer reusing
        new_bin_cost += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += new_bin_cost;
    } else {
        // mild preference for bins whose residual is closest above the item
        score += 0.02 * (bin_residual as f64 - item_size as f64);
        // spread load when many bins are open and mean residual is high
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 0.5;
        }
    }

    // Modulo-class coupling between item and residual (harmonic compatibility).
    if pr > 0 {
        let g = gcd(item_size, pr);
        if g >= 10 {
            score -= 1.5; // item and leftover share a useful divisor
        }
    }

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is above the mean (keep big holes for big future items).
    if (bin_residual as f64) < mean_residual {
        score += 6.0;
    } else {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate calibration: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual < 10 || fill_ratio < 0.35 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits (item + next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            score -= 10.0 * (post_residual as f64 / bin_capacity as f64) * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow into this bin: penalize leftover dead space
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Compare against mean residual across open bins: prefer bins that
    // converge the ensemble toward uniform low residuals.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    // Late-stream conservatism: tighten toward end of stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows quadratically as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is wasted space
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: penalize large leftovers.
            score += 0.08 * post_residual as f64;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;
    if bin_residual == bin_capacity {
        // New-bin candidate: make it unattractive early, tolerable when open bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 10.0 + 14.0 * (1.0 - progress) - 0.05 * open_bins_count as f64 - 0.02 * fragmentation;
    }

    // Mild penalty when this bin deviates from the mean residual (keeps bin states homogeneous).
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;

    let mut score = pr * (1.0 + 0.5 * poly);

    // Penalize near-empty fits (large dead space) more aggressively late in stream
    score += 20.0 * (norm_pr - norm_pr * norm_pr) * (0.5 + progress);

    // Reward tight fits: low post_residual gets discount
    score -= 15.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 10.0 * (1.0 - ((pr - ni) / cap).abs());
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Encourage using bins with above-average residual (reduce fragmentation)
    score -= 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: neutral-to-slightly-high default so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but zero post_residual is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic penalty on leftover: dead space that nothing (>=10) can use is bad.
        let dead = post_residual < 10;
        if dead {
            score += 500.0; // unusable sliver
        }
        // Non-linear: penalize mid-range leftovers less than awkward ones
        score += (post_residual as f64).powf(1.3) * 0.05;
    }

    // Harmonic class of post_residual modulo capacity fractions (capacity = 100)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual % quarter == 0 {
        score -= 8.0; // leftover aligned to quarter classes is reusable
    }
    if post_residual >= half {
        score -= 5.0; // large leftover keeps flexibility
    } else if post_residual < item_size.min(20) && post_residual > 0 {
        score += 12.0; // leftover too small for typical next items
    }

    // Lookahead: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0; // chains nicely
            // exact chain to zero is excellent
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else if next_item_size <= bin_residual {
            // next item could have gone here instead; slight penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets baseline attractiveness only when
    // current open bins are nearly full or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is fine early or when mean residual is small.
        score = 40.0 + mean_residual * 0.4 - progress * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Don't open a new bin if an existing bin would be left with a perfect-fit class
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0;
        }
    }

    // Slight preference for fuller bins among open ones (relative to mean residual)
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 25 {
        score += 0.5 * (post_residual as f64 - 10.0);
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: slightly penalize opening a new bin unless residual is large.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if all open bins would leave tiny dead space, opening new bin is fine.
        if post_residual >= 20 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose post residual is near mean (balanced packing).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty
    // on wasted space to discourage dead zones.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            // Perfect chain: post_residual exactly fits next item -> strong reward.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the shortfall,
            // but only mildly so we don't always reject such bins.
            let shortfall = next - post_residual as f64;
            score += 0.05 * shortfall;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 6.0;
    }

    // Reward matching relative to mean residual: bins below mean residual are
    // "tight" bins; filling them keeps the bin set balanced.
    let diff = post_residual as f64 - mean_residual;
    score += 0.10 * diff;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the fit is good (large post_residual means item is small relative to
    // the bin), otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If many bins are open, discourage spreading further unless fit is very tight.
        if open_bins_count > 4 {
            score += 2.0 * (open_bins_count as f64).ln();
        }
        // If the next item would also fit comfortably in a fresh bin, slight bonus.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 3.0;
        }
    }

    // Mild early-stream exploration: early on, allow opening bins a bit more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Lookahead: penalize if next item could have fit better in this bin's post_residual
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            // next item fits here later — good, slight reward
            score -= 2.0;
        } else {
            // next item won't fit in leftover; penalize proportional to wasted potential
            let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 4.0 * gap;
        }
    } else {
        // last item: just minimize post residual
        score -= 1.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Many fitting bins: mild penalty to avoid scattering across many bins
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (larger post_residual ok);
    // late in stream, prefer filling bins completely
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * tightness;

    // Penalize bins whose residual deviates far from the mean residual (keep balance),
    // unless it's a fresh bin
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.02 * dev;
    } else {
        // New-bin candidate: penalize slightly unless open bins are crowded or fit is poor
        let crowding = open_bins_count as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        score += 1.5;
        if poor_fit && crowding > 2.0 {
            score -= 2.5;
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Penalize very small dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, keep bins flexible (penalize very small residuals more);
    // later, tolerate tight packing more aggressively.
    let flex = 0.5 * (1.0 - progress);
    score += flex * cap * norm_pr * (1.0 - norm_pr) * 4.0 * norm_pr;

    // Reward using the last fitting bin (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Penalize leaving dead space that no typical item can use,
    // coupled smoothly with mean residual state.
    let dead = (norm_pr - (norm_pr * norm_pr)) * cap;
    score += 0.15 * dead * (mean_residual / cap).max(0.0).min(2.0);

    // Lookahead: reward residual that still fits the next item,
    // penalize residual that would strand the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure against bin proliferation early in the stream
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when the
    // current bin would be left with an awkward residual.
    if bin_residual == bin_capacity {
        let awkwardness = 1.0 - ((pr / cap) * 2.0).min(1.0);
        score = cap * 0.6 + 20.0 * awkwardness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let post = post_residual as u32;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post % 10 == 0 {
        score -= 8.0; // clean divisible residue, likely reusable
    } else if post < 10 {
        score += 25.0; // dead space below min item size
    }

    // Modulo-class coupling between post_residual and next_item_size
    if next_item_size > 0 {
        let n = next_item_size;
        if n == post {
            score -= 40.0; // lookahead exactly fills this bin
        } else if n < post && (post - n) % 10 == 0 {
            score -= 15.0; // chain of divisible fits
        } else if n <= post {
            score -= 5.0;
        } else {
            score += 12.0; // next item cannot use this bin's residue
        }
        // harmonic residue class match: both in same decade class
        if (post / 10) == (n / 10) && post >= n {
            score -= 6.0;
        }
    }

    // Penalize spreading across many bins; reward consolidation
    if fitting_bins_count <= 1 {
        score -= 30.0; // last-chance bin: strongly prefer using it
    }

    // Prefer fuller bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space
    if bin_residual == bin_capacity {
        let waste_if_used = (post_residual as f64) / cap;
        score += 20.0 - 20.0 * waste_if_used;
        if post_residual > 0 && post_residual < 10 {
            score += 30.0; // never open a bin for a near-full fit
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open new bin
        }
    }

    // Mild stream-phase damping to stabilize early decisions
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - phase);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 25.0; // perfect or near-perfect fill, reward strongly
    } else if post_residual <= 20 {
        // Small gaps are likely unusable dead space -> penalize heavily.
        score += 40.0;
    } else if post_residual <= 40 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual is barely larger than the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 20.0 * (1.0 - tightness / bin_capacity as f64);

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing bins over new ones.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate: only attractive when item fits badly everywhere else.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Lookahead synergy: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space for the known next item
        score += 5.0;
    }

    // Slight preference early in stream to keep bins consolidated.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but dampen by capacity scale.
    score = post_residual as f64 - 0.5 * (bin_capacity as f64);

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining bonus: next item exactly fills the remainder.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * slack;
            if post_residual == next_item_size {
                score -= 25.0; // exact 2-item fill
            }
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious, use them well.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residuals
    // everywhere are large and the fit here would be terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If current item is large and would leave big dead space anyway,
        // opening fresh is fine: reduce the penalty.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 45.0 * fill_ratio;
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 20.0; // pair won't fit together anywhere; fresh bin OK
        }
    }

    // Late in the stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never be used by the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the known next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
            // If next item is small, leftover might still be usable later; soften.
            if next_item_size <= 15 {
                score -= 0.25 * waste;
            }
        } else {
            // Reward bins that can also host the lookahead item (chaining).
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 0.55 * chain_fit.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty to preserve choice diversity among many fitting bins.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins with residual above the mean (keep small-residual bins for small items).
    let delta_mean = bin_residual as f64 - mean_residual;
    score -= 0.18 * delta_mean;

    // Time horizon: early in the stream, be more selective (favor tight fits);
    // late in the stream, just close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * tightness;

    // When many bins are open, consolidate; when few, allow new bins more freely.
    let open_pressure = open_bins_count as f64;
    score += 0.35 * (open_pressure.ln() + 1.0);

    // New-bin candidate handling: a fresh bin is attractive only if the item is large
    // and the fit in existing bins would leave big unusable gaps.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            // Large item in a fresh bin is efficient.
            score -= 8.0 + 10.0 * fill_ratio;
        } else {
            // Opening a new bin for a small item wastes capacity.
            score += 25.0 * (1.0 - fill_ratio);
        }
        // If a last-chance bin exists, discourage the new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // smooth non-linear core: quadratic + quartic shaping of post residual
    let mut score = pr as f64;
    score += 8.0 * fit * fit * (1.0 - fit) * cap;      // penalize mid-range waste smoothly
    score -= 12.0 * fit * (1.0 - fit) * (1.0 - fit) * cap; // reward near-perfect fills

    // stream-progress coupling: waste tolerance shrinks as stream advances
    let urgency = progress * progress;
    score += urgency * pr * (1.0 - fit);

    // dead-space penalty if next item cannot use the remainder
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 6.0 * (1.0 - pr / ns) * (1.0 + urgency);
        } else {
            score -= 4.0 * (pr - ns) / cap;
        }
    }

    // last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - fit);
    }

    // slight preference for bins below mean residual (balancing)
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual belongs to a
    // "composable" class (can still host common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: leftovers too small for the smallest plausible item
    // (<= 10) are nearly useless unless the fit was exact.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic class reward: residuals that are multiples of common item
    // granularity (10/20/25/50) remain reusable by future items.
    if post_residual % 10 == 0 { score -= 12.0; }
    if post_residual % 20 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 5.0; }
    if post_residual % 50 == 0 { score -= 8.0; }

    // Next-item lookahead: reward residuals that can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // leftover cannot host next item: mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // If next item would exactly fill current bin if we place current item elsewhere,
        // prefer keeping this bin's residual aligned with next item size.
        if bin_residual == next_item_size && post_residual != 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 && post_residual > 0 { score += 20.0; }
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 15.0 * (1.0 - progress);
        // But if all open bins would leave tiny dead space, new bin is attractive.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity as u32 {
            score -= 10.0; // new bin can host a clean pair
        }
    }

    // Prefer tighter bins: relative fill fraction bonus (harmonic fraction of capacity).
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Mean-residual coupling: bins far below mean residual are already tight;
    // prefer them slightly to consolidate waste.
    score += (pr - mean_residual) * 0.15;

    // Integer-division threshold: bucket the residual into capacity eighths;
    // favor bins whose leftover lands in the lowest usable buckets.
    let bucket = post_residual / 13;
    score += bucket as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: small gaps that few items can fill.
    if post_residual > 0 {
        let gap = post_residual as f64;
        let fillable = if gap >= 50.0 { 1.0 } else if gap >= 30.0 { 0.5 } else if gap >= 10.0 { 0.2 } else { 0.0 };
        score += (1.0 - fillable) * gap * 1.5;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tight fit bonus: leaving little slack relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: prefer packing into existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item could use the post-residual, reward leaving that gap.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }

    // Mean residual coupling: penalize bins far below the mean residual (avoid fragmenting big spaces early).
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    // New-bin candidate: make it slightly unattractive unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.0;
        // But attractive if no good fit exists elsewhere.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: penalize large post_residual relative to capacity
    score += 2.0 * (post_residual as f64 / bin_capacity as f64).powi(3) * 100.0;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // chain fit quality: how tightly next item fits after this placement
        let chain_residual = post_residual - next_item_size;
        score -= 30.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post residual likely dead space if smaller than next item
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Match against mean residual: prefer bins tighter than the mean
    score -= 1.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 80.0 + 0.5 * mean_residual;
    }

    // Late in stream: prefer consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: perfect fills are strongly rewarded
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if post_residual == 0 {
        score -= 40.0; // exact fill
    } else if post_residual < 10 {
        score -= 20.0 * fit_ratio; // near-perfect fill
    }

    // Penalize dead space relative to smallest plausible future item
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += 8.0; // residual too small for lookahead item
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // lookahead item can still fit here
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let congestion = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 - 20.0 * congestion - 10.0 * progress;
        // Opening a new bin is better if the item is large and residuals are scattered
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // Mild preference for bins tighter than the global mean (consolidate waste)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, discourage spreading across many open bins
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like, no piecewise constants
    score -= 12.0 * poly * norm_pr * (1.0 - norm_pr) * 4.0;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + poly);

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt);
        } else {
            score -= 4.0 * (1.0 - nxt / pr);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild preference for bins deviating from mean residual (diversification of sizes)
    score += 3.0 * ((pr as f64 - mean_residual) / cap).abs();

    // Slight penalty for opening new bins as stream progresses
    score += 5.0 * poly * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Perfect fit reward ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Harmonic residue classes on post_residual (dead-space classes mod 10) ---
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in [1..9] are "dead space" unless a future item of exactly that size arrives;
    // penalize awkward small residues, mildly favor multiples of 10.
    match class {
        0 => score -= 15.0,                    // clean slot, reusable by size-10 granularity items
        1 | 3 | 7 | 9 => score += 12.0,        // prime-ish residues: rarely matchable
        2 | 4 | 6 | 8 => score += 4.0,         // even residues: some chance of reuse
        _ => score += 8.0,                     // 5: half-decade, moderate dead space
    }

    // --- Integer division thresholds on post_residual: coarse fill tiers ---
    let tier = pr / 10; // 0..=10
    score += (tier as f64) * 3.0; // larger leftover = larger score = less preferred, linearized per tier

    // --- Lookahead coupling: does next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can be chained here: strong reward, scaled by how snugly it fits.
            let snug = (pr - next_item_size) as f64;
            score -= 30.0 - snug * 0.4;
            // Harmonic bonus if next_item_size shares a residue class structure with post_residual
            if next_item_size % 10 == pr % 10 && pr >= next_item_size {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: this bin becomes a likely dead bin.
            // Penalize proportionally to wasted capacity tier.
            let waste_tier = pr / 20;
            score += (waste_tier as f64) * 8.0;
        }
    } else {
        // Last item in stream: any residual is pure waste; minimize it hard.
        score += 50.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- New-bin candidate logic (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item is large (little would be left over
        // as dead space) or when existing bins are already fragmented.
        let frag = if mean_residual > 0.0 { mean_residual } else { 0.0 };
        let large_item_bonus = if item_size >= 50 { 20.0 } else { 0.0 };
        // New bin score: its post_residual is (capacity - item_size); add a surcharge
        // that decays for large items and grows with fragmentation of open bins.
        score += 10.0 - large_item_bonus + frag * 0.3;
        // If many bins are open, prefer packing into existing ones (avoid bin sprawl).
        if open_bins_count > 8 {
            score += (open_bins_count as f64 - 8.0) * 2.0;
        }
        // If item is small and mean residual is large, opening a new bin is wasteful.
        if item_size < 30 && frag > 40.0 {
            score += 30.0;
        }
    }

    // --- Capacity-fraction coupling: reward filling past half / three-quarters marks ---
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill >= 0.75 {
        score -= 12.0;
    } else if fill >= 0.5 {
        score -= 6.0;
    }

    // --- Stream progression: late in the stream, tighten up (prefer snug fits more) ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste. Penalize them heavily.
    if post_residual > 0 {
        let min_useful = 10.0f64.min(bin_capacity as f64);
        if (post_residual as f64) < min_useful {
            score += 40.0 + (min_useful - post_residual as f64) * 3.0;
        } else if post_residual == 0 {
            // Perfect fit: reward strongly.
            score -= 25.0;
        }
    } else {
        score -= 25.0;
    }

    // Tight fits (small post_residual relative to item) are good.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; with few bins, exploration is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.35 + 0.65 * progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when the item leaves a very
    // bad residual elsewhere or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 18.0 + pressure * 0.8;
        // Large items fit well in fresh bins; small items waste them.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // If the next item is large too, a fresh bin may be strategic.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate fullness).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Lookahead: if the post-residual can hold the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: mild dead-space penalty.
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // reward bins whose post_residual exactly accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 60.0; // perfect 2-chain: fill bin completely next step
        } else if (post_residual as f64 - nxt).abs() <= 10.0 {
            score -= 30.0; // near-perfect chain
        } else if post_residual >= next_item_size {
            score -= 12.0; // next item still fits here
        } else {
            // next item won't fit: dead space risk grows with small post_residual
            score += 8.0 + (10.0 - post_residual as f64).max(0.0);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable fragments (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual is already favored by the base term.
    // Penalize very small dead space that is hard to reuse (below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here: mildly reward
            score -= 8.0;
        } else {
            // next item cannot use this residual: penalize proportional to wasted potential
            score += (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Global state coupling: prefer using bins whose residual is below the mean
    // (consolidate space), avoid dumping into already-large-residual bins.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.5 * (residual_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - residual_f);
    }

    // Time horizon: late in the stream, avoid opening new bins unless necessary.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 60.0 * progress;
        // Allow new bin early if many bins are open and mean residual is high (fragmentation).
        if open_bins_count > 4 && mean_residual > 30.0 {
            score -= 15.0;
        }
    }

    // Mild preference for filling bins that are already quite full.
    let fill_ratio = 1.0 - residual_f / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Penalize leaving residuals that cannot fit the smallest possible item (1).
    if post_residual == 0 {
        score -= 5.0; // perfect fit is great
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let rf = pr / cap; // normalized post-placement residual in [0,1]

    let mut score = pr;

    // Non-linear polynomial coupling: residual tightness vs. stream progress.
    // Large leftover space is increasingly penalized as the stream advances;
    // tight fits are progressively rewarded via a smooth (1-rf)^2 term.
    score += 30.0 * rf * rf * (1.0 + t);
    score -= 22.0 * (1.0 - rf) * (1.0 - rf) * (0.5 + t);

    // Lookahead coupling (k=2): reward bins whose leftover can host the next item,
    // penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            // reward proportional to how much of the leftover the next item consumes
            score -= 18.0 * (ns / pr) * (1.0 - 0.3 * t);
        } else {
            // unusable gap for the upcoming item: smooth quadratic dead-space penalty
            let gap = (pr - ns) / cap;
            score += 28.0 * gap * gap * (1.0 + 2.0 * t) + 10.0 * gap;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly favor it
    // to avoid opening a new bin (strength scales with how tight the fit is).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0 * (1.0 - rf) * (1.0 - rf);
    }

    // New-bin candidate detection (bin_residual == bin_capacity): penalize opening
    // a fresh bin, more so late in the stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let oc = open_bins_count as f64;
        score += 12.0 + 18.0 * t * (oc / (1.0 + oc)) + 6.0 * (oc / (oc + 4.0));
    }

    // Mean-residual coupling: prefer bins tighter than the current average
    // (preserves large residuals for large future items); smooth quadratic
    // term damps extreme deviations, and its weight fades with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * (1.0 - 0.5 * t) + 5.0 * dev * dev * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification by modulo classes
    let pr = post_residual;
    let cls = pr % 10; // residue class mod 10
    // Residues that pair well with common small items (0,5) are less harmful
    let class_penalty = match cls {
        0 => 0.0,
        5 => 2.0,
        1 | 9 => 6.0,
        2 | 8 => 9.0,
        3 | 7 => 12.0,
        _ => 15.0, // 4 | 6
    };
    score += class_penalty;

    // Integer-division thresholds: large divisible residuals are valuable
    if pr >= 50 && pr % 25 == 0 { score -= 8.0; }
    if pr >= 30 && pr % 10 == 0 { score -= 4.0; }

    // Lookahead coupling: reward if next item fits exactly or near-exactly in post residual
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 25.0; // perfect chain
        } else if slack <= 10.0 {
            score -= 12.0 * (1.0 - slack / 10.0);
        } else {
            score -= 3.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here regardless; dead space penalty grows with gap
        let gap = (next_item_size - pr) as f64;
        score += 0.05 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins below mean residual (more packed bins)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.10 * (mean_residual - res_f);
    } else {
        score += 0.05 * (res_f - mean_residual);
    }

    // Tight fits are excellent: small post residual relative to item size
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score += 5.0 * tightness;

    // New-bin candidate handling: only prefer new bin when all fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base threshold slightly above typical bad-fit scores
        score = cap * 0.85 + 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0; // next item is large, fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 1000.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny nonzero leftovers are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // moderately risky gap
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.5;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this gap: penalize proportionally.
        score += 8.0;
    }

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: mild penalty scaled by number of open bins
    // to encourage consolidation, but not enough to force bad fits.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a bin rises with congestion.
        score += (open_bins_count as f64) * 2.0 + 5.0;
    } else {
        score -= 3.0;
    }

    // Slight preference for bins tighter than average (better packing).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
