pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        let usable = if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 { 0.3 } else { 1.0 };
        score += 18.0 * dead * dead * usable;
    }

    // Lookahead: if next item also fits this residual, big bonus (pairing).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let pair_waste = post_residual as f64 - next_item_size as f64;
        score -= 12.0 - 0.15 * pair_waste;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item won't fit here after placement; mild penalty unless this is a perfect fit.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier about large residuals.
        score += 0.05 * (fitting_bins_count as f64 - 3.0) * (post_residual as f64 / 10.0);
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    let residual_diff = (bin_residual as f64) - mean_residual;
    score += 0.08 * residual_diff;

    // Mild consolidation pressure: more open bins -> favor filling existing ones.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in the stream, be more willing to open fresh bins for large items
    // (keep flexibility); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Opening a new bin is good for large items or when post_residual would be tiny
        // in the best existing bin anyway; penalize otherwise.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let no_good_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        if large_item || no_good_fit {
            score -= 6.0 + 8.0 * (1.0 - progress);
        } else {
            score += 10.0 + 15.0 * progress;
        }
    }

    // Late stream: strongly discourage leaving medium dead space.
    score += progress * 6.0 * (post_residual as f64 / 100.0);

    // Slight preference for bins whose residual is close to a multiple-ish structure
    // with the item (modular fit heuristic).
    let mod_fit = (bin_residual as i64 - item_size as i64).rem_euclid(10) as f64;
    score += 0.1 * mod_fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: reward tight fits (low post residual), non-linearly.
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize small residuals less),
    // late in stream, strongly prefer minimal post_residual.
    let tight = (pr / cap).powi(2);
    let coupling = 1.0 + 2.5 * progress * progress;
    score += tight * cap * coupling;

    // Smooth interaction: dead space that is too small to be useful
    // is penalized more as the stream progresses.
    let dead = (pr / cap).powi(3) * cap * (1.0 + 3.0 * progress);

    // Lookahead: bonus if next item fits into the post residual.
    let next = next_item_size as f64;
    let lookahead_bonus = if next > 0.0 && next <= pr {
        -(next / cap) * (1.0 + progress) * 8.0
    } else if next > 0.0 {
        // next item won't fit here; penalize wasting large residuals
        (pr / cap) * 2.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using it before opening new bins.
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Slight preference for bins below mean residual (balance load),
    // scaled non-linearly by number of open bins.
    let balance = ((bin_residual as f64 - mean_residual) / cap) * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // New-bin candidate: penalize mildly unless residuals are very tight.
    let new_bin_penalty = if bin_residual == bin_capacity {
        5.0 + 10.0 * progress + dead
    } else {
        0.0
    };

    score + dead + lookahead_bonus + last_chance + balance + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let class = post_residual % 10;
    // Penalize residuals that fall in "dead zones" (1..9) which few item sizes can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else {
        // reward exact-fill classes (post_residual == 0 handled by low base already)
        match class {
            0 => score -= 8.0,                       // perfectly decadal residual, very reusable
            1 | 2 | 3 => score += 6.0,               // awkward small remainders
            4 | 5 | 6 => score += 2.0,               // mid remainders, moderately reusable
            7 | 8 | 9 => score -= 1.0,               // fillable by 70/80 items
            _ => {}
        }
    }

    // Integer-division thresholds: how many "typical" items (size 20) could still fit.
    let quads = post_residual / 20;
    score -= quads as f64 * 4.0;

    // Lookahead coupling: if next item fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // extra reward if next item nearly fills the bin (harmonic pairing)
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, adjusted by stream state.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins would leave bad classes and many bins open.
        score = 40.0 + mean_residual * 0.3 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Prefer bins tighter than the mean residual (better packing candidates).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let min_next = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < min_next.min(bin_capacity) {
            // Gap too small for the lookahead item: dead space penalty,
            // harsher the smaller the gap relative to capacity.
            let gap_ratio = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * (1.0 - gap_ratio) + 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward filling a bin nearly completely (post_residual small in absolute terms).
    if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer packing into existing bins
    // (penalize the new-bin candidate more when many bins are already open).
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Early in the stream, be slightly more willing to open bins (better long-run packing);
    // late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * mean_residual / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Prefer bins whose residual is tighter than the mean (good packing density).
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Mild bias toward fewer open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Penalize leaving large unusable gaps (small dead space already covered).
    if post_residual > 0 && post_residual < 5 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits, but avoid leaving dead space that nothing can use.
    if post_residual > 0 {
        let dead_penalty = if post_residual < 10 { 12.0 } else { 0.0 };
        score += dead_penalty;
    } else {
        score -= 8.0; // perfect fill
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins can already fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (fitting_bins_count as f64).max(1.0);
        score += 30.0 + 8.0 * pressure;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 - gap.min(15.0) * 0.5;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would need a different bin; slight penalty for wasting residual
        score += 4.0;
    }

    // Prefer bins with residuals close to the item (best-fit flavor).
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * diff * diff;

    // Mild pressure to consolidate into bins below mean residual.
    score -= 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits: normalize post_residual, penalize quadratically when large.
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * cap * 0.05;

    // Smooth progress coupling: later in stream, waste is costlier.
    score += 6.0 * post_norm * (0.5 + progress);

    // Interaction of item size with residual: prefer filling big items into roomy bins smoothly.
    let fill = item / cap;
    score -= 8.0 * fill * (1.0 - post_norm);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that blocks the next item only mildly.
        score += 1.5 * ((next_item_size as f64) - post) / cap;
    }

    // Mean residual coupling: avoid creating outliers far below the mean.
    score += 0.5 * (post - mean_residual).abs() / cap;

    // Slight penalty for many open bins to encourage consolidation.
    score += 0.2 * open_bins_count as f64;

    // New-bin candidate: keep it attractive only when post_residual is large.
    if bin_residual == bin_capacity {
        score = post - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Dead-space penalty: leftovers smaller than a quarter are hard to reuse.
    if post < quarter {
        score += (quarter - post) as f64 * 1.5;
    }
    // Modulo classes: residues that pair well with common item sizes get rewards.
    // Residuals divisible by 10 (decile class) are highly reusable.
    if post % 10 == 0 && post > 0 {
        score -= 6.0;
    }
    // Residual divisible by 20 or 25 (harmonic quarters) even better.
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 3.0;
    }
    // Odd residue classes in the awkward band (eighth..quarter) get mild penalty.
    if post >= eighth && post < quarter && post % 5 != 0 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 15.0;
        } else if next_item_size < post {
            // next item fits: reward proportional to tightness class
            let nxt = next_item_size as f64;
            let frac = nxt / cap;
            if frac < 0.25 {
                score -= 4.0 * (1.0 - frac);
            } else if frac < 0.5 {
                score -= 2.0;
            }
            // penalize leaving post_residual - next_item_size as dead space
            let nxt_post = post - next_item_size;
            if nxt_post < quarter {
                score += (quarter - nxt_post) as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Tight fit reward: near-perfect fills are always good.
    if post == 0 {
        score -= 25.0;
    } else if post <= eighth {
        score += 2.0; // small but not zero leftover is semi-dead space
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * (open_bins_count as f64).sqrt() * 1.2;

    // Stream progression: late in the stream, be greedier about packing tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= fill * progress * 4.0;

    // New-bin candidate: penalize opening a new bin unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 10.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 18.0; // fragmentation: better to open fresh bin
        }
        if next_item_size > 0 && next_item_size as f64 / cap > 0.5 {
            score += 8.0; // big next item: keep open bins' space free
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1, but practically < next_item_size or a floor
    // threshold) are wasted capacity. Penalize hard.
    let dead_floor = 1u32;
    if post_residual < dead_floor.max(next_item_size.min(bin_capacity / 10)) && post_residual > 0 {
        // Unusable small gap: heavily penalize proportionally to how close
        // it is to being useless.
        score += 25.0 * (1.0 - post_residual as f64 / (bin_capacity as f64 * 0.1).max(1.0));
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: the leftover is likely dead space.
        score += 6.0;
    }

    // Open bins pressure: penalize using an existing bin when many bins are
    // open, to encourage consolidation; but a last-chance bin (only fitting
    // bin) should be strongly preferred over opening a new one.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive if current
    // residuals are fragmented (high mean residual spread vs item) or the
    // item barely fits anywhere. Make the empty bin slightly unattractive
    // by default so consolidation wins unless dead space dominates.
    if bin_residual == bin_capacity {
        score += 4.0 + mean_residual * 0.05;
        // If item is large relative to typical residuals, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 6.0;
        }
    }

    // Mild stream-progression term: later in the stream, prefer tighter
    // packing even more (less time to recover from fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = (pr - nxt).abs();
            // exact match next step is ideal
            score -= 300.0 * (1.0 - gap / 100.0).max(0.0);
            if gap == 0.0 {
                score -= 250.0;
            }
        } else {
            // next item cannot fit here: penalize proportional to wasted lookahead potential
            score += 0.8 * (nxt - pr);
        }
    } else {
        // last item: minimize post residual aggressively
        score += 2.0 * post_residual as f64;
    }

    // Compare post_residual relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin unless item is large and residuals elsewhere are small
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let urgency = (item_size as f64 / 100.0) * (1.0 - progress);
        score += 150.0 - 120.0 * urgency;
        if next_item_size > 0 && post_residual >= next_item_size as f64 {
            score -= 80.0; // fresh bin can host next item too
        }
    }

    // Tight fit preference: smaller waste relative to capacity
    score += 0.3 * (pr / bin_capacity as f64) * 100.0;

    // Prefer bins with high utilization so far
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Lookahead: penalize if next item cannot use the post residual (dead space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can chain into this bin: reward
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space risk grows with how much leftover can't be used
            score += 5.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: minimize waste aggressively
        score -= 10.0;
    }

    // Last chance: this is the only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins exist with usable residual
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress;
        // if mean residual across open bins is large, opening a new bin is wasteful
        score += 0.3 * mean_residual;
        // many open bins with slack -> discourage new bin
        score += 2.0 * open_bins_count as f64;
    } else {
        // favor consolidating into bins with below-average residual (fill emptier bins)
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Mild preference for using fewer distinct bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = post;
    score += 40.0 * x * x;                       // penalize wasted space superlinearly
    score -= 25.0 * x * (1.0 - x);               // reward mid-range fills smoothly

    // Stream-progress coupling: early on, keep bins flexible (higher post residual OK);
    // later, prefer tight packing. Smooth polynomial interaction.
    let flex = 1.0 - progress;
    score += 30.0 * x * x * flex;                // early: tolerate loose fits
    score -= 20.0 * x * progress;                // late: reward tight fits more

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 + 10.0 * (1.0 - x);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty proportional to mismatch
        score += 8.0 * (next_item_size as f64 - post) / cap;
    }

    // Crowd-awareness: many open bins -> prefer consolidating into existing ones.
    let crowd = (open_bins_count as f64).ln_1p();
    score += 5.0 * crowd * (1.0 - x);

    // Mean residual coupling: if this bin's residual deviates from mean, small smooth penalty.
    let dev = (post - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        score += 60.0 - 40.0 * progress; // less penalty late (opening fresh bins is fine later)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modulo arithmetic on capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that no plausible item (1..=100) can fill well.
    // Harmonic classes of residual: residual % 10 == 0 leaves clean slots.
    let harmonic_class = post_residual % 10;
    if harmonic_class == 0 {
        score -= 6.0; // clean class, very reusable
    } else if harmonic_class <= 3 {
        score += 4.0; // awkward small remainder class
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Fractional capacity coupling: post_residual as fraction of capacity
    let frac = post / cap;
    score += (frac * frac) * 20.0; // penalize large leftover quadratically

    // Integer division thresholds on post_residual: which item classes could still fit?
    // Count harmonic "slots": how many distinct item-size classes (multiples of 10) fit.
    let slots = post_residual / 10;
    score -= (slots as f64) * 3.0; // more usable slots -> better bin

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, stronger if it leaves another clean class
            let next_post = post_residual - next_item_size;
            score -= 10.0 + (next_post % 10 == 0) as i32 as f64 * 6.0;
            // harmonic match: next_item_size class matches residual class
            if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
                score -= 8.0;
            }
        } else {
            // next item won't fit here after this placement
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless their fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * open_bins_count as f64;
        // But if current item is huge relative to typical residuals, opening fresh is fine
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be more aggressive about tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    // Mean residual coupling: prefer bins close to the mean residual (balanced use)
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        // perfect fit, heavily rewarded
        score -= 60.0;
    } else if post_residual <= 10 {
        // tiny unusable gap -> strong penalty
        score += 40.0;
    } else {
        // usable gap: reward proportional to how well next item could use it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // smooth penalty on large leftovers to prefer tight packing
        score += 0.25 * (post_residual as f64).powf(1.1) / 10.0;
    }

    // Tight fit reward: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin pressure: if this is the only bin that fits, favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // but allow new bin if all open bins would leave bad dead space
        if post_residual <= 10 && next_item_size > 0 {
            score -= 45.0;
        }
    } else {
        // slight preference for bins with lower residual among equals
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Early stream: be more conservative, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Dead space: post_residual too small for the next item (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
        // Extra penalty for very tight dead space.
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Reward bins whose residual deviates favorably from the mean (tighter bin).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin early in the stream when open bins could fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // But allow new bins later in the stream for large items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild preference for filling larger items into fuller bins.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
