    if post_residual < quarter {
        score += 5.0; // near-dead space
    } else if post_residual >= quarter * 2 && post_residual <= quarter * 3 {
        score -= 3.0; // sweet spot for future mid-size items
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward more if next item leaves a harmonic residue too
        let next_left = post_residual - next_item_size;
        if next_left % 10 == 0 {
            score -= 10.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow in this bin: penalize proportionally to wasted harmony
        score += (next_item_size % 10) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // discourage opening new bin when decent fits exist
            score += 12.0 + (post_residual as f64 - mean_residual).abs();
        }
    }

    // Stream progression: late in the stream, prefer tighter packing (lower post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far below mean residual are less attractive
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much more than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: nothing (min size 1) can ever use it
    } else if post_residual < 20 {
        score += 8.0; // very hard to fill
    } else if post_residual < 30 {
        score += 3.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still accommodate typical future items.
    if post_residual >= 50 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + slack * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // this bin would become dead space before the next item arrives
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item is large relative
    // to what open bins would leave behind, or no decent fit exists.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin, offset by its huge flexibility
        score = (bin_capacity - item_size) as f64 + 15.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // forced open anyway
        }
    } else {
        // Slight preference for bins whose residual is close to mean (avoid fragmenting outliers)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in stream, be more selective; later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward perfect/near-perfect fits: small post_residual is good.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space: residual smaller than min item size.
        if post_residual < 10 {
            score += 50.0 * (10.0 - post_residual as f64);
        }
        // Tightness reward: quadratic bonus for small residuals.
        let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        score -= 30.0 * tight * tight;
    }

    // 2-step lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chain
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward proportional to how snugly next item fits.
            score -= 200.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 20.0 * (over / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win; reduced late in stream
        // or when many bins are open (consolidation pressure).
        let mut new_bin_penalty = 120.0;
        new_bin_penalty *= 1.0 - 0.5 * progress;
        if open_bins_count > 3 {
            new_bin_penalty -= 10.0 * (open_bins_count.min(10) as f64 - 3.0);
        }
        // If next item is large, a fresh bin may be attractive.
        if next_item_size > 60 {
            new_bin_penalty -= 40.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Prefer bins with below-average residual (more room to fill later),
        // i.e., penalize bins whose residual is already small relative to mean
        // only mildly; favor using fuller bins to consolidate.
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    // Mild global pressure: when many bins are open, pack tighter.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize dead space that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize wasted residual it leaves behind
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be more selective (penalize mediocre fits);
    // late in the stream, just pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_gap = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score += (1.0 - progress) * 10.0 * mean_gap.max(0.0);
    score -= progress * 5.0 * fill_ratio;

    // New-bin candidate handling: only open a new bin if item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count == 0 || fill_ratio == 0.0;
        if pressure && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0; // large item: fresh bin is reasonable
        } else {
            score += 15.0 + 10.0 * (1.0 - progress); // discourage wasting fresh bins early
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate residual less.
    let mut score = post * (1.0 + 0.8 * progress) + 45.0 * norm_post * norm_post * (0.5 + progress);

    // Reward near-perfect fits smoothly (dead-space penalty vanishing at 0).
    let waste = norm_post * norm_post;
    score += 30.0 * waste * (1.0 - progress);

    // Lookahead coupling: if next item fits in the resulting residual, reward;
    // if residual is too small for the next item, penalize smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            let gap = (nx - post) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Congestion: many open bins -> prefer filling existing ones (penalize new-bin tendency).
    let congestion = (open_bins_count as f64).ln_1p();
    score += 3.0 * congestion * norm_post;

    // Mean-residual anchoring: bins deviating below mean residual are more valuable to fill.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 5.0 * dev * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when it genuinely helps
    // (late stream, large item, poor alternatives). Otherwise keep it mildly penalized.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 18.0 * progress * (item_size as f64 / cap);
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by small sizes (10/20/25/50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        // integer-division thresholds: small leftovers are dead space
        if pr <= 10 { bonus -= 8.0; }
        else if pr <= 20 { bonus -= 3.0; }
        else if pr >= 50 { bonus += 5.0; }
        score -= bonus;
    }

    // Lookahead coupling: does the leftover accommodate the next item's class?
    if next_item_size > 0 && pr >= next_item_size {
        let slack_class = (pr - next_item_size) / 10; // integer division class
        score -= 4.0 + slack_class as f64 * 0.5;
    } else if next_item_size > 0 && pr > 0 {
        score += 3.0; // next item cannot follow here -> wasted slot
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual > 0 && (post_residual as f64) < 0.15 * bin_capacity as f64;
        if poor_fit || open_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 10.0 + 10.0 * progress;
        }
    }

    // Prefer tighter bins overall: deviation from mean residual
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for bins whose class matches item size decile
    let item_class = item_size / 10;
    if bin_residual / 10 >= item_class {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Gaps below the minimum item size (1..100 unknown, use conservative band)
        score += 18.0;
    }

    // Reward tight fits (waste ratio low).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - waste_ratio).powi(3);

    // Penalize bins with large residuals being emptied only slightly
    // (prefer filling bins that are already mostly full).
    score += 0.25 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Open bins pressure: when many bins are open, discourage opening new ones;
    // new-bin candidate (bin_residual == bin_capacity) gets a penalty unless
    // existing fits are terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 4.0 * open_bins_count as f64;
        // If the next item is large and no open bin would fit both, opening
        // a fresh bin is attractive: discount the new-bin penalty.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 40.0;
        }
    } else {
        // Prefer reusing bins when few are open.
        score -= 5.0 / (open_bins_count as f64).max(1.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin for a poor fit.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (more freedom later); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mean residual coupling: if this bin's post_residual is far below the
    // mean residual, it's a good consolidation choice.
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
