pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Extra reward if next item exactly fills the bin.
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here; slight penalty for leaving awkward space.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap < 20.0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when no good existing fit exists (large post residual elsewhere).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, softened when many bins are open
        // and mean residual is high (existing bins are fragmented).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 55.0 + 30.0 * (1.0 - fragmentation) - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits; must open
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for pairing in fresh bin
        }
    }

    // Slight preference for filling fuller bins as stream progresses.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * (step_index as f64 / (total_items.max(1) as f64));

    // Mild penalty for scattering across many open bins.
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Tightness: reward small post_residual non-linearly (quartic decay of waste).
    let tightness = 1.0 - post / cap;
    score -= 40.0 * tightness * tightness * tightness * tightness;

    // Perfect / near-perfect fit reward, smoothed.
    if post == 0.0 {
        score -= 60.0;
    } else if post <= 10.0 {
        score -= 25.0 * (1.0 - post / 10.0);
    }

    // Stream-progress coupling: later in the stream, prefer filling existing bins
    // more aggressively (avoid opening new bins that end up nearly empty).
    let late_bias = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 30.0 * late_bias * tightness;

    // Penalize bins whose residual deviates far above the mean residual
    // (keeps residual distribution compact and predictable).
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: if the next item fits the post-residual exactly-ish, reward;
    // if post-residual can't fit the next item but next item is large, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = post - nx;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            score += 10.0 * (nx - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless post-residual is huge dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 - post / cap);
    }

    // New-bin candidate: discourage unless current item is large and nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - item / cap) - 20.0 * late_bias;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into residue
    // classes modulo 10 (typical item granularity). Small residues are "dead space".
    let residue_class = post_residual % 10;
    let dead_penalty: f64 = if post_residual == 0 {
        -30.0 // perfect fit: strongly reward
    } else if residue_class == 0 {
        -6.0 // leftover divisible by 10 is reusable by typical items
    } else if residue_class <= 3 {
        12.0 + residue_class as f64 // tiny unusable sliver: penalize
    } else {
        0.0
    };
    score += dead_penalty;

    // Integer-division threshold on post_residual: how many "next-item-sized"
    // chunks still fit? Reward bins that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            let chunks = post_residual / next_item_size;
            score -= (chunks.min(3)) as f64 * 2.0;
        } else {
            score += 6.0; // lookahead item cannot follow here
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 5 {
            score -= 10.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: prefer existing bins with tight fits;
    // only let a fresh bin win when the current fit leaves large awkward waste.
    if bin_residual == bin_capacity {
        // brand-new bin baseline
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 5.0; // nothing else fits, new bin is fine
        } else if post_residual >= 40 {
            score -= 4.0; // big item into empty bin is reasonable
        } else {
            score += 10.0; // small item: waste of a fresh bin
        }
    }

    // Capacity fraction coupling: reward filling fraction of the bin.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Stream progression: late in the stream, compactness matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 - progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Mean residual context: if this bin is far below mean residual, it is a
    // good "garbage absorber"; if far above, deprioritize it.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Small tie-breaker against post_residual to keep strict ordering.
    score += post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        // A tiny gap (< 10) can never fit the smallest item (size >= 1 assumed small),
        // so it is pure dead space: penalize heavily.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else {
            // Usable gap: mild penalty proportional to how "awkward" it is
            // (gap much smaller than typical items is less useful).
            score += 0.3 * (post_residual as f64).sqrt();
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 25.0; // chain perfect fit
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: dead-space chain risk.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 12.0;

    // New-bin candidate: only attractive when current bin residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Default mild penalty so we prefer existing bins unless they're truly bad.
        score += 20.0;
        if mean_residual < 15.0 {
            // Existing bins nearly full/dead: opening a new bin is good.
            score -= 30.0;
        }
        let _ = fragmentation;
    }

    // Slight time decay: early in the stream, keep bins flexible (favor larger residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: leave exactly the space the next item needs.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space the next item cannot use
        if next_item_size > post_residual && post_residual > 0 {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: reward tightest packing
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean residual shaping: prefer bins tighter than average
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let urgency = (next_item_size as f64 - post_residual as f64).abs();
        let poor_fit_exists = mean_residual < item_size as f64 * 0.5;
        if next_item_size == 0 || (fitting_bins_count == 0) {
            score -= 15.0;
        } else if poor_fit_exists && urgency < 10.0 {
            score -= 5.0;
        } else {
            score += 45.0 + 0.4 * open_bins_count as f64;
        }
    } else {
        // Slight preference for already-open bins over opening new ones
        score -= 5.0;
        // Reward near-perfect fills
        if post_residual <= 2 {
            score -= 20.0;
        }
    }

    // Late-stream tightening: as stream progresses, avoid stranding small residuals
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space: post-residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: reward bins whose leftover fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let mut penalty = 25.0;
        if fitting_bins_count > 0 {
            penalty += 15.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= item_size {
            penalty -= 8.0;
        }
        score += penalty;
    }

    // Global state: many open bins -> prefer consolidating into existing ones.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins below mean residual (balance usage across bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild time decay: late in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post-residual, non-linearly coupled with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Quadratic/cubic dead-space penalty: small post-residuals (but not zero) are risky.
    let dead = norm_pr * (1.0 - norm_pr);
    score += 40.0 * dead * (1.0 - fit);

    // Reward tight fits (near-zero post residual) more strongly later in the stream.
    score -= 25.0 * progress * (-pr / 12.0).exp();

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalty when this bin is much tighter than the average open bin (preserve slack elsewhere).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev * dev / (cap * cap);

    // Lookahead: if next item fits exactly into resulting post_residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 15.0 * (-slack / 10.0).exp();
        } else {
            score += 0.2 * (nx - pr);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: dead space in small classes is worse.
    let pr = post_residual;
    if pr > 0 {
        // Penalize post_residuals in awkward small classes (1..10) heavily.
        if pr < 10 {
            score += 60.0;
        } else {
            // Reward post_residuals that are multiples of common size bands (10/20/25/50).
            if pr % 10 == 0 { score -= 8.0; }
            if pr % 20 == 0 { score -= 4.0; }
            if pr % 25 == 0 { score -= 3.0; }
            if pr % 50 == 0 { score -= 5.0; }
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 100.0;
    }

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0; // exact follow-up fit
        } else if pr >= next_item_size {
            let slack = pr - next_item_size;
            score -= 15.0;
            if slack % 10 == 0 { score -= 6.0; }
            if slack < 10 { score += 10.0; } // leaves tiny dead space after next
        } else {
            // next item cannot use this residual: residual class matters
            score += 5.0;
            if pr < 10 { score += 20.0; }
        }
        // Integer-division thresholds on next_item_size
        let nclass = next_item_size / 20; // 0..5 harmonic class
        match nclass {
            0 => score -= 2.0,  // tiny next item: residual flexibility high
            1 => score += 0.0,
            2 => score += 1.0,
            3 => score += 3.0,
            _ => score += 5.0,  // large next item: prefer roomier bins
        }
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score, worse than good fits.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 10.0 * (open_bins_count as f64).sqrt();
        // Attracted if current open bins have poor average residual vs item.
        if (mean_residual - item_size as f64) < 5.0 {
            score -= 20.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild tie-breaker: prefer fuller bins (smaller residual) via mean coupling.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item (1..=10) are almost certainly wasted -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Lookahead synergy: if the next item fits exactly into the leftover
    // space, strongly prefer this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover cannot host the next item -> mild dead-space penalty.
        score += 6.0;
    }

    // Open-bin pressure: discourage opening new bins when alternatives fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 25.0 + 2.0 * open_bins_count as f64;
        }
        // Opening is cheaper later in the stream when bins accumulate anyway.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Slight preference for using existing bins, more so when many are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Bias toward bins with residuals below the mean (consolidate fullness).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how little slack remains after the pair
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving a gap that likely becomes dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize post_residual below the minimum item size (unusable dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; reduce when many bins are open or fit is bad elsewhere.
        score += 55.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 20.0; // item leaves large residual in new bin: acceptable if others are tight
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin gives room for the larger next item
        }
    }

    // Early stream: be slightly more willing to open bins to build diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // cannot host the lookahead item
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead synergy: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= (bin_capacity as f64 / (1.0 + gap as f64)) * 0.6;
    }

    // New-bin candidate: penalize opening a new bin unless residuals everywhere are tight.
    if bin_residual == bin_capacity {
        let tight = mean_residual / bin_capacity as f64;
        score += 25.0 - 30.0 * tight;
        // Late in stream, prefer reusing existing bins more strongly.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * t;
        // Many open bins -> discourage spreading.
        score += open_bins_count as f64 * 1.5;
    }

    // Slight preference for bins below mean residual (balancing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: post residual, mildly compressed non-linearly
    let mut score = pr * (1.0 + 0.15 * (pr / cap) * (pr / cap));

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, demand tight fits.
    let coupling = (pr / cap) * (1.0 - progress) - 0.35 * (pr / cap) * progress * (pr / cap);
    score += 20.0 * coupling;

    // Reward filling bins well, scaled by how close post_residual is to a "dead zone"
    let dead = (pr / cap - 0.2) * (pr / cap - 0.2);
    score += 15.0 * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin, more so late in stream
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins, especially when mean residual is high (fragmentation)
        score -= 5.0 + 0.3 * mean_residual * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item won't fit here anyway; slight penalty for wasting large residual
        score += 3.0 * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let item = item_size.max(1) as f64;
    let next = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let new_bin = bin_residual == bin_capacity;

    let mut score = pr / cap;

    // Prefer bins that are already tighter than the current average residual.
    score += 0.045 * ((bin_residual as f64 - mean_residual) / cap);

    // Exact closure is excellent.
    if post_residual == 0 {
        score -= 0.18;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic/integer-division class: how many lookahead items fit?
            let units = post_residual / next_item_size;
            let mut pair_reward = 0.34 + 0.08 * (units.min(4) as f64);

            // Reward exact harmonic alignment with the lookahead item and with
            // decimal capacity classes.
            if post_residual % next_item_size == 0 {
                pair_reward += 0.05;
            }
            if post_residual % 10 == 0 {
                pair_reward += 0.02;
            }
            if item_size % 10 == 0 && next_item_size % 10 == 0 && post_residual % 10 == 0 {
                pair_reward += 0.01;
            }

            score -= pair_reward;
        } else {
            // The known lookahead item cannot follow: treat the leftover as
            // potentially dead space, scaled by the harmonic gap class.
            let gap = next_item_size - post_residual;
            let gap_units = (gap / 10).min(6) as f64;
            let mut dead_space =
                0.16 + 0.045 * gap_units + 0.0015 * (gap % 10) as f64;

            // Quarter-capacity class: very small leftovers are poor buffers.
            let quarter_class = post_residual.saturating_mul(4) / bin_capacity.max(1);
            if quarter_class == 0 {
                dead_space += 0.05;
            }

            score += dead_space;
        }
    }

    if new_bin {
        if next_item_size == 0 {
            // Never prefer a fresh bin for the terminal item if any open bin fits.
            score += 8.0;
        } else if post_residual >= next_item_size {
            let mut new_penalty = 0.22
                + 0.012 * (open_bins_count.min(10) as f64)
                + 0.04 * progress
                + 0.012 * (fitting_bins_count.min(8) as f64);

            // If average existing space would probably also serve item+next,
            // opening a fresh bin is less attractive.
            if mean_residual >= item + next {
                new_penalty += 0.10;
            } else {
                new_penalty -= 0.03;
            }

            if open_bins_count == 0 || fitting_bins_count == 0 {
                new_penalty -= 0.08;
            }

            score += new_penalty.max(0.0);
        } else {
            // A fresh bin that cannot absorb the lookahead item merely creates
            // an extra bin now; make it lose to any fitting open bin.
            score += 1.40 + 0.03 * (open_bins_count.min(10) as f64);
        }
    } else if fitting_bins_count == 1 {
        // Last-chance open bin: reward it strongly when it is genuinely useful,
        // but only slightly when the lookahead item would not follow.
        if next_item_size == 0 || post_residual >= next_item_size {
            score -= 0.08 + 0.04 * progress;
        } else {
            score -= 0.02;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 && post_residual < item_size.min(bin_capacity / 2) {
        score += 40.0 * (1.0 - post_residual as f64 / (item_size.max(1) as f64));
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // New-bin candidate logic: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (mean_residual - item_size as f64).max(0.0) };
        score = 55.0 + pressure + open_bins_count as f64 * -0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for a big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_left = post_residual - next_item_size;
        score -= 25.0 - (chain_left as f64).min(20.0);
        if chain_left == 0 {
            score -= 15.0;
        }
    }
    // Next item cannot be chained: penalize dead space if it would be stranded.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Reward tight fits relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(30.0) * 0.8;
    } else {
        score += (pr - mean_residual).min(40.0) * 0.4;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent existing fits exist, unless
    // the item is huge and a fresh bin gives a clean split.
    if bin_residual == bin_capacity {
        let fresh_bonus = if item_size >= 60 { 10.0 } else { 0.0 };
        score += 45.0 - fresh_bonus;
        // Allow new bin when no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream, consolidate rather than open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins with larger residual consumed (waste minimization).
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Slight preference for fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 18.0;

    // Penalize dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.9;
        } else {
            // Reward bins whose post residual still accommodates the lookahead item.
            score -= 4.0;
        }
        // Perfect pairing: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last chance: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0 + (open_bins_count as f64) * 1.5;
        // If the item leaves a large residual that likely wastes space, discourage less.
        let spread = (post_residual as f64) / (bin_capacity as f64);
        score -= spread * 20.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins below mean residual (smaller residuals = tighter bins) when fit is decent.
    let mean_gap = mean_residual - (bin_residual as f64);
    score += mean_gap * 0.15;

    // Mild penalty on many open bins to encourage closing them out.
    score += (open_bins_count as f64) * 0.05;

    // Encourage exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), weighted by progress
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: strongly subtract when post_residual is small relative to item
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (1.0 - progress);

    // Non-linear coupling of post residual with mean residual: prefer bins whose
    // post residual is below the mean (concentrating waste)
    let coupling = (norm_pr - mean_residual / cap);
    score += 25.0 * coupling.abs() * (0.5 + 0.5 * progress) + 15.0 * coupling * coupling;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress) + 10.0;
    }

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 18.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // New-bin candidate: neutral-ish baseline so it's chosen only when open bins score poorly
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: reward residuals that are
    // "usable slots" for common item sizes (mod-based fitability).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else {
        // Usable-slot bonus: residual that can host typical small items
        let mut usable = 0.0;
        for s in [10u32, 15, 20, 25, 30, 40, 50].iter() {
            if pr >= *s {
                usable += 1.0;
            }
        }
        score -= usable * 3.0;

        // Penalize residuals in awkward "dead zone" classes (small unusable slivers)
        if pr < 10 {
            score += 25.0;
        } else if pr % 10 != 0 && pr % 5 != 0 {
            score += 5.0; // non-harmonic residual
        }
    }

    // Tightness: reward small relative waste
    score += (post_residual as f64 / cap) * 20.0;

    // Lookahead: if next item fits exactly in the post-residual, big bonus
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            score += 6.0; // next item won't fit here; deprioritize
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (100.0 - item_size as f64);
        // early in stream, opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer filling bins with large residual spread (avoid many half-empty bins)
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Bonus for leaving room that can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 14.0;
    }
    // Penalize if post residual barely misses the next item (traps space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Pressure on number of open bins: encourage filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + open_bins_count as f64 * 2.0 - progress * 5.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Mild preference toward bins tighter than average (better fit).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, heavily reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits after this placement: reward exact chaining.
            score -= 30.0 / (1.0 + gap);
        } else {
            // Next item cannot use the leftover space: penalize dead space
            // proportionally to how close it came (near-miss is worst).
            score += 15.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Compare residual against mean residual across open bins:
    // placing into a bin that leaves less residual than average keeps
    // larger residuals available for bigger future items.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // item is large or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild stream-position coupling: later in the stream, consolidate more
    // aggressively (favor tight fits over spreading).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - fit_ratio);

    // Penalize leaving residuals too small to ever be useful (below min item size 1..10 range guard).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong bonus.
    let tight_fit_bonus = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    score -= tight_fit_bonus;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        let dead = post_residual < next_item_size;
        if dead {
            score += 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Reward bins that can still hold the lookahead item.
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But allow new bins early in the stream to build diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for bins below mean residual (balance waste across bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Reward using bins that are already fragmented (higher residual) to consolidate.
    score -= 0.05 * bin_residual as f64;

    // Penalize extremely small post-residuals that create unusable slivers
    // (less than half of the minimum plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild preference for tight fits.
    // Later (progress ~ 1): strong quadratic penalty on wasted space.
    let poly = norm_pr * norm_pr * (0.5 + 2.5 * progress) + norm_pr * (1.0 - progress) * 0.3;

    let mut score = pr + 40.0 * poly;

    // Reward filling a bin completely (post_residual near 0).
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Smooth bonus proportional to how close post_residual is to zero.
        score -= 15.0 * (1.0 - norm_pr).exp();
    }

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr {
            // Next item won't fit in the leftover; penalize proportionally to mismatch.
            score += 8.0 * ((ni - pr) / cap) * (0.5 + progress);
        } else {
            // Next item fits the leftover: reward this bin.
            score -= 10.0 * (pr - ni) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    // Slight pull toward bins with below-average residual (tighter bins first).
    score += 0.1 * (mean_residual - bin_residual as f64).abs() * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline; only chosen if no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Reward tight fits: small post_residual gets strong bonus
    if post == 0 {
        score -= 1000.0; // perfect fit, ideal
    } else if post <= quarter / 2 {
        score -= 60.0;
    } else if post <= quarter {
        score -= 30.0;
    } else if post <= half {
        score -= 10.0;
    }

    // Penalize dead space that no item can plausibly fill
    // (items >= 10, so residual < 10 is dead space; residual in [1..9] worst)
    if post > 0 && post < 10 {
        score += 80.0;
    }

    // Modulo harmonic classes on post_residual: multiples of 10 are "friendly"
    // since items are 10..80, residuals divisible by common item sizes are reusable
    if post % 10 == 0 && post > 0 {
        score -= 15.0;
    } else if post % 5 == 0 && post > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 200.0;
        } else if next_item_size <= post {
            // next item fits: good, but prefer exact or near-exact
            let slack = post - next_item_size;
            if slack <= quarter / 2 {
                score -= 40.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item does NOT fit here: penalize leaving space it could have used
            let gap = next_item_size - post;
            if gap <= 10 {
                score += 25.0; // near miss is frustrating
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer reusing open bins generally; make empty bin mildly attractive
    // only when post_residual would be very large (item small relative to bin)
    if bin_residual == bin_capacity {
        // new bin: score = post_residual = capacity - item_size, already high.
        // add small penalty to discourage wasteful opening when fits exist
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // but if the item is huge (would leave tiny residual anyway), neutral
        if item_size >= 3 * quarter {
            score -= 15.0;
        }
    }

    // Progress-based tuning: late in stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Mean residual coupling: when open bins are on average quite full,
    // reusing them is more valuable
    if bin_residual < bin_capacity && (mean_residual as u32) < post {
        score -= 8.0;
    }

    // Small tie-break noise via deterministic function of inputs
    score - ((item_size as f64 * 0.01) + (open_bins_count as f64 * 0.001))
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1.0;
    if post > 0.0 && post < min_item * 10.0 {
        score += 40.0 * (1.0 - post / (min_item * 10.0));
    }

    // Reward near-perfect fits.
    if post == 0 {
        score -= 25.0;
    } else if post <= 5 {
        score -= 15.0;
    }

    // Penalize wasteful placements: item much smaller than residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.4 {
        score += 20.0 * (0.4 - fill_ratio);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would NOT fit, mild penalty unless post residual is tiny.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Open-bin pressure: discourage proliferating bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 6.0;

    // New-bin candidate: only attractive when residuals across open bins are
    // poor and the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) / ((total_items as f64).max(1.0)).sqrt();
        let desperation = if mean_residual > 0.0 {
            1.0 - (mean_residual / cap).min(1.0)
        } else { 1.0 };
        score = cap - post - 10.0 * desperation - 5.0 * openness;
        // A new bin should only win if no open bin fits well.
        if fitting_bins_count > 0 && post_residual >= item_size / 2 {
            score += 30.0;
        }
    }

    // Mild stream-progression tiebreak.
    score += (step_index as f64 / total_items.max(1) as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the NEXT item exactly fills the post residual (perfect 2-step chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1000.0;
    }
    // Reward if next item fits into the post residual (good lookahead match).
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * (next_item_size as f64);
        // Extra reward for tight fit (small leftover after next item).
        let after_next = post_residual as f64 - next_item_size as f64;
        score -= (1.0 - after_next / bin_capacity as f64) * 10.0;
    }
    // Penalize if next item does NOT fit: post residual becomes dead space risk.
    else if next_item_size > 0 {
        score += 0.3 * (post_residual as f64);
    }

    // Penalize residuals that are too small for typical future items (dead space).
    if post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins below mean residual are tighter; prefer tight bins.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: make empty bin moderately attractive only when
    // current item is large relative to residual spread, otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        // Slight penalty so existing reasonable fits win; but not huge, so
        // when all fits are terrible the new bin can win.
        score += 5.0;
        // If many open bins already exist and this item is small, prefer reusing them.
        if item_size < 30 && open_bins_count > 2 {
            score += 20.0;
        }
        // If no open bin fits well (post residual would be huge waste), new bin looks better:
        // handled implicitly since open-bin scores rise with bad post_residual.
    }

    // Mild preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * (bin_residual as f64);

    score
}
